  def _images(self, *args, **kw):
    return [x for x in self._client.images(*args, **kw)]
  @property
  def info(self):
    return self._client.info()
  @property
  def total_num_containers(self):
    info = self.info
    return int(info.get('Containers'))
  @property
  def total_num_images(self):
    info = self.info
    return int(info.get('Images'))
  @property
  def total_num_goroutines(self):
    info = self.info
    return int(info.get('NGoroutines'))
  @property
  def memory_limit(self):
    info = self.info
    return info.get('MemoryLimit')
  @property
  def debug(self):
    info = self.info
    return info.get('Debug')
  def running(self, container):
    container_ids = [x.container_id for x in self.containers]
    if isinstance(container, Container):
      return container.container_id in containder_ids
    elif isinstance(container, basestring):
      return container in container_ids
    raise TypeError('expected container id as string or Container object.')
  def start(self, container, *args, **kw):
    if isinstance(container, Container):
      cid = container.container_id
    elif isinstance(container, basestring):
      cid = container
    return self._client.start(cid, *args, **kw)
  def stop(self, container, *args, **kw):
    if isinstance(container, Container):
      cid = container.container_id
    elif isinstance(container, basestring):
      cid = container
    return self._client.stop(cid, *args, **kw)

class linkedlist: 
    def __init__(self, num, next = None):
        self.num = num
        self.next = next
    def len(self): 
        count = 0 
        while self.next != None:
            count += 1
            self = self.next
        return count
    def __eq__(self, other):
        if self is None and other is None:
            return True
        elif self is None or other is None:
            return False
        elif self.num != other.num:
            return False
        else:
            return self.next == other.next
    def recursivelen(self): 
        if self.next == None: 
            return 1
        else: 
            return 1 + self.next.recursivelen() 
    def Lmax(self): 
        if self.next == None:
            return self.num
        else: 
            return max(self.num, self.next.Lmax())
    def Linsert(self, index, insertion): 
        if index == 0:
            new_node = linkedlist(insertion)
            new_node.next = self
            self = new_node
            return self
        elif index == 1:
            new_node = linkedlist(insertion)
            new_node.next = self.next
            self.next = new_node
            return self
        else:
            self.next.Linsert(index - 1, insertion)
    def isTarget(self, target, index):
        if self.num != target and self.next == None:
            return -1
        elif self.num == target:
            return index
        else:
            return self.next.isTarget(target, index + 1)
    def lsearch(self, target): 
        return self.isTarget(target, 0)
    def lmodify(self, target, modification): 
        if self.num == target and self.next == None:
            self.num = modification
        elif self.num == target and self.next != None:
            self.num = modification
        elif self.num != target and self.next != None:
            self.next.lmodify(target, modification)
    def ldelete(self, target): 
        if self.num == target and self.next == None:
            self = None
        elif self.num != target and self.next == None:
            pass
        elif self.next.num == target:
            self.next = self.next.next
        else:
            self.next.ldelete(target)
    def traverse(self, repre = '['):
        if self.next != None:
            repre += str(self.num)
            repre += ', '
            return self.next.traverse(repre)
        elif self.next == None:
            repre += str(self.num)
            repre += ']'
            return repre
    def add_to_end(self, addition):
        pass

