    def location(self) -> dict:
        old_loc = self._execute(Command.GET_ELEMENT_RECT)["value"]
        new_loc = {"x": round(old_loc["x"]), "y": round(old_loc["y"])}
        return new_loc
    @property
    def rect(self) -> dict:
        return self._execute(Command.GET_ELEMENT_RECT)["value"]
    @property
    def aria_role(self) -> str:
        return self._execute(Command.GET_ELEMENT_ARIA_ROLE)["value"]
    @property
    def accessible_name(self) -> str:
        return self._execute(Command.GET_ELEMENT_ARIA_LABEL)["value"]
    @property
    def screenshot_as_base64(self) -> str:
        return self._execute(Command.ELEMENT_SCREENSHOT)["value"]
    @property
    def screenshot_as_png(self) -> bytes:
        return b64decode(self.screenshot_as_base64.encode("ascii"))
    def screenshot(self, filename) -> bool:
        if not filename.lower().endswith(".png"):
            warnings.warn(
                "name used for saved screenshot does not match file " "type. It should end with a `.png` extension",
                UserWarning,
            )
        png = self.screenshot_as_png
        try:
            with open(filename, "wb") as f:
                f.write(png)
        except OSError:
            return False
        finally:
            del png
        return True
    @property
    def parent(self):
        return self._parent
    @property
    def id(self) -> str:
        return self._id
    def __eq__(self, element):
        return hasattr(element, "id") and self._id == element.id
    def __ne__(self, element):
        return not self.__eq__(element)
    def _execute(self, command, params=None):
        if not params:
            params = {}
        params["id"] = self._id
        return self._parent.execute(command, params)
    def find_element(self, by=By.ID, value=None) -> WebElement:
        if by == By.ID:
            by = By.CSS_SELECTOR
            value = '[id="%s"]' % value
        elif by == By.CLASS_NAME:
            by = By.CSS_SELECTOR
            value = ".%s" % value
        elif by == By.NAME:
            by = By.CSS_SELECTOR
            value = '[name="%s"]' % value
        return self._execute(Command.FIND_CHILD_ELEMENT, {"using": by, "value": value})["value"]
    def find_elements(self, by=By.ID, value=None) -> list[WebElement]:
        if by == By.ID:
            by = By.CSS_SELECTOR
            value = f'[id="{value}"]'
        elif by == By.CLASS_NAME:
            by = By.CSS_SELECTOR
            value = f".{value}"
        elif by == By.NAME:
            by = By.CSS_SELECTOR
            value = f'[name="{value}"]'
        return self._execute(Command.FIND_CHILD_ELEMENTS, {"using": by, "value": value})["value"]
    def __hash__(self) -> int:
        return int(md5_hash(self._id.encode("utf-8")).hexdigest(), 16)
    def _upload(self, filename):
        fp = BytesIO()
        zipped = zipfile.ZipFile(fp, "w", zipfile.ZIP_DEFLATED)
        zipped.write(filename, os.path.split(filename)[1])
        zipped.close()
        content = encodebytes(fp.getvalue())
        if not isinstance(content, str):
            content = content.decode("utf-8")
        try:
            return self._execute(Command.UPLOAD_FILE, {"file": content})["value"]
        except WebDriverException as e:
            if "Unrecognized command: POST" in str(e):
                return filename
            if "Command not found: POST " in str(e):
                return filename
            if '{"status":405,"value":["GET","HEAD","DELETE"]}' in str(e):
                return filename
            raise

class Rational(object):
    def __init__(self, numerator, denominator):
        self.numerator = numerator
        self.denominator = denominator
    def __repr__(self):
        return "%d/%d" % (self.numerator, self.denominator)
    def _gcd(self):
        minNum = min(self.numerator, self.denominator)
        maxNum = max(self.numerator, self.denominator)
        smallest_divisors = {i for i in range(1, minNum + 1) if minNum % 1 == 0}
        common_divisors = {i for i in smallest_divisors if maxNum % i == 0}
        return max(common_divisors)
    def reduce(self) -> object:
        gcd = self._gcd()
        self.numerator = self.numerator / gcd
        self.denominator = self.denominator / gcd
        return self

class Rational:
    def __init__(self,n,d=1):
        if type(n) != int:
            raise TypeError("Numerator must be int.")
        if type(d) != int:
            raise TypeError("Denominator must be int.")
        if d == 0:
            raise ZeroDivisionError
        if d < 0:
            d = abs(d)
            n = -n
        self.n = n
        self.d = d
        self.simplify()
    def simplify(self):
        g = abs(gcd(self.n,self.d))
        self.n = self.n//g
        self.d = self.d//g
    def copy(self):
        return Rational(self.n,self.d)
    def __str__(self):
        if self.d == 1:
            return str(self.n)
        return f"{self.n}/{self.d}"
    def _pretty_name(self):
        if self.d == 1:
            return f"${self.n}$"
        else:
            return f"$\dfrac{{{self.n}}}{{{self.d}}}$"
    def __repr__(self):
        if self.d == 1:
            return str(self.n)
        return f"{self.n}/{self.d}"
    def inv(self):
        return Rational(self.d,self.n)
    def __neg__(self):
        return Rational(-self.n,self.d)
    def __add__(self,addend):
        if type(addend) not in [Rational,int]:
            return NotImplemented
        if type(addend) == int:
            addend = Rational(addend)
        n = self.n*addend.d + addend.n*self.d
        d = self.d*addend.d
        return Rational(n,d)
    def __radd__(self,addend):
        if type(addend) == int:
            addend = Rational(addend)
        return self + addend
    def __sub__(self,addend):
        if type(addend) not in [Rational,int]:
            return NotImplemented
        return self + -addend
    def __rsub__(self,addend):
        return addend + -self
    def __mul__(self,multiplier):
        if type(multiplier) not in [Rational,int]:
            return NotImplemented
        if type(multiplier) == int:
            multiplier = Rational(multiplier)
        n = self.n * multiplier.n
        d = self.d * multiplier.d
        return Rational(n,d)
    def __rmul__(self,multiplier):
        if type(multiplier) == int:
            multiplier = Rational(multiplier)
        return self*multiplier
    def __truediv__(self,divisor):
        if type(divisor) not in [Rational,int]:
            return NotImplemented
        if divisor == 0:
            raise ZeroDivisionError
        if type(divisor) == int:
            divisor = Rational(divisor)
        return self*divisor.inv()
    def __rtruediv__(self,dividend):
        if self == 0:
            raise ZeroDivisionError
        if type(dividend) == int:
            dividend = Rational(dividend)
        return self.inv()*dividend
    def __floordiv__(self,divisor):
        if type(divisor) not in [Rational,int]:
            return NotImplemented
        if divisor == 0:
            raise ZeroDivisionError
        if type(divisor) == int:
            divisor = Rational(divisor)
        q = self*divisor.inv()
        v = q.n // q.d
        return v
    def __mod__(self,modulus):
        if modulus == 0:
            raise ZeroDivisionError
        if type(modulus) == int:
            modulus = Rational(modulus)
        if modulus > self:
            return self
        else:
            a = self.copy()
            while a >= modulus:
                a -= modulus
            return a
    def __eq__(self,other):
        if type(other) == int:
            other = Rational(other)
        if self.n == other.n:
            if self.d == other.d:
                return True
        return False
    def __le__(self, other):
        d = self-other
        if d.n >= 0:
            return False
        return True
    def __lt__(self, other):
        d = self-other
        if d.n > 0:
            return False
        return True
    def __ge__(self, other):
        d = self-other
        if d.n >= 0:
            return True
        return False
    def __gt__(self, other):
        d = self-other
        if d.n > 0:
            return True
        return False
    def __pow__(self,pwr):
        if type(pwr) != int:
            raise TypeError(f"pwr must be an integer not {type(pwr)}")
        if pwr < 0:
            return self.inv()**abs(pwr)
        elif pwr == 0:
            return Rational(1)
        elif pwr == 1:
            return self
        else:
            n = self.n**pwr
            d = self.d**pwr
            return Rational(n,d)
    def __hash__(self):
        return hash(f"CustomRational{self}")
    def __float__(self):
        return self.n/self.d
    def __abs__(self):
        return Rational(abs(self.n),self.d)
    def __floor__(self):
        return self.n // self.d
    def __ceil__(self):
        if self.d == 1:
            return self.n
        else:
            return (self.n // self.d)+1
    def _whole_part(self):
        return self.n // self.d
    def _fractional_part(self):
        return Rational(self.n % self.d, self.d)
    def mixed_form(self):
        w = self.whole_part
        f = self.fractional_part
        return w,f
    def _mixed_name(self):
        if self.d == 1:
            return str(self.n)
        else:
            w,f = self.mixed_form()
            return f"${w}\dfrac{{{f.n}}}{{{f.d}}}$"
    def digits(self,n):
        if n == 0:
            return self.whole_part
        N = abs(self.n)
        D = self.d
        sgn = "-" if N != self.n else ""
        digits = []
        for ctr in range(n+1):
            digits.append(N//D)
            N = (N % D)*10
        x1 = str(digits[0])
        x2 = "".join(str(e) for e in digits[1:])
        out = f"{sgn}{x1}.{x2}"
        return out
    def _decimal_expansion(self):
        if self.d == 1:
            return str(self.n)
        N = abs(self.n)
        D = self.d
        sgn = "-" if N != self.n else ""
        digits = []
        rems = []
        while N not in rems:
            rems.append(N)
            digits.append(N//D)
            N = (N % D)*10
        nonrep = first_where(rems,N)
        x1 = str(digits[0])
        x2 = "".join(str(e) for e in digits[1:nonrep])
        x3 = "".join(str(e) for e in digits[nonrep:])
        if x3 == "0":
            x3 = ""
        else:
            x3 = f"({x3})"
        out = f"{sgn}{x1}.{x2}{x3}"
        return out
    pretty_name = property(_pretty_name)
    whole_part = property(_whole_part)
    fractional_part = property(_fractional_part)
    mixed_name = property(_mixed_name)
    decimal_expansion = property(_decimal_expansion)

class BSTNode:
    def __init__(self,element,left,right):
        self.element = element
        self.left = left
        self.right = right
    def __repr__(self,nspaces=0):
        s1 = ''
        s2 = ''
        s3 = ''
        if self.right != None:
            s1 = self.right.__repr__(nspaces + 3)
        s2 = s2 + ' '*nspaces + str(self.element) + '\n'
        if self.left != None:
            s3 = self.left.__repr__(nspaces + 3)
        return s1 + s2 + s3
    def insert(self,e):
        parent = self
        current = None
        found = False
        if parent.element < e:
            current = parent.right
        elif parent.element > e:
            current = parent.left
        else:
            found = True;
        while not found and current:
            parent = current
            if parent.element < e:
                current = parent.right
            elif parent.element > e:
                current = parent.left
            else:
                found = True
        if not found:
            if parent.element < e:
                parent.right = BSTNode(e,None,None)
            else:
                parent.left = BSTNode(e,None,None)
        return not found
    def insertArray(self,a, low=0, high=-1):
        if len(a) == 0:
            return
        if high == -1:
            high = len(a)-1
        mid = (low+high+1)//2
        self.insert(a[mid])
        if mid > low:
            self.insertArray(a,low,mid-1)
        if high > mid:
            self.insertArray(a,mid + 1,high)
    def search(self,e):
        current = self
        found = False
        while not found and current:
            if current.element < e:
                current = current.right
            elif current.element > e:
                current = current.left
            else:
                found = True
        if found:
            return current
        else:
            return None
    def search2(self,e):
        if self.element == e:
            return self
        parent = self.getParent(e)
        if parent == None:
            return None
        if parent.element < e:
            return parent.right
        return parent.left
    def getParent(self,e):
        parent = self
        current = None
        found = False
        if parent.element < e:
            current = parent.right
        elif parent.element > e:
            current = parent.left;
        else:
            return None
        while not found and current:
            if current.element == e:
                found = True
            else:
                parent = current
                if current.element < e:
                    current = current.right
                else:
                    current = current.left
        if found:
            return parent
        else:
            return None
    def delete(self,e):
        parent = self.getParent(e);
        if parent == None:
            return False
        if parent.element < e:
            current = parent.right
            if current.left == None:
                parent.right = parent.right.right
                return True
            else:
                if current.right == None:
                    parent.right = parent.right.left
                    return True
        else:
            current = parent.left
            if current.left == None:
                parent.left = parent.left.right
                return True
            else:
                if current.right == None:
                    parent.left = parent.left.left
                    return True
        if current.right.left == None:
            current.element = current.right.element
            current.right = current.right.right
            return True
        node = current.parentMinRightTree()
        current.element = node.left.element
        node.left = node.left.right
        return True
    def parentMinRightTree(self):
        parent = self.right
        current = parent.left
        while current.left:
            parent = current
            current = current.left
        return parent

class BST:
    def __init__(self,a=None):
        if a:
            self.mid = len(a)//2
            self.root = BSTNode(a[self.mid],None,None)
            self.root.insertArray(a[:self.mid])
            self.root.insertArray(a[self.mid+1:])
        else:
            self.root = None
    def __repr__(self):
        if self.root:
            return str(self.root)
        else:
            return 'null-tree'
    def search(self,e):
        if self.root and e:
            return self.root.search(e)
        else:
            return None
    def max(self): 
        if self.root:
            return self.root.right
        else:
            return None
    def rsearch(self, value, currentNode): 
        if(currentNode == None):
            return False
        return currentNode.element == value or self.rsearch(value, currentNode.left) or self.rsearch(value, currentNode.right)
    def rinsert(self, value, currentNode): 
        if self.root:
            if not self.rsearch(value, self.root): 
                if value < currentNode.element:
                    if currentNode.left != None:
                        self.rinsert(value, currentNode.left)
                    else:
                        currentNode.left = BSTNode(value,None,None)
                if value > currentNode.element:
                    if currentNode.right != None:
                        self.rinsert(value, currentNode.right)
                    else:
                        currentNode.right = BSTNode(value, None, None)
            else:
                return None
        else:
            self.root = BSTNode(value,None,None)
            return True
    def showLevelNumber(self, level, currentNode):
        if currentNode == None:
            return
        elif level == 1:
            print(currentNode)
        elif level > 1:
            self.showLevelNumber(level - 1, currentNode.left)
            self.showLevelNumber(level - 1, currentNode.right)
    def showLevelOrder(self):
        height = self.mid
        for ita in range(1, height):
            print("Current LEVEL IS: ", ita)
            print("------------------------")
            self.showLevelNumber(ita, self.root)
            print("========================")
    def insert(self,e):
        if e:
            if self.root:
                return self.root.insert(e)
            else:
                self.root = BSTNode(e,None,None)
                return True
        else:
            return False
    def delete(self,e):
        if self.root and e:
            if self.root.element == e:
                if self.root.left == None:
                    self.root = self.root.right
                elif self.root.right == None:
                    self.root = self.root.left
                elif self.root.right.left == None:
                    self.root.element = self.root.right.element
                    self.root.right = self.root.right.right
                else:
                    node = self.root.parentMinRightTree();
                    self.root.element = node.left.element
                    node.left = node.left.right
                return True
            else:
                return self.root.delete(e)
        else:
            return False

