class Pair(object):
    def __init__(self, first, second):
        self.first = first
        self.second = second
    def __repr__(self):
        return "Pair({0}, {1})".format(repr(self.first), repr(self.second))
    def __str__(self):
        s = "(" + str(self.first)
        second = self.second
        while isinstance(second, Pair):
            s += " " + str(second.first)
            second = second.second
        if second is not nil:
            s += " . " + str(second)
        return s + ")"
    def __len__(self):
        n, second = 1, self.second
        while isinstance(second, Pair):
            n += 1
            second = second.second
        if second is not nil:
            raise TypeError("length attempted on improper list")
        return n
    def __getitem__(self, k):
        if k < 0:
            raise IndexError("negative index into list")
        y = self
        for _ in range(k):
            if y.second is nil:
                raise IndexError("list index out of bounds")
            elif not isinstance(y.second, Pair):
                raise TypeError("ill-formed list")
            y = y.second
        return y.first
    def map(self, fn):
        mapped = fn(self.first)
        if self.second is nil or isinstance(self.second, Pair):
            return Pair(mapped, self.second.map(fn))
        else:
            raise TypeError("ill-formed list")

class nil(object):
    def __repr__(self):
        return "nil"
    def __str__(self):
        return "()"
    def __len__(self):
        return 0
    def __getitem__(self, k):
        if k < 0:
            raise IndexError("negative index into list")
        raise IndexError("list index out of bounds")
    def map(self, fn):
        return self

class PipelineStage(Stage):
    def __init__(self, *args, name=None, **kwargs):
        super().__init__(*args, **kwargs)
        self.name = name
        self.cmd_changed = False
        self.tracked_vars = {}
    def __eq__(self, other):
        return super().__eq__(other) and self.name == other.name
    def __hash__(self):
        return hash((self.path_in_repo, self.name))
    @property
    def addressing(self):
        from dvc.dvcfile import PIPELINE_FILE
        if self.path and self.relpath == PIPELINE_FILE:
            return self.name
        return f"{super().addressing}:{self.name}"
    def reload(self):
        return self.dvcfile.stages[self.name]
    def _status_stage(self, ret):
        if self.cmd_changed:
            ret.append("changed command")
    def changed_stage(self):
        if self.cmd_changed:
            logger.debug(self._changed_stage_entry())
        return self.cmd_changed
    def _changed_stage_entry(self):
        return f"'cmd' of {self} has changed."
    def merge(self, ancestor, other):
        raise NotImplementedError

