    def add_vertex(self, v):
        if v not in self._adjsets:
            self._adjsets[v] = set()
    def add_edge(self, e):
        for v in e:
            self.add_vertex(v)
        self._adjsets[e[0]].add(e[1])
    def edges(self):
        edges = set()
        for key, values in self._adjsets.iteritems():
            for v in values:
                edges.add((key, v))
        return set(sorted(edges))
    def draw(self, filename, attr = {}):
        display.write_dot_desc((self._adjsets.keys(), self.edges()), filename, attr)
    def num_edges(self):
        m = 0
        for v in self._adjsets:
            m += len(self._adjsets[v])
        return m
    def num_vertices(self):
        return len(self._adjsets)
    def adj_to(self, v):
        return self._adjsets[v]

class User(PaginatedAPIMixin, UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(64), index=True, unique=True)
    email = db.Column(db.String(120), index=True, unique=True)
    password_hash = db.Column(db.String(128))
    about_me = db.Column(db.String(140))
    last_seen = db.Column(db.DateTime, default=datetime.utcnow)
    posts = db.relationship('Post', backref="author", lazy="dynamic")
    messages_sent = db.relationship('Message', foreign_keys="Message.sender_id", backref="author", lazy="dynamic")
    messages_received = db.relationship('Message', foreign_keys="Message.recipient_id", backref="recipient", lazy="dynamic")
    last_message_read_time = db.Column(db.DateTime) 
    notifications = db.relationship("Notification", backref="user", lazy="dynamic")
    tasks = db.relationship('Task', backref='user', lazy="dynamic")
    token = db.Column(db.String(32), index=True, unique=True)
    token_expiration = db.Column(db.DateTime)
    followed = db.relationship('User', 
                                secondary=followers, 
                                primaryjoin=(followers.c.follower_id==id), 
                                secondaryjoin=(followers.c.followed_id==id), 
                                backref=db.backref('followers', lazy='dynamic'), 
                                lazy='dynamic')
    def __repr__(self):
        return "<User {}>".format(self.username)
    def set_password(self, password):
        self.password_hash = generate_password_hash(password)
    def check_password(self, password):
        return check_password_hash(self.password_hash, password)
    def avatar(self, size):
        digest = md5(self.email.lower().encode('utf-8')).hexdigest()
        return 'https://www.gravatar.com/avatar/{}?d=identicon&s={}'.format(digest, size)
    def follow(self, user):
        if not self.is_following(user):
            self.followed.append(user)
    def unfollow(self, user):
        if self.is_following(user):
            self.followed.remove(user)
    def is_following(self, user):
        return self.followed.filter(followers.c.followed_id == user.id).count() > 0
    def followed_posts(self):
        followed = Post.query.join(
            followers, (followers.c.followed_id == Post.user_id)
        ).filter(
            followers.c.follower_id == self.id
        )
        own = Post.query.filter(Post.user_id==self.id)
        return followed.union(own).order_by(Post.timestamp.desc())
    def get_reset_password(self, expires_in=600):
        return jwt.encode(
            payload={'reset_password': self.id, 'exp': time()+expires_in}, 
            key=current_app.config['SECRET_KEY'], algorithm='HS256').decode('utf-8')
    def new_messages(self):
        last_read_time = self.last_message_read_time or datetime(1900, 1, 1)
        return Message.query.filter_by(recipient=self).filter(Message.timestamp > last_read_time).count()
    def add_notification(self, name, data):
        self.notifications.filter_by(name=name).delete()
        n = Notification(name=name, payload_json=json.dumps(data), user=self)
        db.session.add(n)
        return n
    def launch_task(self, name, description, *args, **kwargs):
        rq_job = current_app.task_queue.enqueue('flaskTutorial.tasks.'+name, self.id, *args, **kwargs)
        task = Task(id=rq_job.get_id(), name=name, description=description, user=self)
        db.session.add(task)
        return task
    def get_tasks_in_progress(self):
        return Task.query.filter_by(user=self, complete=False).all()
    def get_task_in_progress(self, name):
        return Task.query.filter_by(user=self, name=name, complete=False).first()
    def to_dict(self, include_email=False):
        data = {
            'id': self.id, 
            'username': self.username,
            'last_seen': self.last_seen.isoformat()+'Z',
            'about_me': self.about_me,
            'post_count': self.posts.count(),
            'follower_count': self.followers.count(),
            'followed_count': self.followed.count(), 
            '_links': {
                'self': url_for('api.get_user', id=self.id),
                'followers': url_for('api.get_followers', id=self.id),
                'followed': url_for('api.get_followed', id=self.id),
                'avatar': self.avatar(128)
            }
        }
        if include_email:
            data['email'] = self.email
        return data
    def from_dict(self, data, new_user=False):
        for field in ['username', 'email', 'about_me']:
            if field in data:
                setattr(self, field, data[field])
        if new_user and 'password' in data:
            self.set_password(data['password'])
    def get_token(self, expires_in=3600):
        now = datetime.utcnow()
        if self.token and self.token_expiration > now + timedelta(seconds=60):
            return self.token
        self.token = base64.b64encode(os.urandom(24)).decode('utf-8')
        self.token_expiration = now + timedelta(seconds=expires_in)
        db.session.add(self)
        return self.token
    def revoke_token(self):
        self.token_expiration = datetime.utcnow() - timedelta(seconds=1)
    @staticmethod
    def check_token(token):
        user = User.query.filter_by(token=token).first()
        if user is None or user.token_expiration < datetime.utcnow():
            return None 
        return user
    @staticmethod
    def verify_reset_password_token(token):
        try:
            id = jwt.decode(token, current_app.config['SECRET_KEY'], algorithms=['HS256'])['reset_password']
        except:
            return
        return User.query.get(id)

