class Type():
    STVAR, TVAR, TCONST = range(3)
    def __init__(self, arg):
        if not isinstance(arg, Type):
            if type_parser is not None:
                T = type_parser(arg)
            else:
                raise TypeException('Type: parser not found.')
        else:
            T = arg
        self.__dict__.update(T.__dict__)
    def is_stvar(self):
        return self.ty == Type.STVAR
    def is_tvar(self):
        return self.ty == Type.TVAR
    def is_tconst(self):
        return self.ty == Type.TCONST
    def is_fun(self):
        return self.is_tconst() and self.name == "fun"
    def domain_type(self):
        assert self.is_fun(), "domain_type"
        return self.args[0]
    def range_type(self):
        assert self.is_fun(), "range_type"
        return self.args[1]
    def strip_type(self):
        if self.is_fun():
            domains, range = self.range_type().strip_type()
            return ([self.domain_type()] + domains, range)
        else:
            return ([], self)
    def print_basic(self):
        if self.is_stvar():
            return "?'" + self.name
        elif self.is_tvar():
            return "'" + self.name
        elif self.is_tconst():
            if len(self.args) == 0:
                return self.name
            elif len(self.args) == 1:
                if self.args[0].is_fun():
                    return "(%s) %s" % (self.args[0], self.name)
                else:
                    return "%s %s" % (self.args[0], self.name)
            elif self.is_fun():
                if self.args[0].is_fun():
                    return "(%s) => %s" % (self.args[0], self.args[1])
                else:
                    return "%s => %s" % (self.args[0], self.args[1])
            else:
                return "(%s) %s" % (", ".join(str(t) for t in self.args), self.name)
        else:
            raise TypeError
    def __str__(self):
        if type_printer is None:
            return self.print_basic()
        else:
            return type_printer(self)
    def __repr__(self):
        if self.is_stvar():
            return "STVar(%s)" % self.name
        if self.is_tvar():
            return "TVar(%s)" % self.name
        elif self.is_tconst():
            return "TConst(%s, %s)" % (self.name, list(self.args))
        else:
            raise TypeError
    def __hash__(self):
        if not hasattr(self, "_hash_val"):
            if self.is_stvar():
                self._hash_val = hash(("STVAR", self.name))
            if self.is_tvar():
                self._hash_val = hash(("TVAR", self.name))
            elif self.is_tconst():
                self._hash_val = hash(("TCONST", self.name, tuple(hash(arg) for arg in self.args)))
        return self._hash_val
    def __eq__(self, other):
        if other is None:
            return False
        assert isinstance(other, Type), "cannot compare Type with %s" % str(type(other))
        if id(self) == id(other):
            return True
        if self.ty != other.ty:
            return False
        elif self.is_stvar() or self.is_tvar():
            return self.name == other.name
        elif self.is_tconst():
            return self.name == other.name and self.args == other.args
        else:
            raise TypeError
    def __le__(self, other):
        if self.ty != other.ty:
            return self.ty <= other.ty
        elif self.is_stvar() or self.is_tvar():
            return self.name <= other.name
        elif self.is_tconst():
            return (self.name, self.args) <= (other.name, other.args)
        else:
            raise TypeError
    def __lt__(self, other):
        if self.ty != other.ty:
            return self.ty < other.ty
        elif self.is_stvar() or self.is_tvar():
            return self.name < other.name
        elif self.is_tconst():
            return (self.name, self.args) < (other.name, other.args)
        else:
            raise TypeError
    def size(self):
        if self.is_stvar() or self.is_tvar():
            return 1
        elif self.is_tconst():
            return 1 + sum(T.size() for T in self.args)
        else:
            raise TypeError
    def subst(self, tyinst=None, **kwargs):
        if tyinst is None:
            tyinst = TyInst(**kwargs)
        if self.is_stvar():
            if self.name in tyinst:
                return tyinst[self.name]
            else:
                return self
        elif self.is_tvar():
            return self
        elif self.is_tconst():
            return TConst(self.name, *(T.subst(tyinst) for T in self.args))
        else:
            raise TypeError
    def match_incr(self, T, tyinst):
        if self.is_stvar():
            if self.name in tyinst:
                if T != tyinst[self.name]:
                    raise TypeMatchException('Unable to match %s with %s' % (T, tyinst[self.name]))
            else:
                tyinst[self.name] = T
        elif self.is_tvar():
            if self != T:
                raise TypeMatchException('Unable to match %s with %s' % (self, T))
        elif self.is_tconst():
            if (not T.is_tconst()) or T.name != self.name:
                raise TypeMatchException('Unable to match %s with %s' % (self, T))
            else:
                for arg, argT in zip(self.args, T.args):
                    arg.match_incr(argT, tyinst)
        else:
            raise TypeError
    def match(self, T):
        tyinst = TyInst()
        self.match_incr(T, tyinst)
        return tyinst
    def get_stvars(self):
        def collect(T):
            if T.is_stvar():
                return [T]
            elif T.is_tvar():
                return []
            else:
                return sum([collect(arg) for arg in T.args], [])
        return term_ord.sorted_typs(collect(self))
    def get_tvars(self):
        def collect(T):
            if T.is_stvar():
                return []
            elif T.is_tvar():
                return [T]
            else:
                return sum([collect(arg) for arg in T.args], [])
        return term_ord.sorted_typs(collect(self))
    def get_tsubs(self):
        def collect(T):
            if T.is_stvar() or T.is_tvar():
                return [T]
            else:
                return sum([collect(arg) for arg in T.args], [T])
        return term_ord.sorted_typs(collect(self))
    def convert_stvar(self):
        if self.is_stvar():
            raise TypeException("convert_stvar")
        elif self.is_tvar():
            return STVar(self.name)
        elif self.is_tconst():
            return TConst(self.name, *(arg.convert_stvar() for arg in self.args))
        else:
            raise TypeError
    def is_numeral_type(self):
        return self in (NatType, IntType, RealType)

class Fragment(object):
    def __init__(self, length, fid):
        self.length = length
        self.counter = 0
        self.resname_list = []
        self.coords_ca = numpy.zeros((length, 3), "d")
        self.fid = fid
    def get_resname_list(self):
        return self.resname_list
    def get_id(self):
        return self.fid
    def get_coords(self):
        return self.coords_ca
    def add_residue(self, resname, ca_coord):
        if self.counter >= self.length:
            raise PDBException("Fragment boundary exceeded.")
        self.resname_list.append(resname)
        self.coords_ca[self.counter] = ca_coord
        self.counter = self.counter + 1
    def __len__(self):
        return self.length
    def __sub__(self, other):
        sup = SVDSuperimposer()
        sup.set(self.coords_ca, other.coords_ca)
        sup.run()
        return sup.get_rms()
    def __repr__(self):
        return "<Fragment length=%i id=%i>" % (self.length, self.fid)

