class LinkedList():
    def __init__(self):
        self.head = None
        self.tail = None
    def __repr__(self):
        return f"<LinkedList Head: {self.head.data} Tail: {self.tail.data}>"
    def append(self, data):
        new_node = Node(data)
        if self.head is None:
            self.head = new_node
        if self.tail is not None:
            self.tail.next = new_node
        self.tail = new_node
    def remove(self, data):
        if self.head is not None and self.head.data == data:
            self.head = self.head.next
            if self.head is None:
                self.tail = None
            return
        current = self.head
        while current.next is not None:
            if current.next.data == data:
                current.next = current.next.next
                if current.next == None:
                    self.tail = current
                return
            else:
                current = current.next
    def display(self):
        current = self.head
        while current is not None:
            print(current.data)
            current = current.next

class TupleErrorList(list):
    ul_format = '<ul class="{1}" ng-show="{0}.{2}" ng-cloak>{3}</ul>'
    li_format = '<li ng-show="{0}.{1}" class="{2}">{3}</li>'
    li_format_bind = '<li ng-show="{0}.{1}" class="{2}" ng-bind="{0}.{3}"></li>'
    def __str__(self):
        return self.as_ul()
    def __repr__(self):
        return repr([force_text(e[5]) for e in self])
    def as_ul(self):
        if not self:
            return ''
        error_lists = {'$pristine': [], '$dirty': []}
        for e in self:
            li_format = e[5] == '$message' and self.li_format_bind or self.li_format
            err_tuple = (e[0], e[3], e[4], force_text(e[5]))
            error_lists[e[2]].append(format_html(li_format, *err_tuple))
        first = self[0]
        return mark_safe(''.join([format_html(self.ul_format, first[0], first[1], prop,
                    mark_safe(''.join(list_items))) for prop, list_items in error_lists.items()]))
    def as_text(self):
        if not self:
            return ''
        return '\n'.join(['* %s' % force_text(e[5]) for e in self if bool(e[5])])

class ConnectN:
    def __init__(self):
        self._grid = [[] for _ in range(7)]
        self._rows = 6
        self._connect = 4
        self._player = 0
        self._game_fin = 0
        print('\nWelcome!')
        self._name_1 = input('Player 1\'s name: ')
        self._name_2 = input('Player 2\'s name: ')
        self._player_names = {0: self._name_1, 1: self._name_2}
        print(self)
        _column = input(f'{self._player_names[0]}, choose a column (1-{len(self._grid)}) to drop your first disc: ')
        while not (_column in {str(x) for x in range(1, len(self._grid)+1)}):
            _column = input(f'You must choose a number 1-{len(self._grid)}: ')
        self.game(int(_column))
    def __repr__(self):
        def row(i):
            return '| ' + ' | '.join([self._grid[j][i] if len(self._grid[j]) > i else ' '
                                      for j in range(len(self._grid))]) + ' |'
        game_grid = '\n' + '\n'.join([row(i) for i in range(self._rows-1, -1, -1)]) + '\n'
        return game_grid.translate(game_grid.maketrans('01', 'XO'))
    def game(self, n):
        print(self.play(n - 1))
        if not self._game_fin:
            n = input('Choose a column: ')
            while not (n in {str(x) for x in range(1, len(self._grid)+1)}):
                n = input(f'You must choose a number 1-{len(self._grid)}: ')
            return self.game(int(n))
    def play(self, col):
        if len(self._grid[col]) < self._rows:
            self._grid[col].extend(str(self._player))
            self._player = (self._player + 1) % 2
            print(self)
        else:
            return 'Column full!'
        if (str(int((not self._player))) * self._connect in ''.join(self._grid[col])) \
                or (str(int((not self._player))) * self._connect in
                    ''.join([self._grid[i][len(self._grid[col]) - 1] if not (len(self._grid[i]) < len(self._grid[col]))
                             else' ' for i in range(len(self._grid))])) \
                or (str(int((not self._player))) * self._connect in
                    ''.join([self._grid[col-(len(self._grid[col])-1)+i][i]
                             if 0 <= col-(len(self._grid[col])-1)+i < len(self._grid)
                             and (len(self._grid[col-(len(self._grid[col])-1)+i]) >= i+1)
                             else ' 'for i in range(len(self._grid))])) \
                or (str(int((not self._player))) * self._connect in
                    ''.join([self._grid[i][col+(len(self._grid[col])-1)-i]
                             if 0 <= col+(len(self._grid[col])-1)-i < self._rows
                             and (len(self._grid[i]) >= col+(len(self._grid[col])-1)-i+1)
                             else ' ' for i in range(len(self._grid))])):
            self._game_fin = 1
            return f'{self._player_names[int((not self._player))]} wins!\n'
        if all([int(len(self._grid[i]) / self._rows) for i in range(len(self._grid))]):
            self._game_fin = 1
            return 'Game ends in draw'
        return f'{self._player_names[self._player]}\'s turn'

class Neighbourhood(Resource):
    force = None
    _resource_cache = {}
    _boundary = None
    _crimes = None
    fields = ['contact_details', 'name', 'links', 'description', 'url_force',
              'population', 'centre', 'locations']
    class Officer(SimpleResource):
        fields = ['neighbourhood', 'name', 'rank', 'contact_details', 'bio']
        def __str__(self):
            return '<Neighbourhood.Officer> %s' % self.name
    class Event(SimpleResource):
        fields = ['neighbourhood', 'title', 'type', 'description',
                  'contact_details', 'start_date', 'address']
        def __str__(self):
            return '<Neighbourhood.Event> %s' % self.title
        def _hydrate_start_date(self, data):
            return datetime.strptime(data, '%Y-%m-%dT%H:%M:%S')
    class Priority(SimpleResource):
        fields = ['neighbourhood', 'issue', 'action', 'issue_date',
                  'action_date']
        def __str__(self):
            return '<Neighbourhood.Priority> %s' % self.issue
        def _hydrate(self, data):
            for field in ['issue-date', 'action-date']:
                data[field.replace('-', '_')] = data[field]
            return super(Neighbourhood.Priority, self)._hydrate(data)
        def __hydrate_date(self, data):
            return datetime.strptime(data, '%Y-%m-%dT%H:%M:%S')
        def _hydrate_issue_date(self, data):
            return self.__hydrate_date(data) if data else None
        _hydrate_action_date = _hydrate_issue_date
    def __init__(self, *args, **kwargs):
        super(Neighbourhood, self).__init__(*args, **kwargs)
        self._assert_id_not_neighbourhoods()
    def __str__(self):
        return '<Neighbourhood> %s' % self.id
    def __eq__(self, other):
        return isinstance(other, Neighbourhood) and self.id == other.id
    def __hash__(self):
        return hash(self.id)
    def _assert_id_not_neighbourhoods(self):
        if self.id == 'neighbourhoods':
            raise NeighbourhoodsNeighbourhoodException()
    def _get_api_method(self):
        self._assert_id_not_neighbourhoods()
        return '%s/%s' % (self.force.id, self.id)
    def _hydrate_population(self, data):
        return int(data) if data is not None else None
    def _get_resource(self, cls, method):
        if method in self._resource_cache:
            return self._resource_cache[method]
        objs = []
        method = '%s/%s/%s' % (self.force.id, self.id, method)
        for d in self.api.service.request('GET', method):
            d.update({
                'neighbourhood': self,
            })
            objs.append(cls(self.api, data=d))
        self._resource_cache[method] = objs
        return objs
    def _get_boundary(self):
        method = '%s/%s/boundary' % (self.force.id, self.id)
        points = self.api.service.request('GET', method)
