    def priorities(self):
        return sorted(self._get_resource(self.Priority, 'priorities'),
                      key=lambda x: x.issue_date, reverse=True)
    @property
    def boundary(self):
        if self._boundary is None:
            self._boundary = self._get_boundary()
        return self._boundary
    @property
    def crimes(self):
        if self._crimes is None:
            self._crimes = self._get_crimes()
        return self._crimes

class Override(object):
    def __init__(self, *requirements):
        self._requirements = set(requirements)
    def add(self, requirement, *requirements):
        self._requirements.update((requirement,) + requirements)
    def remove(self, requirement, *requirements):
        self._requirements.difference_update((requirement,) + requirements)
    def is_overridden(self, requirement):
        return requirement in self._requirements
    def __contains__(self, other):
        return self.is_overridden(other)
    @_isinstance
    def __add__(self, other):
        requirements = self._requirements | other._requirements
        return Override(*requirements)
    @_isinstance
    def __iadd__(self, other):
        if len(other._requirements) > 0:
            self.add(*other._requirements)
        return self
    @_isinstance
    def __sub__(self, other):
        requirements = self._requirements - other._requirements
        return Override(*requirements)
    @_isinstance
    def __isub__(self, other):
        if len(other._requirements) > 0:
            self.remove(*other._requirements)
        return self
    @_isinstance
    def __eq__(self, other):
        return self._requirements == other._requirements
    @_isinstance
    def __ne__(self, other):
        return not self == other
    def __len__(self):
        return len(self._requirements)
    def __bool__(self):
        return len(self) != 0
    __nonzero__ = __bool__
    def __repr__(self):
        return "Override({!r})".format(self._requirements)

class ValidationError(Exception):
    def __init__(self, message, code=None, params=None):
        super(ValidationError, self).__init__(message, code, params)
        if isinstance(message, ValidationError):
            if hasattr(message, 'error_dict'):
                message = message.error_dict
            elif not hasattr(message, 'message'):
                message = message.error_list
            else:
                message, code, params = tuple([
                    getattr(message, term)
                    for term in ['message', 'code', 'params']])
        if isinstance(message, dict):
            self.error_dict = {}
            for field, messages in message.items():
                if not isinstance(messages, ValidationError):
                    messages = ValidationError(messages)
                self.error_dict[field] = messages.error_list
        elif isinstance(message, list):
            self.error_list = []
            for message in message:
                if not isinstance(message, ValidationError):
                    message = ValidationError(message)
                if hasattr(message, 'error_dict'):
                    self.error_list.extend(
                        sum(message.error_dict.values(), []))
                else:
                    self.error_list.extend(message.error_list)
        else:
            self.message = message
            self.code = code
            self.params = params
            self.error_list = [self]
    @property
    def message_dict(self):
        getattr(self, 'error_dict')
        return dict(self)
    @property
    def messages(self):
        if hasattr(self, 'error_dict'):
            return sum(dict(self).values(), [])
        return list(self)
    def update_error_dict(self, error_dict):
        if hasattr(self, 'error_dict'):
            for field, error_list in self.error_dict.items():
                error_dict.setdefault(field, []).extend(error_list)
        else:
            error_dict.setdefault(
                '__all__', []).extend(self.error_list)
        return error_dict
    def __iter__(self):
        if hasattr(self, 'error_dict'):
            for field, errors in self.error_dict.items():
                yield field, list(ValidationError(errors))
        else:
            for error in self.error_list:
                message = error.message
                if error.params:
                    message %= error.params
                yield force_text(message)
    def __str__(self):
        if hasattr(self, 'error_dict'):
            return pprint.pformat(self.error_dict)
        return repr(list(self))
    def __repr__(self):
        return 'ValidationError(%s)' % self

class Location(object):
    def __init__(self, country_ = None, state_ = None, county_ = None, city_ = None):
        self._country = country_
        self._state = state_
        self._county = county_
        self._city = city_
    @property
    def country(self):
        return self._country
    @property
    def state(self):
        return self._state
    @property
    def county(self):
        return self._county
    @property
    def city(self):
        return self._city
    def locationAsStr(self):
        retList = []
        if self._country is not None:
            retList.append(self._country)
        retList.append('/')
        if self._state is not None:
            retList.append(self._state)
        retList.append('/')
        if self._county is not None:
            retList.append(self._county)
        return ''.join(retList)
    @country.setter
    def country(self, country_):
        return Location(country_, self._state, self._county, self._city)
    @state.setter
    def state(self, state_):
        return Location(self._country, state_, self._county, self._city)
    @county.setter
    def county(self, county_):
        return Location(self._country, self._state, county_, self._city)
    @city.setter
    def city(self, city_):
        return Location(self._country, self._state, self._county, city_)
    def __eq__(self, other_):
        if isinstance(other_, Location):
            return self._country == other_._country and \
                   self._state == other_._state and \
                   self._county == other_._county and \
                   self._city == other_._city
        else:
            return False
    def __hash__(self):
        return hash(str(self))
    def __str__(self):
        retVal = ['[']
        if self._country is not None:
            retVal.append('country = {0}'.format(self._country))
        if self._state is not None:
            retVal.append('state = {0}'.format(self._state))
        if self._county is not None:
            retVal.append('county = {0}'.format(self._county))
        if self._city is not None:
            retVal.append('city = {0}'.format(self._city))
        retVal.append(']')
        return ' ,'.join(retVal)

class System(EventMixin, LoggerMixin):
    def __init__(self, engine=None, **_):
        super().__init__()
        self.engine = engine  
        self._dispatch = None  
        if self.engine:
            self._dispatch = self.engine.dispatch
    def __fire_event__(self, event: Event, dispatch: Callable[[Event], None]) -> None:
        if self.engine.running:
            super(System, self).__fire_event__(event, dispatch)
    def __repr__(self):
        return type(self).__name__
    def __enter__(self):
        pass
    def __exit__(self, exc_type, exc_val, exc_tb):
        pass

