        return _as_meg_type_evoked(self, ch_type=ch_type, mode=mode)
    @fill_doc
    def detrend(self, order=1, picks=None):
        picks = _picks_to_idx(self.info, picks)
        self.data[picks] = detrend(self.data[picks], order, axis=-1)
        return self
