            [
                data.bbox.x1,
                data.bbox.y1,
                data.bbox.x2,
                data.bbox.y2,
                data.bbox.x3,
                data.bbox.y3,
                data.bbox.x4,
                data.bbox.y4,
                data.bbox.angle,
            ],
            label=data.label,
        )
