class Lb(object):
    _version = 11
    def __init__(self, host, username, password, versioncheck=True, use_session=True):
        self._host         = host
        self._username     = username
        self._versioncheck = versioncheck
        self._use_session  = use_session
        if use_session:
            self._transport = bigsuds.BIGIP(
                host, username, password
            ).with_session_id()
        else:
            self._transport = bigsuds.BIGIP(
                host, username, password
            )
        version = self._transport.System.SystemInfo.get_version()
        if versioncheck and not 'BIG-IP_v11' in version:
            raise UnsupportedF5Version('This class only supports BIG-IP v11', version)
        self._active_folder       = self.active_folder
        self._recursive_query     = self.recursive_query
        self._transaction         = self.transaction
        self._transaction_timeout = self.transaction_timeout
    def __repr__(self):
        return "f5.Lb('%s')" % (self._host)
    def _call(self, call, *args, **kwargs):
        return deepgetattr(self._transport, call)(*args, **kwargs)
    @property
    def host(self):
        return self._host
    @property
    def username(self):
        return self._username
    @property
    def versioncheck(self):
        return self._versioncheck
    @property
    def use_session(self):
        return self._use_session
    @property
    def active_folder(self):
        self._active_folder = self._get_active_folder()
        return self._active_folder
    @active_folder.setter
    def active_folder(self, value):
        self._set_active_folder(value)
        self._active_folder =  value
    @property
    def version(self):
        return self._call('System.SystemInfo.get_version')
    @property
    def system_information(self):
        return self._call('System.SystemInfo.get_system_information')
    @property
    def product_information(self):
        return self._call('System.SystemInfo.get_product_information')
    @property
    def failover_state(self):
        self._failover_state = self._call('System.Failover.get_failover_state')[15:]
        return self._failover_state
    @property
    def recursive_query(self):
        recursive_query_state = self._get_recursive_query_state()
        if recursive_query_state == 'STATE_ENABLED':
            self._recursive_query =  True
        elif recursive_query_state == 'STATE_DISABLED':
            self._recursive_query =  False
        else:
            raise RuntimeError('Unknown status %s received for recursive_query_state') % (recursive_query_state)
        return self._recursive_query
    @recursive_query.setter
    def recursive_query(self, value):
        if value == True:
            recursive_query_state = 'STATE_ENABLED'
        elif value == False:
            recursive_query_state = 'STATE_DISABLED'
        else:
            raise ValueError('recursive_query must be one of True/False, not %s' % (value))
        self._set_recursive_query_state(recursive_query_state)
        self._recursive_query = value
    @property
    def transaction(self):
        self._transaction = self._active_transaction()
        return self._transaction
    @transaction.setter
    def transaction(self,value):
        if value == True:
            self._ensure_transaction()
            self._transaction = True
        elif value == False:
            self._ensure_no_transaction()
            self._transaction = False
    @property
    def transaction_timeout(self):
        self._transaction_timeout = self._get_transaction_timeout()
        return self._transaction_timeout
    @transaction_timeout.setter
    def transaction_timeout(self, value):
        self._set_transaction_timeout(value)
        self._transaction_timeout = value
    def _ensure_transaction(self):
        wsdl = self._transport.System.Session
        try:
            wsdl.start_transaction()
        except ServerError as e:
            if 'Only one transaction can be open at any time' in str(e):
                pass
            else:
                raise
    def _ensure_no_transaction(self):
        wsdl = self._transport.System.Session
        try:
            wsdl.rollback_transaction()
        except ServerError as e:
            if 'No transaction is open to roll back.' in str(e):
                pass
            else:
                raise
        except:
            raise
    def _submit_transaction(self):
        wsdl = self._transport.System.Session
        wsdl.submit_transaction()
    def _rollback_transaction(self):
        wsdl = self._transport.System.Session
        wsdl.rollback_transaction()
    def _get_transaction_timeout(self):
        wsdl = self._transport.System.Session
        return wsdl.get_transaction_timeout()
    def _set_transaction_timeout(self, value):
        wsdl = self._transport.System.Session
        wsdl.set_transaction_timeout(value)
    def _active_transaction(self):
        wsdl = self._transport.System.Session
        try:
            wsdl.start_transaction()
        except ServerError as e:
            if 'Only one transaction can be open at any time' in str(e):
                return True
            else:
                raise
        wsdl.rollback_transaction()
        return False
    def _get_active_folder(self):
        wsdl = self._transport.System.Session
        return wsdl.get_active_folder()
    def _set_active_folder(self, folder):
        wsdl = self._transport.System.Session
        return wsdl.set_active_folder(folder)
    def _get_recursive_query_state(self):
        wsdl = self._transport.System.Session
        return wsdl.get_recursive_query_state()
    def _set_recursive_query_state(self, state):
        wsdl = self._transport.System.Session
        wsdl.set_recursive_query_state(state)
    def submit_transaction(self):
        self._submit_transaction()
    def pool_get(self, name):
        try:
            pool = f5.Pool.factory.create([name], self)[0]
            pool.refresh()
        except ServerError as e:
            if 'was not found.' in str(e):
                raise PoolNotFound(name)
            else:
                raise
        return pool
    @recursivereader
    def pools_get(self, pattern=None, minimal=False):
        return f5.Pool._get(self, pattern, minimal)
    def pm_get(self, node, port, pool):
        try:
            pm = f5.PoolMember.factory.create((node, port, pool), self)[0]
            pm.refresh()
        except ServerError as e:
            if 'was not found.' in str(e):
                raise PoolMemberNotFound((node, port, pool))
            else:
                raise
        return pm
    @recursivereader
    def pms_get(self, pools=None, pattern=None, minimal=False):
        return f5.PoolMember._get(self, pools, pattern, minimal)
    def node_get(self, name):
        try:
            node = f5.Node.factory.create([name], self)[0]
            node.refresh()
        except ServerError as e:
            if 'was not found.' in str(e):
                raise NodeNotFound(name)
            else:
                raise
        return node
    @recursivereader
    def nodes_get(self, pattern=None, minimal=False, partition='/'):
        return f5.NodeList(self, pattern, partition, minimal)
    def rule_get(self, name):
        try:
            rule = f5.Rule.factory.create([name], self)[0]
            rule.refresh()
        except ServerError as e:
            if 'was not found.' in str(e):
                raise RuleNotFound(name)
            else:
                raise
        return rule
    @recursivereader
    def rules_get(self, pattern=None, minimal=False):
        return f5.Rule._get(self, pattern, minimal)
    def vs_get(self, name):
        try:
            vs = f5.VirtualServer.factory.create([name], self)[0]
            vs.refresh()
        except ServerError as e:
            if 'was not found.' in str(e):
                raise VirtualServerNotFound(name)
            else:
                raise
        return vs
    @recursivereader
    def vss_get(self, pattern=None, minimal=False):
        return f5.VirtualServer._get(self, pattern, minimal)
    @recursivereader
    def pools_get_vs(self, pools=None, minimal=False):
        if pools is None:
            pools = f5.Pool._get_list(self)
        else:
            if isinstance(pools[0], f5.Pool):
                pools = [pool.name for pool in pools]
        result = {pool: [] for pool in pools}
        vss = f5.VirtualServer._get(self, minimal=minimal)
        if minimal is True:
            vss = f5.VirtualServer._refresh_default_pool(self, vss)
        for pool in pools:
            for vs in vss:
                print(vs._default_pool)
                if pool == vs._default_pool.name:
                    result[pool].append(vs)
        return result

class ZONA:
    def __init__(self, model):
        self.model = model
        self.caero_to_name_map = {}
        self.panlsts = {}
        self.mkaeroz = {}
        self.trimvar = {}
        self.trimlnk = {}
        self.pafoil = {}
    @classmethod
    def _init_from_self(cls, model):
        return cls(model)
    def clear(self):
        self.panlsts = {}
        self.mkaeroz = {}
        self.trimvar = {}
        self.trimlnk = {}
        self.pafoil = {}
    def object_attributes(self, mode:str='public', keys_to_skip: Optional[List[str]]=None,
                          filter_properties: bool=False):
        if keys_to_skip is None:
            keys_to_skip = []
        my_keys_to_skip = [
            'log', 'model',
        ]
        return object_attributes(self, mode=mode, keys_to_skip=keys_to_skip+my_keys_to_skip,
                                 filter_properties=filter_properties)
    def object_methods(self, mode='public', keys_to_skip=None):
        if keys_to_skip is None:
            keys_to_skip = []
        my_keys_to_skip = []  
        my_keys_to_skip = ['log',]
        return object_methods(self, mode=mode, keys_to_skip=keys_to_skip+my_keys_to_skip)
    def verify(self, xref):
        if self.model.nastran_format != 'zona':
            return
        for panlst in self.panlsts.values():
            panlst._verify(xref)
        for mkaeroz in self.mkaeroz.values():
            mkaeroz._verify(xref)
        for trimvar in self.trimvar.values():
            trimvar._verify(xref)
        for trimlnk in self.trimlnk.values():
            trimlnk._verify(xref)
        for pafoil in self.pafoil.values():
            pafoil._verify(xref)
    def validate(self):
        if self.model.nastran_format != 'zona':
            return
        for panlst in self.panlsts.values():
            panlst.validate()
        for mkaeroz in self.mkaeroz.values():
            mkaeroz.validate()
        for trimvar in self.trimvar.values():
            trimvar.validate()
        for trimlnk in self.trimlnk.values():
            trimlnk.validate()
        for pafoil in self.pafoil.values():
            pafoil.validate()
    def PAFOIL(self, pid, msg=''):
        try:
            return self.pafoil[pid]
        except KeyError:
            raise KeyError('pid=%s not found%s.  Allowed pafoils=%s'
                           % (pid, msg, np.unique(list(self.pafoil.keys()))))
    def update_for_zona(self):
        card_parser = self.model._card_parser
        card_parser['TRIM'] = (TRIM_ZONA, self.model._add_trim_object)
        card_parser['CAERO7'] = (CAERO7, self.model._add_caero_object)
        card_parser['AEROZ'] = (AEROZ, self.model._add_aeros_object)
        card_parser['AESURFZ'] = (AESURFZ, self._add_aesurfz_object)
        card_parser['FLUTTER'] = (FLUTTER_ZONA, self.model._add_flutter_object)
        card_parser['SPLINE1'] = (SPLINE1_ZONA, self.model._add_spline_object)
        card_parser['SPLINE2'] = (SPLINE2_ZONA, self.model._add_spline_object)
        card_parser['SPLINE3'] = (SPLINE3_ZONA, self.model._add_spline_object)
        card_parser['PANLST1'] = (PANLST1, self._add_panlst_object)
        card_parser['PANLST3'] = (PANLST3, self._add_panlst_object)
        card_parser['PAFOIL7'] = (PAFOIL7, self._add_pafoil_object)
        card_parser['MKAEROZ'] = (MKAEROZ, self._add_mkaeroz_object)
        card_parser['SEGMESH'] = (SEGMESH, self.model._add_paero_object)
        card_parser['BODY7'] = (BODY7, self.model._add_caero_object)
        card_parser['ACOORD'] = (ACOORD, self.model._add_coord_object)
        card_parser['TRIMVAR'] = (TRIMVAR, self._add_trimvar_object)
        card_parser['TRIMLNK'] = (TRIMLNK, self._add_trimlnk_object)
        cards = [
            'CAERO7', 'AEROZ', 'AESURFZ', 'PANLST1', 'PANLST3', 'PAFOIL7',
            'SEGMESH', 'BODY7', 'ACOORD', 'MKAEROZ',
            'TRIMVAR', 'TRIMLNK', 'FLUTTER']
        self.model.cards_to_read.update(set(cards))
    def _add_panlst_object(self, panlst):
        assert panlst.eid not in self.panlsts
        assert panlst.eid > 0
        key = panlst.eid
        self.panlsts[key] = panlst
        self.model._type_to_id_map[panlst.type].append(key)
    def _add_pafoil_object(self, pafoil):
        assert pafoil.pid not in self.pafoil
        assert pafoil.pid > 0
        key = pafoil.pid
        self.pafoil[key] = pafoil
        self.model._type_to_id_map[pafoil.type].append(key)
    def _add_aesurfz_object(self, aesurf):
        key = aesurf.aesid
        model = self.model
        assert key not in model.aesurf, '\naesurf=\n%s old=\n%s' % (
            aesurf, model.aesurf[key])
        model.aesurf[key] = aesurf
        model._type_to_id_map[aesurf.type].append(key)
    def _add_mkaeroz_object(self, mkaeroz):
        assert mkaeroz.sid not in self.mkaeroz
        assert mkaeroz.sid > 0
        key = mkaeroz.sid
        self.mkaeroz[key] = mkaeroz
        self.model._type_to_id_map[mkaeroz.type].append(key)
    def _add_trimvar_object(self, trimvar):
        assert trimvar.var_id not in self.trimvar
        assert trimvar.var_id > 0
        key = trimvar.var_id
        self.trimvar[key] = trimvar
        self.model._type_to_id_map[trimvar.type].append(key)
    def _add_trimlnk_object(self, trimlnk):
        assert trimlnk.link_id not in self.trimlnk
        assert trimlnk.link_id > 0
        key = trimlnk.link_id
        self.trimlnk[key] = trimlnk
        self.model._type_to_id_map[trimlnk.type].append(key)
    def cross_reference(self):
        if self.model.nastran_format != 'zona':
            return
        for mkaeroz in self.mkaeroz.values():
            mkaeroz.cross_reference(self.model)
        for trimvar in self.trimvar.values():
            trimvar.cross_reference(self.model)
        for trimlnk in self.trimlnk.values():
            trimlnk.cross_reference(self.model)
        for unused_id, pafoil in self.pafoil.items():
            pafoil.cross_reference(self.model)
        for caero in self.model.caeros.values():
            self.caero_to_name_map[caero.label] = caero.eid
    def safe_cross_reference(self):
        self.cross_reference()
    def write_bdf(self, bdf_file, size=8, is_double=False):
        for unused_id, panlst in self.panlsts.items():
            bdf_file.write(panlst.write_card(size=size, is_double=is_double))
        for unused_id, mkaeroz in self.mkaeroz.items():
            bdf_file.write(mkaeroz.write_card(size=size, is_double=is_double))
        for unused_id, trimvar in self.trimvar.items():
            bdf_file.write(trimvar.write_card(size=size, is_double=is_double))
        for unused_id, trimlnk in self.trimlnk.items():
            bdf_file.write(trimlnk.write_card(size=size, is_double=is_double))
        for unused_id, pafoil in self.pafoil.items():
            bdf_file.write(pafoil.write_card(size=size, is_double=is_double))
    def convert_to_nastran(self, save=True):
        if self.model.nastran_format != 'zona':
            caeros = {}
            caero2s = []
            make_paero1 = False
            return caeros, caero2s, make_paero1
        caeros, caero2s, make_paero1 = self._convert_caeros()
        splines = self._convert_splines()
        aesurf, aelists = self._convert_aesurf_aelist()
        trims = self._convert_trim()
        aeros, aero = self.model.aeros.convert_to_zona(self.model)
        aelinks = self._convert_trimlnk()
        if save:
            self.clear()
            self.model.splines = splines
            self.model.aesurf = aesurf
            self.model.aelists = aelists
            self.model.aelinks = aelinks
            self.model.trims = trims
            self.model.aeros = aeros
            self.model.aero = aero
        return caeros, caero2s, make_paero1
    def _convert_caeros(self):
        model = self.model
        caeros = {}
        caero2s = []
        make_paero1 = False
        for caero_id, caero in sorted(model.caeros.items()):
            if caero.type == 'CAERO7':
                caero_new = caero.convert_to_nastran()
                make_paero1 = True
            elif caero.type == 'BODY7':
                caero2s.append(caero)
                continue
            else:
                raise NotImplementedError(caero)
            caeros[caero_id] = caero_new
        self._add_caero2s(caero2s, add=False)
        return caeros, caero2s, make_paero1
    def _add_caero2s(self, caero2s, add=False):
        model = self.model
        caero_body_ids = []
        for caero2 in caero2s:
            caero_id = caero2.eid
            out = caero2.convert_to_nastran(model)
            caero_new, paero2, aefact_xs, aefact_width, aefact_theta1, aefact_theta2 = out
            caero_body_ids.append(caero_id)
            if add:
                model._add_aefact_object(aefact_xs)
                model._add_aefact_object(aefact_width)
                model._add_aefact_object(aefact_theta1)
                model._add_aefact_object(aefact_theta2)
                model._add_paero_object(paero2)
                model._add_caero_object(caero_new)
        return
    def _convert_splines(self):
        splines = {}
        for unused_spline_id, spline in self.model.splines.items():
            if spline.type == 'SPLINE1_ZONA':
                splines_new = spline.convert_to_nastran(self.model)
            elif spline.type == 'SPLINE3_ZONA':
                splines_new = spline.convert_to_nastran(self.model)
            else:
                raise NotImplementedError(spline)
            for spline_new in splines_new:
                splines[spline.eid] = spline_new
        return splines
    def _convert_aesurf_aelist(self):
        model = self.model
        aelist_id = max(model.aelists) + 1 if model.aelists else 1
        aesurf_id = aelist_id
        aesurf = {}
        aelists = {}
        for unused_aesurf_name, aesurfi in sorted(model.aesurf.items()):
            aelist, aesurfi2 = aesurfi.convert_to_nastran(model, aesurf_id, aelist_id)
            aelists[aelist.sid] = aelist
            aesurf[aesurfi2.aesid] = aesurfi2
            aesurf_id += 1
            aelist_id += 1
        return aesurf, aelists
    def _convert_trim(self):
        trims = {}
        model = self.model
        for trim_id, trim in sorted(model.trims.items()):
            trim_new = trim.convert_to_nastran(model)
            trims[trim_id] = trim_new
        return trims
    def _convert_trimlnk(self):
        model = self.model
        assert isinstance(model.aelinks, dict), model.aelinks
        aelinks = {}
        for trim_id, trimlnk in sorted(self.trimlnk.items()):
            aelink = trimlnk.convert_to_nastran(model)
            aelinks[trim_id] = aelink
        return aelinks
    def __repr__(self):
        msg = '<ZONA>; nPANLSTs=%s nmkaeroz=%s' % (
            len(self.panlsts), len(self.mkaeroz),
        )
        return msg

