class Resize(object):
    def __init__(self,
                 img_scale=None,
                 multiscale_mode='range',
                 ratio_range=None,
                 keep_ratio=True):
        if img_scale is None:
            self.img_scale = None
        else:
            if isinstance(img_scale, list):
                self.img_scale = img_scale
            else:
                self.img_scale = [img_scale]
            assert mmcv.is_list_of(self.img_scale, tuple)
        if ratio_range is not None:
            assert len(self.img_scale) == 1
        else:
            assert multiscale_mode in ['value', 'range']
        self.multiscale_mode = multiscale_mode
        self.ratio_range = ratio_range
        self.keep_ratio = keep_ratio
    @staticmethod
    def random_select(img_scales):
        assert mmcv.is_list_of(img_scales, tuple)
        scale_idx = np.random.randint(len(img_scales))
        img_scale = img_scales[scale_idx]
        return img_scale, scale_idx
    @staticmethod
    def random_sample(img_scales):
        assert mmcv.is_list_of(img_scales, tuple) and len(img_scales) == 2
        img_scale_long = [max(s) for s in img_scales]
        img_scale_short = [min(s) for s in img_scales]
        long_edge = np.random.randint(
            min(img_scale_long),
            max(img_scale_long) + 1)
        short_edge = np.random.randint(
            min(img_scale_short),
            max(img_scale_short) + 1)
        img_scale = (long_edge, short_edge)
        return img_scale, None
    @staticmethod
    def random_sample_ratio(img_scale, ratio_range):
        assert isinstance(img_scale, tuple) and len(img_scale) == 2
        min_ratio, max_ratio = ratio_range
        assert min_ratio <= max_ratio
        ratio = np.random.random_sample() * (max_ratio - min_ratio) + min_ratio
        scale = int(img_scale[0] * ratio), int(img_scale[1] * ratio)
        return scale, None
    def _random_scale(self, results):
        if self.ratio_range is not None:
            scale, scale_idx = self.random_sample_ratio(
                self.img_scale[0], self.ratio_range)
        elif len(self.img_scale) == 1:
            scale, scale_idx = self.img_scale[0], 0
        elif self.multiscale_mode == 'range':
            scale, scale_idx = self.random_sample(self.img_scale)
        elif self.multiscale_mode == 'value':
            scale, scale_idx = self.random_select(self.img_scale)
        else:
            raise NotImplementedError
        results['scale'] = scale
        results['scale_idx'] = scale_idx
    def _resize_img(self, results):
        if self.keep_ratio:
            img, scale_factor = mmcv.imrescale(
                results['img'], results['scale'], return_scale=True)
        else:
            img, w_scale, h_scale = mmcv.imresize(
                results['img'], results['scale'], return_scale=True)
            scale_factor = np.array([w_scale, h_scale, w_scale, h_scale],
                                    dtype=np.float32)
        results['img'] = img
        results['img_shape'] = img.shape
        results['pad_shape'] = img.shape  
        results['scale_factor'] = scale_factor
        results['keep_ratio'] = self.keep_ratio
    def _resize_bboxes(self, results):
        img_shape = results['img_shape']
        for key in results.get('bbox_fields', []):
            bboxes = results[key] * results['scale_factor']
            bboxes[:, 0::2] = np.clip(bboxes[:, 0::2], 0, img_shape[1] - 1)
            bboxes[:, 1::2] = np.clip(bboxes[:, 1::2], 0, img_shape[0] - 1)
            results[key] = bboxes
    def _resize_masks(self, results):
        for key in results.get('mask_fields', []):
            if results[key] is None:
                continue
            if self.keep_ratio:
                masks = [
                    mmcv.imrescale(
                        mask, results['scale_factor'], interpolation='nearest')
                    for mask in results[key]
                ]
            else:
                mask_size = (results['img_shape'][1], results['img_shape'][0])
                masks = [
                    mmcv.imresize(mask, mask_size, interpolation='nearest')
                    for mask in results[key]
                ]
            results[key] = masks
    def __call__(self, results):
        if 'scale' not in results:
            self._random_scale(results)
        self._resize_img(results)
        self._resize_bboxes(results)
        self._resize_masks(results)
        return results
    def __repr__(self):
        repr_str = self.__class__.__name__
        repr_str += ('(img_scale={}, multiscale_mode={}, ratio_range={}, '
                     'keep_ratio={})').format(self.img_scale,
                                              self.multiscale_mode,
                                              self.ratio_range,
                                              self.keep_ratio)
        return repr_str

class RandomFlip(object):
    def __init__(self, flip_ratio=None):
        self.flip_ratio = flip_ratio
        if flip_ratio is not None:
            assert flip_ratio >= 0 and flip_ratio <= 1
    def bbox_flip(self, bboxes, img_shape):
        assert bboxes.shape[-1] % 4 == 0
        w = img_shape[1]
        flipped = bboxes.copy()
        flipped[..., 0::4] = w - bboxes[..., 2::4] - 1
        flipped[..., 2::4] = w - bboxes[..., 0::4] - 1
        return flipped
    def __call__(self, results):
        if 'flip' not in results:
            flip = True if np.random.rand() < self.flip_ratio else False
            results['flip'] = flip
        if results['flip']:
            results['img'] = mmcv.imflip(results['img'])
            for key in results.get('bbox_fields', []):
                results[key] = self.bbox_flip(results[key],
                                              results['img_shape'])
            for key in results.get('mask_fields', []):
                results[key] = [mask[:, ::-1] for mask in results[key]]
        return results
    def __repr__(self):
        return self.__class__.__name__ + '(flip_ratio={})'.format(
            self.flip_ratio)

class SegResizeFlipPadRescale(object):
    def __init__(self, scale_factor=1):
        self.scale_factor = scale_factor
    def __call__(self, results):
        if results['keep_ratio']:
            gt_seg = mmcv.imrescale(
                results['gt_semantic_seg'],
                results['scale'],
                interpolation='nearest')
        else:
            gt_seg = mmcv.imresize(
                results['gt_semantic_seg'],
                results['scale'],
                interpolation='nearest')
        if results['flip']:
            gt_seg = mmcv.imflip(gt_seg)
        if gt_seg.shape != results['pad_shape']:
            gt_seg = mmcv.impad(gt_seg, results['pad_shape'][:2])
        if self.scale_factor != 1:
            gt_seg = mmcv.imrescale(
                gt_seg, self.scale_factor, interpolation='nearest')
        results['gt_semantic_seg'] = gt_seg
        return results
    def __repr__(self):
        return self.__class__.__name__ + '(scale_factor={})'.format(
            self.scale_factor)

class Albu(object):
    def __init__(self,
                 transforms,
                 bbox_params=None,
                 keymap=None,
                 update_pad_shape=False,
                 skip_img_without_anno=False):
        self.transforms = transforms
        self.filter_lost_elements = False
        self.update_pad_shape = update_pad_shape
        self.skip_img_without_anno = skip_img_without_anno
        if (isinstance(bbox_params, dict) and 'label_fields' in bbox_params
                and 'filter_lost_elements' in bbox_params):
            self.filter_lost_elements = True
            self.origin_label_fields = bbox_params['label_fields']
            bbox_params['label_fields'] = ['idx_mapper']
            del bbox_params['filter_lost_elements']
        self.bbox_params = (
            self.albu_builder(bbox_params) if bbox_params else None)
        self.aug = Compose([self.albu_builder(t) for t in self.transforms],
                           bbox_params=self.bbox_params)
        if not keymap:
            self.keymap_to_albu = {
                'img': 'image',
                'gt_masks': 'masks',
                'gt_bboxes': 'bboxes'
            }
        else:
            self.keymap_to_albu = keymap
        self.keymap_back = {v: k for k, v in self.keymap_to_albu.items()}
    def albu_builder(self, cfg):
        assert isinstance(cfg, dict) and "type" in cfg
        args = cfg.copy()
        obj_type = args.pop("type")
        if mmcv.is_str(obj_type):
            obj_cls = getattr(albumentations, obj_type)
        elif inspect.isclass(obj_type):
            obj_cls = obj_type
        else:
            raise TypeError(
                'type must be a str or valid type, but got {}'.format(
                    type(obj_type)))
        if 'transforms' in args:
            args['transforms'] = [
                self.albu_builder(transform)
                for transform in args['transforms']
            ]
        return obj_cls(**args)
    @staticmethod
    def mapper(d, keymap):
        updated_dict = {}
        for k, v in zip(d.keys(), d.values()):
            new_k = keymap.get(k, k)
            updated_dict[new_k] = d[k]
        return updated_dict
    def __call__(self, results):
        results = self.mapper(results, self.keymap_to_albu)
        if 'bboxes' in results:
            if isinstance(results['bboxes'], np.ndarray):
                results['bboxes'] = [x for x in results['bboxes']]
            if self.filter_lost_elements:
                results['idx_mapper'] = np.arange(len(results['bboxes']))
        results = self.aug(**results)
        if 'bboxes' in results:
            if isinstance(results['bboxes'], list):
                results['bboxes'] = np.array(
                    results['bboxes'], dtype=np.float32)
            if self.filter_lost_elements:
                results['idx_mapper'] = np.arange(len(results['bboxes']))
                for label in self.origin_label_fields:
                    results[label] = np.array(
                        [results[label][i] for i in results['idx_mapper']])
                if 'masks' in results:
                    results['masks'] = [
                        results['masks'][i] for i in results['idx_mapper']
                    ]
                if (not len(results['idx_mapper'])
                        and self.skip_img_without_anno):
                    return None
        if 'gt_labels' in results:
            if isinstance(results['gt_labels'], list):
                results['gt_labels'] = np.array(results['gt_labels'])
        results = self.mapper(results, self.keymap_back)
        if self.update_pad_shape:
            results['pad_shape'] = results['img'].shape
        return results
    def __repr__(self):
        repr_str = self.__class__.__name__
        repr_str += '(transformations={})'.format(self.transformations)
        return repr_str

class ArrayEnv:
    def __init__(self, data, emulate_swap = False):
        self.start_data = list(data)
        self.emulate_swap = emulate_swap
        self.reset()
    def swap(self, i0, i1):
        if self.emulate_swap: 
            self.stack.push(i0)
            self.stack.push(i1)
            self.stack.pop(i0)
            self.stack.pop(i1)
        else:
            self.instructions.append((0, (i0, i1)))
            self.data[i0], self.data[i1] = self.data[i1], self.data[i0]
    def less_than(self, i0, i1):
        self.instructions.append((1, (i0, i1)))
        x,y = self.data[i0], self.data[i1]
        return x is not None and y is not None and x < y
    def stack_push(self, i):
        self.instructions.append((2, (i,)))
        if self.data[i] is None: return
        self.stack.append(self.data[i])
        self.data[i] = None
    def stack_pop(self, i):
        self.instructions.append((3, (i,)))
        if not self.stack or self.data[i] is not None: return
        self.data[i] = self.stack.pop()
    def instr_by_index(self, i):
        return [self.swap, self.less_than, self.stack_push, self.stack_pop][i]
    def instr_name(self, i):
        return self.instr_by_index(i).__name__
    def run_instr(self, instruction):
        t, args = instruction
        return self.instr_by_index(t)(*args)
    def reset(self):
        self.data = list(self.start_data)
        self.instructions = []
        self.stack = []
    def is_sorted(self):
        return (np.diff(self.data) >= 0).all()
    def __len__(self):
        return len(self.data)
    def __str__(self):
        return str(self.data)
    def __repr__(self):
        return "ArrayEnv({})".format(repr(self.data))

class Entity:
    name: str
    value_type: ValueType
    join_key: str
    description: str
    tags: Dict[str, str]
    owner: str
    created_timestamp: Optional[datetime]
    last_updated_timestamp: Optional[datetime]
    join_keys: List[str]
    @log_exceptions
    def __init__(
        self,
        *args,
        name: Optional[str] = None,
        value_type: ValueType = ValueType.UNKNOWN,
        description: str = "",
        join_key: Optional[str] = None,
        tags: Optional[Dict[str, str]] = None,
        owner: str = "",
        join_keys: Optional[List[str]] = None,
    ):
        if len(args) == 1:
            warnings.warn(
                (
                    "Entity name should be specified as a keyword argument instead of a positional arg."
                    "Feast 0.23+ will not support positional arguments to construct Entities"
                ),
                DeprecationWarning,
            )
        if len(args) > 1:
            raise ValueError(
                "All arguments to construct an entity should be specified as keyword arguments only"
            )
        self.name = args[0] if len(args) > 0 else name
        if not self.name:
            raise ValueError("Name needs to be specified")
        self.value_type = value_type
        if join_key:
            warnings.warn(
                (
                    "The `join_key` parameter is being deprecated in favor of the `join_keys` parameter. "
                    "Please switch from using `join_key` to `join_keys`. Feast 0.23 and onwards will not "
                    "support the `join_key` parameter."
                ),
                DeprecationWarning,
            )
        self.join_keys = join_keys or []
        if join_keys and len(join_keys) > 1:
            raise ValueError(
                "An entity may only have single join key. "
                "Multiple join keys will be supported in the future."
            )
        if join_keys and len(join_keys) == 1:
            self.join_key = join_keys[0]
        else:
            self.join_key = join_key if join_key else self.name
        self.description = description
        self.tags = tags if tags is not None else {}
        self.owner = owner
        self.created_timestamp = None
        self.last_updated_timestamp = None
    def __hash__(self) -> int:
        return hash((self.name, self.join_key))
    def __eq__(self, other):
        if not isinstance(other, Entity):
            raise TypeError("Comparisons should only involve Entity class objects.")
        if (
            self.name != other.name
            or self.value_type != other.value_type
            or self.join_key != other.join_key
            or self.description != other.description
            or self.tags != other.tags
            or self.owner != other.owner
        ):
            return False
        return True
    def __str__(self):
        return str(MessageToJson(self.to_proto()))
    def is_valid(self):
        if not self.name:
            raise ValueError("The entity does not have a name.")
        if not self.value_type:
            raise ValueError(f"The entity {self.name} does not have a type.")
    @classmethod
    def from_proto(cls, entity_proto: EntityProto):
        entity = cls(
            name=entity_proto.spec.name,
            value_type=ValueType(entity_proto.spec.value_type),
            join_keys=[entity_proto.spec.join_key],
            description=entity_proto.spec.description,
            tags=entity_proto.spec.tags,
            owner=entity_proto.spec.owner,
        )
        if entity_proto.meta.HasField("created_timestamp"):
            entity.created_timestamp = entity_proto.meta.created_timestamp.ToDatetime()
        if entity_proto.meta.HasField("last_updated_timestamp"):
            entity.last_updated_timestamp = (
                entity_proto.meta.last_updated_timestamp.ToDatetime()
            )
        return entity
    def to_proto(self) -> EntityProto:
        meta = EntityMetaProto()
        if self.created_timestamp:
            meta.created_timestamp.FromDatetime(self.created_timestamp)
        if self.last_updated_timestamp:
            meta.last_updated_timestamp.FromDatetime(self.last_updated_timestamp)
        spec = EntitySpecProto(
            name=self.name,
            value_type=self.value_type.value,
            join_key=self.join_key,
            description=self.description,
            tags=self.tags,
            owner=self.owner,
        )
        return EntityProto(spec=spec, meta=meta)

