class AStarState(Node):
    def __init__(self, index=None, x=None, y=None):
        super(AStarState, self).__init__(index=index, x=x, y=y)
        self.is_start = None
        self.is_goal = None
        self.state = index
        self.arc_cost = 1
        self.g = 0
        self.h = 0
        self.f = 0
        self.walkable = True
        self.full_repr_mode = True
    def __lt__(self, other):
        if self.f == other.f:
            return self.h < other.h
        return self.f < other.f
    def __gt__(self, other):
        if self.f == other.f:
            return self.h > other.h
        return self.f > other.f
    def __repr__(self):
        if self.full_repr_mode:
            return 'A*Node(%d, %d, F: %d, G: %d, H: %d)' % (self.x, self.y, self.f, self.g, self.h)
        else:
            return 'A*Node(%d (%d, %d))' % (self.index, self.x, self.y)

class State(Abstract):
    __slots__ = ('label', 'actions',)
    def __init__(self, label=None, actions=()):
        self.label = label
        self.actions = list(actions)
    def add(self, *actions):
        self.actions.extend(actions)
    def opcodes(self, debug=False):
        ops = Opcodes()
        if self.label:
            ops << LABEL(self.label)
            if debug:
                ops << Debug('FSM> State: {0}'.format(self.label))
        for action in self.actions:
            ops << action.opcodes(debug)
        return ops
    def __repr__(self):
        actions = [repr(action).replace('\n', '\n  ') for action in self.actions]
        return 'State({0!r}, [\n  {1}\n])'.format(self.label, ',\n  '.join(actions))

class If(Abstract):
    def __init__(self, varname, op, test, true, false=None):
        assert op in ('in', 'not in') or not isinstance(test, STRING_TYPE) or len(test) == 1, \
            'operator {} does not support a string of length {} ({})' \
            .format(op, len(test), test)
        if op == '==' and isinstance(test, STRING_TYPE):
            op = 'in'
        self.op = op
        self.varname = varname
        if isinstance(test, int):
            test = chr(test)
        self.test = test
        if isinstance(true, Abstract):
            true = [true]
        elif isinstance(true, STRING_TYPE):
            true = [Goto(true)]
        self.true = true
        if isinstance(false, Abstract):
            false = [false]
        elif isinstance(false, STRING_TYPE):
            false = [Goto(false)]
        elif false is None:
            false = []
        self.false = false
    def opcodes(self, debug=False):
        ops = Opcodes()
        else_lbl = 'else_{}'.format(id(self))
        endif_lbl = 'endif_{}'.format(id(self))
        ops << LOAD_FAST(self.varname)
        ops << LOAD_CONST(self.test)
        ops << COMPARE_OP(self.op)
        if self.true and isinstance(self.true[0], Goto):
            ops << POP_JUMP_IF_TRUE(self.true[0].label)
        else:
            ops << POP_JUMP_IF_FALSE(else_lbl)
            for action in self.true:
                ops << action.opcodes(debug)
            ops << JUMP_ABSOLUTE(endif_lbl)
        ops << LABEL(else_lbl)
        for action in self.false:
            ops << action.opcodes(debug)
        ops << LABEL(endif_lbl)
        return ops
    def __repr__(self):
        true = repr(self.true)
        false = repr(self.false)
        return 'If({0!r}, {1!r}, {2!r}, {3}, {4})'.format(
            self.varname, self.op, self.test, true, false)

class Debug(Abstract):
    def __init__(self, format, *args):
        self.format = format
        self.args = args
    def opcodes(self, debug=False):
        ops = Opcodes()
        ops << LOAD_CONST(self.format + '\n')
        ops << LOAD_ATTR('format')
        for arg in self.args:
            if isinstance(arg, STRING_TYPE) and arg.startswith('$'):
                ops << LOAD_FAST(arg[1:])
            else:
                ops << LOAD_CONST(arg)
        ops << CALL_FUNCTION(len(self.args))
        ops << Opcode('PRINT_ITEM')
        return ops
    def __repr__(self):
        return 'Debug({0!r}, *{1!r})'.format(self.format, self.args)

class Goto(Abstract):
    __slots__ = ('label',)
    def __init__(self, label):
        self.label = str(label)
    def opcodes(self, debug=False):
        ops = Opcodes()
        if debug:
            ops << Debug('FSM> Goto: {}', self.label).opcodes()
        ops << JUMP_ABSOLUTE(self.label)
        return ops
    def __repr__(self):
        return 'Goto({0!r})'.format(self.label)

class SpectaclesException(Exception):
    exit_code = 100
    def __init__(self, name: str, title: str, detail: str):
        self.type: str = "/errors/" + name
        self.title = title
        self.detail = detail
    def __repr__(self) -> str:
        return self.title
    def __str__(self) -> str:
        return self.title + " " + self.detail

class S3Store(Store):
    def __init__(
        self,
        index: Store,
        bucket: str,
        s3_profile: Union[str, dict] = None,
        compress: bool = False,
        endpoint_url: str = None,
        sub_dir: str = None,
        s3_workers: int = 1,
        key: str = "fs_id",
        store_hash: bool = True,
        searchable_fields: Optional[List[str]] = None,
        **kwargs,
    ):
        if boto3 is None:
            raise RuntimeError("boto3 and botocore are required for S3Store")
        self.index = index
        self.bucket = bucket
        self.s3_profile = s3_profile
        self.compress = compress
        self.endpoint_url = endpoint_url
        self.sub_dir = sub_dir.strip("/") + "/" if sub_dir else ""
        self.s3 = None  
        self.s3_bucket = None  
        self.s3_workers = s3_workers
        self.searchable_fields = searchable_fields if searchable_fields else []
        self.store_hash = store_hash
        assert isinstance(
            index.key, str
        ), "Since we are using the key as a file name in S3, they key must be a string"
        if key != index.key:
            warnings.warn(
                f'The desired S3Store key "{key}" does not match the index key "{index.key},"'
                "the index key will be used",
                UserWarning,
            )
        kwargs["key"] = str(index.key)
        self._thread_local = threading.local()
        super(S3Store, self).__init__(**kwargs)
    @property
    def name(self) -> str:
        return f"s3://{self.bucket}"
    def connect(self, *args, **kwargs):  
        session = self._get_session()
        resource = session.resource("s3", endpoint_url=self.endpoint_url)
        if not self.s3:
            self.s3 = resource
            try:
                self.s3.meta.client.head_bucket(Bucket=self.bucket)
            except ClientError:
                raise RuntimeError("Bucket not present on AWS: {}".format(self.bucket))
            self.s3_bucket = resource.Bucket(self.bucket)
        self.index.connect(*args, **kwargs)
    def close(self):
        self.index.close()
        self.s3 = None
        self.s3_bucket = None
    @property  
    @deprecated(message="This will be removed in the future")
    def collection(self):
        return self.index
    def count(self, criteria: Optional[Dict] = None) -> int:
        return self.index.count(criteria)
    def query(
        self,
        criteria: Optional[Dict] = None,
        properties: Union[Dict, List, None] = None,
        sort: Optional[Dict[str, Union[Sort, int]]] = None,
        skip: int = 0,
        limit: int = 0,
    ) -> Iterator[Dict]:
        prop_keys = set()
        if isinstance(properties, dict):
            prop_keys = set(properties.keys())
        elif isinstance(properties, list):
            prop_keys = set(properties)
        for doc in self.index.query(
            criteria=criteria, sort=sort, limit=limit, skip=skip
        ):
            if properties is not None and prop_keys.issubset(set(doc.keys())):
                yield {p: doc[p] for p in properties if p in doc}
            else:
                try:
                    data = (
                        self.s3_bucket.Object(self.sub_dir + doc[self.key])
                        .get()["Body"]
                        .read()
                    )
                except botocore.exceptions.ClientError as e:
                    error_code = int(e.response["Error"]["Code"])
                    if error_code == 404:
                        self.logger.error(
                            "Could not find S3 object {}".format(doc[self.key])
                        )
                        break
                    else:
                        raise e
                if doc.get("compression", "") == "zlib":
                    data = zlib.decompress(data)
                unpacked_data = msgpack.unpackb(data, raw=False)
                if self.last_updated_field in doc:
                    unpacked_data[self.last_updated_field] = doc[
                        self.last_updated_field
                    ]
                yield unpacked_data
    def distinct(
        self, field: str, criteria: Optional[Dict] = None, all_exist: bool = False
    ) -> List:
        return self.index.distinct(field, criteria=criteria)
    def groupby(
        self,
        keys: Union[List[str], str],
        criteria: Optional[Dict] = None,
        properties: Union[Dict, List, None] = None,
        sort: Optional[Dict[str, Union[Sort, int]]] = None,
        skip: int = 0,
        limit: int = 0,
    ) -> Iterator[Tuple[Dict, List[Dict]]]:
        return self.index.groupby(
            keys=keys,
            criteria=criteria,
            properties=properties,
            sort=sort,
            skip=skip,
            limit=limit,
        )
    def ensure_index(self, key: str, unique: bool = False) -> bool:
        return self.index.ensure_index(key, unique=unique)
    def update(
        self,
        docs: Union[List[Dict], Dict],
        key: Union[List, str, None] = None,
        additional_metadata: Union[str, List[str], None] = None,
    ):
        if not isinstance(docs, list):
            docs = [docs]
        if isinstance(key, str):
            key = [key]
        elif not key:
            key = [self.key]
        if additional_metadata is None:
            additional_metadata = []
        elif isinstance(additional_metadata, str):
            additional_metadata = [additional_metadata]
        else:
            additional_metadata = list(additional_metadata)
        with ThreadPoolExecutor(max_workers=self.s3_workers) as pool:
            fs = {
                pool.submit(
                    self.write_doc_to_s3,
                    doc=itr_doc,
                    search_keys=key + additional_metadata + self.searchable_fields,
                )
                for itr_doc in docs
            }
            fs, _ = wait(fs)
            search_docs = [sdoc.result() for sdoc in fs]
        self.index.update(search_docs, key=self.key)
    def _get_session(self):
        if not hasattr(self._thread_local, "s3_bucket"):
            if isinstance(self.s3_profile, dict):
                return Session(**self.s3_profile)
            else:
                return Session(profile_name=self.s3_profile)
    def _get_bucket(self):
        if threading.current_thread().name == "MainThread":
            return self.s3_bucket
        if not hasattr(self._thread_local, "s3_bucket"):
            session = self._get_session()
            resource = session.resource("s3", endpoint_url=self.endpoint_url)
            self._thread_local.s3_bucket = resource.Bucket(self.bucket)
        return self._thread_local.s3_bucket
    def write_doc_to_s3(self, doc: Dict, search_keys: List[str]):
        s3_bucket = self._get_bucket()
        search_doc = {k: str(doc[k]) for k in search_keys}
        search_doc[self.key] = doc[self.key]  
        if self.sub_dir != "":
            search_doc["sub_dir"] = self.sub_dir
        if "_id" in search_doc:
            del search_doc["_id"]
        lu_info = doc.pop(self.last_updated_field, None)
        data = msgpack.packb(doc, default=monty_default)
        if self.compress:
            search_doc["compression"] = "zlib"
            data = zlib.compress(data)
        if self.last_updated_field in doc:
            search_doc[self.last_updated_field] = str(
                to_isoformat_ceil_ms(doc[self.last_updated_field])
            )
        s3_bucket.put_object(
            Key=self.sub_dir + str(doc[self.key]), Body=data, Metadata=search_doc
        )
        if lu_info is not None:
            search_doc[self.last_updated_field] = lu_info
        if self.store_hash:
            hasher = sha1()
            hasher.update(data)
            obj_hash = hasher.hexdigest()
            search_doc["obj_hash"] = obj_hash
        return search_doc
    def remove_docs(self, criteria: Dict, remove_s3_object: bool = False):
        if not remove_s3_object:
            self.index.remove_docs(criteria=criteria)
        else:
            to_remove = self.index.distinct(self.key, criteria=criteria)
            self.index.remove_docs(criteria=criteria)
            to_remove_chunks = list(grouper(to_remove, n=1000))
            for chunk_to_remove in to_remove_chunks:
                objlist = [{"Key": self.sub_dir + obj} for obj in chunk_to_remove]
                self.s3_bucket.delete_objects(Delete={"Objects": objlist})
    @property
    def last_updated(self):
        return self.index.last_updated
    def newer_in(
        self, target: Store, criteria: Optional[Dict] = None, exhaustive: bool = False
    ) -> List[str]:
        if hasattr(target, "index"):
            return self.index.newer_in(
                target=target.index, criteria=criteria, exhaustive=exhaustive
            )
        else:
            return self.index.newer_in(
                target=target, criteria=criteria, exhaustive=exhaustive
            )
    def __hash__(self):
        return hash((self.index.__hash__, self.bucket))
    def rebuild_index_from_s3_data(self, **kwargs):
        bucket = self.s3_bucket
        objects = bucket.objects.filter(Prefix=self.sub_dir)
        for obj in objects:
            key_ = self.sub_dir + obj.key
            data = self.s3_bucket.Object(key_).get()["Body"].read()
            if self.compress:
                data = zlib.decompress(data)
            unpacked_data = msgpack.unpackb(data, raw=False)
            self.update(unpacked_data, **kwargs)
    def rebuild_metadata_from_index(self, index_query: dict = None):
        qq = {} if index_query is None else index_query
        for index_doc in self.index.query(qq):
            key_ = self.sub_dir + index_doc[self.key]
            s3_object = self.s3_bucket.Object(key_)
            new_meta = {str(k).lower(): v for k, v in s3_object.metadata.items()}
            for k, v in index_doc.items():
                new_meta[str(k).lower()] = v
            new_meta.pop("_id")
            if self.last_updated_field in new_meta:
                new_meta[self.last_updated_field] = str(
                    to_isoformat_ceil_ms(new_meta[self.last_updated_field])
                )
            s3_object.copy_from(
                CopySource={"Bucket": self.s3_bucket.name, "Key": key_},
                Metadata=new_meta,
                MetadataDirective="REPLACE",
            )
    def __eq__(self, other: object) -> bool:
        if not isinstance(other, S3Store):
            return False
        fields = ["index", "bucket", "last_updated_field"]
        return all(getattr(self, f) == getattr(other, f) for f in fields)

class Set:
    def __init__(self, value = []): 		
        self.data = [] 			
        self.concat(value)
    def intersect(self, other): 
        res = [] 				
        for x in self.data:
            if x in other: 		
                res.append(x)
        return Set(res) 		
    def union(self, other): 	
        res = self.data[:] 		
        for x in other: 		
            if not x in res:
                res.append(x)
        return Set(res)
    def concat(self, value): 	
        for x in value: 		
            if not x in self.data:
                self.data.append(x)
    def __len__(self): return len(self.data) 				 	
    def __getitem__(self, id_sli): return self.data[id_sli] 		 	
    def __and__(self, other): return self.intersect(other) 		
    def __or__(self, other): return self.union(other) 			
    def __repr__(self): return 'Set:' + repr(self.data) 		
    def __iter__(self): return iter(self.data)

