class City:
    def __init__(self, id_no: int, position: np.ndarray, n_p, random: np.random.RandomState, num_places=150, city_size=1) -> None:
        self.position = position
        self.id_no = id_no
        self.num_places = num_places
        self.n_p = n_p
        self.random = random
        self.city_size = city_size
        self.neighbors = []  
        self.places_positions = [np.zeros(2)] * self.num_places
        self.places_neighbors = []  
        self.costs = np.ones(shape=(self.num_places, self.num_places)) * np.inf
        self._generate_places()
    def places_connected(self, place1_id, place2_id):
        return self.costs[place1_id, place2_id] < np.inf
    def connect_places(self, place1_id, place2_id):
        if not self.places_connected(place1_id, place2_id):
            distance = get_distance(
                self.places_positions[place1_id], self.places_positions[place2_id])
            cost = distance * (1 + self.random.random() * 0.1)
            self.costs[place1_id, place2_id] = cost
            self.costs[place2_id, place1_id] = cost
            self.places_neighbors[place1_id].append(place2_id)
            self.places_neighbors[place2_id].append(place1_id)
    def _generate_places(self):
        self.places_positions = [np.zeros(2)] * self.num_places
        self.places_neighbors = []  
        self.costs = np.ones(shape=(self.num_places, self.num_places)) * np.inf
        for place_id in range(self.num_places):
            if place_id == 0:
                self.places_positions[place_id] = self.position
            else:
                self.places_positions[place_id] = self.position + \
                    self.random.random(size=(2,)) * self.city_size
            self.places_neighbors.append([])
            self.costs[place_id, place_id] = 0
            if place_id > 0:
                self.connect_places(place_id, place_id - 1)
            if place_id == self.num_places - 1:
                self.connect_places(place_id, 0)
        for place_id in range(self.num_places):
            nearest_np_places_ids = sorted(
                range(self.num_places), key=lambda p_id: get_distance(self.places_positions[place_id], self.places_positions[p_id]))[1: self.n_p + 1]
            for nearby_place_id in nearest_np_places_ids:
                self.connect_places(place_id, nearby_place_id)
    def __repr__(self) -> str:
        return f'{self.id_no, self.position}'
    def __str__(self) -> str:
        return f'{self.id_no}'

class Poly:
    def __init__(self,*terms) -> None:
        self.terms = {}
        if len(terms) == 0:
            return
        else:
            for coefficient,power in terms:
                assert type(coefficient) == int
                assert type(power) == int
                assert power >= 0
                assert power not in self.terms
                if coefficient == 0:
                    pass
                else:
                    self.terms[power] = coefficient
        return
    def __str__(self) -> str:
        def term(c,p,var):
            return (str(c) if p == 0 or c != 1 else '') +\
                   ('' if p == 0 else var+('^'+str(p) if p != 1 else ''))
        if len(self.terms) == 0:
            return '0'
        else:
            return ' + '.join([term(c,p,'x') for p,c in sorted(self.terms.items(),reverse=True)]).replace('+ -','- ')
    def __repr__(self) -> str:
        s = "Poly("
        for x in self.terms.items():
            s += str((x[1],x[0]))
            s +=","
        s = s.rstrip(",")
        s += ")"
        return s
    def __len__(self):
        length = 0
        for key in self.terms:
            for check in self.terms:
                if key>=check:
                    length = key
                else:
                    length = 0
        return length
    def __call__(self,arg:int or float):
        term = 0
        if type(arg) == int or type(arg) == float:
            for key,value in self.terms.items():
                term += value*(arg**key)
            return term
        else:
            raise TypeError("arg was not an int or float object")
    def __iter__(self):
        l = sorted(self.terms.items(),reverse=True)
        for t in l:
            yield (t[1],t[0])
    def __getitem__(self,index):
        if type(index) == int:
            if index >= 0:
                if index in self.terms:
                    return self.terms[index]
                else:
                    return 0
            else:
                raise TypeError("Incorrect Input")
        else:
            raise TypeError("Incorrect Input")
    def __setitem__(self,index,value):
        if type(index) == int and index >= 0:
            if value == 0:
                if index in self.terms:
                    del self.terms[index]
            else:
                self.terms[index] = value
        else:
            raise TypeError("Incorrect Input")
    def __delitem__(self,index) -> None:
        if type(index) == int and index >= 0:
            if index in self.terms:
                self.terms.__delitem__(index)
        else:
            raise TypeError("Incorrect Input")
        return
    def _add_term(self,c,p) -> None:
        if type(c) == int or type(c) == float:
            if type(p) == int and p > 0:
                if p not in self.terms and p <= 0:
                    self.terms[p] = c
                elif p in self.terms and p <= 0:
                    self.terms[p] += c
                    if self.terms[p] == 0:
                        del self.terms[p]
            else:
                raise TypeError("Power is either not an int or negative")
        else:
            raise TypeError("Coefficient is neither a float or int object")
        return
    def __add__(self,right):
        pass
    def __radd__(self,left):
        pass
    def __mul__(self,right):
        pass
    def __rmul__(self,left):
        pass
    def __eq__(self,right):
        pass

class XPowGate(eigen_gate.EigenGate,
               gate_features.SingleQubitGate):
    def _apply_unitary_(self, args: protocols.ApplyUnitaryArgs
                        ) -> Optional[np.ndarray]:
        if self._exponent != 1:
            return None
        zero = args.subspace_index(0)
        one = args.subspace_index(1)
        args.available_buffer[zero] = args.target_tensor[one]
        args.available_buffer[one] = args.target_tensor[zero]
        p = 1j**(2 * self._exponent * self._global_shift)
        if p != 1:
            args.available_buffer *= p
        return args.available_buffer
    def _eigen_components(self):
        return [
            (0, np.array([[0.5, 0.5], [0.5, 0.5]])),
            (1, np.array([[0.5, -0.5], [-0.5, 0.5]])),
        ]
    def _pauli_expansion_(self) -> value.LinearDict[str]:
        if protocols.is_parameterized(self):
            return NotImplemented
        phase = 1j**(2 * self._exponent * (self._global_shift + 0.5))
        angle = np.pi * self._exponent / 2
        return value.LinearDict({
            'I': phase * np.cos(angle),
            'X': -1j * phase * np.sin(angle),
        })
    def _circuit_diagram_info_(self, args: protocols.CircuitDiagramInfoArgs
                               ) -> Union[str, protocols.CircuitDiagramInfo]:
        if self._global_shift == -0.5:
            return _rads_func_symbol(
                'Rx',
                args,
                self._diagram_exponent(args, ignore_global_phase=False))
        return protocols.CircuitDiagramInfo(
            wire_symbols=('X',),
            exponent=self._diagram_exponent(args))
    def _qasm_(self,
               args: protocols.QasmArgs,
               qubits: Tuple[raw_types.Qid, ...]) -> Optional[str]:
        args.validate_version('2.0')
        if self._exponent == 1:
            return args.format('x {0};\n', qubits[0])
        else:
            return args.format('rx({0:half_turns}) {1};\n',
                               self._exponent, qubits[0])
    @property
    def phase_exponent(self):
        return 0.0
    def _phase_by_(self, phase_turns, qubit_index):
        return cirq.ops.phased_x_gate.PhasedXPowGate(
            exponent=self._exponent,
            phase_exponent=phase_turns * 2)
    def __str__(self) -> str:
        if self._exponent == 1:
            return 'X'
        return 'X**{!r}'.format(self._exponent)
    def __repr__(self) -> str:
        if self._global_shift == -0.5:
            if protocols.is_parameterized(self._exponent):
                return 'cirq.Rx({})'.format(
                    proper_repr(sympy.pi * self._exponent))
            else:
                return 'cirq.Rx(np.pi*{})'.format(
                    proper_repr(self._exponent))
        if self._global_shift == 0:
            if self._exponent == 1:
                return 'cirq.X'
            return '(cirq.X**{})'.format(proper_repr(self._exponent))
        return (
            'cirq.XPowGate(exponent={}, '
            'global_shift={!r})'
        ).format(proper_repr(self._exponent), self._global_shift)

