                with open(file_name,"r") as fin:
                    lines = [ line.strip() for line in fin ]
                end = lines.index('END') if 'END' in lines else len(lines)
                lines = lines[:end]
                cards = [ pyfits.Card().fromstring(line) for line in lines ]
                header = pyfits.Header(cards)
            else:
                hdu_list, fin = _read_file(file_name, dir, file_compress)
        if hdu_list:
            hdu = _get_hdu(hdu_list, hdu, pyfits_compress, header_only=True)
            header = hdu.header
        if file_name and not text_file:
            import copy
            self.header = copy.copy(header)
            closeHDUList(hdu_list, fin)
        elif isinstance(header, pyfits.Header):
            self.header = header
        else:
            self.header = pyfits.Header()
            if header is not None:
                if hasattr(header, 'items'):
                    self.update(header)
                else:
                    for card in header:
                        self.header.append(card, end=True)
    def __len__(self):
        return len(self.header)
    def __contains__(self, key):
        return key in self.header
    def __delitem__(self, key):
        self._tag = None
        del self.header[key]
    def __getitem__(self, key):
        return self.header[key]
    def __iter__(self):
        return self.header.__iter__()
    def __setitem__(self, key, value):
        self._tag = None
        self.header[key.upper()] = value
    def comment(self, key):
        return self.header.comments[key.upper()]
    def clear(self):
        self._tag = None
        self.header.clear()
    def get(self, key, default=None):
        return self.header.get(key, default)
    def pop(self, key, default=None):
        return self.header.pop(key, default)
    def items(self):
        return self.header.items()
    def iteritems(self):
        return self.items()
    def iterkeys(self):
        return self.keys()
    def itervalues(self):
        return self.values()
    def keys(self):
        return self.header.keys()
    def update(self, dict2):
        self._tag = None
        for key, item in dict2.items():
            self.header[key.upper()] = item
    def values(self):
        return self.header.values()
    def append(self, key, value='', comment=None, useblanks=True):
        self._tag = None
        self.header.append((key.upper(), value, comment), useblanks=useblanks)
    def extend(self, other, replace=False, useblanks=True):
        self._tag = None
        self.header.extend(other.header, unique=not replace, update=replace, useblanks=useblanks)
    def __repr__(self):
        if self._tag is None:
            return "galsim.FitsHeader(header=%r)"%list(self.items())
        else:
            return "galsim.FitsHeader(%s)"%self._tag
    def __str__(self):
        if self._tag is None:
            return "galsim.FitsHeader(header=<Header object at %s>)"%id(self.header)
        else:
            return "galsim.FitsHeader(%s)"%self._tag
    def __eq__(self, other):
        return (self is other or
                (isinstance(other,FitsHeader) and
                 list(self.header.items()) == list(other.header.items())))
    def __ne__(self, other): return not self.__eq__(other)
    def __hash__(self):
        return hash(tuple(sorted(self.items())))

class Card:
    values = {'6': 1, '7': 2, '8': 3, '9': 4, '10': 5, 'J': 6, 'Q': 7, 'K': 8, 'A': 9}
    trump = None
    def __init__(self, val_suit):
        self.val = val_suit[:-1]
        self.suit = val_suit[-1]
    def __gt__(self, other):
        if self.suit == other.suit:
            return self.values[self.val] > self.values[other.val]
        elif self.suit == self.trump:
            return True
        elif other.suit == self.trump:
            return False
        else:
            raise ValueError("Cannot compare different suits")
    def __eq__(self, other):
        return self.val == other.val and self.suit == other.suit

class AttrDict(OrderedDict):
    def __init__(self, *args, **kwargs):
        super(AttrDict, self).__init__(*args, **kwargs)
        self.__dict__ = self
        for k,v in self.items():
            assert '.' not in k, "AttrDict: attribute '" + k + "' is invalid ('.' char is not allowed)"
            if isinstance(v, dict):
                self[k] = AttrDict(v)
            elif isinstance(v, list):
                self[k] = [AttrDict(item) if isinstance(item, dict) else item for item in v]
    def __repr__(self):
        def write_item(item, margin='\n'):
            if isinstance(item, dict):
                s = '{'
                margin2 = margin + '    '
                for k, v in item.items():
                    if not k.startswith('__') and k != 'data_root':
                        s += margin2 + "'{0}': ".format(k) + write_item(v, margin=margin2) + ","
                if item.items():
                    s += margin
                s += '}'
            elif isinstance(item, (list, tuple)):
                s = '[' if isinstance(item, list) else '('
                for v in item:
                    if isinstance(v, dict):
                        s += margin + '    '
                    else:
                        s += ' '
                    s += write_item(v, margin=margin + '    ')  + ","
                s += ' ' + (']' if isinstance(item, list) else ')')
            else:
                s = repr(item)
            return s
        return write_item(self)
    def has(self, name):
        names = name.split('.')
        dic = self
        for n in names:
            if not hasattr(dic, n):
                return False
            dic = dic[n]
        return True
    def hash(self, shrink_to = 6):
        hash_dict = self.copy()
        hash_dict.pop('data_root', None)
        return hashlib.sha1(json.dumps(hash_dict, sort_keys=True).encode()).hexdigest()[:shrink_to]
    def get_model_name(self):
        assert self.has('model_name')
        return self.model_name.format(**self) + '_' + self.hash()
    def get_base_filename(self):
        assert self.has('data_root')
        return os.path.join(self.data_root, self.get_model_name())
    def save(self, base_fn = None, verbose = 1, can_overwrite = False, create_dirs = False):
        if base_fn is None:
            base_fn = self.get_base_filename()
        params_fn = str(Path(base_fn) / 'param.txt')
        if not can_overwrite:
            assert not os.path.exists(params_fn), "Can't save parameters to {}: File exists".format(params_fn)
        if create_dirs:
            dir_name = os.path.dirname(params_fn)
            os.makedirs(dir_name, exist_ok=True)
        with open(params_fn, 'w+') as f:
            s = str(self)
            s = s + '\nhash: ' + self.hash()
            f.write(s)
            if verbose >= 2:
                print('params: '+ s)
            if verbose >= 1:
                print('saved to ' + params_fn)
    def load_from_str(s, data_root):
        assert len(s) >= 2
        assert s[0][0] == '{' and s[-1][-2:] == '}\n'
        s = ''.join(s)
        s = s.replace('\n', '')
        params = ast.literal_eval(s)
        if data_root:
            params.data_root = data_root
        return AttrDict(params)
    def load(params_fn, data_root = None, verbose = 1):
        import ast
        with open(params_fn) as f:
            s = f.readlines()
            assert s[-1].startswith('hash:')
            params = AttrDict.load_from_str(s[:-1], data_root)
        if verbose >= 2:
            print('params: '+ str(params) + '\nhash: ' + params.hash())
        if verbose >= 1:
            print('loaded from ' + str(params_fn))
        return params

