    def determine_custom_item_names():
        for k,v in Item.custom_items_info.iteritems():
            if "name" not in v:
                v["name"] = k
    @property
    def flags(self):
        flagstr = ""
        for varname,flag in Item.serialization_flags.iteritems():
            if getattr(self, varname):
                flagstr += flag
        return flagstr
