class GregorianCalendar:
    def __init__(self, year, month, day):
        if (
            not isinstance(year, int)
            or not isinstance(month, int)
            or not isinstance(day, int)
        ):
            raise TypeError("integer argument expected")
        if month < 1 or month > 12:
            raise ValueError(
                "Month must be between 1 and 12, while it is {}.".format(month)
            )
        if (
            day < 1
            or day > _days_in_month[GregorianCalendar.is_leap_year(year)][month - 1]
        ):
            raise ValueError(
                "Day must be between 1 and number of days in month, while it is {}.".format(
                    day
                )
            )
        self._year = year
        self._month = month
        self._day = day
        self._rata_die = None
    @property
    def year(self):
        return self._year
    @property
    def month(self):
        return self._month
    @property
    def day(self):
        return self._day
    @classmethod
    def year_day(cls, year, day):
        if not isinstance(year, int) or not isinstance(day, int):
            raise TypeError("integer argument expected")
        if day < 1 or day > (366 if GregorianCalendar.is_leap_year(year) else 365):
            raise ValueError(
                "Day must be between 1 and number of days in year, while it is {}.".format(
                    day
                )
            )
        month = bisect.bisect_left(
            _days_in_previous_months[GregorianCalendar.is_leap_year(year)], day
        )
        day_in_month = (
            day
            - _days_in_previous_months[GregorianCalendar.is_leap_year(year)][month - 1]
        )
        return cls(year, month, day_in_month)
    @classmethod
    def from_rata_die(cls, day_count):
        if not isinstance(day_count, int):
            raise TypeError("integer argument expected")
        y400, d400 = divmod(day_count - 1, 146097)
        y100, d100 = divmod(d400, 36524)
        y4, d4 = divmod(d100, 1461)
        y1 = d4 // 365
        year_minus_one = (
            400 * y400 + 100 * y100 + 4 * y4 + y1 - (1 if (y100 == 4 or y1 == 4) else 0)
        )
        days = (
            day_count
            - 365 * year_minus_one
            - year_minus_one // 4
            + year_minus_one // 100
            - year_minus_one // 400
        )  
        greg_day = cls.year_day(year_minus_one + 1, days)
        greg_day._rata_die = day_count
        return greg_day
    @staticmethod
    def is_leap_year(year):
        return (year % 4 == 0) and (year % 400 not in (100, 200, 300))
    @staticmethod
    def days_in_year(year):
        return 365 if not GregorianCalendar.is_leap_year(year) else 366
    def to_rata_die(self):
        if self._rata_die is None:
            self._rata_die = (
                365 * (self._year - 1)
                + (self._year - 1) // 4
                - (self._year - 1) // 100
                + (self._year - 1) // 400
                + (367 * self._month - 362) // 12
                + (
                    (-1 if GregorianCalendar.is_leap_year(self._year) else -2)
                    if self._month > 2
                    else 0
                )
                + self._day
            )
        return self._rata_die
    def weekday(self):
        return (self.to_rata_die() - 1) % 7 + 1
    def day_of_year(self):
        return self.to_rata_die() - (
            365 * (self._year - 1)
            + (self._year - 1) // 4
            - (self._year - 1) // 100
            + (self._year - 1) // 400
        )
    def replace(self, *, year=None, month=None, day=None):
        if year is None:
            year = self.year
        if month is None:
            month = self.month
        if day is None:
            day = self.day
        return self.__class__(year, month, day)
    def __eq__(self, other):
        return (
            isinstance(other, GregorianCalendar)
            and self.year == other.year
            and self.month == other.month
            and self.day == other.day
        )
    def __gt__(self, other):
        if isinstance(other, GregorianCalendar):
            return (self.year, self.month, self.day) > (
                other.year,
                other.month,
                other.day,
            )
        else:
            return NotImplemented
    def __hash__(self):
        return hash((self.year, self.month, self.day))
    def __repr__(self):
        return "datetime2.western.{}({}, {}, {})".format(
            self.__class__.__name__, self.year, self.month, self.day
        )
    def __str__(self):
        if self.year >= 0:
            return "{:04d}-{:02d}-{:02d}".format(self.year, self.month, self.day)
        else:
            return "{:05d}-{:02d}-{:02d}".format(self.year, self.month, self.day)
    name_weekdays = [
        "Monday",
        "Tuesday",
        "Wednesday",
        "Thursday",
        "Friday",
        "Saturday",
        "Sunday",
    ]
    name_months = [
        "January",
        "February",
        "March",
        "April",
        "May",
        "June",
        "July",
        "August",
        "September",
        "October",
        "November",
        "December",
    ]
    format_functions = {
        "a": lambda self: GregorianCalendar.name_weekdays[self.weekday() - 1][:3],
        "A": lambda self: GregorianCalendar.name_weekdays[self.weekday() - 1],
        "b": lambda self: GregorianCalendar.name_months[self.month - 1][:3],
        "B": lambda self: GregorianCalendar.name_months[self.month - 1],
        "d": lambda self: "{:02d}".format(self.day),
        "m": lambda self: "{:02d}".format(self.month),
        "j": lambda self: "{:03d}".format(self.day_of_year()),
        "U": lambda self: "{:02d}".format(
            (self.day_of_year() + (13 - self.weekday()) % 7) // 7
        ),
        "w": lambda self: "{:1d}".format(self.weekday()),
        "W": lambda self: "{:02d}".format(
            (self.day_of_year() + 7 - self.weekday()) // 7
        ),
        "y": lambda self: "{:03d}".format(self.year)[-2:],
        "Y": lambda self: "{:04d}".format(self.year)
        if self.year >= 0
        else "-{:04d}".format(-self.year),
    }
    def cformat(self, format_string):
        if not isinstance(format_string, str):
            raise TypeError("Format must be specified with string.")
        output_pieces = []
        for format_chunk in format_string.split("%%"):
            format_parts = format_chunk.split("%")
            chunk_pieces = [format_parts[0]]
            for part in format_parts[1:]:
                if part == "":  
                    value = "%"
                else:
                    try:
                        value = self.format_functions[part[0]](self)
                    except KeyError:
                        value = "%" + part[0]
                chunk_pieces.append(value)
                chunk_pieces.append(part[1:])
            output_pieces.append("".join(chunk_pieces))
        return "%".join(output_pieces)

class WesternTime:
    def __init__(self, hour, minute, second, *, to_utc=None):
        if not isinstance(hour, int) or not isinstance(minute, int):
            raise TypeError("Hour and minute must be integer")
        if hour < 0 or hour > 23:
            raise ValueError(
                "Hour must be between 0 and 23, while it is {}.".format(hour)
            )
        if minute < 0 or minute > 59:
            raise ValueError(
                "Minute must be between 0 and 59, while it is {}.".format(minute)
            )
        try:
            second_fraction = verify_fractional_value(second, min=0, max_excl=60)
        except TypeError as exc:
            raise TypeError("Second is not a valid fractional value") from exc
        except ValueError as exc:
            raise ValueError(
                "Second must be equal or greater than 0 and less than 60."
            ) from exc
        self._hour = hour
        self._minute = minute
        self._second = second_fraction
        self._day_frac = None
        if to_utc is None:
            self._to_utc = None
        else:
            try:
                candidate_to_utc = verify_fractional_value(to_utc, min=-24, max=+24)
            except TypeError as exc:
                raise TypeError("Time zone is not a valid fractional value") from exc
            except ValueError as exc:
                raise ValueError(
                    "Time zone must be greater than -24 and less than 24."
                ) from exc
            self._to_utc = candidate_to_utc
    @property
    def hour(self):
        return self._hour
    @property
    def minute(self):
        return self._minute
    @property
    def second(self):
        return self._second
    @property
    def to_utc(self):
        return self._to_utc
    @classmethod
    def in_hours(cls, hours):
        try:
            hour_fraction = verify_fractional_value(hours, min=0, max_excl=24)
        except TypeError as exc:
            raise TypeError("'hours' is not a valid fractional value") from exc
        except ValueError as exc:
            raise ValueError(
                "'hours' must be equal or greater than 0 and less than 24."
            ) from exc
        hour = int(hour_fraction)
        minute = int((hour_fraction - hour) * 60)
        second = (hour_fraction - hour - Fraction(minute, 60)) * 3600
        western = cls(hour, minute, second)
        western._day_frac = hour_fraction / 24
        return western
    @classmethod
    def in_minutes(cls, minutes):
        try:
            minute_fraction = verify_fractional_value(minutes, min=0, max_excl=1440)
        except TypeError as exc:
            raise TypeError("'minutes' is not a valid fractional value") from exc
        except ValueError as exc:
            raise ValueError(
                "'minutes' must be equal or greater than 0 and less than 1440."
            ) from exc
        hour = int(minute_fraction / 60)
        minute = int(minute_fraction - hour * 60)
        second = (minute_fraction - hour * 60 - minute) * 60
        western = cls(hour, minute, second)
        western._day_frac = minute_fraction / 1440
        return western
    @classmethod
    def in_seconds(cls, seconds):
        try:
            second_fraction = verify_fractional_value(seconds, min=0, max_excl=86400)
        except TypeError as exc:
            raise TypeError("'seconds' is not a valid fractional value") from exc
        except ValueError as exc:
            raise ValueError(
                "'seconds' must be equal or greater than 0 and less than 86400."
            ) from exc
        hour = int(second_fraction / 3600)
        minute = int((second_fraction - hour * 3600) / 60)
        second = second_fraction - hour * 3600 - minute * 60
        western = cls(hour, minute, second)
        western._day_frac = second_fraction / 86400
        return western
    @classmethod
    def from_day_frac(cls, day_frac):
        if not isinstance(day_frac, Fraction):
            raise TypeError("Fraction argument expected")
        if day_frac < 0 or day_frac >= 1:
            raise ValueError(
                "Day fraction must be equal or greater than 0 and less than 1, while it is {}.".format(
                    day_frac
                )
            )
        hour = int(day_frac * 24)
        minute = int((day_frac - Fraction(hour, 24)) * 1440)
        second = (day_frac - Fraction(hour, 24) - Fraction(minute, 1440)) * 86400
        western = cls(hour, minute, second)
        western._day_frac = day_frac
        return western
    def to_day_frac(self):
        if self._day_frac is None:
            self._day_frac = (
                self._second / 86400
                + Fraction(self.minute, 1440)
                + Fraction(self.hour, 24)
            )
        return self._day_frac
    def to_hours(self):
        return self.to_day_frac() * 24
    def to_minutes(self):
        return self.to_day_frac() * 1440
    def to_seconds(self):
        return self.to_day_frac() * 86400
    def replace(self, *, hour=None, minute=None, second=None):
        if hour is None:
            hour = self.hour
        if minute is None:
            minute = self.minute
        if second is None:
            second = self.second
        return self.__class__(hour, minute, second)
    def __eq__(self, other):
        return (
            isinstance(other, WesternTime)
            and self.hour == other.hour
            and self.minute == other.minute
            and self.second == other.second
        )
    def __gt__(self, other):
        if isinstance(other, WesternTime):
            return (self.hour, self.minute, self.second) > (
                other.hour,
                other.minute,
                other.second,
            )
        else:
            return NotImplemented
    def __hash__(self):
        return hash((self.hour, self.minute, self.second))
    def __repr__(self):
        return "datetime2.western.{}({}, {}, {})".format(
            self.__class__.__name__, self.hour, self.minute, repr(self.second)
        )
    def __str__(self):
        return "{:02d}:{:02d}:{:02d}".format(self.hour, self.minute, int(self.second))
    format_functions = {
        "H": lambda self: "{:02d}".format(self.hour),
        "I": lambda self: "{:02d}".format(
            12 if self.hour == 0 else self.hour if self.hour <= 12 else self.hour - 12
        ),
        "p": lambda self: "AM" if self.hour < 12 else "PM",
        "M": lambda self: "{:02d}".format(self.minute),
        "S": lambda self: "{:02d}".format(floor(self.second)),
        "f": lambda self: "{:06d}".format(
            int((self.second - floor(self.second)) * 1000000)
        ),
    }
    def cformat(self, format_string):
        if not isinstance(format_string, str):
            raise TypeError("Format must be specified with string.")
        output_pieces = []
        for format_chunk in format_string.split("%%"):
            format_parts = format_chunk.split("%")
            chunk_pieces = [format_parts[0]]
            for part in format_parts[1:]:
                if part == "":  
                    value = "%"
                else:
                    try:
                        value = self.format_functions[part[0]](self)
                    except KeyError:
                        value = "%" + part[0]
                chunk_pieces.append(value)
                chunk_pieces.append(part[1:])
            output_pieces.append("".join(chunk_pieces))
        return "%".join(output_pieces)

class Fan(BaseACIPhysModule):
    def __init__(self, identifier=None, parent=None):
        self.descr = None
        self.type = 'fan'
        self.oper_st = None
        self.direction = None
        self.speed = None
        self.id = identifier
        self._parent = parent
        self._children = []
    @classmethod
    def get(cls, session, parent=None):
        if not isinstance(session, Session):
            raise TypeError('An instance of Session class is required')
        if parent:
            if not isinstance(parent, Fantray):
                raise TypeError('When a parent is specified, it must be of type Fantray class')
        fans = []
        if parent:
            mo_query_url = '/api/mo/' + parent.dn + '.json?query-target=subtree&target-subtree-class=eqptFan'
        else:
            mo_query_url = ('/api/node/class/eqptFan.json?'
                            'query-target=self')
        ret = session.get(mo_query_url)
        node_data = ret.json()['imdata']
        if node_data:
            for fan_obj in node_data:
                fan = Fan()
                fan.dn = str(fan_obj['eqptFan']['attributes']['dn'])
                fan.id = str(fan_obj['eqptFan']['attributes']['id'])
                fan.descr = str(fan_obj['eqptFan']['attributes']['descr'])
                fan.oper_st = str(fan_obj['eqptFan']['attributes']['operSt'])
                fan.direction = str(fan_obj['eqptFan']['attributes']['dir'])
                fan.model = str(fan_obj['eqptFan']['attributes']['model'])
                fan.serial = str(fan_obj['eqptFan']['attributes']['ser'])
                mo_query_url = '/api/mo/' + fan.dn + \
                               '.json?rsp-subtree-include=stats&rsp-subtree-class=eqptFanStats5min'
                ret = session.get(mo_query_url)
                stat_data = ret.json()['imdata']
                fan.speed = 'unknown'
                if stat_data:
                    if 'eqptFan' in stat_data[0]:
                        if 'children' in stat_data[0]['eqptFan']:
                            if stat_data[0]['eqptFan']['children']:
                                if 'eqptFanStats5min' in stat_data[0]['eqptFan']['children'][0]:
                                    fan.speed = \
                                        str(stat_data[0]['eqptFan']['children'][0]['eqptFanStats5min']['attributes'][
                                            'speedLast'])
                if parent:
                    fan._parent = parent
                    parent.add_child(fan)
                fans.append(fan)
        return fans
    def __eq__(self, other):
        if type(self) == type(other):
            if self.model == other.model:
                if self.id == other.id:
                    if self._parent == other._parent:
                        return True
        return False

class Pod(BaseACIPhysObject):
    def __init__(self, pod_id, attributes=None, parent=None):
        if isinstance(parent, str):
            raise TypeError("Parent object can't be a string")
        if attributes:
            if not isinstance(attributes, dict):
                raise TypeError("Attributes must be a dictionary")
        if attributes:
            self.attributes = copy.deepcopy(attributes)
        else:
            self.attributes = {}
        self.pod = str(pod_id)
        self.type = 'pod'
        self.name = 'pod-' + str(self.pod)
        self._session = None
        logging.debug('Creating %s %s', self.__class__.__name__, self.pod)
        self._common_init(parent)
        if 'dist_name' in self.attributes:
            self.atomic = AtomicCountersOnGoing(self, self.attributes['dist_name'])
    @staticmethod
    def get(session, parent=None):
        if parent:
            if not isinstance(parent, PhysicalModel):
                raise TypeError(
                    'The parent of Pod must be of type PhysicalModel.  Got ' + str(type(parent)) + ' instead.')
        if not isinstance(session, Session):
            raise TypeError('An instance of Session class is required')
        class_query_url = ('/api/node/class/fabricPod.json?'
                           'query-target=self')
        pods = []
        ret = session.get(class_query_url)
        pod_data = ret.json()['imdata']
        for apic_pod in pod_data:
            if 'fabricPod' in apic_pod:
                attributes = {'dist_name': str(apic_pod['fabricPod']['attributes']['dn']),
                              'pod_id': str(apic_pod['fabricPod']['attributes']['id'])}
                pod = Pod(attributes['pod_id'], attributes=attributes)
                pod._session = session
                if parent:
                    pod._parent = parent
                    pod._parent.add_child(pod)
                pods.append(pod)
        return pods
    def populate_children(self, deep=False, include_concrete=False):
        Node.get(self._session, self)
        Link.get(self._session, self)
        ExternalSwitch.get(self._session, self)
        if deep:
            for child in self._children:
                child.populate_children(deep, include_concrete)
        return self._children
    def __eq__(self, other):
        if type(self) is not type(other):
            return False
        return self.pod == other.pod
    def __str__(self):
        return 'pod-' + str(self.pod)

class ExternalSwitch(BaseACIPhysObject):
    def __init__(self, parent=None):
        super(ExternalSwitch, self).__init__(name='', parent=parent)
        self.name = None
        if parent:
            if not isinstance(parent, Pod):
                raise TypeError("Parent must be a Pod")
        self._parent = parent
        self._role = None
        self.dn = None
        self.name = None
        self.ip = None
        self.mac = None
        self.id = None
        self.pod = None
        self.status = None
        self.oper_issues = None
        self.fabric_st = 'external'
        self.role = 'external_switch'
        self.descr = None
        self.type = None
        self.state = None
        self.guid = None
        self.oid = None
    def getRole(self):
        return self.role
    @property
    def role(self):
        return self._role
    @role.setter
    def role(self, value):
        valid_roles = [None, 'external_switch']
        if value not in valid_roles:
            raise ValueError("role must be one of " + str(valid_roles) + ' found ' + str(value))
        self._role = value
    @staticmethod
    def _get_physical_switches(session, parent):
        lnode_query_url = ('/api/node/class/fabricLooseNode.json?'
                           'query-target=self')
        lnodes = []
        ret = session.get(lnode_query_url)
        lnode_data = ret.json()['imdata']
        for apic_node in lnode_data:
            if 'fabricLooseNode' in apic_node:
                external_switch = ExternalSwitch(parent)
                external_switch._populate_physical_from_attributes(apic_node['fabricLooseNode']['attributes'])
                external_switch._get_system_info(session)
                if parent:
                    if isinstance(parent, Pod):
                        external_switch._parent.add_child(external_switch)
                lnodes.append(external_switch)
        return lnodes
    def _populate_physical_from_attributes(self, attr):
        self.dn = str(attr['dn'])
        self.name = str(attr['sysName'])
        self.id = str(attr['id'])
        self.status = str(attr['status'])
        self.oper_issues = str(attr['operIssues'])
        self.descr = str(attr['sysDesc'])
    @staticmethod
    def _get_virtual_switches(session, parent):
        class_query_url = '/api/node/class/compHv.json?query-target=self'
        vnodes = []
        ret = session.get(class_query_url)
        vnode_data = ret.json()['imdata']
        for apic_node in vnode_data:
            if 'compHv' in apic_node:
                external_switch = ExternalSwitch()
                external_switch._populate_virtual_from_attributes(apic_node['compHv']['attributes'])
                external_switch._get_system_info(session)
                if parent:
                    if isinstance(parent, Pod):
                        external_switch._parent = parent
                        external_switch._parent.add_child(external_switch)
                vnodes.append(external_switch)
        return vnodes
    def _populate_virtual_from_attributes(self, attr):
        self.dn = str(attr['dn'])
        self.name = str(attr['name'])
        self.descr = str(attr['descr'])
        self.type = str(attr['type'])
        self.state = str(attr['state'])
        self.guid = str(attr['guid'])
        self.oid = str(attr['oid'])
    @classmethod
    def get(cls, session, parent=None):
        if not isinstance(session, Session):
            raise TypeError('session must of type Session')
        if parent:
            if not isinstance(parent, Pod):
                raise TypeError('parent must be of type Pod')
        enodes = cls._get_physical_switches(session, parent)
        enodes.extend(cls._get_virtual_switches(session, parent))
        return enodes
    @staticmethod
    def _get_dn(session, dn):
        mo_query_url = '/api/mo/' + dn + '.json?query-target=self'
        ret = session.get(mo_query_url)
        node_data = ret.json()['imdata']
        return node_data
    @staticmethod
    def _get_dn_children(session, dn):
        mo_query_url = '/api/mo/' + dn + '.json?query-target=children'
        ret = session.get(mo_query_url)
        node_data = ret.json()['imdata']
        return node_data
    def _get_system_info(self, session):
        mo_query_url = '/api/mo/' + self.dn + '.json?query-target=children'
        ret = session.get(mo_query_url)
        node_data = ret.json()['imdata']
        lldp_dn = None
        for node in node_data:
            if 'fabricLooseLink' in node:
                dn = node['fabricLooseLink']['attributes']['portDn']
                name = dn.split('/')
                pod = name[1].split('-')[1]
                node = str(name[2].split('-')[1])
                if 'phys' in name[4]:
                    result = re.search('phys-\[(.+)\]', dn)
                    lldp_dn = 'topology/pod-' + pod + '/node-' + \
                              node + '/sys/lldp/inst/if-[' + result.group(1) + ']/adj-1'
                else:
                    agg_port_data = ExternalSwitch._get_dn(session, dn)
                    if agg_port_data:
                        if 'pcAggrIf' in agg_port_data[0]:
                            port = agg_port_data[0]['pcAggrIf']['attributes']['lastBundleMbr']
                            lldp_dn = 'topology/pod-' + pod + '/node-' + \
                                      node + '/sys/lldp/inst/if-[' + port + ']/adj-1'
            if 'fabricProtLooseLink' in node:
                dn = node['fabricProtLooseLink']['attributes']['portDn']
                name = dn.split('/')
                pod = name[1].split('-')[1]
                node = str(name[2].split('-')[1])
                lldp_dn = 'topology/pod-' + pod + '/node-' + node + '/sys/lldp/inst/if-['
                if dn:
                    link = ExternalSwitch._get_dn_children(session, dn)
                    for child in link:
                        if 'pcRsMbrIfs' in child:
                            port = child['pcRsMbrIfs']['attributes']['tSKey']
                            lldp_dn = lldp_dn + port + ']/adj-1'
        if lldp_dn:
            lldp_data = ExternalSwitch._get_dn(session, lldp_dn)
        else:
            lldp_data = []
        if lldp_data:
            if 'lldpAdjEp' in lldp_data[0]:
                self.ip = str(lldp_data[0]['lldpAdjEp']['attributes']['mgmtIp'])
                self.name = str(lldp_data[0]['lldpAdjEp']['attributes']['sysName'])
                chassis_id_t = lldp_data[0]['lldpAdjEp']['attributes']['chassisIdT']
                if chassis_id_t == 'mac':
                    self.mac = str(lldp_data[0]['lldpAdjEp']['attributes']['chassisIdV'])
                else:
                    self.mac = str(lldp_data[0]['lldpAdjEp']['attributes']['mgmtPortMac'])
        self.state = 'unknown'
    def __eq__(self, other):
        if type(self) is not type(other):
            return False
        return self.name == other.name

class Link(BaseACIPhysObject):
    def __init__(self, pod, link, node1, slot1, port1, node2, slot2, port2, parent=None):
        self.node1 = node1
        self.slot1 = slot1
        self.port1 = port1
        self.node2 = node2
        self.slot2 = slot2
        self.port2 = port2
        self.linkstate = None
        self.linkstatus = None
        self.pod = pod
        self.link = link
        self.descr = None
        if isinstance(parent, str):
            raise TypeError("Parent object can't be a string")
        self.type = 'link'
        self._session = None
        logging.debug('Creating %s %s', self.__class__.__name__,
                      'pod-%s link-%s' % (self.pod, self.link))
        self._common_init(parent)
    @staticmethod
    def get(session, parent_pod=None, node_id=None):
        pod_id = None
        if parent_pod:
            if not isinstance(parent_pod, Pod) and not isinstance(parent_pod, str):
                raise TypeError('An instance of Pod class or a pod number string is required')
            if isinstance(parent_pod, Pod):
                pod_id = parent_pod.pod
            else:
                pod_id = parent_pod
        if not isinstance(session, Session):
            raise TypeError('An instance of Session class is required')
        interface_query_url = '/api/node/class/fabricLink.json?query-target=self'
        if not parent_pod:
            interface_query_url = '/api/node/class/fabricLink.json?query-target=self'
        elif pod_id:
            if node_id:
                interface_query_url = ('/api/node/class/fabricLink.json?'
                                       'query-target=self&query-target-filter=eq(fabricLink.n1,"'
                                       + node_id + '")')
            else:
                interface_query_url = '/api/node/class/fabricLink.json?query-target=self'
        links = []
        ret = session.get(interface_query_url)
        link_data = ret.json()['imdata']
        for apic_link in link_data:
            if 'fabricLink' in apic_link:
                dist_name = str(apic_link['fabricLink']['attributes']['dn'])
                link_n1 = str(apic_link['fabricLink']['attributes']['n1'])
                link_s1 = str(apic_link['fabricLink']['attributes']['s1'])
                link_p1 = str(apic_link['fabricLink']['attributes']['p1'])
                link_n2 = str(apic_link['fabricLink']['attributes']['n2'])
                link_s2 = str(apic_link['fabricLink']['attributes']['s2'])
                link_p2 = str(apic_link['fabricLink']['attributes']['p2'])
                (pod, link) = Link._parse_dn(dist_name)
                link = Link(pod, link, link_n1, link_s1, link_p1, link_n2, link_s2, link_p2)
                link._session = session
                link._populate_from_attributes(apic_link['fabricLink']['attributes'])
                if pod_id:
                    if link.pod == pod_id:
                        if isinstance(parent_pod, Pod):
                            link._parent = parent_pod
                            link._parent.add_child(link)
                        links.append(link)
                else:
                    links.append(link)
        return links
    def _populate_from_attributes(self, attributes):
        self.linkstate = attributes['linkState']
        self.linkstatus = attributes['status']
        self.dn = str(attributes['dn'])
        self.modify_time = str(attributes['modTs'])
    def __str__(self):
        text = 'n%s/s%s/p%s-n%s/s%s/p%s' % (self.node1, self.slot1,
                                            self.port1, self.node2, self.slot2, self.port2)
        return text
    def __eq__(self, other):
        if type(self) is not type(other):
            return False
        return (self.pod == other.pod) and (self.node1 == other.node1) \
               and (self.slot1 == other.slot1) and (self.port1 == other.port1)
    def get_node1(self):
        if not self._parent:
            raise TypeError("Parent pod must be specified in order to get node")
        nodes = self._parent.get_children(Node)
        for node in nodes:
            if node.node == self.node1:
                return node
    def get_node2(self):
        if not self._parent:
            raise TypeError("Parent pod must be specified in order to get node")
        nodes = self._parent.get_children(Node)
        for node in nodes:
            if node.node == self.node2:
                return node
        return None
    def get_slot1(self):
        if not self._parent:
            raise TypeError("Parent pod must be specified in order to get node")
        node = self.get_node1()
        if node:
            linecards = node.get_children(Linecard)
            for linecard in linecards:
                if linecard.slot == self.slot1:
                    return linecard
        return None
    def get_slot2(self):
        if not self._parent:
            raise TypeError("Parent pod must be specified in order to get node")
        node = self.get_node2()
        if node:
            linecards = node.get_children(Linecard)
            for linecard in linecards:
                if linecard.slot == self.slot2:
                    return linecard
        return None
    def get_port1(self):
        if not self._parent:
            raise TypeError("Parent pod must be specified in order to get node")
        linecard = self.get_slot1()
        if linecard:
            interfaces = linecard.get_children(Interface)
            for interface in interfaces:
                if interface.port == self.port1:
                    return interface
        return None
    def get_port2(self):
        if not self._parent:
            raise TypeError(("Parent pod must be specified in "
                             "order to get node"))
        linecard = self.get_slot2()
        if linecard:
            interfaces = linecard.get_children(Interface)
            for interface in interfaces:
                if interface.port == self.port2:
                    return interface
        return None
    def get_port_id1(self):
        return '{0}/{1}/{2}/{3}'.format(self.pod, self.node1, self.slot1, self.port1)
    def get_port_id2(self):
        return '{0}/{1}/{2}/{3}'.format(self.pod, self.node2, self.slot2, self.port2)
    @staticmethod
    def _parse_dn(dn):
        name = dn.split('/')
        pod = str(name[1].split('-')[1])
        link = str(name[2].split('-')[1])
        return pod, link

class Operation(BaseModel):
    id: str
    arguments: List[Argument]
    def __eq__(self, other):
        if isinstance(other, self.__class__):
            return all([
                self.id == other.id,
                self.arguments == other.arguments,
            ])
        else:
            return False
    @staticmethod
    def from_data(data):
        id = data['id']
        arguments = data['arguments']
        return Operation(id=id, arguments=arguments)

class Context(object):
    def __init__(self):
        self.packages = []
        self.rules = []
        self.uses = []
        self._node_map = {}
        self.targets = []
        self.resolver = Resolver()
        self._pkg_map = {}
        self.crcs = {}
        self.src_crcs = {}
        self.old_bldrs = {}
        self.arguments = None
        self._def_args = {}
        self._arg_map = {}
        self.parser = argparse.ArgumentParser('"Use": Software configuration and build.')
        self.parser.add_argument('targets', nargs='*', help='Specify build targets.')
        self.parser.add_argument('-s', dest='show_config', action='store_true', help='Show current configuration.')
        self.new_arguments()('--enable-download-all', dest='download_all', action='boolean', help='Download and install all dependencies.')
    def __eq__(self, op):
        for pkg in self.packages:
            if pkg not in op.packages:
                return False
        for use in self.uses:
            if use not in op.uses:
                return False
        return True
    def __ne__(self, op):
        return not self.__eq__(op)
    def parse_arguments(self):
        for pkg in self.packages:
            pkg.add_arguments(self.parser)
        self.arguments = self.parser.parse_args()
        if 'configure' not in self.arguments.targets and os.path.exists('.use.db'):
            with open('.use.db', 'r') as inf:
                old_ctx = pickle.load(inf)
            for k, v in self.arguments.__dict__.iteritems():
                if v is not None:
                    old_ctx.arguments.__dict__[k] = v
            self.arguments = old_ctx.arguments
        for use in self.uses:
            if use.options is not None:
                use.options.parse(self)
        for rule in self.rules:
            if rule.options is not None:
                rule.options.parse(self)
        for pkg in self.packages:
            pkg.parse_arguments(self.arguments)
    def argument(self, name):
        val = getattr(self.arguments, name, None)
        if val is None:
            return self._def_args.get(name, None)
        return val
    def configure(self):
        if not self.needs_configure():
            self.show_configuration(sys.stdout)
            return
        self.show_configuration(sys.stdout)
        sys.stdout.write('Configuring...\n')
        sys.stdout.write('  Packages to be configured:\n')
        for pkg in self.packages:
            if pkg.explicit:
                sys.stdout.write('    ' + pkg.name + '\n')
        sys.stdout.write('  Installing packages...\n')
        for pkg in self.packages:
            pkg.check_download()
        sys.stdout.write('  Searching for candidates...')
        sys.stdout.flush()
        done = False
        while not done:
            done = True
            for pkg in self.packages:
                if not pkg.search():
                    done = False
        sys.stdout.write(' done.\n')
        sys.stdout.write('  Checking candidates...')
        sys.stdout.flush()
        for pkg in self.packages:
            pkg.check()
        sys.stdout.write(' done.\n')
        if self.resolver is not None:
            sys.stdout.write('  Resolving installations...')
            sys.stdout.flush()
            self.resolver(self)
            sys.stdout.write(' done.\n')
        self.crcs = {}
        self.src_crcs = {}
        self.old_bldrs = {}
        self.save()
        sys.stdout.write('  Success.\n')
        sys.stdout.write('  Configuration details:\n')
        self.write_configuration(sys.stdout, 4)
        sys.stdout.write('\n^^^ Scroll up to see the results of configuring. ^^^\n')
        sys.stdout.write('From here you can:\n')
        sys.stdout.write('  Build:              use\n')
        sys.stdout.write('  Show configuration: use -s\n')
        sys.stdout.write('  Reconfigure:        use configure [options]\n')
        sys.stdout.write('  Show help:          use -h\n')
        sys.exit()
    def needs_configure(self):
        if 'configure' in self.arguments.targets:
            sys.stdout.write('User requested configuration.\n')
            return True
        if not os.path.exists('.use.db'):
            sys.stdout.write('No prior configuration to use.\n')
            return True
        if os.path.exists('.use.db'):
            with open('.use.db', 'r') as inf:
                old_ctx = pickle.load(inf)
        else:
            old_ctx = None
        if self != old_ctx:
            sys.stdout.write('Build structure has changed.\n')
            return True
        self._use_old_ctx(old_ctx)
        for pkg in self.packages:
            if pkg.needs_configure():
                sys.stdout.write(pkg.name + ' has changed.\n')
                return True
        return False
    def find_sources(self):
        for rule in self.rules:
            rule.find_sources(self)
    def expand(self):
        logging.debug('Context: Expanding rules.')
        for rule in self.rules:
            rule.expand(self)
    def scan(self):
        logging.debug('Context: Scanning for dependencies.')
        done = False
        while not done:
            done = True
            for rule in self.rules:
                tmp = rule.scan(self)
                done = tmp if tmp is False else done
        logging.debug('Context: Done scanning for dependencies.')
    def augment(self):
        logging.debug('Context: Beginning augmentation.')
        for use in self.uses:
            if not isinstance(use, Use):
                continue
            deps = use.package.all_dependencies
            if deps and use.parents:
                logging.debug('Context: Augmenting ' + str(use))
                new_use = use
                parents = list(use.parents)
                for dep in deps:
                    logging.debug('Context: Adding ' + dep.name)
                    if len(dep.uses):
                        new_use = new_use + dep.uses[0]
                    else:
                        new_use = new_use + Use(dep, None, use.condition)
                for par in parents:
                    if par.left is use:
                        par.left = new_use
                    else:
                        par.right = new_use
        for rule in self.rules:
            use = rule.use
            if not isinstance(use, Use):
                continue
            deps = use.package.dependencies
            if deps:
                logging.debug('Context: Augmenting ' + str(use))
                new_use = use
                for dep in deps:
                    logging.debug('Context: Adding ' + dep.name)
                    if len(dep.uses):
                        new_use = new_use + dep.uses[0]
                    else:
                        new_use = new_use + Use(dep, None, use.condition)
                rule.use = new_use
        logging.debug('Context: Done augmentation.')
    def find_targets(self):
        logging.debug('Context: Finding targets.')
        self.targets = []
        tgts = set(self.arguments.targets)
        if 'configure' in tgts:
            tgts.remove('configure')
        for tgt in tgts:
            node = self.find_node(tgt)
            if node is not None:
                self.targets.append(node)
        if not self.targets:
            for rule in self.rules:
                for node in rule.product_nodes:
                    if not node.products:
                        self.targets.append(node)
        logging.debug('Context: Found targets: ' + str(self.targets))
        logging.debug('Context: Done finding targets.')
    def build(self):
        logging.debug('Context: Building targets.')
        for tgt in self.targets:
            tgt.build(self)
        self.update_node_crcs()
        self.save()
        logging.debug('Context: Done building targets.')
    def new_arguments(self):
        return Arguments(self)
    def new_options(self, *args, **kwargs):
        return OptionDict(*args, **kwargs)
    def load_package(self, pkg_name, explicit=False):
        pkg_class = load_class(pkg_name)
        if pkg_class not in self._pkg_map:
            pkg = pkg_class(self, explicit)
            self._pkg_map[pkg_class] = pkg
            self.packages.append(pkg)
        else:
            pkg = self._pkg_map[pkg_class]
            pkg.explicit = True if explicit else pkg.explicit
        return pkg
    def new_use(self, pkg_name, opts=None, cond=None, **kwargs):
        pkg = self.load_package(pkg_name, True)
        if opts and kwargs:
            opts = opts + self.new_options(**kwargs)
        elif kwargs:
            opts = self.new_options(**kwargs)
        use = Use(pkg, opts, cond)
        self.uses.append(use)
        return use
    def new_rule(self, src, use, *args, **kwargs):
        opts = self.new_options(**kwargs)
        cond = args[0] if len(args) else None
        rule = Rule(src, use, cond, options=opts)
        self.rules.append(rule)
        return rule
    def package(self, name):
        pkg_class = load_class(name)
        return self._pkg_map[pkg_class]
    def exit(self, save=True):
        if save:
            self.update_node_crcs()
            self.save()
        sys.exit(1)
    def node_crc(self, node):
        return self.crcs.get(repr(node), None)
    def node_source_crcs(self, node):
        return self.src_crcs.get(repr(node), None)
    def update_node_crcs(self):
        for n in self._node_map.itervalues():
            self.update_node_crc(n)
        to_del = [k for k, v in self.crcs.iteritems() if v is None]
        for k in to_del:
            del self.crcs[k]
        to_del = [k for k, v in self.src_crcs.iteritems() if v is None]
        for k in to_del:
            del self.src_crcs[k]
    def update_node_crc(self, node):
        if node.seen:
            self.crcs[repr(node)] = node.current_crc(self)
            self.src_crcs[repr(node)] = node.current_source_crcs(self)
    def save(self):
        parser = self.parser
        targets = self.arguments.targets
        _arg_map = self._arg_map
        del self.parser
        del self._arg_map
        self.arguments.targets = None
        with open('.use.db', 'w') as out:
            pickle.dump(self, out)
        self.parser = parser
        self._arg_map = _arg_map
        self.arguments.targets = targets
    def load(self, base_dir):
        pass
    def _use_old_ctx(self, old_ctx):
        for pkg in self.packages:
            other_pkg = old_ctx._pkg_map[pkg.__class__]
            for ver, other_ver in zip(pkg.versions, other_pkg.versions):
                ver.installations = other_ver.installations
                for inst in ver.installations:
                    inst.version = ver
                    ftr_names = [f.name for f in inst.features]
                    inst.features = []
                    inst._ftr_map = {}
                    for ftr in ver.features:
                        if ftr.name in ftr_names:
                            inst.features.append(ftr)
                            inst._ftr_map[ftr.name] = ftr
        self.crcs = old_ctx.crcs
        self.src_crcs = old_ctx.src_crcs
        self.old_bldrs = old_ctx.old_bldrs
        for rule in old_ctx.rules:
            for n in rule.product_nodes:
                if n.builder is not None:
                    self.old_bldrs[repr(n)] = n.builder
        if self.resolver is not None:
            self.resolver(self)
    def node(self, node_class, *args, **kwargs):
        n = node_class(*args, **kwargs)
        rep = repr(n)
        return self._node_map.setdefault(rep, n)
    def file(self, *args, **kwargs):
        return self.node(File, *args, **kwargs)
    def write_configuration(self, strm, indent=0):
        for pkg in self.packages:
            insts = list(pkg.iter_installations())
            found = len(insts) > 0
            if found and pkg.explicit:
                strm.write(indent*' ' + '%s\n'%pkg.name)
                indent += 2
                if pkg.sub_packages:
                    strm.write(indent*' ' + 'selected package: %s\n'%insts[0].version.package.name)
                if insts[0].location is not None:
                    strm.write(indent*' ' + '%s\n'%insts[0].location.text(indent))
                if insts[0].features:
                    strm.write(indent*' ' + 'features: %s\n'%[f.name for f in insts[0].features])
                indent -= 2
    def show_configuration(self, strm, indent=0):
        if self.arguments.show_config:
            strm.write(indent*' ' + 'Current arguments:\n')
            indent += 2
            for k, v in self.arguments.__dict__.iteritems():
                if k in ['show_config']:
                    continue
                if v is not None and (not isinstance(v, list) or len(v) > 0):
                    arg = self._arg_map.get(k)
                    strm.write(indent*' ' + '{} {}\n'.format(arg.option_strings[0], v))
            indent -= 2
            strm.write('Current configuration:\n')
            self.write_configuration(strm, indent + 2)
            self.exit(False)
    def norm_path(self, path):
        if os.path.isabs(path):
            cwd = os.getcwd()
            if cwd[-1] != '/':
                cwd += '/'
            com = os.path.commonprefix([cwd, path])
            if com == cwd:
                return os.path.relpath(path, cwd)
        return path
    def find_node(self, path):
        path = self.norm_path(path)
        return self._node_map.get(path, None)

class V1Release(object):
    swagger_types = {
        'amount': 'str',
        'denomination': 'str',
        'target_account_id': 'str',
        'internal_account_id': 'str'
    }
    attribute_map = {
        'amount': 'amount',
        'denomination': 'denomination',
        'target_account_id': 'target_account_id',
        'internal_account_id': 'internal_account_id'
    }
    def __init__(self, amount=None, denomination=None, target_account_id=None, internal_account_id=None):  
        self._amount = None
        self._denomination = None
        self._target_account_id = None
        self._internal_account_id = None
        self.discriminator = None
        if amount is not None:
            self.amount = amount
        if denomination is not None:
            self.denomination = denomination
        if target_account_id is not None:
            self.target_account_id = target_account_id
        if internal_account_id is not None:
            self.internal_account_id = internal_account_id
    @property
    def amount(self):
        return self._amount
    @amount.setter
    def amount(self, amount):
        self._amount = amount
    @property
    def denomination(self):
        return self._denomination
    @denomination.setter
    def denomination(self, denomination):
        self._denomination = denomination
    @property
    def target_account_id(self):
        return self._target_account_id
    @target_account_id.setter
    def target_account_id(self, target_account_id):
        self._target_account_id = target_account_id
    @property
    def internal_account_id(self):
        return self._internal_account_id
    @internal_account_id.setter
    def internal_account_id(self, internal_account_id):
        self._internal_account_id = internal_account_id
    def to_dict(self):
        result = {}
        for attr, _ in six.iteritems(self.swagger_types):
            value = getattr(self, attr)
            if isinstance(value, list):
                result[attr] = list(map(
                    lambda x: x.to_dict() if hasattr(x, "to_dict") else x,
                    value
                ))
            elif hasattr(value, "to_dict"):
                result[attr] = value.to_dict()
            elif isinstance(value, dict):
                result[attr] = dict(map(
                    lambda item: (item[0], item[1].to_dict())
                    if hasattr(item[1], "to_dict") else item,
                    value.items()
                ))
            else:
                result[attr] = value
        if issubclass(V1Release, dict):
            for key, value in self.items():
                result[key] = value
        return result
    def to_str(self):
        return pprint.pformat(self.to_dict())
    def __repr__(self):
        return self.to_str()
    def __eq__(self, other):
        if not isinstance(other, V1Release):
            return False
        return self.__dict__ == other.__dict__
    def __ne__(self, other):
        return not self == other

class Tree(metaclass=abc.ABCMeta):
    __slots__ = ["parent", "_metadata", "_label"]
    def __init__(self, label, metadata=None):
        self.parent = None
        self._metadata = Metadata(metadata or {})
        label, idxtype, idx = util.label_and_index(label)
        self._label = label
        if idx is not None:
            self.metadata.index = idx
            self.metadata.idx_type = idxtype
    @abc.abstractmethod
    def __eq__(self, other):
        return self.metadata == other.metadata and \
            self._label == other._label
    def __str__(self):
        import lovett.format
        return self.format(lovett.format.Penn)
    @abc.abstractmethod
    def __repr__(self):
        pass
    def format(self, formatter):
        return "".join((x for x in formatter.node(self, indent=0)))
    def _ipython_display_(self):
        from lovett.ilovett import TreeWidget
        from lovett.format import Json
        display(TreeWidget(self.format(Json)))
    @property
    def label(self):
        return self._label
    @label.setter
    def label(self, new):
        new = new.strip()
        if new == '':
            raise ValueError('Nodes cannot have an empty label.')
        self._label = new
    @property
    def _parent_index(self):
        if self.parent is None:
            return None
        for i, child in enumerate(self.parent):
            if child is self:
                return i
        raise ValueError("Tree not contained in its parent")
    @property
    def left_sibling(self):
        parent_index = self._parent_index
        if self.parent and parent_index > 0:
            return self.parent[parent_index - 1]
        return None
    @property
    def left_siblings(self):
        parent_index = self._parent_index
        if self.parent and parent_index > 0:
            return self.parent[0:parent_index]
        return ()
    @property
    def right_sibling(self):
        parent_index = self._parent_index
        if self.parent and parent_index < len(self.parent) - 1:
            return self.parent[parent_index + 1]
        return None
    @property
    def right_siblings(self):
        parent_index = self._parent_index
        if self.parent and parent_index < len(self.parent) - 1:
            return self.parent[parent_index + 1:]
        return ()
    @property
    def root(self):
        root = self
        while root.parent is not None:
            root = root.parent
        return root
    @property
    def urtext(self):
        r = " ".join(filter(lambda s: s != "", [l.urtext for l in self]))
        r = r.replace("@ @", "")
        r = r.replace(" LOVETT_DEL_SP", "")
        r = r.replace("LOVETT_DEL_SP", "")
        return r.strip()
    @property
    def id(self):
        return self.root.metadata.id
    @abc.abstractmethod
    def nodes(self):
        pass
    def has_label(self, *args):
        if len(args) > 1:
            return self.has_label(args)
        label = args[0]
        if isinstance(label, str):
            return self.label == label or self.label.startswith(label + "-")
        elif hasattr(label, "match"):
            return label.match(self.label) is not None
        else:
            return any((self.has_label(l) for l in list(label)))
    def _has_dash_tag_inner(self, tag):
        return self.label.endswith("-" + tag) or ("-" + tag + "-") in self.label
    def has_dash_tag(self, *tags):
        if len(tags) > 1:
            return self.has_dash_tag(tags)
        tag = tags[0]
        if isinstance(tag, str):
            return self._has_dash_tag_inner(tag)
        return any(self._has_dash_tag_inner(t) for t in tag)
    @property
    def metadata(self):
        return self._metadata
    @metadata.setter
    def metadata(self, new_meta):
        self._metadata = Metadata(new_meta)
    @property
    def word_count(self):
        count = 0
        for node in self:
            count += node.word_count
        return count

class Leaf(Tree):
    __slots__ = ["text"]
    def __init__(self, label, text, metadata=None):
        super(Leaf, self).__init__(label, metadata)
        self.text = text
    def __repr__(self):
        return "Leaf('%s', '%s'%s)" % (self.label.replace("'", "\\'"),
                                       self.text.replace("'", "\\'"),
                                       ", metadata=%r" % self.metadata if self.metadata != {} else "")
    def __eq__(self, other):
        return super(Leaf, self).__eq__(other) and \
            self.text == other.text
    @property
    def urtext(self):
        if not util.means_leaf(self):
            return ""
        if self.label in [",", "."]:
            return "LOVETT_DEL_SP" + self.text
        return self.text
    def nodes(self):
        yield self
    @property
    def word_count(self):
        if util.is_silent(self):
            return 0
        else:
            return 1

class NonTerminal(Tree, collections.abc.MutableSequence):
    __slots__ = ["_children"]
    def __init__(self, label, children, metadata=None):
        super().__init__(label, metadata)
        self._children = list(children)
        for child in self._children:  
            child.parent = self
    def __eq__(self, other):
        return super(NonTerminal, self).__eq__(other) and \
            len(self) == len(other) and \
            all((x == y for x, y in zip(self, other)))
    def __contains__(self, obj):
        return self._children.__contains__(obj)
    def __iter__(self):
        return self._children.__iter__()
    def __len__(self):
        return len(self._children)
    def __getitem__(self, index):
        return self._children[index]
    def __setitem__(self, index, value):
        if isinstance(index, int):
            if not isinstance(value, Tree):
                raise ValueError("Can't place a non-Tree into a Tree: %s" % value)
            value.parent = self
        else:
            for child in value:
                if not isinstance(child, Tree):
                    raise ValueError("Can't place a non-Tree into a Tree: %s" % value)
                child.parent = self
        self._children[index] = value
    def __delitem__(self, index):
        if isinstance(index, int):
            self._children[index].parent = None
        else:
            for child in self._children[index]:  
                child.parent = None
        del self._children[index]
    def insert(self, index, value):
        if not isinstance(value, Tree):
            raise ValueError("Can't place a non-Tree into a Tree: %s" % value)
        value.parent = self
        return self._children.insert(index, value)
    @property
    def children(self):
        return self
    def __repr__(self):
        childstr = ", ".join(repr(c) for c in self)
        return '%s(%r, [%s]%s)' % (type(self).__name__,
                                   self.label,
                                   childstr,
                                   ", metadata=%r" % self.metadata if self.metadata != {} else "")
    def nodes(self):
        yield self
        for child in self:
            yield from child.nodes()

