class PositiveSemidefiniteKernel(object):
  def __init__(self, feature_ndims, dtype=None, name=None):
    if not (isinstance(feature_ndims, int) and feature_ndims > 0):
      raise ValueError(
          '`feature_ndims` must be a Python `integer` greater than zero. ' +
          'Got: {}'.format(feature_ndims))
    self._feature_ndims = feature_ndims
    self._dtype = dtype
    if not name or name[-1] != '/':  
      name = tf.compat.v1.name_scope(name or type(self).__name__).name
    self._name = name
  @property
  def feature_ndims(self):
    return self._feature_ndims
  @property
  def dtype(self):
    return self._dtype
  @property
  def name(self):
    return self._name
  @property
  def batch_shape(self):
    return self._batch_shape()
  def batch_shape_tensor(self):
    with tf.compat.v1.name_scope(self._name):
      if self.batch_shape.is_fully_defined():
        return tf.convert_to_tensor(
            value=self.batch_shape.as_list(),
            dtype=tf.int32,
            name='batch_shape')
      with tf.compat.v1.name_scope('batch_shape_tensor'):
        return self._batch_shape_tensor()
  @contextlib.contextmanager
  def _name_scope(self, name=None, values=None):
    with tf.compat.v1.name_scope(self.name):
      values = [] if values is None else values
      with tf.compat.v1.name_scope(name, values=values) as scope:
        yield scope
  def apply(self, x1, x2):
    with self._name_scope(self._name, values=[x1, x2]):
      x1 = tf.convert_to_tensor(value=x1, name='x1')
      x2 = tf.convert_to_tensor(value=x2, name='x2')
      return self._apply(x1, x2)
  def _apply(self, x1, x2, param_expansion_ndims=0):
    raise NotImplementedError(
        'Subclasses must provide `_apply` implementation.')
  def matrix(self, x1, x2):
    with self._name_scope(self._name, values=[x1, x2]):
      x1 = tf.convert_to_tensor(value=x1, name='x1')
      x2 = tf.convert_to_tensor(value=x2, name='x2')
      x1 = tf.expand_dims(x1, -(self.feature_ndims + 1))
      x2 = tf.expand_dims(x2, -(self.feature_ndims + 2))
      return self._apply(x1, x2, param_expansion_ndims=2)
  def _batch_shape(self):
    raise NotImplementedError('Subclasses must provide batch_shape property.')
  def _batch_shape_tensor(self):
    raise NotImplementedError(
        'Subclasses must provide batch_shape_tensor implementation')
  def __add__(self, k):
    if not isinstance(k, PositiveSemidefiniteKernel):
      raise ValueError(
          "Can't add non-kernel (of type '%s') to kernel" % type(k))
    return _SumKernel([self, k])
  def __iadd__(self, k):
    return self.__add__(k)
  def __mul__(self, k):
    if not isinstance(k, PositiveSemidefiniteKernel):
      raise ValueError(
          "Can't multiply by non-kernel (of type '%s') to kernel" % type(k))
    return _ProductKernel([self, k])
  def __imul__(self, k):
    return self.__mul__(k)
  def __str__(self):
    return ('tfp.positive_semidefinite_kernels.{type_name}('
            '"{self_name}"'
            '{maybe_batch_shape}'
            ', feature_ndims={feature_ndims}'
            ', dtype={dtype})'.format(
                type_name=type(self).__name__,
                self_name=self.name,
                maybe_batch_shape=(', batch_shape={}'.format(self.batch_shape)
                                   if self.batch_shape.ndims is not None
                                   else ''),
                feature_ndims=self.feature_ndims,
                dtype=None if self.dtype is None else self.dtype.name))
  def __repr__(self):
    return ('<tfp.positive_semidefinite_kernels.{type_name} '
            '\'{self_name}\''
            ' batch_shape={batch_shape}'
            ' feature_ndims={feature_ndims}'
            ' dtype={dtype}>'.format(
                type_name=type(self).__name__,
                self_name=self.name,
                batch_shape=self.batch_shape,
                feature_ndims=self.feature_ndims,
                dtype=None if self.dtype is None else self.dtype.name))

class Dataset(Generic[T]):
    def __init__(self, blocks: List[ObjectRef[Block[T]]]):
        self._blocks: List[ObjectRef[Block[T]]] = blocks
    def map(self, fn: Callable[[T], U], compute="tasks",
            **ray_remote_args) -> "Dataset[U]":
        def transform(block: Block[T]) -> Block[U]:
            builder = DelegatingArrowBlockBuilder()
            for row in block.iter_rows():
                builder.add(fn(row))
            return builder.build()
        compute = get_compute(compute)
        return Dataset(compute.apply(transform, ray_remote_args, self._blocks))
    def map_batches(self,
                    fn: Callable[[BatchType], BatchType],
                    batch_size: int = None,
                    compute: str = "tasks",
                    batch_format: str = "pandas",
                    **ray_remote_args) -> "Dataset[Any]":
        raise NotImplementedError  
    def flat_map(self,
                 fn: Callable[[T], Iterator[U]],
                 compute="tasks",
                 **ray_remote_args) -> "Dataset[U]":
        def transform(block: Block[T]) -> Block[U]:
            builder = DelegatingArrowBlockBuilder()
            for row in block.iter_rows():
                for r2 in fn(row):
                    builder.add(r2)
            return builder.build()
        compute = get_compute(compute)
        return Dataset(compute.apply(transform, ray_remote_args, self._blocks))
    def filter(self,
               fn: Callable[[T], bool],
               compute="tasks",
               **ray_remote_args) -> "Dataset[T]":
        def transform(block: Block[T]) -> Block[T]:
            builder = block.builder()
            for row in block.iter_rows():
                if fn(row):
                    builder.add(row)
            return builder.build()
        compute = get_compute(compute)
        return Dataset(compute.apply(transform, ray_remote_args, self._blocks))
    def repartition(self, num_blocks: int) -> "Dataset[T]":
        new_blocks = simple_shuffle(self._blocks, num_blocks)
        return Dataset(new_blocks)
    def sort(self,
             key: Union[str, List[str], Callable[[T], Any]],
             descending: bool = False) -> "Dataset[T]":
        raise NotImplementedError  
    def limit(self, limit: int) -> "Dataset[T]":
        raise NotImplementedError  
    def take(self, limit: int = 20) -> List[T]:
        output = []
        for row in self.to_local_iterator():
            output.append(row)
            if len(output) >= limit:
                break
        return output
    def show(self, limit: int = 20) -> None:
        for row in self.take(limit):
            print(row)
    def count(self) -> int:
        @ray.remote
        def count(block: Block[T]) -> int:
            return block.num_rows()
        return sum(ray.get([count.remote(block) for block in self._blocks]))
    def sum(self) -> int:
        @ray.remote
        def agg(block: Block[T]) -> int:
            return sum(block.iter_rows())
        return sum(ray.get([agg.remote(block) for block in self._blocks]))
    def schema(self) -> Union[type, "pyarrow.lib.Schema"]:
        raise NotImplementedError  
    def num_blocks(self) -> int:
        return len(self._blocks)
    def size_bytes(self) -> int:
        raise NotImplementedError  
    def input_files(self) -> List[str]:
        raise NotImplementedError  
    def write_parquet(path: str,
                      filesystem: Optional["pyarrow.fs.FileSystem"] = None
                      ) -> None:
        raise NotImplementedError  
    def write_json(path: str,
                   filesystem: Optional["pyarrow.fs.FileSystem"] = None
                   ) -> None:
        raise NotImplementedError  
    def write_csv(path: str,
                  filesystem: Optional["pyarrow.fs.FileSystem"] = None
                  ) -> None:
        raise NotImplementedError  
    def to_local_iterator(self) -> Generator:
        for b in self._blocks:
            block = ray.get(b)
            for row in block.iter_rows():
                yield row
    def to_batch_iterators(
            self,
            num_shards: int,
            batch_size: int = None,
            output_location_prefs: List[Any] = None,
            batch_format: str = "pandas",
            repeatable: bool = False) -> List[Iterator[BatchType]]:
        raise NotImplementedError  
    def to_torch(self, **todo) -> "ray.util.sgd.torch.TorchMLDataset":
        raise NotImplementedError  
    def to_tf(self, **todo) -> "ray.util.sgd.tf.TFMLDataset":
        raise NotImplementedError  
    def to_dask(self) -> "dask.DataFrame":
        raise NotImplementedError  
    def to_modin(self) -> "modin.DataFrame":
        raise NotImplementedError  
    def to_pandas(self) -> Iterator[ObjectRef["pandas.DataFrame"]]:
        raise NotImplementedError  
    def to_spark(self) -> "pyspark.sql.DataFrame":
        raise NotImplementedError  
    def __repr__(self) -> str:
        return "Dataset({} blocks)".format(len(self._blocks))
    def __str__(self) -> str:
        return repr(self)
    def _block_sizes(self) -> List[int]:
        @ray.remote
        def query(block: Block[T]) -> int:
            return block.num_rows()
        return ray.get([query.remote(b) for b in self._blocks])

