class _CType:
    def __init__(self, value, endian=None):
        self.value = value
        self.endian = endian
    @classmethod
    def from_buffer(cls, buffer, endian: str = 'little', padding: bytes = None):
        if isinstance(buffer, BytesIO):
            buffer = buffer.read(cls.NBYTES)
        elif isinstance(buffer, socket.socket):
            buffer = buffer.recv(cls.NBYTES)
        if len(buffer) < cls.NBYTES:
            if not padding:
                _bytes = 'bytes' if cls.NBYTES > 1 else 'byte'
                raise BadArgumentException("requires a buffer of %d %s, received %d" % (cls.NBYTES, _bytes, len(buffer)))
            func_padding = bytes.ljust if endian == 'little' else bytes.rjust
            buffer = func_padding(buffer, cls.NBYTES, padding)
        _endian = '<' if endian == 'little' else '>'
        type_struct = cls.TYPE_STRUCT if hasattr(cls, 'TYPE_STRUCT') else cls.TYPE._type_
        value = struct.unpack('%s%s' % (_endian, type_struct), buffer)[0]
        return cls(value, endian)
    def to_bytes(self):
        if isinstance(self.value, (int, bool)):
            type_struct = self.TYPE_STRUCT if hasattr(self, 'TYPE_STRUCT') else self.TYPE._type_
            return struct.pack('%s%s' % ('<' if self.endian == 'little' else '>', type_struct), self.value)
        elif isinstance(self.value, bytes):
            if self.endian == 'little':
                return self.value[::-1]
            return self.value
    def _overflows(self):
        if isinstance(self.value, int):
            try:
                self.value.to_bytes(self.NBYTES, byteorder=self.endian, signed=self.SIGNED)
            except OverflowError as e:
                raise OverflowError("Value \'%d\' does not fit in %s." % (self.value, self.__class__.__name__))
    def __len__(self):
        if isinstance(self.value, bytes):
            return len(self.value)
        if isinstance(self.value, int):
            return len(bytes(self))
        return len(bytes(self.value))
    def __eq__(self, other):
        if isinstance(self.value, int):
            return self.value == other
    def __ne__(self, other):
        if isinstance(other, _CType):
            other = other.value
        if isinstance(self.value, int):
            return self.value != other
    def __and__(self, other):
        if isinstance(other, _CType):
            other = other.value
        if isinstance(self.value, int):
            return self.value & other
        raise NotImplementedError()
    def __lshift__(self, other):
        if isinstance(other, _CType):
            other = other.value
        if isinstance(self.value, int):
            return self.value << other
        raise NotImplementedError()
    def __rshift__(self, other):
        if isinstance(other, _CType):
            other = other.value
        if isinstance(self.value, int):
            return self.value >> other
        raise NotImplementedError()
    def __rlshift__(self, other):
        if isinstance(other, _CType):
            other = other.value
        if isinstance(self.value, int):
            return self.value << other
        raise NotImplementedError()
    def __rrshift__(self, other):
        if isinstance(other, _CType):
            other = other.value
        if isinstance(self.value, int):
            return self.value >> other
        raise NotImplementedError()
    def __or__(self, other):
        if isinstance(other, _CType):
            other = other.value
        if isinstance(self.value, int):
            return self.value | other
        raise NotImplementedError()
    def __mod__(self, other):
        if isinstance(other, _CType):
            other = other.value
        if isinstance(self.value, int):
            return self.value % other
    def __add__(self, other):
        if isinstance(other, _CType):
            other = other.value
        if isinstance(self.value, int):
            return self.value + other
    def __radd__(self, other):
        if isinstance(other, _CType):
            other = other.value
        if isinstance(self.value, int):
            return self.value + other
    def __gt__(self, other):
        if isinstance(other, _CType):
            other = other.value
        if isinstance(self.value, int):
            return self.value > other
    def __lt__(self, other):
        if isinstance(other, _CType):
            other = other.value
        if isinstance(self.value, int):
            return self.value < other
    def __bytes__(self):
        return self.to_bytes()
    def __hash__(self):
        return self.value
    def __int__(self):
        return self.value

class _IntType(_CType):
    def __init__(self, value, endian='little'):
        super(_IntType, self).__init__(value, endian)
        self._overflows()
    def __repr__(self):
        _signed = 'unsigned' if not self.SIGNED else 'signed'
        _bytes = 'bytes' if self.NBYTES > 1 else 'byte'
        _cls_name = self.__class__.__name__
        return '\'%d\' - %s - %s %d %s' % (self.value, _cls_name, _signed, self.NBYTES, _bytes)

class Tax:
    def __init__(self, tax_files: list=None, ncbi_nodes: str=None, ncbi_names: str=None, ncbi_merged: str=None):
        self.nodes = {}
        self.merged = {}
        self.nodes["1"] = ("0", "root", "root")
        if tax_files is not None:
            self.parse(tax_files)
        elif ncbi_nodes is not None:
            self.parse_ncbi_nodes(ncbi_nodes, ncbi_names)
            if ncbi_merged: self.parse_ncbi_merged(ncbi_merged)
    def __repr__(self):
        args = ['{}={}'.format(k, repr(v)) for (k,v) in vars(self).items()]
        return 'Tax({})'.format(', '.join(args))
    def add_nodes(self, new_nodes, label):
        for node,parent in new_nodes.iterrows():
            if node not in self.nodes:
                self.nodes[node] = (parent['taxid'],label,node) 
    def merge(self, extra_tax): 
        for node in extra_tax.nodes:
            if node not in self.nodes: 
                self.nodes[node] = extra_tax.nodes[node]
    def filter(self, filter_nodes):
        new_nodes = {}
        for node in filter_nodes:
            if node in self.nodes: 
                t = node
                while t!="0": 
                    if t in new_nodes: break 
                    new_nodes[t] = self.nodes[t] 
                    t = self.nodes[t][0] 
        self.nodes = new_nodes
    def parse(self, tax_files):
        for tax_file in tax_files:
            with open(tax_file , 'r') as file:
                for line in file:
                    node, parent, rank, name = line.rstrip().split("\t")
                    if node not in self.nodes:
                        self.nodes[node] = (parent,rank,name)
    def parse_ncbi_nodes(self, ncbi_nodes, ncbi_names):
        names = defaultdict(lambda: "")
        if ncbi_names is not None:
            with open(ncbi_names,'r') as file:
                for line in file:
                    node, name, _, name_class = line.split('\t|\t') 
                    if name_class.replace('\t|\n','')=="scientific name":
                        names[node] = name
        with open(ncbi_nodes , 'r') as file:
            for line in file:
                node, parent, rank, _ = line.split('\t|\t', 3) 
                if node not in self.nodes:
                    self.nodes[node] = (parent,rank,names[node])
    def parse_ncbi_merged(self, ncbi_merged):
        self.merged = {}
        with open(ncbi_merged,'r') as file:
            for line in file:
                old_taxid, _, new_taxid, _ = line.split('\t',3)
                self.merged[old_taxid] = new_taxid
    def write(self, file):
        tax_file = open(file,'w')
        for node,(parent, rank, name) in self.nodes.items():
            print(node, parent, rank, name, sep="\t", file=tax_file)
        tax_file.close()
    def get_rank(self, node, rank):
        t = node
        try:
            while self.nodes[t][1]!=rank and t!="1": t = self.nodes[t][0]
        except:
            return node
        return t if t!="1" else node
    def get_node(self, node):
        if node in self.nodes:
            return {"parent": self.nodes[node][0], "rank": self.nodes[node][1], "name": self.nodes[node][2]} 
        else:
            if node in self.merged and self.merged[node] in self.nodes:
                m = self.merged[node]
                return {"parent": self.nodes[m][0], "rank": self.nodes[m][1], "name": self.nodes[m][2]} 
            else:
                return {"parent": "1", "rank": "na", "name": "na"}
    def get_node_rank_fixed(self, node, fixed_ranks):
        n = self.get_node(node)
        rank = n["rank"]
        while node!="0":
            if rank in fixed_ranks:
                return node, rank
            node = n["parent"]
            n = self.get_node(node)
            rank = n["rank"]
        return node, "na"

class SemVer(object):
  def __init__(self, version):
    (self.major, self.minor, self.patch, self.prerelease, self.build) = (
        SemVer._FromString(version))
  @classmethod
  def _FromString(cls, version):
    if version is None:
      raise ParseError('The value is not a valid SemVer string: [None]')
    try:
      match = re.match(_SEMVER, version)
    except (TypeError, re.error) as e:
      raise ParseError('Error parsing version string: [{0}].  {1}'
                       .format(version, e))
    if not match:
      raise ParseError(
          'The value is not a valid SemVer string: [{0}]'.format(version))
    parts = match.groupdict()
    return (
        int(parts['major']), int(parts['minor']), int(parts['patch']),
        parts['prerelease'], parts['build'])
  @classmethod
  def _CmpHelper(cls, x, y):
    return (x > y) - (x < y)
  @classmethod
  def _ComparePrereleaseStrings(cls, s1, s2):
    s1 = s1.split('.') if s1 else []
    s2 = s2.split('.') if s2 else []
    for (this, other) in zip_longest(s1, s2):
      if this is None:
        return 1
      elif other is None:
        return -1
      if this == other:
        continue
      if this.isdigit() and other.isdigit():
        return SemVer._CmpHelper(int(this), int(other))
      return SemVer._CmpHelper(this.lower(), other.lower())
    return 0
  def _Compare(self, other):
    result = SemVer._CmpHelper(
        (self.major, self.minor, self.patch),
        (other.major, other.minor, other.patch))
    result = result or SemVer._ComparePrereleaseStrings(
        self.prerelease, other.prerelease)
    return result
  def Distance(self, other):
    major_diff = self.major - other.major
    minor_diff = self.minor - other.minor
    patch_diff = self.patch - other.patch
    return major_diff, minor_diff, patch_diff
  def __eq__(self, other):
    return other and (
        (self.major, self.minor, self.patch, self.prerelease, self.build) ==
        (other.major, other.minor, other.patch, other.prerelease, other.build))
  def __ne__(self, other):
    return not self == other
  def __gt__(self, other):
    return self._Compare(other) > 0
  def __lt__(self, other):
    return self._Compare(other) < 0
  def __ge__(self, other):
    return not self < other
  def __le__(self, other):
    return not self > other

