class HierarchyLevel:
    paragraph = "paragraph"
    raw_text = "raw_text"
    list_item = "list_item"
    root = "root"
    def __init__(self, level_1: Optional[int], level_2: Optional[int], can_be_multiline: bool, paragraph_type: str):
        assert level_1 is None or level_1 >= 0
        assert level_2 is None or level_2 >= 0
        self.level_1 = level_1
        self.level_2 = level_2
        self.can_be_multiline = can_be_multiline
        self.paragraph_type = paragraph_type
        assert paragraph_type == HierarchyLevel.raw_text or (level_1 is not None and level_2 is not None)
    def __is_defined(self, other: "HierarchyLevel") -> bool:
        return (self.level_1 is not None and
                self.level_2 is not None and
                other.level_1 is not None and
                other.level_2 is not None)
    def __eq__(self, other: "HierarchyLevel") -> bool:
        if self.__is_defined(other) and (self.level_1, self.level_2) == (other.level_1, other.level_2):
            return True
        if self.paragraph_type == HierarchyLevel.raw_text and other.paragraph_type == HierarchyLevel.raw_text:
            return True
        if self.paragraph_type == HierarchyLevel.raw_text and other.paragraph_type != HierarchyLevel.raw_text:
            return False
        if self.paragraph_type != HierarchyLevel.raw_text and other.paragraph_type == HierarchyLevel.raw_text:
            return False
        return False
    def __lt__(self, other: "HierarchyLevel") -> bool:
        if self.__is_defined(other):
            return (self.level_1, self.level_2) < (other.level_1, other.level_2)
        if self.paragraph_type == HierarchyLevel.raw_text and other.paragraph_type == HierarchyLevel.raw_text:
            return False
        if self.paragraph_type == HierarchyLevel.raw_text and other.paragraph_type != HierarchyLevel.raw_text:
            return False
        if self.paragraph_type != HierarchyLevel.raw_text and other.paragraph_type == HierarchyLevel.raw_text:
            return True
        return (self.level_1, self.level_2) < (other.level_1, other.level_2)
    def __str__(self):
        return "HierarchyLevel(level_1={}, level_2={}, can_be_multiline={}, paragraph_type={})".format(
            self.level_1, self.level_2, self.can_be_multiline, self.paragraph_type
        )
    def is_raw_text(self) -> bool:
        return self.paragraph_type == HierarchyLevel.raw_text
    def is_list_item(self) -> bool:
        return self.paragraph_type == HierarchyLevel.list_item
    @staticmethod
    def create_raw_text() -> "HierarchyLevel":
        return HierarchyLevel(level_1=None,
                              level_2=None,
                              can_be_multiline=True,
                              paragraph_type=HierarchyLevel.raw_text)
    @staticmethod
    def create_root() -> "HierarchyLevel":
        return HierarchyLevel(level_1=0, level_2=0, can_be_multiline=True, paragraph_type=HierarchyLevel.root)

class Board(object):
    def __init__(self, client, board_id, name=''):
        self.client = client
        self.id = board_id
        self.name = name
    @classmethod
    def from_json(cls, trello_client, json_obj):
        board = Board(trello_client, json_obj['id'], name=json_obj['name'].encode('utf-8'))
        board.description = json_obj.get('desc', '').encode('utf-8')
        board.closed = json_obj['closed']
        board.url = json_obj['url']
        return board
    def __repr__(self):
        return '<Board %s>' % self.name
    def fetch(self):
        json_obj = self.client.fetch_json('/boards/' + self.id)
        self.name = json_obj['name'].encode('utf-8')
        self.description = json_obj.get('desc', '')
        self.closed = json_obj['closed']
        self.url = json_obj['url']
    def save(self):
        pass
    def close(self):
        self.client.fetch_json(
            '/boards/' + self.id + '/closed',
            http_method='PUT',
            post_args={'value': 'true', }, )
        self.closed = True
    def all_lists(self):
        return self.get_lists('all')
    def open_lists(self):
        return self.get_lists('open')
    def closed_lists(self):
        return self.get_lists('closed')
    def get_lists(self, list_filter):
        json_obj = self.client.fetch_json(
            '/boards/' + self.id + '/lists',
            query_params={'cards': 'none', 'filter': list_filter})
        return [List.from_json(board=self, json_obj=obj) for obj in json_obj]
    def add_list(self, name):
        obj = self.client.fetch_json(
            '/lists',
            http_method='POST',
            post_args={'name': name, 'idBoard': self.id}, )
        return List.from_json(board=self, json_obj=obj)
    def all_cards(self):
        filters = {
            'filter': 'all',
            'fields': 'all'
        }
        return self.get_cards(filters)
    def open_cards(self):
        filters = {
            'filter': 'open',
            'fields': 'all'
        }
        return self.get_cards(filters)
    def closed_cards(self):
        filters = {
            'filter': 'closed',
            'fields': 'all'
        }
        return self.get_cards(filters)
    def get_cards(self, filters=None):
        json_obj = self.client.fetch_json(
            '/boards/' + self.id + '/cards',
            query_params=filters
        )
        cards = list()
        for card_json in json_obj:
            card = Card(self, card_json['id'],
                        name=card_json['name'].encode('utf-8'))
            for card_key, card_val in card_json.iteritems():
                if card_key in ['id', 'name']:
                    continue
                setattr(card, card_key, card_val)
            cards.append(card)
        return cards
    def fetch_actions(self, action_filter):
        json_obj = self.client.fetch_json(
            '/boards/' + self.id + '/actions',
            query_params={'filter': action_filter})
        self.actions = json_obj

