class ColoredText(ColorCodes):
    def __init__(self, code: str, val: str):
        self.code = code
        self.val = val
    def __add__(self, rhs: str) -> str:
        if isinstance(rhs, str):
            return self.code + self.val + self.END + rhs
        elif isinstance(rhs, ColoredText):
            return self.code + self.val + self.END + rhs.code + rhs.val
        else:
            raise TypeError(
                f"Operand '+' is not supported between types {type(self)} and {type(rhs)}."
            )
    def __radd__(self, lhs: str) -> str:
        if isinstance(lhs, str):
            return lhs + f"{self.code}{self.val}{self.END}"
    def __repr__(self) -> str:
        return f"{self.code}{self.val}"
    def __str__(self) -> str:
        return f"{self.code}{self.val}{self.END}"

class Wall:
    def __init__(self, i, j, h=1, w=1, mode=1):
        self.i = i
        self.j = j
        self.h = h
        self.w = w
        self.mode = mode
        self.body = [Vector2D(ii, jj) for ii in range(i, i + h) for jj in range(j, j + w)]
    def is_conflict(self, wall_list):
        if type(wall_list) == Wall:
            if wall_list.i >= self.i + self.h:
                return False
            if wall_list.j >= self.i + self.w:
                return False
            if wall_list.i + wall_list.h <= self.i:
                return False
            if wall_list.j + wall_list.w <= self.j:
                return False
            return True
        if type(wall_list) == list:
            for w in self.body:
                if w in wall_list:
                    return True
            return False
        if type(wall_list) == Vector2D:
            if wall_list.i >= self.i and wall_list.i < self.i + self.h:
                if wall_list.j >= self.j and wall_list.j < self.j + self.w:
                    return True
            return False
    def is_in_game(self):
        if self.i <= 0:
            return False
        if self.i + self.h >= Conf.max_i - 1:
            return False
        if self.j <= 0:
            return False
        if self.j + self.w >= Conf.max_j - 1:
            return False
        return True
    def __repr__(self):
        return '{} {} {} {}, {}'.format(self.i, self.j,
                                        self.h, self.w,
                                        self.body)

