class OPeinRobDuino():
    def __init__(self, port):
        self.port = port
        self.arduino = None
        self.info = {}
        self.serial_write_lock = RLock()
        self.connect()
        logging.info(f"{self} created.")
    def __repr__(self):
        return f"Arduino on {self.port} (id={id(self)})"
    def connect(self):
        if self.arduino is None or not self.arduino.isOpen():
            try:
                self.arduino = serial.Serial(self.port, 9600, timeout = 1)
            except serial.serialutil.SerialException:
                pass
            if self.arduino and self.arduino.isOpen():
                self.arduino.flushInput()
                logging.info(f"Arduino connected on {self.port}")
                return True
            else:
                logging.error(f"Arduino on {self.port} not connected.")
                return False
        else:
            return True
    def send_cells(self, cells_state):
        self.send_order("SC",self.list_to_int(cells_state))
    def send_hauteur(self, index, haut_bas, hauteur ):
        logging.debug(f"send_hauteur : cell n° {index}, seuil {haut_bas}, hauteur = {hauteur}")
        self.send_order("SHS", index, "B" if haut_bas == 'bas' else 'H', hauteur)
        time.sleep(0.5)
    def send_distance_pistolet(self, index, distance ):
        logging.debug(f"send_distance_pistolet : P{index}, distance = {distance}")
        self.send_order("SDP", index, distance)
        time.sleep(0.5)
    def send_init(self):
        logging.debug(f"Init arduino")
        self.send_order("INIT")
        time.sleep(1)
    def send_order(self,order, *args):
        with self.serial_write_lock:
            buf = order
            for arg in args:
                buf += " " + str(arg)
            buf += "\n"
            if self.connect():
                try:
                    self.arduino.write(buf.encode('ascii'))
                except serial.SerialException:
                    logging.error(f"Arduino on {self.port} not connected.")
    @staticmethod
    def list_to_int(l):
        result = 0
        for digit in l:
            result = (result << 1) | digit
        return result
    def _read(self):
        lines = []
        if self.connect():
            try:
                while self.arduino.inWaiting()>0:
                    lines.append(self.arduino.readline())
                return lines
            except OSError:
                logging.error(f"Arduino on {self.port} not connected.")
                self.arduino.close()
        return []
    def ask_info(self):
        self.send_order("INFO")
    def get_info(self):
        return self.info
    def read(self):
        for line in self._read():
            if len(line)>4 and line[:4]==b'INFO':
                liste = line.split(b' ')
                if len(liste) > 2: 
                    info = {}
                    info['hauteur'] = int(liste[1])
                    for p in range(len(liste)-2):
                        info[p] = bool(int(liste[p+2]))
                    self.info = info
                else:
                    logging.debug(f"Arduino : Error on {line}")
            else:
                logging.debug(f"Arduino : {line}")

class Wordform (iWordformMorphology, iWordformPhonology) :
    def __init__(self, lemma=None, ortho=None) :
        self.lemma = lemma
        self.ortho = ortho if ortho else lemma
        self.is_vtmr = False
        self.is_btmr = False
        self.is_opening = False
        self.is_amny = None
        self.is_alternating = False
        self.need_suffix_I = None
    def __repr__(self) :
        return self.ortho
    def cloneAs(self, className) :
        clone = className(self.lemma, self.ortho)
        for key in self.__dict__ :
            setattr(clone, key, self.__dict__[key])
        return clone
    def needSuffixI(self):
        if None != self.need_suffix_I:
            return self.need_suffix_I
        else:
            return Phonology.needSuffixI(self.lemma)
    def appendSuffix(self, suffix) :
        stem = self.cloneAs(self.__class__)
        output_class = self.__class__
        affix = copy.copy(suffix)
        stem.onBeforeSuffixation(affix)
        affix.onBeforeSuffixed(stem)
        interfix_ortho = affix.getInterfix(stem)
        stem.ortho += interfix_ortho + affix.ortho
        affix.onAfterSuffixed(stem)
        return stem
    def onBeforeSuffixation(self, suffix):
        if self.isAlternating() and suffix.isAlternating():
            self.ortho = self.lemma2
        if self.isVTMR() and suffix.isVTMR():
            self.ortho = Phonology.doMR(self.ortho)
        if self.isBTMR() and suffix.isBTMR():
            self.ortho = Phonology.doMR(self.ortho)
        if self.isAMNYLeft() and suffix.isAMNYRight():
            self.ortho = Phonology.doAMNY(self.ortho)
    def isLastVowel(self) :
        return Phonology.isVowel(self.ortho[-1:])
    def isAMNYLeft(self) :
        return self.is_amny if self.is_amny != None else True
    def isAlternating(self) :
        return self.is_alternating
    def needSuffixPhonocode(self) :
        return \
            ('U' if self.needSuffixU() else '-') + \
            ('I' if self.needSuffixI() else '-') + \
            (',O' if self.isOpening() else ',-')
    def isVTMR(self) :
        return self.is_vtmr
    def isBTMR(self) :
        return self.is_btmr
    def attribstr(self):
        return self.needSuffixPhonocode() + \
