class Vec2D():
	def __init__(self,x=None,y=None,r=None,t=None):
		self._pol=False
		self._car=False
		if x!=None and y!=None:
			self.x=x
			self.y=y
			self._car=True
		elif r!=None and t!=None:
			self.r=r
			self.t=t
			self._pol=True
	def car(self):
		if not self._car:
			self._update_car()
		return (self.x,self.y)
	def pol(self):
		if not self._pol:
			self._update_pol()
		return (self.r,self.t)
	def __repr__(self):
		if self._pol:
			return "Vec2D(r="+str(self.r)+", θ="+str(degrees(self.t))+"°)"
		else:
			return "Vec2D(x="+str(self.x)+", y="+str(degrees(self.y))+")"
	def _update_car(self):
		self.x=self.r*np.cos(self.t)
		self.y=self.r*np.sin(self.t)
		self._car=True
	def _update_pol(self):
		self.r=np.sqrt(self.x**2+self.y**2)
		self.t=np.atan2(self.y,self.x)   
		self._pol=True
	def __mul__(self,other):
		if not self._car:
			self._update_car()
		return Vec2D(x=self.x*other,y=self.y*other)
	def __rmul__(self,other):
		if not self._car:
			self._update_car()
		return Vec2D(x=self.x*other,y=self.y*other)
	def __add__(self,other):
		if not self._car:
			self._update_car()
		if not other._car:
			other._update_car()
		return Vec2D(x=self.x+other.x,y=self.y+other.y)
	def __sub__(self,other):
		if not self._car:
			self._update_car()
		if not other._car:
			other._update_car()
		return Vec2D(x=self.x-other.x,y=self.y-other.y)
	def cross(self,other):
		if not self._car:
			self._update_car()
		if not other._car:
			other._update_car()
		return self.x*other.y-self.y-other.x
	def dot(self,other):
		if not self._car:
			self._update_car()
		if not other._car:
			other._update_car()
		return self.x*other.x+self.y*other.y
	def rotate(self,t):
		if not self._pol:
			self._update_pol()
		self.t+=t;
		self._car=False
		self.x=None
		self.y=None

