            order['salt'],  
        ])
    def getZeroExOrderHash(self, order):
        unpacked = [
            self.web3.toChecksumAddress(order['exchangeContractAddress']),  
            self.web3.toChecksumAddress(order['maker']),                    
            self.web3.toChecksumAddress(order['taker']),                    
            self.web3.toChecksumAddress(order['makerTokenAddress']),        
            self.web3.toChecksumAddress(order['takerTokenAddress']),        
            self.web3.toChecksumAddress(order['feeRecipient']),             
            int(order['makerTokenAmount']),             
            int(order['takerTokenAmount']),             
            int(order['makerFee']),                     
            int(order['takerFee']),                     
            int(order['expirationUnixTimestampSec']),   
            int(order['salt']),                         
        ]
        types = [
            'address',  
            'address',  
            'address',  
            'address',  
            'address',  
            'address',  
            'uint256',  
            'uint256',  
            'uint256',  
            'uint256',  
            'uint256',  
            'uint256',  
        ]
        return self.web3.soliditySha3(types, unpacked).hex()
    @staticmethod
    def remove_0x_prefix(value):
        if value[:2] == '0x':
            return value[2:]
        return value
    def getZeroExOrderHashV2(self, order):
        def pad_20_bytes_to_32(twenty_bytes):
            return bytes(12) + twenty_bytes
        def int_to_32_big_endian_bytes(i):
            return i.to_bytes(32, byteorder="big")
        def to_bytes(value):
            if not isinstance(value, str):
                raise TypeError("Value must be an instance of str")
            if len(value) % 2:
                value = "0x0" + self.remove_0x_prefix(value)
            return base64.b16decode(self.remove_0x_prefix(value), casefold=True)
        domain_struct_header = b"\x91\xab=\x17\xe3\xa5\n\x9d\x89\xe6?\xd3\x0b\x92\xbe\x7fS6\xb0;({\xb9Fxz\x83\xa9\xd6*'f\xf0\xf2F\x18\xf4\xc4\xbe\x1eb\xe0&\xfb\x03\x9a \xef\x96\xf4IR\x94\x81}\x10'\xff\xaam\x1fp\xe6\x1e\xad|[\xef\x02x\x16\xa8\x00\xda\x176DO\xb5\x8a\x80~\xf4\xc9`;xHg?~:h\xeb\x14\xa5"
        order_schema_hash = b'w\x05\x01\xf8\x8a&\xed\xe5\xc0J \xef\x87yi\xe9a\xeb\x11\xfc\x13\xb7\x8a\xafAKc=\xa0\xd4\xf8o'
        header = b"\x19\x01"
        domain_struct_hash = self.web3.sha3(
            domain_struct_header +
            pad_20_bytes_to_32(to_bytes(order["exchangeAddress"]))
        )
        order_struct_hash = self.web3.sha3(
            order_schema_hash +
            pad_20_bytes_to_32(to_bytes(order["makerAddress"])) +
            pad_20_bytes_to_32(to_bytes(order["takerAddress"])) +
            pad_20_bytes_to_32(to_bytes(order["feeRecipientAddress"])) +
            pad_20_bytes_to_32(to_bytes(order["senderAddress"])) +
            int_to_32_big_endian_bytes(int(order["makerAssetAmount"])) +
            int_to_32_big_endian_bytes(int(order["takerAssetAmount"])) +
            int_to_32_big_endian_bytes(int(order["makerFee"])) +
            int_to_32_big_endian_bytes(int(order["takerFee"])) +
            int_to_32_big_endian_bytes(int(order["expirationTimeSeconds"])) +
            int_to_32_big_endian_bytes(int(order["salt"])) +
            self.web3.sha3(to_bytes(order["makerAssetData"])) +
            self.web3.sha3(to_bytes(order["takerAssetData"]))
        )
        sha3 = self.web3.sha3(
            header +
            domain_struct_hash +
            order_struct_hash
        )
        return '0x' + base64.b16encode(sha3).decode('ascii').lower()
    def signZeroExOrder(self, order, privateKey):
        orderHash = self.getZeroExOrderHash(order)
        signature = self.signMessage(orderHash[-64:], privateKey)
        return self.extend(order, {
            'orderHash': orderHash,
            'ecSignature': signature,  
        })
    def signZeroExOrderV2(self, order, privateKey):
        orderHash = self.getZeroExOrderHashV2(order)
        signature = self.signMessage(orderHash[-64:], privateKey)
        return self.extend(order, {
            'orderHash': orderHash,
            'signature': self._convertECSignatureToSignatureHex(signature),
        })
    def _convertECSignatureToSignatureHex(self, signature):
        v = signature["v"]
        if v != 27 and v != 28:
            v = v + 27
        return (
            hex(v) +
            signature["r"][-64:] +
            signature["s"][-64:] +
            "03"
        )
    def hashMessage(self, message):
        message_bytes = base64.b16decode(Exchange.encode(Exchange.remove_0x_prefix(message)), True)
        hash_bytes = self.web3.sha3(b"\x19Ethereum Signed Message:\n" + Exchange.encode(str(len(message_bytes))) + message_bytes)
        return '0x' + Exchange.decode(base64.b16encode(hash_bytes)).lower()
    @staticmethod
    def signHash(hash, privateKey):
        signature = Exchange.ecdsa(hash[-64:], privateKey, 'secp256k1', None)
        return {
            'r': '0x' + signature['r'],
            's': '0x' + signature['s'],
            'v': 27 + signature['v'],
        }
    def signMessage(self, message, privateKey):
        message_hash = self.hashMessage(message)
        signature = self.signHash(message_hash[-64:], privateKey[-64:])
        return signature
    def oath(self):
        if self.twofa is not None:
            return self.totp(self.twofa)
        else:
            raise ExchangeError(self.id + ' set .twofa to use this feature')
    @staticmethod
    def decimal_to_bytes(n, endian='big'):
        if n > 0:
            next_byte = Exchange.decimal_to_bytes(n // 256, endian)
            remainder = bytes([n % 256])
            return next_byte + remainder if endian == 'big' else remainder + next_byte
        else:
            return b''
    @staticmethod
    def totp(key):
        def hex_to_dec(n):
            return int(n, base=16)
        def base32_to_bytes(n):
            missing_padding = len(n) % 8
            padding = 8 - missing_padding if missing_padding > 0 else 0
            padded = n.upper() + ('=' * padding)
            return base64.b32decode(padded)  
        epoch = int(time.time()) // 30
        hmac_res = Exchange.hmac(Exchange.decimal_to_bytes(epoch, 'big'), base32_to_bytes(key.replace(' ', '')), hashlib.sha1, 'hex')
        offset = hex_to_dec(hmac_res[-1]) * 2
        otp = str(hex_to_dec(hmac_res[offset: offset + 8]) & 0x7fffffff)
        return otp[-6:]

class Account:
    def __init__(self, name, start_balance=0):
        self.name = name
        self.start_balance = start_balance
        self._transactions = []
    @property
    def balance(self):
        return self.start_balance + sum(self._transactions)
    def __len__(self):
        return len(self._transactions)
    def __add__(self, input):
        if isinstance(input, int):
            self._transactions.append(input)
        else:
            raise ValueError
    def __sub__(self, input):
        if isinstance(input, int):
            self._transactions.append(-input)
        else:
            raise ValueError
    def __gt__(self, other):
        if self.balance > other.balance:
            return True
        else:
            return False
    def __ge__(self, other):
        if self.balance >= other.balance:
            return True
        else:
            return False
    def __lt__(self, other):
        if self.balance < other.balance:
            return True
        else:
            return False
    def __le__(self, other):
        if self.balance <= other.balance:
            return True
        else:
            return False
    def __eq__(self, other):
        if self.balance == other.balance:
            return True
        else:
            return False
    def __str__(self):
        return f"{self.name} account - balance: {self.balance}"
    def __getitem__(self, item):
        return self._transactions[item]

class SwedishHistoricalDate:
    def __init__(self, year, month, day):
        self.year = year
        self.month = month
        self.day = day
        if (year, month, day) >= (1753, 3, 1): 
            self.rd = datetime(year, month, day).toordinal()
        elif (year, month, day) > (1712, 2, 30): 
            assert (year, month, day) < (1753, 2, 18) 
            self.rd = julian2rd(year, month, day)
        elif (year, month, day) > (1700, 2, 28): 
            assert (year, month, day) != (1700, 2, 29) 
            self.rd = swedish2rd(year, month, day)
        else: 
            self.rd = julian2rd(year, month, day)
        assert year > 0
        assert 1 <= month <= 12
        if month == 2:
            feb_len = 28 
            if self.style == "Swedish":
                if year == 1712:
                    feb_len = 30
                elif year == 1700:
                    feb_len = 28
                elif _is_julian_leapyear(year):
                    feb_len = 29
            elif self.style == "Gregorian" and _is_gregorian_leapyear(year):
                    feb_len = 29
            elif self.style == "Julian" and _is_julian_leapyear(year): 
                    feb_len = 29
            assert 1 <= day <= feb_len
        else:
            assert 1 <= day <= MONTH_LEN[month]
        return
    def __add__(self, N):
        return SwedishHistoricalDate.fromordinal(self.rd + N)
    def __sub__(self, N):
        if type(N) == type(self):
            return self.rd - N.rd
        else:
            return SwedishHistoricalDate.fromordinal(self.rd - N)
    def __eq__(self, other):
        if isinstance(other, SwedishHistoricalDate):
            return self.rd == other.rd
        raise NotImplemented
    @classmethod
    def fromordinal(cls, N):
        style = _get_style_from_rd(N)
        if style == "Julian":
            return cls(*rd2julian(N))
        elif style == "Swedish":
            return cls(*rd2swedish(N))
        else:
            assert style == "Gregorian"
            dateobj = datetime.fromordinal(N)
            return cls(dateobj.year, dateobj.month, dateobj.day)
    def toordinal(self):
        return self.rd
    @property
    def tuple(self):
        return (self.year, self.month, self.day)
    @property
    def proleptic_gregorian_tuple(self):
        dateobj = datetime.fromordinal(self.rd)
        return (dateobj.year, dateobj.month, dateobj.day)
    @property
    def style(self):
        if self.rd >= GREGORIAN_START:
            return "Gregorian"
        elif self.rd > SWEDISH_STYLE_END:
            return "Julian"
        elif self.rd >= SWEDISH_STYLE_START:
            return "Swedish"
        else:
            return "Julian"
    def __repr__(self):
        return "<SwedishHistoricalDate({}, {}, {}, style={})>".format(
                self.year, self.month, self.day, self.style)

class Cart:
    def __init__(self):
        self._contents = dict()
    def __repr__(self):
        return "{0} {1}".format(Cart, self.__dict__)
    def process(self, u_order):
        if u_order.add:
            if u_order.item not in self._contents:
                self._contents[u_order.item] = 0
            self._contents[u_order.item] += 1
        elif u_order.delete:
            self._contents[u_order.item] -= 1
            if self._contents[u_order.item] <= 0:
                del self._contents[u_order.item]

class Hook(Command):
    blocking = True
    name: ClassVar[str]
    def __new__(cls, *args, **kwargs):
        if cls is Hook:
            raise TypeError("Hook may not be instantiated directly.")
        return super().__new__(cls)
    def __init_subclass__(cls, **kwargs):
        if not getattr(cls, "name", None):
            cls.name = re.sub('(?!^)([A-Z]+)', r'_\1', cls.__name__.replace("Hook", "")).lower()
        if cls.name in all_hooks:
            other = all_hooks[cls.name]
            raise RuntimeError(f"Two conflicting hooks for {cls.name}: {cls} and {other}")
        all_hooks[cls.name] = cls
        dataclasses.dataclass(cls, repr=False, eq=False)
    def __repr__(self):
        return f"Hook({self.name})"
    def args(self) -> List[Any]:
        args = []
        for field in dataclasses.fields(self):
            args.append(getattr(self, field.name))
        return args

