class Block(object):
    __slots__ = ['items', 'ref_items', '_ref_locs', 'values', 'ndim']
    def __init__(self, values, items, ref_items, ndim=2,
                 do_integrity_check=False):
        if issubclass(values.dtype.type, basestring):
            values = np.array(values, dtype=object)
        assert(values.ndim == ndim)
        assert(len(items) == len(values))
        self.values = values
        self.ndim = ndim
        self.items = _ensure_index(items)
        self.ref_items = _ensure_index(ref_items)
        if do_integrity_check:
            self._check_integrity()
    def _check_integrity(self):
        if len(self.items) < 2:
            return
        return (self.ref_locs[1:] > self.ref_locs[:-1]).all()
    _ref_locs = None
    @property
    def ref_locs(self):
        if self._ref_locs is None:
            indexer = self.ref_items.get_indexer(self.items)
            assert((indexer != -1).all())
            self._ref_locs = indexer
        return self._ref_locs
    def set_ref_items(self, ref_items, maybe_rename=True):
        assert(isinstance(ref_items, Index))
        if maybe_rename:
            self.items = ref_items.take(self.ref_locs)
        self.ref_items = ref_items
    def __repr__(self):
        shape = ' x '.join([str(s) for s in self.shape])
        name = type(self).__name__
        return '%s: %s, %s, dtype %s' % (name, self.items, shape, self.dtype)
    def __contains__(self, item):
        return item in self.items
    def __len__(self):
        return len(self.values)
    def __getstate__(self):
        return (self.items, self.ref_items, self.values)
    def __setstate__(self, state):
        items, ref_items, values = state
        self.items = _ensure_index(items)
        self.ref_items = _ensure_index(ref_items)
        self.values = values
        self.ndim = values.ndim
    @property
    def shape(self):
        return self.values.shape
    @property
    def dtype(self):
        return self.values.dtype
    def copy(self, deep=True):
        values = self.values
        if deep:
            values = values.copy()
        return make_block(values, self.items, self.ref_items)
    def merge(self, other):
        assert(self.ref_items.equals(other.ref_items))
        return _merge_blocks([self, other], self.ref_items)
    def reindex_axis(self, indexer, mask, needs_masking, axis=0):
        if self.values.size > 0:
            new_values = com.take_fast(self.values, indexer, mask,
                                       needs_masking, axis=axis)
        else:
            shape = list(self.shape)
            shape[axis] = len(indexer)
            new_values = np.empty(shape)
            new_values.fill(np.nan)
        return make_block(new_values, self.items, self.ref_items)
    def reindex_items_from(self, new_ref_items, copy=True):
        new_ref_items, indexer = self.items.reindex(new_ref_items)
        if indexer is None:
            new_items = new_ref_items
            new_values = self.values.copy() if copy else self.values
        else:
            mask = indexer != -1
            masked_idx = indexer[mask]
            if self.values.ndim == 2:
                new_values = com.take_2d(self.values, masked_idx, axis=0,
                                         needs_masking=False)
            else:
                new_values = self.values.take(masked_idx, axis=0)
            new_items = self.items.take(masked_idx)
        return make_block(new_values, new_items, new_ref_items)
    def get(self, item):
        loc = self.items.get_loc(item)
        return self.values[loc]
    def set(self, item, value):
        loc = self.items.get_loc(item)
        self.values[loc] = value
    def delete(self, item):
        loc = self.items.get_loc(item)
        new_items = self.items.delete(loc)
        new_values = np.delete(self.values, loc, 0)
        return make_block(new_values, new_items, self.ref_items)
    def split_block_at(self, item):
        loc = self.items.get_loc(item)
        if len(self.items) == 1:
            return None, None
        if loc == 0:
            left_block = None
            right_block = make_block(self.values[1:], self.items[1:].copy(),
                                      self.ref_items)
        elif loc == len(self.values) - 1:
            left_block = make_block(self.values[:-1], self.items[:-1].copy(),
                                    self.ref_items)
            right_block = None
        else:
            left_block = make_block(self.values[:loc],
                                    self.items[:loc].copy(), self.ref_items)
            right_block = make_block(self.values[loc + 1:],
                                     self.items[loc + 1:].copy(), self.ref_items)
        return left_block, right_block
    def fillna(self, value):
        new_values = self.values.copy()
        mask = com.isnull(new_values.ravel())
        new_values.flat[mask] = value
        return make_block(new_values, self.items, self.ref_items)

class BlockManager(object):
    __slots__ = ['axes', 'blocks', 'ndim']
    def __init__(self, blocks, axes, do_integrity_check=True):
        self.axes = [_ensure_index(ax) for ax in axes]
        self.blocks = blocks
        ndim = len(axes)
        for block in blocks:
            assert(ndim == block.values.ndim)
        if do_integrity_check:
            self._verify_integrity()
    @property
    def ndim(self):
        return len(self.axes)
    def is_mixed_dtype(self):
        counts = set()
        for block in self.blocks:
            counts.add(block.dtype)
            if len(counts) > 1:
                return True
        return False
    def set_axis(self, axis, value):
        cur_axis = self.axes[axis]
        if len(value) != len(cur_axis):
            raise Exception('Length mismatch (%d vs %d)'
                            % (len(value), len(cur_axis)))
        self.axes[axis] = _ensure_index(value)
        if axis == 0:
            for block in self.blocks:
                block.set_ref_items(self.items, maybe_rename=True)
    def _get_items(self):
        return self.axes[0]
    items = property(fget=_get_items)
    def set_items_norename(self, value):
        value = _ensure_index(value)
        self.axes[0] = value
        for block in self.blocks:
            block.set_ref_items(value, maybe_rename=False)
    def __getstate__(self):
        block_values = [b.values for b in self.blocks]
        block_items = [b.items for b in self.blocks]
        axes_array = [ax for ax in self.axes]
        return axes_array, block_values, block_items
    def __setstate__(self, state):
        ax_arrays, bvalues, bitems = state[:3]
        self.axes = [_ensure_index(ax) for ax in ax_arrays]
        blocks = []
        for values, items in zip(bvalues, bitems):
            blk = make_block(values, items, self.axes[0],
                             do_integrity_check=True)
            blocks.append(blk)
        self.blocks = blocks
    def __len__(self):
        return len(self.items)
    def __repr__(self):
        output = 'BlockManager'
        for i, ax in enumerate(self.axes):
            if i == 0:
                output += '\nItems: %s' % ax
            else:
                output += '\nAxis %d: %s' % (i, ax)
        for block in self.blocks:
            output += '\n%s' % repr(block)
        return output
    @property
    def shape(self):
        return tuple(len(ax) for ax in self.axes)
    def _verify_integrity(self):
        _union_block_items(self.blocks)
        mgr_shape = self.shape
        for block in self.blocks:
            assert(block.values.shape[1:] == mgr_shape[1:])
        tot_items = sum(len(x.items) for x in self.blocks)
        assert(len(self.items) == tot_items)
    def astype(self, dtype):
        new_blocks = []
        for block in self.blocks:
            newb = make_block(block.values.astype(dtype), block.items,
                              block.ref_items)
            new_blocks.append(newb)
        new_mgr = BlockManager(new_blocks, self.axes)
        return new_mgr.consolidate()
    def is_consolidated(self):
        dtypes = [blk.dtype for blk in self.blocks]
        return len(dtypes) == len(set(dtypes))
    def get_slice(self, slobj, axis=0):
        new_axes = list(self.axes)
        new_axes[axis] = new_axes[axis][slobj]
        if axis == 0:
            new_items = new_axes[0]
            if len(self.blocks) == 1:
                blk = self.blocks[0]
                newb = make_block(blk.values[slobj], new_items,
                                  new_items)
                new_blocks = [newb]
            else:
                return self.reindex_items(new_items)
        else:
            new_blocks = self._slice_blocks(slobj, axis)
        return BlockManager(new_blocks, new_axes, do_integrity_check=False)
    def _slice_blocks(self, slobj, axis):
        new_blocks = []
        slicer = [slice(None, None) for _ in range(self.ndim)]
        slicer[axis] = slobj
        slicer = tuple(slicer)
        for block in self.blocks:
            newb = make_block(block.values[slicer], block.items,
                              block.ref_items)
            new_blocks.append(newb)
        return new_blocks
    def get_series_dict(self):
        return _blocks_to_series_dict(self.blocks, self.axes[1])
    @classmethod
    def from_blocks(cls, blocks, index):
        items = _union_block_items(blocks)
        return BlockManager(blocks, [items, index])
    def __contains__(self, item):
        return item in self.items
    @property
    def nblocks(self):
        return len(self.blocks)
    def copy(self, deep=True):
        copy_blocks = [block.copy(deep=deep) for block in self.blocks]
        copy_axes = list(self.axes)
        return BlockManager(copy_blocks, copy_axes, do_integrity_check=False)
    def as_matrix(self, items=None):
        if len(self.blocks) == 0:
            mat = np.empty(self.shape, dtype=float)
        elif len(self.blocks) == 1:
            blk = self.blocks[0]
            if items is None or blk.items.equals(items):
                mat = blk.values
            else:
                mat = self.reindex_items(items).as_matrix()
        else:
            if items is None:
                mat = self._interleave(self.items)
            else:
                mat = self.reindex_items(items).as_matrix()
        return mat
    def _interleave(self, items):
        dtype = _interleaved_dtype(self.blocks)
        items = _ensure_index(items)
        result = np.empty(self.shape, dtype=dtype)
        itemmask = np.zeros(len(items), dtype=bool)
        for block in self.blocks:
            indexer = items.get_indexer(block.items)
            assert((indexer != -1).all())
            result[indexer] = block.values
            itemmask[indexer] = 1
        assert(itemmask.all())
        return result
    def xs(self, key, axis=1, copy=True):
        assert(axis >= 1)
        loc = self.axes[axis].get_loc(key)
        slicer = [slice(None, None) for _ in range(self.ndim)]
        slicer[axis] = loc
        slicer = tuple(slicer)
        new_axes = list(self.axes)
        if isinstance(loc, (slice, np.ndarray)):
            new_axes[axis] = new_axes[axis][loc]
        else:
            new_axes.pop(axis)
        new_blocks = []
        if len(self.blocks) > 1:
            if not copy:
                raise Exception('cannot get view of mixed-type or '
                                'non-consolidated DataFrame')
            for blk in self.blocks:
                newb = make_block(blk.values[slicer], blk.items, blk.ref_items)
                new_blocks.append(newb)
        elif len(self.blocks) == 1:
            vals = self.blocks[0].values[slicer]
            if copy:
                vals = vals.copy()
            new_blocks = [make_block(vals, self.items, self.items)]
        return BlockManager(new_blocks, new_axes)
    def fast_2d_xs(self, loc, copy=False):
        if len(self.blocks) == 1:
            result = self.blocks[0].values[:, loc]
            if copy:
                result = result.copy()
            return result
        if not copy:
            raise Exception('cannot get view of mixed-type or '
                            'non-consolidated DataFrame')
        dtype = _interleaved_dtype(self.blocks)
        items = self.items
        n = len(items)
        result = np.empty(n, dtype=dtype)
        for blk in self.blocks:
            values = blk.values
            for j, item in enumerate(blk.items):
                i = items.get_loc(item)
                result[i] = values[j, loc]
        return result
    def consolidate(self):
        if self.is_consolidated():
            return self
        new_blocks = _consolidate(self.blocks, self.items)
        return BlockManager(new_blocks, self.axes)
    def get(self, item):
        _, block = self._find_block(item)
        return block.get(item)
    def get_scalar(self, tup):
        item = tup[0]
        _, blk = self._find_block(item)
        item_loc = blk.items.get_loc(item),
        full_loc = item_loc + tuple(ax.get_loc(x)
                                    for ax, x in zip(self.axes[1:], tup[1:]))
        return blk.values[full_loc]
    def delete(self, item):
        i, _ = self._find_block(item)
        loc = self.items.get_loc(item)
        new_items = Index(np.delete(np.asarray(self.items), loc))
        self._delete_from_block(i, item)
        self.set_items_norename(new_items)
    def set(self, item, value):
        if value.ndim == self.ndim - 1:
            value = value.reshape((1,) + value.shape)
        assert(value.shape[1:] == self.shape[1:])
        if item in self.items:
            i, block = self._find_block(item)
            if not block.should_store(value):
                self._delete_from_block(i, item)
                self._add_new_block(item, value)
            else:
                block.set(item, value)
        else:
            self.insert(len(self.items), item, value)
    def insert(self, loc, item, value):
        if item in self.items:
            raise Exception('cannot insert %s, already exists' % item)
        new_items = self.items.insert(loc, item)
        self.set_items_norename(new_items)
        self._add_new_block(item, value)
    def _delete_from_block(self, i, item):
        block = self.blocks.pop(i)
        new_left, new_right = block.split_block_at(item)
        if new_left is not None:
            self.blocks.append(new_left)
        if new_right is not None:
            self.blocks.append(new_right)
    def _add_new_block(self, item, value):
        loc = self.items.get_loc(item)
        new_block = make_block(value, self.items[loc:loc+1].copy(),
                               self.items)
        self.blocks.append(new_block)
    def _find_block(self, item):
        self._check_have(item)
        for i, block in enumerate(self.blocks):
            if item in block:
                return i, block
    def _check_have(self, item):
        if item not in self.items:
            raise KeyError('no item named %s' % str(item))
    def reindex_axis(self, new_axis, method=None, axis=0, copy=True):
        new_axis = _ensure_index(new_axis)
        cur_axis = self.axes[axis]
        if new_axis.equals(cur_axis):
            if copy:
                result = self.copy(deep=True)
                result.axes[axis] = new_axis
                return result
            else:
                return self
        if axis == 0:
            assert(method is None)
            return self.reindex_items(new_axis)
        new_axis, indexer = cur_axis.reindex(new_axis, method)
        return self.reindex_indexer(new_axis, indexer, axis=axis)
    def reindex_indexer(self, new_axis, indexer, axis=1):
        if axis == 0:
            return self._reindex_indexer_items(new_axis, indexer)
        mask = indexer == -1
        needs_masking = len(new_axis) > 0 and mask.any()
        new_blocks = []
        for block in self.blocks:
            newb = block.reindex_axis(indexer, mask, needs_masking,
                                      axis=axis)
            new_blocks.append(newb)
        new_axes = list(self.axes)
        new_axes[axis] = new_axis
        return BlockManager(new_blocks, new_axes)
    def _reindex_indexer_items(self, new_items, indexer):
        item_order = com.take_1d(self.items.values, indexer)
        mask = np.zeros(len(item_order), dtype=bool)
        new_blocks = []
        for blk in self.blocks:
            blk_indexer = blk.items.get_indexer(item_order)
            selector = blk_indexer != -1
            mask |= selector
            if not selector.any():
                continue
            new_block_items = new_items.take(selector.nonzero()[0])
            new_values = com.take_fast(blk.values, blk_indexer[selector],
                                       None, False, axis=0)
            new_blocks.append(make_block(new_values, new_block_items,
                                         new_items))
        if not mask.all():
            na_items = new_items[-mask]
            na_block = self._make_na_block(na_items, new_items)
            new_blocks.append(na_block)
            new_blocks = _consolidate(new_blocks, new_items)
        return BlockManager(new_blocks, [new_items] + self.axes[1:])
    def reindex_items(self, new_items, copy=True):
        new_items = _ensure_index(new_items)
        data = self
        if not data.is_consolidated():
            data = data.consolidate()
            return data.reindex_items(new_items)
        new_items, indexer = self.items.reindex(new_items)
        new_blocks = []
        if indexer is None:
            for blk in self.blocks:
                if copy:
                    new_blocks.append(blk.reindex_items_from(new_items))
                else:
                    new_blocks.append(blk)
        else:
            for block in self.blocks:
                newb = block.reindex_items_from(new_items, copy=copy)
                if len(newb.items) > 0:
                    new_blocks.append(newb)
            mask = indexer == -1
            if mask.any():
                extra_items = new_items[mask]
                na_block = self._make_na_block(extra_items, new_items)
                new_blocks.append(na_block)
                new_blocks = _consolidate(new_blocks, new_items)
        return BlockManager(new_blocks, [new_items] + self.axes[1:])
    def _make_na_block(self, items, ref_items):
        block_shape = list(self.shape)
        block_shape[0] = len(items)
        block_values = np.empty(block_shape, dtype=np.float64)
        block_values.fill(nan)
        na_block = make_block(block_values, items, ref_items,
                              do_integrity_check=True)
        return na_block
    def take(self, indexer, axis=1):
        if axis == 0:
            raise NotImplementedError
        indexer = np.asarray(indexer, dtype='i4')
        n = len(self.axes[axis])
        if ((indexer == -1) | (indexer >= n)).any():
            raise Exception('Indices must be nonzero and less than '
                            'the axis length')
        new_axes = list(self.axes)
        new_axes[axis] = self.axes[axis].take(indexer)
        new_blocks = []
        for blk in self.blocks:
            new_values = com.take_fast(blk.values, indexer,
                                       None, False, axis=axis)
            newb = make_block(new_values, blk.items, self.items)
            new_blocks.append(newb)
        return BlockManager(new_blocks, new_axes)
    def merge(self, other, lsuffix=None, rsuffix=None):
        assert(self._is_indexed_like(other))
        this, other = self._maybe_rename_join(other, lsuffix, rsuffix)
        cons_items = this.items + other.items
        consolidated = _consolidate(this.blocks + other.blocks, cons_items)
        new_axes = list(this.axes)
        new_axes[0] = cons_items
        return BlockManager(consolidated, new_axes)
    def _maybe_rename_join(self, other, lsuffix, rsuffix, exclude=None,
                           copydata=True):
        to_rename = self.items.intersection(other.items)
        if exclude is not None and len(exclude) > 0:
            to_rename = to_rename - exclude
        if len(to_rename) > 0:
            if not lsuffix and not rsuffix:
                raise Exception('columns overlap: %s' % to_rename)
            def lrenamer(x):
                if x in to_rename:
                    return '%s%s' % (x, lsuffix)
                return x
            def rrenamer(x):
                if x in to_rename:
                    return '%s%s' % (x, rsuffix)
                return x
            this = self.rename_items(lrenamer, copydata=copydata)
            other = other.rename_items(rrenamer, copydata=copydata)
        else:
            this = self
        return this, other
    def _is_indexed_like(self, other):
        assert(self.ndim == other.ndim)
        for ax, oax in zip(self.axes[1:], other.axes[1:]):
            if not ax.equals(oax):
                return False
        return True
    def rename_axis(self, mapper, axis=1):
        new_axis = Index([mapper(x) for x in self.axes[axis]])
        new_axis._verify_integrity()
        new_axes = list(self.axes)
        new_axes[axis] = new_axis
        return BlockManager(self.blocks, new_axes)
    def rename_items(self, mapper, copydata=True):
        new_items = Index([mapper(x) for x in self.items])
        new_items._verify_integrity()
        new_blocks = []
        for block in self.blocks:
            newb = block.copy(deep=copydata)
            newb.set_ref_items(new_items, maybe_rename=True)
            new_blocks.append(newb)
        new_axes = list(self.axes)
        new_axes[0] = new_items
        return BlockManager(new_blocks, new_axes)
    def add_prefix(self, prefix):
        f = (('%s' % prefix) + '%s').__mod__
        return self.rename_items(f)
    def add_suffix(self, suffix):
        f = ('%s' + ('%s' % suffix)).__mod__
        return self.rename_items(f)
    def fillna(self, value):
        new_blocks = [b.fillna(value) for b in self.blocks]
        return BlockManager(new_blocks, self.axes)
    @property
    def block_id_vector(self):
        result = np.empty(len(self.items), dtype=int)
        result.fill(-1)
        for i, blk in enumerate(self.blocks):
            indexer = self.items.get_indexer(blk.items)
            assert((indexer != -1).all())
            result.put(indexer, i)
        assert((result >= 0).all())
        return result
    @property
    def item_dtypes(self):
        result = np.empty(len(self.items), dtype='O')
        mask = np.zeros(len(self.items), dtype=bool)
        for i, blk in enumerate(self.blocks):
            indexer = self.items.get_indexer(blk.items)
            result.put(indexer, blk.values.dtype.name)
            mask.put(indexer, 1)
        assert(mask.all())
        return result

class HashableArray( object ):
  def __init__( self, array ):
    self.array = array
    self.quickdata = array.shape, tuple( array.flat[::array.size//32+1] )
  def __hash__( self ):
    return hash( self.quickdata )
  def __eq__( self, other ):
    return isinstance(other,HashableArray) and ( self.array is other.array
      or self.quickdata == other.quickdata and numpy.all( self.array == other.array ) )

class HashableAny( object ):
  def __init__( self, obj ):
    self.obj = obj
  def __hash__( self ):
    return hash( id(self.obj) )
  def __eq__( self, other ):
    return isinstance(other,HashableAny) and self.obj is other.obj

class ScipySparseMat(object):
    @staticmethod
    def convert_vector_to_dense(vec):
        dense_vec = asarray(vec._matrix.todense())
        if vec.shape == (1, 1):
            return dense_vec.reshape(1)
        else:
            return squeeze(dense_vec)
    def __init__(self, num_rows, num_cols, dtype=float, data=None):
        if num_rows == 0 or num_cols == 0:
            self._matrix = None
            self._empty_shape = (num_rows, num_cols)
        else:
            if data is None:
                self._matrix = coo_matrix((num_rows, num_cols), dtype=dtype)
            else:
                self._matrix = coo_matrix(data, shape=(num_rows, num_cols),
                                          dtype=dtype)
                self.convert('csr')
                self._matrix.eliminate_zeros()
    def _is_empty(self):
        return self._matrix is None
    is_empty = property(_is_empty)
    def _get_shape(self):
        if self.is_empty:
            return self._empty_shape
        else:
            return self._matrix.shape
    shape = property(_get_shape)
    def _get_dtype(self):
        if self.is_empty:
            return None
        else:
            return self._matrix.dtype
    dtype = property(_get_dtype)
    def _get_format(self):
        if self.is_empty:
            return None
        else:
            return self._matrix.getformat()
    fmt = property(_get_format)
    def _get_size(self):
        if self.is_empty:
            return 0
        else:
            return self._matrix.nnz
    size = property(_get_size)
    def convert(self, fmt=None):
        if not self.is_empty:
            self._matrix = self._matrix.asformat(fmt)
    def transpose(self):
        transposed = self.__class__(self.shape[1], self.shape[0],
                                    dtype=self.dtype)
        if not self.is_empty:
            if self.fmt == 'lil':
                self.convert('csr')
            transposed._matrix = self._matrix.transpose(copy=True)
        return transposed
    T = property(transpose)
    def sum(self, axis=None):
        if self.is_empty:
            matrix_sum = 0
        else:
            matrix_sum = squeeze(asarray(self._matrix.sum(axis=axis)))
            if axis is not None and matrix_sum.shape == ():
                matrix_sum = matrix_sum.reshape(1)
        return matrix_sum
    def get_row(self, row_idx):
        if self.is_empty:
            raise IndexError("Cannot retrieve a row from an "
                             "empty/null matrix.")
        num_rows, num_cols = self.shape
        if row_idx >= num_rows or row_idx < 0:
            raise IndexError("Row index %d is out of bounds." % row_idx)
        self.convert('csr')
        row_vector = self.__class__(1, num_cols, dtype=self.dtype)
        row_vector._matrix = self._matrix.getrow(row_idx)
        return row_vector
    def get_col(self, col_idx):
        if self.is_empty:
            raise IndexError("Cannot retrieve a column from an empty/null "
                             "matrix.")
        num_rows, num_cols = self.shape
        if col_idx >= num_cols or col_idx < 0:
            raise IndexError("Column index %d is out of bounds." % col_idx)
        self.convert('csc')
        col_vector = self.__class__(num_rows, 1, dtype=self.dtype)
        col_vector._matrix = self._matrix.getcol(col_idx)
        return col_vector
    def items(self):
        return list(self.iteritems())
    def iteritems(self):
        if not self.is_empty:
            self.convert('coo')
            for r, c, v in izip(self._matrix.row, self._matrix.col,
                                self._matrix.data):
                yield (r, c), v
    def copy(self):
        new_self = self.__class__(*self.shape, dtype=self.dtype)
        if not self.is_empty:
            new_self._matrix = self._matrix.copy()
        return new_self
    def __eq__(self, other):
        if not isinstance(other, self.__class__):
            return False
        if self.shape != other.shape:
            return False
        if self.dtype != other.dtype:
            return False
        if self.size != other.size:
            return False
        if not self.is_empty:
            self.convert('csr')
            other.convert('csr')
            if abs(self._matrix - other._matrix).nnz > 0:
                return False
        return True
    def __ne__(self, other):
        return not (self == other)
    def __str__(self):
        if self.is_empty:
            return '<%dx%d empty/null sparse matrix>' % self.shape
        else:
            return str(self._matrix)
    def __setitem__(self, args, value):
        if self.is_empty:
            raise IndexError("Cannot set an element on an empty/null matrix.")
        try:
            row, col = args
        except:
            raise IndexError("Must specify the row and column of the element "
                             "to be set.")
        self.convert('lil')
        if value == 0:
            if self._matrix[row, col] != 0:
                raise ValueError("Cannot set an existing non-zero element to "
                                 "zero.")
        else:
            self._matrix[row, col] = value
    def __getitem__(self, args):
        if self.is_empty:
            raise IndexError("Cannot retrieve an element from an empty/null "
                             "matrix.")
        try:
            row, col = args
        except:
            raise IndexError("Must specify (row, col).")
        if isinstance(row, slice) and isinstance(col, slice):
            raise IndexError("Can only slice a single axis.")
        if isinstance(row, slice):
            if row.start is None and row.stop is None:
                return self.get_col(col)
            else:
                raise IndexError("Can only handle full : slices per axis.")
        elif isinstance(col, slice):
            if col.start is None and col.stop is None:
                return self.get_row(row)
            else:
                raise IndexError("Can only handle full : slices per axis.")
        else:
            if self.fmt == 'coo':
                self.convert('csr')
            return self._matrix[row, col]

class Mesure:
    def __init__(self, amplitude, position, typeDomaine='segment'):
        if len(amplitude) != len(position):
            raise ValueError('Pas le même nombre')
        self.a = amplitude
        self.x = position
        self.N = len(amplitude)
        self.Xtype = typeDomaine
    def __add__(self, m):
        return Mesure(self.a + m.a, self.x + m.x)
    def __eq__(self, m):
        if m == 0 and (self.a == [] and self.x == []):
            return True
        elif isinstance(m, self.__class__):
            return self.__dict__ == m.__dict__
        else:
            return False
    def __ne__(self, m):
        return not self.__eq__(m)
    def __str__(self):
        amplitudes = np.round(self.a, 2)
        positions = np.round(self.x, 2)
        return(f'Amplitude : {amplitudes} --- Position : {positions}')
    def graphe(self):
        plt.figure()
        plt.plot(X,y, label='$y_0$')
        plt.stem(self.x, self.a, label='$m_{a,x}$', linefmt='C1--', 
                  markerfmt='C1o', use_line_collection=True, basefmt=" ")
        plt.grid()
        return
    def torus(self, current_fig=False, subplot=False):
        if subplot == True:
            ax = fig.add_subplot(224, projection='3d')
        else:
            current_fig = plt.figure()
            ax = current_fig.add_subplot(111, projection='3d')
        theta = np.linspace(0, 2*np.pi, N_ech)
        y_torus = np.sin(theta)
        x_torus = np.cos(theta)
        a_x_torus = np.sin(2*np.pi*np.array(self.x))
        a_y_torus = np.cos(2*np.pi*np.array(self.x))
        a_z_torus = self.a
        ax.plot(x_torus,y_torus, 0, '-k', label='$\mathbb{S}_1$')
        ax.plot(a_x_torus,a_y_torus, a_z_torus,
                'o', label='$m_{a,x}$', color='orange')
        for i in range(self.N):
            ax.plot((a_x_torus[i],a_x_torus[i]),(a_y_torus[i],a_y_torus[i]),
                    (0,a_z_torus[i]), '--r', color='orange')
        ax.set_xlabel('$X$')
        ax.set_ylabel('$Y$')
        ax.set_zlabel('$Amplitude$')
        ax.set_title('Mesure sur $\mathbb{S}_1$', fontsize=20)
        ax.legend()
        return 
    def kernel(self, X, noyau='gaussien'):
        N = self.N
        x = self.x
        a = self.a
        acquis = X*0
        if noyau == 'gaussien':
            for i in range(0,N):
                acquis += a[i] * gaussienne(X - x[i])
            return acquis
        elif noyau == 'double_gaussien':
            for i in range(0,N):
                acquis += a[i] * double_gaussienne(X - x[i])
            return acquis
        elif noyau == 'fourier':
            a = np.array(a)
            acquis = fourier_measurements(x, F_C) @ a
            return acquis
        else:
            raise TypeError("Unknown kernel")
    def acquisition(self, nv, noyau='gaussien'):
        acquis = self.kernel(X, noyau=noyau)
        if nv == 0:
            return acquis
        if noyau == 'fourier':
            w = np.fft.fft(np.random.randn(acquis.shape[0]))
            w = np.fft.fftshift(w)
            w /= np.linalg.norm(w)
            acquis += nv * w
            return acquis
        if noyau == 'gaussien':
            w = nv*np.random.random_sample((N_ech))
            acquis += w
            return acquis
        else:
            raise TypeError("Unknown kernel")
    def tv(self):
        return np.linalg.norm(self.a, 1)
    def energie(self, X, acquis, regul, noyau='gaussien'):
        attache = 0.5*np.linalg.norm(acquis - self.kernel(X, noyau=noyau))/len(acquis)
        parcimonie = regul*self.tv()
        return(attache + parcimonie)
    def prune(self, tol=1e-3):
        nnz_a = np.array(self.a)
        nnz = np.abs(nnz_a) > tol
        nnz_a = nnz_a[nnz]
        nnz_x = np.array(self.x)
        nnz_x = nnz_x[nnz]
        m = Mesure(nnz_a.tolist(), nnz_x.tolist())
        return m
    def deltaSeparation(self):
        diff = np.inf
        if self.Xtype == 'segment':
            for i in range(self.N-1): 
