class Column(Generic[T]):
    name: str
    _data_backend: B
    loc: Column._LocIndexer[T]
    iloc: Column._ILocIndexer[T]
    dtype: DataType
    @classmethod
    def __class_getitem__(_, dtype: T) -> Type[Column]:
        from .column_alias import ColumnAlias
        return ColumnAlias(dtype)
    def __init__(
        self: Column[T],
        name: str,
        data: Optional[list[T]] = None,
        index: Optional[list] = None,
        dtype: Optional[T] = None,
    ) -> None:
        self.name = name
        if data is not None:
            if issubclass(type(data), DataBackend):
                self._data_backend = data
            else:
                self._data_backend = PandasBackend({name: data}, index=index)
            self.dtype = (
                self.infer_dtype(self.name, self._data_backend)
                if dtype is None
                else DataType(dtype)
            )
        else:
            self._data_backend = PandasBackend(index=index)
            self.dtype = Object
        if data is not None:
            self._validate_column()
            self.loc = Column._LocIndexer[T](self)
            self.iloc = Column._ILocIndexer[T](self)
    @staticmethod
    def determine_nested_dtype(data: Iterable) -> DataType:
        if len(data) == 0:
            return Object
        sample = next(iter(data))
        stype = type(sample)
        if sample == data:
            return type(data)
        elif stype is list or stype is set:
            nested_type = Column.determine_nested_dtype(sample)
        else:
            nested_type = stype
        return GenericAlias(type(data), nested_type)
    @staticmethod
    def infer_dtype(column_name: str, data_backend: DataBackend) -> DataType:
        dtype: type = data_backend.dtypes[column_name]
        if dtype == Object:
            if len(data_backend) == 0:
                dtype = Object
            else:
                sample = data_backend.iloc[0].values[0]
                stype = type(sample)
                if stype is list or stype is set:
                    dtype = DataType(
                        GenericAlias(stype, Column.determine_nested_dtype(sample))
                    )
                else:
                    dtype = stype
        return DataType(dtype)
    def _validate_column(self: Column[T]) -> None:
        if self._data_backend.is_link() or isinstance(self.dtype, TypeAlias):
            return
        data_type = self.infer_dtype(self.name, self._data_backend)
        if self.dtype != data_type:
            try:
                self._data_backend = self._data_backend.cast_columns(
                    {self.name: self.dtype.pdtype()}
                )
            except Exception as e:
                raise TypeError(
                    f"Failed to cast '{data_type.__name__}' to '{self.dtype.__name__}'",
                    e,
                )
    @property
    def index(self: Column[T]) -> Index:
        return self._data_backend.index
    def tolist(self: Column[T]) -> list:
        return self._data_backend.values.tolist()
    @property
    def values(self: Column[T]) -> np.ndarray:
        return self._data_backend.values
    @classmethod
    def _new_data_copy(
        cls: type[Column], name: str, data_backend: DataBackend, dtype: type[NT]
    ) -> "Column[NT]":
        instance: Column[dtype] = cls(name)
        instance._data_backend = data_backend
        instance.dtype = DataType(dtype)
        return instance
    def astype(self: Column[T], new_dtype: type[NT]) -> "Column[NT]":
        return Column(
            self.name,
            self._data_backend.cast_columns({self.name: new_dtype}),
            dtype=new_dtype,
        )
    def first(
        self: Column[T], n: Optional[int] = 1, offset: Optional[int] = 0
    ) -> Column[T]:
        return Column(
            self.name,
            self._data_backend.iloc[self.index[offset : offset + n]],
            dtype=self.dtype,
        )
    def nunique(self) -> int:
        return self._data_backend.nunique()[self.name]
    def equals(self: Column[T], other: Any) -> bool:
        if type(other) is Column:
            return self._data_backend.equals(cast(Column, other)._data_backend)
        else:
            return self._data_backend.equals(other)
    def __eq__(self: Column[T], other: Any) -> Column[Boolean]:
        if isinstance(other, Column):
            other = other._data_backend
        return self._data_backend == other
    def __ne__(self: Column[T], other: Any) -> bool:
        if isinstance(other, Column):
            other = other._data_backend
        return self._data_backend != other
    def __gt__(self: Column[T], other: Any) -> bool:
        if isinstance(other, Column):
            other = other._data_backend
        return self._data_backend > other
    def __ge__(self: Column[T], other: Any) -> bool:
        if isinstance(other, Column):
            other = other._data_backend
        return self._data_backend >= other
    def __lt__(self: Column[T], other: Any) -> bool:
        if isinstance(other, Column):
            other = other._data_backend
        return self._data_backend < other
    def __le__(self: Column[T], other: Any) -> bool:
        if isinstance(other, Column):
            other = other._data_backend
        return self._data_backend <= other
    def __len__(self: Column[T]):
        return len(self._data_backend)
    def __iter__(self: Column[T]) -> Iterator[T]:
        return self._data_backend.itertuples()
    def item(self) -> Any:
        if len(self) > 1:
            raise RuntimeError("Cannot call `item` on list of column values")
        return self.values[0]
    def __getitem__(self: Column[T], indexable: Indexible) -> Column[T]:
        return self.loc[indexable]
    def __str__(self: Column[T]) -> str:
        result = f"Column {self.name}"
        if len(self._data_backend) == 0:
            return f"{result}([], dtype: {self.dtype.__name__})"
        else:
            return str(self._data_backend)
    def __repr__(self: Column[T]) -> str:
        return str(self)
    class _ILocIndexer(Generic[T]):
        _column: Column[T]
        def __init__(self, column: Column[T]) -> None:
            self._column = column
        def __getitem__(self, item: Union[int, list, slice]) -> Column[T]:
            data = self._column._data_backend.iloc[item]
            return Column._new_data_copy(self._column.name, data, self._column.dtype)
    class _LocIndexer(Generic[T]):
        _column: Column[T]
        def __init__(self, column: Column[T]) -> None:
            self._column = column
        def __getitem__(self, item: Union[Any, list, slice]) -> Column[T]:
            data = self._column._data_backend.loc[item]
            return Column._new_data_copy(self._column.name, data, self._column.dtype)

class MarathonClients(object):
    def __init__(self, current: List[MarathonClient], previous: List[MarathonClient]) -> None:
        self.current = current
        self.previous = previous
    def __repr__(self) -> str:
        return f'MarathonClients(current={self.current!r}, previous={self.previous!r}'
    def get_current_client_for_service(self, job_config: 'MarathonServiceConfig') -> MarathonClient:
        service_instance = compose_job_id(job_config.service, job_config.instance)
        if job_config.get_marathon_shard() is not None:
            return self.current[job_config.get_marathon_shard()]
        else:
            return rendezvous_hash(choices=self.current, key=service_instance)
    def get_previous_clients_for_service(self, job_config: 'MarathonServiceConfig') -> Sequence[MarathonClient]:
        service_instance = compose_job_id(job_config.service, job_config.instance)
        if job_config.get_previous_marathon_shards() is not None:
            return [self.previous[i] for i in job_config.get_previous_marathon_shards()]
        else:
            try:
                return [rendezvous_hash(choices=self.previous, key=service_instance)]
            except ValueError:
                return []
    def get_all_clients_for_service(self, job_config: 'MarathonServiceConfig') -> Sequence[MarathonClient]:
        all_clients = [self.get_current_client_for_service(job_config)]
        all_clients.extend(self.get_previous_clients_for_service(job_config))
        return dedupe_clients(all_clients)
    def get_all_clients(self) -> List[MarathonClient]:
        return dedupe_clients(self.current + self.previous)

class Account:
    def __init__(self, owner, amount=0):
        self.owner = owner
        self.amount = amount
        self._transactions = []
    def __add__(self, other):
        account = Account(f'{self.owner}&{other.owner}', self.amount + other.amount)
        account._transactions = self._transactions + other._transactions
        return account
    def __str__(self):
        return f"{__class__.__name__} of {self.owner} with starting amount: {self.amount}"
    def __repr__(self):
        return f"{__class__.__name__}({self.owner}, {self.amount})"
    def __len__(self):
        return len(self._transactions)
    def __getitem__(self, index):
        return self._transactions[index]
    def __reversed__(self):
        return reversed(self._transactions)
    def __eq__(self, other):
        return self.balance == other.balance
    def __gt__(self, other):
        return self.balance > other.balance
    def __ge__(self, other):
        return self.balance >= other.balance
    def add_transaction(self, amount):
        if not isinstance(amount, int):
            raise ValueError('please use int for amount')
        self._transactions.append(amount)
    @property
    def balance(self):
        return self.amount + sum(self._transactions)
    @staticmethod
    def validate_transaction(account, amount_to_add):
        if account.amount + amount_to_add < 0:
            raise ValueError("sorry cannot go in debt!")
        account._transactions.append(amount_to_add)
        return f"New balance: {account.balance}"

class V1MatrixRange(object):
    openapi_types = {"kind": "object"}
    attribute_map = {"kind": "kind"}
    def __init__(self, kind=None, local_vars_configuration=None):  
        if local_vars_configuration is None:
            local_vars_configuration = Configuration()
        self.local_vars_configuration = local_vars_configuration
        self._kind = None
        self.discriminator = None
        if kind is not None:
            self.kind = kind
    @property
    def kind(self):
        return self._kind
    @kind.setter
    def kind(self, kind):
        self._kind = kind
    def to_dict(self):
        result = {}
        for attr, _ in six.iteritems(self.openapi_types):
            value = getattr(self, attr)
            if isinstance(value, list):
                result[attr] = list(
                    map(lambda x: x.to_dict() if hasattr(x, "to_dict") else x, value)
                )
            elif hasattr(value, "to_dict"):
                result[attr] = value.to_dict()
            elif isinstance(value, dict):
                result[attr] = dict(
                    map(
                        lambda item: (item[0], item[1].to_dict())
                        if hasattr(item[1], "to_dict")
                        else item,
                        value.items(),
                    )
                )
            else:
                result[attr] = value
        return result
    def to_str(self):
        return pprint.pformat(self.to_dict())
    def __repr__(self):
        return self.to_str()
    def __eq__(self, other):
        if not isinstance(other, V1MatrixRange):
            return False
        return self.to_dict() == other.to_dict()
    def __ne__(self, other):
        if not isinstance(other, V1MatrixRange):
            return True
        return self.to_dict() != other.to_dict()

class Resize(object):
    def __init__(self,
                 img_scale=None,
                 multiscale_mode='range',
                 ratio_range=None,
                 keep_ratio=True):
        if img_scale is None:
            self.img_scale = None
        else:
            if isinstance(img_scale, list):
                self.img_scale = img_scale
            else:
                self.img_scale = [img_scale]
            assert mmcv.is_list_of(self.img_scale, tuple)
        if ratio_range is not None:
            assert len(self.img_scale) == 1
        else:
            assert multiscale_mode in ['value', 'range']
        self.multiscale_mode = multiscale_mode
        self.ratio_range = ratio_range
        self.keep_ratio = keep_ratio
    @staticmethod
    def random_select(img_scales):
        assert mmcv.is_list_of(img_scales, tuple)
        scale_idx = np.random.randint(len(img_scales))
        img_scale = img_scales[scale_idx]
        return img_scale, scale_idx
    @staticmethod
    def random_sample(img_scales):
        assert mmcv.is_list_of(img_scales, tuple) and len(img_scales) == 2
        img_scale_long = [max(s) for s in img_scales]
        img_scale_short = [min(s) for s in img_scales]
        long_edge = np.random.randint(
            min(img_scale_long),
            max(img_scale_long) + 1)
        short_edge = np.random.randint(
            min(img_scale_short),
            max(img_scale_short) + 1)
        img_scale = (long_edge, short_edge)
        return img_scale, None
    @staticmethod
    def random_sample_ratio(img_scale, ratio_range):
        assert isinstance(img_scale, tuple) and len(img_scale) == 2
        min_ratio, max_ratio = ratio_range
        assert min_ratio <= max_ratio
        ratio = np.random.random_sample() * (max_ratio - min_ratio) + min_ratio
        scale = int(img_scale[0] * ratio), int(img_scale[1] * ratio)
        return scale, None
    def _random_scale(self, results):
        if self.ratio_range is not None:
            scale, scale_idx = self.random_sample_ratio(
                self.img_scale[0], self.ratio_range)
        elif len(self.img_scale) == 1:
            scale, scale_idx = self.img_scale[0], 0
        elif self.multiscale_mode == 'range':
            scale, scale_idx = self.random_sample(self.img_scale)
        elif self.multiscale_mode == 'value':
            scale, scale_idx = self.random_select(self.img_scale)
        else:
            raise NotImplementedError
        results['scale'] = scale
        results['scale_idx'] = scale_idx
    def _resize_img(self, results):
        if self.keep_ratio:
            img, scale_factor = mmcv.imrescale(
                results['img'], results['scale'], return_scale=True)
        else:
            img, w_scale, h_scale = mmcv.imresize(
                results['img'], results['scale'], return_scale=True)
            scale_factor = np.array([w_scale, h_scale, w_scale, h_scale],
                                    dtype=np.float32)
        results['img'] = img
        results['img_shape'] = img.shape
        results['pad_shape'] = img.shape  
        results['scale_factor'] = scale_factor
        results['keep_ratio'] = self.keep_ratio
    def _resize_bboxes(self, results):
        img_shape = results['img_shape']
        for key in results.get('bbox_fields', []):
            bboxes = results[key] * results['scale_factor']
            bboxes[:, 0::2] = np.clip(bboxes[:, 0::2], 0, img_shape[1] - 1)
            bboxes[:, 1::2] = np.clip(bboxes[:, 1::2], 0, img_shape[0] - 1)
            results[key] = bboxes
    def _resize_masks(self, results):
        for key in results.get('mask_fields', []):
            if results[key] is None:
                continue
            if self.keep_ratio:
                masks = [
                    mmcv.imrescale(
                        mask, results['scale_factor'], interpolation='nearest')
                    for mask in results[key]
                ]
            else:
                mask_size = (results['img_shape'][1], results['img_shape'][0])
                masks = [
                    mmcv.imresize(mask, mask_size, interpolation='nearest')
                    for mask in results[key]
                ]
            results[key] = np.stack(masks)
    def _resize_seg(self, results):
        for key in results.get('seg_fields', []):
            if self.keep_ratio:
                gt_seg = mmcv.imrescale(
                    results[key], results['scale'], interpolation='nearest')
            else:
                gt_seg = mmcv.imresize(
                    results[key], results['scale'], interpolation='nearest')
            results['gt_semantic_seg'] = gt_seg
    def __call__(self, results):
        if 'scale' not in results:
            self._random_scale(results)
        self._resize_img(results)
        self._resize_bboxes(results)
        self._resize_masks(results)
        self._resize_seg(results)
        return results
    def __repr__(self):
        repr_str = self.__class__.__name__
        repr_str += ('(img_scale={}, multiscale_mode={}, ratio_range={}, '
                     'keep_ratio={})').format(self.img_scale,
                                              self.multiscale_mode,
                                              self.ratio_range,
                                              self.keep_ratio)
        return repr_str

class RandomFlip(object):
    def __init__(self, flip_ratio=None, direction='horizontal'):
        self.flip_ratio = flip_ratio
        self.direction = direction
        if flip_ratio is not None:
            assert flip_ratio >= 0 and flip_ratio <= 1
        assert direction in ['horizontal', 'vertical']
    def bbox_flip(self, bboxes, img_shape, direction):
        assert bboxes.shape[-1] % 4 == 0
        flipped = bboxes.copy()
        if direction == 'horizontal':
            w = img_shape[1]
            flipped[..., 0::4] = w - bboxes[..., 2::4] - 1
            flipped[..., 2::4] = w - bboxes[..., 0::4] - 1
        elif direction == 'vertical':
            h = img_shape[0]
            flipped[..., 1::4] = h - bboxes[..., 3::4] - 1
            flipped[..., 3::4] = h - bboxes[..., 1::4] - 1
        else:
            raise ValueError(
                'Invalid flipping direction "{}"'.format(direction))
        return flipped
    def __call__(self, results):
        if 'flip' not in results:
            flip = True if np.random.rand() < self.flip_ratio else False
            results['flip'] = flip
        if 'flip_direction' not in results:
            results['flip_direction'] = self.direction
        if results['flip']:
            results['img'] = mmcv.imflip(
                results['img'], direction=results['flip_direction'])
            for key in results.get('bbox_fields', []):
                results[key] = self.bbox_flip(results[key],
                                              results['img_shape'],
                                              results['flip_direction'])
            for key in results.get('mask_fields', []):
                results[key] = np.stack([
                    mmcv.imflip(mask, direction=results['flip_direction'])
                    for mask in results[key]
                ])
            for key in results.get('seg_fields', []):
                results[key] = mmcv.imflip(
                    results[key], direction=results['flip_direction'])
        return results
    def __repr__(self):
        return self.__class__.__name__ + '(flip_ratio={})'.format(
            self.flip_ratio)

class Pad(object):
    def __init__(self, size=None, size_divisor=None, pad_val=0):
        self.size = size
        self.size_divisor = size_divisor
        self.pad_val = pad_val
        assert size is not None or size_divisor is not None
        assert size is None or size_divisor is None
    def _pad_img(self, results):
        if self.size is not None:
            padded_img = mmcv.impad(results['img'], self.size, self.pad_val)
        elif self.size_divisor is not None:
            padded_img = mmcv.impad_to_multiple(
                results['img'], self.size_divisor, pad_val=self.pad_val)
        results['img'] = padded_img
        results['pad_shape'] = padded_img.shape
        results['pad_fixed_size'] = self.size
        results['pad_size_divisor'] = self.size_divisor
    def _pad_masks(self, results):
        pad_shape = results['pad_shape'][:2]
        for key in results.get('mask_fields', []):
            padded_masks = [
                mmcv.impad(mask, pad_shape, pad_val=self.pad_val)
                for mask in results[key]
            ]
            if padded_masks:
                results[key] = np.stack(padded_masks, axis=0)
            else:
                results[key] = np.empty((0, ) + pad_shape, dtype=np.uint8)
    def _pad_seg(self, results):
        for key in results.get('seg_fields', []):
            results[key] = mmcv.impad(results[key], results['pad_shape'][:2])
    def __call__(self, results):
        self._pad_img(results)
        self._pad_masks(results)
        self._pad_seg(results)
        return results
    def __repr__(self):
        repr_str = self.__class__.__name__
        repr_str += '(size={}, size_divisor={}, pad_val={})'.format(
            self.size, self.size_divisor, self.pad_val)
        return repr_str

class SegRescale(object):
    def __init__(self, scale_factor=1):
        self.scale_factor = scale_factor
    def __call__(self, results):
        for key in results.get('seg_fields', []):
            if self.scale_factor != 1:
                results[key] = mmcv.imrescale(
                    results[key], self.scale_factor, interpolation='nearest')
        return results
    def __repr__(self):
        return self.__class__.__name__ + '(scale_factor={})'.format(
            self.scale_factor)

class Albu(object):
    def __init__(self,
                 transforms,
                 bbox_params=None,
                 keymap=None,
                 update_pad_shape=False,
                 skip_img_without_anno=False):
        if Compose is None:
            raise RuntimeError('albumentations is not installed')
        self.transforms = transforms
        self.filter_lost_elements = False
        self.update_pad_shape = update_pad_shape
        self.skip_img_without_anno = skip_img_without_anno
        if (isinstance(bbox_params, dict) and 'label_fields' in bbox_params
                and 'filter_lost_elements' in bbox_params):
            self.filter_lost_elements = True
            self.origin_label_fields = bbox_params['label_fields']
            bbox_params['label_fields'] = ['idx_mapper']
            del bbox_params['filter_lost_elements']
        self.bbox_params = (
            self.albu_builder(bbox_params) if bbox_params else None)
        self.aug = Compose([self.albu_builder(t) for t in self.transforms],
                           bbox_params=self.bbox_params)
        if not keymap:
            self.keymap_to_albu = {
                'img': 'image',
                'gt_masks': 'masks',
                'gt_bboxes': 'bboxes'
            }
        else:
            self.keymap_to_albu = keymap
        self.keymap_back = {v: k for k, v in self.keymap_to_albu.items()}
    def albu_builder(self, cfg):
        assert isinstance(cfg, dict) and 'type' in cfg
        args = cfg.copy()
        obj_type = args.pop('type')
        if mmcv.is_str(obj_type):
            if albumentations is None:
                raise RuntimeError('albumentations is not installed')
            obj_cls = getattr(albumentations, obj_type)
        elif inspect.isclass(obj_type):
            obj_cls = obj_type
        else:
            raise TypeError(
                'type must be a str or valid type, but got {}'.format(
                    type(obj_type)))
        if 'transforms' in args:
            args['transforms'] = [
                self.albu_builder(transform)
                for transform in args['transforms']
            ]
        return obj_cls(**args)
    @staticmethod
    def mapper(d, keymap):
        updated_dict = {}
        for k, v in zip(d.keys(), d.values()):
            new_k = keymap.get(k, k)
            updated_dict[new_k] = d[k]
        return updated_dict
    def __call__(self, results):
        results = self.mapper(results, self.keymap_to_albu)
        if 'bboxes' in results:
            if isinstance(results['bboxes'], np.ndarray):
                results['bboxes'] = [x for x in results['bboxes']]
            if self.filter_lost_elements:
                results['idx_mapper'] = np.arange(len(results['bboxes']))
        results = self.aug(**results)
        if 'bboxes' in results:
            if isinstance(results['bboxes'], list):
                results['bboxes'] = np.array(
                    results['bboxes'], dtype=np.float32)
            results['bboxes'] = results['bboxes'].reshape(-1, 4)
            if self.filter_lost_elements:
                results['idx_mapper'] = np.arange(len(results['bboxes']))
                for label in self.origin_label_fields:
                    results[label] = np.array(
                        [results[label][i] for i in results['idx_mapper']])
                if 'masks' in results:
                    results['masks'] = np.array(
                        [results['masks'][i] for i in results['idx_mapper']])
                if (not len(results['idx_mapper'])
                        and self.skip_img_without_anno):
                    return None
        if 'gt_labels' in results:
            if isinstance(results['gt_labels'], list):
                results['gt_labels'] = np.array(results['gt_labels'])
            results['gt_labels'] = results['gt_labels'].astype(np.int64)
        results = self.mapper(results, self.keymap_back)
        if self.update_pad_shape:
            results['pad_shape'] = results['img'].shape
        return results
    def __repr__(self):
        repr_str = self.__class__.__name__
        repr_str += '(transformations={})'.format(self.transformations)
        return repr_str

class RandomTranslate(object):
    def __init__(self, translate_ratio=None, translate = 0.2, diff = False):
        self.translate_ratio = translate_ratio
        self.translate = translate
        self.diff = diff
        if translate_ratio is not None:
            assert translate_ratio >= 0 and translate_ratio <= 1
    def bbox_area(self,bbox):
        return (bbox[:,2] - bbox[:,0])*(bbox[:,3] - bbox[:,1])
    def clip_box(self, bbox, clip_box, alpha):
        ar_ = (self.bbox_area(bbox))
        x_min = np.maximum(bbox[:,0], clip_box[0]).reshape(-1,1)
        y_min = np.maximum(bbox[:,1], clip_box[1]).reshape(-1,1)
        x_max = np.minimum(bbox[:,2], clip_box[2]).reshape(-1,1)
        y_max = np.minimum(bbox[:,3], clip_box[3]).reshape(-1,1)
        delta_area = ((ar_ - self.bbox_area(bbox))/ar_)
        mask = (delta_area < (1 - alpha)).astype(int)
        bbox = bbox[mask == 1,:]
        return bbox
    def translate_img(self,img,bboxes):
        bws = bboxes[:,2] - bboxes[:,0]
        bhs = bboxes[:,3] - bboxes[:,1]
        if (bws == 0).any() or (bhs == 0).any():
            print('Not translate')
            return img,bboxes
        img_shape = img.shape
        translate_factor_x = np.random.uniform(-self.translate,self.translate)
        translate_factor_y = np.random.uniform(-self.translate,self.translate)
        if not self.diff:
            translate_factor_y = translate_factor_x
        canvas = np.zeros(img_shape).astype(np.uint8)
        corner_x = int(translate_factor_x*img.shape[1])
        corner_y = int(translate_factor_y*img.shape[0])
        orig_box_cords =  [max(0,corner_y), max(corner_x,0), min(img_shape[0], corner_y + img.shape[0]), min(img_shape[1],corner_x + img.shape[1])]
        mask = img[max(-corner_y, 0):min(img.shape[0], -corner_y + img_shape[0]), max(-corner_x, 0):min(img.shape[1], -corner_x + img_shape[1]),:]
        canvas[orig_box_cords[0]:orig_box_cords[2], orig_box_cords[1]:orig_box_cords[3],:] = mask
        img = canvas
        bboxes[:,:4] += [corner_x, corner_y, corner_x, corner_y]
        bboxes = self.clip_box(bboxes, [0, 0, img_shape[1], img_shape[0]], 0.25)
        return img, bboxes
    def __call__(self, results):
        if 'translate' not in results:
            translate = True if np.random.rand() < self.translate_ratio else False
            results['translate'] = translate
        if results['translate']:
            for key in results.get('bbox_fields', []):
                bboxes = results[key]
                if len(bboxes) > 0:
                    results['img'],results[key] = self.translate_img(results['img'],results[key])
        return results
    def __repr__(self):
        return self.__class__.__name__ + '(translate_ratio={},translate = {},diff = {})'.format(
            self.translate_ratio,self.translate,self.diff)

class RandomShear(object):
    def __init__(self, shear_ratio=None, shear_factor = 0.2):
        self.shear_ratio = shear_ratio
        self.shear_factor = shear_factor
        if shear_ratio is not None:
            assert shear_ratio >= 0 and shear_ratio <= 1
    def shear_img(self,img,bboxes):
        shear_factor = np.random.uniform(0,self.shear_factor)
        w,h = img.shape[1], img.shape[0]
        M = np.array([[1, abs(shear_factor), 0],[0,1,0]])
        nW =  img.shape[1] + abs(shear_factor*img.shape[0])
        bboxes[:,[0,2]] += ((bboxes[:,[1,3]]) * abs(shear_factor) ).astype(int) 
        img = cv2.warpAffine(img, M, (int(nW), img.shape[0]))
        img = cv2.resize(img, (w,h))
        scale_factor_x = nW / w
        bboxes[:,:4] /= [scale_factor_x, 1, scale_factor_x, 1] 
        return img,bboxes
    def __call__(self, results):
        if 'shear' not in results:
            shear = True if np.random.rand() < self.shear_ratio else False
            results['shear'] = shear
        if results['shear']:
            for key in results.get('bbox_fields', []):
                results['img'],results[key] = self.shear_img(results['img'],results[key])
        return results
    def __repr__(self):
        return self.__class__.__name__ + '(shear_ratio={},shear_factor = {})'.format(
            self.shear_ratio,self.shear_factor)

class AlbuSizedBBoxSafeCrop(object):
    def __init__(self,
                 transforms,
                 bbox_params=None,
                 keymap=None,
                 update_pad_shape=False,
                 skip_img_without_anno=False):
        if Compose is None:
            raise RuntimeError('albumentations is not installed')
        self.transforms = transforms
        self.filter_lost_elements = False
        self.update_pad_shape = update_pad_shape
        self.skip_img_without_anno = skip_img_without_anno
        if (isinstance(bbox_params, dict) and 'label_fields' in bbox_params
                and 'filter_lost_elements' in bbox_params):
            self.filter_lost_elements = True
            self.origin_label_fields = bbox_params['label_fields']
            bbox_params['label_fields'] = ['idx_mapper']
            del bbox_params['filter_lost_elements']
        self.bbox_params = (
            self.albu_builder(bbox_params) if bbox_params else None)
        self.aug = Compose([self.albu_builder(t) for t in self.transforms],
                           bbox_params=self.bbox_params)
        if not keymap:
            self.keymap_to_albu = {
                'img': 'image',
                'gt_masks': 'masks',
                'gt_bboxes': 'bboxes'
            }
        else:
            self.keymap_to_albu = keymap
        self.keymap_back = {v: k for k, v in self.keymap_to_albu.items()}
    def albu_builder(self, cfg):
        assert isinstance(cfg, dict) and 'type' in cfg
        args = cfg.copy()
        obj_type = args.pop('type')
        if mmcv.is_str(obj_type):
            if albumentations is None:
                raise RuntimeError('albumentations is not installed')
            obj_cls = getattr(albumentations, obj_type)
        elif inspect.isclass(obj_type):
            obj_cls = obj_type
        else:
            raise TypeError(
                'type must be a str or valid type, but got {}'.format(
                    type(obj_type)))
        if 'transforms' in args:
            args['transforms'] = [
                self.albu_builder(transform)
                for transform in args['transforms']
            ]
        return obj_cls(**args)
    @staticmethod
    def mapper(d, keymap):
        updated_dict = {}
        for k, v in zip(d.keys(), d.values()):
            new_k = keymap.get(k, k)
            updated_dict[new_k] = d[k]
        return updated_dict
    def __call__(self, results):
        results = self.mapper(results, self.keymap_to_albu)
        if 'bboxes' in results:
            if isinstance(results['bboxes'], np.ndarray):
                results['bboxes'] = [x for x in results['bboxes']]
            if self.filter_lost_elements:
                results['idx_mapper'] = np.arange(len(results['bboxes']))
        img_h,img_w,img_c = results['img_shape']
        for index,value in enumerate(self.transforms):
            self.transforms[index]['height'] = img_h
            self.transforms[index]['width'] = img_w
        results = self.aug(**results)
        if 'bboxes' in results:
            if isinstance(results['bboxes'], list):
                results['bboxes'] = np.array(
                    results['bboxes'], dtype=np.float32)
            results['bboxes'] = results['bboxes'].reshape(-1, 4)
            if self.filter_lost_elements:
                results['idx_mapper'] = np.arange(len(results['bboxes']))
                for label in self.origin_label_fields:
                    results[label] = np.array(
                        [results[label][i] for i in results['idx_mapper']])
                if 'masks' in results:
                    results['masks'] = np.array(
                        [results['masks'][i] for i in results['idx_mapper']])
                if (not len(results['idx_mapper'])
                        and self.skip_img_without_anno):
                    return None
        if 'gt_labels' in results:
            if isinstance(results['gt_labels'], list):
                results['gt_labels'] = np.array(results['gt_labels'])
            results['gt_labels'] = results['gt_labels'].astype(np.int64)
        results = self.mapper(results, self.keymap_back)
        if self.update_pad_shape:
            results['pad_shape'] = results['img'].shape
        return results
    def __repr__(self):
        repr_str = self.__class__.__name__
        repr_str += '(transformations={})'.format(self.transformations)
        return repr_str

class _BaseLogger:
    __slots__ = ('group', 'default_owner')
    def __init__(self, group, default_owner=None):
        self.group = group
        self.default_owner = default_owner
    def __repr__(self):
        return 'Logger({}, default_owner={})'.format(self.group, self.default_owner)
    def log(self, *args, **kwargs):
        raise NotImplementedError
    def _log_for_level(level):
        def log_for_level(self, *args, **kwargs):
            return self.log(*args, level=level, **kwargs)
        return log_for_level
    debug = _log_for_level(LEVEL_DEBUG)
    info = _log_for_level(LEVEL_INFO)
    warn = _log_for_level(LEVEL_WARN)
    error = _log_for_level(LEVEL_ERROR)
    del _log_for_level
    def exception(self, message, *args, exc=None, **kwargs):
        message += '\n{}'
        args += (format_exc(exc),)
        return self.log(message, *args, exc=exc, **kwargs)
    def callstack(self, message, *args, **kwargs):
        message = generate_message_with_callstack(message, *args, **kwargs)
        return self.log(message, *args, **kwargs)
    def assert_log(self, condition, message, *args, level=LEVEL_ERROR, **kwargs):
        if not condition:
            self.log(message, *args, level=level, **kwargs)
    def assert_raise(self, condition, message, *args, owner=None, **kwargs):
        if not condition:
            owner = owner or self.default_owner
            message = ('[{group}] [{owner}] ' + message).format(*args, group=self.group, owner=owner)
            raise AssertionError(message)

class TranG(MatrixLieGroup):
    @contract(n='1|2|3')
    def __init__(self, n):
        algebra = tran[n]
        MatrixLieGroup.__init__(self, n=n + 1, algebra=algebra, dimension=n)
        self.En = R[n]
        DifferentiableManifold.isomorphism(self, algebra,
                            self.algebra_from_group,
                            self.group_from_algebra,
                            itype='lie')
    def __repr__(self):
        return 'Tr%s' % (self.n - 1)
    def belongs(self, x):
        R, t, zero, one = extract_pieces(x)  
        assert_allclose(R, np.eye(self.n - 1))
        assert_allclose(zero, 0, err_msg='I expect the lower row to be 0.')
        assert_allclose(one, 1, err_msg='Bottom-right must be 1.')
    @contract(returns='belongs')
    def sample_uniform(self):
        t = self.En.sample_uniform()
        return pose_from_rotation_translation(np.eye(self.n - 1), t)
    def friendly(self, a):
        t = rotation_translation_from_pose(a)[1]
        return 'Tran(%s)' % (self.En.friendly(t))
    def logmap(self, base, p):
        return base, p - base
    def expmap(self, bv):
        base, vel = bv
        return base + vel
    def algebra_from_group(self, g):
        a = np.zeros((self.n, self.n))
        a[:-1, -1] = g[:-1, -1]
        return a
    def group_from_algebra(self, a):
        g = np.eye(self.n)
        g[:-1, -1] = a[:-1, -1]
        return g
    def interesting_points(self):
        points = []
        for t in self.En.interesting_points():
            p = pose_from_rotation_translation(np.eye(self.n - 1), t)
            points.append(p)
        return points

