class Node:
    def __init__(self, move=None, parent=None, state=None):
        self.move = move  
        self.parentNode = parent  
        self.childNodes = []
        self.wins = 0
        self.visits = 0
        self.untriedMoves = state.get_moves()  
        self.playerJustMoved = state.playerJustMoved  
    def uct_select_child(self):
        s = sorted(self.childNodes, key=lambda c: c.wins / c.visits + sqrt(2 * log(self.visits) / c.visits))[-1]
        return s
    def add_child(self, m, s):
        n = Node(move=m, parent=self, state=s)
        self.untriedMoves.remove(m)
        self.childNodes.append(n)
        return n
    def update(self, result):
        self.visits += 1
        self.wins += result
    def __repr__(self):
        return "[M:" + str(self.move) + " W/V:" + str(self.wins) + "/" + str(self.visits) + " U:" + str(
            self.untriedMoves) + "]"
    def convert_tree_to_string(self, indent):
        s = self.get_indent_string(indent) + str(self)
        for c in self.childNodes:
            s += c.convert_tree_to_string(indent + 1)
        return s
    @staticmethod
    def get_indent_string(indent):
        s = "\n"
        for i in range(1, indent + 1):
            s += "| "
        return s
    def convert_children_to_string(self):
        s = ""
        for c in self.childNodes:
            s += str(c) + "\n"
        return s

