            build=None,
            partial=False):
        if partial:
            warnings.warn(
                "Partial versions will be removed in 3.0; use SimpleSpec('1.x.x') instead.",
                DeprecationWarning,
                stacklevel=2,
            )
        has_text = version_string is not None
        has_parts = not (major is minor is patch is prerelease is build is None)
        if not has_text ^ has_parts:
            raise ValueError("Call either Version('1.2.3') or Version(major=1, ...).")
        if has_text:
            major, minor, patch, prerelease, build = self.parse(version_string, partial)
        else:
            prerelease = tuple(prerelease or ())
            if not partial:
                build = tuple(build or ())
            self._validate_kwargs(major, minor, patch, prerelease, build, partial)
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease
        self.build = build
        self.partial = partial
        self._cmp_precedence_key = self._build_precedence_key(with_build=False)
        self._sort_precedence_key = self._build_precedence_key(with_build=True)
    @classmethod
    def _coerce(cls, value, allow_none=False):
        if value is None and allow_none:
            return value
        return int(value)
    def next_major(self):
        if self.prerelease and self.minor == self.patch == 0:
            return Version(
                major=self.major,
                minor=0,
                patch=0,
                partial=self.partial,
            )
        else:
            return Version(
                major=self.major + 1,
                minor=0,
                patch=0,
                partial=self.partial,
            )
    def next_minor(self):
        if self.prerelease and self.patch == 0:
            return Version(
                major=self.major,
                minor=self.minor,
                patch=0,
                partial=self.partial,
            )
        else:
            return Version(
                major=self.major,
                minor=self.minor + 1,
                patch=0,
                partial=self.partial,
            )
    def next_patch(self):
        if self.prerelease:
            return Version(
                major=self.major,
                minor=self.minor,
                patch=self.patch,
                partial=self.partial,
            )
        else:
            return Version(
                major=self.major,
                minor=self.minor,
                patch=self.patch + 1,
                partial=self.partial,
            )
    def truncate(self, level='patch'):
        if level == 'build':
            return self
        elif level == 'prerelease':
            return Version(
                major=self.major,
                minor=self.minor,
                patch=self.patch,
                prerelease=self.prerelease,
                partial=self.partial,
            )
        elif level == 'patch':
            return Version(
                major=self.major,
                minor=self.minor,
                patch=self.patch,
                partial=self.partial,
            )
        elif level == 'minor':
            return Version(
                major=self.major,
                minor=self.minor,
                patch=None if self.partial else 0,
                partial=self.partial,
            )
        elif level == 'major':
            return Version(
                major=self.major,
                minor=None if self.partial else 0,
                patch=None if self.partial else 0,
                partial=self.partial,
            )
        else:
            raise ValueError("Invalid truncation level `%s`." % level)
    @classmethod
    def coerce(cls, version_string, partial=False):
        base_re = re.compile(r'^\d+(?:\.\d+(?:\.\d+)?)?')
        match = base_re.match(version_string)
        if not match:
            raise ValueError(
                "Version string lacks a numerical component: %r"
                % version_string
            )
        version = version_string[:match.end()]
        if not partial:
            while version.count('.') < 2:
                version += '.0'
        version = '.'.join(
            part.lstrip('0') or '0'
            for part in version.split('.')
        )
        if match.end() == len(version_string):
            return Version(version, partial=partial)
        rest = version_string[match.end():]
        rest = re.sub(r'[^a-zA-Z0-9+.-]', '-', rest)
        if rest[0] == '+':
            prerelease = ''
            build = rest[1:]
        elif rest[0] == '.':
            prerelease = ''
            build = rest[1:]
        elif rest[0] == '-':
            rest = rest[1:]
            if '+' in rest:
                prerelease, build = rest.split('+', 1)
            else:
                prerelease, build = rest, ''
        elif '+' in rest:
            prerelease, build = rest.split('+', 1)
        else:
            prerelease, build = rest, ''
        build = build.replace('+', '.')
        if prerelease:
            version = '%s-%s' % (version, prerelease)
        if build:
            version = '%s+%s' % (version, build)
        return cls(version, partial=partial)
    @classmethod
    def parse(cls, version_string, partial=False, coerce=False):
        if not version_string:
            raise ValueError('Invalid empty version string: %r' % version_string)
        if partial:
            version_re = cls.partial_version_re
        else:
            version_re = cls.version_re
        match = version_re.match(version_string)
        if not match:
            raise ValueError('Invalid version string: %r' % version_string)
        major, minor, patch, prerelease, build = match.groups()
        if _has_leading_zero(major):
            raise ValueError("Invalid leading zero in major: %r" % version_string)
        if _has_leading_zero(minor):
            raise ValueError("Invalid leading zero in minor: %r" % version_string)
        if _has_leading_zero(patch):
            raise ValueError("Invalid leading zero in patch: %r" % version_string)
        major = int(major)
        minor = cls._coerce(minor, partial)
        patch = cls._coerce(patch, partial)
        if prerelease is None:
            if partial and (build is None):
                return (major, minor, patch, None, None)
            else:
                prerelease = ()
        elif prerelease == '':
            prerelease = ()
        else:
            prerelease = tuple(prerelease.split('.'))
            cls._validate_identifiers(prerelease, allow_leading_zeroes=False)
        if build is None:
            if partial:
                build = None
            else:
                build = ()
        elif build == '':
            build = ()
        else:
            build = tuple(build.split('.'))
            cls._validate_identifiers(build, allow_leading_zeroes=True)
        return (major, minor, patch, prerelease, build)
    @classmethod
    def _validate_identifiers(cls, identifiers, allow_leading_zeroes=False):
        for item in identifiers:
            if not item:
                raise ValueError(
                    "Invalid empty identifier %r in %r"
                    % (item, '.'.join(identifiers))
                )
            if item[0] == '0' and item.isdigit() and item != '0' and not allow_leading_zeroes:
                raise ValueError("Invalid leading zero in identifier %r" % item)
    @classmethod
    def _validate_kwargs(cls, major, minor, patch, prerelease, build, partial):
        if (
                major != int(major)
                or minor != cls._coerce(minor, partial)
                or patch != cls._coerce(patch, partial)
                or prerelease is None and not partial
                or build is None and not partial
        ):
            raise ValueError(
                "Invalid kwargs to Version(major=%r, minor=%r, patch=%r, "
                "prerelease=%r, build=%r, partial=%r" % (
                    major, minor, patch, prerelease, build, partial
                ))
        if prerelease is not None:
            cls._validate_identifiers(prerelease, allow_leading_zeroes=False)
        if build is not None:
            cls._validate_identifiers(build, allow_leading_zeroes=True)
    def __iter__(self):
        return iter((self.major, self.minor, self.patch, self.prerelease, self.build))
    def __str__(self):
        version = '%d' % self.major
        if self.minor is not None:
            version = '%s.%d' % (version, self.minor)
        if self.patch is not None:
            version = '%s.%d' % (version, self.patch)
        if self.prerelease or (self.partial and self.prerelease == () and self.build is None):
            version = '%s-%s' % (version, '.'.join(self.prerelease))
        if self.build or (self.partial and self.build == ()):
            version = '%s+%s' % (version, '.'.join(self.build))
        return version
    def __repr__(self):
        return '%s(%r%s)' % (
            self.__class__.__name__,
            str(self),
            ', partial=True' if self.partial else '',
        )
    def __hash__(self):
        return hash((self.major, self.minor, self.patch, self.prerelease, self.build))
    def _build_precedence_key(self, with_build=False):
        if self.prerelease:
            prerelease_key = tuple(
                NumericIdentifier(part) if part.isdigit() else AlphaIdentifier(part)
                for part in self.prerelease
            )
        else:
            prerelease_key = (
                MaxIdentifier(),
            )
        if not with_build:
            return (
                self.major,
                self.minor,
                self.patch,
                prerelease_key,
            )
        build_key = tuple(
            NumericIdentifier(part) if part.isdigit() else AlphaIdentifier(part)
            for part in self.build or ()
        )
        return (
            self.major,
            self.minor,
            self.patch,
            prerelease_key,
            build_key,
        )
    @property
    def precedence_key(self):
        return self._sort_precedence_key
    def __cmp__(self, other):
        if not isinstance(other, self.__class__):
            return NotImplemented
        if self < other:
            return -1
        elif self > other:
            return 1
        elif self == other:
            return 0
        else:
            return NotImplemented
    def __eq__(self, other):
        if not isinstance(other, self.__class__):
            return NotImplemented
        return (
            self.major == other.major
            and self.minor == other.minor
            and self.patch == other.patch
            and (self.prerelease or ()) == (other.prerelease or ())
            and (self.build or ()) == (other.build or ())
        )
    def __ne__(self, other):
        if not isinstance(other, self.__class__):
            return NotImplemented
        return tuple(self) != tuple(other)
    def __lt__(self, other):
        if not isinstance(other, self.__class__):
            return NotImplemented
        return self._cmp_precedence_key < other._cmp_precedence_key
    def __le__(self, other):
        if not isinstance(other, self.__class__):
            return NotImplemented
        return self._cmp_precedence_key <= other._cmp_precedence_key
    def __gt__(self, other):
        if not isinstance(other, self.__class__):
            return NotImplemented
        return self._cmp_precedence_key > other._cmp_precedence_key
    def __ge__(self, other):
        if not isinstance(other, self.__class__):
            return NotImplemented
        return self._cmp_precedence_key >= other._cmp_precedence_key

class BaseSpec(object):
    SYNTAXES = {}
    @classmethod
    def register_syntax(cls, subclass):
        syntax = subclass.SYNTAX
        if syntax is None:
            raise ValueError("A Spec needs its SYNTAX field to be set.")
        elif syntax in cls.SYNTAXES:
            raise ValueError(
                "Duplicate syntax for %s: %r, %r"
                % (syntax, cls.SYNTAXES[syntax], subclass)
            )
        cls.SYNTAXES[syntax] = subclass
        return subclass
    def __init__(self, expression):
        super(BaseSpec, self).__init__()
        self.expression = expression
        self.clause = self._parse_to_clause(expression)
    @classmethod
    def parse(cls, expression, syntax=DEFAULT_SYNTAX):
        return cls.SYNTAXES[syntax](expression)
    @classmethod
    def _parse_to_clause(cls, expression):
        raise NotImplementedError()
    def filter(self, versions):
        for version in versions:
            if self.match(version):
                yield version
    def match(self, version):
        return self.clause.match(version)
    def select(self, versions):
        options = list(self.filter(versions))
        if options:
            return max(options)
        return None
    def __contains__(self, version):
        if isinstance(version, Version):
            return self.match(version)
        return False
    def __eq__(self, other):
        if not isinstance(other, self.__class__):
            return NotImplemented
        return self.clause == other.clause
    def __hash__(self):
        return hash(self.clause)
    def __str__(self):
        return self.expression
    def __repr__(self):
        return '<%s: %r>' % (self.__class__.__name__, self.expression)

class Clause(object):
    __slots__ = []
    def match(self, version):
        raise NotImplementedError()
    def __and__(self, other):
        raise NotImplementedError()
    def __or__(self, other):
        raise NotImplementedError()
    def __eq__(self, other):
        raise NotImplementedError()
    def prettyprint(self, indent='\t'):
        return '\n'.join(self._pretty()).replace('\t', indent)
    def _pretty(self):
        yield repr(self)
    def __ne__(self, other):
        return not self == other
    def simplify(self):
        return self

class AnyOf(Clause):
    __slots__ = ['clauses']
    def __init__(self, *clauses):
        super(AnyOf, self).__init__()
        self.clauses = frozenset(clauses)
    def match(self, version):
        return any(c.match(version) for c in self.clauses)
    def simplify(self):
        subclauses = set()
        for clause in self.clauses:
            simplified = clause.simplify()
            if isinstance(simplified, AnyOf):
                subclauses |= simplified.clauses
            elif simplified == Never():
                continue
            else:
                subclauses.add(simplified)
        if len(subclauses) == 1:
            return subclauses.pop()
        return AnyOf(*subclauses)
    def __hash__(self):
        return hash((AnyOf, self.clauses))
    def __iter__(self):
        return iter(self.clauses)
    def __eq__(self, other):
        return isinstance(other, self.__class__) and self.clauses == other.clauses
    def __and__(self, other):
        if isinstance(other, AllOf):
            return other & self
        elif isinstance(other, Matcher) or isinstance(other, AnyOf):
            return AllOf(self, other)
        else:
            return NotImplemented
    def __or__(self, other):
        if isinstance(other, AnyOf):
            clauses = list(self.clauses | other.clauses)
        elif isinstance(other, Matcher) or isinstance(other, AllOf):
            clauses = list(self.clauses | set([other]))
        else:
            return NotImplemented
        return AnyOf(*clauses)
    def __repr__(self):
        return 'AnyOf(%s)' % ', '.join(sorted(repr(c) for c in self.clauses))
    def _pretty(self):
        yield 'AnyOF('
        for clause in self.clauses:
            lines = list(clause._pretty())
            for line in lines[:-1]:
                yield '\t' + line
            yield '\t' + lines[-1] + ','
        yield ')'

class AllOf(Clause):
    __slots__ = ['clauses']
    def __init__(self, *clauses):
        super(AllOf, self).__init__()
        self.clauses = frozenset(clauses)
    def match(self, version):
        return all(clause.match(version) for clause in self.clauses)
    def simplify(self):
        subclauses = set()
        for clause in self.clauses:
            simplified = clause.simplify()
            if isinstance(simplified, AllOf):
                subclauses |= simplified.clauses
            elif simplified == Always():
                continue
            else:
                subclauses.add(simplified)
        if len(subclauses) == 1:
            return subclauses.pop()
        return AllOf(*subclauses)
    def __hash__(self):
        return hash((AllOf, self.clauses))
    def __iter__(self):
        return iter(self.clauses)
    def __eq__(self, other):
        return isinstance(other, self.__class__) and self.clauses == other.clauses
    def __and__(self, other):
        if isinstance(other, Matcher) or isinstance(other, AnyOf):
            clauses = list(self.clauses | set([other]))
        elif isinstance(other, AllOf):
            clauses = list(self.clauses | other.clauses)
        else:
            return NotImplemented
        return AllOf(*clauses)
    def __or__(self, other):
        if isinstance(other, AnyOf):
            return other | self
        elif isinstance(other, Matcher):
            return AnyOf(self, AllOf(other))
        elif isinstance(other, AllOf):
            return AnyOf(self, other)
        else:
            return NotImplemented
    def __repr__(self):
        return 'AllOf(%s)' % ', '.join(sorted(repr(c) for c in self.clauses))
    def _pretty(self):
        yield 'AllOF('
        for clause in self.clauses:
            lines = list(clause._pretty())
            for line in lines[:-1]:
                yield '\t' + line
            yield '\t' + lines[-1] + ','
        yield ')'

class PolynomialsOverZp:
    mod_p = p
    def __init__(self, lst):
        lst = [x % p for x in lst]
        lst = _remove_trailing_zeros(lst)
        self.coefs = lst
    @classmethod
    def from_dict(cls, dct):
        if len(dct) == 0:
            result = cls([])
        else:
            assert(
                    all([_represents_natural_number(key) for key in dct.keys()])
                    ), 'Invalid keys in dict'
            powers = [int(x) for x in dct.keys()]
            degree = max(powers)
            lst = [0]*(degree+1)
            for i in powers:
                lst[i] = dct[str(i)]
            result = cls(lst)
        return result
    @classmethod
    def from_int(cls, int_):
        assert(type(int_) == int), 'Input is not of type int.'
        return cls([int_])
    def is_zero(self): 
        return self.coefs == []
    def typesetter(func):
        def new_func(self, other):
            if isinstance(other, PolynomialsOverZp):
                result = func(self, other)
            elif type(other) == list:
                other = PolynomialsOverZp(other)
                result = func(self, other)
            elif type(other) == dict:
                other = PolynomialsOverZp.from_dict(other)
                result = func(self, other)
            elif type(other) == int:
                other = PolynomialsOverZp([other])
                result = func(self, other)
            else:
                error_msg = 'Not a valid polynomial.'
                raise TypeError(error_msg)
            return result
        return new_func
    @typesetter
    def is_equal(self, other):
        return self.coefs == other.coefs
    def __eq__(self, other):
        return self.is_equal(other)
    @typesetter
    def add(self, other):
        self_coefs = self.coefs.copy()
        self_coefs.reverse()
        other_coefs = other.coefs.copy()
        other_coefs.reverse()
        result_coefs = gt.gf_add(self_coefs, other_coefs, p, ZZ)
        result_coefs.reverse()
        result = PolynomialsOverZp(result_coefs)
        return result
    def __add__(self, other):
        return self.add(other)
    def neg(self):
        return PolynomialsOverZp([(-n) % p for n in self.coefs])
    def __neg__(self):
        return self.neg()
    @typesetter
    def sub(self, other):
        return self.add(other.neg())
    def __sub__(self, other):
        return self.sub(other)
    @typesetter
    def mul(self, other):
        self_coefs = self.coefs.copy()
        self_coefs.reverse()
        other_coefs = other.coefs.copy()
        other_coefs.reverse()
        result_coefs = gt.gf_mul(self_coefs, other_coefs, p, ZZ)
        result_coefs.reverse()
        result = PolynomialsOverZp(result_coefs)
        return result
    def __mul__(self, other):
        return self.mul(other)
    @typesetter
    def div_mod(self, other):
        self_coefs = self.coefs.copy()
        self_coefs.reverse()
        other_coefs = other.coefs.copy()
        other_coefs.reverse()
        quot_coefs, remainder_coefs = gt.gf_div(self_coefs, other_coefs, 
                                                p, ZZ)
        quot_coefs.reverse()
        remainder_coefs.reverse()
        quot = PolynomialsOverZp(quot_coefs)
        remainder = PolynomialsOverZp(remainder_coefs)
        return quot, remainder
    def quotient(self, other):
        result, _ = self.div_mod(other)
        return result
    def __floordiv__(self, other):
        result = self.quotient(other)
        return result
    def mod(self, other):
        _, result = self.div_mod(other)
        return result
    def __mod__(self, other):
        return self.mod(other)
    def is_irreducible(self):
        if self.is_zero():
            return False
        else:
            self_coefs = self.coefs.copy()
            self_coefs.reverse()
            result = gt.gf_irreducible_p(self_coefs, p, ZZ)
            return result
    def to_list(self):
        return self.coefs
    def to_dict(self):
        result = {'%d'%i : self.coefs[i] for i in range(
                len(self.coefs)
                ) if self.coefs[i] != 0}
        return result
    def degree(self):
        if self.is_zero():
            return -1
        else:
            return len(self.coefs) - 1
    def __repr__(self):
        if self.is_zero():
            return '0'
        else:
            deg = self.degree()
            if deg == 0:
                return str( self.coefs[0] )
            else:
                poly_str_lst = []
                if self.coefs[0] != 0:
                    poly_str_lst.append( str(self.coefs[0]) )
                first_coef = self.coefs[1]
                if first_coef != 0:
                    first_coef_ = '' if first_coef == 1 else first_coef
                    poly_str_lst.append( '%sx' % first_coef_ )
                if deg == 1:
                    poly_str = ' + '.join( poly_str_lst )
                else:
                    for power, coef in zip( range(2, deg+1), self.coefs[2:] ):
                        if coef != 0:
                            coef_ = '' if coef == 1 else coef
                            poly_str_lst.append( '%sx^{%s}' % ( coef_, power) )
                    poly_str = ' + '.join( poly_str_lst )
                return poly_str

class BlockRDD(object):
    def __init__(self, rdd, bsize=-1, dtype=tuple, noblock=False):
        if isinstance(rdd, BlockRDD):
            _check_dtype(rdd.first(), dtype)
            self._rdd = rdd._rdd
            bsize = rdd.bsize
        elif isinstance(rdd, RDD):
            if not noblock:
                rdd = self._block(rdd, bsize, dtype)
            self._rdd = rdd
        else:
            raise TypeError(
                "Unexpected type {0} for parameter rdd".format(type(rdd)))
        self.dtype = dtype
        self.bsize = bsize
    def _block(self, rdd, bsize, dtype):
        return rdd.mapPartitions(
            lambda x: _block_collection(x, dtype, bsize))
    def get_params(self):
        return {'bsize': self.bsize,
                'dtype': self.dtype}
    def __repr__(self):
        return "{0} from {1}".format(self.__class__, repr(self._rdd))
    def __getattr__(self, attr):
        def bypass(*args, **kwargs):
            result = getattr(self._rdd, attr)(*args, **kwargs)
            if isinstance(result, RDD):
                if result is self._rdd:
                    return self
                else:
                    return BlockRDD(result, bsize=self.bsize, dtype=self.dtype,
                                    noblock=True)
            return result
        if not hasattr(self._rdd, attr):
            raise AttributeError("{0} object has no attribute {1}".format(
                                 self.__class__, attr))
        return bypass
    def __getitem__(self, index):
        if isinstance(index, tuple):
            raise IndexError("Too many indices for BlockRDD")
        elif isinstance(index, slice) and index == slice(None, None, None):
            return self
        indices = np.arange(self.blocks)[index]
        indexed = self._rdd.zipWithIndex()
        if isinstance(index, slice):
            ascending = index.step is None or index.step > 0
            rdd = indexed.filter(lambda x_i: x_i[1] in indices)
            if not ascending:
                rdd = rdd.sortBy(lambda x_i: x_i[1], ascending)
        elif hasattr(index, "__iter__"):
            arg = indices.tolist()
            rdd = indexed.filter(lambda x_i: x_i[1] in indices) \
                         .sortBy(lambda x_i: arg.index(x_i[1]))
        elif isinstance(index, int):
            rdd = indexed.filter(lambda x_i: x_i[1] == indices)
        else:
            raise KeyError("Unexpected type of index: {0}".format(type(index)))
        rdd = rdd.map(lambda x_i: x_i[0])
        return self.__class__(rdd, noblock=True, **self.get_params())
    def __len__(self):
        return self._rdd.map(len).sum()
    @property
    def context(self):
        return self._rdd.ctx
    @property
    def blocks(self):  
        return self._rdd.count()
    @property
    def partitions(self):  
        return self._rdd.getNumPartitions()
    def unblock(self):
        return self._rdd.flatMap(lambda x: list(x))
    def tolist(self):
        return self.unblock().collect()
    def toarray(self):
        rdd = self._rdd.map(lambda x: np.array(x))
        return np.concatenate(rdd.collect())
    def transform(self, fn, dtype=None, *args, **kwargs):
        rdd = self._rdd.map(fn)
        if dtype is None:
            return self.__class__(rdd, noblock=True, **self.get_params())
        if dtype is np.ndarray:
            return ArrayRDD(rdd, bsize=self.bsize, noblock=True)
        elif dtype is sp.spmatrix:
            return SparseRDD(rdd, bsize=self.bsize, noblock=True)
        else:
            return BlockRDD(rdd, bsize=self.bsize, dtype=dtype, noblock=True)

class _cs_matrix(_data_matrix, _minmax_mixin, IndexMixin):
    def __init__(self, arg1, shape=None, dtype=None, copy=False):
        _data_matrix.__init__(self)
        if isspmatrix(arg1):
            if arg1.format == self.format and copy:
                arg1 = arg1.copy()
            else:
                arg1 = arg1.asformat(self.format)
            self._set_self(arg1)
        elif isinstance(arg1, tuple):
            if isshape(arg1):
                self._shape = check_shape(arg1)
                M, N = self.shape
                idx_dtype = get_index_dtype(maxval=max(M, N))
                self.data = np.zeros(0, getdtype(dtype, default=float))
                self.indices = np.zeros(0, idx_dtype)
                self.indptr = np.zeros(self._swap((M, N))[0] + 1,
                                       dtype=idx_dtype)
            else:
                if len(arg1) == 2:
                    from .coo import coo_matrix
                    other = self.__class__(coo_matrix(arg1, shape=shape,
                                                      dtype=dtype))
                    self._set_self(other)
                elif len(arg1) == 3:
                    (data, indices, indptr) = arg1
                    maxval = None
                    if shape is not None:
                        maxval = max(shape)
                    idx_dtype = get_index_dtype((indices, indptr),
                                                maxval=maxval,
                                                check_contents=True)
                    self.indices = np.array(indices, copy=copy,
                                            dtype=idx_dtype)
                    self.indptr = np.array(indptr, copy=copy, dtype=idx_dtype)
                    self.data = np.array(data, copy=copy, dtype=dtype)
                else:
                    raise ValueError("unrecognized {}_matrix "
                                     "constructor usage".format(self.format))
        else:
            try:
                arg1 = np.asarray(arg1)
            except Exception as e:
                raise ValueError("unrecognized {}_matrix constructor usage"
                                 "".format(self.format)) from e
            from .coo import coo_matrix
            self._set_self(self.__class__(coo_matrix(arg1, dtype=dtype)))
        if shape is not None:
            self._shape = check_shape(shape)
        else:
            if self.shape is None:
                try:
                    major_dim = len(self.indptr) - 1
                    minor_dim = self.indices.max() + 1
                except Exception as e:
                    raise ValueError('unable to infer matrix dimensions') from e
                else:
                    self._shape = check_shape(self._swap((major_dim,
                                                          minor_dim)))
        if dtype is not None:
            self.data = self.data.astype(dtype, copy=False)
        self.check_format(full_check=False)
    def getnnz(self, axis=None):
        if axis is None:
            return int(self.indptr[-1])
        else:
            if axis < 0:
                axis += 2
            axis, _ = self._swap((axis, 1 - axis))
            _, N = self._swap(self.shape)
            if axis == 0:
                return np.bincount(downcast_intp_index(self.indices),
                                   minlength=N)
            elif axis == 1:
                return np.diff(self.indptr)
            raise ValueError('axis out of bounds')
    getnnz.__doc__ = spmatrix.getnnz.__doc__
    def _set_self(self, other, copy=False):
        if copy:
            other = other.copy()
        self.data = other.data
        self.indices = other.indices
        self.indptr = other.indptr
        self._shape = check_shape(other.shape)
    def check_format(self, full_check=True):
        major_name, minor_name = self._swap(('row', 'column'))
        major_dim, minor_dim = self._swap(self.shape)
        if self.indptr.dtype.kind != 'i':
            warn("indptr array has non-integer dtype ({})"
                 "".format(self.indptr.dtype.name), stacklevel=3)
        if self.indices.dtype.kind != 'i':
            warn("indices array has non-integer dtype ({})"
                 "".format(self.indices.dtype.name), stacklevel=3)
        idx_dtype = get_index_dtype((self.indptr, self.indices))
        self.indptr = np.asarray(self.indptr, dtype=idx_dtype)
        self.indices = np.asarray(self.indices, dtype=idx_dtype)
        self.data = to_native(self.data)
        for x in [self.data.ndim, self.indices.ndim, self.indptr.ndim]:
            if x != 1:
                raise ValueError('data, indices, and indptr should be 1-D')
        if (len(self.indptr) != major_dim + 1):
            raise ValueError("index pointer size ({}) should be ({})"
                             "".format(len(self.indptr), major_dim + 1))
        if (self.indptr[0] != 0):
            raise ValueError("index pointer should start with 0")
        if (len(self.indices) != len(self.data)):
            raise ValueError("indices and data should have the same size")
        if (self.indptr[-1] > len(self.indices)):
            raise ValueError("Last value of index pointer should be less than "
                             "the size of index and data arrays")
        self.prune()
        if full_check:
            if self.nnz > 0:
                if self.indices.max() >= minor_dim:
                    raise ValueError("{} index values must be < {}"
                                     "".format(minor_name, minor_dim))
                if self.indices.min() < 0:
                    raise ValueError("{} index values must be >= 0"
                                     "".format(minor_name))
                if np.diff(self.indptr).min() < 0:
                    raise ValueError("index pointer values must form a "
                                     "non-decreasing sequence")
    def _scalar_binopt(self, other, op):
        self.sum_duplicates()
        res = self._with_data(op(self.data, other), copy=True)
        res.eliminate_zeros()
        return res
    def __eq__(self, other):
        if isscalarlike(other):
            if np.isnan(other):
                return self.__class__(self.shape, dtype=np.bool_)
            if other == 0:
                warn("Comparing a sparse matrix with 0 using == is inefficient"
                     ", try using != instead.", SparseEfficiencyWarning,
                     stacklevel=3)
                all_true = self.__class__(np.ones(self.shape, dtype=np.bool_))
                inv = self._scalar_binopt(other, operator.ne)
                return all_true - inv
            else:
                return self._scalar_binopt(other, operator.eq)
        elif isdense(other):
            return self.todense() == other
        elif is_pydata_spmatrix(other):
            return NotImplemented
        elif isspmatrix(other):
            warn("Comparing sparse matrices using == is inefficient, try using"
                 " != instead.", SparseEfficiencyWarning, stacklevel=3)
            if self.shape != other.shape:
                return False
            elif self.format != other.format:
                other = other.asformat(self.format)
            res = self._binopt(other, '_ne_')
            all_true = self.__class__(np.ones(self.shape, dtype=np.bool_))
            return all_true - res
        else:
            return False
    def __ne__(self, other):
        if isscalarlike(other):
            if np.isnan(other):
                warn("Comparing a sparse matrix with nan using != is"
                     " inefficient", SparseEfficiencyWarning, stacklevel=3)
                all_true = self.__class__(np.ones(self.shape, dtype=np.bool_))
                return all_true
            elif other != 0:
                warn("Comparing a sparse matrix with a nonzero scalar using !="
                     " is inefficient, try using == instead.",
                     SparseEfficiencyWarning, stacklevel=3)
                all_true = self.__class__(np.ones(self.shape), dtype=np.bool_)
                inv = self._scalar_binopt(other, operator.eq)
                return all_true - inv
            else:
                return self._scalar_binopt(other, operator.ne)
        elif isdense(other):
            return self.todense() != other
        elif is_pydata_spmatrix(other):
            return NotImplemented
        elif isspmatrix(other):
            if self.shape != other.shape:
                return True
            elif self.format != other.format:
                other = other.asformat(self.format)
            return self._binopt(other, '_ne_')
        else:
            return True
    def _inequality(self, other, op, op_name, bad_scalar_msg):
        if isscalarlike(other):
            if 0 == other and op_name in ('_le_', '_ge_'):
                raise NotImplementedError(" >= and <= don't work with 0.")
            elif op(0, other):
                warn(bad_scalar_msg, SparseEfficiencyWarning)
                other_arr = np.empty(self.shape, dtype=np.result_type(other))
                other_arr.fill(other)
                other_arr = self.__class__(other_arr)
                return self._binopt(other_arr, op_name)
            else:
                return self._scalar_binopt(other, op)
        elif isdense(other):
            return op(self.todense(), other)
        elif isspmatrix(other):
            if self.shape != other.shape:
                raise ValueError("inconsistent shapes")
            elif self.format != other.format:
                other = other.asformat(self.format)
            if op_name not in ('_ge_', '_le_'):
                return self._binopt(other, op_name)
            warn("Comparing sparse matrices using >= and <= is inefficient, "
                 "using <, >, or !=, instead.", SparseEfficiencyWarning)
            all_true = self.__class__(np.ones(self.shape, dtype=np.bool_))
            res = self._binopt(other, '_gt_' if op_name == '_le_' else '_lt_')
            return all_true - res
        else:
            raise ValueError("Operands could not be compared.")
    def __lt__(self, other):
        return self._inequality(other, operator.lt, '_lt_',
                                "Comparing a sparse matrix with a scalar "
                                "greater than zero using < is inefficient, "
                                "try using >= instead.")
    def __gt__(self, other):
        return self._inequality(other, operator.gt, '_gt_',
                                "Comparing a sparse matrix with a scalar "
                                "less than zero using > is inefficient, "
                                "try using <= instead.")
    def __le__(self, other):
        return self._inequality(other, operator.le, '_le_',
                                "Comparing a sparse matrix with a scalar "
                                "greater than zero using <= is inefficient, "
                                "try using > instead.")
    def __ge__(self, other):
        return self._inequality(other, operator.ge, '_ge_',
                                "Comparing a sparse matrix with a scalar "
                                "less than zero using >= is inefficient, "
                                "try using < instead.")
    def _add_dense(self, other):
        if other.shape != self.shape:
            raise ValueError('Incompatible shapes ({} and {})'
                             .format(self.shape, other.shape))
        dtype = upcast_char(self.dtype.char, other.dtype.char)
        order = self._swap('CF')[0]
        result = np.array(other, dtype=dtype, order=order, copy=True)
        M, N = self._swap(self.shape)
        y = result if result.flags.c_contiguous else result.T
        csr_todense(M, N, self.indptr, self.indices, self.data, y)
        return matrix(result, copy=False)
    def _add_sparse(self, other):
        return self._binopt(other, '_plus_')
    def _sub_sparse(self, other):
        return self._binopt(other, '_minus_')
    def multiply(self, other):
        if isscalarlike(other):
            return self._mul_scalar(other)
        if isspmatrix(other):
            if self.shape == other.shape:
                other = self.__class__(other)
                return self._binopt(other, '_elmul_')
            elif other.shape == (1, 1):
                return self._mul_scalar(other.toarray()[0, 0])
            elif self.shape == (1, 1):
                return other._mul_scalar(self.toarray()[0, 0])
            elif self.shape[1] == 1 and other.shape[0] == 1:
                return self._mul_sparse_matrix(other.tocsc())
            elif self.shape[0] == 1 and other.shape[1] == 1:
                return other._mul_sparse_matrix(self.tocsc())
            elif other.shape[0] == 1 and self.shape[1] == other.shape[1]:
                other = dia_matrix((other.toarray().ravel(), [0]),
                                   shape=(other.shape[1], other.shape[1]))
                return self._mul_sparse_matrix(other)
            elif self.shape[0] == 1 and self.shape[1] == other.shape[1]:
                copy = dia_matrix((self.toarray().ravel(), [0]),
                                  shape=(self.shape[1], self.shape[1]))
                return other._mul_sparse_matrix(copy)
            elif other.shape[1] == 1 and self.shape[0] == other.shape[0]:
                other = dia_matrix((other.toarray().ravel(), [0]),
                                   shape=(other.shape[0], other.shape[0]))
                return other._mul_sparse_matrix(self)
            elif self.shape[1] == 1 and self.shape[0] == other.shape[0]:
                copy = dia_matrix((self.toarray().ravel(), [0]),
                                  shape=(self.shape[0], self.shape[0]))
                return copy._mul_sparse_matrix(other)
            else:
                raise ValueError("inconsistent shapes")
        other = np.atleast_2d(other)
        if other.ndim != 2:
            return np.multiply(self.toarray(), other)
        if other.size == 1:
            return self._mul_scalar(other.flat[0])
        elif self.shape == (1, 1):
            return np.multiply(self.toarray()[0, 0], other)
        from .coo import coo_matrix
        ret = self.tocoo()
        if self.shape == other.shape:
            data = np.multiply(ret.data, other[ret.row, ret.col])
        elif self.shape[0] == 1:
            if other.shape[1] == 1:  
                data = np.multiply(ret.data, other)
            elif other.shape[1] == self.shape[1]:  
                data = np.multiply(ret.data, other[:, ret.col])
            else:
                raise ValueError("inconsistent shapes")
            row = np.repeat(np.arange(other.shape[0]), len(ret.row))
            col = np.tile(ret.col, other.shape[0])
            return coo_matrix((data.view(np.ndarray).ravel(), (row, col)),
                              shape=(other.shape[0], self.shape[1]),
                              copy=False)
        elif self.shape[1] == 1:
            if other.shape[0] == 1:  
                data = np.multiply(ret.data[:, None], other)
            elif other.shape[0] == self.shape[0]:  
                data = np.multiply(ret.data[:, None], other[ret.row])
            else:
                raise ValueError("inconsistent shapes")
            row = np.repeat(ret.row, other.shape[1])
            col = np.tile(np.arange(other.shape[1]), len(ret.col))
            return coo_matrix((data.view(np.ndarray).ravel(), (row, col)),
                              shape=(self.shape[0], other.shape[1]),
                              copy=False)
        elif other.shape[0] == 1 and self.shape[1] == other.shape[1]:
            data = np.multiply(ret.data, other[:, ret.col].ravel())
        elif other.shape[1] == 1 and self.shape[0] == other.shape[0]:
            data = np.multiply(ret.data, other[ret.row].ravel())
        else:
            raise ValueError("inconsistent shapes")
        ret.data = data.view(np.ndarray).ravel()
        return ret
    def _mul_vector(self, other):
        M, N = self.shape
        result = np.zeros(M, dtype=upcast_char(self.dtype.char,
                                               other.dtype.char))
        fn = getattr(_sparsetools, self.format + '_matvec')
        fn(M, N, self.indptr, self.indices, self.data, other, result)
        return result
    def _mul_multivector(self, other):
        M, N = self.shape
        n_vecs = other.shape[1]  
        result = np.zeros((M, n_vecs),
                          dtype=upcast_char(self.dtype.char, other.dtype.char))
        fn = getattr(_sparsetools, self.format + '_matvecs')
        fn(M, N, n_vecs, self.indptr, self.indices, self.data,
           other.ravel(), result.ravel())
        return result
    def _mul_sparse_matrix(self, other):
        M, K1 = self.shape
        K2, N = other.shape
        major_axis = self._swap((M, N))[0]
        other = self.__class__(other)  
        idx_dtype = get_index_dtype((self.indptr, self.indices,
                                     other.indptr, other.indices))
        fn = getattr(_sparsetools, self.format + '_matmat_maxnnz')
        nnz = fn(M, N,
                 np.asarray(self.indptr, dtype=idx_dtype),
                 np.asarray(self.indices, dtype=idx_dtype),
                 np.asarray(other.indptr, dtype=idx_dtype),
                 np.asarray(other.indices, dtype=idx_dtype))
        idx_dtype = get_index_dtype((self.indptr, self.indices,
                                     other.indptr, other.indices),
                                    maxval=nnz)
        indptr = np.empty(major_axis + 1, dtype=idx_dtype)
        indices = np.empty(nnz, dtype=idx_dtype)
        data = np.empty(nnz, dtype=upcast(self.dtype, other.dtype))
        fn = getattr(_sparsetools, self.format + '_matmat')
        fn(M, N, np.asarray(self.indptr, dtype=idx_dtype),
           np.asarray(self.indices, dtype=idx_dtype),
           self.data,
           np.asarray(other.indptr, dtype=idx_dtype),
           np.asarray(other.indices, dtype=idx_dtype),
           other.data,
           indptr, indices, data)
        return self.__class__((data, indices, indptr), shape=(M, N))
    def diagonal(self, k=0):
        rows, cols = self.shape
        if k <= -rows or k >= cols:
            return np.empty(0, dtype=self.data.dtype)
        fn = getattr(_sparsetools, self.format + "_diagonal")
        y = np.empty(min(rows + min(k, 0), cols - max(k, 0)),
                     dtype=upcast(self.dtype))
        fn(k, self.shape[0], self.shape[1], self.indptr, self.indices,
           self.data, y)
        return y
    diagonal.__doc__ = spmatrix.diagonal.__doc__
    def _maximum_minimum(self, other, npop, op_name, dense_check):
        if isscalarlike(other):
            if dense_check(other):
                warn("Taking maximum (minimum) with > 0 (< 0) number results"
                     " to a dense matrix.", SparseEfficiencyWarning,
                     stacklevel=3)
                other_arr = np.empty(self.shape, dtype=np.asarray(other).dtype)
                other_arr.fill(other)
                other_arr = self.__class__(other_arr)
                return self._binopt(other_arr, op_name)
            else:
                self.sum_duplicates()
                new_data = npop(self.data, np.asarray(other))
                mat = self.__class__((new_data, self.indices, self.indptr),
                                     dtype=new_data.dtype, shape=self.shape)
                return mat
        elif isdense(other):
            return npop(self.todense(), other)
        elif isspmatrix(other):
            return self._binopt(other, op_name)
        else:
            raise ValueError("Operands not compatible.")
    def maximum(self, other):
        return self._maximum_minimum(other, np.maximum,
                                     '_maximum_', lambda x: np.asarray(x) > 0)
    maximum.__doc__ = spmatrix.maximum.__doc__
    def minimum(self, other):
        return self._maximum_minimum(other, np.minimum,
                                     '_minimum_', lambda x: np.asarray(x) < 0)
    minimum.__doc__ = spmatrix.minimum.__doc__
    def sum(self, axis=None, dtype=None, out=None):
        if (not hasattr(self, 'blocksize') and
                axis in self._swap(((1, -1), (0, 2)))[0]):
            res_dtype = get_sum_dtype(self.dtype)
            ret = np.zeros(len(self.indptr) - 1, dtype=res_dtype)
            major_index, value = self._minor_reduce(np.add)
            ret[major_index] = value
            ret = asmatrix(ret)
            if axis % 2 == 1:
                ret = ret.T
            if out is not None and out.shape != ret.shape:
                raise ValueError('dimensions do not match')
            return ret.sum(axis=(), dtype=dtype, out=out)
        else:
            return spmatrix.sum(self, axis=axis, dtype=dtype, out=out)
    sum.__doc__ = spmatrix.sum.__doc__
    def _minor_reduce(self, ufunc, data=None):
        if data is None:
            data = self.data
        major_index = np.flatnonzero(np.diff(self.indptr))
        value = ufunc.reduceat(data,
                               downcast_intp_index(self.indptr[major_index]))
        return major_index, value
    def _get_intXint(self, row, col):
        M, N = self._swap(self.shape)
        major, minor = self._swap((row, col))
        indptr, indices, data = get_csr_submatrix(
            M, N, self.indptr, self.indices, self.data,
            major, major + 1, minor, minor + 1)
        return data.sum(dtype=self.dtype)
    def _get_sliceXslice(self, row, col):
        major, minor = self._swap((row, col))
        if major.step in (1, None) and minor.step in (1, None):
            return self._get_submatrix(major, minor, copy=True)
        return self._major_slice(major)._minor_slice(minor)
    def _get_arrayXarray(self, row, col):
        idx_dtype = self.indices.dtype
        M, N = self._swap(self.shape)
        major, minor = self._swap((row, col))
        major = np.asarray(major, dtype=idx_dtype)
        minor = np.asarray(minor, dtype=idx_dtype)
        val = np.empty(major.size, dtype=self.dtype)
        csr_sample_values(M, N, self.indptr, self.indices, self.data,
                          major.size, major.ravel(), minor.ravel(), val)
        if major.ndim == 1:
            return asmatrix(val)
        return self.__class__(val.reshape(major.shape))
    def _get_columnXarray(self, row, col):
        major, minor = self._swap((row, col))
        return self._major_index_fancy(major)._minor_index_fancy(minor)
    def _major_index_fancy(self, idx):
        idx_dtype = self.indices.dtype
        indices = np.asarray(idx, dtype=idx_dtype).ravel()
        _, N = self._swap(self.shape)
        M = len(indices)
        new_shape = self._swap((M, N))
        if M == 0:
            return self.__class__(new_shape)
        row_nnz = self.indptr[indices + 1] - self.indptr[indices]
        idx_dtype = self.indices.dtype
        res_indptr = np.zeros(M+1, dtype=idx_dtype)
        np.cumsum(row_nnz, out=res_indptr[1:])
        nnz = res_indptr[-1]
        res_indices = np.empty(nnz, dtype=idx_dtype)
        res_data = np.empty(nnz, dtype=self.dtype)
        csr_row_index(M, indices, self.indptr, self.indices, self.data,
                      res_indices, res_data)
        return self.__class__((res_data, res_indices, res_indptr),
                              shape=new_shape, copy=False)
    def _major_slice(self, idx, copy=False):
        if idx == slice(None):
            return self.copy() if copy else self
        M, N = self._swap(self.shape)
        start, stop, step = idx.indices(M)
        M = len(range(start, stop, step))
        new_shape = self._swap((M, N))
        if M == 0:
            return self.__class__(new_shape)
        start0, stop0 = start, stop
        if stop == -1 and start >= 0:
            stop0 = None
        start1, stop1 = start + 1, stop + 1
        row_nnz = self.indptr[start1:stop1:step] - \
            self.indptr[start0:stop0:step]
        idx_dtype = self.indices.dtype
        res_indptr = np.zeros(M+1, dtype=idx_dtype)
        np.cumsum(row_nnz, out=res_indptr[1:])
        if step == 1:
            all_idx = slice(self.indptr[start], self.indptr[stop])
            res_indices = np.array(self.indices[all_idx], copy=copy)
            res_data = np.array(self.data[all_idx], copy=copy)
        else:
            nnz = res_indptr[-1]
            res_indices = np.empty(nnz, dtype=idx_dtype)
            res_data = np.empty(nnz, dtype=self.dtype)
            csr_row_slice(start, stop, step, self.indptr, self.indices,
                          self.data, res_indices, res_data)
        return self.__class__((res_data, res_indices, res_indptr),
                              shape=new_shape, copy=False)
    def _minor_index_fancy(self, idx):
        idx_dtype = self.indices.dtype
        idx = np.asarray(idx, dtype=idx_dtype).ravel()
        M, N = self._swap(self.shape)
        k = len(idx)
        new_shape = self._swap((M, k))
        if k == 0:
            return self.__class__(new_shape)
        col_offsets = np.zeros(N, dtype=idx_dtype)
        res_indptr = np.empty_like(self.indptr)
        csr_column_index1(k, idx, M, N, self.indptr, self.indices,
                          col_offsets, res_indptr)
        col_order = np.argsort(idx).astype(idx_dtype, copy=False)
        nnz = res_indptr[-1]
        res_indices = np.empty(nnz, dtype=idx_dtype)
        res_data = np.empty(nnz, dtype=self.dtype)
        csr_column_index2(col_order, col_offsets, len(self.indices),
                          self.indices, self.data, res_indices, res_data)
        return self.__class__((res_data, res_indices, res_indptr),
                              shape=new_shape, copy=False)
    def _minor_slice(self, idx, copy=False):
        if idx == slice(None):
            return self.copy() if copy else self
        M, N = self._swap(self.shape)
        start, stop, step = idx.indices(N)
        N = len(range(start, stop, step))
        if N == 0:
            return self.__class__(self._swap((M, N)))
        if step == 1:
            return self._get_submatrix(minor=idx, copy=copy)
        return self._minor_index_fancy(np.arange(start, stop, step))
    def _get_submatrix(self, major=None, minor=None, copy=False):
        M, N = self._swap(self.shape)
        i0, i1 = _process_slice(major, M)
        j0, j1 = _process_slice(minor, N)
        if i0 == 0 and j0 == 0 and i1 == M and j1 == N:
            return self.copy() if copy else self
        indptr, indices, data = get_csr_submatrix(
            M, N, self.indptr, self.indices, self.data, i0, i1, j0, j1)
        shape = self._swap((i1 - i0, j1 - j0))
        return self.__class__((data, indices, indptr), shape=shape,
                              dtype=self.dtype, copy=False)
    def _set_intXint(self, row, col, x):
        i, j = self._swap((row, col))
        self._set_many(i, j, x)
    def _set_arrayXarray(self, row, col, x):
        i, j = self._swap((row, col))
        self._set_many(i, j, x)
    def _set_arrayXarray_sparse(self, row, col, x):
        self._zero_many(*self._swap((row, col)))
        M, N = row.shape  
        broadcast_row = M != 1 and x.shape[0] == 1
        broadcast_col = N != 1 and x.shape[1] == 1
        r, c = x.row, x.col
        x = np.asarray(x.data, dtype=self.dtype)
        if x.size == 0:
            return
        if broadcast_row:
            r = np.repeat(np.arange(M), len(r))
            c = np.tile(c, M)
            x = np.tile(x, M)
        if broadcast_col:
            r = np.repeat(r, N)
            c = np.tile(np.arange(N), len(c))
            x = np.repeat(x, N)
        i, j = self._swap((row[r, c], col[r, c]))
        self._set_many(i, j, x)
    def _setdiag(self, values, k):
        if 0 in self.shape:
            return
        M, N = self.shape
        broadcast = (values.ndim == 0)
        if k < 0:
            if broadcast:
                max_index = min(M + k, N)
            else:
                max_index = min(M + k, N, len(values))
            i = np.arange(max_index, dtype=self.indices.dtype)
            j = np.arange(max_index, dtype=self.indices.dtype)
            i -= k
        else:
            if broadcast:
                max_index = min(M, N - k)
            else:
                max_index = min(M, N - k, len(values))
            i = np.arange(max_index, dtype=self.indices.dtype)
            j = np.arange(max_index, dtype=self.indices.dtype)
            j += k
        if not broadcast:
            values = values[:len(i)]
        self[i, j] = values
    def _prepare_indices(self, i, j):
        M, N = self._swap(self.shape)
        def check_bounds(indices, bound):
            idx = indices.max()
            if idx >= bound:
                raise IndexError('index (%d) out of range (>= %d)' %
                                 (idx, bound))
            idx = indices.min()
            if idx < -bound:
                raise IndexError('index (%d) out of range (< -%d)' %
                                 (idx, bound))
        i = np.array(i, dtype=self.indices.dtype, copy=False, ndmin=1).ravel()
        j = np.array(j, dtype=self.indices.dtype, copy=False, ndmin=1).ravel()
        check_bounds(i, M)
        check_bounds(j, N)
        return i, j, M, N
    def _set_many(self, i, j, x):
        i, j, M, N = self._prepare_indices(i, j)
        x = np.array(x, dtype=self.dtype, copy=False, ndmin=1).ravel()
        n_samples = x.size
        offsets = np.empty(n_samples, dtype=self.indices.dtype)
        ret = csr_sample_offsets(M, N, self.indptr, self.indices, n_samples,
                                 i, j, offsets)
        if ret == 1:
            self.sum_duplicates()
            csr_sample_offsets(M, N, self.indptr, self.indices, n_samples,
                               i, j, offsets)
        if -1 not in offsets:
            self.data[offsets] = x
            return
        else:
            warn("Changing the sparsity structure of a {}_matrix is expensive."
                 " lil_matrix is more efficient.".format(self.format),
                 SparseEfficiencyWarning, stacklevel=3)
            mask = offsets > -1
            self.data[offsets[mask]] = x[mask]
            mask = ~mask
            i = i[mask]
            i[i < 0] += M
            j = j[mask]
            j[j < 0] += N
            self._insert_many(i, j, x[mask])
    def _zero_many(self, i, j):
        i, j, M, N = self._prepare_indices(i, j)
        n_samples = len(i)
        offsets = np.empty(n_samples, dtype=self.indices.dtype)
        ret = csr_sample_offsets(M, N, self.indptr, self.indices, n_samples,
                                 i, j, offsets)
        if ret == 1:
            self.sum_duplicates()
            csr_sample_offsets(M, N, self.indptr, self.indices, n_samples,
                               i, j, offsets)
        self.data[offsets[offsets > -1]] = 0
    def _insert_many(self, i, j, x):
        order = np.argsort(i, kind='mergesort')  
        i = i.take(order, mode='clip')
        j = j.take(order, mode='clip')
        x = x.take(order, mode='clip')
        do_sort = self.has_sorted_indices
        idx_dtype = get_index_dtype((self.indices, self.indptr),
                                    maxval=(self.indptr[-1] + x.size))
        self.indptr = np.asarray(self.indptr, dtype=idx_dtype)
        self.indices = np.asarray(self.indices, dtype=idx_dtype)
        i = np.asarray(i, dtype=idx_dtype)
        j = np.asarray(j, dtype=idx_dtype)
        indices_parts = []
        data_parts = []
        ui, ui_indptr = np.unique(i, return_index=True)
        ui_indptr = np.append(ui_indptr, len(j))
        new_nnzs = np.diff(ui_indptr)
        prev = 0
        for c, (ii, js, je) in enumerate(zip(ui, ui_indptr, ui_indptr[1:])):
            start = self.indptr[prev]
            stop = self.indptr[ii]
            indices_parts.append(self.indices[start:stop])
            data_parts.append(self.data[start:stop])
            uj, uj_indptr = np.unique(j[js:je][::-1], return_index=True)
            if len(uj) == je - js:
                indices_parts.append(j[js:je])
                data_parts.append(x[js:je])
            else:
                indices_parts.append(j[js:je][::-1][uj_indptr])
                data_parts.append(x[js:je][::-1][uj_indptr])
                new_nnzs[c] = len(uj)
            prev = ii
        start = self.indptr[ii]
        indices_parts.append(self.indices[start:])
        data_parts.append(self.data[start:])
        self.indices = np.concatenate(indices_parts)
        self.data = np.concatenate(data_parts)
        nnzs = np.empty(self.indptr.shape, dtype=idx_dtype)
        nnzs[0] = idx_dtype(0)
        indptr_diff = np.diff(self.indptr)
        indptr_diff[ui] += new_nnzs
        nnzs[1:] = indptr_diff
        self.indptr = np.cumsum(nnzs, out=nnzs)
        if do_sort:
            self.has_sorted_indices = False
            self.sort_indices()
        self.check_format(full_check=False)
    def tocoo(self, copy=True):
        major_dim, minor_dim = self._swap(self.shape)
        minor_indices = self.indices
        major_indices = np.empty(len(minor_indices), dtype=self.indices.dtype)
        _sparsetools.expandptr(major_dim, self.indptr, major_indices)
        row, col = self._swap((major_indices, minor_indices))
        from .coo import coo_matrix
        return coo_matrix((self.data, (row, col)), self.shape, copy=copy,
                          dtype=self.dtype)
    tocoo.__doc__ = spmatrix.tocoo.__doc__
    def toarray(self, order=None, out=None):
        if out is None and order is None:
            order = self._swap('cf')[0]
        out = self._process_toarray_args(order, out)
        if not (out.flags.c_contiguous or out.flags.f_contiguous):
            raise ValueError('Output array must be C or F contiguous')
        if out.flags.c_contiguous:
            x = self.tocsr()
            y = out
        else:
            x = self.tocsc()
            y = out.T
        M, N = x._swap(x.shape)
        csr_todense(M, N, x.indptr, x.indices, x.data, y)
        return out
    toarray.__doc__ = spmatrix.toarray.__doc__
    def eliminate_zeros(self):
        M, N = self._swap(self.shape)
        _sparsetools.csr_eliminate_zeros(M, N, self.indptr, self.indices,
                                         self.data)
        self.prune()  
    def __get_has_canonical_format(self):
        if not getattr(self, '_has_sorted_indices', True):
            self._has_canonical_format = False
        elif not hasattr(self, '_has_canonical_format'):
            self.has_canonical_format = bool(
                _sparsetools.csr_has_canonical_format(
                    len(self.indptr) - 1, self.indptr, self.indices))
        return self._has_canonical_format
    def __set_has_canonical_format(self, val):
        self._has_canonical_format = bool(val)
        if val:
            self.has_sorted_indices = True
    has_canonical_format = property(fget=__get_has_canonical_format,
                                    fset=__set_has_canonical_format)
    def sum_duplicates(self):
        if self.has_canonical_format:
            return
        self.sort_indices()
        M, N = self._swap(self.shape)
        _sparsetools.csr_sum_duplicates(M, N, self.indptr, self.indices,
                                        self.data)
        self.prune()  
        self.has_canonical_format = True
    def __get_sorted(self):
        if not hasattr(self, '_has_sorted_indices'):
            self._has_sorted_indices = bool(
                _sparsetools.csr_has_sorted_indices(
                    len(self.indptr) - 1, self.indptr, self.indices))
        return self._has_sorted_indices
    def __set_sorted(self, val):
        self._has_sorted_indices = bool(val)
    has_sorted_indices = property(fget=__get_sorted, fset=__set_sorted)
    def sorted_indices(self):
        A = self.copy()
        A.sort_indices()
        return A
    def sort_indices(self):
        if not self.has_sorted_indices:
            _sparsetools.csr_sort_indices(len(self.indptr) - 1, self.indptr,
                                          self.indices, self.data)
            self.has_sorted_indices = True
    def prune(self):
        major_dim = self._swap(self.shape)[0]
        if len(self.indptr) != major_dim + 1:
            raise ValueError('index pointer has invalid length')
        if len(self.indices) < self.nnz:
            raise ValueError('indices array has fewer than nnz elements')
        if len(self.data) < self.nnz:
            raise ValueError('data array has fewer than nnz elements')
        self.indices = _prune_array(self.indices[:self.nnz])
        self.data = _prune_array(self.data[:self.nnz])
    def resize(self, *shape):
        shape = check_shape(shape)
        if hasattr(self, 'blocksize'):
            bm, bn = self.blocksize
            new_M, rm = divmod(shape[0], bm)
            new_N, rn = divmod(shape[1], bn)
            if rm or rn:
                raise ValueError("shape must be divisible into %s blocks. "
                                 "Got %s" % (self.blocksize, shape))
            M, N = self.shape[0] // bm, self.shape[1] // bn
        else:
            new_M, new_N = self._swap(shape)
            M, N = self._swap(self.shape)
        if new_M < M:
            self.indices = self.indices[:self.indptr[new_M]]
            self.data = self.data[:self.indptr[new_M]]
            self.indptr = self.indptr[:new_M + 1]
        elif new_M > M:
            self.indptr = np.resize(self.indptr, new_M + 1)
            self.indptr[M + 1:].fill(self.indptr[M])
        if new_N < N:
            mask = self.indices < new_N
            if not np.all(mask):
                self.indices = self.indices[mask]
                self.data = self.data[mask]
                major_index, val = self._minor_reduce(np.add, mask)
                self.indptr.fill(0)
                self.indptr[1:][major_index] = val
                np.cumsum(self.indptr, out=self.indptr)
        self._shape = shape
    resize.__doc__ = spmatrix.resize.__doc__
    def _with_data(self, data, copy=True):
        if copy:
            return self.__class__((data, self.indices.copy(),
                                   self.indptr.copy()),
                                  shape=self.shape,
                                  dtype=data.dtype)
        else:
            return self.__class__((data, self.indices, self.indptr),
                                  shape=self.shape, dtype=data.dtype)
    def _binopt(self, other, op):
        other = self.__class__(other)
        fn = getattr(_sparsetools, self.format + op + self.format)
        maxnnz = self.nnz + other.nnz
        idx_dtype = get_index_dtype((self.indptr, self.indices,
                                     other.indptr, other.indices),
                                    maxval=maxnnz)
        indptr = np.empty(self.indptr.shape, dtype=idx_dtype)
        indices = np.empty(maxnnz, dtype=idx_dtype)
        bool_ops = ['_ne_', '_lt_', '_gt_', '_le_', '_ge_']
        if op in bool_ops:
            data = np.empty(maxnnz, dtype=np.bool_)
        else:
            data = np.empty(maxnnz, dtype=upcast(self.dtype, other.dtype))
        fn(self.shape[0], self.shape[1],
           np.asarray(self.indptr, dtype=idx_dtype),
           np.asarray(self.indices, dtype=idx_dtype),
           self.data,
           np.asarray(other.indptr, dtype=idx_dtype),
           np.asarray(other.indices, dtype=idx_dtype),
           other.data,
           indptr, indices, data)
        A = self.__class__((data, indices, indptr), shape=self.shape)
        A.prune()
        return A
    def _divide_sparse(self, other):
        if other.shape != self.shape:
            raise ValueError('inconsistent shapes')
        r = self._binopt(other, '_eldiv_')
        if np.issubdtype(r.dtype, np.inexact):
            out = np.empty(self.shape, dtype=self.dtype)
            out.fill(np.nan)
            row, col = other.nonzero()
            out[row, col] = 0
            r = r.tocoo()
            out[r.row, r.col] = r.data
            out = matrix(out)
        else:
            out = r
        return out

