        parser = etree.HTMLParser() if parser_type == 'html' else etree.XMLParser(dtd_validation=validate)
        tree = etree.parse(BytesIO(self.content), parser)
        matches = tree.xpath(xpath_query)
        if not matches:
            return default
        match = matches[0]
        return match.text

class Pieces:
    PADDING=10
    OUTLINE=2
    def __init__(self,row,col,color):
        self.row=row
        self.col=col
        self.color=color
        self.king=False
        self.x=0
        self.y=0
        self.calc_position()
    def calc_position(self):
        self.x=SQUARE_SIZE*self.col+SQUARE_SIZE//2
        self.y=SQUARE_SIZE*self.row+SQUARE_SIZE//2
    def make_king(self):
        self.king=True
    def draw(self,window):
        radius=SQUARE_SIZE//2-self.PADDING
        pygame.draw.circle(window,GREY,(self.x,self.y),radius+self.OUTLINE)
        pygame.draw.circle(window,self.color,(self.x,self.y),radius)
        if self.king:
            window.blit(CROWN,(self.x-CROWN.get_width()//2,self.y-CROWN.get_height()//2))
    def move(self,row,col):
        self.row=row
        self.col=col
        self.calc_position() 
    def __repr__(self):
        return str(self.color)

