class AsyncWriteCacheClient(BaseCacheClient):
    def __init__(self, client, writer_queue_size, writer_workers = None, overflow = False, threadpool = None,
            defer_threadpool = None, writer_threadpool = None):
        self.client = client
        self.writer_queue_size = writer_queue_size
        self.writer_workers = writer_workers if writer_workers is not None else multiprocessing.cpu_count()
        self.writer = None
        self.overflow = overflow
        self.spawning_lock = threading.Lock()
        self._defer_threadpool = defer_threadpool or threadpool
        self._writer_threadpool = writer_threadpool or threadpool
    def assert_started(self):
        if self.writer is None:
            with self.spawning_lock:
                if self.writer is None:
                    self.writer = AsyncCacheWriterPool(
                        self.writer_queue_size,
                        self.writer_workers,
                        self.client,
                        self.overflow,
                        defer_threadpool = self._defer_threadpool,
                        writer_threadpool = self._writer_threadpool)
    def is_started(self):
        return self.writer is not None
    def start(self):
        if self.writer is not None:
            raise AssertionError("Starting AsyncCacheClient twice")
        self.assert_started()
    def stop(self, abort_tasks=False):
        if self.writer is not None:
            if not abort_tasks:
                self.writer.join()
            self.writer.terminate()
    @property
    def is_async(self):
        return True
    @property
    def capacity(self):
        return (self.client.capacity, self.writer.capacity if self.writer is not None else 0)
    @property
    def usage(self):
        return (self.client.usage, self.writer.usage if self.writer is not None else 0)
    def put(self, key, value, ttl, **kw):
        self.assert_started()
        self.writer.put(key, value, ttl, **kw)
    def renew(self, key, ttl, **kw):
        self.assert_started()
        self.writer.renew(key, ttl, **kw)
    def delete(self, key):
        self.assert_started()
        self.writer.delete(key)
    def expire(self, key):
        self.assert_started()
        self.writer.expire(key)
    def clear(self):
        if self.is_started():
            self.writer.clear()
    def purge(self, timeout = None):
        if self.is_started():
            self.writer.purge()
    def getTtl(self, key, default = NONE,
            _DELETE = _DELETE, _EXPIRE = _EXPIRE, _RENEW = _RENEW, _CLEAR = _CLEAR,
            NONE = NONE, _NONE = _NONE,
            hasattr = hasattr,
            **kw):
        ettl = None
        writer = self.writer
        if writer is not None: 
            value = writer.getTtl(key, _NONE)
            if value is not _NONE:
                value, ttl, _ = value
                if value is _DELETE:
                    if default is NONE:
                        raise CacheMissError(key)
                    else:
                        return default, -1
                elif value is _EXPIRE:
                    ettl = -1
                elif value is _RENEW:
                    ettl = ttl
                elif not hasattr(value, 'undefer'):
                    return value, ttl
            if writer._contains(_CLEAR):
                if default is NONE:
                    raise CacheMissError(key)
                else:
                    return default, -1
        value, ttl = self.client.getTtl(key, default, **kw)
        if ettl is not None:
            ttl = ettl
        if value is NONE:
            raise CacheMissError(key)
        else:
            return value, ttl
    def get(self, key, default = NONE, ttl_skip = None,
            _DELETE = _DELETE, _EXPIRE = _EXPIRE, _RENEW = _RENEW, _CLEAR = _CLEAR,
            NONE = NONE, _NONE = _NONE,
            hasattr = hasattr,
            **kw):
        writer = self.writer
        if writer is not None: 
            value = writer.getTtl(key, _NONE)
            if value is not _NONE:
                value, ttl, _ = value
                if value is _DELETE or value is _EXPIRE:
                    if default is NONE:
                        raise CacheMissError(key)
                    else:
                        return default
                elif value is _RENEW and (ttl_skip is None or ttl >= ttl_skip):
                    ttl_skip = None
                elif not hasattr(value, 'undefer'):
                    return value
            if writer._contains(_CLEAR):
                if default is NONE:
                    raise CacheMissError(key)
                else:
                    return default
        return self.client.get(key, default, ttl_skip = ttl_skip, **kw)
    def getTtlMulti(self, keys, default = NONE,
            _DELETE = _DELETE, _EXPIRE = _EXPIRE, _RENEW = _RENEW, _CLEAR = _CLEAR,
            NONE = NONE, _NONE = _NONE,
            hasattr = hasattr,
            **kw):
        ettl = {}
        writer = self.writer
        default_rv = (default, -1)
        if writer is not None: 
            wgetTtl = writer.getTtl
            nkeys = []
            nkeys_append = nkeys.append
            for key in keys:
                value = wgetTtl(key, _NONE)
                if value is not _NONE:
                    value, ttl, _ = value
                    if value is _DELETE:
                        yield key, default_rv
                        continue
                    elif value is _EXPIRE:
                        ettl[key] = -1
                    elif value is _RENEW:
                        ettl[key] = ttl
                    elif not hasattr(value, 'undefer'):
                        yield key, (value, ttl)
                        continue
                nkeys_append(key)
            keys = nkeys
            del nkeys, nkeys_append
            if writer._contains(_CLEAR):
                for key in keys:
                    yield key, default_rv
                return
        ettlget = ettl.get
        for key, (value, ttl) in self.client.getTtlMulti(keys, default, **kw):
            ttl = ettlget(key, ttl)
            yield key, (value, ttl)
    def getMulti(self, keys, default = NONE, ttl_skip = None,
            _DELETE = _DELETE, _EXPIRE = _EXPIRE, _RENEW = _RENEW, _CLEAR = _CLEAR,
            NONE = NONE, _NONE = _NONE,
            hasattr = hasattr,
            **kw):
        ettl = []
        ettl_append = ettl.append
        writer = self.writer
        if writer is not None: 
            wgetTtl = writer.getTtl
            nkeys = []
            nkeys_append = nkeys.append
            for key in keys:
                value = wgetTtl(key, _NONE)
                if value is not _NONE:
                    value, ttl, _ = value
                    if value is _DELETE or value is _EXPIRE:
                        yield key, default
                        continue
                    elif value is _RENEW and (ttl_skip is None or ttl >= ttl_skip):
                        if ttl_skip is not None:
                            ettl_append(key)
                            continue
                    elif not hasattr(value, 'undefer'):
                        yield key, value
                        continue
                nkeys_append(key)
            keys = nkeys
            del nkeys, nkeys_append
            if writer._contains(_CLEAR):
                for key in keys:
                    yield key, default
                for key in ettl:
                    yield key, default
                return
        if ettl:
            for key, value in self.client.getMulti(keys, default, **kw):
                yield key, value
        if keys:
            for key, value in self.client.getMulti(keys, default, ttl_skip = ttl_skip, **kw):
                yield key, value
    def promote(self, key, *p, **kw):
        if self.is_started() and self.writer.contains(key):
            return
        else:
            return self.client.promote(key, *p, **kw)
    def wait(self, key, timeout = None):
        if self.is_started() and self.writer.contains(key):
            self.writer.waitkey(key, timeout)
    def contains(self, key, ttl = None, **kw):
        if self.is_started():
            if self.writer.contains(key):
                return True
            else:
                return self.client.contains(key, ttl, **kw)
        else:
            return self.client.contains(key, ttl, **kw)
    def register_cleanup(self, task):
        self.writer.register_cleanup(task)
    def __str__(self):
        return "<%s of %r>" % (self.__class__.__name__, self.client)
    def __repr__(self):
        return str(self)

class Clock:
    def __init__(self, hour, minute):
        self.minutes = (60 * hour + minute) % 1440
    def __repr__(self):
        return f"{self.minutes//60:02}:{self.minutes%60:02}"
    def __eq__(self, other):
        return self.minutes == other.minutes
    def __add__(self, minutes):
        return Clock(0, (self.minutes + minutes) % 1440)
    def __sub__(self, minutes):
        return Clock(0, (self.minutes - minutes) % 1440)

class ArrayRecordDataSource(AbcSequence):
  dataset_info: dataset_info_lib.DatasetInfo
  split: splits_lib.Split = None
  decoders: Optional[type_utils.TreeDict[decode.partial_decode.DecoderArg]] = (
      None
  )
  data_source: Any = dataclasses.field(init=False)
  length: int = dataclasses.field(init=False)
  def __post_init__(self):
    file_format = self.dataset_info.file_format
    if file_format != file_adapters.FileFormat.ARRAY_RECORD:
      raise NotImplementedError(
          f'No random access data source for file format {file_format}. Please,'
          ' generate your data using `tfds.builder(...,'
          f' file_format={file_adapters.FileFormat.ARRAY_RECORD})`.'
      )
    split_infos = self.dataset_info.splits.values()
    splits_dict = splits_lib.SplitDict(split_infos=split_infos)
    file_instructions = splits_dict[self.split].file_instructions
    self.data_source = array_record_data_source.ArrayRecordDataSource(
        file_instructions
    )
    self.length = len(self.data_source)
  def __len__(self) -> int:
    return self.length
  def __iter__(self):
    for i in range(self.length):
      yield self[i]
  def __getitem__(self, record_key: int) -> Any:
    if not isinstance(record_key, int):
      logging.error(
          'Calling ArrayRecordDataSource.__getitem__() with sequence '
          'of record keys (%s) is deprecated. Either pass a single '
          'integer or switch to __getitems__().',
          record_key,
      )
      return self.__getitems__(record_key)
    record = self.data_source[record_key]
    return self.dataset_info.features.deserialize_example_np(
        record, decoders=self.decoders
    )
  def __getitems__(self, record_keys: Sequence[int]) -> Sequence[Any]:
    records = self.data_source.__getitems__(record_keys)
    features = self.dataset_info.features
    if len(record_keys) != len(records):
      raise IndexError(
          f'Requested {len(record_keys)} records but got'
          f' {len(records)} records.'
          f'{record_keys=}, {records=}'
      )
    return [
        features.deserialize_example_np(record, decoders=self.decoders)
        for record in records
    ]
  def __repr__(self) -> str:
    decoders_repr = (
        tree.map_structure(type, self.decoders) if self.decoders else None
    )
    return (
        f'DataSource(name={self.dataset_info.name}, '
        f'split={self.split!r}, '
        f'decoders={decoders_repr})'
    )

class Lambda(NoOp):
    def __init__(self, image=None, mask=None, keypoint=None, bbox=None, name=None, always_apply=False, p=1.0):
        super(Lambda, self).__init__(always_apply, p)
        self.name = name
        self.custom_apply_fns = {target_name: F.noop for target_name in ("image", "mask", "keypoint", "bbox")}
        for target_name, custom_apply_fn in {"image": image, "mask": mask, "keypoint": keypoint, "bbox": bbox}.items():
            if custom_apply_fn is not None:
                if isinstance(custom_apply_fn, LambdaType) and custom_apply_fn.__name__ == "<lambda>":
                    warnings.warn(
                        "Using lambda is incompatible with multiprocessing. "
                        "Consider using regular functions or partial()."
                    )
                self.custom_apply_fns[target_name] = custom_apply_fn
    def apply(self, img, **params):
        fn = self.custom_apply_fns["image"]
        return fn(img, **params)
    def apply_to_mask(self, mask, **params):
        fn = self.custom_apply_fns["mask"]
        return fn(mask, **params)
    def apply_to_bbox(self, bbox, **params):
        fn = self.custom_apply_fns["bbox"]
        return fn(bbox, **params)
    def apply_to_keypoint(self, keypoint, **params):
        fn = self.custom_apply_fns["keypoint"]
        return fn(keypoint, **params)
    def _to_dict(self):
        if self.name is None:
            raise ValueError(
                "To make a Lambda transform serializable you should provide the `name` argument, "
                "e.g. `Lambda(name='my_transform', image=<some func>, ...)`."
            )
        return {"__type__": "Lambda", "__name__": self.name}
    def __repr__(self):
        state = {"name": self.name}
        state.update(self.custom_apply_fns.items())
        state.update(self.get_base_init_args())
        return "{name}({args})".format(name=self.__class__.__name__, args=format_args(state))

