class OrderedSet(collections.abc.MutableSet):
    def __init__(self, *args):
        if not args:
            iterable = []
        elif len(args) == 1:
            iterable = args[0]
        else:
            raise TypeError('%s expected at most 1 arguments, got %s' %
                            type(self).__name__, len(args))
        if not isinstance(iterable, collections.abc.Iterable):
            raise TypeError("'%s' object is not iterable" %
                            type(iterable).__name__)
        self.__data = collections.OrderedDict(
            itertools.zip_longest(iterable, [], fillvalue=None)
        )
    def __repr__(self):
        vals = self.__data.keys()
        if not vals:
            return type(self).__name__ + '()'
        else:
            return '{' + ', '.join(str(v) for v in vals) + '}'
    def __contains__(self, item):
        return item in self.__data
    def __iter__(self):
        return iter(self.__data)
    def __len__(self):
        return len(self.__data)
    def __eq__(self, other):
        if not isinstance(other, collections.abc.Set):
            return NotImplemented
        return set(self.__data.keys()) == other
    def __gt__(self, other):
        if not isinstance(other, collections.abc.Set):
            return NotImplemented
        return set(self.__data.keys()) > other
    def __and__(self, other):
        if not isinstance(other, collections.abc.Set):
            return NotImplemented
        return set(self.__data.keys()) & other
    def __or__(self, other):
        if not isinstance(other, collections.abc.Set):
            return NotImplemented
        return set(self.__data.keys()) | other
    def __sub__(self, other):
        if not isinstance(other, collections.abc.Set):
            return NotImplemented
        return set(self.__data.keys()) - other
    def __xor__(self, other):
        if not isinstance(other, collections.abc.Set):
            return NotImplemented
        return set(self.__data.keys()) ^ other
    def isdisjoint(self, other):
        if not isinstance(other, collections.abc.Set):
            return NotImplemented
        return set(self.__data.keys()).isdisjoint(other)
    def issubset(self, other):
        return self <= other
    def issuperset(self, other):
        return self >= other
    def symmetric_difference(self, other):
        return self ^ other
    def union(self, *others):
        ret = type(self)(self)
        for s in others:
            ret |= s
        return ret
    def intersection(self, *others):
        ret = type(self)(self)
        for s in others:
            ret &= s
        return ret
    def difference(self, *others):
        ret = type(self)(self)
        for s in others:
            ret -= s
        return ret
    def add(self, elem):
        self.__data[elem] = None
    def remove(self, elem):
        del self.__data[elem]
    def discard(self, elem):
        try:
            self.remove(elem)
        except KeyError:
            pass
    def pop(self):
        return self.__data.popitem()[0]
    def clear(self):
        self.__data.clear()
    def __ior__(self, other):
        if not isinstance(other, collections.abc.Set):
            return NotImplemented
        for e in other:
            self.add(e)
        return self
    def __iand__(self, other):
        if not isinstance(other, collections.abc.Set):
            return NotImplemented
        discard_list = [e for e in self if e not in other]
        for e in discard_list:
            self.discard(e)
        return self
    def __isub__(self, other):
        if not isinstance(other, collections.abc.Set):
            return NotImplemented
        for e in other:
            self.discard(e)
        return self
    def __ixor__(self, other):
        if not isinstance(other, collections.abc.Set):
            return NotImplemented
        discard_list = [e for e in self if e in other]
        for e in discard_list:
            self.discard(e)
        return self
    def __reversed__(self):
        return reversed(self.__data.keys())

