class ArraySpec(object):
  __slots__ = ('_shape', '_dtype', '_name')
  def __init__(self, shape, dtype, name=None):
    self._shape = tuple(shape)
    self._dtype = np.dtype(dtype)
    self._name = name
  @property
  def shape(self):
    return self._shape
  @property
  def dtype(self):
    return self._dtype
  @property
  def name(self):
    return self._name
  def __repr__(self):
    return 'ArraySpec(shape={}, dtype={}, name={})'.format(self.shape,
                                                           repr(self.dtype),
                                                           repr(self.name))
  def __eq__(self, other):
    if not isinstance(other, ArraySpec):
      return False
    return self.shape == other.shape and self.dtype == other.dtype
  def __ne__(self, other):
    return not self == other
  def _fail_validation(self, message, *args):
    message %= args
    if self.name:
      message += ' for spec %s' % self.name
    raise ValueError(message)
  def validate(self, value):
    value = np.asarray(value)
    if value.shape != self.shape:
      self._fail_validation(
          'Expected shape %r but found %r', self.shape, value.shape)
    if value.dtype != self.dtype:
      self._fail_validation(
          'Expected dtype %s but found %s', self.dtype, value.dtype)
  def generate_value(self):
    return np.zeros(shape=self.shape, dtype=self.dtype)

class BoundedArraySpec(ArraySpec):
  __slots__ = ('_minimum', '_maximum')
  def __init__(self, shape, dtype, minimum, maximum, name=None):
    super(BoundedArraySpec, self).__init__(shape, dtype, name)
    try:
      np.broadcast_to(minimum, shape=shape)
    except ValueError as numpy_exception:
      raise ValueError('minimum is not compatible with shape. '
                       'Message: {!r}.'.format(numpy_exception))
    try:
      np.broadcast_to(maximum, shape=shape)
    except ValueError as numpy_exception:
      raise ValueError('maximum is not compatible with shape. '
                       'Message: {!r}.'.format(numpy_exception))
    self._minimum = np.array(minimum)
    self._minimum.setflags(write=False)
    self._maximum = np.array(maximum)
    self._maximum.setflags(write=False)
  @property
  def minimum(self):
    return self._minimum
  @property
  def maximum(self):
    return self._maximum
  def __repr__(self):
    template = ('BoundedArraySpec(shape={}, dtype={}, name={}, '
                'minimum={}, maximum={})')
    return template.format(self.shape, repr(self.dtype), repr(self.name),
                           self._minimum, self._maximum)
  def __eq__(self, other):
    if not isinstance(other, BoundedArraySpec):
      return False
    return (super(BoundedArraySpec, self).__eq__(other) and
            (self.minimum == other.minimum).all() and
            (self.maximum == other.maximum).all())
  def validate(self, value):
    value = np.asarray(value)
    super(BoundedArraySpec, self).validate(value)
    if (value < self.minimum).any() or (value > self.maximum).any():
      self._fail_validation(
          'Values were not all within bounds %s <= value <= %s',
          self.minimum, self.maximum)
  def generate_value(self):
    return (np.ones(shape=self.shape, dtype=self.dtype) *
            self.dtype.type(self.minimum))

class ObjectId(object):
    _inc = random.randint(0, 0xFFFFFF)
    _inc_lock = threading.Lock()
    _machine_bytes = _machine_bytes()
    __slots__ = ('__id')
    def __init__(self, oid=None):
        if oid is None:
            self.__generate()
        else:
            self.__validate(oid)
    @classmethod
    def from_datetime(cls, generation_time):
        if generation_time.utcoffset() is not None:
            generation_time = generation_time - generation_time.utcoffset()
        ts = calendar.timegm(generation_time.timetuple())
        oid = struct.pack(">i", int(ts)) + ZERO * 8
        return cls(oid)
    @classmethod
    def is_valid(cls, oid):
        try:
            ObjectId(oid)
            return True
        except (InvalidId, TypeError):
            return False
    def __generate(self):
        oid = EMPTY
        oid += struct.pack(">i", int(time.time()))
        oid += ObjectId._machine_bytes
        oid += struct.pack(">H", os.getpid() % 0xFFFF)
        ObjectId._inc_lock.acquire()
        oid += struct.pack(">i", ObjectId._inc)[1:4]
        ObjectId._inc = (ObjectId._inc + 1) % 0xFFFFFF
        ObjectId._inc_lock.release()
        self.__id = oid
    def __validate(self, oid):
        if isinstance(oid, ObjectId):
            self.__id = oid.__id
        elif isinstance(oid, string_types):
            if len(oid) == 12:
                if isinstance(oid, binary_type):
                    self.__id = oid
                else:
                    raise InvalidId("%s is not a valid ObjectId" % oid)
            elif len(oid) == 24:
                try:
                    self.__id = bytes_from_hex(oid)
                except (TypeError, ValueError):
                    raise InvalidId("%s is not a valid ObjectId" % oid)
            else:
                raise InvalidId("%s is not a valid ObjectId" % oid)
        else:
            raise TypeError("id must be an instance of (%s, %s, ObjectId), "
                            "not %s" % (binary_type.__name__,
                                        text_type.__name__, type(oid)))
    @property
    def binary(self):
        return self.__id
    @property
    def generation_time(self):
        t = struct.unpack(">i", self.__id[0:4])[0]
        return datetime.datetime.fromtimestamp(t, utc)
    def __getstate__(self):
        return self.__id
    def __setstate__(self, value):
        if isinstance(value, dict):
            oid = value["_ObjectId__id"]
        else:
            oid = value
        if PY3 and isinstance(oid, text_type):
            self.__id = oid.encode('latin-1')
        else:
            self.__id = oid
    def __str__(self):
        return binascii.hexlify(self.__id).decode()
    def __repr__(self):
        return "ObjectId('%s')" % (str(self),)
    def __eq__(self, other):
        if isinstance(other, ObjectId):
            return self.__id == other.__id
        return NotImplemented
    def __ne__(self,other):
        if isinstance(other, ObjectId):
            return self.__id != other.__id
        return NotImplemented
    def __lt__(self, other):
        if isinstance(other, ObjectId):
            return self.__id < other.__id
        return NotImplemented
    def __le__(self, other):
        if isinstance(other, ObjectId):
            return self.__id <= other.__id
        return NotImplemented
    def __gt__(self, other):
        if isinstance(other, ObjectId):
            return self.__id > other.__id
        return NotImplemented
    def __ge__(self, other):
        if isinstance(other, ObjectId):
            return self.__id >= other.__id
        return NotImplemented
    def __hash__(self):
        return hash(self.__id)

class DFAState(object):
    def __init__(self, nfaset, final):
        assert isinstance(nfaset, dict)
        assert isinstance(next(iter(nfaset)), NFAState)
        assert isinstance(final, NFAState)
        self.nfaset = nfaset
        self.isfinal = final in nfaset
        self.arcs = {} 
    def addarc(self, next, label):
        assert isinstance(label, str)
        assert label not in self.arcs
        assert isinstance(next, DFAState)
        self.arcs[label] = next
    def unifystate(self, old, new):
        for label, next in self.arcs.items():
            if next is old:
                self.arcs[label] = new
    def __eq__(self, other):
        assert isinstance(other, DFAState)
        if self.isfinal != other.isfinal:
            return False
        if len(self.arcs) != len(other.arcs):
            return False
        for label, next in self.arcs.items():
            if next is not other.arcs.get(label):
                return False
        return True
    __hash__ = None

