class ODMSession(object):
    _registry = {}
    def __init__(self, doc_session=None, bind=None, extensions=None,
                 autoflush=False):
        if doc_session is None:
            doc_session = Session(bind)
        if extensions is None: extensions = []
        self.impl = doc_session
        self.uow = UnitOfWork(self)
        self.imap = IdentityMap()
        self.extensions = [ e(self) for e in extensions ]
        self.autoflush = autoflush
    def register_extension(self, extension):
        self.extensions.append(extension(self))
    @property
    def bind(self):
        return self.impl.bind
    @property
    def db(self):
        return self.impl.db
    @classmethod
    def by_name(cls, name):
        if name in cls._registry:
            result = cls._registry[name]
        else:
            result = cls._registry[name] = cls(bind=Session._datastores.get(name))
        return result
    def mapper(self, cls, collection, **kwargs):
        return mapper(
            cls, collection=collection, session=self, **kwargs)
    def save(self, obj):
        self.uow.save(obj)
        self.imap.save(obj)
        state(obj).session = self
    def expunge(self, obj):
        self.uow.expunge(obj)
        self.imap.expunge(obj)
        state(obj).session = None
    def refresh(self, obj):
        self.expunge(obj)
        return self.find(obj.__class__, {'_id': obj._id}, refresh=True).first()
    @_with_hooks('flush')
    def flush(self, obj=None):
        if self.impl.db is None: return
        if obj is None:
            self.uow.flush()
        else:
            st = state(obj)
            if st.status == st.new:
                self.insert_now(obj, st)
            elif st.status == st.dirty:
                self.update_now(obj, st)
            elif st.status == st.deleted:
                self.delete_now(obj, st)
    @_with_hooks('insert')
    def insert_now(self, obj, st, **kwargs):
        mapper(obj).insert(obj, st, self, **kwargs)
    @_with_hooks('update')
    def update_now(self, obj, st, **kwargs):
        mapper(obj).update(obj, st, self, **kwargs)
    @_with_hooks('delete')
    def delete_now(self, obj, st, **kwargs):
        mapper(obj).delete(obj, st, self, **kwargs)
    def clear(self):
        for obj in self.uow:
            state(obj).session = None
        self.uow.clear()
        self.imap.clear()
    def close(self):
        self.clear()
    def get(self, cls, idvalue):
        result = self.imap.get(cls, idvalue)
        if result is None:
            result = self.find(cls, dict(_id=idvalue)).first()
        return result
    def find(self, cls, *args, **kwargs):
        if self.autoflush:
            self.flush()
        refresh = kwargs.pop('refresh', False)
        decorate = kwargs.pop('decorate', None)
        m = mapper(cls)
        projection = kwargs.pop('fields', kwargs.pop('projection', None))
        if projection is not None:
            kwargs['projection'] = projection
        ming_cursor = self.impl.find(m.collection, *args, **kwargs)
        odm_cursor = ODMCursor(self, cls, ming_cursor, refresh=refresh, decorate=decorate,
                               fields=kwargs.get('projection'))
        _call_hook(self, 'cursor_created', odm_cursor, 'find', cls, *args, **kwargs)
        return odm_cursor
    def find_and_modify(self, cls, *args, **kwargs):
        decorate = kwargs.pop('decorate', None)
        if self.autoflush:
            self.flush()
        m = mapper(cls)
        obj = self.impl.find_and_modify(m.collection, *args, **kwargs)
        if obj is None: return None
        cursor = ODMCursor(self, cls, iter([ obj ]), refresh=True, decorate=decorate)
        result = cursor.first()
        state(result).status = ObjectState.clean
        return result
    @_with_hooks('remove')
    def remove(self, cls, *args, **kwargs):
        m = mapper(cls)
        m.remove(self, *args, **kwargs)
    def update(self, cls, spec, fields, **kwargs):
        m = mapper(cls)
        m.update_partial(self, spec, fields, **kwargs)
    def update_if_not_modified(self, obj, fields, upsert=False):
        spec = state(obj).original_document
        self.update(obj.__class__, spec, fields, upsert=upsert)
        err = self.impl.db.command(dict(getlasterror=1))
        return bool(err['n'] and err['updatedExisting'])
    def __repr__(self):
        l = ['<session>']
        l.append('  ' + indent(repr(self.uow), 2))
        l.append('  ' + indent(repr(self.imap), 2))
        return '\n'.join(l)
    def ensure_index(self, cls, fields, **kwargs):
        return self.impl.ensure_index(cls, fields, **kwargs)
    def ensure_indexes(self, cls):
        return self.impl.ensure_indexes(cls)
    def drop_indexes(self, cls):
        return self.impl.drop_indexes(cls)
    def group(self, cls, *args, **kwargs):
        m = mapper(cls)
        return self.impl.group(m.collection, *args, **kwargs)
    def aggregate(self, cls, *args, **kwargs):
        m = mapper(cls)
        return self.impl.aggregate(m.collection, *args, **kwargs)
    def distinct(self, cls, *args, **kwargs):
        m = mapper(cls)
        return self.impl.distinct(m.collection, *args, **kwargs)
    def map_reduce(self, cls, *args, **kwargs):
        m = mapper(cls)
        return self.impl.map_reduce(m.collection, *args, **kwargs)
    def inline_map_reduce(self, cls, *args, **kwargs):
        m = mapper(cls)
        return self.impl.inline_map_reduce(m.collection, *args, **kwargs)

class Sentence():
    def __init__(self, cells, count):
        self.cells = set(cells)
        self.count = count
    def __eq__(self, other):
        return self.cells == other.cells and self.count == other.count
    def __str__(self):
        return f"{self.cells} = {self.count}"
    def known_mines(self):
        if self.count == len(self.cells):
            return self.cells
    def known_safes(self):
        if self.count == 0:
            return self.cells
    def mark_mine(self, cell):
        if cell in self.cells:
            self.cells.remove(cell)
            self.count -= 1
        else:
            pass
    def mark_safe(self, cell):
        if cell in self.cells:
            self.cells.remove(cell)
        else:
            pass

class Instrument(InstrumentBase):
    shared_kwargs = ()
    _all_instruments = {} 
    _type = None
    _instances = [] 
    def __init__(self, name: str,
                 metadata: Optional[Dict]=None, **kwargs) -> None:
        self._t0 = time.time()
        if kwargs.pop('server_name', False):
            warnings.warn("server_name argument not supported any more",
                          stacklevel=0)
        super().__init__(name, **kwargs)
        self.add_parameter('IDN', get_cmd=self.get_idn,
                           vals=Anything())
        self.record_instance(self)
    def get_idn(self) -> Dict[str, Optional[str]]:
        try:
            idstr = ''  
            idstr = self.ask('*IDN?')
            idparts = [] 
            for separator in ',;:':
                idparts = [p.strip() for p in idstr.split(separator, 3)]
                if len(idparts) > 1:
                    break
            if len(idparts) < 4:
                idparts += [None] * (4 - len(idparts))
        except:
            log.debug('Error getting or interpreting *IDN?: '
                      + repr(idstr))
            idparts = [None, self.name, None, None]
        if str(idparts[1]).lower().startswith('model'):
            idparts[1] = str(idparts[1])[5:].strip()
        return dict(zip(('vendor', 'model', 'serial', 'firmware'), idparts))
    def connect_message(self, idn_param: str='IDN',
                        begin_time: float=None) -> None:
        idn = {'vendor': None, 'model': None,
               'serial': None, 'firmware': None}
        idn.update(self.get(idn_param))
        t = time.time() - (begin_time or self._t0)
        con_msg = ('Connected to: {vendor} {model} '
                   '(serial:{serial}, firmware:{firmware}) '
                   'in {t:.2f}s'.format(t=t, **idn))
        print(con_msg)
    def __repr__(self):
        return '<{}: {}>'.format(type(self).__name__, self.name)
    def __del__(self):
        try:
            wr = weakref.ref(self)
            if wr in getattr(self, '_instances', []):
                self._instances.remove(wr)
            self.close()
        except:
            pass
    def close(self) -> None:
        if hasattr(self, 'connection') and hasattr(self.connection, 'close'):
            self.connection.close()
        strip_attrs(self, whitelist=['name'])
        self.remove_instance(self)
    @classmethod
    def close_all(cls) -> None:
        log.info("Closing all registered instruments")
        for inststr in list(cls._all_instruments):
            try:
                inst = cls.find_instrument(inststr)
                log.info(f"Closing {inststr}")
                inst.close()
            except:
                log.exception(f"Failed to close {inststr}, ignored")
                pass
    @classmethod
    def record_instance(cls, instance: 'Instrument') -> None:
        wr = weakref.ref(instance)
        name = instance.name
        existing_wr = cls._all_instruments.get(name)
        if existing_wr and existing_wr():
            raise KeyError('Another instrument has the name: {}'.format(name))
        cls._all_instruments[name] = wr
        if getattr(cls, '_type', None) is not cls:
            cls._type = cls
            cls._instances = []
        cls._instances.append(wr)
    @classmethod
    def instances(cls) -> List['Instrument']:
        if getattr(cls, '_type', None) is not cls:
            return []
        return [wr() for wr in getattr(cls, '_instances', []) if wr()]
    @classmethod
    def remove_instance(cls, instance: 'Instrument') -> None:
        wr = weakref.ref(instance)
        if wr in getattr(cls, "_instances", []):
            cls._instances.remove(wr)
        all_ins = cls._all_instruments
        for name, ref in list(all_ins.items()):
            if ref is wr:
                del all_ins[name]
    @classmethod
    def find_instrument(cls, name: str,
                        instrument_class: Optional[type]=None) -> 'Instrument':
        ins = cls._all_instruments[name]()
        if ins is None:
            del cls._all_instruments[name]
            raise KeyError('Instrument {} has been removed'.format(name))
        if instrument_class is not None:
            if not isinstance(ins, instrument_class):
                raise TypeError(
                    'Instrument {} is {} but {} was requested'.format(
                        name, type(ins), instrument_class))
        return ins
    @staticmethod
    def exist(name: str, instrument_class: Optional[type]=None) -> bool:
        instrument_exists = True
        try:
            _ = Instrument.find_instrument(
                name, instrument_class=instrument_class)
        except KeyError as exception:
            instrument_is_not_found = \
                any(str_ in str(exception)
                    for str_ in [name, 'has been removed'])
            if instrument_is_not_found:
                instrument_exists = False
            else:
                raise exception
        return instrument_exists
    @staticmethod
    def is_valid(instr_instance: 'Instrument') -> bool:
        if isinstance(instr_instance, Instrument) \
                and instr_instance in instr_instance.instances():
            return True
        return False
    def write(self, cmd: str) -> None:
        try:
            self.write_raw(cmd)
        except Exception as e:
            inst = repr(self)
            e.args = e.args + ('writing ' + repr(cmd) + ' to ' + inst,)
            raise e
    def write_raw(self, cmd: str) -> None:
        raise NotImplementedError(
            'Instrument {} has not defined a write method'.format(
                type(self).__name__))
    def ask(self, cmd: str) -> str:
        try:
            answer = self.ask_raw(cmd)
            return answer
        except Exception as e:
            inst = repr(self)
            e.args = e.args + ('asking ' + repr(cmd) + ' to ' + inst,)
            raise e
    def ask_raw(self, cmd: str) -> str:
        raise NotImplementedError(
            'Instrument {} has not defined an ask method'.format(
                type(self).__name__))

class MultiIndex(Index):
    def __init__(
        self, levels=None, codes=None, labels=None, names=None, **kwargs
    ):
        from cudf.core.series import Series
        self.name = None
        self.names = names
        self._source_data = None
        column_names = []
        if labels:
            warnings.warn(
                "the 'labels' keyword is deprecated, use 'codes' " "instead",
                FutureWarning,
            )
        if labels and not codes:
            codes = labels
        if "source_data" in kwargs:
            self._source_data = kwargs["source_data"].reset_index(drop=True)
            self._codes = codes
            self._levels = levels
            return
        if isinstance(
            names,
            (
                Sequence,
                pd.core.indexes.frozen.FrozenNDArray,
                pd.core.indexes.frozen.FrozenList,
            ),
        ):
            if sum(x is None for x in names) > 1:
                column_names = list(range(len(codes)))
            else:
                column_names = names
        elif names is None:
            column_names = list(range(len(codes)))
        else:
            column_names = names
        if len(levels) == 0:
            raise ValueError("Must pass non-zero number of levels/codes")
        from cudf import DataFrame
        if not isinstance(codes, DataFrame) and not isinstance(
            codes[0], (Sequence, pd.core.indexes.frozen.FrozenNDArray)
        ):
            raise TypeError("Codes is not a Sequence of sequences")
        if isinstance(codes, DataFrame):
            self._codes = codes
        elif len(levels) == len(codes):
            self._codes = DataFrame()
            for i, codes in enumerate(codes):
                name = column_names[i] or i
                codes = column.as_column(codes)
                self._codes[name] = codes.astype(np.int64)
        else:
            raise ValueError(
                "MultiIndex has unequal number of levels and "
                "codes and is inconsistent!"
            )
        self._levels = [Series(level) for level in levels]
        self._validate_levels_and_codes(self._levels, self._codes)
        self._source_data = DataFrame()
        for i, name in enumerate(self._codes.columns):
            codes = as_index(self._codes[name]._column)
            level = DataFrame({name: self._levels[i]})
            level = DataFrame(index=codes).join(level)
            self._source_data[name] = level[name].reset_index(drop=True)
        self.names = [None] * len(self._levels) if names is None else names
    def _validate_levels_and_codes(self, levels, codes):
        if len(levels) != len(codes.columns):
            raise ValueError(
                "MultiIndex has unequal number of levels and "
                "codes and is inconsistent!"
            )
        code_length = len(codes[codes.columns[0]])
        for index, code in enumerate(codes):
            if code_length != len(codes[code]):
                raise ValueError(
                    "MultiIndex length of codes does not match "
                    "and is inconsistent!"
                )
        for index, code in enumerate(codes):
            if codes[code].max() > len(levels[index]) - 1:
                raise ValueError(
                    "MultiIndex code %d contains value %d larger "
                    "than maximum level size at this position"
                )
    def copy(self, deep=True):
        mi = MultiIndex(source_data=self._source_data.copy(deep))
        if self._levels is not None:
            mi._levels = [s.copy(deep) for s in self._levels]
        if self._codes is not None:
            mi._codes = self._codes.copy(deep)
        if self.names is not None:
            mi.names = self.names.copy()
        return mi
    def deepcopy(self):
        return self.copy(deep=True)
    def __copy__(self):
        return self.copy(deep=True)
    def _popn(self, n):
        from cudf import DataFrame
        codes = DataFrame()
        for idx in self.codes.columns[n:]:
            codes.add_column(idx, self.codes[idx])
        result = MultiIndex(self.levels[n:], codes)
        if self.names is not None:
            result.names = self.names[n:]
        return result
    def __repr__(self):
        return (
            "MultiIndex(levels="
            + str(self.levels)
            + ",\ncodes="
            + str(self.codes)
            + ")"
        )
    @property
    def codes(self):
        if self._codes is None:
            self._compute_levels_and_codes()
        return self._codes
    @property
    def levels(self):
        if self._levels is None:
            self._compute_levels_and_codes()
        return self._levels
    @property
    def labels(self):
        warnings.warn(
            "This feature is deprecated in pandas and will be"
            "dropped from cudf as well.",
            FutureWarning,
        )
        return self.codes
    def _compute_levels_and_codes(self):
        levels = []
        from cudf import DataFrame
        codes = DataFrame()
        for name in self._source_data.columns:
            code, cats = self._source_data[name].factorize()
            codes[name] = code.reset_index(drop=True).astype(np.int64)
            cats = cats.reset_index(drop=True)._copy_construct(name=None)
            levels.append(cats)
        self._levels = levels
        self._codes = codes
    def _compute_validity_mask(self, index, row_tuple, max_length):
        from cudf import DataFrame
        from cudf import Series
        from cudf import concat
        from cudf.utils.cudautils import arange
        lookup = DataFrame()
        for idx, row in enumerate(row_tuple):
            if row == slice(None):
                continue
            lookup[index._source_data.columns[idx]] = Series(row)
        data_table = concat(
            [
                index._source_data,
                DataFrame({"idx": Series(arange(len(index._source_data)))}),
            ],
            axis=1,
        )
        result = lookup.merge(data_table)["idx"]
        if len(result) == 0:
            for idx, row in enumerate(row_tuple):
                if row == slice(None):
                    continue
                if row not in index.levels[idx]._column:
                    raise KeyError(row)
        return result
    def _get_valid_indices_by_tuple(self, index, row_tuple, max_length):
        from cudf.utils.cudautils import arange
        from cudf import Series
        if isinstance(row_tuple, slice):
            if (
                isinstance(row_tuple.start, numbers.Number)
                or isinstance(row_tuple.stop, numbers.Number)
                or row_tuple == slice(None)
            ):
                stop = row_tuple.stop or max_length
                start, stop, step = row_tuple.indices(stop)
                return arange(start, stop, step)
