class Card(object):
    def __init__(self, val, suit):
        self.val = val
        self.suit = suit
        self.face_score = {'A': 14,
                          'K': 13,
                          'Q': 12,
                          'J': 11}
    def __repr__(self):
        return f"{self.val}{self.suit}"
    def __str__(self):
        return f"{self.val}{self.suit}"
    def __gt__(self, other_card):
        val1 = self.val
        val2 = other_card.val
        if isinstance(val1,int) and isinstance(val2,int):
            return val1 > val2
        elif isinstance(val1,str) and isinstance(val2,str):
            return self.face_score[val1] > self.face_score[val2]
        elif isinstance(val1,str) and isinstance(val2,int):
            return True
        else:
            return False
    def __ge__(self, other_card):
        val1 = self.val
        val2 = other_card.val
        if isinstance(val1,int) and isinstance(val2,int):
            return val1 >= val2
        elif isinstance(val1,str) and isinstance(val2,str):
            return self.face_score[val1] >= self.face_score[val2]
        elif isinstance(val1,str) and isinstance(val2,int):
            return True
        else:
            return False
    def __lt__(self, other_card):
        val1 = self.val
        val2 = other_card.val
        if isinstance(val1,int) and isinstance(val2,int):
            return val1 < val2
        elif isinstance(val1,str) and isinstance(val2,str):
            return self.face_score[val1] < self.face_score[val2]
        elif isinstance(val1,str) and isinstance(val2,int):
            return False
        else:
            return True
    def __le__(self, other_card):
        val1 = self.val
        val2 = other_card.val
        if isinstance(val1,int) and isinstance(val2,int):
            return val1 <= val2
        elif isinstance(val1,str) and isinstance(val2,str):
            return self.face_score[val1] <= self.face_score[val2]
        elif isinstance(val1,str) and isinstance(val2,int):
            return False
        else:
            return True
    def __eq__(self, other_card):
        val1 = self.val
        val2 = other_card.val
        if isinstance(val1,int) and isinstance(val2,int):
            return val1 == val2
        elif isinstance(val1,str) and isinstance(val2,str):
            return self.face_score[val1] == self.face_score[val2]
        elif isinstance(val1,str) and isinstance(val2,int):
            return False
        else:
            return False
    def __sub__(self, other_card):
        val1 = self.val
        val2 = other_card.val
        if isinstance(val1,int) and isinstance(val2,int):
            return val1 - val2
        elif isinstance(val1,str) and isinstance(val2,str):
            return self.face_score[val1] - self.face_score[val2]
        elif isinstance(val1,str) and isinstance(val2,int):
            return self.face_score[val1] - val2
        else:
            return val1 - self.face_score[val2]
    def __hash__(self):
        return hash(tuple([self.val, self.suit]))

