            if rand:
                self.init = [random.randint(0, 1) for _ in range(MAX_ITEMS)]
            else:
                self.init = [0] * MAX_ITEMS
            super(Vector, self).__init__(self.init)
        else:
            self.init = init
            super(Vector, self).__init__(self.init)
        Vector.__instances.append(weakref.ref(self))
