        return self.__repr__()
    def _split_buffer(self):
        self._lines_buffer = self.getvalue().split('\n')
        self._iter = None
    def __iter__(self):
        self._split_buffer()
        return iter(self._lines_buffer)
    def __len__(self):
        self._split_buffer()
        return len(self._lines_buffer)
