class OrderSet:
    def __init__(self,val):
        self.val = [x for x in val]
    def __repr__(self):
        return 'OrderSet(%s)'%self.val
    def __and__(self,rhs):
        L = []
        for x in self.val:
            if x in rhs.val:
                L.append(x)
        return OrderSet(L)
    def __or__(self,rhs):
        L = []
        for x in self.val:
            if x not in rhs.val:
                L.append(x)
        L.extend(rhs.val)
        return OrderSet(L)
    def __xor__(self,rhs):
        L = []
        for x in self.val:
            if x not in rhs.val:
                L.append(x)
        for x in rhs.val:
            if x not in self.val:
                L.append(x)
        return OrderSet(L)
    def __ne__(self,rhs):
        if self.val != rhs.val:
            return True
        else:
            return False
    def __eq__(self,rhs):
        if self.val == rhs.val:
            return True
        else:
            return False
    def __contains__(self,rhs):
        if rhs in self.val:
            return True
        else:
            return False

