class QuizQuestion:
    def __init__(self, statement, options, answer=None, answer_code=None):
        self.statement = statement
        if not len(options) > 1:
            raise ValueError("Options provided are not more than 1.")
        self.option_codes = [x for x in options.keys()]
        self.options = [x for x in options.values()]
        if answer is None and answer_code is not None:
            try:
                answer = options[answer_code]
            except KeyError:
                raise ValueError("%s is not a valid answer code. It is not contained in the options" % answer_code)
        if answer not in self.options:
            try:
                answer = options[answer]
            except KeyError:
                raise ValueError("%s is not a valid answer. It is not contained in the options" % answer)
        self.answer = answer
        self.answer_code = self.option_codes[self.options.index(answer)]
    def __repr__(self):
        return('QuizQuestion(**' +
               self.as_dict().__repr__() +
               ')')
    def __str__(self):
        return(yaml.dump(self.as_dict()))
    def shuffle(self):
        shuffle(self.options)
        self.answer_code = self.option_codes[self.options.index(self.answer)]
    def as_dict(self):
        out_dict = {'statement': self.statement,
                    'options': {x:y for x, y in zip(self.option_codes, self.options)},
                    'answer': self.answer}
        return out_dict

class MarketFactor:
    def __init__(self, ticker_, data_):
        self.ticker = ticker_
        close = data_[CLOSE_COLUMN]
        data_[RETURN_COLUMN] = np.log(close / close.shift(1)) 
        data_ = data_.ix[1:]  
        self.data = data_  
        self.data.index = self.data[DATE_TIME_COLUMN]
    def __repr__(self):
        return 'MarketFactor(' + self.ticker + ',' + yyyymmdd(self.data.index[0]) \
               + ' to ' + yyyymmdd(self.data.index[-1]) + ',' + str(len(self.data)) + ' days)'
    def mostRecentPrice(self):
        return self.data[CLOSE_COLUMN][-1]

class MarketFactorVector:
    def __init__(self, marketFactor_, startDate_, endDate_, decay_):
        self.marketFactor = marketFactor_
        self.startDate = startDate_
        self.endDate = endDate_
        returnsDataFrame = marketFactor_.data[startDate_:endDate_]
        numDays = len(returnsDataFrame)
        if decay_ < 1:
            sqrtSumOfWeights = math.sqrt((1 + decay_ ** numDays) / (1 - decay_))
            weights = [decay_ ** (numDays - i) / sqrtSumOfWeights for i in range(numDays)]
            self.weightedReturns = np.multiply(returnsDataFrame[RETURN_COLUMN].values, weights)
        else:
            self.weightedReturns = np.divide(returnsDataFrame[RETURN_COLUMN].values, math.sqrt(numDays))
    def __repr__(self):
        return 'MarketFactorVector(' + self.marketFactor.ticker + ', ' + yyyymmdd(self.startDate) \
               + ', ' + yyyymmdd(self.endDate) + ',' + str(len(self.weightedReturns)) + ' returns)'

class MarketUniverse:
    def __init__(self):
        self.tickerToMarketFactorDict = {}
    def __repr__(self):
        return 'MarketUniver('+str(self.tickerToMarketFactorDict)+')'
    def initializeFromFileNames(self, dataFileNames):
        fileCount = 0
        columnNames = [DATE_TIME_COLUMN, 'time', 'open', 'high', 'low', CLOSE_COLUMN, 'volume']
        for dataFileName in dataFileNames:
            fileCount += 1
            if fileCount > 3:
                break
            ticker = dataFileName[6:dataFileName.find('.')].upper()
            data = pd.read_csv('daily/' + dataFileName)
            data.columns = columnNames
            data[DATE_TIME_COLUMN] = data[DATE_TIME_COLUMN].apply(lambda x: datetime64FromYYYYMMDD(x))
            for columnName in columnNames:
                if columnName != 'date' and columnName != 'close':
                    data.drop(columnName, axis=1, inplace=True)
            self.tickerToMarketFactorDict[ticker] = MarketFactor(ticker, data)
    def initializeFromTickers(self, tickers):
        self.initializeFromFileNames(['table_' + ticker + '.csv' for ticker in tickers])
    def marketForTickers(self,tickers,startDate,endDate,decay):
        tickerToMarketFactorDict=collections.OrderedDict()
        for ticker in tickers:
            tickerToMarketFactorDict[ticker]=self.tickerToMarketFactorDict[ticker]
        return Market(tickerToMarketFactorDict,startDate,endDate,decay)
    def marketForAllTickers(self,startDate,endDate,decay):
        return self.marketForTickers(self.tickerToMarketFactorDict.keys(),startDate,endDate,decay)

class Circle:
    def __init__(self, radius=4):
        self.radius = radius
    @property
    def area(self):
        return math.pi * self.radius ** 2
    @property
    def diameter(self):
        return 2 * self.radius
    @diameter.setter
    def diameter(self, diameter):
        self.radius = diameter / 2
    def __str__(self):
        return "Circle with radius: {:.6f}".format(self.radius)
    def __repr__(self):
        return "Circle({})".format(self.radius)
    def __add__(self, other):
        rad = self.radius + other.radius
        return Circle(rad)
    def __mul__(self, other):
        rad = self.radius * other
        return Circle(rad)
    def __lt__(self, other):
        return self.radius < other.radius
    def __le__(self, other):
        return self.radius <= other.radius

class UsageRecordList(ListResource):
    def __init__(self, version, sim_sid):
        super(UsageRecordList, self).__init__(version)
        self._solution = {'sim_sid': sim_sid, }
        self._uri = '/Sims/{sim_sid}/UsageRecords'.format(**self._solution)
    def stream(self, end=values.unset, start=values.unset, granularity=values.unset,
               limit=None, page_size=None):
        limits = self._version.read_limits(limit, page_size)
        page = self.page(end=end, start=start, granularity=granularity, page_size=limits['page_size'], )
        return self._version.stream(page, limits['limit'], limits['page_limit'])
    def list(self, end=values.unset, start=values.unset, granularity=values.unset,
             limit=None, page_size=None):
        return list(self.stream(
            end=end,
            start=start,
            granularity=granularity,
            limit=limit,
            page_size=page_size,
        ))
    def page(self, end=values.unset, start=values.unset, granularity=values.unset,
             page_token=values.unset, page_number=values.unset,
             page_size=values.unset):
        data = values.of({
            'End': serialize.iso8601_datetime(end),
            'Start': serialize.iso8601_datetime(start),
            'Granularity': granularity,
            'PageToken': page_token,
            'Page': page_number,
            'PageSize': page_size,
        })
        response = self._version.page(method='GET', uri=self._uri, params=data, )
        return UsageRecordPage(self._version, response, self._solution)
    def get_page(self, target_url):
        response = self._version.domain.twilio.request(
            'GET',
            target_url,
        )
        return UsageRecordPage(self._version, response, self._solution)
