             date_created_after=values.unset, date_created_before=values.unset,
             limit=None, page_size=None):
        return list(self.stream(
            status=status,
            identity=identity,
            date_created_after=date_created_after,
            date_created_before=date_created_before,
            limit=limit,
            page_size=page_size,
        ))
