class OlgaModel:
    def __init__(self, chain_folder, recomb_type):
        self.chain_folder     = chain_folder
        self.recomb_type      = recomb_type
        self.generative_model = None
        self.genomic_data     = None
        self.pgen_model       = None
        self._validate_chain_folder_arg()
        self._validate_recomb_type_arg()
        self._validate_chain_folder_with_recomb_type()
        params_file_name = op.join(path_to_olga_default_models,
                                   chain_folder,
                                   'model_params.txt')
        marginals_file_name = op.join(path_to_olga_default_models,
                                      chain_folder,
                                      'model_marginals.txt')
        V_anchor_pos_file = op.join(path_to_olga_default_models,
                                    chain_folder,
                                    'V_gene_CDR3_anchors.csv')
        J_anchor_pos_file = op.join(path_to_olga_default_models,
                                    chain_folder,
                                     'J_gene_CDR3_anchors.csv')
        if recomb_type == 'VDJ':
            genomic_data = load_model.GenomicDataVDJ()
            genomic_data.load_igor_genomic_data(params_file_name, V_anchor_pos_file, J_anchor_pos_file)
            generative_model = load_model.GenerativeModelVDJ()
            generative_model.load_and_process_igor_model(marginals_file_name)
            pgen_model = generation_probability.GenerationProbabilityVDJ(generative_model, genomic_data)
            self.genomic_data = genomic_data
            self.generative_model = generative_model
            self.pgen_model = pgen_model
        elif recomb_type == 'VJ':
            genomic_data = load_model.GenomicDataVJ()
            genomic_data.load_igor_genomic_data(params_file_name, V_anchor_pos_file, J_anchor_pos_file)
            generative_model = load_model.GenerativeModelVJ()
            generative_model.load_and_process_igor_model(marginals_file_name)
            pgen_model = generation_probability.GenerationProbabilityVJ(generative_model, genomic_data)
            self.genomic_data = genomic_data
            self.generative_model = generative_model
            self.pgen_model = pgen_model
    def __repr__(self):
        return "tcrdist.pgen.OlgaModel set to recomb_type: '{}' and chain_folder: '{}'".format(self.recomb_type, self.chain_folder)
    def compute_aa_cdr3_pgen(self, CDR3_seq, V_usage_mask_in = None, J_usage_mask_in = None):
        pgen_estimate = self.pgen_model.compute_aa_CDR3_pgen(CDR3_seq, V_usage_mask_in, J_usage_mask_in)
        return(pgen_estimate)
    def compute_aa_cdr3_pgens(self, CDR3_seq, V_usage_mask_in = None, J_usage_mask_in = None):
        if V_usage_mask_in is None:
            V_usage_mask_in = [None]*len(CDR3_seq)
            if len(CDR3_seq) != len(V_usage_mask_in):
                raise TypeError("len(CDR3_seq) must equal len(V_usage_mask_in)")
        else:
            if len(CDR3_seq) != len(V_usage_mask_in):
                raise TypeError("len(CDR3_seq) must equal len(V_usage_mask_in)")
        if J_usage_mask_in is None:
            J_usage_mask_in = [None]*len(CDR3_seq)
            if len(CDR3_seq) != len(J_usage_mask_in):
                raise TypeError("len(CDR3_seq) must equal len(V_usage_mask_in)")
        else:
            if len(CDR3_seq) != len(J_usage_mask_in):
                raise TypeError("len(CDR3_seq) must equal len(V_usage_mask_in)")
        l = len(CDR3_seq)
        input_tuples  = [(CDR3_seq[i], V_usage_mask_in[i], J_usage_mask_in[i] ) \
                         for i in range(l)]
        pgen_estimates = [self.compute_aa_cdr3_pgen(x,y,z) for x,y,z in input_tuples]
        return(pgen_estimates)
    def _validate_recomb_type_arg(self):
        ["VDJ","VJ"].index(self.recomb_type)
    def _validate_chain_folder_arg(self):
        valid_chain_folders = [x for x in os.listdir(path_to_olga_default_models)]
        valid_chain_folders_string =  " ".join(map( str, valid_chain_folders))
        try:
            valid_chain_folders.index(self.chain_folder)
        except ValueError:
            raise ValueError('chain_folder arg in OlgaModel must be: {}'.format(valid_chain_folders_string))
        return(1)
    def _validate_chain_folder_with_recomb_type(self):
        if self.recomb_type == "VDJ" and self.chain_folder == "human_T_alpha":
            raise ValueError("human_T_alpha default is recomb_type = VJ")
        if self.recomb_type == "VJ" and self.chain_folder == "human_T_beta":
            raise ValueError("human_T_beta default is recomb_type = VDJ")
        return(1)

class Student(object):
    def __init__(self, year, courses, noise=const.NOISE):
        self.year = year
        self.noise = noise
        self.courses = courses
        self.subjects = set(
            sample(const.SUBJECTS, randint(const.MIN_SUBJECTS, const.MAX_SUBJECTS))
        )
        self.interested = set()
        self.preferences = []
        self.preference_dict = {}
        self._init_preferences()
        self.offered_courses = set()
        self.enrolled_courses = set()
    def _init_preferences(self):
        for course in self.courses:
            if course.subject in self.subjects:
                value = course.quality + normal(scale=self.noise)
                if value >= 0:
                    self.interested.add(course)
                    self.preferences.append((course, value))
        self.preferences.sort(key=lambda c: c[1])
        self.preference_dict = defaultdict(int, dict(self.preferences))
    def init_trading(self):
        self.offered_courses.update(self.enrolled_courses)
        self.enrolled_courses.clear()
    def _update_preferences(self):
        while (self.preferences
               and self.has_room()
               and self.preferences[-1][0] in self.offered_courses):
            self.enrolled_courses.add(self.preferences[-1][0])
            self.offered_courses.remove(self.preferences[-1][0])
            self.preferences.pop()
    def top_preference(self):
        if self.preferences:
            return self.preferences[-1][0]
    def offer_spot(self, course):
        self.offered_courses.add(course)
    def get_studycard(self):
        all_courses = list(self.offered_courses.union(self.enrolled_courses))
        all_courses.sort(key=lambda c: self.preference_dict[c], reverse=True)
        accepts = all_courses[0:const.MAX_COURSES]
        return accepts
    def get_studycard_destructive(self):
        accepts = self.get_studycard()
        rejects = [c for c in self.offered_courses if c not in accepts]
        for course in accepts:
            self.enroll(course)
        for course in rejects:
            course.unenroll(self)
        self.offered_courses.difference_update(self.enrolled_courses)
        return accepts
    def enroll(self, course):
        if self.has_room():
            self.enrolled_courses.add(course)
    def remove_spot(self, course):
        if course in self.offered_courses:
            self.offered_courses.remove(course)
    def get_studycard_value(self):
        studycard = self.get_studycard()
        return sum([self.preference_dict[c] for c in studycard])
    def has_room(self):
        return len(self.enrolled_courses) < const.MAX_COURSES
    def __repr__(self):
         return str(self.__hash__())

class Message:
    cmdid = None
    @property
    def hash(self):
        packed = self.packed()
        return sha3(packed.data)
    def __eq__(self, other):
        return isinstance(other, self.__class__) and self.hash == other.hash
    def __hash__(self):
        return big_endian_to_int(self.hash)
    def __ne__(self, other):
        return not self.__eq__(other)
    def __repr__(self):
        return '<{klass} [msghash={msghash}]>'.format(
            klass=self.__class__.__name__,
            msghash=pex(self.hash),
        )
    @classmethod
    def decode(cls, data):
        packed = messages.wrap(data)
        return cls.unpack(packed)
    def encode(self):
        packed = self.packed()
        return bytes(packed.data)
    def packed(self):
        klass = messages.CMDID_MESSAGE[self.cmdid]
        data = buffer_for(klass)
        data[0] = self.cmdid
        packed = klass(data)
        self.pack(packed)
        return packed
    @classmethod
    def unpack(cls, packed):
        raise NotImplementedError('Method needs to be implemented in a subclass.')
    def pack(self, packed):
        raise NotImplementedError('Method needs to be implemented in a subclass.')
    def to_dict(self):
        raise NotImplementedError('Method needs to be implemented in a subclass.')
    @classmethod
    def from_dict(cls, data):
        raise NotImplementedError('Method needs to be implemented in a subclass.')

class Processed(SignedMessage):
    cmdid = messages.PROCESSED
    def __init__(self, message_identifier: MessageID):
        super().__init__()
        self.message_identifier = message_identifier
    @classmethod
    def unpack(cls, packed):
        processed = cls(
            message_identifier=packed.message_identifier,
        )
        processed.signature = packed.signature
        return processed
    def pack(self, packed):
        packed.message_identifier = self.message_identifier
        packed.signature = self.signature
    @classmethod
    def from_event(cls, event):
        return cls(message_identifier=event.message_identifier)
    def __repr__(self):
        return '<{} [msgid:{}]>'.format(
            self.__class__.__name__,
            self.message_identifier,
        )
    def to_dict(self):
        return {
            'type': self.__class__.__name__,
            'message_identifier': self.message_identifier,
            'signature': encode_hex(self.signature),
        }
    @classmethod
    def from_dict(cls, data):
        assert data['type'] == cls.__name__
        processed = cls(
            message_identifier=data['message_identifier'],
        )
        processed.signature = decode_hex(data['signature'])
        return processed

