class RawQuerySet(object):
    def __init__(self, raw_query, model=None, query=None, params=None,
                 translations=None, using=None, hints=None):
        self.raw_query = raw_query
        self.model = model
        self._db = using
        self._hints = hints or {}
        self.query = query or sql.RawQuery(sql=raw_query, using=self.db, params=params)
        self.params = params or ()
        self.translations = translations or {}
    def resolve_model_init_order(self):
        model_init_fields = [f for f in self.model._meta.fields if f.column in self.columns]
        annotation_fields = [(column, pos) for pos, column in enumerate(self.columns)
                             if column not in self.model_fields]
        model_init_order = [self.columns.index(f.column) for f in model_init_fields]
        model_init_names = [f.attname for f in model_init_fields]
        return model_init_names, model_init_order, annotation_fields
    def __iter__(self):
        db = self.db
        compiler = connections[db].ops.compiler('SQLCompiler')(
            self.query, connections[db], db
        )
        query = iter(self.query)
        try:
            model_init_names, model_init_pos, annotation_fields = self.resolve_model_init_order()
            skip = set()
            for field in self.model._meta.fields:
                if field.attname not in model_init_names:
                    skip.add(field.attname)
            if skip:
                if self.model._meta.pk.attname in skip:
                    raise InvalidQuery('Raw query must include the primary key')
            model_cls = self.model
            fields = [self.model_fields.get(c) for c in self.columns]
            converters = compiler.get_converters([
                f.get_col(f.model._meta.db_table) if f else None for f in fields
            ])
            for values in query:
                if converters:
                    values = compiler.apply_converters(values, converters)
                model_init_values = [values[pos] for pos in model_init_pos]
                instance = model_cls.from_db(db, model_init_names, model_init_values)
                if annotation_fields:
                    for column, pos in annotation_fields:
                        setattr(instance, column, values[pos])
                yield instance
        finally:
            if hasattr(self.query, 'cursor') and self.query.cursor:
                self.query.cursor.close()
    def __repr__(self):
        return "<RawQuerySet: %s>" % self.query
    def __getitem__(self, k):
        return list(self)[k]
    @property
    def db(self):
        "Return the database that will be used if this query is executed now"
        return self._db or router.db_for_read(self.model, **self._hints)
    def using(self, alias):
        return RawQuerySet(
            self.raw_query, model=self.model,
            query=self.query.clone(using=alias),
            params=self.params, translations=self.translations,
            using=alias,
        )
    @property
    def columns(self):
        if not hasattr(self, '_columns'):
            self._columns = self.query.get_columns()
            for (query_name, model_name) in self.translations.items():
                try:
                    index = self._columns.index(query_name)
                    self._columns[index] = model_name
                except ValueError:
                    pass
        return self._columns
    @property
    def model_fields(self):
        if not hasattr(self, '_model_fields'):
            converter = connections[self.db].introspection.table_name_converter
            self._model_fields = {}
            for field in self.model._meta.fields:
                name, column = field.get_attname_column()
                self._model_fields[converter(column)] = field
        return self._model_fields

class Prefetch(object):
    def __init__(self, lookup, queryset=None, to_attr=None):
        self.prefetch_through = lookup
        self.prefetch_to = lookup
        if queryset is not None and queryset._iterable_class is not ModelIterable:
            raise ValueError('Prefetch querysets cannot use values().')
        if to_attr:
            self.prefetch_to = LOOKUP_SEP.join(lookup.split(LOOKUP_SEP)[:-1] + [to_attr])
        self.queryset = queryset
        self.to_attr = to_attr
    def add_prefix(self, prefix):
        self.prefetch_through = LOOKUP_SEP.join([prefix, self.prefetch_through])
        self.prefetch_to = LOOKUP_SEP.join([prefix, self.prefetch_to])
    def get_current_prefetch_through(self, level):
        return LOOKUP_SEP.join(self.prefetch_through.split(LOOKUP_SEP)[:level + 1])
    def get_current_prefetch_to(self, level):
        return LOOKUP_SEP.join(self.prefetch_to.split(LOOKUP_SEP)[:level + 1])
    def get_current_to_attr(self, level):
        parts = self.prefetch_to.split(LOOKUP_SEP)
        to_attr = parts[level]
        as_attr = self.to_attr and level == len(parts) - 1
        return to_attr, as_attr
    def get_current_queryset(self, level):
        if self.get_current_prefetch_to(level) == self.prefetch_to:
            return self.queryset
        return None
    def __eq__(self, other):
        if isinstance(other, Prefetch):
            return self.prefetch_to == other.prefetch_to
        return False
    def __hash__(self):
        return hash(self.__class__) ^ hash(self.prefetch_to)

class WJ(s.Problem):
    def __init__(self, capacities=(5,2), initial=(5,0), goal=(0,1)):
        self.capacities = capacities
        self.initial = initial
        self.goal = goal
    def __repr__(self):
        return "WJ({},{},{})".format(self.capacities, self.initial, self.goal)
    def goal_test(self, state):
        g = self.goal
        return (state[0] == g[0] or g[0] == '*' ) and \
               (state[1] == g[1] or g[1] == '*')
    def h(self, node):
        return 0 if self.goal_test(node.state) else 1
    def actions(self, state):
        (J0, J1) = state
        (C0, C1) = self.capacities
        if J0 > 0: yield 'dump0'
        if J1>0: yield 'dump1'
        if J1<C1 and J0>0: yield 'pour_0_1'
        if J0<C0 and J1>0: yield 'pour_1_0'
    def result(self, state, action):
        (J0, J1) = state
        (C0, C1) = self.capacities
        if action == 'dump0':
            return (0, J1)
        elif action == 'dump1':
            return (J0, 0)
        elif action == 'pour_0_1':
            delta = min(J0, C1-J1)
            return (J0-delta, J1+delta)
        elif action == 'pour_1_0':
            delta = min(J1, C0-J0)
            return (J0+delta, J1-delta)
        else:
            raise ValueError('Unrecognized action: ' + action)
    def path_cost(self, c, state1, action, state2):
        return c + 1

