class Task(object):
    def __init__(self, tmgr, descr, origin):
        descr.verify()
        self._tmgr   = tmgr
        self._descr  = descr.as_dict()
        self._origin = origin
        self._session          = self._tmgr.session
        self._uid              = self._descr.get('uid')
        self._state            = rps.NEW
        self._log              = tmgr._log
        self._exit_code        = None
        self._stdout           = None
        self._stderr           = None
        self._return_value     = None
        self._exception        = None
        self._pilot            = descr.get('pilot')
        self._resource_sandbox = None
        self._pilot_sandbox    = None
        self._task_sandbox     = None
        self._client_sandbox   = None
        self._callbacks        = dict()
        if self._uid:
            if not _check_uid(self._uid):
                raise ValueError('uid %s is not unique' % self._uid)
        else:
            self._uid = ru.generate_id('task.%(item_counter)06d', ru.ID_CUSTOM,
                                       ns=self._session.uid)
        for m in rpc.TMGR_METRICS:
            self._callbacks[m] = dict()
        self._callbacks[rpc.TASK_STATE][self._default_state_cb.__name__] = {
                'cb'      : self._default_state_cb,
                'cb_data' : None}
        expand_description(self._descr)
        self._tmgr.advance(self.as_dict(), rps.NEW, publish=False, push=False)
    def __repr__(self):
        return '<%s object, uid %s>' % (self.__class__.__qualname__, self._uid)
    def __str__(self):
        return str([self.uid, self.pilot, self.state])
    def _default_state_cb(self, task, state=None):
        self._log.info("[Callback]: task %s state: %s.", self.uid, self.state)
    def _update(self, task_dict):
        assert(task_dict['uid'] == self.uid), 'update called on wrong instance'
        current = self.state
        target  = task_dict['state']
        if target not in [rps.FAILED, rps.CANCELED]:
            s_tgt = rps._task_state_value(target)
            s_cur = rps._task_state_value(current)
            if s_tgt - s_cur != 1:
                self._log.error('%s: invalid state transition %s -> %s',
                                self.uid, current, target)
                raise RuntimeError('invalid state transition')
        self._state = target
        for key in ['state', 'stdout', 'stderr', 'exit_code', 'pilot',
                    'resource_sandbox', 'pilot_sandbox', 'task_sandbox',
                    'client_sandbox']:
            val = task_dict.get(key, None)
            if val is not None:
                setattr(self, "_%s" % key, val)
    def as_dict(self):
        ret = {
            'type':             'task',
            'tmgr':             self.tmgr.uid,
            'uid':              self.uid,
            'name':             self.name,
            'state':            self.state,
            'origin':           self.origin,
            'exit_code':        self.exit_code,
            'stdout':           self.stdout,
            'stderr':           self.stderr,
            'return_value':     self.return_value,
            'exception':        self.exception,
            'pilot':            self.pilot,
            'resource_sandbox': self.resource_sandbox,
            'pilot_sandbox':    self.pilot_sandbox,
            'task_sandbox':     self.task_sandbox,
            'client_sandbox':   self.client_sandbox,
            'description':      self.description   
        }
        return ret
    @property
    def session(self):
        return self._session
    @property
    def tmgr(self):
        return self._tmgr
    @property
    def uid(self):
        return self._uid
    @property
    def name(self):
        return self._descr.get('name')
    @property
    def origin(self):
        return self._origin
    @property
    def state(self):
        return self._state
    @property
    def exit_code(self):
        return self._exit_code
    @property
    def stdout(self):
        return self._stdout
    @property
    def stderr(self):
        return self._stderr
    @property
    def return_value(self):
        return self._return_value
    @property
    def exception(self):
        return self._exception
    @property
    def pilot(self):
        return self._pilot
    @property
    def working_directory(self):         
        return self.sandbox
    @property
    def sandbox(self):
        return self.task_sandbox
    @property
    def task_sandbox(self):
        return self._task_sandbox
    @property
    def resource_sandbox(self):
        return self._resource_sandbox
    @property
    def pilot_sandbox(self):
        return self._pilot_sandbox
    @property
    def client_sandbox(self):
        return self._client_sandbox
    @property
    def description(self):
        return copy.deepcopy(self._descr)
    @property
    def metadata(self):
        return copy.deepcopy(self._descr.get('metadata'))
    def register_callback(self, cb, cb_data=None, metric=None):
        if not metric:
            metric = rpc.TASK_STATE
        self._tmgr.register_callback(cb, cb_data, metric=metric, uid=self._uid)
    def wait(self, state=None, timeout=None):
        if not state:
            states = rps.FINAL
        if not isinstance(state, list):
            states = [state]
        else:
            states = state
        if self.state in rps.FINAL:
            if self.state in states:
                return
            return self.state
        start_wait = time.time()
        while self.state not in states:
            time.sleep(0.1)
            if timeout and (timeout <= (time.time() - start_wait)):
                break
            if self._tmgr._terminate.is_set():
                break
        return self.state
    def cancel(self):
        self._tmgr.cancel_tasks(self.uid)

class dictionary(subtype):
	def __init__(self, items=None):
		self._items={} if items is None else items
	def __call__(self, *arguments, **keywords):
		if "let" in keywords:
			if len(arguments)!=1: raise errors.wrong_number_of_arguments
			self._items[arguments[0].subtype]=keywords["let"].as_simple
		elif "set" in keywords:
			if len(arguments)!=1: raise errors.wrong_number_of_arguments
			self._items[arguments[0].subtype]=keywords["set"].as_complex
		else:
			if len(arguments)!=1: raise errors.wrong_number_of_arguments
			return self._items.get(arguments[0].subtype, v_empty)
	copy=property(lambda self: dictionary({key.copy: value.copy \
		for key, value in self._items.iteritems()}))
	code=property(lambda self: 9001)
	name=property(lambda self: "Dictionary")
	def erase(self, *arguments):
		if arguments:
			if len(arguments)>1: raise errors.wrong_number_of_arguments
			try: del self._items[arguments[0].as_simple]
			except KeyError: raise errors.invalid_procedure_call
		else:
			self._items.clear()
	as_simple=property(lambda self: self)
	as_dictionary=property(lambda self: self)
	def is_dictionary(self, function=None):
		return all((function(key, value) for ket, value in self._items.iteritems())) if function \
			else True
	items=property(lambda self: self._items)
	def __iter__(self):
		for item in self._items:
			yield variant(item)
	def __len__(self):
		return len(self._items)
	def __contains__(self, value):
		return value.subtype in self._items
	def __repr__(self):
		return "DICTIONARY@%08X:%r"%(id(self), self._items)

