class OAuthFlow(object):
    openapi_types = {
        'authorization_url': 'str',
        'token_url': 'str',
        'refresh_url': 'str',
        'scopes': 'dict(str, str)',
        'extensions': 'dict(str, object)'
    }
    attribute_map = {
        'authorization_url': 'authorizationUrl',
        'token_url': 'tokenUrl',
        'refresh_url': 'refreshUrl',
        'scopes': 'scopes',
        'extensions': 'extensions'
    }
    def __init__(self, authorization_url=None, token_url=None, refresh_url=None, scopes=None, extensions=None):  
        self._authorization_url = None
        self._token_url = None
        self._refresh_url = None
        self._scopes = None
        self._extensions = None
        self.discriminator = None
        if authorization_url is not None:
            self.authorization_url = authorization_url
        if token_url is not None:
            self.token_url = token_url
        if refresh_url is not None:
            self.refresh_url = refresh_url
        if scopes is not None:
            self.scopes = scopes
        if extensions is not None:
            self.extensions = extensions
    @property
    def authorization_url(self):
        return self._authorization_url
    @authorization_url.setter
    def authorization_url(self, authorization_url):
        self._authorization_url = authorization_url
    @property
    def token_url(self):
        return self._token_url
    @token_url.setter
    def token_url(self, token_url):
        self._token_url = token_url
    @property
    def refresh_url(self):
        return self._refresh_url
    @refresh_url.setter
    def refresh_url(self, refresh_url):
        self._refresh_url = refresh_url
    @property
    def scopes(self):
        return self._scopes
    @scopes.setter
    def scopes(self, scopes):
        self._scopes = scopes
    @property
    def extensions(self):
        return self._extensions
    @extensions.setter
    def extensions(self, extensions):
        self._extensions = extensions
    def to_dict(self):
        result = {}
        for attr, _ in six.iteritems(self.openapi_types):
            value = getattr(self, attr)
            if isinstance(value, list):
                result[attr] = list(map(
                    lambda x: x.to_dict() if hasattr(x, "to_dict") else x,
                    value
                ))
            elif hasattr(value, "to_dict"):
                result[attr] = value.to_dict()
            elif isinstance(value, dict):
                result[attr] = dict(map(
                    lambda item: (item[0], item[1].to_dict())
                    if hasattr(item[1], "to_dict") else item,
                    value.items()
                ))
            else:
                result[attr] = value
        return result
    def to_str(self):
        return pprint.pformat(self.to_dict())
    def __repr__(self):
        return self.to_str()
    def __eq__(self, other):
        if not isinstance(other, OAuthFlow):
            return False
        return self.__dict__ == other.__dict__
    def __ne__(self, other):
        return not self == other

class Scope(object):
  def __init__(self, parent):
    self.parent = parent
    self.values = {}
  def __repr__(self):
    return 'Scope[%s]' % self.values.keys()
  def copy(self):
    s = Scope(self.parent)
    s.values = self.values.copy()
    return s
  def setval(self, name, value):
    self.values[name] = value
  def hasval(self, name):
    return (name in self.values or
            (self.parent is not None and self.parent.hasval(name)))
  def getval(self, name):
    if name in self.values:
      return self.values[name]
    if self.parent is not None:
      return self.parent.getval(name)
    raise KeyError(name)

