class Vowel:
    def __init__(self, is_rounded, backness, height, is_nasal, is_vowel = True, is_consonant = False, is_voiced = True):
        self.is_rounded = is_rounded
        self.backness = backness
        self.height = height
        self.is_nasal = is_nasal
        self.is_consonant = is_consonant
        self.is_vowel = is_vowel
        self.is_voiced = is_voiced
    def __str__(self): 
        return_val = ''
        if self.is_rounded:
            if self.backness == 'back' or self.backness == 'near_back':
                if self.height == 'open':
                    return_val = 'o'
                else:
                    return_val = 'u'
            if self.backness == 'central':
                return_val = 'ò'
            if self.backness == 'front' or 'near_front':
                if self.height == 'close':
                    return_val = 'û'
                else:
                    return_val = 'u'
        else:
            if self.backness == 'back' or self.backness == 'near_back':
                if self.height == 'open':
                    return_val = 'a'
                else:
                    return_val = 'u'
            if self.backness == 'central':
                if self.height == 'open':
                    return_val = 'é'
                if self.height == 'mid':
                    return_val = 'e'
                if self.height == 'close':
                    return_val = 'i'
            if self.backness == 'front' or self.backness == 'near_front':
                if self.height == 'close':
                    return_val = 'i'
                else:
                    return_val = 'æ'
        if self.is_nasal:
            if return_val == 'a':
                return_val = 'ä'
            if return_val == 'e':
                return_val = 'ë'
            if return_val == 'i':
                return_val = 'ï'
            if return_val == 'o':
                return_val = 'ö'
            if return_val == 'u':
                return_val = 'ü'
        return return_val
    def __repr__(self):
        return str(self)

class Consonant:
    def __init__(self, is_voiced, is_aspirated, place_of_articulation, type_of_articulation, is_ejective, is_lateral,
                 is_nasal, is_vowel = False, is_consonant = True):
        self.is_voiced = is_voiced
        self.is_aspirated = is_aspirated
        self.place_of_articulation = place_of_articulation
        self.type_of_articulation = type_of_articulation
        self.is_ejective = is_ejective
        self.is_lateral = is_lateral
        self.is_nasal = is_nasal
        self.is_consonant = is_consonant
        self.is_vowel = is_vowel
    def __str__(self): 
        return_val = ''
        if self.type_of_articulation == 'plosive':
            if self.place_of_articulation == 'bilabial':
                if not self.is_voiced:
                    if not self.is_aspirated:
                        return_val = 'p'
                    else:
                        return_val = 'ph'
                else:
                    return_val = 'b'
            elif self.place_of_articulation == 'dental' or self.place_of_articulation == 'alveolar':
                if not self.is_voiced:
                    if not self.is_aspirated:
                        return_val = 't'
                    else:
                        return_val = 'th'
                else:
                    return_val = 'd'
            elif self.place_of_articulation == 'palatal':
                if not self.is_voiced:
                    if not self.is_aspirated:
                        return_val = 'c'
                    else:
                        return_val = 'ch'
                else:
                    return_val = 'j'
            elif self.place_of_articulation == 'velar':
                if not self.is_voiced:
                    if not self.is_aspirated:
                        return_val = 'k'
                    else:
                        return_val = 'kh'
                else:
                    return_val = 'g'
            elif self.place_of_articulation == 'uvular':
                if not self.is_voiced:
                    if not self.is_aspirated:
                        return_val = 'q'
                    else:
                        return_val = 'qh'
                else:
                    return_val = 'G'
            else:
                return_val = "'"
        if self.type_of_articulation == 'fricative':
            if self.place_of_articulation == 'bilabial':
                if not self.is_voiced:
                    return_val = 'w'
                else:
                    return_val = 'v'
                    if self.is_nasal:
                        return_val = 'm'
            elif self.place_of_articulation == 'dental':
                return_val = 'th'
            elif self.place_of_articulation == 'alveolar':
                if not self.is_voiced:
                    return_val = 's'
                else:
                    return_val = 'z'
                    if self.is_nasal:
                        return_val = 'n'
                    if self.is_lateral:
                        return_val = 'l'
            elif self.place_of_articulation == 'palatal':
                if not self.is_voiced:
                    return_val = 'ç'
                else:
                    return_val = 'y'
                    if self.is_nasal:
                        return_val = 'ñ'
            elif self.place_of_articulation == 'velar' or self.place_of_articulation == 'uvular':
                if not self.is_voiced:
                    return_val = 'x'
                else:
                    return_val = 'gh'
                    if self.is_nasal:
                        return_val = 'ng'
            else:
                return_val = 'h'
        if self.type_of_articulation == 'affricate':
            if self.place_of_articulation == 'dental' or self.place_of_articulation == 'alveolar':
                if not self.is_voiced:
                    if not self.is_aspirated:
                        return_val = 'ts'
                        if self.is_lateral:
                            return_val = 'tl'
                    else:
                        return_val = 'tsh'
                else:
                    return_val = 'dz'
                    if self.is_lateral:
                        return_val = 'dl'
            elif self.place_of_articulation == 'palatal':
                if not self.is_voiced:
                    if not self.is_aspirated:
                        return_val = 'ch'
                    else:
                        return_val = 'chh'
                else:
                    return_val = 'j'
            else:
                if not self.is_voiced:
                    if not self.is_aspirated:
                        return_val = 'qx'
                    else:
                        return_val = 'qxh'
        if self.is_ejective and self.place_of_articulation != 'glottal' and (
                self.type_of_articulation == 'plosive' or self.type_of_articulation == 'affricate') and self.is_voiced == False and return_val != '' and self.is_aspirated == False:
            return_val += "'"
        return return_val
    def __repr__(self):
        return str(self)

class ExponentialMovingAverage(object):
    def __init__(self, module, decay=0.999):
        self.decay = decay
        self.module_params = {n: p for (n, p) in module.named_parameters()}
        self.ema_params = {n: p.data.clone() for (n, p) in module.named_parameters()}
        self.nparams = sum(p.numel() for (_, p) in self.ema_params.items())
    def apply(self, decay=None):
        decay = decay or self.decay
        with torch.no_grad():
            for name, param in self.module_params.items():
                self.ema_params[name] -= (1 - decay) * (self.ema_params[name] - param.data)
    def set(self, named_params):
        with torch.no_grad():
            for name, param in named_params.items():
                self.ema_params[name].copy_(param)
    def replace_with_ema(self):
        for name, param in self.module_params.items():
            param.data.copy_(self.ema_params[name])
    def swap(self):
        for name, param in self.module_params.items():
            tmp = self.ema_params[name].clone()
            self.ema_params[name].copy_(param.data)
            param.data.copy_(tmp)
    def __repr__(self):
        return (
            '{}(decay={}, module={}, nparams={})'.format(
                self.__class__.__name__, self.decay, self.module.__class__.__name__, self.nparams
            )
        )

class IssueReport(JSONSerializable):
