class Quotes(object):
    def __init__(self, _ticker, _date, _quoteReader):
        self._ticker = _ticker
        self._date = _date
        self._quoteReader = _quoteReader
        self._N = _quoteReader.getN()
        self._epoch = _quoteReader.getSecsFromEpocToMidn()
        self._qb = np.zeros(self._N, dtype=float)  
        self._qa = np.zeros(self._N, dtype=float)  
        self._bs = np.zeros(self._N, dtype=int)  
        self._as = np.zeros(self._N, dtype=int)  
        self._qt = np.zeros(self._N, dtype=int)  
        for i in range(self._N):
            self._qb[i] = self._quoteReader.getBidPrice(i)
            self._qa[i] = self._quoteReader.getAskPrice(i)
            self._bs[i] = self._quoteReader.getBidSize(i)
            self._as[i] = self._quoteReader.getAskSize(i)
            self._qt[i] = self._quoteReader.getMillisFromMidn(i)
    @property
    def N(self):
        return self._N
    @property
    def epoch(self):
        return self._epoch
    @property
    def qb(self):
        return self._qb
    @property
    def qa(self):
        return self._qa
    @property
    def bs(self):
        return self._bs
    @property
    def As(self):
        return self._as
    @property
    def qt(self):
        return self._qt
    def __repr__(self):
        return "Quotes object of {0} at date {1}".format(self._ticker, self._date)
    def adj(self, cumPriceFactor, cumShareFactor):
        self._qb /= cumPriceFactor
        self._qa /= cumPriceFactor
        self._bs = (self._bs * cumShareFactor).astype(int)
        self._as = (self._as * cumShareFactor).astype(int)
    def setQb(self, idx, val):
        self._qb[idx] = val
    def setQa(self, idx, val):
        self._qa[idx] = val
    def setAs(self, idx, val):
        self._as[idx] = val
    def setBs(self, idx, val):
        self._bs[idx] = val
    def clean(self, midPrice, band):
        idx1 = (np.abs(self._qb - midPrice) <= band)
        idx2 = (np.abs(self._qa - midPrice) <= band)
        idxs = idx1 & idx2
        self._qt = self._qt[idxs]
        self._qa = self._qa[idxs]
        self._qb = self._qb[idxs]
        self._as = self._as[idxs]
        self._bs = self._bs[idxs]
        self._N = self._qt.shape[0]
    def getN(self):
        return self._N
    def getPrice(self, idx):
        return (self._qa[idx] + self._qb[idx]) / 2.
    def getTimestamp(self, idx):
        return self._qt[idx]

class Future(object):
    def __init__(self):
        self._condition = threading.Condition()
        self._state = PENDING
        self._result = None
        self._exception = None
        self._waiters = []
        self._done_callbacks = []
    def _invoke_callbacks(self):
        for callback in self._done_callbacks:
            try:
                callback(self)
            except Exception:
                LOGGER.exception('exception calling callback for %r', self)
    def __repr__(self):
        with self._condition:
            if self._state == FINISHED:
                if self._exception:
                    return '<Future at %s state=%s raised %s>' % (
                        hex(id(self)),
                        _STATE_TO_DESCRIPTION_MAP[self._state],
                        self._exception.__class__.__name__)
                else:
                    return '<Future at %s state=%s returned %s>' % (
                        hex(id(self)),
                        _STATE_TO_DESCRIPTION_MAP[self._state],
                        self._result.__class__.__name__)
            return '<Future at %s state=%s>' % (
                    hex(id(self)),
                   _STATE_TO_DESCRIPTION_MAP[self._state])
    def cancel(self):
        with self._condition:
            if self._state in [RUNNING, FINISHED]:
                return False
            if self._state in [CANCELLED, CANCELLED_AND_NOTIFIED]:
                return True
            self._state = CANCELLED
            self._condition.notify_all()
        self._invoke_callbacks()
        return True
    def cancelled(self):
        with self._condition:
            return self._state in [CANCELLED, CANCELLED_AND_NOTIFIED]
    def running(self):
        with self._condition:
            return self._state == RUNNING
    def done(self):
        with self._condition:
            return self._state in [CANCELLED, CANCELLED_AND_NOTIFIED, FINISHED]
    def __get_result(self):
        if self._exception:
            raise self._exception
        else:
            return self._result
    def add_done_callback(self, fn):
        with self._condition:
            if self._state not in [CANCELLED, CANCELLED_AND_NOTIFIED, FINISHED]:
                self._done_callbacks.append(fn)
                return
        fn(self)
    def result(self, timeout=None):
        with self._condition:
            if self._state in [CANCELLED, CANCELLED_AND_NOTIFIED]:
                raise CancelledError()
            elif self._state == FINISHED:
                return self.__get_result()
            self._condition.wait(timeout)
            if self._state in [CANCELLED, CANCELLED_AND_NOTIFIED]:
                raise CancelledError()
            elif self._state == FINISHED:
                return self.__get_result()
            else:
                raise TimeoutError()
    def exception(self, timeout=None):
        with self._condition:
            if self._state in [CANCELLED, CANCELLED_AND_NOTIFIED]:
                raise CancelledError()
            elif self._state == FINISHED:
                return self._exception
            self._condition.wait(timeout)
            if self._state in [CANCELLED, CANCELLED_AND_NOTIFIED]:
                raise CancelledError()
            elif self._state == FINISHED:
                return self._exception
            else:
                raise TimeoutError()
    def set_running_or_notify_cancel(self):
        with self._condition:
            if self._state == CANCELLED:
                self._state = CANCELLED_AND_NOTIFIED
                for waiter in self._waiters:
                    waiter.add_cancelled(self)
                return False
            elif self._state == PENDING:
                self._state = RUNNING
                return True
            else:
                LOGGER.critical('Future %s in unexpected state: %s',
                                id(self),
                                self._state)
                raise RuntimeError('Future in unexpected state')
    def set_result(self, result):
        with self._condition:
            self._result = result
            self._state = FINISHED
            for waiter in self._waiters:
                waiter.add_result(self)
            self._condition.notify_all()
        self._invoke_callbacks()
    def set_exception(self, exception):
        with self._condition:
            self._exception = exception
            self._state = FINISHED
            for waiter in self._waiters:
                waiter.add_exception(self)
            self._condition.notify_all()
        self._invoke_callbacks()

