class TypeAST(AST):
    def __init__(self, slicc, ident):
        super(TypeAST, self).__init__(slicc)
        self.ident = ident
    def __repr__(self):
        return self.ident
    def __str__(self):
        return self.ident
    @property
    def type(self, assert_type=None):
        type = self.symtab.find(self.ident, Type)
        if not type:
