class Schedule(ScheduleComponent):
    def __init__(self, *schedules: List[Union[ScheduleComponent, Tuple[int, ScheduleComponent]]],
                 name: str = None):
        self._name = name
        try:
            timeslots = []
            _children = []
            for sched_pair in schedules:
                if not isinstance(sched_pair, (list, tuple)):
                    sched_pair = (0, sched_pair)
                sched_pair = tuple(sched_pair)
                insert_time, sched = sched_pair
                sched_timeslots = sched.timeslots
                if insert_time:
                    sched_timeslots = sched_timeslots.shift(insert_time)
                timeslots.append(sched_timeslots.timeslots)
                _children.append(sched_pair)
            self._timeslots = TimeslotCollection(*itertools.chain(*timeslots))
            self.__children = tuple(_children)
            self._buffer = max([child.buffer for _, child in _children]) if _children else 0
        except PulseError as ts_err:
            raise PulseError('Child schedules {0} overlap.'.format(schedules)) from ts_err
    @property
    def name(self) -> str:
        return self._name
    @property
    def timeslots(self) -> TimeslotCollection:
        return self._timeslots
    @property
    def duration(self) -> int:
        return self.timeslots.duration
    @property
    def start_time(self) -> int:
        return self.timeslots.start_time
    @property
    def stop_time(self) -> int:
        return self.timeslots.stop_time
    @property
    def buffer(self) -> int:
        return self._buffer
    @property
    def channels(self) -> Tuple[Channel]:
        return self.timeslots.channels
    @property
    def _children(self) -> Tuple[ScheduleComponent]:
        return self.__children
    @property
    def instructions(self) -> Tuple[Tuple[int, 'Instruction']]:
        return tuple(self._instructions())
    def ch_duration(self, *channels: List[Channel]) -> int:
        return self.timeslots.ch_duration(*channels)
    def ch_start_time(self, *channels: List[Channel]) -> int:
        return self.timeslots.ch_start_time(*channels)
    def ch_stop_time(self, *channels: List[Channel]) -> int:
        return self.timeslots.ch_stop_time(*channels)
    def _instructions(self, time: int = 0) -> Iterable[Tuple[int, 'Instruction']]:
        for insert_time, child_sched in self._children:
            yield from child_sched._instructions(time + insert_time)
    def union(self, *schedules: List[ScheduleComponent], name: str = None) -> 'Schedule':
        return ops.union(self, *schedules, name=name)
    def shift(self: ScheduleComponent, time: int, name: str = None) -> 'Schedule':
        return ops.shift(self, time, name=name)
    def insert(self, start_time: int, schedule: ScheduleComponent, buffer: bool = False,
               name: str = None) -> 'Schedule':
        return ops.insert(self, start_time, schedule, buffer=buffer, name=name)
    def append(self, schedule: ScheduleComponent, buffer: bool = True,
               name: str = None) -> 'Schedule':
        return ops.append(self, schedule, buffer=buffer, name=name)
    def flatten(self) -> 'ScheduleComponent':
        return ops.flatten(self)
    def draw(self, dt: float = 1, style=None,
             filename: str = None, interp_method: Callable = None, scaling: float = 1,
             channels_to_plot: List[Channel] = None, plot_all: bool = False,
             plot_range: Tuple[float] = None, interactive: bool = False,
             table: bool = True, label: bool = False,
             framechange: bool = True):
        from qiskit.tools import visualization
        return visualization.pulse_drawer(self, dt=dt, style=style,
                                          filename=filename, interp_method=interp_method,
                                          scaling=scaling, channels_to_plot=channels_to_plot,
                                          plot_all=plot_all, plot_range=plot_range,
                                          interactive=interactive, table=table,
                                          label=label, framechange=framechange)
    def __add__(self, schedule: ScheduleComponent) -> 'Schedule':
        return self.append(schedule)
    def __or__(self, schedule: ScheduleComponent) -> 'Schedule':
        return self.union(schedule)
    def __lshift__(self, time: int) -> 'Schedule':
        return self.shift(time)
    def __repr__(self):
        res = 'Schedule("name=%s", ' % self._name if self._name else 'Schedule('
        res += '%d, ' % self.start_time
        instructions = [repr(instr) for instr in self.instructions]
        res += ', '.join([str(i) for i in instructions[:50]])
        if len(instructions) > 50:
            return res + ', ...)'
        return res + ')'

class Customer(object):
  used_ips = []
  nextUserIndex = 1
  nextDeviceIndex = 1
  def __init__(self):
    self.ip = self.getNewRandomIp()
    self.userId = self.getNextUserId()
    self.deviceId = self.getNextDeviceId()
  def start(self, page, time=None):
    self.page = page
    self.time = time if time else datetime.datetime.now()
    self.history = []
  @classmethod
  def getNewRandomIp(cls):
    new_ip = "{}.{}.{}.{}".format(random.randint(0,255), random.randint(0,255), random.randint(0,255), random.randint(0,255))
    while new_ip in cls.used_ips:
      new_ip = "{}.{}.{}.{}".format(random.randint(0,255), random.randint(0,255), random.randint(0,255), random.randint(0,255))
    cls.used_ips.append(new_ip)
    return new_ip
  @classmethod
  def getNextUserId(cls):
    userId = "user_{:0{width}}".format(cls.nextUserIndex, width=8)
    cls.nextUserIndex += 1
    return userId
  @classmethod
  def getNextDeviceId(cls):
    deviceId = "device_{:0{width}}".format(cls.nextDeviceIndex, width=8)
    cls.nextDeviceIndex += 1
    return deviceId
  @classmethod
  def calculateCumulativeWeightedTransitions(cls, weighted_transitions):
    weights,transitions = [list(wt) for wt in zip(*weighted_transitions)]
    totalWeights = sum(weights)
    cumulativeWeights = [float(sum(weights[:i+1]))/totalWeights for (i,w) in enumerate(weights)]
    return zip(cumulativeWeights, transitions)
  @classmethod
  def pick(cls, weighted_transitions, p):
    cumulativeWeights = cls.calculateCumulativeWeightedTransitions(weighted_transitions) 
    for (cw, t) in cumulativeWeights:
      if p < cw:
        return t
    return t 
  def step(self):
    if self.page.quitProb > random.random():
      self.page = None
      return
    if not self.page.transitions:
      self.page = None
      return
    transition = self.pick(self.page.transitions, random.random())
    self.page = transition.destination
    self.time += datetime.timedelta(0,max(0,random.gauss(transition.timeBeforePageChange,transition.timeBeforePageChange/4)))
    self.history.append((self.time, transition))
  def createHistory(self, length=0):
    while self.page and (length == 0 or len(self.history) <= length):
      self.step()
  def formatHistory(self):
    for (transitionTime, transition) in self.history:
      if transition.destination == None:
        return
      if transition.destination.logged:
        logline_data = {
          "ip": self.ip,
          "user": self.userId,
          "time": transitionTime.strftime("[%d/%b/%Y:%H:%M:%S +0000]"),
          "method": transition.method,
          "destination": re.sub(r':userId', self.userId, transition.destination.path),
          "status": transition.status,
          "size": transition.destination.size,
          "source": transition.source.domain + re.sub(r':userId', self.userId, transition.source.path),
          "fingerprint": self.deviceId
        }
        yield (transitionTime, transition.destination.logtemplate.format(**logline_data))
  def __repr__(self):
    return "User {}: ip = {}; device = {}".format(self.userId, self.ip, self.deviceId)

class Transition(object):
  def __init__(self, source, destination, method='GET', status=None, timeBeforePageChange=120.0):
    self.source = source
    self.destination = destination
    self.method = method
    self.timeBeforePageChange = timeBeforePageChange
    defaultStatus = {'GET': 200, 'POST': 201, 'PUT': 200}
    self.status = status if status else defaultStatus.get(method, 200)
  def __repr__(self):
    return "Transition: ({}) -> ({}) (method: {} status: {} in {} seconds)".format(
      self.source, self.destination, self.method, 
      self.status, self.timeBeforePageChange
    )

class Page(object):
  def __init__(self, path, size=None, domain=None, quitProb=0.001, logged=True, logtemplate=None):
    self.path = path
    self.domain = domain if domain else "www.example.com"
    self.size = size if size else random.randint(200, 2000)
    self.quitProb = quitProb
    self.logged = logged
    self.logtemplate = logtemplate if logtemplate else "{ip} {user} {time} \"{method} {destination}\" {status} {size} \"{source}\" {fingerprint}"
    self.transitions = []
  def addNextPage(self, page, method='GET', status=None, timeBeforePageChange=120.0, likelyhoodWeight=1):
    self.transitions.append((likelyhoodWeight, Transition(self, page, method, status, timeBeforePageChange)))
  def __repr__(self):
    return "Page: <{},{}>".format(self.domain, self.path)

