class CachedSession(OriginalSession):
    def __init__(self, cache_name='cache', backend=None, expire_after=None,
                 allowable_codes=(200,), allowable_methods=('GET',),
                 old_data_on_error=False, **backend_options):
        self.cache = backends.create_backend(backend, cache_name, backend_options)
        self._cache_name = cache_name
        if expire_after is not None and not isinstance(expire_after, timedelta):
            expire_after = timedelta(seconds=expire_after)
        self._cache_expire_after = expire_after
        self._cache_allowable_codes = allowable_codes
        self._cache_allowable_methods = allowable_methods
        self._return_old_data_on_error = old_data_on_error
        self._is_cache_disabled = False
        self._update_cache_enabled = False
        super(CachedSession, self).__init__()
    def _request(self, method, url,
            params=None, data=None, headers=None, cookies=None, files=None,
            auth=None, timeout=None, allow_redirects=True, proxies=None,
            hooks=None, stream=None, verify=None, cert=None, json=None, 
            from_cache=True, update_cache=False):
        req = Request(
            method=method.upper(),
            url=url,
            headers=headers,
            files=files,
            data=data or {},
            json=json,
            params=params or {},
            auth=auth,
            cookies=cookies,
            hooks=hooks,
        )
        prep = self.prepare_request(req)
        proxies = proxies or {}
        settings = self.merge_environment_settings(
            prep.url, proxies, stream, verify, cert
        )
        send_kwargs = {
            'timeout': timeout,
            'allow_redirects': allow_redirects,
            'from_cache': from_cache,
            'update_cache': update_cache
        }
        send_kwargs.update(settings)
        resp = self.send(prep, **send_kwargs)
        return resp
    def send(self, request, from_cache=True, update_cache=False, **kwargs):
        print("URL:{0}, FROM_CACHE:{1}, UPDATE_CACHE:{2}".format(request.url, from_cache, update_cache))
        if (self._is_cache_disabled
            or request.method not in self._cache_allowable_methods) or (not from_cache and not update_cache):
            response = super(CachedSession, self).send(request, **kwargs)
            response.from_cache = False
            return response
        cache_key = self.cache.create_key(request)
        def send_request_and_cache_response():
            response = super(CachedSession, self).send(request, **kwargs)
            if response.status_code in self._cache_allowable_codes:
                self.cache.save_response(cache_key, response)
            response.from_cache = False
            return response
        if update_cache:
            return send_request_and_cache_response()
        response, timestamp = self.cache.get_response_and_time(cache_key)
        if response is None:
            return send_request_and_cache_response()
        if self._cache_expire_after is not None:
            is_expired = datetime.utcnow() - timestamp > self._cache_expire_after
            if is_expired:
                if not self._return_old_data_on_error:
                    self.cache.delete(cache_key)
                    return send_request_and_cache_response()
                try:
                    new_response = send_request_and_cache_response()
                except Exception:
                    return response
                else:
                    if new_response.status_code not in self._cache_allowable_codes:
                        return response
                    return new_response
        response.from_cache = True
        response = dispatch_hook('response', request.hooks, response, **kwargs)
        return response
    def request(self, method, url, params=None, data=None, **kwargs):
        response = self._request(
            method, url,
            _normalize_parameters(params),
            _normalize_parameters(data),
            **kwargs
        )
        if self._is_cache_disabled:
            return response
        main_key = self.cache.create_key(response.request)
        for r in response.history:
            self.cache.add_key_mapping(
                self.cache.create_key(r.request), main_key
            )
        return response
    @contextmanager
    def cache_disabled(self):
        self._is_cache_disabled = True
        try:
            yield
        finally:
            self._is_cache_disabled = False
    def remove_expired_responses(self):
        if not self._cache_expire_after:
            return
        self.cache.remove_old_entries(datetime.utcnow() - self._cache_expire_after)
    def __repr__(self):
        return (
            "<CachedSession(%s('%s', ...), expire_after=%s, "
            "allowable_methods=%s)>" % (
                self.cache.__class__.__name__, self._cache_name,
                self._cache_expire_after, self._cache_allowable_methods
            )
        )

class Entity(dict):
    def __init__(self, key=None, exclude_from_indexes=()):
        super(Entity, self).__init__()
        self.key = key
        self.exclude_from_indexes = set(
            _ensure_tuple_or_list("exclude_from_indexes", exclude_from_indexes)
        )
        self._meanings = {}
    def __eq__(self, other):
        if not isinstance(other, Entity):
            return NotImplemented
        return (
            self.key == other.key
            and self.exclude_from_indexes == other.exclude_from_indexes
            and self._meanings == other._meanings
            and super(Entity, self).__eq__(other)
        )
    def __ne__(self, other):
        return not self == other
    @property
    def kind(self):
        if self.key:
            return self.key.kind
    @property
    def id(self):
        if self.key is None:
            return None
        else:
            return self.key.id
    def __repr__(self):
        if self.key:
            return "<Entity%s %s>" % (
                self.key._flat_path,
                super(Entity, self).__repr__(),
            )
        else:
            return "<Entity %s>" % (super(Entity, self).__repr__(),)

class EndEffector(object):
    def __init__(self, robot, ee_link, tool_link, **kwargs):
        self.robot = robot
        self.ee_link = ee_link
        self.tool_link = tool_link
        self.tool_from_ee = get_relative_pose(self.robot, self.ee_link, self.tool_link)
        tool_links = get_link_subtree(robot, self.ee_link)
        self.body = clone_body(robot, links=tool_links, **kwargs)
        set_static(self.body)
    def get_tool_pose(self, get_cloned_pose=True):
        if not clone_body:
            return get_link_pose(self.robot, self.tool_link)
        else:
            ee_pose = get_pose(self.body)
            return multiply(ee_pose, invert(self.tool_from_ee))
    def set_pose(self, tool_pose):
        pose = multiply(tool_pose, self.tool_from_ee)
        set_pose(self.body, pose)
        return pose
    @property
    def tool_from_root(self):
        return self.tool_from_ee
    def __repr__(self):
        return '{}({}, {})'.format(self.__class__.__name__, self.robot, self.body)

