            return r_json
    def revoke_refresh_token(self, **kwargs):
        c = self.get_credentials()
        data = {
            "client_id": c.client_id,
            "client_secret": c.client_secret,
            "token": c.refresh_token,
            "token_type_hint": "refresh_token",
        }
