class TransferFunction(LinearTimeInvariant):
    r
    def __new__(cls, *system, **kwargs):
        if len(system) == 1 and isinstance(system[0], LinearTimeInvariant):
            return system[0].to_tf()
        if cls is TransferFunction:
            if kwargs.get('dt') is None:
                return TransferFunctionContinuous.__new__(
                    TransferFunctionContinuous,
                    *system,
                    **kwargs)
            else:
                return TransferFunctionDiscrete.__new__(
                    TransferFunctionDiscrete,
                    *system,
                    **kwargs)
        return super(TransferFunction, cls).__new__(cls)
    def __init__(self, *system, **kwargs):
        if isinstance(system[0], LinearTimeInvariant):
            return
        super(TransferFunction, self).__init__(**kwargs)
        self._num = None
        self._den = None
        self.num, self.den = normalize(*system)
    def __repr__(self):
        return '{0}(\n{1},\n{2},\ndt: {3}\n)'.format(
            self.__class__.__name__,
            repr(self.num),
            repr(self.den),
            repr(self.dt),
            )
    @property
    def num(self):
        return self._num
    @num.setter
    def num(self, num):
        self._num = atleast_1d(num)
        if len(self.num.shape) > 1:
            self.outputs, self.inputs = self.num.shape
        else:
            self.outputs = 1
            self.inputs = 1
    @property
    def den(self):
        return self._den
    @den.setter
    def den(self, den):
        self._den = atleast_1d(den)
    def _copy(self, system):
        self.num = system.num
        self.den = system.den
    def to_tf(self):
        return copy.deepcopy(self)
    def to_zpk(self):
        return ZerosPolesGain(*tf2zpk(self.num, self.den),
                              **self._dt_dict)
    def to_ss(self):
        return StateSpace(*tf2ss(self.num, self.den),
                          **self._dt_dict)
    @staticmethod
    def _z_to_zinv(num, den):
        diff = len(num) - len(den)
        if diff > 0:
            den = np.hstack((np.zeros(diff), den))
        elif diff < 0:
            num = np.hstack((np.zeros(-diff), num))
        return num, den
    @staticmethod
    def _zinv_to_z(num, den):
        diff = len(num) - len(den)
        if diff > 0:
            den = np.hstack((den, np.zeros(diff)))
        elif diff < 0:
            num = np.hstack((num, np.zeros(-diff)))
        return num, den

class ZerosPolesGain(LinearTimeInvariant):
    r
    def __new__(cls, *system, **kwargs):
        if len(system) == 1 and isinstance(system[0], LinearTimeInvariant):
            return system[0].to_zpk()
        if cls is ZerosPolesGain:
            if kwargs.get('dt') is None:
                return ZerosPolesGainContinuous.__new__(
                    ZerosPolesGainContinuous,
                    *system,
                    **kwargs)
            else:
                return ZerosPolesGainDiscrete.__new__(
                    ZerosPolesGainDiscrete,
                    *system,
                    **kwargs
                    )
        return super(ZerosPolesGain, cls).__new__(cls)
    def __init__(self, *system, **kwargs):
        if isinstance(system[0], LinearTimeInvariant):
            return
        super(ZerosPolesGain, self).__init__(**kwargs)
        self._zeros = None
        self._poles = None
        self._gain = None
        self.zeros, self.poles, self.gain = system
    def __repr__(self):
        return '{0}(\n{1},\n{2},\n{3},\ndt: {4}\n)'.format(
            self.__class__.__name__,
            repr(self.zeros),
            repr(self.poles),
            repr(self.gain),
            repr(self.dt),
            )
    @property
    def zeros(self):
        return self._zeros
    @zeros.setter
    def zeros(self, zeros):
        self._zeros = atleast_1d(zeros)
        if len(self.zeros.shape) > 1:
            self.outputs, self.inputs = self.zeros.shape
        else:
            self.outputs = 1
            self.inputs = 1
    @property
    def poles(self):
        return self._poles
    @poles.setter
    def poles(self, poles):
        self._poles = atleast_1d(poles)
    @property
    def gain(self):
        return self._gain
    @gain.setter
    def gain(self, gain):
        self._gain = gain
    def _copy(self, system):
        self.poles = system.poles
        self.zeros = system.zeros
        self.gain = system.gain
    def to_tf(self):
        return TransferFunction(*zpk2tf(self.zeros, self.poles, self.gain),
                                **self._dt_dict)
    def to_zpk(self):
        return copy.deepcopy(self)
    def to_ss(self):
        return StateSpace(*zpk2ss(self.zeros, self.poles, self.gain),
                          **self._dt_dict)

class StateSpace(LinearTimeInvariant):
    r
    __array_priority__ = 100.0
    __array_ufunc__ = None
    def __new__(cls, *system, **kwargs):
        if len(system) == 1 and isinstance(system[0], LinearTimeInvariant):
            return system[0].to_ss()
        if cls is StateSpace:
            if kwargs.get('dt') is None:
                return StateSpaceContinuous.__new__(StateSpaceContinuous,
                                                    *system, **kwargs)
            else:
                return StateSpaceDiscrete.__new__(StateSpaceDiscrete,
                                                  *system, **kwargs)
        return super(StateSpace, cls).__new__(cls)
    def __init__(self, *system, **kwargs):
        if isinstance(system[0], LinearTimeInvariant):
            return
        super(StateSpace, self).__init__(**kwargs)
        self._A = None
        self._B = None
        self._C = None
        self._D = None
        self.A, self.B, self.C, self.D = abcd_normalize(*system)
    def __repr__(self):
        return '{0}(\n{1},\n{2},\n{3},\n{4},\ndt: {5}\n)'.format(
            self.__class__.__name__,
            repr(self.A),
            repr(self.B),
            repr(self.C),
            repr(self.D),
            repr(self.dt),
            )
    def _check_binop_other(self, other):
        return isinstance(other, (StateSpace, np.ndarray, float, complex,
                                  np.number, int))
    def __mul__(self, other):
        if not self._check_binop_other(other):
            return NotImplemented
        if isinstance(other, StateSpace):
            if type(other) is not type(self):
                return NotImplemented
            if self.dt != other.dt:
                raise TypeError('Cannot multiply systems with different `dt`.')
            n1 = self.A.shape[0]
            n2 = other.A.shape[0]
            a = np.vstack((np.hstack((self.A, np.dot(self.B, other.C))),
                           np.hstack((zeros((n2, n1)), other.A))))
            b = np.vstack((np.dot(self.B, other.D), other.B))
            c = np.hstack((self.C, np.dot(self.D, other.C)))
            d = np.dot(self.D, other.D)
        else:
            a = self.A
            b = np.dot(self.B, other)
            c = self.C
            d = np.dot(self.D, other)
        common_dtype = np.find_common_type((a.dtype, b.dtype, c.dtype, d.dtype), ())
        return StateSpace(np.asarray(a, dtype=common_dtype),
                          np.asarray(b, dtype=common_dtype),
                          np.asarray(c, dtype=common_dtype),
                          np.asarray(d, dtype=common_dtype),
                          **self._dt_dict)
    def __rmul__(self, other):
        if not self._check_binop_other(other) or isinstance(other, StateSpace):
            return NotImplemented
        a = self.A
        b = self.B
        c = np.dot(other, self.C)
        d = np.dot(other, self.D)
        common_dtype = np.find_common_type((a.dtype, b.dtype, c.dtype, d.dtype), ())
        return StateSpace(np.asarray(a, dtype=common_dtype),
                          np.asarray(b, dtype=common_dtype),
                          np.asarray(c, dtype=common_dtype),
                          np.asarray(d, dtype=common_dtype),
                          **self._dt_dict)
    def __neg__(self):
        return StateSpace(self.A, self.B, -self.C, -self.D, **self._dt_dict)
    def __add__(self, other):
        if not self._check_binop_other(other):
            return NotImplemented
        if isinstance(other, StateSpace):
            if type(other) is not type(self):
                raise TypeError('Cannot add {} and {}'.format(type(self),
                                                              type(other)))
            if self.dt != other.dt:
                raise TypeError('Cannot add systems with different `dt`.')
            a = linalg.block_diag(self.A, other.A)
            b = np.vstack((self.B, other.B))
            c = np.hstack((self.C, other.C))
            d = self.D + other.D
        else:
            other = np.atleast_2d(other)
            if self.D.shape == other.shape:
                a = self.A
                b = self.B
                c = self.C
                d = self.D + other
            else:
                raise ValueError("Cannot add systems with incompatible "
                                 "dimensions ({} and {})"
                                 .format(self.D.shape, other.shape))
        common_dtype = np.find_common_type((a.dtype, b.dtype, c.dtype, d.dtype), ())
        return StateSpace(np.asarray(a, dtype=common_dtype),
                          np.asarray(b, dtype=common_dtype),
                          np.asarray(c, dtype=common_dtype),
                          np.asarray(d, dtype=common_dtype),
                          **self._dt_dict)
    def __sub__(self, other):
        if not self._check_binop_other(other):
            return NotImplemented
        return self.__add__(-other)
    def __radd__(self, other):
        if not self._check_binop_other(other):
            return NotImplemented
        return self.__add__(other)
    def __rsub__(self, other):
        if not self._check_binop_other(other):
            return NotImplemented
        return (-self).__add__(other)
    def __truediv__(self, other):
        if not self._check_binop_other(other) or isinstance(other, StateSpace):
            return NotImplemented
        if isinstance(other, np.ndarray) and other.ndim > 0:
            raise ValueError("Cannot divide StateSpace by non-scalar numpy arrays")
        return self.__mul__(1/other)
    @property
    def A(self):
        return self._A
    @A.setter
    def A(self, A):
        self._A = _atleast_2d_or_none(A)
    @property
    def B(self):
        return self._B
    @B.setter
    def B(self, B):
        self._B = _atleast_2d_or_none(B)
        self.inputs = self.B.shape[-1]
    @property
    def C(self):
        return self._C
    @C.setter
    def C(self, C):
        self._C = _atleast_2d_or_none(C)
        self.outputs = self.C.shape[0]
    @property
    def D(self):
        return self._D
    @D.setter
    def D(self, D):
        self._D = _atleast_2d_or_none(D)
    def _copy(self, system):
        self.A = system.A
        self.B = system.B
        self.C = system.C
        self.D = system.D
    def to_tf(self, **kwargs):
        return TransferFunction(*ss2tf(self._A, self._B, self._C, self._D,
                                       **kwargs), **self._dt_dict)
    def to_zpk(self, **kwargs):
        return ZerosPolesGain(*ss2zpk(self._A, self._B, self._C, self._D,
                                      **kwargs), **self._dt_dict)
    def to_ss(self):
        return copy.deepcopy(self)

class Cromossome:
    @staticmethod
    def ref_database(ref):
        Gene.ref_database(ref)
    def __init__(self, individual, day, random=False):
        super().__init__()
        self.individual = individual
        self.weekday = day
        self.genes = []
        for i in range(NUMBER_OF_GENES):
            self.genes.append(Gene(self, gene_type=(self.weekday, i), random=False))
        if random:
            self.randomize()
    def __repr__(self):
        s = []
        for g in self.genes:
            if g.data is None:
                s.append("(Vazio)")
            else:
                s.append(g.data.nome)
        return ", ".join(s)
    def __eq__(self, other):
        for g, o in zip(self.genes, other.genes):
            if g != o:
                return False
        return True
    def randomize(self):
        for i in range(NUMBER_OF_GENES):
            self.genes[i] = Gene(self, gene_type=(self.weekday, i), random=True)
    def crossover(self, children, other, tip=None):
        return self.uniform_crossover(children, other)
    def uniform_crossover(self, child, other):
        c = Cromossome(child, self.weekday)
        for i in range(NUMBER_OF_GENES):
            if self.genes[i] == other.genes[i]:
                c.genes[i] = self.genes[i].clone(c)
            else:
                if random.uniform(0, 1) < 0.5:
                    c.genes[i] = self.genes[i].clone(c)
                else:
                    c.genes[i] = other.genes[i].clone(c)
        return c
    def single_point_crossover(self, children, other, tip):
        c = Cromossome(children[0], self.weekday)
        c2 = Cromossome(children[1], self.weekday)
        for i in range(tip+1):
            c.genes[i] = self.genes[i].clone(c)
            c.genes[i].cromossome = c
            c2.genes[i] = other.genes[i].clone(c2)
            c2.genes[i].cromossome = c2
        for i in range(tip+1, NUMBER_OF_GENES):
            c.genes[i] = other.genes[i].clone(c)
            c.genes[i].cromossome = c
            c2.genes[i] = self.genes[i].clone(c2)
            c2.genes[i].cromossome = c2
        return c, c2
    def gap_size(self, gene_index):
        pre_gap = 0
        student = Gene.ref_database.student
        for k in reversed(range(gene_index)):
            if self.genes[k].isEmpty():
                pre_gap += 1
                gene_type = self.genes[k].gene_type
                if student.preferences[gene_type[1]][gene_type[0]] == '0':  
                    pre_gap -= 1
            else:
                break
        pos_gap = 0
        for k in range(gene_index + 1, NUMBER_OF_GENES):
            if self.genes[k].isEmpty():
                pos_gap += 1
                gene_type = self.genes[k].gene_type
                if student.preferences[gene_type[1]][gene_type[0]] == '0':  
                    pre_gap -= 1
            else:
                break
        if pre_gap == gene_index and pos_gap == NUMBER_OF_GENES - gene_index + 1:
            gap = 0  
        else:
            if pre_gap == gene_index:
                gap = 0  
            elif pos_gap == NUMBER_OF_GENES - (gene_index + 1):
                gap = 0  
            else:
                gap = pre_gap + 1 + pos_gap
        return gap

class PlexObject(object):
    TAG = None      
    TYPE = None     
    key = None      
    def __init__(self, server, data, initpath=None, parent=None):
        self._server = server
        self._data = data
        self._initpath = initpath or self.key
        self._parent = weakref.ref(parent) if parent is not None else None
        self._details_key = None
        if data is not None:
            self._loadData(data)
        self._details_key = self._buildDetailsKey()
        self._autoReload = False
    def __repr__(self):
        uid = self._clean(self.firstAttr('_baseurl', 'key', 'id', 'playQueueID', 'uri'))
        name = self._clean(self.firstAttr('title', 'name', 'username', 'product', 'tag', 'value'))
        return '<%s>' % ':'.join([p for p in [self.__class__.__name__, uid, name] if p])
    def __setattr__(self, attr, value):
        if attr in _DONT_OVERWRITE_SESSION_KEYS and value == []:
            value = getattr(self, attr, [])
        autoReload = self.__dict__.get('_autoReload')
        if value is not None or attr.startswith('_') or attr not in self.__dict__ or not autoReload:
            self.__dict__[attr] = value
    def _clean(self, value):
        if value:
            value = str(value).replace('/library/metadata/', '')
            value = value.replace('/children', '')
            value = value.replace('/accounts/', '')
            value = value.replace('/devices/', '')
            return value.replace(' ', '-')[:20]
    def _buildItem(self, elem, cls=None, initpath=None):
        initpath = initpath or self._initpath
        if cls is not None:
            return cls(self._server, elem, initpath, parent=self)
        etype = elem.attrib.get('streamType', elem.attrib.get('tagType', elem.attrib.get('type')))
        ehash = '%s.%s' % (elem.tag, etype) if etype else elem.tag
        ecls = utils.PLEXOBJECTS.get(ehash, utils.PLEXOBJECTS.get(elem.tag))
        if ecls is not None:
            return ecls(self._server, elem, initpath)
        raise UnknownType("Unknown library type <%s type='%s'../>" % (elem.tag, etype))
    def _buildItemOrNone(self, elem, cls=None, initpath=None):
        try:
            return self._buildItem(elem, cls, initpath)
        except UnknownType:
            return None
    def _buildDetailsKey(self, **kwargs):
        details_key = self.key
        if details_key and hasattr(self, '_INCLUDES'):
            includes = {}
            for k, v in self._INCLUDES.items():
                value = kwargs.get(k, v)
                if value not in [False, 0, '0']:
                    includes[k] = 1 if value is True else value
            if includes:
                details_key += '?' + urlencode(sorted(includes.items()))
        return details_key
    def _isChildOf(self, **kwargs):
        obj = self
        while obj and obj._parent is not None:
            obj = obj._parent()
            if obj and obj._checkAttrs(obj._data, **kwargs):
                return True
        return False
    def _manuallyLoadXML(self, xml, cls=None):
        elem = ElementTree.fromstring(xml)
        return self._buildItemOrNone(elem, cls)
    def fetchItem(self, ekey, cls=None, **kwargs):
        if ekey is None:
            raise BadRequest('ekey was not provided')
        if isinstance(ekey, int):
            ekey = '/library/metadata/%s' % ekey
        for elem in self._server.query(ekey):
            if self._checkAttrs(elem, **kwargs):
                return self._buildItem(elem, cls, ekey)
        clsname = cls.__name__ if cls else 'None'
        raise NotFound('Unable to find elem: cls=%s, attrs=%s' % (clsname, kwargs))
    def fetchItems(self, ekey, cls=None, container_start=None, container_size=None, **kwargs):
        url_kw = {}
        if container_start is not None:
            url_kw["X-Plex-Container-Start"] = container_start
        if container_size is not None:
            url_kw["X-Plex-Container-Size"] = container_size
        if ekey is None:
            raise BadRequest('ekey was not provided')
        data = self._server.query(ekey, params=url_kw)
        items = self.findItems(data, cls, ekey, **kwargs)
        librarySectionID = utils.cast(int, data.attrib.get('librarySectionID'))
        if librarySectionID:
            for item in items:
                item.librarySectionID = librarySectionID
        return items
    def findItems(self, data, cls=None, initpath=None, rtag=None, **kwargs):
        if cls and cls.TAG and 'tag' not in kwargs:
            kwargs['etag'] = cls.TAG
        if cls and cls.TYPE and 'type' not in kwargs:
            kwargs['type'] = cls.TYPE
        if rtag:
            data = next(data.iter(rtag), [])
        items = []
        for elem in data:
            if self._checkAttrs(elem, **kwargs):
                item = self._buildItemOrNone(elem, cls, initpath)
                if item is not None:
                    items.append(item)
        return items
    def firstAttr(self, *attrs):
        for attr in attrs:
            value = getattr(self, attr, None)
            if value is not None:
                return value
    def listAttrs(self, data, attr, rtag=None, **kwargs):
        results = []
        if rtag:
            data = next(data.iter(rtag), [])
        for elem in data:
            kwargs['%s__exists' % attr] = True
            if self._checkAttrs(elem, **kwargs):
                results.append(elem.attrib.get(attr))
        return results
    def reload(self, key=None, **kwargs):
        return self._reload(key=key, **kwargs)
    def _reload(self, key=None, _autoReload=False, **kwargs):
        details_key = self._buildDetailsKey(**kwargs) if kwargs else self._details_key
        key = key or details_key or self.key
        if not key:
            raise Unsupported('Cannot reload an object not built from a URL.')
        self._initpath = key
        data = self._server.query(key)
        self._autoReload = _autoReload
        self._loadData(data[0])
        self._autoReload = False
        return self
    def _checkAttrs(self, elem, **kwargs):
        attrsFound = {}
        for attr, query in kwargs.items():
            attr, op, operator = self._getAttrOperator(attr)
            values = self._getAttrValue(elem, attr)
            if op == 'exact' and not values and query in (None, 0, ''):
                return True
            attrsFound[attr] = False
            for value in values:
                value = self._castAttrValue(op, query, value)
                if operator(value, query):
                    attrsFound[attr] = True
                    break
        return all(attrsFound.values())
    def _getAttrOperator(self, attr):
        for op, operator in OPERATORS.items():
            if attr.endswith('__%s' % op):
                attr = attr.rsplit('__', 1)[0]
                return attr, op, operator
        return attr, 'exact', OPERATORS['exact']
    def _getAttrValue(self, elem, attrstr, results=None):
        parts = attrstr.split('__', 1)
        attr = parts[0]
        attrstr = parts[1] if len(parts) == 2 else None
        if attrstr:
            results = [] if results is None else results
            for child in [c for c in elem if c.tag.lower() == attr.lower()]:
                results += self._getAttrValue(child, attrstr, results)
            return [r for r in results if r is not None]
        if attr.lower() == 'etag':
            return [elem.tag]
        for _attr, value in elem.attrib.items():
            if attr.lower() == _attr.lower():
                return [value]
        return []
    def _castAttrValue(self, op, query, value):
        if op == 'exists':
            return value
        if isinstance(query, bool):
            return bool(int(value))
        if isinstance(query, int) and '.' in value:
            return float(value)
        if isinstance(query, int):
            return int(value)
        if isinstance(query, float):
            return float(value)
        return value
    def _loadData(self, data):
        raise NotImplementedError('Abstract method not implemented.')

class PlexPartialObject(PlexObject):
    _INCLUDES = {
        'checkFiles': 1,
        'includeAllConcerts': 1,
        'includeBandwidths': 1,
        'includeChapters': 1,
        'includeChildren': 1,
        'includeConcerts': 1,
        'includeExternalMedia': 1,
        'includeExtras': 1,
        'includeFields': 'thumbBlurHash,artBlurHash',
        'includeGeolocation': 1,
        'includeLoudnessRamps': 1,
        'includeMarkers': 1,
        'includeOnDeck': 1,
        'includePopularLeaves': 1,
        'includePreferences': 1,
        'includeRelated': 1,
        'includeRelatedCount': 1,
        'includeReviews': 1,
        'includeStations': 1
    }
    def __eq__(self, other):
        return other not in [None, []] and self.key == other.key
    def __hash__(self):
        return hash(repr(self))
    def __iter__(self):
        yield self
    def __getattribute__(self, attr):
        value = super(PlexPartialObject, self).__getattribute__(attr)
        if attr in _DONT_RELOAD_FOR_KEYS: return value
        if attr in _DONT_OVERWRITE_SESSION_KEYS: return value
        if attr in USER_DONT_RELOAD_FOR_KEYS: return value
        if attr.startswith('_'): return value
        if value not in (None, []): return value
        if self.isFullObject(): return value
        clsname = self.__class__.__name__
        title = self.__dict__.get('title', self.__dict__.get('name'))
        objname = "%s '%s'" % (clsname, title) if title else clsname
        log.debug("Reloading %s for attr '%s'", objname, attr)
        self._reload(_autoReload=True)
        return super(PlexPartialObject, self).__getattribute__(attr)
    def analyze(self):
        key = '/%s/analyze' % self.key.lstrip('/')
        self._server.query(key, method=self._server._session.put)
    def isFullObject(self):
        return not self.key or (self._details_key or self.key) == self._initpath
    def isPartialObject(self):
        return not self.isFullObject()
    def _edit(self, **kwargs):
        if 'id' not in kwargs:
            kwargs['id'] = self.ratingKey
        if 'type' not in kwargs:
            kwargs['type'] = utils.searchType(self.type)
        part = '/library/sections/%s/all?%s' % (self.librarySectionID,
                                                urlencode(kwargs))
        self._server.query(part, method=self._server._session.put)
    def edit(self, **kwargs):
        self._edit(**kwargs)
    def _edit_tags(self, tag, items, locked=True, remove=False):
        if not isinstance(items, list):
            items = [items]
        value = getattr(self, utils.tag_plural(tag))
        existing_tags = [t.tag for t in value if t and remove is False]
        tag_edits = utils.tag_helper(tag, existing_tags + items, locked, remove)
        self.edit(**tag_edits)
    def refresh(self):
        key = '%s/refresh' % self.key
        self._server.query(key, method=self._server._session.put)
    def section(self):
        return self._server.library.sectionByID(self.librarySectionID)
    def delete(self):
        try:
            return self._server.query(self.key, method=self._server._session.delete)
        except BadRequest:  
            log.error('Failed to delete %s. This could be because you '
                'have not allowed items to be deleted', self.key)
            raise
    def history(self, maxresults=9999999, mindate=None):
        return self._server.history(maxresults=maxresults, mindate=mindate, ratingKey=self.ratingKey)

class V1beta1NonResourceAttributes(object):
    swagger_types = {
        'path': 'str',
        'verb': 'str'
    }
    attribute_map = {
        'path': 'path',
        'verb': 'verb'
    }
    def __init__(self, path=None, verb=None):  
        self._path = None
        self._verb = None
        self.discriminator = None
        if path is not None:
            self.path = path
        if verb is not None:
            self.verb = verb
