class Vec:
    def __init__(self, labels, function):
        self.D = labels
        self.f = function
    __getitem__ = getitem
    __setitem__ = setitem
    __neg__ = neg
    __rmul__ = scalar_mul 
    def __mul__(self,other):
        if isinstance(other, Vec):
            return dot(self,other)
        else:
            return NotImplemented  
    def __truediv__(self,other):  
        return (1/other)*self
    __add__ = add
    def __radd__(self, other):
        "Hack to allow sum(...) to work with vectors"
        if other == 0:
            return self
    def __sub__(a,b):
        "Returns a vector which is the difference of a and b."
        return a+(-b)
    __eq__ = equal
    def is_almost_zero(self):
        s = 0
        for x in self.f.values():
            if isinstance(x, int) or isinstance(x, float):
                s += x*x
            elif isinstance(x, complex):
                s += x*x.conjugate()
            else: return False
        return s < 1e-20
    def __str__(v):
        "pretty-printing"
        D_list = sorted(v.D, key=repr)
        numdec = 3
        wd = dict([(k,(1+max(len(str(k)), len('{0:.{1}G}'.format(v[k], numdec))))) if isinstance(v[k], int) or isinstance(v[k], float) else (k,(1+max(len(str(k)), len(str(v[k]))))) for k in D_list])
        s1 = ''.join(['{0:>{1}}'.format(str(k),wd[k]) for k in D_list])
        s2 = ''.join(['{0:>{1}.{2}G}'.format(v[k],wd[k],numdec) if isinstance(v[k], int) or isinstance(v[k], float) else '{0:>{1}}'.format(v[k], wd[k]) for k in D_list])
        return "\n" + s1 + "\n" + '-'*sum(wd.values()) +"\n" + s2
    def __hash__(self):
        "Here we pretend Vecs are immutable so we can form sets of them"
        h = hash(frozenset(self.D))
        for k,v in sorted(self.f.items(), key = lambda x:repr(x[0])):
            if v != 0:
                h = hash((h, hash(v)))
        return h
    def __repr__(self):
        return "Vec(" + str(self.D) + "," + str(self.f) + ")"
    def copy(self):
        "Don't make a new copy of the domain D"
        return Vec(self.D, self.f.copy())

class Frequency(object):
    unit_dict = {\
            'hz':'Hz',\
            'khz':'KHz',\
            'mhz':'MHz',\
            'ghz':'GHz',\
            'thz':'THz'\
            }
    multiplier_dict = {\
            'hz':1,\
            'khz':1e3,\
            'mhz':1e6,\
            'ghz':1e9,\
            'thz':1e12\
            }
    def __init__(self, start=0, stop=0, npoints=0, unit='ghz', sweep_type='lin'):
        self._unit = unit.lower()
        self.sweep_type = sweep_type
        start = self.multiplier * start
        stop = self.multiplier * stop
        if sweep_type.lower() == 'lin':
            self.f = linspace(start, stop, npoints)
        else:
            raise ValueError('Sweep Type not recognized')
    def __str__(self):
        try:
            output =  \
                   '%i-%i %s, %i pts' % \
                   (self.f_scaled[0], self.f_scaled[-1], self.unit, self.npoints)
        except (IndexError):
            output = "[no freqs]"
        return output
    def __repr__(self):
        return self.__str__()
    def __getitem__(self, key):
        output = self.copy()
        if isinstance(key, str):
            re_numbers = re.compile('.*\d')
            re_hyphen = re.compile('\s*-\s*')
            re_letters = re.compile('[a-zA-Z]+')
            freq_unit = re.findall(re_letters, key)
            if len(freq_unit) == 0:
                freq_unit = self.unit
            else:
                freq_unit = freq_unit[0]
            key_nounit = re.sub(re_letters, '', key)
            edges = re.split(re_hyphen, key_nounit)
            edges_freq = Frequency.from_f([float(k) for k in edges],
                                        unit=freq_unit)
            if len(edges_freq) == 2:
                slicer = slice_domain(output.f, edges_freq.f)
            elif len(edges_freq) == 1:
                key = find_nearest_index(output.f, edges_freq.f[0])
                slicer = slice(key, key+1, 1)
            else:
                raise ValueError()
            try:
                output.f = npy.array(output.f[slicer]).reshape(-1)
                return output
            except(IndexError):
                raise IndexError('slicing frequency is incorrect')
        output.f = npy.array(output.f[key]).reshape(-1)
        return output
    @classmethod
    def from_f(cls, f, *args, **kwargs):
        temp_freq = cls(0, 0, 0, *args, **kwargs)
        temp_freq.f = npy.array(f) * temp_freq.multiplier
        return temp_freq
    def __eq__(self, other):
        if len(self.f) != len(other.f):
            return False
        elif len(self.f) == len(other.f) == 0:
            return True
        else:
            return (max(abs(self.f-other.f)) < ZERO)
    def __ne__(self, other):
        return (not self.__eq__(other))
    def __len__(self):
        return self.npoints
    def __mul__(self, other):
        out = self.copy()
        out.f = self.f*other
        return out
    def __rmul__(self, other):
        out = self.copy()
        out.f = self.f*other
        return out
    def __div__(self, other):
        out = self.copy()
        out.f = self.f/other
        return out
    @property
    def start(self):
        return self.f[0]
    @property
    def start_scaled(self):
        return self.f_scaled[0]
    @property
    def stop_scaled(self):
        return self.f_scaled[-1]
    @property
    def stop(self):
        return self.f[-1]
    @property
    def npoints(self):
        return len(self.f)
    @npoints.setter
    def npoints(self, n):
        self.f = linspace(self.start, self.stop, n)
    @property
    def center(self):
        return self.start + (self.stop-self.start)/2.
    @property
    def center_idx(self):
        return int(self.npoints)/2
    @property
    def center_scaled(self):
        return self.start_scaled + (self.stop_scaled-self.start_scaled)/2.
    @property
    def step(self):
        return self.span/(self.npoints-1.)
    @property
    def step_scaled(self):
        return self.span_scaled/(self.npoints-1.)
    @property
    def span(self):
        return abs(self.stop-self.start)
    @property
    def span_scaled(self):
        return abs(self.stop_scaled-self.start_scaled)
    @property
    def f(self):
        return self._f
    @f.setter
    def f(self, new_f):
        self._f = npy.array(new_f)
    @property
    def f_scaled(self):
        return self.f/self.multiplier
    @property
    def w(self):
        return 2*pi*self.f
    @property
    def df(self):
        return gradient(self.f)
    @property
    def df_scaled(self):
        return gradient(self.f_scaled)
    @property
    def dw(self):
        return gradient(self.w)
    @property
    def unit(self):
        return self.unit_dict[self._unit]
    @unit.setter
    def unit(self, unit):
        self._unit = unit.lower()
    @property
    def multiplier(self):
        return self.multiplier_dict[self._unit]
    def copy(self):
        freq = Frequency.from_f(self.f, unit='hz')
        freq.unit = self.unit
        return freq
    @property
    def t(self):
        return linspace(-.5/self.step, .5/self.step, self.npoints)
    @property
    def t_ns(self):
        return self.t*1e9
    def round_to(self, val='hz'):
        if isinstance(val, str):
            val = self.multiplier_dict[val.lower()]
        self.f = npy.round_(self.f/val)*val
    def overlap(self, f2):
        return overlap_freq(self, f2)

