class Model:
    def __init__(self, name, flux):
        assert(type(flux)==np.ndarray)
        self.flux = flux
        self.name = name
    def __str__(self):
        return self.name
    def __repr__(self):
        return self.__str__()
    def stellar_params(self):
        a = self.name[2:-4].split('_')
        MH = 0.1*float(a[0])
        if self.name[1]=='m': MH = -MH
        Teff = float(a[1])
        logg = 0.01*float(a[2])
        vmicro = 0.1*float(a[3])
        vsini = float(a[6])
        sp = StellarParams(Teff, logg, vsini, MH, vmicro)
        return sp

