            for line in f:
                arr = line.split()
                flux.append(float(arr[1]))
        return np.array(flux)
    def load(self):
        if True:
            L, names = [],[]
            grid_files = [f for f in os.listdir(self.folder) if f.endswith(".rgs")]
            for grid_fn in grid_files:
                fn = join(self.folder, grid_fn)
                model_flux = Grid.load_flux(fn)
