        return self._available_domains
    def generate_login(self, min_length=6, max_length=10, digits=True):
        chars = string.ascii_lowercase
        if digits:
            chars += string.digits
        length = random.randint(min_length, max_length)
        return ''.join(random.choice(chars) for x in range(length))
    def get_email_address(self):
        if self.login is None:
            self.login = self.generate_login()
        available_domains = self.available_domains
        if self.domain is None:
            self.domain = random.choice(available_domains)
        elif self.domain not in available_domains:
            raise ValueError('Domain not found in available domains!')
        return u'{0}{1}'.format(self.login, self.domain)
    def get_hash(self, email):
        return md5(email).hexdigest()
    def get_mailbox(self, email=None, email_hash=None):
        if email is None:
            email = self.get_email_address()
        if email_hash is None:
            email_hash = self.get_hash(email)
        url = 'http://{0}/request/mail/id/{1}/format/json/'.format(
            self.api_domain, email_hash)
        req = requests.get(url)
        return req.json()

class _Logger():
    datefmt = '%y-%m-%d %H:%M:%S'
    formatter = logging.Formatter(
        (
            '%(levelname)-5s '
            '[%(asctime)s] '
            '%(name)s %(funcName)s '
            ':%(lineno)d '
            '%(message)s'
        ),
        datefmt=datefmt,
    )
    colored_formatter = ColoredFormatter(
        (
            '%(log_color)s%(levelname)-5s%(reset)s '
            '%(yellow)s[%(asctime)s]%(reset)s%(white)s '
            '%(name)s %(funcName)s '
            '%(bold_purple)s:%(lineno)d%(reset)s '
            '%(log_color)s%(message)s%(reset)s'
        ),
        datefmt=datefmt,
        log_colors={
            'DEBUG': 'blue',
            'INFO': 'bold_cyan',
            'WARNING': 'red,',
            'ERROR': 'bg_bold_red',
            'CRITICAL': 'red,bg_white',
        }
    )
    stream = None
    def __init__(self, stream=None):
        logging.getLogger().setLevel(logging.DEBUG)
        self._loggers = logging.Logger.manager.loggerDict
        self._loggers.clear()  
    def __getattr__(self, name):
        logger_name = self.get_current_name()
        if not self._loggers.get(logger_name):
            self.set_stream()
            if settings.ROTATE_ENABLE:
                self.set_rotate()
        return getattr(self._loggers[logger_name], name)
    def set_stream(self):
        logger_name = self.get_current_name()
        _logger = logging.getLogger(logger_name)
        sh = logging.StreamHandler(self.stream)
        sh.setLevel(settings.STREAM_LEVEL)
        sh.setFormatter(self.colored_formatter
                        if settings.STREAM_COLOR
                        else self.formatter)
        _logger.addHandler(sh)
    def set_rotate(self):
        logger_name = self.get_current_name()
        fh = TimedRotatingFileHandler(
            join(settings.ROTATE_DIR, logger_name),
            when='midnight',
            backupCount=7
        )
        fh.setLevel(settings.ROTATE_LEVEL)
        fh.setFormatter(self.formatter)
        logging.getLogger(logger_name).addHandler(fh)
    def __repr__(self):
        return str(self._loggers)
    def get_current_name(self):
        frame = currentframe()
        while True:
            filepath = getfile(frame)
            if __file__ == filepath:
                frame = frame.f_back
            else:
                break
        logger_name = frame.f_globals.get('__loggername__')
        logger_name = logger_name or frame.f_globals['__name__']
        return logger_name

