class OperationCounters(object):
  def __init__(self, counter_factory, step_name, coder, output_index):
    self._counter_factory = counter_factory
    self.element_counter = counter_factory.get_counter(
        '%s-out%s-ElementCount' % (step_name, output_index), Counter.SUM)
    self.mean_byte_counter = counter_factory.get_counter(
        '%s-out%s-MeanByteCount' % (step_name, output_index), Counter.MEAN)
    self.coder_impl = coder.get_impl() if coder else None
    self.active_accumulator = None
    self._sample_counter = 0
    self._next_sample = 0
  def update_from(self, windowed_value):
    self.element_counter.update(1)
    if self._should_sample():
      self.do_sample(windowed_value)
  def _observable_callback(self, inner_coder_impl, accumulator):
    def _observable_callback_inner(value, is_encoded=False):
      if is_encoded:
        size = len(value)
        accumulator.update(size)
      else:
        accumulator.update(inner_coder_impl.estimate_size(value))
    return _observable_callback_inner
  def do_sample(self, windowed_value):
    size, observables = (
        self.coder_impl.get_estimated_size_and_observables(windowed_value))
    if not observables:
      self.mean_byte_counter.update(size)
    else:
      self.active_accumulator = SumAccumulator()
      self.active_accumulator.update(size)
      for observable, inner_coder_impl in observables:
        observable.register_observer(
            self._observable_callback(
                inner_coder_impl, self.active_accumulator))
  def update_collect(self):
    if self.active_accumulator is not None:
      self.mean_byte_counter.update(self.active_accumulator.value())
      self.active_accumulator = None
  def _compute_next_sample(self, i):
    gap = math.log(1.0 - random.random()) / math.log(1.0 - (10.0 / i))
    return i + math.floor(gap)
  def _should_sample(self):
    if self.coder_impl is None:
      return False
    self._sample_counter += 1
    if self._next_sample == 0:
      if random.randint(1, self._sample_counter) <= 10:
        if self._sample_counter > 30:
          self._next_sample = self._compute_next_sample(self._sample_counter)
        return True
      return False
    elif self._sample_counter >= self._next_sample:
      self._next_sample = self._compute_next_sample(self._sample_counter)
      return True
    return False
  def should_sample(self):
    return self._should_sample()
  def __str__(self):
    return '<%s [%s]>' % (self.__class__.__name__,
                          ', '.join([str(x) for x in self.__iter__()]))
  def __repr__(self):
    return '<%s %s at %s>' % (self.__class__.__name__,
                              [x for x in self.__iter__()], hex(id(self)))

class BaseMaze(ABC):
    def __init__(self, **kwargs):
        objects = self.make_objects()
        assert all([isinstance(obj, Object) for obj in objects])
        self.objects = namedtuple('Objects', map(lambda x: x.name, objects), defaults=objects)()
        for key, value in kwargs.items():
            setattr(self, key, value)
    @property
    @abstractmethod
    def size(self):
        r
        pass
    @abstractmethod
    def make_objects(self):
        r
        pass
    def _convert(self, x, name):
        for obj in self.objects:
            pos = np.asarray(obj.positions)
            if pos.size > 0:
                x[pos[:, 0], pos[:, 1], pos[:, 2]] = getattr(obj, name, None)
        return x
    def to_name(self):
        x = np.empty(self.size, dtype=object)
        return self._convert(x, 'name')
    def to_value(self):
        x = np.empty(self.size, dtype=int)
        return self._convert(x, 'value')
    def to_rgb(self):
        x = np.empty((*self.size, 3), dtype=np.uint8)
        return self._convert(x, 'rgb')
    def to_impassable(self):
        x = np.empty(self.size, dtype=bool)
        return self._convert(x, 'impassable')
    def __repr__(self):
        return f'{self.__class__.__name__}{self.size}'

class MicrosoftEvent(abc.Set):
    def __init__(self, iterable=()):
        self._events = {}
        for item in iterable:
            if isinstance(item, self.__class__):
                self._events[item.id] = item._events[item.id]
            elif isinstance(item, Mapping):
                self._events[item.get('id')] = item
            else:
                raise ValueError("Only %s or iterable of dict are supported" % self.__class__.__name__)
    def __iter__(self) -> Iterator['MicrosoftEvent']:
        return iter(MicrosoftEvent([vals]) for vals in self._events.values())
    def __contains__(self, microsoft_event):
        return microsoft_event.id in self._events
    def __len__(self):
        return len(self._events)
    def __bool__(self):
        return bool(self._events)
    def __getattr__(self, name):
        try:
            event, = self._events.keys()
        except ValueError:
            raise ValueError("Expected singleton: %s" % self)
        event_id = list(self._events.keys())[0]
        return self._events[event_id].get(name)
    def __repr__(self):
        return '%s%s' % (self.__class__.__name__, self.ids)
    @property
    def ids(self):
        return tuple(e.id for e in self)
    def microsoft_ids(self):
        return tuple(e.id for e in self)
    def flectra_id(self, env):
        self.flectra_ids(env)  
        return self._flectra_id
    def _meta_flectra_id(self, microsoft_guid):
        if self.singleValueExtendedProperties:
            o_id = [prop['value'] for prop in self.singleValueExtendedProperties if prop['id'] == 'String {%s} Name flectra_id' % microsoft_guid][0]
            return int(o_id)
    def flectra_ids(self, env):
        ids = tuple(e._flectra_id for e in self if e._flectra_id)
        if len(ids) == len(self):
            return ids
        found = self._load_flectra_ids_from_db(env)
        unsure = self - found
        if unsure:
            unsure._load_flectra_ids_from_metadata(env)
        return tuple(e._flectra_id for e in self)
    def _load_flectra_ids_from_metadata(self, env):
        model_env = self._get_model(env)
        microsoft_guid = env['ir.config_parameter'].sudo().get_param('microsoft_calendar.microsoft_guid', False)
        unsure_flectra_ids = tuple(e._meta_flectra_id(microsoft_guid) for e in self)
        flectra_events = model_env.browse(_id for _id in unsure_flectra_ids if _id)
        o_ids = flectra_events.exists().filtered(lambda e: not e.microsoft_id).ids
        for e in self:
            flectra_id = e._meta_flectra_id(microsoft_guid)
            if flectra_id in o_ids:
                e._events[e.id]['_flectra_id'] = flectra_id
    def _load_flectra_ids_from_db(self, env):
        model_env = self._get_model(env)
        flectra_events = model_env.with_context(active_test=False)._from_microsoft_ids(self.ids).with_env(env)
        mapping = {e.microsoft_id: e.id for e in flectra_events}
        existing_microsoft_ids = flectra_events.mapped('microsoft_id')
        for e in self:
            flectra_id = mapping.get(e.id)
            if flectra_id:
                e._events[e.id]['_flectra_id'] = flectra_id
        return self.filter(lambda e: e.id in existing_microsoft_ids)
    def owner(self, env):
        if self.singleValueExtendedProperties:
            microsoft_guid = env['ir.config_parameter'].sudo().get_param('microsoft_calendar.microsoft_guid', False)
            real_owner_id = [prop['value'] for prop in self.singleValueExtendedProperties if prop['id'] == 'String {%s} Name owner_flectra_id' % microsoft_guid][0]
            real_owner = real_owner_id and env['res.users'].browse(int(real_owner_id))
        else:
            real_owner_id = False
        if real_owner_id and real_owner.exists():
            return real_owner
        elif self.isOrganizer:
            return env.user
        elif self.organizer and self.organizer.get('emailAddress') and self.organizer.get('emailAddress').get('address'):
            return env['res.users'].search([('email', '=', self.organizer.get('emailAddress').get('address'))], limit=1)
        else:
            return env['res.users']
    def filter(self, func) -> 'MicrosoftEvent':
        return MicrosoftEvent(e for e in self if func(e))
    def is_recurrence(self):
        return self.type == 'seriesMaster'
    def is_recurrent(self):
        return bool(self.seriesMasterId or self.is_recurrence())
    def is_recurrent_not_master(self):
        return bool(self.seriesMasterId)
    def get_recurrence(self):
        if not self.recurrence:
            return {}
        pattern = self.recurrence['pattern']
        range = self.recurrence['range']
        end_type_dict = {
            'endDate': 'end_date',
            'noEnd': 'forever',
            'numbered': 'count',
        }
        type_dict = {
            'absoluteMonthly': 'monthly',
            'relativeMonthly': 'monthly',
            'absoluteYearly': 'yearly',
            'relativeYearly': 'yearly',
        }
        index_dict = {
            'first': '1',
            'second': '2',
            'third': '3',
            'fourth': '4',
            'last': '-1',
        }
        rrule_type = type_dict.get(pattern['type'], pattern['type'])
        interval = pattern['interval']
        if rrule_type == 'yearly':
            interval *= 12
        result = {
            'rrule_type': rrule_type,
            'end_type': end_type_dict.get(range['type'], False),
            'interval': interval,
            'count': range['numberOfOccurrences'],
            'day': pattern['dayOfMonth'],
            'byday': index_dict.get(pattern['index'], False),
            'until': range['endDate'],
        }
        month_by_dict = {
            'absoluteMonthly': 'date',
            'relativeMonthly': 'day',
            'absoluteYearly': 'date',
            'relativeYearly': 'day',
        }
        month_by = month_by_dict.get(pattern['type'], False)
        if month_by:
            result['month_by'] = month_by
        week_days = [x[:2] for x in pattern.get('daysOfWeek', [])]
        for week_day in ['mo', 'tu', 'we', 'th', 'fr', 'sa', 'su']:
            result[week_day] = week_day in week_days
        if week_days:
            result['weekday'] = week_days[0].upper()
        return result
    def is_cancelled(self):
        return bool(self.isCancelled or (self.__getattr__('@removed') and self.__getattr__('@removed').get('reason') == 'deleted'))
    def is_recurrence_outlier(self):
        return bool(self.originalStartTime)
    def cancelled(self):
        return self.filter(lambda e: e.is_cancelled())
    def exists(self, env) -> 'MicrosoftEvent':
        recurrences = self.filter(MicrosoftEvent.is_recurrence)
        events = self - recurrences
        recurrences.flectra_ids(env)
        events.flectra_ids(env)
        return self.filter(lambda e: e._flectra_id)
    def _get_model(self, env):
        if all(e.is_recurrence() for e in self):
            return env['calendar.recurrence']
        if all(not e.is_recurrence() for e in self):
            return env['calendar.event']
        raise TypeError("Mixing Microsoft events and Microsoft recurrences")

