class NexentaEdgeJSONProxy(object):
    def __init__(self, protocol, host, port, path, user, password, auto=False,
                 method=None):
        self.protocol = protocol.lower()
        self.host = host
        self.port = port
        self.path = path
        self.user = user
        self.password = password
        self.auto = auto
        self.method = method
    @property
    def url(self):
        return '%s://%s:%s%s' % (self.protocol,
                                 self.host, self.port, self.path)
    def __getattr__(self, name):
        if not self.method:
            method = name
        else:
            raise Exception("Wrong resource call syntax")
        return NexentaEdgeJSONProxy(
            self.protocol, self.host, self.port, self.path,
            self.user, self.password, self.auto, method)
    def __hash__(self):
        return self.url.__hash___()
    def __repr__(self):
        return 'HTTP JSON proxy: %s' % self.url
    def __call__(self, *args):
        self.path += args[0]
        data = None
        if len(args) > 1:
            data = json.dumps(args[1])
        auth = ('%s:%s' % (self.user, self.password)).encode('base64')[:-1]
        headers = {
            'Content-Type': 'application/json',
            'Authorization': 'Basic %s' % auth
        }
        LOG.debug(__('Sending JSON data: %s') % self.url)
        try:
            request = urllib2.Request(self.url, data, headers)
            if self.method == 'get':
                request.get_method = lambda: 'GET'
            elif self.method == 'post':
                request.get_method = lambda: 'POST'
            elif self.method == 'put':
                request.get_method = lambda: 'PUT'
            elif self.method == 'delete':
                request.get_method = lambda: 'DELETE'
            response_obj = urllib2.urlopen(request)
            if response_obj.info().status == 'EOF in headers':
                if not self.auto or self.protocol != 'http':
                    LOG.error(__('No headers in server response'))
                    raise NexentaJSONException(__('Bad response from server'))
                LOG.info(
                    __('Auto switching to HTTPS connection to %s') % self.url)
                self.protocol = 'https'
                request = urllib2.Request(self.url, data, headers)
                if self.method == 'get':
                    request.get_method = lambda: 'GET'
                elif self.method == 'post':
                    request.get_method = lambda: 'POST'
                elif self.method == 'put':
                    request.get_method = lambda: 'PUT'
                elif self.method == 'delete':
                    request.get_method = lambda: 'DELETE'
                response_obj = urllib2.urlopen(request)
            response_data = response_obj.read()
            rsp = json.loads(response_data)
        except urllib2.HTTPError as e:
            response_data = e.read()
            rsp = json.loads(response_data)
        except urllib2.URLError as e:
            rsp = {'code': str(e.reason), 'message': str(e)}
        except Exception as e:
            rsp = {'code': 'UNKNOWN_ERROR',
                   "message": __('Error: %s') % str(e)}
        LOG.debug(__('Got response: %s') % rsp)
        if 'code' in rsp:
            raise NexentaJSONException(rsp['message'])
        return rsp['response']

class L2Device:
	def __init__(self, name, ports):
		self.name = name
		self.mac = MAC.random()
		self.ports = [Port(partial(self.recv_frame, port_number)) for port_number in range(ports)]
		log.debug('created %s with %s', self.name, self.mac)
	def __repr__(self):
		return f'<{self.name} mac={self.mac} ports={len(self.ports)}>'
	def send_frame(self, port, frame):
		self.ports[port].send_frame(frame)
	def flood_frame(self, frame, except_port=None):
		for idx, other_port in enumerate(self.ports):
			if except_port is not None and idx == except_port:
				continue
			if not other_port.connected:
				continue
			other_port.send_frame(frame)
	def recv_frame(self, port, frame):
		if frame.dest != self.mac and frame.dest != MAC.broadcast():
			log.warning('%s received frame with wrong mac: %s', self.name, frame.dest)
			return
		self.handle_frame(port, frame)
	def handle_frame(self, port, frame):
		pass

