class StatisticsAggregator(StatisticsCollector):
    def __init__(self):
        super(StatisticsAggregator, self).__init__()
        self.aggregators = dict()
    def add_aggregator(self, key, formatting):
        self.formatting[key] = formatting
        self.aggregators[key] = -1
    def __getitem__(self, key):
        return self.aggregators[key]
    def __setitem__(self, key, value):
        self.aggregators[key] = value
    def __delitem__(self, key):
        del self.aggregators[key]
    def __len__(self):
        return self.aggregators.__len__()
    def __eq__(self, other):
        if isinstance(other, self.__class__):
            return self.statistics == other.statistics and self.formatting == other.formatting and self.aggregators == other.aggregators
        else:
            return False
    def __iter__(self):
        return self.aggregators.__iter__()
    def initialize_csv_file(self, log_dir, filename):
        header_str = ''
        for key in self.aggregators.keys():
            header_str += key + ","
        header_str = header_str[:-1] + '\n'
        self.csv_file = open(log_dir + filename, 'w', 1)
        self.csv_file.write(header_str)
        return self.csv_file
    def export_to_csv(self, csv_file=None):
        if csv_file is None:
            csv_file = self.csv_file
        if csv_file is None:
            return
        values_str = ''
        for key, value in self.aggregators.items():
            format_str = self.formatting.get(key, '{}')
            values_str += format_str.format(value) + ","
        values_str = values_str[:-1] + '\n'
        csv_file.write(values_str)
    def export_to_checkpoint(self):
        chkpt = {}
        for key, value in self.aggregators.items():
            format_str = self.formatting.get(key, '{}')
            chkpt[key] = format_str.format(value)
        return chkpt        
    def export_to_string(self, additional_tag=''):
        stat_str = ''
        for key, value in self.aggregators.items():
            stat_str += key + ' '
            format_str = self.formatting.get(key, '{}')
            stat_str += format_str.format(value) + "; "
        stat_str = stat_str[:-2] + " " + additional_tag
        return stat_str
    def export_to_tensorboard(self, tb_writer = None):
        episode = self.aggregators['episode']
        if tb_writer is None:
            tb_writer = self.tb_writer
        if tb_writer is None:
            return
        for key, value in self.aggregators.items():
            if key == 'episode':
                continue
            tb_writer.add_scalar(key, value, episode)

class Book(db.Model):
    __tablename__ = 'books'
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(80), nullable=False)
    price = db.Column(db.Float, nullable=False)
    isbn = db.Column(db.Integer)
    def json(self):
        return {'name': self.name, 'price': self.price, 'isbn': self.isbn}
    def add_book(_name, _price, _isbn):
        new_book = Book(name=_name, price=_price, isbn=_isbn)
        db.session.add(new_book)
        db.session.commit()
    def get_all_books():
        return [Book.json(book) for book in Book.query.all()]
    def get_book(_isbn):
        return Book.json(Book.query.filter_by(isbn=_isbn).first())
    def delete_book(_isbn):
        is_successful = Book.query.filter_by(isbn=_isbn).delete()
        db.session.commit()
        return bool(is_successful)
    def update_book_price(_isbn, _price):
        book_to_update = Book.query.filter_by(isbn=_isbn).first()
        book_to_update.price = _price
        db.session.commit()
    def update_book_name(_isbn, _name):
        book_to_update = Book.query.filter_by(isbn=_isbn).first()
        book_to_update.name = _name
        db.session.commit()
    def replace_book(_isbn, _name, _price):
        book_to_replace = Book.query.filter_by(isbn=_isbn).first()
        book_to_replace.price = _price
        book_to_replace.name = _name
        db.session.commit()
    def __repr__(self):
        book_object = {
            'name': self.name,
            'price': self.price,
            'isbn': self.isbn
        }
        return json.dumps(book_object)

class Posterior(LossFunction):
    def __init__(self, likelihood, prior):
        self.loglikelihood = likelihood
        self.logprior = prior
    def __repr__(self):
        return "<Posterior(likelihood={}, prior={})>".format(self.loglikelihood,
                self.prior)
    def evaluate(self, params):
        return self.loglikelihood(params) + self.logprior(params)
    def gradient(self, params):
        return self.loglikelihood.gradient(params) + self.logprior.gradient(params)

class Protocol:
    logger = logging.getLogger("p2p.protocol.Protocol")
    name: str = None
    version: int = None
    cmd_length: int = None
    _commands: List[Type[Command]] = []
    def __init__(self, peer: 'BasePeer', cmd_id_offset: int) -> None:
        self.peer = peer
        self.cmd_id_offset = cmd_id_offset
        self.commands = [cmd_class(cmd_id_offset) for cmd_class in self._commands]
        self.cmd_by_id = dict((cmd.cmd_id, cmd) for cmd in self.commands)
    def send(self, header: bytes, body: bytes) -> None:
        self.peer.send(header, body)
    def __repr__(self) -> str:
        return "(%s, %d)" % (self.name, self.version)

