    self._s.authed = False
    self._s.started_auth_attempt = False
    self._s.initialized = False
    self._s.pre_init_queue = []
    self._s.mm_queue = collections.deque()
    self._s.roomids = {}
    self._send_to_server('/autojoin')
  def on_stop(self):
    for roomid in self._s.battles:
      self._battle_finalized(roomid)
    del self._s.battles
    self._s.bq.stop()
    self._s.bq.join()
    del self._s.bq
    self._s.cxn.stop()
    self._s.cxn.join()
    del self._s.cxn
  def receive(self, msg):
    if msg.opcode == 'command-from-server':
      for roomid, chunk in _parse_command(msg.data):
        self.debug('> %s%s', roomid, chunk)
        self._route_to_room(roomid, chunk)
    elif msg.opcode == 'ps-message':
      self._handle_ps_message(msg.data)
    elif msg.opcode == 'battle-ended':
      roomid = msg.data['roomid']
      result = msg.data['result']
      room = self._s.battles[roomid]
      msg = dict(
        username = self.username,
        roomid = roomid,
        id = room.extra['id'],
        result = result,
      )
      if self.is_root:
        self.queue.put(('battle-ended', msg))
      else:
        self._parent.send('battle-ended', msg)
    elif msg.opcode == 'send-to-room':
      payload, roomid = msg.data
      self._send_to_server(payload, roomid = roomid)
    elif msg.opcode == 'check-init':
      self._check_init()
    elif msg.opcode == 'challenge':
      self._bq_send(msg)
    elif msg.opcode == 'matchmaking':
      assert not self._conf.accept_challenges, 'Cannot accept challenges while in MM'
      self._s.mm_queue.append(msg.data)
      self._bq_send('matchmaking', msg.data)
    elif msg.opcode == 'forced-socket-close':
      msg = 'Forced socket close from websocket'
      self.log(msg, loglevel = logging.ERROR)
      if self.is_root:
        self.queue.put(('error', msg))
      else:
        self._parent.send('error', msg)
      self.stop()
    else:
      self.die('got unexpected message: %s', msg)
  @property
  def conf(self):
    return self._conf
  @property
  def username(self):
    return self._username
  @property
  def queue(self):
    assert self.is_root
    return self._battle_results_queue
  def _battle_finalized(self, roomid):
    'Called when a battle is finalized (fully finished).'
    self.log('closing battle [%s]', roomid)
    self._s.battles[roomid].stop()
    self._s.battles[roomid].join()
    del self._s.battles[roomid]
    self.log('closed battle [%s]', roomid)
    self._bq_send('battle-ended', None)
  def _battle_accepted(self, roomid):
    'Called when a battle has started between two players.'
    self._bq_send('battle-started', None)
    if self._s.mm_queue:
      data = self._s.mm_queue.popleft()
    else:
      data = {
        'player_ctor': self._player_ctor,
        'id': roomid,
      }
    room = self.spawn(BattleRoom,
      roomid = roomid,
      player_ctor = data['player_ctor'],
      conf = self._conf,
      extra = data,
    )
    self._s.battles[roomid] = room
    return room
  def _ready(self):
    return self._s.authed
  def _bq_send(self, *args):
    if self._s.initialized:
      self._s.bq.send(*args)
    else:
      self._s.pre_init_queue.append(args)
  def _check_init(self):
    if not self._s.initialized:
      self._s.initialized = True
      for args in self._s.pre_init_queue:
        self._bq_send(*args)
      self._s.pre_init_queue[:] = []
  def _route_to_room(self, roomid, chunk):
    if not roomid:
      handler = self
    elif roomid in self._s.battles:
      handler = self._s.battles[roomid]
    elif roomid.startswith('battle-') and chunk == '|init|battle':
      handler = self._battle_accepted(roomid)
    else:
      self.warn('recv msg [%s] for [%s] but room not initialized', chunk, roomid)
      handler = None
    if handler:
      handler.send('ps-message', chunk)
    if chunk == '|deinit':
      self._battle_finalized(roomid)
  def _handle_ps_message(self, message):
    if message.startswith('|nametaken'):
      self.die('name [%s] already exists, exitting', self._username)
    elif (message.startswith('|popup|Error: You need to make a move in')
      or message.startswith('|popup|Error: You need to wait until after making a move')):
      self._bq_send('search-cancelled-by-server', message)
    elif message.startswith('|updatechallenges'):
      self._bq_send('update-challenges', json.loads(message.split('|', 2)[2]))
    elif message.startswith('|challstr') or message.startswith('|updateuser'):
      self._handle_auth_message(message)
    elif message.startswith('|pm'):
      self.info(message)
  def _handle_auth_message(self, message):
    if message.startswith('|challstr'):
      if self._s.authed:
        self.die('received message [%s] but already authed', message)
      challstr = '|'.join(message.split('|')[2:])
      username = self._username
      assertion = _fetch_assertion_string(username, challstr)
      self._send_to_server('/trn %s,0,%s' % (username, assertion))
      self._s.started_auth_attempt = True
    elif message.startswith('|updateuser'):
      username = message.split('|')[2]
      username = username[1:]
      if username.lower().startswith('guest '):
        if self._s.started_auth_attempt:
          self.die('attempted auth but received message [%s]', message)
        else:
          self._s.authed = False
      else:
        if not self._s.started_auth_attempt:
          self.die('did not attempt auth but was assigned username [%s]', username)
        elif username != self._username:
          self.die('auth succeeded but users do not match [%s, %s]', username, self._username)
        else:
          self._s.authed = True
          self.send('check-init', None)
  def _send_to_server(self, payload, roomid = ''):
    payload = '%s|%s' % (roomid, payload)
    self.debug('< %s', payload)
    self._s.cxn.send('send', payload)
  def __repr__(self):
    return 'Client(%s)' % self._username

class BaseCollection(Sequence, NotebookPlottingMixin):
    def __len__(self):
        raise NotImplementedError
    def __iter__(self):  
        raise NotImplementedError
    def __getitem__(self, index):
        raise NotImplementedError
    def __eq__(self, other):
        return all(feat == feat_other for feat, feat_other in zip(self, other))
    @property
    def crs(self):
        raise NotImplementedError
    @property
    def attribute_names(self):
        return list(self.schema['properties'].keys())
    @property
    def schema(self):
        raise NotImplementedError
    @property
    def is_empty(self):
        return all(feature.is_empty for feature in self)
    @property
    def convex_hull(self):  
        try:
            crs = self.crs
            shapes = [feature.geometry.get_shape(crs) for feature in self]
            if not all([sh.is_valid for sh in shapes]):
                warnings.warn(
                    "Some invalid shapes found, discarding them."
                )
        except IndexError:
            crs = DEFAULT_CRS
            shapes = []
        return GeoVector(
            cascaded_union([sh for sh in shapes if sh.is_valid]).convex_hull,
            crs=crs
        )
    @property
    def envelope(self):  
        try:
            crs = self.crs
            envelopes = [feature.geometry.envelope.get_shape(crs) for feature in self]
            if not all([sh.is_valid for sh in envelopes]):
                warnings.warn(
                    "Some invalid shapes found, discarding them."
                )
        except IndexError:
            crs = DEFAULT_CRS
            envelopes = []
        return GeoVector(
            cascaded_union([sh for sh in envelopes if sh.is_valid]).envelope,
            crs=crs
        )
    @property
    def __geo_interface__(self):
        return self.to_record(WGS84_CRS)
    def to_record(self, crs):
        return {
            'type': 'FeatureCollection',
            'features': [feature.to_record(crs) for feature in self],
        }
    def reproject(self, new_crs):
        return FeatureCollection([feature.reproject(new_crs) for feature in self])
    def filter(self, intersects):
        try:
            crs = self.crs
            vector = intersects.geometry if isinstance(intersects, GeoFeature) else intersects
            prepared_shape = prep(vector.get_shape(crs))
            hits = []
            for feature in self:
                target_shape = feature.geometry.get_shape(crs)
                if prepared_shape.overlaps(target_shape) or prepared_shape.intersects(target_shape):
                    hits.append(feature)
        except IndexError:
            hits = []
        return FeatureCollection(hits)
    def map(self, map_function):
        return FeatureCollection(map_function(x) for x in self)
    def rasterize(self, dest_resolution, polygonize_width=0, crs=WEB_MERCATOR_CRS, fill_value=None,
                  nodata_value=None, bounds=None, **polygonize_kwargs):
        if not isinstance(polygonize_width, int):
            raise TypeError("The width in pixels must be an integer")
        if polygonize_width == 1:
            polygonize_kwargs.update(cap_style_point=CAP_STYLE.square)
        width = polygonize_width * dest_resolution
        polygonized = [feature.polygonize(width, **polygonize_kwargs) for feature in self]
        shapes = [feature.geometry.get_shape(crs) for feature in polygonized
                  if not feature.is_empty]
        if bounds is None:
            bounds = self.convex_hull.get_shape(crs)
        if bounds.area == 0.0:
            raise ValueError("Specify non-empty ROI")
        elif isinstance(bounds, GeoVector):
            bounds = bounds.get_shape(crs)
        return rasterize(shapes, crs, bounds, dest_resolution, fill_value, nodata_value)
    def plot(self, mp=None, max_plot_rows=200, **plot_kwargs):
        if len(self) > max_plot_rows:
            warnings.warn(
                "Plotting only first {num_rows} rows to avoid browser freeze, "
                "please use .filter to narrow your query."
                .format(num_rows=max_plot_rows)
            )
            subset = self[:max_plot_rows]
            return subset.plot(mp, **plot_kwargs)
        else:
            return super().plot(mp, **plot_kwargs)
    def _adapt_feature_before_write(self, feature):
        return feature
    def save(self, filename, driver=None):
        if driver is None:
            driver = DRIVERS.get(os.path.splitext(filename)[-1])
        if driver == "GeoJSON":
            with contextlib.suppress(FileNotFoundError):
                os.remove(filename)
            crs = WGS84_CRS
        else:
            crs = self.crs
        with fiona.open(filename, 'w', driver=driver, schema=self.schema, crs=crs) as sink:
            for feature in self:
                new_feature = self._adapt_feature_before_write(feature)
                sink.write(new_feature.to_record(crs))

class FileCollection(BaseCollection):
    def __init__(self, filename, crs, schema, length):
        super().__init__()
        self._filename = filename
        self._crs = crs
        self._schema = schema
        self._length = length
    def __eq__(self, other):
        return (
            all(feat == feat_other for feat, feat_other in zip(self, other))
            and len(self) == len(other)
            and self.crs == other.crs
            and self.attribute_names == self.attribute_names
        )
    @classmethod
    def open(cls, filename):
        with fiona.open(filename, 'r') as source:
            crs = CRS(source.crs)
            schema = source.schema
            length = len(source)
        return cls(filename, crs, schema, length)
    @property
    def crs(self):
        return self._crs
    @property
    def schema(self):
        return self._schema
    def __len__(self):
        return self._length
    def __iter__(self):
        with fiona.open(self._filename, 'r') as source:
            for record in source:
                yield GeoFeature.from_record(record, source.crs, source.schema)
    def __getitem__(self, index):
        if isinstance(index, int):
            index = index % len(self)
            return list(islice(self, index, index + 1))[0]
        else:
            start, stop, step = index.start, index.stop, index.step
            start = start % len(self) if start is not None else None
            stop = stop % len(self) if stop is not None else None
            try:
                results = list(islice(self, start, stop, step))
            except ValueError:
                results = list(self)[index]
            return FeatureCollection(results)

