class Connection:
    _source_traceback = None
    _transport = None
    def __init__(self, connector, key, protocol, loop):
        self._key = key
        self._connector = connector
        self._loop = loop
        self._protocol = protocol
        self._callbacks = []
        if loop.get_debug():
            self._source_traceback = traceback.extract_stack(sys._getframe(1))
    def __repr__(self):
        return 'Connection<{}>'.format(self._key)
    def __del__(self, _warnings=warnings):
        if self._protocol is not None:
            _warnings.warn('Unclosed connection {!r}'.format(self),
                           ResourceWarning)
            if self._loop.is_closed():
                return
            self._connector._release(
                self._key, self._protocol, should_close=True)
            context = {'client_connection': self,
                       'message': 'Unclosed connection'}
            if self._source_traceback is not None:
                context['source_traceback'] = self._source_traceback
            self._loop.call_exception_handler(context)
    @property
    def loop(self):
        return self._loop
    @property
    def transport(self):
        return self._protocol.transport
    @property
    def protocol(self):
        return self._protocol
    @property
    def writer(self):
        return self._protocol.writer
    def add_callback(self, callback):
        if callback is not None:
            self._callbacks.append(callback)
    def _notify_release(self):
        callbacks, self._callbacks = self._callbacks[:], []
        for cb in callbacks:
            try:
                cb()
            except:
                pass
    def close(self):
        self._notify_release()
        if self._protocol is not None:
            self._connector._release(
                self._key, self._protocol, should_close=True)
            self._protocol = None
    def release(self):
        self._notify_release()
        if self._protocol is not None:
            self._connector._release(
                self._key, self._protocol,
                should_close=self._protocol.should_close)
            self._protocol = None
    def detach(self):
        self._notify_release()
        if self._protocol is not None:
            self._connector._release_acquired(self._protocol)
        self._protocol = None
    @property
    def closed(self):
        return self._protocol is None or not self._protocol.is_connected()

class User(UserMixin, MediaObject):
    username = db.Column(db.String(64), index=True, unique=True)
    email = db.Column(db.String(120), index=True, unique=True)
    password = db.Column(db.String(128))
    def __init__(self, username, email, password, name=None):
        self.username = username
        self.email = email
        self.password = password
        super().__init__(name=name)
    def __repr__(self):
        return '<User {}>'.format(self.username)
    def _to_dict(self):
        return {
            'id': self.id,
            'uuid': self.uuid,
            'name': self.name,
            'username': self.username,
            'email': self.email,
            'archived': self.archived
        }
    def dict(self):
        if self.archived:
            return self._get_archived()
        else:
            return self._to_dict()
    @staticmethod
    def query_users(params):
        q = User.query.filter()
        if params['username'] is not None:
            q = q.filter(User.username == params['username'])
        elif params['name'] is not None:
            q = q.filter(User.name == params['name'])
        elif params['email'] is not None:
            q = q.filter(User.email == params['email'])
        return [user for user in q]
    @staticmethod
    def get_user(id=None, uuid=None, username=None, email=None):
        if id is not None:
            user = User.query.filter(User.id == id).first()
        elif uuid is not None:
            user = User.query.filter(User.uuid == uuid).first()
        elif username is not None:
            user = User.query.filter(User.username == username).first()
        elif email is not None:
            user = User.query.filter(User.email == email).first()
        else:
            user = None
        return user
    @staticmethod
    def create(name, username, email, password1, password2):
        if password1 != password2:
            msg = 'passwords do not match.'
            raise ValueError(msg)
        if User.query.filter(User.username == username).count():
            raise ValueError('That username is already taken!')
        if User.query.filter(User.email == email).count():
            raise ValueError('An account with that email already exists!')
        user = User(
            name=name,
            username=username,
            email=email,
            password=generate_password_hash(password1)
        )
        db.session.add(user)
        db.session.commit()
        return user.dict()
    def update(self, name=None, username=None, email=None, password1=None, password2=None, archived=None):
        self.name = name or self.name
        self.username = username or self.username
        self.email = email or self.email
        if password1 and password1 == password2:
            self.password = generate_password_hash(password1)
        self.archived = archived if archived is not None else self.archived
        db.session.commit()
        return self.dict()
    def get_followers(self):
        return [f.originating_user.dict() for f in self.followers]
    def get_following(self):
        return [f.target_user.dict() for f in self.following]
    def is_following(self, target_user_id):
        relationship = Follow.get(self.uuid, target_user_id)
        return True if relationship else False
    def belongs_to_group(self, group_id):
        relationship = GroupMembership.query.filter(GroupMembership.member_id == self.id, GroupMembership.group_id == group_id)
        return True if relationship.one() else False

class Follow(Base):
    originating_id = db.Column(db.Integer, db.ForeignKey('user.id'), index=True)
    target_id = db.Column(db.Integer, db.ForeignKey('user.id'), index=True)
    label = db.Column(db.String)
    def __repr__(self):
        return '{} {} {}'.format(self.originating_id, self.label, self.target_id)
    @staticmethod
    def get(ou_id, tu_id):
        relatiohship = Follow.query.filter(Follow.originating_id == ou_id, Follow.target_id == tu_id).first()
        if relatiohship:
            return relatiohship
        else:
            return None
    @staticmethod
    def follow_user(ou, tu, label='following'):
        originating_user = User.query.filter(
                User.uuid == ou,
                User.archived == False
            ).first()
        target_user = User.query.filter(
                User.uuid == tu,
                User.archived == False
            ).first()
        if originating_user and originating_user.valid() and target_user and target_user.valid() and not originating_user.is_following(target_user.uuid):
            relationship = Follow()
            relationship.originating_id = ou
            relationship.target_id = tu
            relationship.label = label
            db.session.add(relationship)
            db.session.commit()
            return relationship.__repr__()
    @staticmethod
    def unfollow_user(ou, tu):
        originating_user = User.query.filter(
                User.uuid == ou,
                User.archived == False
            ).first()
        target_user = User.query.filter(
                User.uuid == tu,
                User.archived == False
            ).first()
        if originating_user and originating_user.valid() and target_user and target_user.valid() and originating_user.is_following(target_user.uuid):
            relationship = Follow().query\
                                .filter(Follow.originating_id == originating_user.uuid)\
                                .filter(Follow.target_id == target_user.uuid).first()
        else:
            relationship = None
        if relationship:
            db.session.delete(relationship)
            db.session.commit()
            return '{} successfully unfollowed {}'.format(ou, tu)
        else:
            return None

