        return f'{self.__class__.__name__}({self.conjunction_of_disjunction_of_linear_deciders})'

class BoundLoggerBase:
    _logger: WrappedLogger
    def __init__(
        self,
        logger: WrappedLogger,
        processors: Iterable[Processor],
        context: Context,
    ):
        self._logger = logger
        self._processors = processors
        self._context = context
    def __repr__(self) -> str:
        return "<{}(context={!r}, processors={!r})>".format(
            self.__class__.__name__, self._context, self._processors
        )
    def __eq__(self, other: object) -> bool:
        try:
            return self._context == other._context  
        except AttributeError:
            return False
    def __ne__(self, other: object) -> bool:
        return not self.__eq__(other)
    def bind(self, **new_values: Any) -> BoundLoggerBase:
        return self.__class__(
            self._logger,
            self._processors,
            self._context.__class__(self._context, **new_values),
        )
    def unbind(self, *keys: str) -> BoundLoggerBase:
        bl = self.bind()
        for key in keys:
            del bl._context[key]
        return bl
    def try_unbind(self, *keys: str) -> BoundLoggerBase:
        bl = self.bind()
        for key in keys:
            bl._context.pop(key, None)
        return bl
    def new(self, **new_values: Any) -> BoundLoggerBase:
        self._context.clear()
        return self.bind(**new_values)
    def _process_event(
        self, method_name: str, event: str | None, event_kw: dict[str, Any]
    ) -> tuple[Sequence[Any], Mapping[str, Any]]:
        event_dict: Any = self._context.copy()
        event_dict.update(**event_kw)
        if event is not None:
            event_dict["event"] = event
        for proc in self._processors:
            event_dict = proc(self._logger, method_name, event_dict)
        if isinstance(event_dict, (str, bytes, bytearray)):
            return (event_dict,), {}
        if isinstance(event_dict, tuple):
            return event_dict  
        if isinstance(event_dict, dict):
            return (), event_dict
        msg = "Last processor didn't return an appropriate value.  Valid return values are a dict, a tuple of (args, kwargs), bytes, or a str."
        raise ValueError(msg)
    def _proxy_to_logger(
        self, method_name: str, event: str | None = None, **event_kw: Any
    ) -> Any:
        try:
            args, kw = self._process_event(method_name, event, event_kw)
            return getattr(self._logger, method_name)(*args, **kw)
        except DropEvent:
            return None

class Point( object ) : 
  "Point class to save a point and define some basic"
  "equality functions"
  eps = 0.000000001
  def __init__( self, x, y ) : 
    self.x = float(x)
    self.y = float(y)
  def __repr__( s ) : return s.__str__()
  def __str__( s ) : 
    xx = round( s.x, 2 )
    yy = round( s.y, 2 ) 
    return "(%4.2f, %4.2f)"%(xx,yy)
  def __eq__( s, o ) :
    return Point.y_sorter( s, o ) == 0
  def __lt__( s, o ) :
    return Point.y_sorter( s, o ) == -1
  def __gt__( s, o ) : 
    return Point.y_sorter( s, o ) == 1 
  def __ge__( s, o ) :
    return Point.y_sorter( s, o ) >= 0
  def __le__( s, o ) : 
    return Point.y_sorter( s, o ) <= 0
  def __sub__( s, o ) : 
    return Point( s.x - o.x, s.y - o.y )
  def __add__( s, o ) : 
    return Point( s.x + o.x, s.y + o.y )
  def scale( s, m ) :
    return Point( s.x * m, s.y * m )
  def perp( s ) :
    return Point( -s.y, s.x )
  def dot( s, o ) :
    return ( s.x * o.x ) + (  s.y * o.y )
  @staticmethod
  def cross( s, o ) : 
    return (s.x * o.y) - ( o.x * s.y )
  @staticmethod
  def eq( a, b ) : 
    return a == b
  @staticmethod 
  def x_eq( a, b ) : 
    return abs( a.x - b.x ) < Point.eps 
  @staticmethod 
  def y_eq( a, b ) : 
    return abs( a.y - b.y ) < Point.eps 
  @staticmethod
  def x_sorter( a, b ) :
    if Point.x_eq( a, b): 
      return 0
    if ( a.x < b.x )                : 
      return -1
    return  1
  @staticmethod
  def y_sorter( a, b ) :
    if Point.y_eq(a, b ) : 
      return Point.x_sorter(a,b) 
    if ( a.y < b.y ) :              
      return -1 
    return  1

class BaseQuestionAnswerer(ABC):
    def __init__(self, **kwargs):
        if not kwargs.get("app_path") and not kwargs.get("app_namespace"):
            msg = f"At least one of 'app_path' or 'app_namespace' must be inputted as arguments " \
                  f"while creating an instance of {self.__class__.__name__} in order to " \
                  f"distinctly identify the Knowledge Base indices being created. Using the " \
                  f"default 'app_path' as the current working directory path: '{os.getcwd()}'."
            logger.warning(msg)
        app_path = kwargs.get("app_path") or os.getcwd()  
        self.app_path = os.path.abspath(app_path)
        self.app_namespace = kwargs.get("app_namespace") or get_app_namespace(self.app_path)
        self.resource_loader = (
            kwargs.get("resource_loader") or ResourceLoader.create_resource_loader(self.app_path)
        )
        self._qa_config = (
            kwargs.get("config")
            or get_classifier_config("question_answering", app_path=self.app_path)
        )
    def __repr__(self):
        return f"<{self.__class__.__name__} query_type: {self.query_type} " \
               f"app_path: {self.app_path} app_namespace: {self.app_namespace}>"
    @property
    def model_type(self) -> str:
        return self._qa_config.get("model_type")
    @property
    def query_type(self) -> str:
        _query_type = self._qa_config.get("model_settings", {}).get("query_type")
        if _query_type in ALL_QUERY_TYPES:
            return _query_type
        else:
            return DEFAULT_QUERY_TYPE
    @property
    def model_settings(self) -> dict:
        return self._qa_config.get("model_settings", {})
    @abstractmethod
    def _get(self, *args, **kwargs):
        raise NotImplementedError
    @abstractmethod
    def _build_search(self, *args, **kwargs):
        raise NotImplementedError
    @abstractmethod
    def _load_kb(self, *args, **kwargs):
        raise NotImplementedError
    @staticmethod
    def _resolve_deprecated_index_name(index_name, index):
        if index:
            msg = "Input the index name to a question answerer method by using the argument name " \
                  "'index_name' instead of 'index'."
            warnings.warn(msg, DeprecationWarning)
        index_name = index_name or index
        if not index_name:
            msg = "Missing one required argument: 'index_name'"
            raise TypeError(msg)
        return index_name
    def get(self, index_name=None, size=10, query_type=None, app_namespace=None, **kwargs):
        index_name = self._resolve_deprecated_index_name(index_name, kwargs.pop("index", None))
        return self._get(index=index_name, size=size, query_type=query_type,
                         app_namespace=app_namespace, **kwargs)
    def build_search(self, index_name=None, ranking_config=None, app_namespace=None, **kwargs):
        index_name = self._resolve_deprecated_index_name(index_name, kwargs.pop("index", None))
        return self._build_search(index=index_name, ranking_config=ranking_config,
                                  app_namespace=app_namespace, **kwargs)
    def load_kb(self, index_name, data_file, **kwargs):
        if (
            ("config" in kwargs and kwargs["config"])
            or ("app_path" in kwargs and kwargs["app_path"])
        ):
            msg = "Passing 'config' or 'app_path' to '.load_kb()' method is no longer " \
                  "supported. Create a Question Answerer instance with the required " \
                  "configurations and/or app path before calling '.load_kb()'."
            raise ValueError(msg)
        self._load_kb(index_name, data_file, **kwargs)

class LimitedSizeDict(OrderedDict):
    def __init__(self, *args, **kwds):
        if "size_limit" not in kwds:
            raise ValueError("'size_limit' must be passed as a keyword "
                             "argument")
        self.size_limit = kwds.pop("size_limit")
        if len(args) > 1:
            raise TypeError('expected at most 1 arguments, got %d' % len(args))
        if len(args) == 1 and len(args[0]) + len(kwds) > self.size_limit:
            raise ValueError("Tried to initialize LimitedSizedDict with more "
                             "value than permitted with 'limit_size'")
        super(LimitedSizeDict, self).__init__(*args, **kwds)
    def __setitem__(self, key, value, dict_setitem=OrderedDict.__setitem__):
        dict_setitem(self, key, value)
        self._check_size_limit()
    def _check_size_limit(self):
        if self.size_limit is not None:
            while len(self) > self.size_limit:
                self.popitem(last=False)
    def __eq__(self, other):
        if self.size_limit != other.size_limit:
            return False
        return super(LimitedSizeDict, self).__eq__(other)

class RejectResult():
    def __init__(self, code, reason=b''):
        self.code = code
        self.reason = reason
    def match(self, other):
        if self.code != other.code:
            return False
        return other.reason.startswith(self.reason)
    def __repr__(self):
        return '%i:%s' % (self.code,self.reason or '*')

class HTTPResponse(object):
    def __init__(self, request, code, headers=None, buffer=None,
                 effective_url=None, error=None, request_time=None,
                 time_info=None, reason=None, start_time=None,
                 primary_ip=None, speed_download=None, speed_upload=None):
        if isinstance(request, _RequestProxy):
            self.request = request.request
        else:
            self.request = request
        self.code = code
        self.reason = reason or httputil.responses.get(code, "Unknown")
        if headers is not None:
            self.headers = headers
        else:
            self.headers = httputil.HTTPHeaders()
        self.buffer = buffer
        self._body = None
        if effective_url is None:
            self.effective_url = request.url
        else:
            self.effective_url = effective_url
        self._error_is_response_code = False
        if error is None:
            if self.code < 200 or self.code >= 300:
                self._error_is_response_code = True
                self.error = HTTPException(self.code, message=self.reason,
                                       response=self)
            else:
                self.error = None
        else:
            self.error = error
        self.start_time = start_time
        self.request_time = request_time
        self.time_info = time_info or {}
        self.primary_ip = primary_ip
        self.speed_download = speed_download
        self.speed_upload = speed_upload
    @property
    def body(self):
        if self.buffer is None:
            return None
        elif self._body is None:
            self._body = self.buffer.getvalue()
        return self._body
    def rethrow(self):
        if self.error:
            raise self.error
    def __repr__(self):
        args = ",".join("%s=%r" % i for i in sorted(self.__dict__.items()))
        return "%s(%s)" % (self.__class__.__name__, args)

