            if real_target.parent is None and real_target.is_in_sim_inventory():
                return True
            if body[BODY_POSTURE_TYPE_INDEX].unconstrained:
                if real_target.parent is None:
                    return False
                if body[BODY_TARGET_INDEX] is None:
                    return False
