class WizardView(TemplateView):
    storage_name = None
    form_list = None
    initial_dict = None
    instance_dict = None
    condition_dict = None
    template_name = 'formtools/wizard/wizard_form.html'
    def __repr__(self):
        return '<%s: forms: %s>' % (self.__class__.__name__, self.form_list)
    @classonlymethod
    def as_view(cls, *args, **kwargs):
        initkwargs = cls.get_initkwargs(*args, **kwargs)
        return super(WizardView, cls).as_view(**initkwargs)
    @classmethod
    def get_initkwargs(cls, form_list=None, initial_dict=None, instance_dict=None,
                       condition_dict=None, *args, **kwargs):
        kwargs.update({
            'initial_dict': (
                initial_dict or
                kwargs.pop('initial_dict', getattr(cls, 'initial_dict', None)) or {}
            ),
            'instance_dict': (
                instance_dict or
                kwargs.pop('instance_dict', getattr(cls, 'instance_dict', None)) or {}
            ),
            'condition_dict': (
                condition_dict or
                kwargs.pop('condition_dict', getattr(cls, 'condition_dict', None)) or {}
            )
        })
        form_list = form_list or kwargs.pop('form_list', getattr(cls, 'form_list', None)) or []
        computed_form_list = OrderedDict()
        assert len(form_list) > 0, 'at least one form is needed'
        for i, form in enumerate(form_list):
            if isinstance(form, (list, tuple)):
                computed_form_list[six.text_type(form[0])] = form[1]
            else:
                computed_form_list[six.text_type(i)] = form
        for form in six.itervalues(computed_form_list):
            if issubclass(form, formsets.BaseFormSet):
                form = form.form
            for field in six.itervalues(form.base_fields):
                if (isinstance(field, forms.FileField) and
                        not hasattr(cls, 'file_storage')):
                    raise NoFileStorageConfigured(
                        "You need to define 'file_storage' in your "
                        "wizard view in order to handle file uploads."
                    )
        kwargs['form_list'] = computed_form_list
        return kwargs
    def get_prefix(self, request, *args, **kwargs):
        return normalize_name(self.__class__.__name__)
    def get_form_list(self):
        form_list = OrderedDict()
        for form_key, form_class in six.iteritems(self.form_list):
            condition = self.condition_dict.get(form_key, True)
            if callable(condition):
                condition = condition(self)
            if condition:
                form_list[form_key] = form_class
        return form_list
    def dispatch(self, request, *args, **kwargs):
        self.prefix = self.get_prefix(request, *args, **kwargs)
        self.storage = get_storage(
            self.storage_name, self.prefix, request,
            getattr(self, 'file_storage', None),
        )
        self.steps = StepsHelper(self)
        response = super(WizardView, self).dispatch(request, *args, **kwargs)
        self.storage.update_response(response)
        return response
    def get(self, request, *args, **kwargs):
        self.storage.reset()
        self.storage.current_step = self.steps.first
        return self.render(self.get_form())
    def post(self, *args, **kwargs):
        wizard_goto_step = self.request.POST.get('wizard_goto_step', None)
        if wizard_goto_step and wizard_goto_step in self.get_form_list():
            return self.render_goto_step(wizard_goto_step)
        management_form = ManagementForm(self.request.POST, prefix=self.prefix)
        if not management_form.is_valid():
            raise ValidationError(
                _('ManagementForm data is missing or has been tampered.'),
                code='missing_management_form',
            )
        form_current_step = management_form.cleaned_data['current_step']
        if (form_current_step != self.steps.current and
                self.storage.current_step is not None):
            self.storage.current_step = form_current_step
        form = self.get_form(data=self.request.POST, files=self.request.FILES)
        if form.is_valid():
            self.storage.set_step_data(self.steps.current, self.process_step(form))
            self.storage.set_step_files(self.steps.current, self.process_step_files(form))
            if self.steps.current == self.steps.last:
                return self.render_done(form, **kwargs)
            else:
                return self.render_next_step(form)
        return self.render(form)
    def render_next_step(self, form, **kwargs):
        next_step = self.steps.next
        new_form = self.get_form(
            next_step,
            data=self.storage.get_step_data(next_step),
            files=self.storage.get_step_files(next_step),
        )
        self.storage.current_step = next_step
        return self.render(new_form, **kwargs)
    def render_goto_step(self, goto_step, **kwargs):
        self.storage.current_step = goto_step
        form = self.get_form(
            data=self.storage.get_step_data(self.steps.current),
            files=self.storage.get_step_files(self.steps.current))
        return self.render(form)
    def render_done(self, form, **kwargs):
        final_forms = OrderedDict()
        for form_key in self.get_form_list():
            form_obj = self.get_form(
                step=form_key,
                data=self.storage.get_step_data(form_key),
                files=self.storage.get_step_files(form_key)
            )
            if not form_obj.is_valid():
                return self.render_revalidation_failure(form_key, form_obj, **kwargs)
            final_forms[form_key] = form_obj
        done_response = self.done(final_forms.values(), form_dict=final_forms, **kwargs)
        self.storage.reset()
        return done_response
    def get_form_prefix(self, step=None, form=None):
        if step is None:
            step = self.steps.current
        return str(step)
    def get_form_initial(self, step):
        return self.initial_dict.get(step, {})
    def get_form_instance(self, step):
        return self.instance_dict.get(step, None)
    def get_form_kwargs(self, step=None):
        return {}
    def get_form(self, step=None, data=None, files=None):
        if step is None:
            step = self.steps.current
        form_class = self.form_list[step]
        kwargs = self.get_form_kwargs(step)
        kwargs.update({
            'data': data,
            'files': files,
            'prefix': self.get_form_prefix(step, form_class),
            'initial': self.get_form_initial(step),
        })
        if issubclass(form_class, (forms.ModelForm, forms.models.BaseInlineFormSet)):
            kwargs.setdefault('instance', self.get_form_instance(step))
        elif issubclass(form_class, forms.models.BaseModelFormSet):
            kwargs.setdefault('queryset', self.get_form_instance(step))
        return form_class(**kwargs)
    def process_step(self, form):
        return self.get_form_step_data(form)
    def process_step_files(self, form):
        return self.get_form_step_files(form)
    def render_revalidation_failure(self, step, form, **kwargs):
        self.storage.current_step = step
        return self.render(form, **kwargs)
    def get_form_step_data(self, form):
        return form.data
    def get_form_step_files(self, form):
        return form.files
    def get_all_cleaned_data(self):
        cleaned_data = {}
        for form_key in self.get_form_list():
            form_obj = self.get_form(
                step=form_key,
                data=self.storage.get_step_data(form_key),
                files=self.storage.get_step_files(form_key)
            )
            if form_obj.is_valid():
                if isinstance(form_obj.cleaned_data, (tuple, list)):
                    cleaned_data.update({
                        'formset-%s' % form_key: form_obj.cleaned_data
                    })
                else:
                    cleaned_data.update(form_obj.cleaned_data)
        return cleaned_data
    def get_cleaned_data_for_step(self, step):
        if step in self.form_list:
            form_obj = self.get_form(
                step=step,
                data=self.storage.get_step_data(step),
                files=self.storage.get_step_files(step),
            )
            if form_obj.is_valid():
                return form_obj.cleaned_data
        return None
    def get_next_step(self, step=None):
        if step is None:
            step = self.steps.current
        form_list = self.get_form_list()
        keys = list(form_list.keys())
        key = keys.index(step) + 1
        if len(keys) > key:
            return keys[key]
        return None
    def get_prev_step(self, step=None):
        if step is None:
            step = self.steps.current
        form_list = self.get_form_list()
        keys = list(form_list.keys())
        key = keys.index(step) - 1
        if key >= 0:
            return keys[key]
        return None
    def get_step_index(self, step=None):
        if step is None:
            step = self.steps.current
        return list(self.get_form_list().keys()).index(step)
    def get_context_data(self, form, **kwargs):
        context = super(WizardView, self).get_context_data(form=form, **kwargs)
        context.update(self.storage.extra_data)
        context['wizard'] = {
            'form': form,
            'steps': self.steps,
            'management_form': ManagementForm(prefix=self.prefix, initial={
                'current_step': self.steps.current,
            }),
        }
        return context
    def render(self, form=None, **kwargs):
        form = form or self.get_form()
        context = self.get_context_data(form=form, **kwargs)
        return self.render_to_response(context)
    def done(self, form_list, **kwargs):
        raise NotImplementedError(
            "Your %s class has not defined a done() method, which is required."
            % self.__class__.__name__
        )

