            self.items = items
    def __setattr__(self, key, value):
        if key not in self.attribute_map:
            raise KeyError("Invalid key `{}` for `SupportResponse`".format(key))
        self.__dict__[key] = value
    def __getattribute__(self, item):
        value = object.__getattribute__(self, item)
        if isinstance(value, Property):
            return None
        else:
            return value
    def to_dict(self):
        result = {}
        for attr, _ in six.iteritems(self.swagger_types):
            if hasattr(self, attr):
                value = getattr(self, attr)
                if isinstance(value, list):
                    result[attr] = list(map(
                        lambda x: x.to_dict() if hasattr(x, "to_dict") else x,
                        value
                    ))
                elif hasattr(value, "to_dict"):
                    result[attr] = value.to_dict()
                elif isinstance(value, dict):
                    result[attr] = dict(map(
                        lambda item: (item[0], item[1].to_dict())
                        if hasattr(item[1], "to_dict") else item,
                        value.items()
                    ))
                else:
                    result[attr] = value
        if issubclass(SupportResponse, dict):
            for key, value in self.items():
                result[key] = value
        return result
    def to_str(self):
        return pprint.pformat(self.to_dict())
    def __repr__(self):
        return self.to_str()
    def __eq__(self, other):
        if not isinstance(other, SupportResponse):
            return False
        return self.__dict__ == other.__dict__
    def __ne__(self, other):
        return not self == other

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    nickname = db.Column(db.String(64), index=True, unique=True)
    passward= db.Column(db.String(64), index=True, unique=True)
    email = db.Column(db.String(120), index=True, unique=True)
    posts = db.relationship('Post', backref='author', lazy='dynamic')
    about_me = db.Column(db.String(140))
    last_seen = db.Column(db.DateTime)
    followed = db.relationship('User',
        secondary = followers,
        primaryjoin = (followers.c.follower_id == id),
        secondaryjoin = (followers.c.followed_id == id),
        backref = db.backref('followers', lazy = 'dynamic'),
        lazy = 'dynamic')
    is_authenticated = True
    is_active = True
    is_anonymous = False
    def get_id(self):
            return str(self.id)  
    def __repr__(self):
        return '<User %r>' % (self.nickname)
    def set_password(self, password):
        self.passward = generate_password_hash(password)
    def check_password(self, password):
        return check_password_hash(self.passward, password)
    def avatar(self,size):
        return 'http://www.gravatar.com/avatar/f9879d71855b5ff21e4963273a886bfc?d=mm&s=' + str(size)
    def follow(self, user):
        if not self.is_following(user):
            self.followed.append(user)
            return self
    def unfollow(self, user):
        if self.is_following(user):
            self.followed.remove(user)
            return self
    def is_following(self, user):
        return self.followed.filter(followers.c.followed_id == user.id).count() > 0
    def followed_posts(self):
        return Post.query.join(followers, (followers.c.followed_id == Post.user_id)).filter(followers.c.follower_id == self.id).order_by(Post.timestamp.desc())
    @staticmethod
    def make_unique_nickname(nickname):
        if User.query.filter_by(nickname = nickname).first() == None:
         return nickname
        version = 2
        while True:
            new_nickname = nickname + str(version)
            if User.query.filter_by(nickname = new_nickname).first() == None:
                break
            version+=1
        return new_nickname

class Cursor(object):
    __slots__ = [
        "_conn",
        "_type",
        "_id",
        "_count",
        "_cached",
        "_profile",
        "_warnings",
        "_has_more",
        "_batch",
        "_count",
    ]
    def __init__(self, connection, init_data, cursor_type="cursor"):
        self._conn = connection
        self._type = cursor_type
        self._batch = deque()
        self._id = None
        self._count = None
        self._cached = None
        self._profile = None
        self._warnings = None
        if isinstance(init_data, list):
            self._has_more = False
            self._batch.extend(init_data)
            self._count = len(init_data)
        else:
            self._update(init_data)
    def __iter__(self):
        return self
    def __next__(self):
        return self.next()
    def __enter__(self):
        return self
    def __len__(self):
        return self._count
    def __exit__(self, *_):
        self.close(ignore_missing=True)
    def __repr__(self):
        return "<Cursor {}>".format(self._id) if self._id else "<Cursor>"
    def _update(self, data):
        result = {}
        if "id" in data:
            self._id = data["id"]
            result["id"] = data["id"]
        if "count" in data:
            self._count = data["count"]
            result["count"] = data["count"]
        if "cached" in data:
            self._cached = data["cached"]
            result["cached"] = data["cached"]
        self._has_more = data["hasMore"]
        result["has_more"] = data["hasMore"]
        self._batch.extend(data["result"])
        result["batch"] = data["result"]
        if "extra" in data:
            extra = data["extra"]
            if "profile" in extra:
                self._profile = extra["profile"]
                result["profile"] = extra["profile"]
            if "warnings" in extra:
                self._warnings = extra["warnings"]
                result["warnings"] = extra["warnings"]
        return result
    @property
    def id(self):
        return self._id
    @property
    def type(self):
        return self._type
    def batch(self):
        return self._batch
    def has_more(self):
        return self._has_more
    def count(self):
        return self._count
    def cached(self):
        return self._cached
    def profile(self):
        return self._profile
    def warnings(self):
        return self._warnings
    def empty(self):
        return len(self._batch) == 0
    def next(self):
        if self.empty():
            if not self.has_more():
                raise StopIteration
            self.fetch()
        return self.pop()
    def pop(self):
        if len(self._batch) == 0:
            raise CursorEmptyError("current batch is empty")
        return self._batch.popleft()
    def fetch(self):
        if self._id is None:
            raise CursorStateError("cursor ID not set")
        request = Request(method="put", endpoint="/cursor/{}".format(self._id))
        resp = self._conn.send_request(request)
        if not resp.is_success:
            raise CursorNextError(resp, request)
        return self._update(resp.body)
    def close(self, ignore_missing=False):
        if self._id is None:
            return None
        request = Request(method="delete", endpoint="/cursor/{}".format(self._id))
        resp = self._conn.send_request(request)
        if resp.is_success:
            return True
        if resp.status_code == 404 and ignore_missing:
            return False
        raise CursorCloseError(resp, request)

class MVLinear:
    def __init__(self, num_variables: int, term: Dict[int, int], p: int):
        self.num_variables = num_variables
        self.terms: Dict[int, int] = dict()
        self.p = p
        for k,v in term.items():
            if k >> self.num_variables > 0:
                raise ValueError("Term is out of range.")
            if v % p == 0:
                continue
            if k in self.terms:
                self.terms[k] = (self.terms[k] + term[k]) % self.p
            else:
                self.terms[k] = term[k] % self.p
    def __repr__(self):
        limit = 8
        s = ""
        s += "MVLinear("
        for k in self.terms:
            s += " + "
            if limit == 0:
                s += "..."
                break
            s += str(self.terms[k])
            if k != 0:
                s += "*"
            i = 0
            while k != 0:
                if k & 1 == 1:
                    s += "x" + str(i)
                i += 1
                k >>= 1
            limit -= 1
        s += ")"
        return s
    def __copy__(self) -> 'MVLinear':
        t = self.terms.copy()
        return MVLinear(self.num_variables, t, self.p)
    __deepcopy__ = __copy__
    def _assert_same_type(self, other: 'MVLinear'):
        if not isinstance(other, MVLinear):
            raise TypeError("MVLinear can only be added with MVLinear")
        if other.p != self.p:
            raise TypeError("The function being added is not in the same field. ")
    def __add__(self, other: Union['MVLinear', int]) -> 'MVLinear':
        if type(other) is int:
            other = MVLinear(self.num_variables, {0b0: other}, self.p)
        self._assert_same_type(other)
        ans: MVLinear = copy.copy(self)
        ans.num_variables = max(self.num_variables, other.num_variables)
        for k in other.terms:
            if k in self.terms:
                ans.terms[k] = (ans.terms[k] + other.terms[k]) % self.p
                if ans.terms[k] == 0:
                    ans.terms.pop(k)
            else:
                ans.terms[k] = other.terms[k] % self.p
        return ans
    __radd__ = __add__
    def __sub__(self, other: Union['MVLinear', int]) -> 'MVLinear':
        if type(other) is int:
            other = MVLinear(self.num_variables, {0b0: other}, self.p)
        self._assert_same_type(other)
        ans: MVLinear = copy.copy(self)
        ans.num_variables = max(self.num_variables, other.num_variables)
        for k in other.terms:
            if k in self.terms:
                ans.terms[k] = (ans.terms[k] - other.terms[k]) % self.p
                if ans.terms[k] == 0:
                    ans.terms.pop(k)
            else:
                ans.terms[k] = (- other.terms[k]) % self.p
        return ans
    def __neg__(self):
        return 0 - self
    def __rsub__(self, other):
        if type(other) is int:
            other = MVLinear(self.num_variables, {0b0: other}, self.p)
        return other - self
    def __mul__(self, other: Union['MVLinear', int]) -> 'MVLinear':
        if type(other) is int:
            other = MVLinear(self.num_variables, {0b0: other}, self.p)
        self._assert_same_type(other)
        terms: Dict[int, int] = dict()
        for sk in self.terms:  
            for ok in other.terms:  
                if sk & ok > 0:
                    raise ArithmeticError("The product is no longer multi-linear function.")
                nk = sk + ok  
                if nk in terms:
                    terms[nk] = (terms[nk] + self.terms[sk] * other.terms[ok]) % self.p
                else:
                    terms[nk] = (self.terms[sk] * other.terms[ok]) % self.p
                if terms[nk] == 0:
                    terms.pop(nk)
        ans = MVLinear(max(self.num_variables, other.num_variables), terms, self.p)
        return ans
    __rmul__ = __mul__  
    def eval(self, at: List[int]) -> int:
        s = 0
        for term in self.terms:
            i = 0
            val = self.terms[term]
            while term != 0:
                if term & 1 == 1:
                    val = (val * (at[i] % self.p)) % self.p
                if val == 0:
                    break
                term >>= 1
                i += 1
            s = (s + val) % self.p
        return s
    def eval_bin(self, at: int) -> int:
        if at > 2 ** self.num_variables:
            raise ArithmeticError("Number of variables is larger than expected")
        args = [0 for _ in range(self.num_variables)]
        for i in range(self.num_variables):
            args[i] = at >> i & 1
        return self.eval(args)
    def __call__(self, *args, **kwargs) -> int:
        if len(args) == 0:
            return self.eval([])
        if isinstance(args[0], list):
            return self.eval(args[0])
        if isinstance(args[0], set):
            if len(args[0]) != 1:
                raise TypeError("Binary representation should have only one element. ")
            return self.eval_bin(next(iter(args[0])))
        return self.eval(list(args))
    def latex(self):
        s = ""
        for k in self.terms:
            s += " + "
            if self.terms[k] != 1:
                s += str(self.terms[k])
            i = 0
            while k != 0:
                if k & 1 == 1:
                    s += "x_{" + str(i) + "}"
                i += 1
                k >>= 1
        s = s[3:]
        display(Latex('$' + s + '$'))
    def __eq__(self, other: 'MVLinear') -> bool:
        diff = self - other
        return len(diff.terms) == 0  
    def __getitem__(self, item):
        if item in self.terms.keys():
            return self.terms[item]
        else:
            return 0
    def eval_part(self, args: List[int]) -> 'MVLinear':
        s = len(args)
        if s > self.num_variables:
            raise ValueError("len(args) > self.num_variables")
        new_terms: Dict[int, int] = dict()
        for t, v in self.terms.items():
            for k in range(s):
                if t & (1 << k) > 0:
                    v = v * (args[k] % self.p) % self.p
                    t = t & ~(1 << k)
            t_shifted = t >> s
            if t_shifted not in new_terms:
                new_terms[t_shifted] = 0
            new_terms[t_shifted] = (new_terms[t_shifted] + v) % self.p
        return MVLinear(self.num_variables - len(args), new_terms, self.p)
    def collapse_left(self, n: int) -> 'MVLinear':
        new_terms: Dict[int, int] = dict()
        mask = (1 << n) - 1
        for t, v in self.terms.items():
            if t & mask > 0:
                raise ArithmeticError("Cannot collapse: Variable exist. ")
            new_terms[t >> n] = v
        return MVLinear(self.num_variables - n, new_terms, self.p)
    def collapse_right(self, n: int) -> 'MVLinear':
        new_terms: Dict[int, int] = dict()
        mask = ((1 << n) - 1) << (self.num_variables - n)
        anti_mask = (1 << (self.num_variables - n)) - 1
        for t, v in self.terms.items():
            if t & mask > 0:
                raise ArithmeticError("Cannot collapse: Variable exist. ")
            new_terms[t & anti_mask] = v
        return MVLinear(self.num_variables - n, new_terms, self.p)

class PDFPage(object):
