            self.error_msg = error_msg
    @property
    def desktop_id(self):
        return self._desktop_id
    @desktop_id.setter
    def desktop_id(self, desktop_id):
        self._desktop_id = desktop_id
    @property
    def desktop_name(self):
        return self._desktop_name
    @desktop_name.setter
    def desktop_name(self, desktop_name):
        self._desktop_name = desktop_name
    @property
    def error_code(self):
        return self._error_code
    @error_code.setter
    def error_code(self, error_code):
        self._error_code = error_code
    @property
    def error_msg(self):
        return self._error_msg
    @error_msg.setter
    def error_msg(self, error_msg):
        self._error_msg = error_msg
    def to_dict(self):
        result = {}
        for attr, _ in six.iteritems(self.openapi_types):
            value = getattr(self, attr)
            if isinstance(value, list):
                result[attr] = list(map(
                    lambda x: x.to_dict() if hasattr(x, "to_dict") else x,
                    value
                ))
            elif hasattr(value, "to_dict"):
                result[attr] = value.to_dict()
            elif isinstance(value, dict):
                result[attr] = dict(map(
                    lambda item: (item[0], item[1].to_dict())
                    if hasattr(item[1], "to_dict") else item,
                    value.items()
                ))
            else:
                if attr in self.sensitive_list:
                    result[attr] = "****"
                else:
                    result[attr] = value
        return result
    def to_str(self):
        import simplejson as json
        if six.PY2:
            import sys
            reload(sys)
            sys.setdefaultencoding("utf-8")
        return json.dumps(sanitize_for_serialization(self), ensure_ascii=False)
    def __repr__(self):
        return self.to_str()
    def __eq__(self, other):
        if not isinstance(other, VmOperateResult):
            return False
        return self.__dict__ == other.__dict__
    def __ne__(self, other):
        return not self == other

class BaseForm(object):
    field_order = None
    prefix = None
    def __init__(self, data=None, files=None, auto_id='id_%s', prefix=None,
                 initial=None, error_class=ErrorList, label_suffix=None,
                 empty_permitted=False, field_order=None):
        self.is_bound = data is not None or files is not None
        self.data = data or {}
        self.files = files or {}
        self.auto_id = auto_id
        if prefix is not None:
            self.prefix = prefix
        self.initial = initial or {}
        self.error_class = error_class
        self.label_suffix = label_suffix if label_suffix is not None else _(':')
        self.empty_permitted = empty_permitted
        self._errors = None  
        self.fields = copy.deepcopy(self.base_fields)
        self._bound_fields_cache = {}
        self.order_fields(self.field_order if field_order is None else field_order)
    def order_fields(self, field_order):
        if field_order is None:
            return
        fields = OrderedDict()
        for key in field_order:
            try:
                fields[key] = self.fields.pop(key)
            except KeyError:  
                pass
        fields.update(self.fields)  
        self.fields = fields
    def __str__(self):
        return self.as_table()
    def __repr__(self):
        if self._errors is None:
            is_valid = "Unknown"
        else:
            is_valid = self.is_bound and not bool(self._errors)
        return '<%(cls)s bound=%(bound)s, valid=%(valid)s, fields=(%(fields)s)>' % {
            'cls': self.__class__.__name__,
            'bound': self.is_bound,
            'valid': is_valid,
            'fields': ';'.join(self.fields),
        }
    def __iter__(self):
        for name in self.fields:
            yield self[name]
    def __getitem__(self, name):
        "Returns a BoundField with the given name."
        try:
            field = self.fields[name]
        except KeyError:
            raise KeyError(
                "Key %r not found in '%s'" % (name, self.__class__.__name__))
        if name not in self._bound_fields_cache:
            self._bound_fields_cache[name] = field.get_bound_field(self, name)
        return self._bound_fields_cache[name]
    @property
    def errors(self):
        "Returns an ErrorDict for the data provided for the form"
        if self._errors is None:
            self.full_clean()
        return self._errors
    def is_valid(self):
        return self.is_bound and not self.errors
    def add_prefix(self, field_name):
        return '%s-%s' % (self.prefix, field_name) if self.prefix else field_name
    def add_initial_prefix(self, field_name):
        return 'initial-%s' % self.add_prefix(field_name)
    def _html_output(self, normal_row, error_row, row_ender, help_text_html, errors_on_separate_row):
        "Helper function for outputting HTML. Used by as_table(), as_ul(), as_p()."
        top_errors = self.non_field_errors()  
        output, hidden_fields = [], []
        for name, field in self.fields.items():
            html_class_attr = ''
            bf = self[name]
            bf_errors = self.error_class([conditional_escape(error) for error in bf.errors])
            if bf.is_hidden:
                if bf_errors:
                    top_errors.extend(
                        [_('(Hidden field %(name)s) %(error)s') % {'name': name, 'error': force_text(e)}
                         for e in bf_errors])
                hidden_fields.append(six.text_type(bf))
            else:
                css_classes = bf.css_classes()
                if css_classes:
                    html_class_attr = ' class="%s"' % css_classes
                if errors_on_separate_row and bf_errors:
                    output.append(error_row % force_text(bf_errors))
                if bf.label:
                    label = conditional_escape(force_text(bf.label))
                    label = bf.label_tag(label) or ''
                else:
                    label = ''
                if field.help_text:
                    help_text = help_text_html % force_text(field.help_text)
                else:
                    help_text = ''
                output.append(normal_row % {
                    'errors': force_text(bf_errors),
                    'label': force_text(label),
                    'field': six.text_type(bf),
                    'help_text': help_text,
                    'html_class_attr': html_class_attr,
                    'css_classes': css_classes,
                    'field_name': bf.html_name,
                })
        if top_errors:
            output.insert(0, error_row % force_text(top_errors))
        if hidden_fields:  
            str_hidden = ''.join(hidden_fields)
            if output:
                last_row = output[-1]
                if not last_row.endswith(row_ender):
                    last_row = (normal_row % {
                        'errors': '',
                        'label': '',
                        'field': '',
                        'help_text': '',
                        'html_class_attr': html_class_attr,
                        'css_classes': '',
                        'field_name': '',
                    })
                    output.append(last_row)
                output[-1] = last_row[:-len(row_ender)] + str_hidden + row_ender
            else:
                output.append(str_hidden)
        return mark_safe('\n'.join(output))
    def as_table(self):
        "Returns this form rendered as HTML <tr>s -- excluding the <table></table>."
        return self._html_output(
            normal_row='<tr%(html_class_attr)s><th>%(label)s</th><td>%(errors)s%(field)s%(help_text)s</td></tr>',
            error_row='<tr><td colspan="2">%s</td></tr>',
            row_ender='</td></tr>',
            help_text_html='<br /><span class="helptext">%s</span>',
            errors_on_separate_row=False)
    def as_ul(self):
        "Returns this form rendered as HTML <li>s -- excluding the <ul></ul>."
        return self._html_output(
            normal_row='<li%(html_class_attr)s>%(errors)s%(label)s %(field)s%(help_text)s</li>',
            error_row='<li>%s</li>',
            row_ender='</li>',
            help_text_html=' <span class="helptext">%s</span>',
            errors_on_separate_row=False)
    def as_p(self):
        "Returns this form rendered as HTML <p>s."
        return self._html_output(
            normal_row='<p%(html_class_attr)s>%(label)s %(field)s%(help_text)s</p>',
            error_row='%s',
            row_ender='</p>',
            help_text_html=' <span class="helptext">%s</span>',
            errors_on_separate_row=True)
    def non_field_errors(self):
        return self.errors.get(NON_FIELD_ERRORS, self.error_class(error_class='nonfield'))
    def add_error(self, field, error):
        if not isinstance(error, ValidationError):
            error = ValidationError(error)
        if hasattr(error, 'error_dict'):
            if field is not None:
                raise TypeError(
                    "The argument `field` must be `None` when the `error` "
                    "argument contains errors for multiple fields."
                )
            else:
                error = error.error_dict
        else:
            error = {field or NON_FIELD_ERRORS: error.error_list}
        for field, error_list in error.items():
            if field not in self.errors:
                if field != NON_FIELD_ERRORS and field not in self.fields:
                    raise ValueError(
                        "'%s' has no field named '%s'." % (self.__class__.__name__, field))
                if field == NON_FIELD_ERRORS:
                    self._errors[field] = self.error_class(error_class='nonfield')
                else:
                    self._errors[field] = self.error_class()
            self._errors[field].extend(error_list)
            if field in self.cleaned_data:
                del self.cleaned_data[field]
    def has_error(self, field, code=None):
        if code is None:
            return field in self.errors
        if field in self.errors:
            for error in self.errors.as_data()[field]:
                if error.code == code:
                    return True
        return False
    def full_clean(self):
        self._errors = ErrorDict()
        if not self.is_bound:  
            return
        self.cleaned_data = {}
        if self.empty_permitted and not self.has_changed():
            return
        self._clean_fields()
        self._clean_form()
        self._post_clean()
    def _clean_fields(self):
        for name, field in self.fields.items():
            if field.disabled:
                value = self.initial.get(name, field.initial)
            else:
                value = field.widget.value_from_datadict(self.data, self.files, self.add_prefix(name))
            try:
                if isinstance(field, FileField):
                    initial = self.initial.get(name, field.initial)
                    value = field.clean(value, initial)
                else:
                    value = field.clean(value)
                self.cleaned_data[name] = value
                if hasattr(self, 'clean_%s' % name):
                    value = getattr(self, 'clean_%s' % name)()
                    self.cleaned_data[name] = value
            except ValidationError as e:
                self.add_error(name, e)
    def _clean_form(self):
        try:
            cleaned_data = self.clean()
        except ValidationError as e:
            self.add_error(None, e)
        else:
            if cleaned_data is not None:
                self.cleaned_data = cleaned_data
    def _post_clean(self):
        pass
    def clean(self):
        return self.cleaned_data
    def has_changed(self):
        return bool(self.changed_data)
    @cached_property
    def changed_data(self):
        data = []
        for name, field in self.fields.items():
            prefixed_name = self.add_prefix(name)
            data_value = field.widget.value_from_datadict(self.data, self.files, prefixed_name)
            if not field.show_hidden_initial:
                initial_value = self.initial.get(name, field.initial)
                if callable(initial_value):
                    initial_value = initial_value()
            else:
                initial_prefixed_name = self.add_initial_prefix(name)
                hidden_widget = field.hidden_widget()
                try:
                    initial_value = field.to_python(hidden_widget.value_from_datadict(
                        self.data, self.files, initial_prefixed_name))
                except ValidationError:
                    data.append(name)
                    continue
            if field.has_changed(initial_value, data_value):
                data.append(name)
        return data
    @property
    def media(self):
        media = Media()
        for field in self.fields.values():
            media = media + field.widget.media
        return media
    def is_multipart(self):
        for field in self.fields.values():
            if field.widget.needs_multipart_form:
                return True
        return False
    def hidden_fields(self):
        return [field for field in self if field.is_hidden]
    def visible_fields(self):
        return [field for field in self if not field.is_hidden]

class WMB(object):
    class Node:
        def __init__(self):
            self.clique = VarSet()
            self.theta = Factor().log()
            self.weight = 1.0
            self.parent = None
            self.children = []
            self.msgFwd = Factor().log()
            self.msgBwd = Factor().log()
            self.originals = []
        def __repr__(self):
            return "{}^{}".format(self.clique,self.weight)
        def __str__(self):
            return "{}".format(self.clique)
        def __lt__(self, other):
            return False         
    class ConstantList:
        def __init__(self, val):
            self.val = val
        def __getitem__(self, loc):
            return self.val
    def __init__(self, model, elimOrder=None, iBound=0, sBound=0, weights=1.0, attach=True, **kwargs):
        self.model = model
        self.X     = model.X
        self.logValue = model.logValue
        if elimOrder is None: elimOrder = 'wtminfill'
        if type(elimOrder) is str:   
            if not type(weights) in {float, str}:
              raise ValueError("Must specify elimination order or use all-equal weights (float or string)"); 
            elimOrder = eliminationOrder(self.model, orderMethod=elimOrder)[0];  
        self.elimOrder = elimOrder
        self.priority = [-1 for i in range(model.nvar)]  
        for i,x in enumerate(elimOrder): self.priority[x] = i
        self.buckets = [ [] for x in range(model.nvar) ]  
        self.matches = [ [] for x in range(model.nvar) ] 
        self.setWeights(weights)   
        for f in model.factors:
            n = self.addClique(f.vars)
            if attach: n.theta += f.log()                 
            n.originals.append(f)              
        self.setWeights(weights)
    def setWeights(self,weights):
        if type(weights) is str:
            if weights == 'sum+': weights =  1.0;
            elif weights=='sum-': weights = -1.0;
            elif weights=='max+': weights = 1e-8;
            else: raise ValueError("Unknown weight / task type; must be max+, sum+, sum-, or float / float list")
        if type(weights) is float: weights = WMB.ConstantList(weights)
        self.weights = weights
        for i,xi in enumerate(self.elimOrder):     
            ni = len(self.buckets[i])
            for j in range(ni):               
                self.buckets[i][j].weight = self.weights[xi]/ni
            if self.weights[xi] < 0 and ni > 0:          
                self.buckets[i][0].weight = 1.0 - self.weights[xi]*(ni-1)/ni
    def __nodeID(self,node):
        if not isinstance(node, WMB.Node): return None,None
        i = min([self.priority[x] for x in node.clique])  
        j = self.buckets[i].index(node)
        return i,j
    def __repr__(self):     
        to_return = ""
        for i,b in enumerate(self.buckets):
            to_return += "{:03d}: ".format(int(self.elimOrder[i]))
            for j,mb in enumerate(b):
                to_return += "{!s}^{:.2f} => {}; ".format(mb,mb.weight, self.__nodeID(mb.parent))
            to_return += "\n"
        return to_return
    def addClique(self,vars):
        vs = VarSet(vars)
        corder = np.argsort( [self.priority[x] for x in vars]  ) 
        corder = [vars[c] for c in corder]
        added = []
        found = False
        for x in corder:
            if found: break
            b = self.buckets[self.priority[x]]
            to_remove = []
            for mb in b:
                if mb.clique < vs:
                   to_remove.append(mb)
                if mb.clique >= vs:                
                    if len(added) > 0:             
                        mb.children.append( added[-1] )  
                        added[-1].parent = mb          
                    found = True                   
                    added.append(mb)               
                    break
            if not found:                          
                n = WMB.Node()
                n.clique = VarSet(vs)
                n.weight = -1e-3 if self.weights[x] < 0 else 1e-3;   
                b.append(n)
                if len(added) > 0:                 
                    n.children.append(added[-1])
                    added[-1].parent = n
                added.append(n)                    
                vs -= [x]                          
                for mb in to_remove:
                    for c in mb.children: c.parent = n  
                    n.children.extend(mb.children) 
                    n.weight += mb.weight          
                    if mb.parent is not None:      
                        mb.theta -= mb.msgFwd
                        mb.parent.theta += mb.msgFwd
                        mb.parent.children.remove(mb)
                    n.theta += mb.theta                
                    n.originals.extend(mb.originals)   
                    b.remove(mb)
        return added[0]
    def detachFactors(self):
        for b in self.buckets:
            for mb in b:
                mb.theta = Factor([],0.)
    def attachFactors(self):
        for b in self.buckets:
            for mb in b:
                mb.theta = Factor([],0.)
                for f in mb.originals: mb.theta += f.log()
    def memory(self, bucket=None, use_backward=True):
        mem = 0.
        use_buckets = self.buckets if bucket is None else [self.buckets[bucket]]
        for b in use_buckets:
            for mb in b:
                mem += mb.clique.nrStatesDouble() * mb.theta.table.itemsize
        return mem / 1024. / 1024.
    def scoreByScope(ibound=None, sbound=None):
      def score(m1,m2):
        jt = m1.clique | m2.clique
        if ibound is not None and len(jt) > ibound: return -1
        if sbound is not None and jt.nrStates() > sbound: return -1
        mx,mn = max([len(m1.clique),len(m2.clique)]), min([len(m1.clique),len(m2.clique)])
        return 1.0/(float(mx)+float(mn)/mx)
      return score
    def merge(self, score):
        from heapq import heappush,heappop
        from itertools import count
        tiebreak = count().__next__        
        for b in self.buckets:
            priority = [] 
            lookup = {}
            for i,m1 in enumerate(b):
                for m2 in b[i+1:]:
                    s = score(m1,m2)
                    if s >= 0.0:
                        entry = [-s,tiebreak(),m1,m2]
                        lookup[(m1,m2)] = entry
                        heappush(priority, entry)
            while len(priority):
                entry = heappop(priority)
                s,_,m1,m2 = entry[0],entry[1],entry[2],entry[3]
                if m1 is None or m2 is None: continue
                if m1 not in b or m2 not in b: continue   
                for m in b:
                    for ma,mb in [(m1,m),(m,m1),(m2,m),(m,m2)]:
                        s = -lookup.get( (ma,mb), [1,None,None] )[0]
                        if s >= 0.0: 
                            entry = lookup.pop( (ma,mb) )
                            entry[2],entry[3] = None,None  
                m12 = self.addClique( m1.clique | m2.clique )
                for m in b:
                    if m is m12: continue
                    s = score(m12,m)
                    if s >= 0.0:
                        entry = [-s,tiebreak(),m12,m] 
                        lookup[ (m12,m) ] = entry
                        heappush(priority,entry)
        return None
    def mergeScope(iBound=0, sBound=0): 
