class Exemplar(object):
    def __init__(self, base, trailers=''):
        self.base = base
        self.trailers = trailers
    def _get_text(self):
        return self.base + self.trailers
    text = property(_get_text)
    def __str__(self):
        if self.trailers == '':
            return self.base
        else:
            return '{} {}'.format(self.base, self.trailers)
    def __repr__(self):
        base = codecs.encode(self.base, 'unicode_escape')
        if self.trailers == '':
            return "'Exemplar('{}')'".format(base)
        else:
            trailers = codecs.encode(self.trailers, 'unicode_escape')
            return "'Exemplar('{}', '{}')'".format(base, trailers)
    def __hash__(self):
        return hash((self.base, self.trailers))
    def __eq__(self, other):
        if self.base == other.base and self.trailers == other.trailers:
            return True
        return False
    def __ne__(self, other):
        return not self.__eq__(other)

class BinaryOperator(Node):
    def __init__(self, lhs, rhs, symbol, operator):
        super().__init__()
        self.lhs = lhs
        self.rhs = rhs
        self.symbol = symbol
        self.operator = operator
    def __eq__(self, other):
        assert (self.lhs is not None and self.rhs is not None)
        assert (other.lhs is not None and other.rhs is not None)
        assert (isinstance(self.lhs, type(other.lhs)))
        assert (isinstance(self.rhs, type(other.rhs)))
        return self.lhs == other.lhs and self.rhs == other.rhs
    def __str__(self):
        assert (self.lhs is not None and self.rhs is not None)
        return '({} {} {})'.format(self.lhs, self.symbol, self.rhs)

