class Condition:
    def __init__(self,attribute="",op="",value=0):
        self.attribute = attribute
        self.op = op
        self.value = value
    def clear(self):
        self.op=""
        self.attribute=""
        self.value=0
    def judge(self,value):
        if type(value)==type(1.0):
            if self.op=='<':
                return value<self.value
            elif self.op=='<=':
                return (value<self.value) or abs(self.value-value)<0.0001
            elif self.op=='>':
                return value>self.value
            elif self.op=='>=':
                return (value>self.value) or abs(self.value-value)<0.0001
            elif self.op=='=':
                return abs(self.value-value)<0.0001
            elif self.op=='!=':
                return not abs(self.value-value)<0.0001
            else:
                return False
        else:
            if self.op=='<':
                return value<self.value
            elif self.op=='<=':
                return value<=self.value
            elif self.op=='>':
                return value>self.value
            elif self.op=='>=':
                return value>=self.value
            elif self.op=='=':
                return self.value==value
            elif self.op=='!=':
                return not self.value==value
            else:
                return False
    def __repr__(self):
        return self.op+str(self.value)

