    def __init__(self, blocks):
        self.blocks = blocks
    def is_valid(self):
        for index, cur_block in enumerate(self.blocks[1:]):
            prev_block = self.blocks[index]
            if prev_block.index + 1 != cur_block.index:
                print('index error')
                return False
            if not cur_block.is_valid():  
                print('block invalid')
                return False
            if prev_block.hash != cur_block.prev_hash:
                print('hash error')
                return False
        return True
    def self_save(self):
        for b in self.blocks:
            b.self_save()
        return True
    def find_block_by_index(self, index):
      for b in self.blocks:
        if b.index == index:
          return b['count']
      return False
    def find_block_by_hash(self, hash):
        for b in self.blocks:
            if b.hash == hash:
                return b
        return False
    def __len__(self):
        return len(self.blocks)
    def __eq__(self, other):
        if len(self) != len(other):
            return False
        for self_block, other_block in zip(self.blocks, other.blocks):
            if self_block != other_block:
                return False
        return True
    def most_recent_block(self):
        return self.blocks[-1]
    def max_index(self):
        return self.blocks[-1].index
    def add_block(self, new_block):
        if new_block.index > len(self):
            pass
        self.blocks.append(new_block)
        return True
