class Sprite(object):
    def __init__(self, name, loot, strength):
        self.name = name
        self.x = 0
        self.y = 0
        self.health = 10
        self.strength = strength
        self.loot = loot
        self.is_alive = True
        self.MAX_HEALTH = 15
        self.magic_key = False
        logging.debug("{0} created with health of {1} and strength of {2}"
                      .format(self.name, self.health, self.strength))
    def __repr__(self):
        return "\nSprite info: " + self.name + "\nx = {0}\ny = {1}\nhealth = {2}\nstrength = {3}\nloot = {4}\n"\
            .format(self.x, self.y, self.health, self.strength, self.loot)
    def set_dead(self):
        assert self.health < 0, "Health is not less than 0, Sprite should not be dead"
        self.is_alive = False
    def attack(self, victim):
        assert victim.is_alive, "Cannot attack, victim is already dead"
        if victim.strength < self.strength:
            victim.health -= random.randint(0, 15)
            logging.debug("{0} is stronger".format(self.name))
        else:  
            victim.health -= random.randint(0, 5)
            logging.debug("{0} is stronger".format(victim.name))
        print(self.name, "attacks", victim.name)
        victim.show_health()
        if victim.health < 0:
            self.loot += victim.loot
            victim.loot = 0
    def feed(self):
        self.health += random.randrange(1, 3)  
        if self.health > self.MAX_HEALTH:  
            self.health = self.MAX_HEALTH
        print(self.name, "ate food")
        self.show_health()
    def show_health(self):
        print(self.name + "'s health is ", str(self.health))
    def show_loot(self):
        print(self.name, "has a total loot of ", str(self.loot))
    def show_strength(self):
        print(self.name, "has a strength of", str(self.strength))
    def move(self):
        assert self.is_alive, "Sprite is dead, and should not be able to move"
        if self.health > 3:
            self.y += random.randint(-1, 1)  
            self.x += random.randint(-1, 1)  
        print(self.name, "moves to position", str(self.x), ",", str(self.y))

class Delta(GaOptimizable):
    tuner = None
    fittest = None
    real_delta = []
    def __init__(self, generation):
        super(Delta, self).__init__(generation)
        self.delta_params = DeltaParams()
        if Delta.tuner is None:
            Delta.tuner = DeltaTuner('COM10')
        try:
            Delta.real_delta[self.get_reference_delta()]
        except IndexError:
            try:
                ref_params = Delta.fittest.delta_params
            except AttributeError:
                ref_params = Delta.tuner.get_delta_params()
            Delta.tuner.set_delta_params(ref_params)
            time.sleep(1)
            probings = Delta.tuner.probe_bed()
            zcount = 0
            zsum = 0
            for probing in probings:
                zcount += 1
                zsum += probing[2]
            zsum /= zcount
            for i, probing in enumerate(probings):
                probings[i][2] -= zsum
            Delta.real_delta.append({
                'params': ref_params,
                'probing': probings
            })
        self.sim = DeltaSimulator(Delta.real_delta[self.get_reference_delta()]['params'], self.delta_params)
    def get_reference_delta(self):
        return 0
    def get_adn_limits(self):
        return self.delta_params.get_param_lims()
    def get_adn(self):
        return self.delta_params.serialize()
    def set_adn(self, adn):
        self.delta_params.deserialize(adn)
        self.sim.real_params = self.delta_params
    def rate_fitness(self):
        probings = Delta.real_delta[self.get_reference_delta()]['probing']
        sim_probings = self.sim.calc_z_errors_at_pos(probings)
        error = 0
        for i, probing in enumerate(probings):
            error += (probings[i][2] - sim_probings[i][2])**2
        return 1/error
    def from_json(cls, js_data):
        raise NotImplementedError()
    def __repr__(self):
        return "Delta {} [x:{:.2f} y:{:.2f} z:{:.2f} A_ang:{:.2f} B_ang:{:.2f} C_ang:{:.2f} " \
               "A_rad:{:.2f} B_rad:{:.2f} C_rad:{:.2f} dt_rad:{:.2f} " \
               "A_rod:{:.2f} B_rod:{:.2f} C_rod:{:.2f} ".format(
            self.name,
            self.delta_params.x_endstop,
            self.delta_params.y_endstop,
            self.delta_params.z_endstop,
            self.delta_params.angle_offset_t1,
            self.delta_params.angle_offset_t2,
            self.delta_params.angle_offset_t3,
            self.delta_params.radius_offset_t1,
            self.delta_params.radius_offset_t2,
            self.delta_params.radius_offset_t3,
            self.delta_params.radius,
