    def psd(self, nperseg=None, noverlap=None, detrend='constant', nfft=None, normalize=False, **kwargs):
        t, x = self.get(**kwargs)
        if nperseg is None:
            nperseg = int(0.25 * x.size)
        _dt = np.diff(t)
        if not np.isclose(min(_dt), max(_dt), rtol=1.e-2, atol=1.e-6):
            raise ValueError(f"The time step of '{self.name}' varies with more than 1%. A constant time step is "
                             f"required when estimating power spectral density using FFT. Resample to constant "
                             f"time step.")
        dt = float(np.mean(_dt))
        f, p = psd(x, dt, nperseg=nperseg, noverlap=noverlap, detrend=detrend, nfft=nfft, scaling='density',
                   return_onesided=True, axis=-1)
        if normalize:
            p = p / np.max(p)
        return f, p
    def resample(self, dt=None, t=None):
        assert dt is not None or t is not None, "Either new time step 'dt' or new time array 't' has to be specified."
        if t is not None:
            assert t.min() >= self.start and t.max() <= self.end, "The new specified time array exceeds the original " \
                                                                  "time array. Extrapolation is not allowed."
            return self.interpolate(t)
        else:
            assert dt > 0., "The specified time step is to small."
            return self.interpolate(np.arange(self.start, self.end, step=dt))
    def rfc(self, **kwargs):
        _, x = self.get(**kwargs)
        cycles = count_cycles(x)
        return cycles
    def set_dtg_ref(self, new_ref=None):
        if new_ref is not None and not isinstance(new_ref, datetime):
            raise ValueError("`new_ref` must be a datetime.datetime instance")
        elif new_ref is None and self._dtg_ref is None:
            raise ValueError("New dtg reference must be given if attribute `dtg_ref` is not pre-defined")
        if new_ref is not None and self._dtg_ref is None:
            self._dtg_ref = new_ref
        elif new_ref is not None and self._dtg_ref is not None:
            delta = (self._dtg_ref - new_ref).total_seconds()
            self._dtg_ref = new_ref
            self._t += delta
            self._dtg_time = None  
        elif new_ref is None and self._dtg_ref is not None:
            delta = -self.start
            self._dtg_ref = self.dtg_start
            self._t += delta
            self._dtg_time = None  
    def stats(self, statsdur=10800., quantiles=(0.37, 0.57, 0.9), is_minima=False, include_sample=False, **kwargs):
        t, x = self.get(**kwargs)
        try:
            tz = 1. / average_frequency(t, x)
        except IndexError:
            tz = np.nan
        if not is_minima:
            f = 1.
        else:
            f = -1.
        mx = find_maxima(f * x)
        if np.size(mx) <= 1:
            wloc = wscale = wshape = gloc = gscale = np.nan
            pvalues = {f"p_{100 * q:.2f}": np.nan for q in quantiles}
        else:
            wloc, wscale, wshape = pwm(mx)
            if any(np.isnan([wloc, wscale, wshape])):
                wloc = wscale = wshape = np.nan
            n = round(statsdur / (t[-1] - t[0]) * np.size(mx))
            try:
                gloc, gscale = weibull2gumbel(wloc, wscale, wshape, n)
            except (AssertionError, ZeroDivisionError) as e:
                gloc = gscale = np.nan
            try:
                g = Gumbel(loc=gloc, scale=gscale)
            except AssertionError as e:
                values = np.nan * np.ones(np.shape(quantiles))
            else:
                values = g.invcdf(p=quantiles)
            finally:
                pvalues = {f"p_{100 * q:.2f}": f * v for q, v in zip(quantiles, values)}
        d = OrderedDict(
            start=t[0], end=t[-1], duration=t[-1] - t[0], dtavg=np.mean(np.diff(t)),
            mean=x.mean(), std=tstd(x), skew=skew(x, bias=False),
            kurt=kurtosis(x, fisher=False, bias=False), min=x.min(), max=x.max(), tz=tz,
            wloc=wloc, wscale=wscale, wshape=wshape, gloc=gloc, gscale=gscale, is_minima=is_minima,
            sample=f * mx if include_sample else None, **pvalues
        )
        return d
    def std(self, **kwargs):
        _, x = self.get(**kwargs)
        return tstd(x)
    def skew(self, bias=False, **kwargs):
        _, x = self.get(**kwargs)
        return skew(x, bias=bias)

class PrefixCppDocComment:
    def __init__(self, token):
        self.start_pos = token.start_pos
        self.value_len = len(token.value)  
        self.value = token.value[3:-2].strip()
    def appply_to_idl(self, idl: Idl, content: str):
        if self.start_pos is None:
            return
        actual_pos = self.start_pos + self.value_len
        while content[actual_pos] in ' \t\n\r':
            actual_pos += 1
        for item in self.supported_types(idl):
            meta = item.parse_meta
            if meta and meta.start_pos == actual_pos:
                item.description = self.value
                return
    def supported_types(self, idl: Idl):
        for cluster in idl.clusters:
            yield cluster
            for command in cluster.commands:
                yield command
    def __repr__(self):
        return ("PREFIXDoc: %r at %r" % (self.value, self.start_pos))

class PeerList(object):
    def __init__(self):
        self._peers_state = RandomlyOrderedDict() 
        self._on_state_change_callbacks = [] 
    def __getitem__(self, peer: Peer) -> Peer:
        return self._peers_state[peer].peer
    def __delitem__(self, peer: Peer) -> None:
        if peer in self._peers_state:
            peer_state = self._peers_state[peer]
            del self._peers_state[peer]
            self._trigger_on_state_change_callbacks(peer_state.peer, None, peer_state.state)
        else:
            raise KeyError()
    def __len__(self):
        return len(self._peers_state)
    def __iter__(self):
        return self._peers_state.__iter__()
    def __repr__(self):
        return "<PeerList %s>" % (' '.join('%s[%s]' % (peer_state.peer.nodename, peer_state.state) for peer_state in self._peers_state.values()))
    def on_state_change(self, callback: Callable):
        self._on_state_change_callbacks.append(callback)
    def _trigger_on_state_change_callbacks(self, peer, state, oldstate):
        for callback in self._on_state_change_callbacks:
            callback(peer, state, oldstate)
    def set_peer_state(self, peer: Peer, state: PeerState):
        if peer in self._peers_state:
            old_state = self._peers_state[peer].state
            self._peers_state[peer].update_state(state)
        else:
            old_state = None
            self._peers_state[peer] = PeerUpdate(peer, state)
        if old_state != self._peers_state[peer].state:
            self._trigger_on_state_change_callbacks(peer, state, old_state)
    def apply_updates(self, updates: List[PeerUpdate]):
        if not isinstance(updates, Iterable):
            updates = [updates]
        for update in updates:
            if update.peer not in self._peers_state:
                self.set_peer_state(update.peer, update.state)
            elif update.refresh_timestamp >= self._peers_state[update.peer].refresh_timestamp:
                current = self._peers_state[update.peer]
                if update.state != current.state:
                    self.set_peer_state(update.peer, update.state)
                if current.peer.nodename != update.peer.nodename:
                    logger.warning("Node %s (%s:%d) changed name to %s", current.peer.nodename, current.peer.host, current.peer.port, update.peer.nodename)
                    current.peer.nodename = update.peer.nodename
                current.refresh_timestamp = update.refresh_timestamp
    def get_peers_states(self, exclude_peers: List[Peer] = None, include_states: Iterable[PeerState] = None):
        if exclude_peers == None:
            exclude_peers = []
        if include_states == None:
            include_states = list(PeerState)
        peers_states = list(
            peer_state
            for peer_state
            in self._peers_state.values()
            if peer_state.peer not in exclude_peers
            and peer_state.state in include_states
            )
        return peers_states
    def get_peers(self, exclude_peers: List[Peer] = None, include_states: Iterable[PeerState] = None) -> List[Peer]:
        return list(peer_state.peer for peer_state in self.get_peers_states(exclude_peers, include_states))
    def get_random_peers(self, count: int, **kwargs) -> List[Peer]:
        peers = self.get_peers(**kwargs)
        return random.sample(peers, min(len(peers), count))
    def cycle_peers(self, exclude_peers: List[Peer] = None, include_states: Iterable[PeerState] = None) -> Iterator[Peer]:
        i = iter(self._peers_state.values())
        nothing_matched = True
        while True:
            try:
                peer_state = next(i)
                if peer_state.peer in exclude_peers:
                    continue
                elif peer_state.state not in include_states:
                    continue
                else:
                    nothing_matched = False
                    yield peer_state.peer
            except StopIteration:
                if nothing_matched:
                    yield None
                i = iter(self._peers_state.values())
                nothing_matched = True
    def get_hash(self):
        sorted_list = sorted(list(self._peers_state.values()))
        string = ','.join('%s:%d=%s' % (peer_state.peer.host, peer_state.peer.port, peer_state.state) for peer_state in sorted_list)
        return hashlib.sha1(string.encode('ascii')).hexdigest()

class V1StatefulSetCondition(object):
    openapi_types = {
        'last_transition_time': 'datetime',
        'message': 'str',
        'reason': 'str',
        'status': 'str',
        'type': 'str'
    }
    attribute_map = {
        'last_transition_time': 'lastTransitionTime',
        'message': 'message',
        'reason': 'reason',
        'status': 'status',
        'type': 'type'
    }
    def __init__(self, last_transition_time=None, message=None, reason=None, status=None, type=None, local_vars_configuration=None):  
        if local_vars_configuration is None:
            local_vars_configuration = Configuration()
        self.local_vars_configuration = local_vars_configuration
        self._last_transition_time = None
        self._message = None
        self._reason = None
        self._status = None
        self._type = None
        self.discriminator = None
        if last_transition_time is not None:
            self.last_transition_time = last_transition_time
        if message is not None:
            self.message = message
        if reason is not None:
            self.reason = reason
        self.status = status
        self.type = type
    @property
    def last_transition_time(self):
        return self._last_transition_time
    @last_transition_time.setter
    def last_transition_time(self, last_transition_time):
        self._last_transition_time = last_transition_time
    @property
    def message(self):
        return self._message
    @message.setter
    def message(self, message):
        self._message = message
    @property
    def reason(self):
        return self._reason
    @reason.setter
    def reason(self, reason):
        self._reason = reason
    @property
    def status(self):
        return self._status
    @status.setter
    def status(self, status):
        if self.local_vars_configuration.client_side_validation and status is None:  
            raise ValueError("Invalid value for `status`, must not be `None`")  
        self._status = status
    @property
    def type(self):
        return self._type
    @type.setter
    def type(self, type):
        if self.local_vars_configuration.client_side_validation and type is None:  
            raise ValueError("Invalid value for `type`, must not be `None`")  
        self._type = type
    def to_dict(self):
        result = {}
        for attr, _ in six.iteritems(self.openapi_types):
            value = getattr(self, attr)
            if isinstance(value, list):
                result[attr] = list(map(
                    lambda x: x.to_dict() if hasattr(x, "to_dict") else x,
                    value
                ))
            elif hasattr(value, "to_dict"):
                result[attr] = value.to_dict()
            elif isinstance(value, dict):
                result[attr] = dict(map(
                    lambda item: (item[0], item[1].to_dict())
                    if hasattr(item[1], "to_dict") else item,
                    value.items()
                ))
            else:
                result[attr] = value
        return result
    def to_str(self):
        return pprint.pformat(self.to_dict())
    def __repr__(self):
        return self.to_str()
    def __eq__(self, other):
        if not isinstance(other, V1StatefulSetCondition):
            return False
        return self.to_dict() == other.to_dict()
    def __ne__(self, other):
        if not isinstance(other, V1StatefulSetCondition):
            return True
        return self.to_dict() != other.to_dict()

class GNS(object):
    def __init__(self, *args, **kwargs):
        self.COLON = ':'
        self.CLN = ':'
        self.COMMA = ','
        self.CMMA = ','
        self.SEMICOLON = ';'
        self.NEWLINE = '\n'
        self.NWLNE = '\n'
        self.SPACE = ' '
        self.SPCE = ' '
        self.TAB = '\t'
        self.TB = '\t'
        self.SLASH = '/'
        self.LPARENS = '('
        self.RPARENS = ')'
        self.AT = '@'
        self.DOT = '.'
        self.ASTER = '*'
        self.set_namespace('config')
        self.set_namespace('config.directories')
        self.config.directories.home = os.sep.join(os.path.realpath(__file__).split(os.sep)[:-2]) + os.sep
        self.config.directories.settings_ini = self.config.directories.home + 'settings.ini'
        settings = configparser.ConfigParser()
        results = settings.read(self.config.directories.settings_ini)
        for SECTION in [s for s in settings.sections()]:
            section = SECTION.lower()
            self.set_namespace('config.{}'.format(section))
            for OPTION in settings.options(SECTION):
                option = OPTION.lower()
                value = settings.get(SECTION, OPTION)
                setattr(getattr(self.config, section), option, self.pythonize(value))
        path_to_logging = self('{config.directories.path_to_logging}/{date}', date=datetime.datetime.now().strftime('%Y/%m/%d--%X').replace('/', '-'))
        log_level = self.config.logging.log_level
        numeric_level = getattr(logging, log_level.upper())
        if numeric_level is None:
            raise ValueError('Invalid log level: {}'.format(loglevel))
        logging.basicConfig(filename=path_to_logging, filemode='a+', level=numeric_level)
        if hasattr(sys.stdout, 'isatty') and sys.stdout.isatty():
            root = logging.getLogger()
            stdout_level = logging.DEBUG
            stdout_handler = logging.StreamHandler(sys.stdout)
            stdout_handler.setLevel(logging.INFO)
            root.addHandler(stdout_handler)
    @staticmethod
    def pythonize(value):
        if isinstance(value, str) or isinstance(value, unicode):
            return {
                'true':True, 'false':False, 
                'on':True, 'off':False, 
                'yes':True, 'no':False
                }.get(value.lower().strip(), value)
        return value
    def setup_verbosity(self, obj):
        obj.verbose = self.config.defaults.verbose
        if obj.verbose:
            obj.default_logger = lambda *args, **kwargs: sys.stdout.write("".join(args) + '\n')
        else:
            obj.default_logger = lambda *args, **kwargs: ()
    @property
    def dict_not_underscore_not_upper(self):
        return {key: value for key, value in self.__dict__.items() if not key.startswith('_') and not key.isupper()}
    @staticmethod
    def make_object(name):
        return type(name, (), {})
    def set_namespace(self, ns):
        if not '.' in ns:
            setattr(self, ns, GNS.make_object(ns))
        else:
            class_name = []
            prev_class = self
            for inner in ns.split('.'):
                class_name.append(inner)
                if not hasattr(prev_class, inner):
                    setattr(prev_class, inner, GNS.make_object(".".join(class_name)))
                prev_class = getattr(prev_class, inner)
    def new(self):
        for key in self.dict_not_underscore_not_upper:
            del self.__dict__[key]
    def local(self):
        return self.__class__()        
    @contextlib.contextmanager
    def block(self):
        yield self.__class__()
    @property
    def dict_from_dict(self):
        return {key: value for key, value in self.__dict__.items() if not key.startswith('_')}
    def __call__(self, *args, **kwargs):
        d = self.dict_from_dict
        d.update(kwargs)
        try:
            return ''.join(args).format(**d)
        except AttributeError:
            return None
    @classmethod
    def string(cls, astring, *args, **kwargs):
        for arg in args:
            kwargs.update(arg.__dict__)
        return cls(*args, **kwargs)(astring)
    def get(self, path, default=None, required=True):
        me = self
        for inner in path.split('.'):
            if not hasattr(me, inner):
                if required:
                    raise TypeError(self('This app requires a setting for {path}', path=path))
                return default
            else:
                me = getattr(me, inner)
        return me
    @property
    def kwargs(self):
        return {key: value for key, value in self.__dict__.items() if key.islower() and not key.startswith('_')}
    @property
    def declared_kwargs(self):
        return {key: value for key, value in self.__dict__.items() if key.islower() and not key.startswith('_')}
    def __repr__(self):
        return str(self.dict_not_underscore_not_upper)

class _WhContextManager:
    def __init__(self, func, stream):
        self._args = self._kwds = self._ret = None
        self._func = func
        self._stream = stream
        self._started = self.ncall = self.elapsed = 0
        self._called = False
    def __call__(self, *args, **kwds):
        if self._called:
            return self._after_call(*args, **kwds)
        self._args = args
        self._kwds = kwds
        self._called = True
        return self
    def _after_call(self, *args, **kwds):
        self._record_start()
        self._ret = self._func(*args, **kwds)
        self._record_end()
        return self._ret
    def _record_start(self):
        self.ncall += 1
        self._started = time() * 1000
    def _record_end(self):
        self.elapsed += time() * 1000 - self._started
    def __enter__(self):
        self._record_start()
        self._ret = self._func(* self._args, ** self._kwds)
        self._record_end()
        return self._ret
    def reset(self):
        self._called = False
        self.ncall = self.elapsed = 0
    def done(self):
        self._stream.write(
            '[wh] {}: {} calls, {}(ms) elapsed\n'.format(
                self._func.__name__, self.ncall, self.elapsed
            )
        )
        self._stream.flush()
        self.reset()
    def __exit__(self, *_):
        self.done()
    def _check_call(self):
        if not self._called:
            raise TypeError('Function should be called at least once')
        self.__enter__()
    @property
    def retval(self):
        self._check_call()
        return self._ret
    def __eq__(self, other):
        self._check_call()
        return self._ret == other
    def __lt__(self, other):
        self._check_call()
        return self._ret < other
    def __repr__(self):
        self._check_call()
        return repr(self._ret)
    def __str__(self):
        self._check_call()
        return str(self._ret)

class SignalDesc:
    def __init__(self, event, fields):
        self.event = event
        self.fields = sorted(fields)
    def __eq__(self, other):
        return self.__dict__ == other.__dict__
    def __hash__(self):
        return hash(self.event) ^ hash(tuple(self.fields))
    @classmethod
    def from_event(cls, event, fields=None):
        try:
            return cls._SIGNALS_MAP[event]
        except KeyError:
            if not fields:
                return [cls(event, fields=[])]
            else:
                fields = set(fields)
                default_field_sets = [
                    {'comm', 'pid'},
                    {'cpu'},
                ]
                return [
                    cls(event, fields=field_set)
                    for field_set in default_field_sets
                    if fields > field_set
                ]

class Card:
    def __init__(self, suit, val):
        self.suit = suit
        self.value = val
    def __str__(self):
        return "{} of {}".format(self.value, self.suit)
