        self.reset_parameters()
    def reset_parameters(self):
        init_range = math.sqrt(6.0 / (self.in_features + self.out_features))
        self.weight.data.uniform_(-init_range, init_range)
        if self.bias is not None:
            self.bias.data.uniform_(-init_range, init_range)
    def forward(self, x, adj):
        support = self.sparse_mm(x, self.weight)
        output = self.sparse_mm(adj, support)
        if self.bias is not None:
            return output + self.bias
        else:
            return output
    def __repr__(self):
        return self.__class__.__name__ + ' (' \
               + str(self.in_features) + ' -> ' \
               + str(self.out_features) + ')'

class NetworkingEnvironment(Environment, ABC):
    def __init__(
        self,
        *,
        ip: str = "localhost",
        port: int = 6969,
        connect_to_running: bool = False,
        on_connected_callback: callable = None,
        on_disconnected_callback: callable = None,
        on_timeout_callback: callable = None,
        on_reconnected_callback: callable = None,
        retries: int = 10,
        connect_try_interval: float = 0.1,
        **kwargs,
    ):
        super().__init__(**kwargs)
        self._ip = ip
        self._port = port
        self._connect_to_running = connect_to_running
        self._external_on_connected_callback = on_connected_callback
        self._external_on_disconnected_callback = on_disconnected_callback
        self._external_on_timeout_callback = on_timeout_callback
        self._external_on_reconnected_callback = on_reconnected_callback
        self._retries = retries
        self._connect_try_interval = connect_try_interval
    def __next__(self) -> EnvironmentSnapshot:
        if not self._is_connected_to_server:
            raise StopIteration
        return self.react()
    def _setup_connection(self, auto_describe: bool = True, writer=logging.info):
        connect_tries = range(self._retries)
        self._message_server = MessageClient(
            self._ip,
            self._port,
            on_timeout_callback=self.__on_timeout_callback__,
            on_connected_callback=self.__on_connected_callback__,
            on_disconnected_callback=self.__on_disconnected_callback__,
            on_reconnected_callback=self.__on_reconnected_callback__,
            writer=writer,
        )
        if auto_describe:
            while self.description is None:
                self.describe()
                time.sleep(self._connect_try_interval)
                writer(
                    f"Connecting, please make sure that the ip {self._ip} "
                    f"and port {self._port} "
                    f"are correct"
                )
                n = next(connect_tries)
                if n >= self._retries:
                    raise ConnectionError
            self._is_connected_to_server = True
        else:
            self._is_connected_to_server = True
    @message_client_event(event=ClientEventsEnum.connected)
    def __on_connected_callback__(self):
        if self._external_on_connected_callback:
            self._external_on_connected_callback()
    @message_client_event(event=ClientEventsEnum.disconnected)
    def __on_disconnected_callback__(self):
        self._is_connected_to_server = False
        if self._external_on_disconnected_callback:
            self._external_on_disconnected_callback()
    @message_client_event(event=ClientEventsEnum.timeout)
    def __on_timeout_callback__(self):
        if self._external_on_timeout_callback:
            self._external_on_timeout_callback()
    @message_client_event(event=ClientEventsEnum.reconnected)
    def __on_reconnected_callback__(self):
        if self._external_on_reconnected_callback:
            self._external_on_reconnected_callback()
    @property
    def is_connected(self):
        return self._is_connected_to_server
    @abstractmethod
    def _close(self, *args, **kwargs):
        raise NotImplementedError
    def __enter__(self):
        self.reset()
        return self
    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()
    def close(self, *args, **kwargs):
        self._message_server.teardown()
        return self._close(*args, **kwargs)
    def __repr__(self):
        return (
            f"<NetworkingEnvironment>\n"
            f"  <IsConnected>{self.is_connected}</IsConnected>\n"
            f"</NetworkingEnvironment>"
        )

class FITS_record:
    def __init__(
        self, input, row=0, start=None, end=None, step=None, base=None, **kwargs
    ):
        self.array = input
        self.row = row
        if base:
            width = len(base)
        else:
            width = self.array._nfields
        s = slice(start, end, step).indices(width)
        self.start, self.end, self.step = s
        self.base = base
    def __getitem__(self, key):
        if isinstance(key, str):
            indx = _get_index(self.array.names, key)
            if indx < self.start or indx > self.end - 1:
                raise KeyError(f"Key '{key}' does not exist.")
        elif isinstance(key, slice):
            return type(self)(self.array, self.row, key.start, key.stop, key.step, self)
        else:
            indx = self._get_index(key)
            if indx > self.array._nfields - 1:
                raise IndexError("Index out of bounds")
        return self.array.field(indx)[self.row]
    def __setitem__(self, key, value):
        if isinstance(key, str):
            indx = _get_index(self.array.names, key)
            if indx < self.start or indx > self.end - 1:
                raise KeyError(f"Key '{key}' does not exist.")
        elif isinstance(key, slice):
            for indx in range(slice.start, slice.stop, slice.step):
                indx = self._get_indx(indx)
                self.array.field(indx)[self.row] = value
        else:
            indx = self._get_index(key)
            if indx > self.array._nfields - 1:
                raise IndexError("Index out of bounds")
        self.array.field(indx)[self.row] = value
    def __len__(self):
        return len(range(self.start, self.end, self.step))
    def __repr__(self):
        outlist = []
        for idx in range(len(self)):
            outlist.append(repr(self[idx]))
        return f"({', '.join(outlist)})"
    def field(self, field):
        return self.__getitem__(field)
    def setfield(self, field, value):
        self.__setitem__(field, value)
    @lazyproperty
    def _bases(self):
        bases = [weakref.proxy(self)]
        base = self.base
        while base:
            bases.append(base)
            base = base.base
        return bases
    def _get_index(self, indx):
        indices = np.ogrid[: self.array._nfields]
        for base in reversed(self._bases):
            if base.step < 1:
                s = slice(base.start, None, base.step)
            else:
                s = slice(base.start, base.end, base.step)
            indices = indices[s]
        return indices[indx]

class Calculator:
    def __init__(self, init_value=0.0, valid_number_of_atr=10):
        self.value = init_value
        self.valid_number_of_atr = valid_number_of_atr
    def __setattr__(self, key, value):
        if not hasattr(self, 'valid_number_of_atr') or len(self.__dict__) < self.valid_number_of_atr:
            self.__dict__[key] = value
    def __add__(self, component):
        if isinstance(component, Calculator):
            value = component.value
        else:
            value = component
        return Calculator(self.value + value)
    def __mul__(self, component):
        if isinstance(component, Calculator):
            value = component.value
        else:
            value = component
        return Calculator(self.value * value)
    def __pow__(self, component):
        if isinstance(component, Calculator):
            value = component.value
        else:
            value = component
        if self.value < 0 and not check_if_int(value):
            return Calculator(0, True)
        else:
            return Calculator(self.value ** value)
    def __truediv__(self, component):
        if isinstance(component, Calculator):
            value = component.value
        else:
            value = component
        return Calculator(self.value / value)
    def __sub__(self, component):
        if isinstance(component, Calculator):
            value = component.value
        else:
            value = component
        return Calculator(self.value - value)
    def __repr__(self):
        return self.__dict__
    def __str__(self):
        return str(self.__dict__)
    def root(self):
        self.value = sqrt(self.value)
        return self

