class Move:
    rankToRows = {"1": 7, "2": 6, "3": 5, "4": 4,
                  "5": 3, "6": 2, "7": 1, "8": 0}
    rowsToRanks = {v: k for k, v in rankToRows.items()}
    filesToCols = {"a": 0, "b": 1, "c": 2, "d": 3,
                   "e": 4, "f": 5, "g": 6, "h": 7}
    colsToFiles = {v: k for k, v in filesToCols.items()}
    def __init__(self, startSq, endSq, board):
        self.startRow = startSq[0]
        self.startCol = startSq[1]
        self.endRow = endSq[0]
        self.endCol = endSq[1]
        self.pieceMove = board[self.startRow][self.startCol]
        self.pieceCaptured = board[self.endRow][self.endCol]
        self.moveID = self.startRow * 1000 + self.startCol * 100 + self.endRow * 10 + self.endCol
    def __eq__(self, other):
        if isinstance(other, Move):
            return self.moveID == other.moveID
        return False
    def getChessNotation(self):
        return self.getRankFile(self.startRow, self.startCol) + self.getRankFile(self.endRow, self.endCol)
    def getRankFile(self, r, c):
        return self.colsToFiles[c] + self.rowsToRanks[r]

class CardGraphicsItem(QtSvg.QGraphicsSvgItem):
    def __init__(self, name, ind, svgFile, player=0, faceDown=False):
        super(CardGraphicsItem, self).__init__(svgFile)
        self.name = name        
        self.ind = ind 
        self.svgFile = svgFile 
        self.player = player 
        self.faceDown = faceDown 
        self.anim = QPropertyAnimation(self, 'pos') 
        self.setAcceptHoverEvents(True) 
    def getSuit(self):
        return self.name.split("_")[0]
    def getRank(self):    
        return self.name.split("_")[1]
    def getValue(self):        
        if self.getSuit()=='j':
            return 99
        rank = self.getRank()
        if rank == 'A':
            value = 14
        elif rank == 'K':
            value = 13
        elif rank == 'Q':
            value = 12            
        elif rank == 'J':
            value = 11
        else:
            value = int(rank)        
        return value            
    def hoverEnterEvent(self, event):
        effect = QGraphicsDropShadowEffect(self)
        effect.setBlurRadius(15)
        effect.setColor(Qt.red)        
        effect.setOffset(QPointF(-5,0))
        self.setGraphicsEffect(effect)        
    def hoverLeaveEvent(self, event):
        self.setGraphicsEffect(None) 
    def __repr__(self):                
        return '<CardGraphicsItem: %s>' % self.name

