class Set:
    def __init__(self, elements=None):
        self.hash_table = HashTable()
        if elements:
            for element in elements:
                self.add(element)  
    def __str__(self):
        items = ['({!r})'.format(item) for item in self.hash_table.keys()]
        return ''.join(items)
    def __iter__(self):
        for item in self.hash_table.keys():
            yield item
    def __repr__(self):
        return '({!r})'.format(self.hash_table.keys())
    def size(self):
        return self.hash_table.size
    def contains(self, element):
        return self.hash_table.contains(element)
    def add(self, element):
        self.hash_table.set(element, None)  
    def remove(self, element):
        if self.hash_table.contains(element):  
            self.hash_table.delete(element)  
        else:
            raise KeyError('Element not found:'.format(element))
    def union(self, other_set):
        union_set = Set(self)  
        for item in other_set:  
            union_set.add(item)  
        return union_set
    def intersection(self, other_set):
        intersection_set = Set()  
        if other_set.size() >= self.size():  
            bigger_set = other_set  
            smaller_set = self  
        else:
            bigger_set = self  
            smaller_set = other_set  
        for item in smaller_set:  
            if bigger_set.contains(item):  
                intersection_set.add(item)  
        return intersection_set
    def symmetric_difference(self, other_set):
        union_set = self.union(other_set)  
        inter_set = self.intersection(other_set)  
        for element in inter_set:  
            if union_set.contains(element):  
                union_set.remove(element)  
        return union_set
    def difference(self, other_set):
        new_set = Set()
        for element in self:  
            if other_set.contains(element) is False:  
                new_set.add(element)  
        return new_set
    def is_subset(self, other_set):
        if other_set.size() > self.size():  
            return False
        if other_set.size() == 0:  
            return True
        counter = 0
        for element in other_set:  
            if self.contains(element):  
                counter += 1
        return counter == other_set.size()

class MyStack:
    def __init__(self, *args):
        self.stack = []
        self.stack.extend(args)
    def push(self, item):
        self.stack.append(item)
    def pop(self):
        if len(self.stack) == 0:
            return None
        return self.stack.pop() 
    def __repr__(self):
        return 'MyStack(' + repr(self.stack)  + ')'
    def __str__(self):
        return str(self.stack)
    def __iter__(self):
        return iter(self.stack)
    def __getitem__(self, KEY):
        return self.stack[KEY]

