            setattr(self, name, default_value)
        if allowed is not None:
            value = getattr(self, name)
            if callable(allowed):
                ok = allowed(value)
            else:
                ok = value in allowed
            if not ok:
                raise ValueError(
                    f
                )

class RBF(object):
  _INSTANCES = []
  @property
  def expr(self):
    return self._expr
  @property
  def tol(self):
    return self._tol
  @property
  def limits(self):
    return self._limits
  def __init__(self, expr, tol=None, limits=None):
    if not issubclass(type(expr), sympy.Expr):
      raise ValueError(
        '`expr` must be a sympy expression')
    other_symbols = expr.free_symbols.difference({_R, _EPS})
    if len(other_symbols) != 0:
      raise ValueError(
        '`expr` cannot contain any symbols other than `r` and `eps`')
    if not expr.has(_R):
      raise ValueError(
        '`expr` must contain the symbol `r`')
    if not expr.has(_EPS):
      expr = expr.subs(_R, _EPS*_R)
    self._expr = expr
    if tol is not None:
      tol = sympy.sympify(tol)
      other_symbols = tol.free_symbols.difference({_EPS})
      if len(other_symbols) != 0:
        raise ValueError(
          '`tol` cannot contain any symbols other than `eps`')
      mapping = {n : sympy.Float(n, 50) for n in tol.atoms(sympy.Number)}
      tol = tol.xreplace(mapping)
    self._tol = tol
    if limits is None:
      limits = {}
    self._limits = limits
    self._cache = {}
    RBF._INSTANCES += [weakref.ref(self)]
  def __call__(self, x, c, eps=1.0, diff=None):
    x = np.asarray(x, dtype=float)
    assert_shape(x, (None, None), 'x')
    c = np.asarray(c, dtype=float)
    assert_shape(c, (None, x.shape[1]), 'c')
    if np.isscalar(eps):
      eps = np.full(c.shape[0], eps, dtype=float)
    else:  
      eps = np.asarray(eps, dtype=float)
      assert_shape(eps, (c.shape[0],), 'eps')
    if diff is None:
      diff = (0,)*x.shape[1]
    else:
      diff = tuple(diff)
      assert_shape(diff, (x.shape[1],), 'diff')
    if diff not in self._cache:
      self._add_diff_to_cache(diff)
    x = x.T[:, :, None] 
    c = c.T[:, None, :]
    args = (tuple(x) + tuple(c) + (eps,))
    out = self._cache[diff](*args)
    return out
  def __repr__(self):
    out = '<RBF : %s>' % str(self.expr)
    return out
  def _add_diff_to_cache(self, diff):
    logger.debug('Creating a numerical function for the RBF %s with '
                 'the derivative %s ...' % (self,str(diff)))
    dim = len(diff)
    c_sym = sympy.symbols('c:%s' % dim)
    x_sym = sympy.symbols('x:%s' % dim)    
    r_sym = sympy.sqrt(sum((xi-ci)**2 for xi, ci in zip(x_sym, c_sym)))
    expr = self.expr.subs(_R, r_sym)            
    for xi, order in zip(x_sym, diff):
      if order == 0:
        continue
      expr = expr.diff(*(xi,)*order)
    if self.tol is not None:
      if diff in self.limits:
        lim = self.limits[diff]
      else: 
        logger.debug('Approximating the value at the RBF center ...')
        subs_list  = [(x_sym[0], self.tol + c_sym[0])]
        subs_list += zip(x_sym[1:], c_sym[1:])
        a = expr.subs(subs_list) 
        b = expr.diff(x_sym[0]).subs(subs_list)
        lim = a - self.tol*b
        lim = sympy.cancel(lim) 
        mapping = {n : float(n) for n in lim.atoms(sympy.Number)}
        lim = sympy.sympify(lim.xreplace(mapping))
        logger.debug('Approximate value at the RBF center: %s' % lim)
      expr = sympy.Piecewise((lim, r_sym < self.tol), (expr, True)) 
    if _SYMBOLIC_TO_NUMERIC_METHOD == 'ufuncify':      
      func = ufuncify(x_sym + c_sym + (_EPS,), expr, backend='numpy')
    elif _SYMBOLIC_TO_NUMERIC_METHOD == 'lambdify':
      func = lambdify(x_sym + c_sym + (_EPS,), expr, modules=['numpy'])
    else:
      raise ValueError()          
    self._cache[diff] = func
    logger.debug('The numeric function has been created and cached')
  def clear_cache(self):
    self._cache = {}

class HttpRequest:
    _encoding = None
    _upload_handlers = []
    def __init__(self):
        self.GET = QueryDict(mutable=True)
        self.POST = QueryDict(mutable=True)
        self.COOKIES = {}
        self.META = {}
        self.FILES = MultiValueDict()
        self.path = ''
        self.path_info = ''
        self.method = None
        self.resolver_match = None
        self.content_type = None
        self.content_params = None
    def __repr__(self):
        if self.method is None or not self.get_full_path():
            return '<%s>' % self.__class__.__name__
        return '<%s: %s %r>' % (self.__class__.__name__, self.method, self.get_full_path())
    @cached_property
    def headers(self):
        return HttpHeaders(self.META)
    def _get_raw_host(self):
        if settings.USE_X_FORWARDED_HOST and (
                'HTTP_X_FORWARDED_HOST' in self.META):
            host = self.META['HTTP_X_FORWARDED_HOST']
        elif 'HTTP_HOST' in self.META:
            host = self.META['HTTP_HOST']
        else:
            host = self.META['SERVER_NAME']
            server_port = self.get_port()
            if server_port != ('443' if self.is_secure() else '80'):
                host = '%s:%s' % (host, server_port)
        return host
    def get_host(self):
        host = self._get_raw_host()
        allowed_hosts = settings.ALLOWED_HOSTS
        if settings.DEBUG and not allowed_hosts:
            allowed_hosts = ['localhost', '127.0.0.1', '[::1]']
        domain, port = split_domain_port(host)
        if domain and validate_host(domain, allowed_hosts):
            return host
        else:
            msg = "Invalid HTTP_HOST header: %r." % host
            if domain:
                msg += " You may need to add %r to ALLOWED_HOSTS." % domain
            else:
                msg += " The domain name provided is not valid according to RFC 1034/1035."
            raise DisallowedHost(msg)
    def get_port(self):
        if settings.USE_X_FORWARDED_PORT and 'HTTP_X_FORWARDED_PORT' in self.META:
            port = self.META['HTTP_X_FORWARDED_PORT']
        else:
            port = self.META['SERVER_PORT']
        return str(port)
    def get_full_path(self, force_append_slash=False):
        return self._get_full_path(self.path, force_append_slash)
    def get_full_path_info(self, force_append_slash=False):
        return self._get_full_path(self.path_info, force_append_slash)
    def _get_full_path(self, path, force_append_slash):
        return '%s%s%s' % (
            escape_uri_path(path),
            '/' if force_append_slash and not path.endswith('/') else '',
            ('?' + iri_to_uri(self.META.get('QUERY_STRING', ''))) if self.META.get('QUERY_STRING', '') else ''
        )
    def get_signed_cookie(self, key, default=RAISE_ERROR, salt='', max_age=None):
        try:
            cookie_value = self.COOKIES[key]
        except KeyError:
            if default is not RAISE_ERROR:
                return default
            else:
                raise
        try:
            value = signing.get_cookie_signer(salt=key + salt).unsign(
                cookie_value, max_age=max_age)
        except signing.BadSignature:
            if default is not RAISE_ERROR:
                return default
            else:
                raise
        return value
    def get_raw_uri(self):
        return '{scheme}://{host}{path}'.format(
            scheme=self.scheme,
            host=self._get_raw_host(),
            path=self.get_full_path(),
        )
    def build_absolute_uri(self, location=None):
        if location is None:
            location = '//%s' % self.get_full_path()
        bits = urlsplit(location)
        if not (bits.scheme and bits.netloc):
            if (bits.path.startswith('/') and not bits.scheme and not bits.netloc and
                    '/./' not in bits.path and '/../' not in bits.path):
                if location.startswith('//'):
                    location = location[2:]
                location = self._current_scheme_host + location
            else:
                location = urljoin(self._current_scheme_host + self.path, location)
        return iri_to_uri(location)
    @cached_property
    def _current_scheme_host(self):
        return '{}://{}'.format(self.scheme, self.get_host())
    def _get_scheme(self):
        return 'http'
    @property
    def scheme(self):
        if settings.SECURE_PROXY_SSL_HEADER:
            try:
                header, secure_value = settings.SECURE_PROXY_SSL_HEADER
            except ValueError:
                raise ImproperlyConfigured(
                    'The SECURE_PROXY_SSL_HEADER setting must be a tuple containing two values.'
                )
            header_value = self.META.get(header)
            if header_value is not None:
                return 'https' if header_value == secure_value else 'http'
        return self._get_scheme()
    def is_secure(self):
        return self.scheme == 'https'
    def is_ajax(self):
        return self.META.get('HTTP_X_REQUESTED_WITH') == 'XMLHttpRequest'
    @property
    def encoding(self):
        return self._encoding
    @encoding.setter
    def encoding(self, val):
        self._encoding = val
        if hasattr(self, 'GET'):
            del self.GET
        if hasattr(self, '_post'):
            del self._post
    def _initialize_handlers(self):
        self._upload_handlers = [uploadhandler.load_handler(handler, self)
                                 for handler in settings.FILE_UPLOAD_HANDLERS]
    @property
    def upload_handlers(self):
        if not self._upload_handlers:
            self._initialize_handlers()
        return self._upload_handlers
    @upload_handlers.setter
    def upload_handlers(self, upload_handlers):
        if hasattr(self, '_files'):
            raise AttributeError("You cannot set the upload handlers after the upload has been processed.")
        self._upload_handlers = upload_handlers
    def parse_file_upload(self, META, post_data):
        self.upload_handlers = ImmutableList(
            self.upload_handlers,
            warning="You cannot alter upload handlers after the upload has been processed."
        )
        parser = MultiPartParser(META, post_data, self.upload_handlers, self.encoding)
        return parser.parse()
    @property
    def body(self):
        if not hasattr(self, '_body'):
            if self._read_started:
                raise RawPostDataException("You cannot access body after reading from request's data stream")
            if (settings.DATA_UPLOAD_MAX_MEMORY_SIZE is not None and
                    int(self.META.get('CONTENT_LENGTH') or 0) > settings.DATA_UPLOAD_MAX_MEMORY_SIZE):
                raise RequestDataTooBig('Request body exceeded settings.DATA_UPLOAD_MAX_MEMORY_SIZE.')
            try:
                self._body = self.read()
            except IOError as e:
                raise UnreadablePostError(*e.args) from e
            self._stream = BytesIO(self._body)
        return self._body
    def _mark_post_parse_error(self):
        self._post = QueryDict()
        self._files = MultiValueDict()
    def _load_post_and_files(self):
        if self.method != 'POST':
            self._post, self._files = QueryDict(encoding=self._encoding), MultiValueDict()
            return
        if self._read_started and not hasattr(self, '_body'):
            self._mark_post_parse_error()
            return
        if self.content_type == 'multipart/form-data':
            if hasattr(self, '_body'):
                data = BytesIO(self._body)
            else:
                data = self
            try:
                self._post, self._files = self.parse_file_upload(self.META, data)
            except MultiPartParserError:
                self._mark_post_parse_error()
                raise
        elif self.content_type == 'application/x-www-form-urlencoded':
            self._post, self._files = QueryDict(self.body, encoding=self._encoding), MultiValueDict()
        else:
            self._post, self._files = QueryDict(encoding=self._encoding), MultiValueDict()
    def close(self):
        if hasattr(self, '_files'):
            for f in chain.from_iterable(list_[1] for list_ in self._files.lists()):
                f.close()
    def read(self, *args, **kwargs):
        self._read_started = True
        try:
            return self._stream.read(*args, **kwargs)
        except IOError as e:
            raise UnreadablePostError(*e.args) from e
    def readline(self, *args, **kwargs):
        self._read_started = True
        try:
            return self._stream.readline(*args, **kwargs)
        except IOError as e:
            raise UnreadablePostError(*e.args) from e
    def __iter__(self):
        return iter(self.readline, b'')
    def xreadlines(self):
        warnings.warn(
            'HttpRequest.xreadlines() is deprecated in favor of iterating the '
            'request.', RemovedInDjango30Warning, stacklevel=2,
        )
        yield from self
    def readlines(self):
        return list(self)

