class Build(object):
    def __init__(self, api):
        super(Build, self).__init__()
        self._api = api
        self._log = logging.getLogger(__name__)
    def __eq__(self, obj):
        if not isinstance(obj, Build):
            return False
        if obj.id != self.id:
            return False
        return True
    def __ne__(self, obj):
        if not isinstance(obj, Build):
            return True
        if obj.id != self.id:
            return True
        return False
    def __hash__(self):
        return hash(self.id)
    @property
    def number(self):
        data = self._api.get_api_data()
        return data['number']
    @property
    def start_time(self):
        data = self._api.get_api_data()
        time_in_seconds = data['timestamp'] * 0.001
        return datetime.fromtimestamp(time_in_seconds)
    @property
    def is_building(self):
        data = self._api.get_api_data()
        return data['building']
    @property
    def console_output(self):
        return self._api.get_text("/consoleText")
    @property
    def result(self):
        data = self._api.get_api_data()
        return data['result']
    @property
    def changeset(self):
        data = self._api.get_api_data()
        return Changeset(self._api, data['changeSet'])
    @property
    def description(self):
        data = self._api.get_api_data()
        retval = data["description"]
        if retval is None:
            return ""
        return retval
    @property
    def id(self):  
        data = self._api.get_api_data()
        return data["id"]
    @property
    def artifact_urls(self):
        data = self._api.get_api_data()
        artifacts_node = data['artifacts']
        retval = []
        for node in artifacts_node:
            url = urllib_parse.urljoin(self._api.url, "artifact/" + node['fileName'])
            retval.append(url)
        return retval
    @property
    def duration(self):
        data = self._api.get_api_data()
        return data['duration']
    @property
    def estimated_duration(self):
        data = self._api.get_api_data()
        return data['estimatedDuration']
    def abort(self):
        self._api.post(self._api.url + "stop")
    def kill(self):
        self._api.post(self._api.url + "kill")

class HttpResponse(HttpResponseBase):
    streaming = False
    def __init__(self, content=b'', *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.content = content
    def __repr__(self):
        return '<%(cls)s status_code=%(status_code)d%(content_type)s>' % {
            'cls': self.__class__.__name__,
            'status_code': self.status_code,
            'content_type': self._content_type_for_repr,
        }
    def serialize(self):
        return self.serialize_headers() + b'\r\n\r\n' + self.content
    __bytes__ = serialize
    @property
    def content(self):
        return b''.join(self._container)
    @content.setter
    def content(self, value):
        if hasattr(value, '__iter__') and not isinstance(value, (bytes, str)):
            content = b''.join(self.make_bytes(chunk) for chunk in value)
            if hasattr(value, 'close'):
                try:
                    value.close()
                except Exception:
                    pass
        else:
            content = self.make_bytes(value)
        self._container = [content]
    def __iter__(self):
        return iter(self._container)
    def write(self, content):
        self._container.append(self.make_bytes(content))
    def tell(self):
        return len(self.content)
    def getvalue(self):
        return self.content
    def writable(self):
        return True
    def writelines(self, lines):
        for line in lines:
            self.write(line)

class HttpResponseRedirectBase(HttpResponse):
    allowed_schemes = ['http', 'https', 'ftp']
    def __init__(self, redirect_to, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self['Location'] = iri_to_uri(redirect_to)
        parsed = urlparse(str(redirect_to))
        if parsed.scheme and parsed.scheme not in self.allowed_schemes:
            raise DisallowedRedirect("Unsafe redirect to URL with protocol '%s'" % parsed.scheme)
    url = property(lambda self: self['Location'])
    def __repr__(self):
        return '<%(cls)s status_code=%(status_code)d%(content_type)s, url="%(url)s">' % {
            'cls': self.__class__.__name__,
            'status_code': self.status_code,
            'content_type': self._content_type_for_repr,
            'url': self.url,
        }

class HttpResponseNotAllowed(HttpResponse):
