class LenWrapperStream(object):
    def __init__(self, stream):
        self.stream = stream
    def read(self, n=-1):
        return self.stream.read(n)
    def __iter__(self):
        return self.stream
    def seek(self, pos, mode=0):
        return self.stream.seek(pos, mode)
    def tell(self):
        return self.stream.tell()
    def __len__(self):
        o = self.stream
        if hasattr(o, '__len__'):
            return len(o)
        if hasattr(o, 'len'):
            return o.len
        if hasattr(o, 'fileno'):
            try:
                return os.fstat(o.fileno()).st_size
            except IOError:
                pass  
        start_pos = o.tell()
        o.seek(0, os.SEEK_END)
        size = o.tell() - start_pos
        o.seek(start_pos)
        return size
    def __eq__(self, other):
        if self.stream == other:
            return True
        if isinstance(other, LenWrapperStream) and other.stream == self.stream:
            return True
    @property
    def closed(self):
        return self.stream.closed
    def __repr__(self):
        return repr(self.stream)

class Montage:
    def __init__(self, dataset_parent, portal_id, name, json_pairs):
        self.parent = dataset_parent
        self.portal_id = portal_id
        self.name = name
        self.indexed_pairs = self._json_pairs_to_pairs(json_pairs)
        self.pairs = [(channel.raw_label, reference.raw_label if reference else None) for channel, reference in self.indexed_pairs]
        self._matrix = self._calculate_matrix()
        self._montage_channels_to_info = {}
    def _label_to_half_montage_channel(self, raw_label):
        try:
            chan_index = self.parent.ch_labels.index(raw_label)
            return HalfMontageChannel(raw_label, chan_index)
        except ValueError:
            return HalfMontageChannel(raw_label, None)
    def _json_pair_to_pair(self, json_pair):
        channel_half = self._label_to_half_montage_channel(
            json_pair['@channel'])
        reference_label = json_pair.get('@refChannel')
        reference_half = self._label_to_half_montage_channel(
            reference_label) if reference_label else None
        return (channel_half, reference_half)
    def _json_pairs_to_pairs(self, json_pairs):
        if isinstance(json_pairs, dict):
            return [self._json_pair_to_pair(json_pairs)]
        return [self._json_pair_to_pair(json_pair) for json_pair in json_pairs]
    def _calculate_matrix(self):
        matrix_columns = []
        for pair_channel, pair_ref in self.indexed_pairs:
            column = [0] * len(self.parent.ch_labels)
            if pair_channel.raw_index is not None:
                column[pair_channel.raw_index] = 1
            if pair_ref and pair_ref.raw_index is not None:
                column[pair_ref.raw_index] = -1
            matrix_columns.append(column)
        return np.column_stack(matrix_columns)
    @classmethod
    def create_montage_map(cls, dataset, json_montages):
        montages = {}
        for json_montage in json_montages:
            montage = cls(dataset,
                          json_montage['@serverId'],
                          json_montage['@name'],
                          json_montage['montagePairs']['montagePair'])
            if montage.size() > 0:
                same_name = montages.get(montage.name)
                if same_name:
                    same_name.append(montage)
                else:
                    montages[montage.name] = [montage]
        return montages
    def size(self):
        return np.count_nonzero(np.count_nonzero(self._matrix, axis=0))
    def get_montage_info(self, montage_channels):
        key = tuple(montage_channels)
        cached_info = self._montage_channels_to_info.get(key)
        if cached_info:
            return cached_info
        requested_matrix = self._matrix[:, montage_channels]
        nonzero_channel_indices = requested_matrix.nonzero()[0]
        uniq_sorted_indices = list(set(nonzero_channel_indices))
        uniq_sorted_indices.sort()
        reduced_matrix = requested_matrix[~np.all(
            requested_matrix == 0, axis=1), :]
        computed_info = (uniq_sorted_indices, reduced_matrix)
        self._montage_channels_to_info[key] = computed_info
        return computed_info
    def __repr__(self):
        return "montage(" + self.name + "): " + str(self.pairs)

class Dataset:
    snap_id = ""
    ts_details = {}  
    ts_details_by_id = {}  
    ch_labels = []  
    ts_array = []   
    _SERVER_GAP_VALUE = np.iinfo(np.int32).min
    def __init__(self, ts_details, snapshot_id, parent, json_montages=None):
        self.session = parent
        self.snap_id = snapshot_id
        xml_details = ts_details.findall('details')[0]
        for dt in xml_details.findall('detail'):
            name = dt.findall('channelLabel')[0].text
            portal_id = dt.findall('revisionId')[0].text
            details = TimeSeriesDetails(portal_id,
                                        dt.findall('name')[0].text,
                                        name,
                                        dt.findall('duration')[0].text,
                                        dt.findall('minSample')[0].text,
                                        dt.findall('maxSample')[0].text,
                                        dt.findall('numberOfSamples')[0].text,
                                        dt.findall('startTime')[0].text,
                                        dt.findall('voltageConversionFactor')[0].text,)
            self.ch_labels.append(name)
            self.ts_array.append(dt)
            self.ts_details[name] = details
            self.ts_details_by_id[portal_id] = details
        self.montages = Montage.create_montage_map(self, json_montages if json_montages else [])
        self.current_montage = None
    def __repr__(self):
        return "Dataset with: " + str(len(self.ch_labels)) + " channels."
    def __str__(self):
        return "Dataset with: " + str(len(self.ch_labels)) + " channels."
    def get_channel_labels(self):
        return self.ch_labels
    def get_channel_indices(self, list_of_labels):
        if self.current_montage is None:
            return [self.ch_labels.index(x) for x in list_of_labels]
        return [self.current_montage.pairs.index(x) for x in list_of_labels]
    def get_time_series_details(self, label):
        return self.ts_details[label]
    def set_current_montage(self, montage_name, portal_id=None):
        if montage_name is None:
            self.current_montage = None
            return
        montages_with_name = self.montages[montage_name]
        if len(montages_with_name) == 1:
            self.current_montage = montages_with_name[0]
        else:
            new_montage = None
            for montage in montages_with_name:
                if montage.portal_id == portal_id:
                    new_montage = montage
                    break
            if new_montage:
                self.current_montage = new_montage
            else:
                raise ValueError('Montage '
                                 + montage_name
                                 + ', id '
                                 + portal_id
                                 + ' does not exist')
    def get_current_montage(self):
        return self.current_montage
    def _get_unmontaged_data(self, start, duration, raw_channels):
        def all_same(items):
            return all(x == items[0] for x in items)
        response = self.session.api.get_data(
            self, start, duration, raw_channels)
        int_array = np.frombuffer(response.content, dtype='>i4')
        samples_per_row_array = [int(numeric_string)
                          for numeric_string in response.headers['samples-per-row'].split(',')]
        if not all_same(samples_per_row_array):
            raise IeegConnectionError(
                'Not all channels in response have equal length')
        samples_per_row = samples_per_row_array[0]
        conv_f = np.array([float(numeric_string)
                           for numeric_string in response.headers['voltage-conversion-factors-mv'].split(',')])
        int_matrix = np.reshape(
            int_array, (samples_per_row, len(raw_channels)), order='F')
        unmontaged_data = int_matrix * conv_f[np.newaxis, :]
        unmontaged_data[int_matrix == Dataset._SERVER_GAP_VALUE] = np.nan
        return unmontaged_data
    def get_data(self, start, duration, channels):
        if not self.current_montage:
            return self._get_unmontaged_data(start, duration, channels)
        raw_channels, montage_matrix = self.current_montage.get_montage_info(channels)
        raw_data = self._get_unmontaged_data(start, duration, raw_channels)
        return np.matmul(raw_data, montage_matrix)
    def get_dataframe(self, start, duration, channels):
        array = self.get_data(start, duration, channels)
        return pd.DataFrame(array, columns=[self.ch_labels[i] for i in channels])
    def get_annotation_layers(self):
        response = self.session.api.get_annotation_layers(self)
        if response.status_code != requests.codes.ok:
            print(response.text)
            raise IeegConnectionError(
                'Could not get annotation layers for dataset')
        response_body = response.json()
        counts_by_layer = response_body['countsByLayer']['countsByLayer']
        if not counts_by_layer:
            return {}
        entry = counts_by_layer['entry']
        try:
            return {entry['key']: entry['value']}
        except TypeError:
            return {e['key']: e['value'] for e in entry}
    def get_annotations(self, layer_name,
                        start_offset_usecs=None, first_result=None, max_results=None):
        response = self.session.api.get_annotations(self, layer_name,
                                                    start_offset_usecs=start_offset_usecs,
                                                    first_result=first_result,
                                                    max_results=max_results)
        if response.status_code != requests.codes.ok:
            print(response.text)
            raise IeegConnectionError(
                'Could not get annotation layer ' + layer_name)
        response_body = response.json()
        timeseries_annotations = response_body['timeseriesannotations']
        json_annotations = timeseries_annotations['annotations']['annotation']
        try:
            annotations = [Annotation(
                self,
                a['annotator'],
                a['type'],
                a.get('description', ''),
                a['layer'],
                a['startTimeUutc'],
                a['endTimeUutc'],
                portal_id=a['revId'],
                annotated_portal_ids=a['timeseriesRevIds']['timeseriesRevId'])
                for a in json_annotations]
        except TypeError:
            annotations = [Annotation(
                self,
                json_annotations['annotator'],
                json_annotations['type'],
                json_annotations.get('description', ''),
                json_annotations['layer'],
                json_annotations['startTimeUutc'],
                json_annotations['endTimeUutc'],
                portal_id=json_annotations['revId'],
                annotated_portal_ids=json_annotations['timeseriesRevIds']['timeseriesRevId'])]
        return annotations
    def add_annotations(self, annotations):
        response = self.session.api.add_annotations(self, annotations)
        if response.status_code != requests.codes.ok:
            response_body = response.text
            print(response_body)
            raise IeegConnectionError(
                'Could not add annotations')
        if self.session.mprov_listener:
            self.session.mprov_listener.on_add_annotations(annotations)
    def move_annotation_layer(self, from_layer, to_layer):
        response = self.session.api.move_annotation_layer(
            self, from_layer, to_layer)
        if response.status_code != requests.codes.ok:
            response_body = response.text
            print(response_body)
            raise IeegConnectionError(
                'Could not move annotation layer ' + from_layer + ' to ' + to_layer)
        response_body = response.json()
        moved = response_body['tsAnnotationsMoved']['moved']
        return int(moved)
    def delete_annotation_layer(self, layer):
        response = self.session.api.delete_annotation_layer(self, layer)
        if response.status_code != requests.codes.ok:
            response_body = response.text
            print(response_body)
            raise IeegConnectionError(
                'Could not delete annotation layer ' + layer)
        response_body = response.json()
        deleted = response_body['tsAnnotationsDeleted']['noDeleted']
        return int(deleted)
    @deprecated
    def getChannelLabels(self):
        return self.get_channel_labels()
    @deprecated
    def getData(self, start, duration, channels):
        return self.get_data(start, duration, channels)

class Row(BasicStorage):
    def __getitem__(self, k):
        key = str(k)
        _extra = BasicStorage.get(self, "_extra", None)
        if _extra is not None:
            v = _extra.get(key, DEFAULT)
            if v is not DEFAULT:
                return v
        try:
            return BasicStorage.__getattribute__(self, key)
        except AttributeError:
            pass
        m = REGEX_TABLE_DOT_FIELD.match(key)
        if m:
            key2 = m.group(2)
            try:
                return BasicStorage.__getitem__(self, m.group(1))[key2]
            except (KeyError, TypeError):
                pass
            try:
                return BasicStorage.__getitem__(self, key2)
            except KeyError:
                pass
        lg = BasicStorage.get(self, "__get_lazy_reference__", None)
        if callable(lg):
            v = self[key] = lg(key)
            return v
        raise KeyError(key)
    def __repr__(self):
        return "<Row %s>" % self.as_dict(custom_types=[LazySet])
    def __int__(self):
        return self.get("id")
    def __long__(self):
        return long(int(self))
    def __hash__(self):
        return id(self)
    __str__ = __repr__
    __call__ = __getitem__
    def __getattr__(self, k):
        try:
            return self.__getitem__(k)
        except KeyError:
            raise AttributeError
    def __copy__(self):
        return Row(self)
    def __eq__(self, other):
        try:
            return self.as_dict() == other.as_dict()
        except AttributeError:
            return False
    def get(self, key, default=None):
        try:
            return self.__getitem__(key)
        except (KeyError, AttributeError, TypeError):
            return default
    def as_dict(self, datetime_to_str=False, custom_types=None):
        SERIALIZABLE_TYPES = [str, int, float, bool, list, dict]
        DT_INST = (datetime.date, datetime.datetime, datetime.time)
        if PY2:
            SERIALIZABLE_TYPES += [unicode, long]
        if isinstance(custom_types, (list, tuple, set)):
            SERIALIZABLE_TYPES += custom_types
        elif custom_types:
            SERIALIZABLE_TYPES.append(custom_types)
        d = dict(self)
        for k in list(d.keys()):
            v = d[k]
            if d[k] is None:
                continue
            elif isinstance(v, Row):
                d[k] = v.as_dict()
            elif isinstance(v, Reference):
                d[k] = long(v)
            elif isinstance(v, decimal.Decimal):
                d[k] = float(v)
            elif isinstance(v, DT_INST):
                if datetime_to_str:
                    d[k] = v.isoformat().replace("T", " ")[:19]
            elif not isinstance(v, tuple(SERIALIZABLE_TYPES)):
                del d[k]
        return d
    def as_xml(self, row_name="row", colnames=None, indent="  "):
        def f(row, field, indent="  "):
            if isinstance(row, Row):
                spc = indent + "  \n"
                items = [f(row[x], x, indent + "  ") for x in row]
                return "%s<%s>\n%s\n%s</%s>" % (
                    indent,
                    field,
                    spc.join(item for item in items if item),
                    indent,
                    field,
                )
            elif not callable(row):
                if re.match(REGEX_ALPHANUMERIC, field):
                    return "%s<%s>%s</%s>" % (indent, field, row, field)
                else:
                    return '%s<extra name="%s">%s</extra>' % (indent, field, row)
            else:
                return None
        return f(self, row_name, indent=indent)
    def as_json(
        self, mode="object", default=None, colnames=None, serialize=True, **kwargs
    ):
        item = self.as_dict(**kwargs)
        if serialize:
            return serializers.json(item)
        else:
            return item

class Select(BasicStorage):
    def __init__(self, db, query, fields, attributes):
        self._db = db
        self._tablename = None  
        self._rname = self._raw_rname = self._dalname = None
        self._common_filter = None
        self._query = query
        self._correlated = attributes.pop("correlated", True)
        self._attributes = attributes
        self._qfields = list(fields)
        self._fields = SQLCallableList()
        self._virtual_fields = []
        self._virtual_methods = []
        self.virtualfields = []
        self._sql_cache = None
        self._colnames_cache = None
        fieldcheck = set()
        for item in fields:
            if isinstance(item, Field):
                checkname = item.name
                field = item.clone()
            elif isinstance(item, Expression):
                if item.op != item._dialect._as:
                    continue
                checkname = item.second
                field = Field(item.second, type=item.type)
            else:
                raise SyntaxError("Invalid field in Select")
            if db and db._ignore_field_case:
                checkname = checkname.lower()
            if checkname in fieldcheck:
                raise SyntaxError("duplicate field %s in select query" % field.name)
            fieldcheck.add(checkname)
            field.bind(self)
            self.fields.append(field.name)
            self[field.name] = field
        self.ALL = SQLALL(self)
    @property
    def fields(self):
        return self._fields
    def update(self, *args, **kwargs):
        raise RuntimeError("update() method not supported")
    def __getitem__(self, key):
        try:
            return getattr(self, key)
        except AttributeError:
            raise KeyError(key)
    def __setitem__(self, key, value):
        self.__dict__[str(key)] = value
    def __call__(self):
        adapter = self._db._adapter
        colnames, sql = self._compile()
        cache = self._attributes.get("cache", None)
        if cache and self._attributes.get("cacheable", False):
            return adapter._cached_select(
                cache, sql, self._fields, self._attributes, colnames
            )
        return adapter._select_aux(sql, self._qfields, self._attributes, colnames)
    def __setattr__(self, key, value):
        if key[:1] != "_" and key in self:
            raise SyntaxError("Object exists and cannot be redefined: %s" % key)
        self[key] = value
    def __iter__(self):
        for fieldname in self.fields:
            yield self[fieldname]
    def __repr__(self):
        return "<Select (%s)>" % ", ".join(map(str, self._qfields))
    def __str__(self):
        return self._compile(with_alias=(self._tablename is not None))[1]
    def with_alias(self, alias):
        other = copy.copy(self)
        other["ALL"] = SQLALL(other)
        other["_tablename"] = alias
        for fieldname in other.fields:
            tmp = self[fieldname].clone()
            tmp.bind(other)
            other[fieldname] = tmp
        return other
    def on(self, query):
        if not self._tablename:
            raise SyntaxError("Subselect must be aliased for use in a JOIN")
        return Expression(self._db, self._db._adapter.dialect.on, self, query)
    def _compile(self, outer_scoped=[], with_alias=False):
        if not self._correlated:
            outer_scoped = []
        if outer_scoped or not self._sql_cache:
            adapter = self._db._adapter
            attributes = self._attributes.copy()
            attributes["outer_scoped"] = outer_scoped
            colnames, sql = adapter._select_wcols(
                self._query, self._qfields, **attributes
            )
            if not outer_scoped:
                self._colnames_cache, self._sql_cache = colnames, sql
        else:
            colnames, sql = self._colnames_cache, self._sql_cache
        if with_alias and self._tablename is not None:
            sql = "(%s)" % sql[:-1]
            sql = self._db._adapter.dialect.alias(sql, self._tablename)
        return colnames, sql
    def query_name(self, outer_scoped=[]):
        if self._tablename is None:
            raise SyntaxError("Subselect must be aliased for use in a JOIN")
        colnames, sql = self._compile(outer_scoped, True)
        return (sql,)
    @property
    def sql_shortref(self):
        if self._tablename is None:
            raise SyntaxError("Subselect must be aliased for use in a JOIN")
        return self._db._adapter.dialect.quote(self._tablename)
    def _filter_fields(self, record, id=False):
        return dict(
            [
                (k, v)
                for (k, v) in iteritems(record)
                if k in self.fields and (self[k].type != "id" or id)
            ]
        )

class Expression(object):
    _dialect_expressions_ = {}
    def __new__(cls, *args, **kwargs):
        for name, wrapper in iteritems(cls._dialect_expressions_):
            setattr(cls, name, _expression_wrap(wrapper))
        new_cls = super(Expression, cls).__new__(cls)
        return new_cls
    def __init__(self, db, op, first=None, second=None, type=None, **optional_args):
        self.db = db
        self.op = op
        self.first = first
        self.second = second
        self._table = getattr(first, "_table", None)
        if not type and first and hasattr(first, "type"):
            self.type = first.type
        else:
            self.type = type
        if isinstance(self.type, str):
            self._itype = REGEX_TYPE.match(self.type).group(0)
        else:
            self._itype = None
        self.optional_args = optional_args
    @property
    def _dialect(self):
        return self.db._adapter.dialect
    def sum(self):
        return Expression(self.db, self._dialect.aggregate, self, "SUM", self.type)
    def max(self):
        return Expression(self.db, self._dialect.aggregate, self, "MAX", self.type)
    def min(self):
        return Expression(self.db, self._dialect.aggregate, self, "MIN", self.type)
    def len(self):
        return Expression(self.db, self._dialect.length, self, None, "integer")
    def avg(self):
        return Expression(self.db, self._dialect.aggregate, self, "AVG", self.type)
    def abs(self):
        return Expression(self.db, self._dialect.aggregate, self, "ABS", self.type)
    def cast(self, cast_as, **kwargs):
        return Expression(
            self.db,
            self._dialect.cast,
            self,
            self._dialect.types[cast_as] % kwargs,
            cast_as,
        )
    def lower(self):
        return Expression(self.db, self._dialect.lower, self, None, self.type)
    def upper(self):
        return Expression(self.db, self._dialect.upper, self, None, self.type)
    def replace(self, a, b):
        return Expression(self.db, self._dialect.replace, self, (a, b), self.type)
    def year(self):
        return Expression(self.db, self._dialect.extract, self, "year", "integer")
    def month(self):
        return Expression(self.db, self._dialect.extract, self, "month", "integer")
    def day(self):
        return Expression(self.db, self._dialect.extract, self, "day", "integer")
    def hour(self):
        return Expression(self.db, self._dialect.extract, self, "hour", "integer")
    def minutes(self):
        return Expression(self.db, self._dialect.extract, self, "minute", "integer")
    def coalesce(self, *others):
        return Expression(self.db, self._dialect.coalesce, self, others, self.type)
    def coalesce_zero(self):
        return Expression(self.db, self._dialect.coalesce_zero, self, None, self.type)
    def seconds(self):
        return Expression(self.db, self._dialect.extract, self, "second", "integer")
    def epoch(self):
        return Expression(self.db, self._dialect.epoch, self, None, "integer")
    def __getitem__(self, i):
        if isinstance(i, slice):
            start = i.start or 0
            stop = i.stop
            db = self.db
            if start < 0:
                pos0 = "(%s - %d)" % (self.len(), abs(start) - 1)
            else:
                pos0 = start + 1
            maxint = sys.maxint if PY2 else sys.maxsize
            if stop is None or stop == maxint:
                length = self.len()
            elif stop < 0:
                length = "(%s - %d - %s)" % (self.len(), abs(stop) - 1, pos0)
            else:
                length = "(%s - %s)" % (stop + 1, pos0)
            return Expression(
                db, self._dialect.substring, self, (pos0, length), self.type
            )
        else:
            return self[i : i + 1]
    def __str__(self):
        return str(self.db._adapter.expand(self, self.type))
    def __or__(self, other):  
        return Expression(self.db, self._dialect.comma, self, other, self.type)
    def __invert__(self):
        if hasattr(self, "_op") and self.op == self._dialect.invert:
            return self.first
        return Expression(self.db, self._dialect.invert, self, type=self.type)
    def __add__(self, other):
        return Expression(self.db, self._dialect.add, self, other, self.type)
    def __sub__(self, other):
        if self.type in ("integer", "bigint"):
            result_type = "integer"
        elif self.type in ["date", "time", "datetime", "double", "float"]:
            result_type = "double"
        elif self.type.startswith("decimal("):
            result_type = self.type
        else:
            raise SyntaxError("subtraction operation not supported for type")
        return Expression(self.db, self._dialect.sub, self, other, result_type)
    def __mul__(self, other):
        return Expression(self.db, self._dialect.mul, self, other, self.type)
    def __div__(self, other):
        return Expression(self.db, self._dialect.div, self, other, self.type)
    def __truediv__(self, other):
        return self.__div__(other)
    def __mod__(self, other):
        return Expression(self.db, self._dialect.mod, self, other, self.type)
    def __eq__(self, value):
        return Query(self.db, self._dialect.eq, self, value)
    def __ne__(self, value):
        return Query(self.db, self._dialect.ne, self, value)
    def __lt__(self, value):
        return Query(self.db, self._dialect.lt, self, value)
    def __le__(self, value):
        return Query(self.db, self._dialect.lte, self, value)
    def __gt__(self, value):
        return Query(self.db, self._dialect.gt, self, value)
    def __ge__(self, value):
        return Query(self.db, self._dialect.gte, self, value)
    def like(self, value, case_sensitive=True, escape=None):
        op = case_sensitive and self._dialect.like or self._dialect.ilike
        return Query(self.db, op, self, value, escape=escape)
    def ilike(self, value, escape=None):
        return self.like(value, case_sensitive=False, escape=escape)
    def regexp(self, value):
        return Query(self.db, self._dialect.regexp, self, value)
    def belongs(self, *value, **kwattr):
        db = self.db
        if len(value) == 1:
            value = value[0]
        if isinstance(value, Query):
            value = db(value)._select(value.first._table._id)
        elif not isinstance(value, (Select, basestring)):
            value = set(value)
            if kwattr.get("null") and None in value:
                value.remove(None)
                return (self == None) | Query(
                    self.db, self._dialect.belongs, self, value
                )
        return Query(self.db, self._dialect.belongs, self, value)
    def startswith(self, value):
        if self.type not in ("string", "text", "json", "jsonb", "upload"):
            raise SyntaxError("startswith used with incompatible field type")
        return Query(self.db, self._dialect.startswith, self, value)
    def endswith(self, value):
        if self.type not in ("string", "text", "json", "jsonb", "upload"):
            raise SyntaxError("endswith used with incompatible field type")
        return Query(self.db, self._dialect.endswith, self, value)
    def contains(self, value, all=False, case_sensitive=False):
        if isinstance(value, (list, tuple)):
            subqueries = [
                self.contains(str(v), case_sensitive=case_sensitive)
                for v in value
                if str(v)
            ]
            if not subqueries:
                return self.contains("")
            else:
                return reduce(all and AND or OR, subqueries)
        if (
            self.type
            not in (
                "string",
                "text",
                "json",
                "jsonb",
                "upload",
            )
            and not self.type.startswith("list:")
        ):
            raise SyntaxError("contains used with incompatible field type")
        return Query(
            self.db, self._dialect.contains, self, value, case_sensitive=case_sensitive
        )
    def with_alias(self, alias):
        return Expression(self.db, self._dialect._as, self, alias, self.type)
    @property
    def alias(self):
        if self.op == self._dialect._as:
            return self.second
    def st_asgeojson(self, precision=15, options=0):
        return Expression(
            self.db,
            self._dialect.st_asgeojson,
            self,
            dict(precision=precision, options=options),
            "string",
        )
    def st_astext(self):
        return Expression(self.db, self._dialect.st_astext, self, type="string")
    def st_aswkb(self):
        return Expression(self.db, self._dialect.st_aswkb, self, type="string")
    def st_x(self):
        return Expression(self.db, self._dialect.st_x, self, type="string")
    def st_y(self):
        return Expression(self.db, self._dialect.st_y, self, type="string")
    def st_distance(self, other):
        return Expression(self.db, self._dialect.st_distance, self, other, "double")
    def st_simplify(self, value):
        return Expression(self.db, self._dialect.st_simplify, self, value, self.type)
    def st_simplifypreservetopology(self, value):
        return Expression(
            self.db, self._dialect.st_simplifypreservetopology, self, value, self.type
        )
    def st_transform(self, value):
        return Expression(self.db, self._dialect.st_transform, self, value, self.type)
    def st_contains(self, value):
        return Query(self.db, self._dialect.st_contains, self, value)
    def st_equals(self, value):
        return Query(self.db, self._dialect.st_equals, self, value)
    def st_intersects(self, value):
        return Query(self.db, self._dialect.st_intersects, self, value)
    def st_overlaps(self, value):
        return Query(self.db, self._dialect.st_overlaps, self, value)
    def st_touches(self, value):
