class MCTSNode():
    @staticmethod
    def root_node(position, move_probabilities):
        node = MCTSNode(None, None, 0)
        node.position = position
        node.expand(move_probabilities)
        return node
    def __init__(self, parent, move, prior):
        self.parent = parent  
        self.move = move  
        self.prior = prior
        self.position = None  
        self.children = {}  
        self.Q = self.parent.Q if self.parent is not None else 0  
        self.U = prior  
        self.N = 0  
    def __repr__(self):
        return "<MCTSNode move=%s prior=%s score=%s is_expanded=%s>" % (
        self.move, self.prior, self.action_score, self.is_expanded())
    @property
    def action_score(self):
        return self.Q + self.U
    def is_expanded(self):
        return self.position is not None
    def compute_position(self):
        self.position = self.parent.position.play_move(self.move)
        return self.position
    def expand(self, move_probabilities):
        self.children = {move: MCTSNode(self, move, prob)
                         for move, prob in np.ndenumerate(move_probabilities)}
        self.children[None] = MCTSNode(self, None, 0)
    def backup_value(self, value):
        self.N += 1
        if self.parent is None:
            return
        self.Q, self.U = (
            self.Q + (value - self.Q) / self.N,
            c_PUCT * math.sqrt(self.parent.N) * self.prior / self.N,
        )
        self.parent.backup_value(-value)
    def select_leaf(self):
        current = self
        while current.is_expanded():
            current = max(current.children.values(), key=lambda node: node.action_score)
        return current

class CapacityRequest(object):
  @classmethod
  def from_task(cls, task):
    return cls(ResourceAggregate(numCpus=task.numCpus, ramMb=task.ramMb, diskMb=task.diskMb))
  def __init__(self, quota=None):
    self._quota = quota or ResourceAggregate(numCpus=0.0, ramMb=0, diskMb=0)
  def __add__(self, other):
    return self._op(operator.__add__, other)
  def __radd__(self, other):
    return self._op(operator.__add__, other)
  def __sub__(self, other):
    return self._op(operator.__sub__, other)
  def __eq__(self, other):
    return self._quota == other._quota
  def _op(self, op, other):
    if not isinstance(other, CapacityRequest):
      return self
    return CapacityRequest(
        ResourceAggregate(numCpus=op(self._quota.numCpus, other._quota.numCpus),
              ramMb=op(self._quota.ramMb, other._quota.ramMb),
              diskMb=op(self._quota.diskMb, other._quota.diskMb)))
  def valid(self):
    return self._quota.numCpus >= 0.0 and self._quota.ramMb >= 0 and self._quota.diskMb >= 0
  def quota(self):
    return deepcopy(self._quota)

