            "wins": desc(SeasonStats.wins),
            "losses": desc(SeasonStats.losses),
        }
        result = (
            SeasonStats.query.join(Player)
            .group_by(Player.steam_id)
            .filter(SeasonStats.season_id == s_id)
            .order_by(sort_dict.get(sort, desc(SeasonStats.pts)))
            .join(PlayerMatchStats)
            .group_by(SeasonStats.id)
        )
        if nickname_filter:
            result = result.filter(
                func.lower(Player.nickname).startswith(func.lower(nickname_filter))
            )
        return result
    def calibrated(self):
        from gleague.models import PlayerMatchStats
        if self.inactive:
            return False
        return (
            db.session.query(func.count(PlayerMatchStats.id))
            .join(SeasonStats)
            .group_by(SeasonStats.id)
            .filter(SeasonStats.id == self.id)
        ).scalar() > current_app.config["SEASON_CALIBRATING_MATCHES_NUM"]
    def __repr__(self):
        return "{} ({})".format(self.player.__repr__(), self.season.__repr__())

class FalkonBase(base.BaseEstimator, ABC):
    def __init__(self,
                 kernel: falkon.kernels.Kernel,
                 M: int,
                 center_selection: Union[str, falkon.center_selection.CenterSelector] = 'uniform',
                 seed: Optional[int] = None,
                 error_fn: Optional[callable] = None,
                 error_every: Optional[int] = 1,
                 options: Optional[FalkonOptions] = None,
                 ):
        self.kernel = kernel
        self.M = M
        self.seed = seed
        if self.seed is not None:
            torch.manual_seed(self.seed)  
        self.random_state_ = check_random_generator(self.seed)
        self.error_fn = error_fn
        self.error_every = error_every
        self.options = options or FalkonOptions()
        self._cg_options = self.options.get_conjgrad_options()
        self._keops_options = self.options.get_keops_options()
        self._pc_options = self.options.get_pc_options()
        self._cholesky_opt = self.options.get_chol_options()
        self._lauum_opt = self.options.get_lauum_options()
        self._base_opt = self.options.get_base_options()
        self.use_cuda_ = decide_cuda(self.options)
        self.num_gpus = 0
        self.alpha_ = None
        self.ny_points_ = None
        self.fit_times_ = None
        if isinstance(center_selection, str):
            if center_selection.lower() == 'uniform':
                self.center_selection: falkon.center_selection.CenterSelector = \
                    falkon.center_selection.UniformSelector(self.random_state_)
            else:
                raise ValueError(f'Center selection "{center_selection}" is not valid.')
        else:
            self.center_selection: falkon.center_selection.CenterSelector = center_selection
    def _init_cuda(self):
        if self.use_cuda_:
            torch.cuda.init()
            from falkon.cuda import initialization
            initialization.init(self._base_opt)
            self.num_gpus = devices.num_gpus(self.options)
    def _get_callback_fn(self, X, Y, Xts, Yts, ny_points, precond):
        def val_cback(it, beta, train_time):
            self.fit_times_.append(self.fit_times_[0] + train_time)
            if it % self.error_every != 0:
                print("Iteration %3d - Elapsed %.1fs" % (it, self.fit_times_[-1]), flush=True)
                return
            err_str = "training" if Xts is None or Yts is None else "validation"
            alpha = precond.apply(beta)
            if Xts is not None and Yts is not None:
                pred = self._predict(Xts, ny_points, alpha)
                err = self.error_fn(Yts, pred)
            else:
                pred = self._predict(X, ny_points, alpha)
                err = self.error_fn(Y, pred)
            err_name = "error"
            if isinstance(err, tuple) and len(err) == 2:
                err, err_name = err
            print("Iteration %3d - Elapsed %.1fs - %s %s: %.4f" %
                  (it, self.fit_times_[-1], err_str, err_name, err), flush=True)
        return val_cback
    def _check_fit_inputs(self,
                          X: _tensor_type,
                          Y: torch.Tensor,
                          Xts: _tensor_type,
                          Yts: torch.Tensor) -> Tuple[_tensor_type, torch.Tensor, _tensor_type, torch.Tensor]:
        if X.shape[0] != Y.shape[0]:
            raise ValueError("X and Y must have the same number of "
                             "samples (found %d and %d)" %
                             (X.shape[0], Y.shape[0]))
        if Y.dim() == 1:
            Y = torch.unsqueeze(Y, 1)
        if Y.dim() != 2:
            raise ValueError("Y is expected 1D or 2D. Found %dD." % (Y.dim()))
        if not check_same_dtype(X, Y):
            raise TypeError("X and Y must have the same data-type.")
        if should_use_keops(X, X, self.options):
            X = to_c_contig(X, "X", True)
            Y = to_c_contig(Y, "Y", True)
            Xts = to_c_contig(Xts, "Xts", True)
            Yts = to_c_contig(Yts, "Yts", True)
        return X, Y, Xts, Yts
    def _check_predict_inputs(self, X: _tensor_type) -> _tensor_type:
        if self.alpha_ is None or self.ny_points_ is None:
            raise RuntimeError(
                "Falkon has not been trained. `predict` must be called after `fit`.")
        if should_use_keops(X, self.ny_points_, self.options):
            X = to_c_contig(X, "X", True)
        return X
    def _can_store_knm(self, X, ny_points, available_ram, store_threshold=1200):
        if self.options.never_store_kernel:
            return False
        dts = sizeof_dtype(X.dtype)
        if X.size(1) > store_threshold:
            necessary_ram = X.size(0) * ny_points.size(0) * dts
            if available_ram > necessary_ram:
                if self.options.debug:
                    print("%d*%d Kernel matrix will be stored" %
                          (X.size(0), ny_points.size(0)))
                return True
            elif self.options.debug:
                print(
                    "Cannot store full kernel matrix: not enough memory (have %.2fGB, need %.2fGB)" %
                    (available_ram / 2 ** 30, necessary_ram / 2 ** 30))
                return False
        else:
            return False
    @abstractmethod
    def fit(self,
            X: torch.Tensor,
            Y: torch.Tensor,
            Xts: Optional[torch.Tensor] = None,
            Yts: Optional[torch.Tensor] = None):
        pass
    @abstractmethod
    def _predict(self, X, ny_points_, alpha_):
        pass
    def predict(self, X: torch.Tensor) -> torch.Tensor:
        X = self._check_predict_inputs(X)
        return self._predict(X, self.ny_points_, self.alpha_)
    def __repr__(self, **kwargs):
        return super().__repr__(N_CHAR_MAX=5000)

class ArloMediaLibrary(object):
    def __init__( self,arlo,max_days ):
        self._arlo      = arlo
        self._lock      = threading.Lock()
        self._load_cbs_ = []
        self._count     = 0
        self._videos    = []
        self._video_keys = []
    def __repr__(self):
        return "<{0}:{1}>".format( self.__class__.__name__,self._arlo.name )
    def update( self ):
        self._arlo.debug( 'updating image library' )
        date_to = datetime.today().strftime('%Y%m%d')
        data = self._arlo._be.post( LIBRARY_URL,{ 'dateFrom':date_to,'dateTo':date_to } )
        with self._lock:
            keys = self._video_keys
        videos = []
        for video in data:
            if not video.get('contentType','').startswith('video/'):
                continue
            camera = self._arlo.lookup_camera_by_id( video.get('deviceId') )
            if not camera:
                continue
            key = '{0}:{1}'.format( video.get('deviceId'), arlotime_strftime( video.get('localCreatedDate' ) ) )
            if key in keys:
                continue
            self._arlo.debug( 'adding {0}'.format( key ) )
            videos.append( ArloVideo(video,camera,self._arlo) )
            keys.append( key )
        cbs = []
        with self._lock:
            self._count += 1
            self._videos = videos + self._videos
            self._video_keys = keys
            self._arlo.debug( 'ml:update-count=' + str(self._count) )
            cbs = self._load_cbs_
            self._load_cbs_ = []
        for cb in cbs:
            cb()
    def load( self,days=PRELOAD_DAYS ):
        self._arlo.debug( 'loading image library' )
        now       = datetime.today()
        date_from = (now - timedelta(days=days)).strftime('%Y%m%d')
        date_to   = now.strftime('%Y%m%d')
        data = self._arlo._be.post( LIBRARY_URL,{ 'dateFrom':date_from,'dateTo':date_to } )
        videos = []
        keys = []
        for video in data:
            if not video.get('contentType','').startswith('video/'):
                continue
            camera = self._arlo.lookup_camera_by_id( video.get('deviceId') )
            if camera is not None:
                key = '{0}:{1}'.format( video.get('deviceId'), arlotime_strftime( video.get('localCreatedDate' ) ) )
                self._arlo.debug( 'adding {0}'.format( key ) )
                videos.append(ArloVideo(video, camera, self._arlo))
                keys.append( key )
        with self._lock:
            self._count += 1
            self._videos = videos
            self._video_keys = keys
            self._arlo.debug( 'ml:load-count=' + str(self._count) )
    @property
    def videos( self ):
        with self._lock:
            return ( self._count,self._videos )
    @property
    def count( self ):
        with self._lock:
            return self._count
    def videos_for( self,camera ):
        camera_videos = []
        with self._lock:
            for video in self._videos:
                if camera.device_id == video.camera.device_id:
                    camera_videos.append( video )
            return ( self._count,camera_videos )
    def queue_update( self,cb ):
        with self._lock:
            if not self._load_cbs_:
                self._arlo.debug( 'queueing image library update' )
                self._arlo._bg.run_low_in( self.update,2 )
            self._load_cbs_.append( cb )

