class LinkedList(object):
    def __init__(self, head=None):
        self.head = head
    def get_head(self):
        return self.head
    def get_tail(self):
        current = self.head
        if not current or not current.has_next():
            return current
        while current.has_next():
            current = current.get_next()
        return current
    def insert(self, payload, new_node=None):
        if not new_node:
            new_node = Node(payload)
        new_node.set_next(self.head)
        self.head = new_node
        return self
    def append(self, payload, new_node=None):
        if not new_node:
            new_node = Node(payload)
        self.get_tail().set_next(new_node)
        return self
    def size(self):
        current = self.head
        node_count = 0
        while current:
            node_count += 1
            current = current.get_next()
        return node_count
    def reverse(self):
        new_head = self.get_head()
        new_list = LinkedList( head=Node( self.head.get_payload()) )
        current = self.head.get_next()
        while current:
            new_list.insert(current)
            current = current.get_next()
        return new_list
    def __repr__(self):
        current = self.head
        line = ""
        while current:
            line += "({}) -> ".format(current.__str__())
            current = current.get_next()
        line += "None"
        return line

