class FileList(collections.MutableSequence):
    def __init__(self, path, initial=None):
        if not os.path.isabs(path):
            raise AbsolutePathRequiredError(path)
        self.path = path
        if initial:
            try:
                os.unlink(self.path)
            except EnvironmentError:
                pass
            for i in initial:
                self.append(i)
    def __read(self):
        lines = []
        try:
            with open(self.path) as fd:
                for line in fd:
                    lines.append(line.rstrip('\n'))
        except EnvironmentError as e:
            pass
        return lines
    def __write(self, lines):
        try:
            with open(self.path, 'w') as fd:
                for line in lines:
                    fd.write(str(line) + '\n')
        except EnvironmentError as e:
            raise cdist.Error(str(e))
    def __repr__(self):
        return repr(list(self))
    def __getitem__(self, index):
        return self.__read()[index]
    def __setitem__(self, index, value):
        lines = self.__read()
        lines[index] = value
        self.__write(lines)
    def __delitem__(self, index):
        lines = self.__read()
        del lines[index]
        self.__write(lines)
    def __len__(self):
        lines = self.__read()
        return len(lines)
    def insert(self, index, value):
        lines = self.__read()
        lines.insert(index, value)
        self.__write(lines)
    def sort(self):
        lines = sorted(self)
        self.__write(lines)

class DirectoryDict(collections.MutableMapping):
    def __init__(self, path, initial=None, **kwargs):
        if not os.path.isabs(path):
            raise AbsolutePathRequiredError(path)
        self.path = path
        try:
            if not os.path.isdir(self.path):
                os.mkdir(self.path)
        except EnvironmentError as e:
            raise cdist.Error(str(e))
        if initial is not None:
            self.update(initial)
        if kwargs:
            self.update(kwargs)
    def __repr__(self):
        return repr(dict(self))
    def __getitem__(self, key):
        try:
            with open(os.path.join(self.path, key), "r") as fd:
                return fd.read().rstrip('\n')
        except EnvironmentError:
            raise KeyError(key)
    def __setitem__(self, key, value):
        try:
            with open(os.path.join(self.path, key), "w") as fd:
                if (not hasattr(value, 'strip') and
                    (hasattr(value, '__getitem__') or
                     hasattr(value, '__iter__'))):
                    for v in value:
                        fd.write(str(v) + '\n')
                else:
                    fd.write(str(value))
                    if value and value[-1] != '\n':
                        fd.write('\n')
        except EnvironmentError as e:
            raise cdist.Error(str(e))
    def __delitem__(self, key):
        try:
            os.remove(os.path.join(self.path, key))
        except EnvironmentError:
            raise KeyError(key)
    def __iter__(self):
        try:
            return iter(os.listdir(self.path))
        except EnvironmentError as e:
            raise cdist.Error(str(e))
    def __len__(self):
        try:
            return len(os.listdir(self.path))
        except EnvironmentError as e:
            raise cdist.Error(str(e))

class Fraction:
    @staticmethod
    def _gcd(x : int, y : int) -> int:
        assert x >= 0 and y >= 0, 'Fraction._gcd: x('+str(x)+') and y('+str(y)+') must be >= 0'
        while y != 0:
            x, y = y, x % y
        return x
    def __call__(self, decimal_places):
        answer = ''
        num = self.num
        denom = self.denom
        if num < 0:
            num, answer = -num, '-'
        if num >= denom:
            answer += str(num//denom)
            num     = num - num//denom*denom
        answer += '.'+str(num*10**decimal_places//denom)
        return answer
    @staticmethod
    def _validate_arithmetic(v, t : set, op : str, lt : str, rt : str):
        if type(v) not in t:
            raise TypeError('unsupported operand type(s) for '+op+
                            ': \''+lt+'\' and \''+rt+'\'')        
    @staticmethod
    def _validate_relational(v, t : set, op : str, rt : str):
        if type(v) not in t:
            raise TypeError('unorderable types: '+
                            'Fraction() '+op+' '+rt+'()')        
    def __init__(self,num=0,denom=1):
        if num == 0 and denom != 1:
            self.num = num
            self.denom = 1
            return None
        if denom == 0:
            raise AssertionError('Cannot divide by 0 for a fraction')
        if (type(num) is not int) or (type(denom) is not int):
            raise AssertionError('Arguments must be 1-2 integers')
            return None
        if denom > 0 and num < 0:
            gcd = self._gcd(-num,denom)
            self.num = int(num/gcd)
            self.denom = int(denom/gcd)
            return None
        if denom < 0 and num < 0:
            num = -num
            denom = -denom
            gcd = self._gcd(num,denom)
            self.num = int(num/gcd)
            self.denom = int(denom/gcd)
            return None
        if num > 0 and denom < 0:
            num = -num
            denom = -denom
            gcd = self._gcd(-num,denom)
            self.num = int(num/gcd)
            self.denom = int(denom/gcd)
            return None
        gcd = self._gcd(num,denom)
