class SearchAgentsAsyncPager:
    def __init__(
        self,
        method: Callable[..., Awaitable[agent.SearchAgentsResponse]],
        request: agent.SearchAgentsRequest,
        response: agent.SearchAgentsResponse,
        *,
        metadata: Sequence[Tuple[str, str]] = ()
    ):
        self._method = method
        self._request = agent.SearchAgentsRequest(request)
        self._response = response
        self._metadata = metadata
    def __getattr__(self, name: str) -> Any:
        return getattr(self._response, name)
    @property
    async def pages(self) -> AsyncIterable[agent.SearchAgentsResponse]:
        yield self._response
        while self._response.next_page_token:
            self._request.page_token = self._response.next_page_token
            self._response = await self._method(self._request, metadata=self._metadata)
            yield self._response
    def __aiter__(self) -> AsyncIterable[agent.Agent]:
        async def async_generator():
            async for page in self.pages:
                for response in page.agents:
                    yield response
        return async_generator()
    def __repr__(self) -> str:
        return "{0}<{1!r}>".format(self.__class__.__name__, self._response)

class ray:
    def __init__(self, p, r , turtle):
        self.p = p
        self.r = r
        self.turtle = turtle
    def __repr__(self):
        return str(self.p) + " " + str(self.r)
    def intersectsWithLinesegment(self, linesegment):
        num = self.r[1]*(linesegment.xstart - self.p[0])+self.r[0]*(self.p[1]-linesegment.ystart) 
        denom = self.r[1]*(linesegment.xstart - linesegment.xstop)+self.r[0]*(linesegment.ystop-linesegment.ystart)
        if denom != 0:
            v = num/denom
        else:
            v = 0.5
        if 0 < v < 1:
            self.turtle.goto(linesegment.xstart + v*(linesegment.xstop-linesegment.xstart), linesegment.ystart + v*(linesegment.ystop-linesegment.ystart) )
            self.turtle.pencolor("red")
            self.turtle.dot()
    def updateRayDirection(self, x, y):
        self.r[0] = x - self.p[0]
        self.r[1] = y - self.p[1]

