class JID(object):
    __slots__ = ('local', 'domain', 'resource', 'real_domain')
    def __init__(self, jid, validate_on_init=True):
        super(JID, self).__init__()
        self.real_domain = False
        parts = unicode(jid).split('@', 1)
        if len(parts) == 2:
            self.local = parts[0]
            jid = parts[1]
        else:
            self.local = None
            jid = parts[0]
        parts = jid.split('/', 1)
        if len(parts) == 2:
            self.domain = parts[0]
            self.resource = parts[1]
        else:
            self.domain = parts[0]
            self.resource = None
        if validate_on_init:
            self.validate(raise_error=True)
    def __eq__(self, other):
        return self.local == other.local and \
               self.domain == other.domain and \
               self.resource == other.resource
    def __ne__(self, other):
        return not self.__eq__(other)
    def __str__(self):
        if self.local is not None and \
           self.resource is not None:
            return "%s@%s/%s" % (self.local, self.domain, self.resource)
        elif self.local is not None:
            return "%s@%s" % (self.local, self.domain)
        elif self.resource is not None:
            return "%s/%s" % (self.domain, self.resource)
        else:
            return self.domain
    def validate(self, raise_error=False):
        if self.domain is None or len(self.domain) < 1:
            if raise_error:
                raise ValueError("A domain is required")
            else:
                return False
        if self.domain.find(".") >= 0 or self.domain.find(":") >= 0:
            if not ((len(self.domain) < 256 and \
                     RE_DOMAIN.match(self.domain) is not None) or \
                    util.is_valid_ipv4(self.domain) or \
                    util.is_valid_ipv6(self.domain)):
                if raise_error:
                    raise ValueError("malformed domain")
                else:
                    return False
            self.real_domain = True
        else:
            if len(self.domain.encode("utf-8")) > 1024:
                if raise_error:
                    raise ValueError("malformed domain")
                else:
                    return False
        if self.local is not None:
            if len(self.local) < 1:
                if raise_error:
                    raise ValueError("local part too short")
                else:
                    return False
            if len(self.local.encode("utf-8")) > 1024:
                if raise_error:
                    raise ValueError("local part too long")
                else:
                    return False
            for char in self.local:
                number = ord(char)
                if not ((number in [0x21, 0x3B, 0x3D, 0x3F]) or \
                        (number >= 0x23 and number <= 0x25) or \
                        (number >= 0x28 and number <= 0x2E) or \
                        (number >= 0x30 and number <= 0x39) or \
                        (number >= 0x41 and number <= 0x7E) or \
                        (number >= 0x80 and number <= 0xD7FF) or \
                        (number >= 0xE000 and number <= 0xFFFD) or \
                        (number >= 0x10000 and number <= 0x10FFFF)
                        ):
                    if raise_error:
                        raise ValueError("malformed local part")
                    else:
                        return False
        if self.resource is not None:
            if len(self.resource) < 1:
                if raise_error:
                    raise ValueError("resource part too short")
                else:
                    return False
            if len(self.resource.encode("utf-8")) > 1024:
                if raise_error:
                    raise ValueError("resource part too long")
                else:
                    return False
            for char in self.resource:
                number = ord(char)
                if not ((number >= 0x20 and number <= 0xD7FF) or \
                        (number >= 0xE000 and number <= 0xFFFD) or \
                        (number >= 0x10000 and number <= 0x10FFFF)):
                    if raise_error:
                        raise ValueError("malformed resource")
                    else:
                        return False
        if not raise_error:
            return True
    @property
    def bare(self):
        if self.local is not None:
            return "%s@%s" % (self.local, self.domain)
        else:
            return self.domain

class Road(Loggable):
    def __init__(self, network=None, vehicles=None, np_random=None):
        self.network = network or []
        self.vehicles = vehicles or []
        self.np_random = np_random if np_random else np.random.RandomState()
    def close_vehicles_to(self, vehicle, distances):
        return [v for v in self.vehicles if (distances[0] < vehicle.lane_distance_to(v) < distances[1]
                                             and v is not vehicle)]
    def closest_vehicles_to(self, vehicle, count):
        sorted_v = sorted([v for v in self.vehicles
                           if v is not vehicle
                           and -2*vehicle.LENGTH < vehicle.lane_distance_to(v)],
                          key=lambda v: abs(vehicle.lane_distance_to(v)))
        return sorted_v[:count]
    def act(self):
        for vehicle in self.vehicles:
            vehicle.act()
    def step(self, dt):
        for vehicle in self.vehicles:
            vehicle.step(dt)
        for vehicle in self.vehicles:
            for other in self.vehicles:
                vehicle.check_collision(other)
    def neighbour_vehicles(self, vehicle, lane_index=None):
        lane_index = lane_index or vehicle.lane_index
        if not lane_index:
            return None, None
        lane = self.network.get_lane(lane_index)
        s = self.network.get_lane(lane_index).local_coordinates(vehicle.position)[0]
        s_front = s_rear = None
        v_front = v_rear = None
        for v in self.vehicles:
            if v is not vehicle and self.network.is_connected_road(v.lane_index, lane_index, same_lane=True):
                s_v, lat_v = lane.local_coordinates(v.position)
                if not lane.on_lane(v.position, s_v, lat_v):
                    continue
                if s <= s_v and (s_front is None or s_v <= s_front):
                    s_front = s_v
                    v_front = v
                if s_v < s and (s_rear is None or s_v > s_rear):
                    s_rear = s_v
                    v_rear = v
        return v_front, v_rear
    def dump(self):
        for v in self.vehicles:
            if not isinstance(v, Obstacle):
                v.dump()
    def get_log(self):
        return pd.concat([v.get_log() for v in self.vehicles])
    def __repr__(self):
        return self.vehicles.__repr__()

class EpsilonGreedyAgent(Agent):
    def __init__(self, epsilon: float = None):
        super().__init__()  
        self.epsilon = epsilon
    def _get_random_bandit(self) -> Bandit:
        return np.random.choice(self.bandits)
    def _get_current_best_bandit(self) -> Bandit:
        estimates = []
        for bandit in self.bandits:
            bandit_record = self.rewards_log[bandit]
            if not bandit_record['actions']:
                estimates.append(0)
            else:
                estimates.append(bandit_record['reward'] / bandit_record['actions'])
        return self.bandits[np.argmax(estimates)]
    def _choose_bandit(self) -> Bandit:
        epsilon = self.epsilon or 1 / (1 + self.rewards_log.total_actions)
        p = np.random.uniform(0, 1, 1)
        if p < epsilon:
            bandit = self._get_random_bandit()
        else:
            bandit = self._get_current_best_bandit()
        return bandit
    def take_action(self):
        current_bandit = self._choose_bandit()
        reward = current_bandit.pull()
        self.rewards_log.record_action(current_bandit, reward)
        return reward
    def __repr__(self):
        return 'EpsilonGreedyAgent(epsilon={})'.format(self.epsilon)

class UCB1Agent(UCBAgent):
    def initialise(self):
        if self.initialised:
            logger.info('Initialisation step has been executed before.')
            return
        for bandit in self.bandits:
            reward = bandit.pull()
            self.rewards_log.record_action(bandit, reward)
        self.initialised = True
    def calculate_bandit_index(self, bandit):
        bandit_record = self.rewards_log[bandit]
        sample_mean = bandit_record['reward'] / bandit_record['actions']
        c = np.sqrt(2 * np.log(self.rewards_log.total_actions) / bandit_record['actions'])
        return sample_mean + c
    def __repr__(self):
        return 'UCB1()'

class UCB1TunedAgent(UCBAgent):
    def initialise(self):
        if self.initialised:
            logger.info('Initialisation step has been executed before.')
            return
        for bandit in self.bandits:
            reward = bandit.pull()
            self.rewards_log.record_action(bandit, reward)
        self.initialised = True
    def calculate_bandit_index(self, bandit):
        bandit_record = self.rewards_log[bandit]
        n = bandit_record['actions']
        sample_mean = bandit_record['reward'] / n
        variance_bound = bandit_record['reward_squared'] / n - sample_mean ** 2
        variance_bound += np.sqrt(2 * np.log(self.rewards_log.total_actions) / n)
        c = np.sqrt(np.min([variance_bound, 1 / 4]) * np.log(self.rewards_log.total_actions) / n)
        return sample_mean + c
    def __repr__(self):
        return 'UCB1Tuned()'

class UCB1NormalAgent(UCBAgent):
    def initialise(self):
        if self.initialised:
            logger.info('Initialisation step has been executed before.')
            return
        for bandit in self.bandits:
            for _ in range(2):
                reward = bandit.pull()
                self.rewards_log.record_action(bandit, reward)
        self.initialised = True
    def calculate_bandit_index(self, bandit):
        bandit_record = self.rewards_log[bandit]
        n = bandit_record['actions']
        sample_mean = bandit_record['reward'] / n
        sample_variance = (bandit_record['reward_squared'] - n * sample_mean ** 2) / (n - 1)
        c = np.sqrt(16 * sample_variance * np.log(self.rewards_log.total_actions - 1) / n)
        return sample_mean + c
    def _get_bandit_with_insufficient_data(self):
        res = []
        for bandit in self.bandits:
            bandit_record = self.rewards_log[bandit]
            if bandit_record['actions'] < np.max([3, np.ceil(8 * np.log(self.rewards_log.total_actions))]):
                res.append(bandit)
        if res:
            return np.random.choice(res)
        return None
    def _get_current_best_bandit(self) -> Bandit:
        estimates = [self.calculate_bandit_index(bandit) for bandit in self.bandits]
        return self.bandits[np.argmax(estimates)]
    def take_action(self):
        if not self.initialised:
            raise Exception('Initialisation step needs to be executed first.')
        current_bandit = self._get_bandit_with_insufficient_data()
        if not current_bandit:
            current_bandit = self._get_current_best_bandit()
        reward = current_bandit.pull()
        self.rewards_log.record_action(current_bandit, reward)
        return reward
    def __repr__(self):
        return 'UCB1Normal()'

class Variable:
    __array_priority__ = 200
    def __init__(self, data: np.ndarray, name=None):
        if data is not None:
            if not isinstance(data, np.ndarray):
                raise TypeError('{} is not supported'.format(type(data)))
        self.data = data
        self.name = name
        self.grad = None
        self.creator = None
        self.generation = 0
    def __repr__(self):
        if self.data is None:
            return 'variable(None)'
        p = str(self.data).replace('\n', '\n' + ' ' * 9)
        return 'variable(' + p + ')'
    def __len__(self):
        return len(self.data)
    @property
    def shape(self):
        return self.data.shape
    @property
    def ndim(self):
        return self.data.ndim
    @property
    def size(self):
        return self.data.size
    @property
    def dtype(self):
        return self.data.dtype
    def set_creator(self, func: 'Function') -> None:
        self.creator = func
        self.generation = func.generation + 1
    def cleargrad(self):
        self.grad = None
    def backward(self, retain_grad=False, create_graph=False):
        if self.grad is None:
            self.grad = Variable(np.ones_like(self.data))
        funcs = []
        seen_set = set()
        def add_func(f):
            if f not in seen_set:
                funcs.append(f)
                seen_set.add(f)
                funcs.sort(key=lambda x: x.generation)
        add_func(self.creator)
        while funcs:
            f = funcs.pop()
            gys = [output().grad for output in f.outputs]
            with using_config('enable_backprop', create_graph):
                gxs = f.backward(*gys)
                if not isinstance(gxs, tuple):
                    gxs = (gxs,)
                for x, gx in zip(f.inputs, gxs):
                    if x.grad is None:
                        x.grad = gx
                    else:
                        x.grad = x.grad + gx
                    if x.creator is not None:
                        add_func(x.creator)
            if not retain_grad:
                for y in f.outputs:
                    y().grad = None  
    def reshape(self, *shape):
        if len(shape) == 1 and isinstance(shape[0], (tuple, list)):
            shape = shape[0]
        return dezero.functions.reshape(self, shape)
    def transpose(self):
        return dezero.functions.transpose(self)
    @property
    def T(self):
        return dezero.functions.transpose(self)

class ModelDataBillingFormatter(FormatterBase):
    def __repr__(self):
        return 'ModelDataBillingFormatter()'
    def _unestimated(self, data):
        def _yield_values():
            index, value = None, None
            for i, row in data.iterrows():
                if row.estimated:
                    if index is None:
                        index, value = i, row.value
                    else:
                        value += row.value
                else:
                    if index is None:
                        yield i, row.value
                    else:
                        yield index, (value + row.value)
                    index, value = None, None
        yielded = list(_yield_values())
        if len(yielded) == 0:
            return pd.Series()
        index, values = zip(*yielded)
        return pd.Series(values, index=index)
    def create_input(self, trace, weather_source):
        unestimated_trace_data = self._unestimated(trace.data.copy())
        temp_data = weather_source.indexed_temperatures(
            unestimated_trace_data.index, "degF", allow_mixed_frequency=True)
        return unestimated_trace_data, temp_data
    def create_demand_fixture(self, index, weather_source):
        tempF = weather_source.indexed_temperatures(index, "degF")
        return pd.DataFrame({"tempF": tempF})
    def _get_start_date(self, input_data):
        unestimated_trace_data, temp_data = input_data
        if unestimated_trace_data.shape[0] >= 1:
            return unestimated_trace_data.index[0]
        return None
    def _get_end_date(self, input_data):
        unestimated_trace_data, temp_data = input_data
        if unestimated_trace_data.shape[0] >= 1:
            return unestimated_trace_data.index[-1]
        return None
    def _get_n_rows(self, input_data):
        unestimated_trace_data, temp_data = input_data
        return unestimated_trace_data.shape[0]

