class Q(object):
    def __init__(self, a, b=1):
        self.a = a
        self.b = b
    def __repr__(self):
        if self.b==1:
            return str(self.a)
        return f'{self.a}/{self.b}'
    def __add__(self,q):
        a = self.a
        b = self.b
        c = q.a
        d = q.b
        return Q(a*d+b*c,b*d)
    def __sub__(self,q):
        a = self.a
        b = self.b
        c = q.a
        d = q.b
        return Q(a*d-b*c,b*d)
    def __mul__(self,q):
        a = self.a
        b = self.b
        c = q.a
        d = q.b
        return Q(a*c,b*d)
    def __truediv(self,q):
        a = self.a
        b = self.b
        c = q.a
        d = q.b
        return Q(a*d,b*c)

