        self.weight = left.weight + right.weight
    def __repr__(self):
        return '<Node with weight {}>'.format(self.weight)
    def __lt__(self, other):
        return self.weight < other.weight

class Leaf(Node):
    def __init__(self, symbol, weight):
        self.parent = None
        self.symbol = symbol
        self.weight = weight
    def __repr__(self):
        return "<Leaf '{}' with weight {}, code '{}'>".format(self.symbol, self.weight, self.code)
    @property
    def code(self):
        code = ''
        n = self
        while n.parent is not None:
            codebit = '0' if n is n.parent.left else '1'
            code = codebit + code
            n = n.parent
        return code

class RandomHorizontalFlipSlice(object):
    def __init__(self, p=0.5):
        self.p = p
    def __call__(self, img):
        image = img[0]
        labels = img[1]
        if random.random() < self.p:
            return np.flip(image, axis = -2).copy(), np.flip(labels, axis = -2).copy() 
        return img
    def __repr__(self):
        return self.__class__.__name__ + '(p={})'.format(self.p)

