  def reduce(self, initial_state, reduce_func):
    with ops.name_scope("initial_state"):
      initial_state = nest.pack_sequence_as(initial_state, [
          sparse_tensor_lib.SparseTensor.from_value(t)
          if sparse_tensor_lib.is_sparse(t) else ops.convert_to_tensor(
              t, name="component_%d" % i)
          for i, t in enumerate(nest.flatten(initial_state))
      ])
    state_structure = structure_lib.Structure.from_value(initial_state)
    need_to_rerun = True
    while need_to_rerun:
      wrapped_func = StructuredFunctionWrapper(
          reduce_func,
          "reduce()",
          input_structure=structure_lib.NestedStructure(
              (state_structure, self._element_structure)),
          add_to_graph=False)
      output_classes = wrapped_func.output_classes
      state_classes = state_structure._to_legacy_output_classes()  
      for new_state_class, state_class in zip(
          nest.flatten(output_classes), nest.flatten(state_classes)):
        if not issubclass(new_state_class, state_class):
          raise TypeError(
              "The element classes for the new state must match the initial "
              "state. Expected %s; got %s." % (state_classes,
                                               wrapped_func.output_classes))
      output_types = wrapped_func.output_types
      state_types = state_structure._to_legacy_output_types()  
      for new_state_type, state_type in zip(
          nest.flatten(output_types), nest.flatten(state_types)):
        if new_state_type != state_type:
          raise TypeError(
              "The element types for the new state must match the initial "
              "state. Expected %s; got %s." % (state_types,
                                               wrapped_func.output_types))
      output_shapes = wrapped_func.output_shapes
      state_shapes = state_structure._to_legacy_output_shapes()  
      flat_state_shapes = nest.flatten(state_shapes)
      flat_new_state_shapes = nest.flatten(output_shapes)
      weakened_state_shapes = [
          original.most_specific_compatible_shape(new)
          for original, new in zip(flat_state_shapes, flat_new_state_shapes)
      ]
      need_to_rerun = False
      for original_shape, weakened_shape in zip(flat_state_shapes,
                                                weakened_state_shapes):
        if original_shape.ndims is not None and (
            weakened_shape.ndims is None or
            original_shape.as_list() != weakened_shape.as_list()):
          need_to_rerun = True
          break
      if need_to_rerun:
        state_structure = structure_lib.convert_legacy_structure(
            state_types,
            nest.pack_sequence_as(state_shapes, weakened_state_shapes),
            state_classes)
    reduce_func = wrapped_func.function
    reduce_func.add_to_graph(ops.get_default_graph())
    return state_structure._from_compatible_tensor_list(
        gen_dataset_ops.reduce_dataset(
            self._variant_tensor,
            state_structure._to_tensor_list(initial_state),
            reduce_func.captured_inputs,
            f=reduce_func,
            output_shapes=state_structure._flat_shapes,
            output_types=state_structure._flat_types))
  def with_options(self, options):
    return _OptionsDataset(self, options)

class CircularHRR:
    def __init__(self, size_or_arr, seed=None):
        if isinstance(size_or_arr, int):
            size = size_or_arr
            if seed:
                rs = numpy.random.RandomState(seed)
            else:
                rs = numpy.random.default_rng()
            self.arr = numpy.exp(rs.uniform(math.tau, size=size) * 1j)
        else:
            arr = size_or_arr
            self.arr = numpy.copy(arr)
        self.perm, self.invperm = _perm(len(self.arr))
    def to_real_vec(self, dtype=None):
        realvec = numpy.empty(len(self.arr) * 2, dtype=dtype)
        realvec[0::2] = self.arr.real
        realvec[1::2] = self.arr.imag
        return realvec
    def normalize(self):
        return CircularHRR(self.arr / abs(self.arr))
    def permute_(self, perm):
        return CircularHRR(self.arr[perm])
    def permute(self):
        return self.permute_(self.perm)
    def invpermute(self):
        return self.permute_(self.invperm)
    def __mul__(self, other):
        if isinstance(other, CircularHRR):
            return CircularHRR(self.arr * other.arr)
        elif numpy.isscalar(other):
            return CircularHRR(self.arr * other)
        else:
            return NotImplemented
    def __rmul__(self, other):
        if isinstance(other, CircularHRR):
            return CircularHRR(self.arr * other.arr)
        elif numpy.isscalar(other):
            return CircularHRR(self.arr * other)
        else:
            return NotImplemented
    def __matmul__(self, other):
        return self * other.permute()
    def __truediv__(self, other):
        return self.decoderight(other)
    def decoderight(self, other):
        return self * ~(other.permute())
    def decodeleft(self, other):
        return (~other * self).invpermute()
    def __add__(self, other):
        if other == 0:
            return CircularHRR(self.arr)
        return CircularHRR(self.arr + other.arr)
    def __radd__(self, other):
        if other == 0:
            return CircularHRR(self.arr)
        return CircularHRR(self.arr + other.arr)
    def __neg__(self):
        return CircularHRR(-self.arr)
    def __invert__(self):
        return CircularHRR(self.arr.conj())
    def __sub__(self, other):
        return CircularHRR(self.arr - other.arr)
    def similarity(self, other):
        return sum((self.arr / other.arr).real) / len(self.arr)
    def __repr__(self):
        return repr(self.arr)
    def __str__(self):
        return str(self.arr)
    @staticmethod
    def cleanupmemory(hrrs):
        return scipy.spatial.KDTree(numpy.copy([hrr.arr for hrr in hrrs]))
    @staticmethod
    def cleanup(memory, hrr, k=1):
        _, indices = memory.query(hrr.arr, k=k)
        if k == 1:
            indices = [indices]
        cleanhrrs = [CircularHRR(memory.data[index]) for index in indices]
        cosinedistances = [hrr.similarity(cleanhrr) for cleanhrr in cleanhrrs]
        return cleanhrrs, cosinedistances

