class Rational:
    def __init__(self,x,y):
        self.x = x
        self.y = y
        assert type(x) == int and type(y) == int
    def __repr__(self):
        divided = Fraction(self.x, self.y)
        if divided._denominator == 1:
            return '%d'%divided._numerator
        return '%d/%d'%(divided._numerator, divided._denominator)
    def __float__(self):
        return float(self.x/self.y)
    def __int__(self):
        return int(self.x/self.y)
    def __mul__(self, other):
        if not isinstance(other, (int, float)):
            simplified = Fraction(self.x * other.x, self.y * other.y)
            return Rational(simplified._numerator, simplified._denominator)
        multiplied = Fraction(self.x,self.y) * Fraction(other)
        return Rational(Fraction(multiplied)._numerator, Fraction(multiplied)._denominator)
    def __add__(self, other):
        added = Fraction(self.x,self.y) + Fraction(other.x, other.y)
        return Rational(Fraction(added)._numerator, Fraction(added)._denominator)
    def __sub__(self, other):
        subbed = Fraction(self.x,self.y) - Fraction(other.x, other.y)
        return Rational(Fraction(subbed)._numerator, Fraction(subbed)._denominator)
    def __truediv__(self, other):
        if not isinstance(other, (int, float)):
            divided = Fraction(other.x,other.y)/Fraction(self.x,self.y)
            return Rational(Fraction(divided)._numerator, Fraction(divided)._denominator)
        divided = Fraction(self.x,self.y) / Fraction(other)
        return Rational(Fraction(divided)._numerator, Fraction(divided)._denominator)
    def __rtruediv__(self, other):
        if not isinstance(other, (int, float)):
            divided = Fraction(other.x, other.y) / Fraction(self.x, self.y)
            return Rational(Fraction(divided)._numerator, Fraction(divided)._denominator)
        fraction1 = Fraction(self.x, self.y)
        faction2 = Fraction(other)
        divided = faction2 / fraction1
        return Rational(Fraction(divided)._numerator, Fraction(divided)._denominator)
    def __neg__(self):
        return Rational(-self.x,self.y)
    def __lt__(self, other):
        fraction2 = Fraction(other.x, other.y)
        fraction1 = Fraction(self.x,self.y)
        if fraction2 < fraction1:
            return False
        elif fraction1 < fraction2:
            return True
        else: 
            return NotImplemented
    def __eq__(self, other):
        if self.x == other.x:
            if self.y == other.y:
                return True
        else:
            return False

class Node:
    def __init__(self, graph: 'Graph', name: str, op: str, target: Target,
                 args: Tuple[Argument, ...], kwargs: Dict[str, Argument],
                 type : Optional[Any] = None) -> None:
        self.graph = graph
        self.name = name  
        assert op in ['placeholder', 'call_method', 'call_module', 'call_function', 'get_attr', 'output', 'root']
        self.op = op  
        if op in ['call_method', 'call_module']:
            assert isinstance(target, str)
        self.target = target  
        self._uses : Dict[Node, None] = {}
        self._update_args_kwargs(map_arg(args, lambda x: x), map_arg(kwargs, lambda x: x))  
        self.users : Dict['Node', None] = {}
        self.type : Optional[Any] = type
        self._prev = self
        self._next = self
        self._erased = False
    @property
    def next(self) -> 'Node':
        return self._next
    @property
    def prev(self) -> 'Node':
        return self._prev
    def prepend(self, x: 'Node'):
        assert self.graph == x.graph, "Attempting to move a Node into a different Graph"
        x._remove_from_list()
        p = self._prev
        p._next, x._prev = x, p
        x._next, self._prev = self, x
    def append(self, x: 'Node'):
        self._next.prepend(x)
    def _remove_from_list(self):
        p, n = self._prev, self._next
        p._next, n._prev = n, p
    @property
    def args(self) -> Tuple[Argument, ...]:
        return self._args
    @args.setter
    def args(self, a : Tuple[Argument, ...]):
        self._update_args_kwargs(map_arg(a, lambda x: x), self._kwargs)  
    @property
    def kwargs(self) -> Dict[str, Argument]:
        return self._kwargs
    @kwargs.setter
    def kwargs(self, k : Dict[str, Argument]):
        self._update_args_kwargs(self._args, map_arg(k, lambda x: x))  
    def _update_args_kwargs(self, new_args : Tuple[Argument, ...], new_kwargs : Dict[str, Argument]):
        self._args = new_args
        self._kwargs = new_kwargs
        for old_use in self._uses.keys():
            old_use.users.pop(self)
        self._uses = {}
        map_arg(self._args, lambda n: self._uses.setdefault(n))
        map_arg(self._kwargs, lambda n: self._uses.setdefault(n))
        for new_use in self._uses.keys():
            new_use.users.setdefault(self)
    def __repr__(self) -> str:
        return self.name
    def replace_all_uses_with(self, replace_with : 'Node') -> List['Node']:
        to_process = list(self.users)
        for use_node in to_process:
            def maybe_replace_node(n : Node) -> Node:
                if n == self:
                    return replace_with
                else:
                    return n
            new_args = map_arg(use_node.args, maybe_replace_node)
            new_kwargs = map_arg(use_node.kwargs, maybe_replace_node)
            assert isinstance(new_args, tuple)
            assert isinstance(new_kwargs, dict)
            use_node._update_args_kwargs(new_args, new_kwargs)
        assert len(self.users) == 0
        return to_process

class StringMixin(object):
    def __unicode__(self):
        raise NotImplementedError
    def __str__(self):
        if compat.PY3:
            return self.__unicode__()
        return self.__bytes__()
    def __bytes__(self):
        from pandas.core.config import get_option
        encoding = get_option("display.encoding")
        return self.__unicode__().encode(encoding, 'replace')
    def __repr__(self):
        return str(self)

