class CachedProperty(misc_tools.OwnNameDiscoveringDescriptor):
    def __init__(self, getter_or_value, doc=None, name=None,
                 force_value_not_getter=False):
        misc_tools.OwnNameDiscoveringDescriptor.__init__(self, name=name)
        if callable(getter_or_value) and not force_value_not_getter:
            self.getter = getter_or_value
        else:
            self.getter = lambda thing: getter_or_value
        self.__doc__ = doc or getattr(self.getter, '__doc__', None)
    def __get__(self, thing, our_type=None):
        if thing is None:
            return self
        value = self.getter(thing)
        setattr(thing, self.get_our_name(thing, our_type=our_type), value)
        return value
    def __call__(self, method_function):
        def inner(same_method_function, self_obj, *args, **kwargs):
            with getattr(self_obj, self.get_our_name(self_obj)):
                return method_function(self_obj, *args, **kwargs)
        return decorator_tools.decorator(inner, method_function)
    def __repr__(self):
        return '<%s: %s>' % (type(self).__name__, self.our_name or self.getter)

class Version(object):
  _DEFAULT_EXPERIMENTS = {
      Experiment.DUMMY: False,
  }
  def __init__(
      self,
      version: Union["Version", str],
      experiments=None,
      tfds_version_to_prepare=None,
  ):
    if isinstance(version, Version):
      version_str = str(version)
      experiments = experiments or version._experiments
      tfds_version_to_prepare = (
          tfds_version_to_prepare or version.tfds_version_to_prepare)
    else:
      version_str = version
    self._experiments = self._DEFAULT_EXPERIMENTS.copy()
    self.tfds_version_to_prepare = tfds_version_to_prepare
    if experiments:
      if isinstance(experiments, str):
        raise ValueError(
            f"Invalid Version('{version}', '{experiments}'). Description is "
            "deprecated. RELEASE_NOTES should be used instead.")
      self._experiments.update(experiments)
    self.major, self.minor, self.patch = _str_to_version(version_str)
  def implements(self, experiment):
    return self._experiments[experiment]
  def __str__(self):
    return "{}.{}.{}".format(*self.tuple)
  def __repr__(self) -> str:
    return f"{type(self).__name__}(\'{str(self)}\')"
  @property
  def tuple(self):
    return self.major, self.minor, self.patch
  def _validate_operand(self, other):
    if isinstance(other, six.string_types):
      return Version(other)
    elif isinstance(other, Version):
      return other
    raise AssertionError("{} (type {}) cannot be compared to version.".format(
        other, type(other)))
  def __eq__(self, other):
    other = self._validate_operand(other)
    return self.tuple == other.tuple
  def __ne__(self, other):
    other = self._validate_operand(other)
    return self.tuple != other.tuple
  def __lt__(self, other):
    other = self._validate_operand(other)
    return self.tuple < other.tuple
  def __le__(self, other):
    other = self._validate_operand(other)
    return self.tuple <= other.tuple
  def __gt__(self, other):
    other = self._validate_operand(other)
    return self.tuple > other.tuple
  def __ge__(self, other):
    other = self._validate_operand(other)
    return self.tuple >= other.tuple
  def __hash__(self) -> int:
    return hash(self.tuple)
  def match(self, other_version):
    major, minor, patch = _str_to_version(other_version, allow_wildcard=True)
    return (major in [self.major, "*"] and minor in [self.minor, "*"] and
            patch in [self.patch, "*"])
  @classmethod
  def is_valid(cls, version: str) -> bool:
    try:
      return cls(version) and True
    except ValueError:  
      return False

class Item:
    cache = None
    key = None
    value = None
    def __str__(self):
        if self.value is not None:
            return self.value
        if self.key is not None:
            return "IronCache Item '%s'" % self.key
        if self.cache is not None:
            return "IronCache Item in Cache '%s'" % self.cache
        return "IronCache item"
    def __repr__(self):
        if self.value is not None:
            if self.cache is not None and self.key is not None:
                return "%s[%s]: %s" % (self.cache, self.key, self.value)
            elif self.cache is None:
                return "%s: %s" % (self.key, self.value)
            else:
                return "%s" % self.value
        else:
            return "IronCache Item"
    def __init__(self, values={}, **kwargs):
        for k in kwargs.keys():
            values[k] = kwargs[k]
        for prop in values.keys():
            if prop == "cache":
                self.cache = values["cache"]
            elif prop == "key":
                self.key = values["key"]
            elif prop == "value":
                self.value = values["value"]

