        translate_polymorphic_filter_definitions_in_args(self.model, args) 
        additional_args = translate_polymorphic_filter_definitions_in_kwargs(self.model, kwargs) 
        return super(PolymorphicQuerySet, self)._filter_or_exclude(negate, *(list(args) + additional_args), **kwargs)
