class Angle(float):
    def __new__(cls, val, mapper=lambda x : x):
        if val is None:             
            return super(Angle, cls).__new__(cls, 'NaN')
        if isinstance(val,Angle):   
            return val
        return super(Angle, cls).__new__(cls, mapper(val))
    def __str__(self):
        if math.isnan(self):
            return '(no angle)'
        return '{:f} deg'.format(float(self))
    def __repr__(self):
        return self.__str__()
    identity = staticmethod(lambda x : x)
    none = staticmethod(lambda x : Angle('NaN'))
    @staticmethod
    def fixed(x):
        return lambda y : x
    @staticmethod
    def shifted(d):
        return lambda x : x + d
    @staticmethod
    def transform(dict_like, angle_variable='angle', angle_mapper='angle_mapper', mask_key_error=True):
      try:
        if angle_variable in dict_like and angle_mapper in dict_like:
            dict_like[angle_variable] = Angle(dict_like[angle_variable], dict_like[angle_mapper])
        if dict_like[angle_variable] is None:
            del dict_like[angle_variable]
        return dict_like
      except KeyError:
        if mask_key_error:
          return dict_like
        else:
          raise

class Token(object):
    def __init__(self, _type, value):
        self.type = _type
        self.value = value
    def append(self, val):
        self.value.append(val)
    def to_xml(self):
        if isinstance(self.value, list):
            assert all(isinstance(child, Token) for child in self.value)
            children = ''.join(
                '\n'.join(
                    ('  ' + line if line else line) 
                    for line in token.to_xml().split('\n')
                )
                for token in self.value
            )
            if children:            
                return '<{type}>\n{children}</{type}>\n'.format(
                    type=self.type, children=children
                )
            else:
                return '<{type}>\n</{type}>\n'.format(type=self.type)
        else:
            value = (self.value
                .replace('&', '&amp;')
                .replace('>', '&gt;')
                .replace('<', '&lt;')
                .replace('"', ' &quot;')
            )
            return '<{type}> {value} </{type}>\n'.format(
                type=self.type, value=value
            )
    def __repr__(self):
        return '< {} {} >'.format(self.type, self.value)
    def __eq__(self, other):
        return (
            self.type == other.type and 
            self.value == other.value
        )
    def __ne__(self, other):
        return not self.__eq__(other)
    def __hash__(self):
        return id(self)

class SearchNode:
    def __init__(self,state: OptimizedMap, parent, depth, heuristic_grid, next_move = None):
        self.state = state
        self.parent = parent
        self.depth = depth
        self.next_move = next_move
        self.heuristic = self.apply_heuristic_grid(heuristic_grid) + self.depth*0.2
    def apply_heuristic_grid(self, heuristic_grid):
        heuristic = 0
        for box in self.state.boxes:
            if box in heuristic_grid:
                heuristic += heuristic_grid[box]
        return heuristic
    def manhatan_distance(self):
        distance = 0
        radius = 2
        for box in self.state.boxes:
