    def __ne__(self, qns):
        return not self == qns
    def __le__(self, qns):
        try:
            for qn in self:
                if qns[qn] != self[qn]:
                    return False
            return True
        except:
            return False
    def __ge__(self, qns):
        try:
            for qn in qns:
                if qns[qn] != self[qn]:
                    return False
            return True
        except:
            return False
