class fraction:
    def __init__(self,numer,denom):
        self.numer = numer
        self.denom = denom
    def prnt(self):
        return "출력 : " + str(self.denom) + "/" + str(self.numer)
    def __str__(self):
        return "출력 : "+str(self.denom)+"/"+str(self.numer)
    def __add__(self,other):
        add = self.numer * other.denom + self.denom * other.numer
        c = self.numer * other.numer
        if(add == 0):
            return fraction(0,0)
        for i in range(2,c):
            if(add%i == 0 and c%i == 0):
                add = add//i
                c = c//i
                i = 2
        s = fraction(c,add)
        return s
    def __sub__(self, other):
        sub = self.denom * other.numer - self.numer * other.denom
        c = self.numer * other.numer
        if (sub == 0):
            return fraction(0,0)
        for i in range(2,c):
            if(sub%i == 0 and c%i == 0):
                sub = sub//i
                c = c//i
                i = 2
        s = fraction(c, sub)
        return s
    def  __eq__(self, other):
        if(self.denom * other.numer == self.numer * other.denom):
            return True
        else:
            return False
    def __ne__(self, other):
        if (self.denom * other.numer != self.numer * other.denom):
            return True
        else:
            return False
    def __lt__(self, other):
        if (self.denom * other.numer < self.numer * other.denom):
            return True
        else:
            return False
    def __gt__(self, other):
        if (self.denom * other.numer > self.numer * other.denom):
            return True
        else:
            return False

class Vim:
    def __init__(self,
                 protocol="https",
                 host="localhost"):
        if not suds:
            raise Exception(_("Unable to import suds."))
        self._protocol = protocol
        self._host_name = host
        self.wsdl_url = Vim.get_wsdl_url(protocol, host)
        self.url = Vim.get_soap_url(protocol, host)
        self.client = suds.client.Client(self.wsdl_url, location=self.url,
                                         plugins=[VIMMessagePlugin()])
        self._service_content = self.retrieve_service_content()
    def retrieve_service_content(self):
        return self.RetrieveServiceContent("ServiceInstance")
    @staticmethod
    def get_wsdl_url(protocol, host_name):
        if CONF.vmware.wsdl_location:
            return CONF.vmware.wsdl_location
        return Vim.get_soap_url(protocol, host_name) + "/vimService.wsdl"
    @staticmethod
    def get_soap_url(protocol, host_name):
        if utils.is_valid_ipv6(host_name):
            return '%s://[%s]/sdk' % (protocol, host_name)
        return '%s://%s/sdk' % (protocol, host_name)
    def get_service_content(self):
        return self._service_content
    def __getattr__(self, attr_name):
        def vim_request_handler(managed_object, **kwargs):
            try:
                request_mo = self._request_managed_object_builder(
                             managed_object)
                request = getattr(self.client.service, attr_name)
                response = request(request_mo, **kwargs)
                if hasattr(error_util.FaultCheckers,
                                attr_name.lower() + "_fault_checker"):
                    fault_checker = getattr(error_util.FaultCheckers,
                                attr_name.lower() + "_fault_checker")
                    fault_checker(response)
                return response
            except error_util.VimFaultException:
                raise
            except suds.MethodNotFound:
                raise
            except suds.WebFault as excep:
                doc = excep.document
                detail = doc.childAtPath("/Envelope/Body/Fault/detail")
                fault_list = []
                for child in detail.getChildren():
                    fault_list.append(child.get("type"))
                raise error_util.VimFaultException(fault_list, excep)
            except AttributeError as excep:
                raise error_util.VimAttributeError(_("No such SOAP method "
                     "'%s' provided by VI SDK") % (attr_name), excep)
            except (httplib.CannotSendRequest,
                    httplib.ResponseNotReady,
                    httplib.CannotSendHeader) as excep:
                raise error_util.SessionOverLoadException(_("httplib "
                                "error in %s: ") % (attr_name), excep)
            except (urllib2.URLError,
                    urllib2.HTTPError) as excep:
                raise error_util.SessionConnectionException(_("urllib2 "
                            "error in  %s: ") % (attr_name), excep)
            except Exception as excep:
                if (str(excep).find(ADDRESS_IN_USE_ERROR) != -1 or
                        str(excep).find(CONN_ABORT_ERROR)) != -1:
                    raise error_util.SessionOverLoadException(_("Socket "
                                "error in %s: ") % (attr_name), excep)
                elif str(excep).find(RESP_NOT_XML_ERROR) != -1:
                    raise error_util.SessionOverLoadException(_("Type "
                                "error in  %s: ") % (attr_name), excep)
                else:
                    raise error_util.VimException(
                       _("Exception in %s ") % (attr_name), excep)
        return vim_request_handler
    def _request_managed_object_builder(self, managed_object):
        if isinstance(managed_object, str):
            mo = suds.sudsobject.Property(managed_object)
            mo._type = managed_object
        else:
            mo = managed_object
        return mo
    def __repr__(self):
        return "VIM Object"
    def __str__(self):
        return "VIM Object"

class Program(object):
    def __init__(self):
        self.rules = {}
    def __repr__(self):
        unsortedKeys = list(self.rules.keys())
        sortedKeys = sorted(unsortedKeys)
        fullSt = ""
        for i in sortedKeys:
            fullSt = fullSt + str(i[0]) + " " + str(i[1]) + " -> " + \
                self.rules[i][0] + " " + str(self.rules[i][1]) + '\n'
        return fullSt
    def randomize(self):
        for i in range(NUMSTATES):
            for mnorth in ["N", "x"]:
                for meast in ["E", "x"]:
                    for mwest in ["W", "x"]:
                        for msouth in ["S", "x"]:
                            tPossibilities = ["X"]
                            if mnorth == "x":
                                tPossibilities += ["N"]
                            if meast == "x":
                                tPossibilities += ["E"]
                            if mwest == "x":
                                tPossibilities += ["W"]
                            if msouth == "x":
                                tPossibilities += ["S"]
                            self.rules[(i, mnorth + meast + mwest + msouth)] = \
                                 (random.choice(tPossibilities), random.choice(range(NUMSTATES))) 
    def getMove(self, state, surroundings):
        return self.rules[(state, surroundings)]
    def mutate(self):
        changeKey = random.choice( list(self.rules.keys()))
        currentVal = self.rules[changeKey]
        tPossibilities = ["X"]
        if changeKey[1][0] == "x":
            tPossibilities += ["N"]
        if changeKey[1][1] == "x":
            tPossibilities += ["E"]
        if changeKey[1][2] == "x":
            tPossibilities += ["W"]
        if changeKey[1][3] == "x":
            tPossibilities += ["S"]
        t = currentVal
        while t == currentVal:
            t = (random.choice(tPossibilities), random.choice(range(NUMSTATES)))
        self.rules[changeKey] = t
    def __gt__(self, other):
        return random.choice([True, False])
    def __lt__(self, other):
        return random.choice([True, False])

class World: 
    def __init__(self, initial_row, initial_col, program):
        self.row = initial_row                                  
        self.col = initial_col                                  
        self.state = 0                                          
        self.prog = program                                     
        self.room = [[' ']*WIDTH for row in range(HEIGHT)]      
        self.room[initial_row][initial_col] = "P"
    def __repr__(self):
        nstring = ""
        nstring += " " + "-" * WIDTH + "\n"
        for row in range(HEIGHT):
            nstring += "|"
            for colv in range(WIDTH):
                nstring += self.room[row][colv]
            nstring += '|\n'
        nstring += " " + "-" * WIDTH
        return nstring
    def getCurrentSurroundings(self):
        outstr = ""
        if self.row != 0:
            if self.room[self.row -1][self.col] == "+":
                outstr += "N"
            else:
                outstr += "x"
        else:
            outstr += "N"
        if self.col != (WIDTH - 1):
            if self.room[self.row][self.col +1] == "+":
                outstr += "E"
            else:
                outstr += "x"
        else:
            outstr += "E"
        if self.col != 0:
            if self.room[self.row][self.col - 1] == "+":
                outstr += "W"
            else:
                outstr += "x"
        else:
            outstr += "W"
        if self.row != (HEIGHT - 1):
            if self.room[self.row + 1][self.col] == "+":
                outstr += "S"
            else:
                outstr += "x"
        else:
            outstr += "S"
        return outstr
    def step (self): 
        self.room[self.row][self.col] = "o"
        nextpos = self.prog.getMove(self.state, self.getCurrentSurroundings())
        self.state = nextpos[1]
        if nextpos[0] == "N":
            self.row -= 1
        if nextpos[0] == "E":
            self.col += 1
        if nextpos[0] == "W":
            self.col -= 1
        if nextpos[0] == "S":
            self.row += 1
        self.room[self.row][self.col] = "P"
    def run(self, steps):
        for i in range(steps):
            self.step()
    def fractionVisitedCells(self):
        visited = 0
        freecells = 0
        for row in range(HEIGHT):
            for col in range(WIDTH):
                if self.room[row][col] == "o":
                    visited += 1
                elif self.room[row][col] == " ":
                    freecells += 1
        return visited / (visited + freecells)

