class Body:
    def __init__(self, part: email.message.Message):
        self.content_type = part.get_content_type()
        self.charsets = [part.get_content_charset()]  
        parent_charset = part.get_charsets()[0]
        if parent_charset and parent_charset != self.charsets[0]:
            self.charsets.append(
                parent_charset
            )  
        self.character_set = None
        self.string: typing.Optional[str] = None
        self.flowed = "format=flowed" in part.get("content-type", "")
        self.bytes = part.get_payload(decode=True)
        self.html_as_source = False
        if self.bytes is not None:
            valid_encodings = [x for x in self.charsets if x]
            if valid_encodings:
                for cs in valid_encodings:
                    try:
                        self.string = self.bytes.decode(cs)
                        self.character_set = str(cs)
                        break
                    except UnicodeDecodeError:
                        pass
            if not self.string:
                try:
                    self.string = self.bytes.decode("us-ascii", errors="strict")
                    if valid_encodings:
                        self.character_set = "us-ascii"
                except UnicodeDecodeError:
                    self.string = self.bytes.decode(DEFAULT_CHARACTER_SET, "replace")
    def __repr__(self):
        return self.string
    def __len__(self):
        return len(self.string or "")
    def assign(self, new_string):
        self.string = new_string
    def encode(self, encoding=DEFAULT_CHARACTER_SET, errors="strict"):
        return self.string.encode(encoding=encoding, errors=errors)
    def unflow(self, convert_lf=False):
        if self.string:
            if self.flowed:
                character_set = self.character_set or DEFAULT_CHARACTER_SET
                if convert_lf:
                    fixed_string = "\r\n".join(
                        [x.rstrip("\r") for x in self.string.split("\n")]
                    )
                    conversion_was_needed = fixed_string != self.string
                else:
                    fixed_string = self.string
                flow_fixed = formatflowed.convertToWrapped(
                    fixed_string.encode(character_set, errors="ignore"),
                    wrap_fixed=False,
                    character_set=character_set,
                )
                if convert_lf and conversion_was_needed:
                    flow_fixed = "\n".join(
                        [x.rstrip("\r") for x in self.string.split("\n")]
                    )
                return flow_fixed
        return self.string

class Computer(object):
    def __init__(self, name, *args, **kwargs):
        self.name = name
        self.fs = filesystem.Directory()
        self.game = kwargs.get('game', None)
        self.ports = getattr(kwargs, 'ports', {})
        self.users = getattr(kwargs, 'users', {})
    def get_shell(self, user, agent=None):
        return shell.Shell(self, user, agent=agent, game=self.game)
    def open_port(self, ports):
        for port_no, service in ports.items():
            if port_no in self.ports.keys():
                self.ports[port_no] = service
            else:
                self.ports.update({port_no: service})
    def add_user(self, username):
        self.users.update({username:User(username)})
    def get_user(self, username):
        try:
            return self.users[username]
        except KeyError:
            return None
    def login(self, username, password):
        try:
            if self.users[username].password == password:
                return True
            else:
                return False
        except KeyError:
            return None
    def __repr__(self):
        return self.name
    __str__ = __repr__

class User:
    def __init__(self, name, password=None):
        self.name = name
        self.password = password or funfunctions.passwordRandomizer()
    def changePassword(self, password):
        self.password = password
    def __repr__(self):
        return self.name
    __str__ = __repr__

class Expr(object):
    def __init__(self, op, *args):
        self.op = str(op)
        self.args = args
        self.__hash = None
    def __neg__(self):      return Expr('-', self)
    def __pos__(self):      return Expr('+', self)
    def __invert__(self):   return Expr('~', self)
    def __add__(self, rhs): return Expr('+', self, rhs)
    def __sub__(self, rhs): return Expr('-', self, rhs)
    def __mul__(self, rhs): return Expr('*', self, rhs)
    def __pow__(self, rhs): return Expr('**',self, rhs)
    def __mod__(self, rhs): return Expr('%', self, rhs)
    def __and__(self, rhs): return Expr('&', self, rhs)
    def __xor__(self, rhs): return Expr('^', self, rhs)
    def __rshift__(self, rhs):   return Expr('>>', self, rhs)
    def __lshift__(self, rhs):   return Expr('<<', self, rhs)
    def __truediv__(self, rhs):  return Expr('/',  self, rhs)
    def __floordiv__(self, rhs): return Expr('//', self, rhs)
    def __matmul__(self, rhs):   return Expr('@',  self, rhs)
    def __or__(self, rhs):
        "Allow both P | Q, and P |'==>'| Q."
        if isinstance(rhs, Expression):
            return Expr('|', self, rhs)
        else:
            return PartialExpr(rhs, self)
    def __radd__(self, lhs): return Expr('+',  lhs, self)
    def __rsub__(self, lhs): return Expr('-',  lhs, self)
    def __rmul__(self, lhs): return Expr('*',  lhs, self)
    def __rdiv__(self, lhs): return Expr('/',  lhs, self)
    def __rpow__(self, lhs): return Expr('**', lhs, self)
    def __rmod__(self, lhs): return Expr('%',  lhs, self)
    def __rand__(self, lhs): return Expr('&',  lhs, self)
    def __rxor__(self, lhs): return Expr('^',  lhs, self)
    def __ror__(self, lhs):  return Expr('|',  lhs, self)
    def __rrshift__(self, lhs):   return Expr('>>',  lhs, self)
    def __rlshift__(self, lhs):   return Expr('<<',  lhs, self)
    def __rtruediv__(self, lhs):  return Expr('/',  lhs, self)
    def __rfloordiv__(self, lhs): return Expr('//',  lhs, self)
    def __rmatmul__(self, lhs):   return Expr('@', lhs, self)
    def __call__(self, *args):
        "Call: if 'f' is a Symbol, then f(0) == Expr('f', 0)."
        if self.args:
            raise ValueError('can only do a call for a Symbol, not an Expr')
        else:
            return Expr(self.op, *args)
    def __eq__(self, other):
        "'x == y' evaluates to True or False; does not build an Expr."
        return (isinstance(other, Expr)
                and self.op == other.op
                and self.args == other.args)
    def __hash__(self):
        self.__hash = self.__hash or hash(self.op) ^ hash(self.args)
        return self.__hash
    def __repr__(self):
        op = self.op
        args = [str(arg) for arg in self.args]
        if op.isidentifier():       
            return '{}({})'.format(op, ', '.join(args)) if args else op
        elif len(args) == 1:        
            return op + args[0]
        else:                       
            opp = (' ' + op + ' ')
            return '(' + opp.join(args) + ')'

class PartialExpr:
    def __init__(self, op, lhs): self.op, self.lhs = op, lhs
    def __or__(self, rhs):       return Expr(self.op, self.lhs, rhs)
    def __repr__(self):          return "PartialExpr('{}', {})".format(self.op, self.lhs)

class CBlockLocator():
    def __init__(self):
        self.nVersion = MY_VERSION
        self.vHave = []
    def deserialize(self, f):
        self.nVersion = struct.unpack("<i", f.read(4))[0]
        self.vHave = deser_uint256_vector(f)
    def serialize(self):
        r = b""
        r += struct.pack("<i", self.nVersion)
        r += ser_uint256_vector(self.vHave)
        return r
    def __repr__(self):
        return "CBlockLocator(nVersion=%i vHave=%s)" \
            % (self.nVersion, repr(self.vHave))

class COutPoint():
    def __init__(self, hash=0, n=0):
        self.hash = hash
        self.n = n
    def deserialize(self, f):
        self.hash = deser_uint256(f)
        self.n = struct.unpack("<I", f.read(4))[0]
    def serialize(self):
        r = b""
        r += ser_uint256(self.hash)
        r += struct.pack("<I", self.n)
        return r
    def serialize_uniqueness(self):
        r = b""
        r += struct.pack("<I", self.n)
        r += ser_uint256(self.hash)
        return r
    def deserialize_uniqueness(self, f):
        self.n = struct.unpack("<I", f.read(4))[0]
        self.hash = deser_uint256(f)
    def __repr__(self):
        return "COutPoint(hash=%064x n=%i)" % (self.hash, self.n)

class CTxIn():
    def __init__(self, outpoint=None, scriptSig=b"", nSequence=0):
        if outpoint is None:
            self.prevout = COutPoint()
        else:
            self.prevout = outpoint
        self.scriptSig = scriptSig
        self.nSequence = nSequence
    def deserialize(self, f):
        self.prevout = COutPoint()
        self.prevout.deserialize(f)
        self.scriptSig = deser_string(f)
        self.nSequence = struct.unpack("<I", f.read(4))[0]
    def serialize(self):
        r = b""
        r += self.prevout.serialize()
        r += ser_string(self.scriptSig)
        r += struct.pack("<I", self.nSequence)
        return r
    def __repr__(self):
        return "CTxIn(prevout=%s scriptSig=%s nSequence=%i)" \
            % (repr(self.prevout), bytes_to_hex_str(self.scriptSig),
               self.nSequence)
    def is_zerocoinspend(self):
        return bytes_to_hex_str(self.scriptSig)[:2] == "c2"

class CTxOut():
    def __init__(self, nValue=0, scriptPubKey=b""):
        self.nValue = nValue
        self.scriptPubKey = scriptPubKey
    def deserialize(self, f):
        self.nValue = struct.unpack("<q", f.read(8))[0]
        self.scriptPubKey = deser_string(f)
    def serialize(self):
        r = b""
        r += struct.pack("<q", self.nValue)
        r += ser_string(self.scriptPubKey)
        return r
    def __repr__(self):
        return "CTxOut(nValue=%i.%08i scriptPubKey=%s)" \
            % (self.nValue // COIN, self.nValue % COIN,
               bytes_to_hex_str(self.scriptPubKey))

class CTransaction():
    def __init__(self, tx=None):
        if tx is None:
            self.nVersion = 1
            self.vin = []
            self.vout = []
            self.nLockTime = 0
            self.sha256 = None
            self.hash = None
        else:
            self.nVersion = tx.nVersion
            self.vin = copy.deepcopy(tx.vin)
            self.vout = copy.deepcopy(tx.vout)
            self.nLockTime = tx.nLockTime
            self.sha256 = tx.sha256
            self.hash = tx.hash
    def deserialize(self, f):
        self.nVersion = struct.unpack("<i", f.read(4))[0]
        self.vin = deser_vector(f, CTxIn)
        flags = 0
        if len(self.vin) == 0:
            flags = struct.unpack("<B", f.read(1))[0]
            if (flags != 0):
                self.vin = deser_vector(f, CTxIn)
                self.vout = deser_vector(f, CTxOut)
        else:
            self.vout = deser_vector(f, CTxOut)
        self.nLockTime = struct.unpack("<I", f.read(4))[0]
        self.sha256 = None
        self.hash = None
    def serialize_without_witness(self):
        r = b""
        r += struct.pack("<i", self.nVersion)
        r += ser_vector(self.vin)
        r += ser_vector(self.vout)
        r += struct.pack("<I", self.nLockTime)
        return r
    def serialize(self):
        return self.serialize_without_witness()
    def rehash(self):
        self.sha256 = None
        self.calc_sha256()
    def calc_sha256(self, with_witness=False):
        if self.sha256 is None:
            self.sha256 = uint256_from_str(hash256(self.serialize_without_witness()))
        self.hash = encode(hash256(self.serialize_without_witness())[::-1], 'hex_codec').decode('ascii')
    def is_valid(self):
        self.calc_sha256()
        for tout in self.vout:
            if tout.nValue < 0 or tout.nValue > 21000000 * COIN:
                return False
        return True
    def is_coinbase(self):
        return (
                len(self.vin) == 1 and
                self.vin[0].prevout == NullOutPoint and
                (not self.vin[0].is_zerocoinspend())
        )
    def is_coinstake(self):
        return (
                len(self.vin) == 1 and
                len(self.vout) >= 2 and
                self.vout[0] == CTxOut()
        )
    def from_hex(self, hexstring):
        f = BytesIO(hex_str_to_bytes(hexstring))
        self.deserialize(f)
    def spends(self, outpoint):
        return len([x for x in self.vin if
                    x.prevout.hash == outpoint.hash and x.prevout.n == outpoint.n]) > 0
    def __repr__(self):
        return "CTransaction(nVersion=%i vin=%s vout=%s nLockTime=%i)" \
            % (self.nVersion, repr(self.vin), repr(self.vout), self.nLockTime)

class CBlock(CBlockHeader):
    def __init__(self, header=None):
        super(CBlock, self).__init__(header)
        self.vtx = []
        self.sig_key = None     
    def deserialize(self, f):
        super(CBlock, self).deserialize(f)
        self.vtx = deser_vector(f, CTransaction)
        self.sig_key = None
    def serialize(self, with_witness=False):
        r = b""
        r += super(CBlock, self).serialize()
        if with_witness:
            r += ser_vector(self.vtx, "serialize_with_witness")
        else:
            r += ser_vector(self.vtx, "serialize_without_witness")
            if hasattr(self, 'vchBlockSig'):
                r += ser_string(self.vchBlockSig)
        return r
    @classmethod
    def get_merkle_root(cls, hashes):
        while len(hashes) > 1:
            newhashes = []
            for i in range(0, len(hashes), 2):
                i2 = min(i+1, len(hashes)-1)
                newhashes.append(hash256(hashes[i] + hashes[i2]))
            hashes = newhashes
        return uint256_from_str(hashes[0])
    def calc_merkle_root(self):
        hashes = []
        for tx in self.vtx:
            tx.calc_sha256()
            hashes.append(ser_uint256(tx.sha256))
        return self.get_merkle_root(hashes)
    def calc_witness_merkle_root(self):
        hashes = [ser_uint256(0)]
        for tx in self.vtx[1:]:
            hashes.append(ser_uint256(tx.calc_sha256(True)))
        return self.get_merkle_root(hashes)
    def is_valid(self):
        self.calc_sha256()
        target = uint256_from_compact(self.nBits)
        if self.sha256 > target:
            return False
        for tx in self.vtx:
            if not tx.is_valid():
                return False
        if self.calc_merkle_root() != self.hashMerkleRoot:
            return False
        return True
    def solve(self):
        self.rehash()
        target = uint256_from_compact(self.nBits)
        while self.sha256 > target:
            self.nNonce += 1
            self.rehash()
    def sign_block(self, key, low_s=True):
        data = b""
        data += struct.pack("<i", self.nVersion)
        data += ser_uint256(self.hashPrevBlock)
        data += ser_uint256(self.hashMerkleRoot)
        data += struct.pack("<I", self.nTime)
        data += struct.pack("<I", self.nBits)
        data += struct.pack("<I", self.nNonce)
        sha256NoSig = hash256(data)
        self.vchBlockSig = key.sign(sha256NoSig, low_s=low_s)
        self.sig_key = key
        self.low_s = low_s
    def re_sign_block(self):
        if self.sig_key == None:
            raise Exception("Unable to re-sign block. Key Not present, use 'sign_block' first.")
        return self.sign_block(self.sig_key, self.low_s)
    def __repr__(self):
        return "CBlock(nVersion=%i hashPrevBlock=%064x hashMerkleRoot=%064x nTime=%s nBits=%08x nNonce=%08x vtx=%s)" \
            % (self.nVersion, self.hashPrevBlock, self.hashMerkleRoot,
               time.ctime(self.nTime), self.nBits, self.nNonce, repr(self.vtx))

class PrefilledTransaction():
    def __init__(self, index=0, tx = None):
        self.index = index
        self.tx = tx
    def deserialize(self, f):
        self.index = deser_compact_size(f)
        self.tx = CTransaction()
        self.tx.deserialize(f)
    def serialize(self, with_witness=True):
        r = b""
        r += ser_compact_size(self.index)
        if with_witness:
            r += self.tx.serialize_with_witness()
        else:
            r += self.tx.serialize_without_witness()
        return r
    def serialize_without_witness(self):
        return self.serialize(with_witness=False)
    def serialize_with_witness(self):
        return self.serialize(with_witness=True)
    def __repr__(self):
        return "PrefilledTransaction(index=%d, tx=%s)" % (self.index, repr(self.tx))

class P2PHeaderAndShortIDs():
    def __init__(self):
        self.header = CBlockHeader()
        self.nonce = 0
        self.shortids_length = 0
        self.shortids = []
        self.prefilled_txn_length = 0
        self.prefilled_txn = []
    def deserialize(self, f):
        self.header.deserialize(f)
        self.nonce = struct.unpack("<Q", f.read(8))[0]
        self.shortids_length = deser_compact_size(f)
        for i in range(self.shortids_length):
            self.shortids.append(struct.unpack("<Q", f.read(6) + b'\x00\x00')[0])
        self.prefilled_txn = deser_vector(f, PrefilledTransaction)
        self.prefilled_txn_length = len(self.prefilled_txn)
    def serialize(self, with_witness=False):
        r = b""
        r += self.header.serialize()
        r += struct.pack("<Q", self.nonce)
        r += ser_compact_size(self.shortids_length)
        for x in self.shortids:
            r += struct.pack("<Q", x)[0:6]
        if with_witness:
            r += ser_vector(self.prefilled_txn, "serialize_with_witness")
        else:
            r += ser_vector(self.prefilled_txn, "serialize_without_witness")
        return r
    def __repr__(self):
        return "P2PHeaderAndShortIDs(header=%s, nonce=%d, shortids_length=%d, shortids=%s, prefilled_txn_length=%d, prefilledtxn=%s" % (repr(self.header), self.nonce, self.shortids_length, repr(self.shortids), self.prefilled_txn_length, repr(self.prefilled_txn))

class BlockTransactionsRequest():
    def __init__(self, blockhash=0, indexes = None):
        self.blockhash = blockhash
        self.indexes = indexes if indexes != None else []
    def deserialize(self, f):
        self.blockhash = deser_uint256(f)
        indexes_length = deser_compact_size(f)
        for i in range(indexes_length):
            self.indexes.append(deser_compact_size(f))
    def serialize(self):
        r = b""
        r += ser_uint256(self.blockhash)
        r += ser_compact_size(len(self.indexes))
        for x in self.indexes:
            r += ser_compact_size(x)
        return r
    def from_absolute(self, absolute_indexes):
        self.indexes = []
        last_index = -1
        for x in absolute_indexes:
            self.indexes.append(x-last_index-1)
            last_index = x
    def to_absolute(self):
        absolute_indexes = []
        last_index = -1
        for x in self.indexes:
            absolute_indexes.append(x+last_index+1)
            last_index = absolute_indexes[-1]
        return absolute_indexes
    def __repr__(self):
        return "BlockTransactionsRequest(hash=%064x indexes=%s)" % (self.blockhash, repr(self.indexes))

