class Hash:
    def __init__(self):
        self.len = 1
        self.table = [set()]
        self.used = 0
    def __repr__(self):
        message = ""
        count = 0
        for i in self.table:
            message += str(count) + ":"
            count += 1
            message += str(i) + "\n"
        return message
    def search(self, e):
        if e:
            for i in self.table:
                if e in i:
                    return True
        return False
    def insert(self, e):
        if e:
            key = int(e % self.len)
            if self.used > 0.75 * self.len:
                self.rehash(self.len * 2)
            self.table[key].add(e)
            self.used += 1
    def delete(self, e):
        if e:
            for i in self.table:
                if e in i:
                    i.remove(e)
                    self.used -= 1
                    return True
        return False
    def rehash(self, new_len):
        print("Rehashing")
        print(self)
        oldTable = self.table
        self.table = []
        self.len = new_len
        for i in range(new_len):
            self.table.append(set())
        for i in oldTable:
            for s in i:
                self.table[int(s % self.len)].add(s)

class Results:
    def __init__(self,
                 observation: dict = None,
                 done: bool = None,
                 reward: float = None,
                 info=None,
                 parameter_mask=None,
                 action_space=None,
                 error: Exception = None,
                 error_msg: str = None,
                 next_observation=None,
                 action=None,
                 action_name: str = None):
        self.observation = observation
        self.next_observation = next_observation
        self.done = done
        self.reward = reward
        self.action = action
        self.info = info
        self.parameter_mask = parameter_mask
        self.action_space = action_space
        self.error = error
        self.error_msg = error_msg
        self.action_name = action_name
        self.selection_masks = None
    def has_error(self):
        return self.error is not None
    def copy(self):
        copy_kwargs = {
            "done": self.done,
            "reward": self.reward,
            "error": deepcopy(self.error),
            "error_msg": deepcopy(self.error_msg),
            "action": deepcopy(self.action),
            "info": deepcopy(self.info),
            "action_space": deepcopy(self.action_space)
        }
        if isinstance(self.observation, Observation):
            copy_kwargs["observation"] = self.observation.copy()
        else:
            copy_kwargs["observation"] = deepcopy(self.observation)
        if isinstance(self.next_observation, Observation):
            copy_kwargs["next_observation"] = self.next_observation.copy()
        else:
            copy_kwargs["next_observation"] = deepcopy(self.next_observation)
        return Results(**copy_kwargs)
    def __str__(self):
        output = [f"{self.__class__.__name__}:"]
        for attr, v in self.__dict__.items():
            if v is None:
                continue
            if isinstance(v, dict):
                v_str = pprint.pformat(v)
            else:
                v_str = str(v)
            output.append(f"{attr}={v_str}")
        return "\n".join(output)
    def __eq__(self, other):
        if not isinstance(other, type(self)):
            return False
        for k, v in self.__dict__.items():
            if k not in other.__dict__:
                return False
            if v != other.__dict__[k]:
                return False
        return True

class Version:
    def __init__(self, version):
        replacement_rules = {"alpha": '0', "beta": '1', "a": '-0', "b": '-1', "rc": '2', "-": '.'}
        for key in replacement_rules.keys():
            version = version.replace(key, replacement_rules[key])
        self.version = version.split('.')
    def __lt__(self, other):
        couples = zip_longest(self.version, other.version, fillvalue='0')
        for first, second in couples:
            first, second = int(first), int(second)
            if first < second:
                return True
            if first > second:
                return False
            if first == second:
                continue
        return False
    def __eq__(self, other):
        couples = zip_longest(self.version, other.version, fillvalue='0')
        for first, second in couples:
            first, second = int(first), int(second)
            if first < second or first > second:
                return False
            if first == second:
                continue
        return True

