class Angle(HeadingBase):
    def __init__(self, theta):
        if theta is None:
            raise ValueError('None is not a valid Angle')
        if isinstance(theta, Heading):
            raise TypeError('Angle required, not Heading')
        if isinstance(theta, Angle):
            theta = theta.theta
        self.theta = theta
    def __str__(self):  
        return str(self.theta)
    def __repr__(self):  
        return 'Angle({})'.format(self.theta)
    def __eq__(self, other):
        other = Angle(other)
        return self.theta == other.theta
    def __gt__(self, other):
        other = Angle(other)
        return self.theta > other.theta
    def __lt__(self, other):
        return not self >= other
    def __add__(self, other):
        other = Angle(other)
        return Angle(self.theta + other.theta)
    def __sub__(self, other):
        other = Angle(other)
        return Angle(self.theta - other.theta)
    def __mul__(self, other):
        return Angle(self.theta * other)
    def __truediv__(self, other):
        return Angle(self.theta / other)
    def __neg__(self):
        return Angle(-self.theta)
    def __abs__(self):
        return Angle(abs(self.theta))
    def __mod__(self, other):
        return Angle(self.theta % other)
    def copy(self):
        return Angle(self.theta)

class Heading(HeadingBase):
    def __init__(self, theta):
        if theta is None:
            raise ValueError('None is not a valid Heading')
        if isinstance(theta, Angle):
            raise TypeError('Heading required, not Angle')
        if isinstance(theta, Heading):
            theta = theta.theta
        self.theta = theta % 360
    def __str__(self):  
        return str(self.theta)
    def __repr__(self):  
        return 'Heading({})'.format(self.theta)
    def __eq__(self, other):
        other = Heading(other)
        return self.theta == other.theta
    def __gt__(self, other):
        if self == other:
            return False
        diff = (self - other).theta
        return 0 < diff <= 180
    def __add__(self, other):
        other = Angle(other)
        return Heading(self.theta + other.theta)
    def __sub__(self, other):
        if isinstance(other, Heading):
            a = self.theta
            b = other.theta
            if a < b:
                a += 360
            return Angle(a - b)
        else:
            other = Angle(other)
            return Heading(self.theta - other.theta)
    def between(self, lo, hi):
        lo = Heading(lo).theta
        mid = self.theta
        hi = Heading(hi).theta
        if lo == hi or mid == lo or mid == hi:
            return False
        if mid < lo:
            mid += 360
            hi += 360
        if hi < mid:
            hi += 360
        return hi - lo < 360
    def angle_to(self, other):
        other = Heading(other)
        angle = other - self
        if angle > 180:
            angle -= 360
        return angle
    def copy(self):
        return Heading(self.theta)
    def flipped_x(self):
        return Heading(180 - self.theta)
    def flipped_y(self):
        return Heading(-self.theta)

