class PandasHash:
    __slots__ = "pandas_object"
    def __init__(self, pandas_object):
        if not isinstance(pandas_object, (pd.DataFrame, pd.Series)):
            raise TypeError("Can only wrap pandas DataFrame or Series objects")
        self.pandas_object = pandas_object
    def __eq__(self, other):
        return hash(self) == hash(other)
    def __hash__(self):
        hashable = tuple(self.pandas_object.values.tobytes())
        if isinstance(self.pandas_object, pd.DataFrame):
            hashable += tuple(self.pandas_object.columns)
        else:
            hashable += tuple(self.pandas_object.name)
        return hash(hashable)

class Module(object):
    def __init__(self, name: str):
        self.name = name
        self.root_command = self._load()
    def __repr__(self):
        return "<Module: {}>".format(self.name)
    @classmethod
    def resolve_alias(cls, module: str) -> str:
        if module in MODULE_ALIASES:
            return MODULE_ALIASES[module]
        return module
    def _load(self) -> Iterable[str]:
        module = self.resolve_alias(self.name)
        try:
            import_string(module)
            return [sys.executable,
                    '-m',
                    'dotops.modules._runner',
                    module]
        except ImportError:
            pass
        raise ModuleNotFound(self.name)
    def exec(self, data, capture=False) -> None:
        cmd = self.root_command + [
            json.dumps(data)
        ]
        logger.info("Running: {}".format(" ".join(cmd)))
        pipe = subprocess.PIPE if capture else None
        subprocess.run(cmd, check=True, stdout=pipe, stderr=pipe)
    def exec_pretty(self, data, capture=None):
        capture = capture or context.get('capture_output', True)
        print(colour.blue | "{}: {}".format(self.name, data),
              end=" " if capture else None)
        if not capture:
            sys.stdout.flush()
        try:
            self.exec(data, capture)
        except subprocess.CalledProcessError as e:
            print(colour.red | colour.bold | "ERROR")
            if capture:
                if e.stdout:
                    stdout = indent_string(
                        e.stdout.decode('utf-8'),
                        indent='O: ')
                    print(colour.yellow | stdout)
                if e.stderr:
                    stderr = indent_string(
                        e.stderr.decode('utf-8'),
                        indent='E: ')
                    print(colour.red | stderr)
            raise ModuleExecFailed(self.name, data)
        else:
            print(colour.green | colour.bold | "OK")

class DictMixin:
    def __setitem__(self, key, item):
        self.__dict__[key] = item
    def __getitem__(self, key):
        return self.__dict__[key]
    def __repr__(self):
        return str(self)
    def __len__(self):
        return len(self.keys())
    def __delitem__(self, key):
        self.__dict__[key] = None
    def __eq__(self, other):
        if isinstance(other, self.__class__):
            return self.__dict__ == other.__dict__
        return False
    def __ne__(self, other):
        return not self.__eq__(other)
    def __contains__(self, key):
        return key in self.__dict__
    def __str__(self):
        return str({k: v for k, v in self.__dict__.items() if not k.startswith("_")})
    def has_key(self, k):
        return k in self.__dict__
    def update(self, *args, **kwargs):
        return self.__dict__.update(*args, **kwargs)
    def keys(self):
        return [k for k in self.__dict__ if not k.startswith("_")]
    def values(self):
        return [v for k, v in self.__dict__.items() if not k.startswith("_")]
    def items(self):
        return [(k, v) for k, v in self.__dict__.items() if not k.startswith("_")]
    def get(self, key, default=None):
        if key in self.__dict__:
            return self.__dict__[key]
        return default

