class EnrichmentMerchant(object):
    openapi_types = {
        'merchant_name': 'str',
        'parent_group': 'str'
    }
    attribute_map = {
        'merchant_name': 'merchantName',
        'parent_group': 'parentGroup'
    }
    def __init__(self, merchant_name=None, parent_group=None, local_vars_configuration=None):  
        if local_vars_configuration is None:
            local_vars_configuration = Configuration()
        self.local_vars_configuration = local_vars_configuration
        self._merchant_name = None
        self._parent_group = None
        self.discriminator = None
        if merchant_name is not None:
            self.merchant_name = merchant_name
        if parent_group is not None:
            self.parent_group = parent_group
    @property
    def merchant_name(self):
        return self._merchant_name
    @merchant_name.setter
    def merchant_name(self, merchant_name):
        self._merchant_name = merchant_name
    @property
    def parent_group(self):
        return self._parent_group
    @parent_group.setter
    def parent_group(self, parent_group):
        self._parent_group = parent_group
    def to_dict(self):
        result = {}
        for attr, _ in six.iteritems(self.openapi_types):
            value = getattr(self, attr)
            if isinstance(value, list):
                result[attr] = list(map(
                    lambda x: x.to_dict() if hasattr(x, "to_dict") else x,
                    value
                ))
            elif hasattr(value, "to_dict"):
                result[attr] = value.to_dict()
            elif isinstance(value, dict):
                result[attr] = dict(map(
                    lambda item: (item[0], item[1].to_dict())
                    if hasattr(item[1], "to_dict") else item,
                    value.items()
                ))
            else:
                result[attr] = value
        return result
    def to_str(self):
        return pprint.pformat(self.to_dict())
    def __repr__(self):
        return self.to_str()
    def __eq__(self, other):
        if not isinstance(other, EnrichmentMerchant):
            return False
        return self.to_dict() == other.to_dict()
    def __ne__(self, other):
        if not isinstance(other, EnrichmentMerchant):
            return True
        return self.to_dict() != other.to_dict()

class Config(object):
    def __init__(self, scheme, description, format, yaml_file):
        self.scheme = scheme
        self.description = description
        self.format = format
        self.translators_dict = {}
        self.rules_dict = {}
        self.target_keys = []
        self.addition_translators_dict = {}
        self.source_keys = []
        self.namespaces = {}
        self.yaml_file = yaml_file
    def __repr__(self):
        return("scheme: " + self.scheme + ", description: " + self.description + ", format: " + self.format + ", translators: " + str(self.translators_dict) + ", rules dict: " + str(self.rules_dict))
    def pretty_yaml(self):
        return pyaml.dump(self.yaml_file)
    def get_translator(self, source_key):
        return self.translators_dict.get(source_key)
    def dump(self):
        return {"scheme": self.scheme, "description": self.description, "format": self.format}
    def get_source_keys(self):
        return self.source_keys
    def get_target_keys(self):
        self.target_keys = list(dict.fromkeys(self.target_keys))
        return self.target_keys
    def add_translator(self, translator_yaml):
        translator = TranslatorFactory.create_translator(translator_yaml)
        source_key = translator.get_source_key()
        target_key = translator.get_target_key()
        target_key = [target_key] if not isinstance(target_key, list) else target_key
        source_key = [source_key] if not isinstance(source_key, list) else source_key
        for key in target_key:
            if key in DV_FIELD:
                self.target_keys.append(key)
            else:
                g.warnings.append("Target key " + key + " does not exist. Check dv-metadata-config for existing metadata keys.")
                return
        for key in source_key:
            if not key in self.translators_dict:
                self.translators_dict[key] = []
            self.source_keys.append(key)
            self.translators_dict[key].append(translator)
    def add_rules(self, rule_yaml):
        t = {}        
        trigger = rule_yaml.get("trigger", None)
        self.source_keys.append(trigger)
        trigger_values = rule_yaml.get("trigger_values", None)
        for trigger_value in trigger_values:
            translators_yaml = rule_yaml.get(trigger_value, None)   
            translators = []                                        
            for translator in translators_yaml:
                source_key = translator.get('source_key', None)
                self.source_keys.append(source_key)
                target_key = translator.get('target_key', None)
                translators.append(BaseTranslator(source_key, target_key))
            t[trigger_value] = translators            
            self.rules_dict[trigger] = t
    def add_namespace(self, name_space):
        namespace_split = name_space.split("=", 1)
        self.namespaces[namespace_split[0]]=namespace_split[1]

class Key:
    __slots__ = ("_key", "_reference")
    def __init__(self, *path_args, **kwargs):
        _constructor_handle_positional(path_args, kwargs)
        if (
            "reference" in kwargs
            or "serialized" in kwargs
            or "urlsafe" in kwargs
        ):
            ds_key, reference = _parse_from_ref(type(self), **kwargs)
        elif "pairs" in kwargs or "flat" in kwargs:
            ds_key = _parse_from_args(**kwargs)
            reference = None
        else:
            raise TypeError(
                "Key() cannot create a Key instance without arguments."
            )
        self._key = ds_key
        self._reference = reference
    @classmethod
    def _from_ds_key(cls, ds_key):
        key = cls.__new__(cls)
        key._key = ds_key
        key._reference = None
        return key
    def __repr__(self):
        args = ["{!r}".format(item) for item in self.flat()]
        if self.app() != _project_from_app(None):
            args.append("app={!r}".format(self.app()))
        if self.namespace() is not None:
            args.append("namespace={!r}".format(self.namespace()))
        return "Key({})".format(", ".join(args))
    def __str__(self):
        return self.__repr__()
    def __hash__(self):
        return hash(self.pairs())
    def _tuple(self):
        return (self.app(), self.namespace(), self.pairs())
    def __eq__(self, other):
        if not isinstance(other, Key):
            return NotImplemented
        return self._tuple() == other._tuple()
    def __ne__(self, other):
        return not self == other
    def __lt__(self, other):
        if not isinstance(other, Key):
            return NotImplemented
        return self._tuple() < other._tuple()
    def __le__(self, other):
        if not isinstance(other, Key):
            return NotImplemented
        return self._tuple() <= other._tuple()
    def __gt__(self, other):
        return not self <= other
    def __ge__(self, other):
        return not self < other
    def __getstate__(self):
        return (
            {
                "pairs": self.pairs(),
                "app": self.app(),
                "namespace": self.namespace(),
            },
        )
    def __setstate__(self, state):
        if len(state) != 1:
            msg = "Invalid state length, expected 1; received {:d}".format(
                len(state)
            )
            raise TypeError(msg)
        kwargs = state[0]
        if not isinstance(kwargs, dict):
            raise TypeError(
                "Key accepts a dict of keyword arguments as state; "
                "received {!r}".format(kwargs)
            )
        flat = _get_path(None, kwargs["pairs"])
        project = _project_from_app(kwargs["app"])
        self._key = _key_module.Key(
            *flat, project=project, namespace=kwargs["namespace"]
        )
        self._reference = None
    def __getnewargs__(self):
        return (
            {
                "pairs": self.pairs(),
                "app": self.app(),
                "namespace": self.namespace(),
            },
        )
    def parent(self):
        if self._key.parent is None:
            return None
        return Key._from_ds_key(self._key.parent)
    def root(self):
        root_key = self._key
        while root_key.parent is not None:
            root_key = root_key.parent
        if root_key is self._key:
            return self
        return Key._from_ds_key(root_key)
    def namespace(self):
        return self._key.namespace
    def app(self):
        return self._key.project
    def id(self):
        return self._key.id_or_name
    def string_id(self):
        return self._key.name
    def integer_id(self):
        return self._key.id
    def pairs(self):
        flat = self.flat()
        pairs = []
        for i in range(0, len(flat), 2):
            pairs.append(flat[i : i + 2])
        return tuple(pairs)
    def flat(self):
        flat_path = self._key.flat_path
        if len(flat_path) % 2 == 1:
            flat_path += (None,)
        return flat_path
    def kind(self):
        return self._key.kind
    def reference(self):
        if self._reference is None:
            self._reference = _app_engine_key_pb2.Reference(
                app=self._key.project,
                path=_to_legacy_path(self._key.path),
                name_space=self._key.namespace,
            )
        return self._reference
    def serialized(self):
        reference = self.reference()
        return reference.SerializeToString()
    def urlsafe(self):
        raw_bytes = self.serialized()
        return base64.urlsafe_b64encode(raw_bytes).strip(b"=")
    def get(self, **ctx_options):
        raise NotImplementedError
    def get_async(self, **ctx_options):
        raise NotImplementedError
    def delete(self, **ctx_options):
        raise NotImplementedError
    def delete_async(self, **ctx_options):
        raise NotImplementedError
    @classmethod
    def from_old_key(cls, old_key):
        raise NotImplementedError(_NO_LEGACY)
    def to_old_key(self):
        raise NotImplementedError(_NO_LEGACY)

class FlatCamera(Camera):
    def __init__(self, x, y, width, height, near=-50, far=50):
        self.x, self.y = x, y
        self.width, self.height = width, height
        self.near, self.far = near, far
    def project(self):
        glMatrixMode(GL_PROJECTION)
        glLoadIdentity()
        glViewport(self.x, self.y, self.width, self.height)
        glOrtho(0, self.width, 0, self.height, self.near, self.far)
        glMatrixMode(GL_MODELVIEW)
    def on_resize(self, width, height):
        self.width, self.height = width, height
        return EVENT_UNHANDLED
    def __repr__(self):
        return '<%s object at 0x%x pos=(%d,%d) size=(%d,%d)>'%(
            self.__class__.__name__, id(self), self.x, self.y, self.width,
            self.height)

