class Player:
    def __init__(self, payoff_array: np.ndarray):
        self.payoff_array: np.ndarray = np.asarray(payoff_array, order='C')
        if self.payoff_array.ndim == 0:
            raise ValueError('payoff_array must be an array_like')
        if np.prod(self.payoff_array.shape) == 0:
            raise ValueError('every player must have at least one action')
        self.num_opponents: int = self.payoff_array.ndim - 1
        self.num_actions: int = self.payoff_array.shape[0]
        self.dtype: np.dtype = self.payoff_array.dtype
        self.tol: float = 1e-8
    def __repr__(self) -> str:
        s = repr(self.payoff_array).replace('array', 'Player')
        l = s.splitlines()
        for i in range(1, len(l)):
            if l[i]:
                l[i] = ' ' + l[i]
        return '\n'.join(l)
    def __str__(self) -> str:
        N = self.num_opponents + 1
        s = 'Player in a {N}-player normal form game'.format(N=N)
        s += ' with payoff array:\n'
        s += np.array2string(self.payoff_array, separator=', ')
        return s
    def delete_action(self, action: IntOrArrayT, player_idx: int = 0) -> "Player":
        payoff_array_new = np.delete(self.payoff_array, action, player_idx)
        return Player(payoff_array_new)
    def payoff_vector(self, opponents_actions: npt.ArrayLike) -> np.ndarray:
        def reduce_last_player(payoff_array: np.ndarray, action: IntOrArrayT) -> np.ndarray:
            if isinstance(action, numbers.Integral):  
                return payoff_array.take(action, axis=-1)
            else:  
                return payoff_array.dot(action)
        if self.num_opponents == 1:
            payoff_vector = \
                reduce_last_player(self.payoff_array, opponents_actions)
        elif self.num_opponents >= 2:
            payoff_vector = self.payoff_array
            for i in reversed(range(self.num_opponents)):
                payoff_vector = \
                    reduce_last_player(payoff_vector, opponents_actions[i])
        else:  
            payoff_vector = self.payoff_array
        return payoff_vector
    def is_best_response(
        self,
        own_action: IntOrArrayT,
        opponents_actions: IntOrArrayT,
        tol: Optional[float] = None,
    ) -> bool:
        if tol is None:
            tol = self.tol
        payoff_vector = self.payoff_vector(opponents_actions)
        payoff_max = payoff_vector.max()
        if isinstance(own_action, numbers.Integral):
            return payoff_vector[own_action] >= payoff_max - tol
        else:
            return np.dot(own_action, payoff_vector) >= payoff_max - tol
    def best_response(
        self,
        opponents_actions: IntOrArrayT,
        tie_breaking: str = 'smallest',
        payoff_perturbation: Optional[np.ndarray] = None,
        tol: Optional[float] = None,
        random_state: Optional[Union[int, np.random.RandomState]] = None,
    ) -> IntOrArrayT:
        if tol is None:
            tol = self.tol
        payoff_vector = self.payoff_vector(opponents_actions)
        if payoff_perturbation is not None:
            try:
                payoff_vector += payoff_perturbation
            except TypeError:  
                payoff_vector = payoff_vector + payoff_perturbation
        best_responses = \
            np.where(payoff_vector >= payoff_vector.max() - tol)[0]
        if tie_breaking == 'smallest':
            return best_responses[0]
        elif tie_breaking == 'random':
            return self.random_choice(best_responses,
                                      random_state=random_state)
        elif tie_breaking is False:
            return best_responses
        else:
            msg = "tie_breaking must be one of 'smallest', 'random', or False"
            raise ValueError(msg)
    def random_choice(
        self,
        actions: Optional[npt.ArrayLike] = None,
        random_state: Optional[Union[int, np.random.RandomState]] = None,
    ) -> int:
        random_state = check_random_state(random_state)
        if actions is not None:
            n = len(actions)
        else:
            n = self.num_actions
        if n == 1:
            idx = 0
        else:
            idx = random_state.randint(n)
        if actions is not None:
            return actions[idx]
        else:
            return idx
    def is_dominated(
        self,
        action: int,
        tol: Optional[float] = None,
        method: Optional[str] = None,
    ) -> bool:
        if tol is None:
            tol = self.tol
        payoff_array = self.payoff_array
        if self.num_opponents == 0:
            return payoff_array.max() > payoff_array[action] + tol
        ind = np.ones(self.num_actions, dtype=bool)
        ind[action] = False
        D = payoff_array[ind]
        D -= payoff_array[action]
        if D.shape[0] == 0:  
            return False
        if self.num_opponents >= 2:
            D.shape = (D.shape[0], np.prod(D.shape[1:]))
        if method is None:
            from .lemke_howson import lemke_howson
            g_zero_sum = NormalFormGame([Player(D), Player(-D.T)])
            NE = lemke_howson(g_zero_sum)
            return NE[0] @ D @ NE[1] > tol
        elif method in ['simplex', 'interior-point', 'revised simplex']:
            from scipy.optimize import linprog
            m, n = D.shape
            A_ub = np.empty((n, m+1))
            A_ub[:, :m] = -D.T
            A_ub[:, -1] = 1  
            b_ub = np.zeros(n)
            A_eq = np.empty((1, m+1))
            A_eq[:, :m] = 1  
            A_eq[:, -1] = 0
            b_eq = np.ones(1)
            c = np.zeros(m+1)
            c[-1] = -1
            res = linprog(c, A_ub=A_ub, b_ub=b_ub, A_eq=A_eq, b_eq=b_eq,
                          method=method)
            if res.success:
                return res.x[-1] > tol
            elif res.status == 2:  
                return False
            else:  
                msg = 'scipy.optimize.linprog returned {0}'.format(res.status)
                raise RuntimeError(msg)
        else:
            raise ValueError('Unknown method {0}'.format(method))
    def dominated_actions(
        self, tol: Optional[float] = None, method: Optional[str] = None) -> List[int]:
        out = []
        for action in range(self.num_actions):
            if self.is_dominated(action, tol=tol, method=method):
                out.append(action)
        return out

class NormalFormGame:
    def __init__(self, data: npt.ArrayLike, dtype: Optional[np.dtype] = None):
        if hasattr(data, '__getitem__') and isinstance(data[0], Player):
            N = len(data)
            shape_0 = data[0].payoff_array.shape
            dtype_0 = data[0].payoff_array.dtype
            for i in range(1, N):
                shape = data[i].payoff_array.shape
                if not (
                    len(shape) == N and
                    shape == shape_0[i:] + shape_0[:i]
                ):
                    raise ValueError(
                        'shapes of payoff arrays must be consistent'
                    )
                dtype = data[i].payoff_array.dtype
                if dtype != dtype_0:
                    raise ValueError(
                        'dtypes of payoff arrays must coincide'
                    )
            self.players = tuple(data)
            self.dtype = dtype_0
        else:
            data = np.asarray(data)
            if data.ndim == 0:  
                N = 1
                self.players = (Player(np.zeros(data)),)
                self.dtype = data.dtype
            elif data.ndim == 1:  
                N = data.size
                self.players = tuple(
                    Player(np.zeros(tuple(data[i:]) + tuple(data[:i]),
                                    dtype=dtype))
                    for i in range(N)
                )
                self.dtype = self.players[0].payoff_array.dtype
            elif data.ndim == 2 and data.shape[1] >= 2:
                if data.shape[0] != data.shape[1]:
                    raise ValueError(
                        'symmetric two-player game must be represented ' +
                        'by a square matrix'
                    )
                N = 2
                self.players = tuple(Player(data) for i in range(N))
                self.dtype = data.dtype
            else:  
                N = data.ndim - 1
                if data.shape[-1] != N:
                    raise ValueError(
                        'size of innermost array must be equal to ' +
                        'the number of players'
                    )
                payoff_arrays = tuple(
                    np.empty(data.shape[i:-1]+data.shape[:i], dtype=data.dtype)
                    for i in range(N)
                )
                for i, payoff_array in enumerate(payoff_arrays):
                    payoff_array[:] = \
                        data.take(i, axis=-1).transpose(list(range(i, N)) +
                                                        list(range(i)))
                self.players = tuple(
                    Player(payoff_array) for payoff_array in payoff_arrays
                )
                self.dtype = data.dtype
        self.N = N  
        self.nums_actions = tuple(
            player.num_actions for player in self.players
        )
        self.payoff_arrays = tuple(
            player.payoff_array for player in self.players
        )
    @property
    def payoff_profile_array(self) -> np.ndarray:
        N = self.N
        dtype = self.dtype
        payoff_profile_array = \
            np.empty(self.players[0].payoff_array.shape + (N,), dtype=dtype)
        for i, player in enumerate(self.players):
            payoff_profile_array[..., i] = \
                player.payoff_array.transpose(list(range(N-i, N)) +
                                              list(range(N-i)))
        return payoff_profile_array
    def __repr__(self) -> str:
        s = '<{nums_actions} {N}-player NormalFormGame of dtype {dtype}>'
        return s.format(nums_actions=_nums_actions2string(self.nums_actions),
                        N=self.N,
                        dtype=self.dtype)
    def __str__(self) -> str:
        s = '{N}-player NormalFormGame with payoff profile array:\n'
        s += _payoff_profile_array2string(self.payoff_profile_array)
        return s.format(N=self.N)
    def __getitem__(self, action_profile: IntOrArrayT) -> np.ndarray:
        if self.N == 1:  
            if not isinstance(action_profile, numbers.Integral):
                raise TypeError('index must be an integer')
            return self.players[0].payoff_array[action_profile]
        try:
            if len(action_profile) != self.N:
                raise IndexError('index must be of length {0}'.format(self.N))
        except TypeError:
            raise TypeError('index must be a tuple')
        payoff_profile = np.empty(self.N, dtype=self.dtype)
        for i, player in enumerate(self.players):
            payoff_profile[i] = \
                player.payoff_array[
                    tuple(action_profile[i:]) + tuple(action_profile[:i])
                ]
        return payoff_profile
    def __setitem__(self, action_profile: IntOrArrayT, payoff_profile: npt.ArrayLike) -> None:
        if self.N == 1:  
            if not isinstance(action_profile, numbers.Integral):
                raise TypeError('index must be an integer')
            self.players[0].payoff_array[action_profile] = payoff_profile
            return None
        try:
            if len(action_profile) != self.N:
                raise IndexError('index must be of length {0}'.format(self.N))
        except TypeError:
            raise TypeError('index must be a tuple')
        try:
            if len(payoff_profile) != self.N:
                raise ValueError(
                    'value must be an array_like of length {0}'.format(self.N)
                )
        except TypeError:
            raise TypeError('value must be a tuple')
        for i, player in enumerate(self.players):
            player.payoff_array[
                tuple(action_profile[i:]) + tuple(action_profile[:i])
            ] = payoff_profile[i]
    def delete_action(self, player_idx: int, action: IntOrArrayT) -> "NormalFormGame":
        if -self.N <= player_idx < 0:
            player_idx = player_idx + self.N
        players_new = tuple(
            player.delete_action(action, player_idx-i)
            for i, player in enumerate(self.players)
        )
        return NormalFormGame(players_new)
    def is_nash(self, action_profile: npt.ArrayLike, tol: Optional[float] = None) -> bool:
        if self.N == 2:
            for i, player in enumerate(self.players):
                own_action, opponent_action = \
                    action_profile[i], action_profile[1-i]
                if not player.is_best_response(own_action, opponent_action,
                                               tol):
                    return False
        elif self.N >= 3:
            for i, player in enumerate(self.players):
                own_action = action_profile[i]
                opponents_actions = \
                    tuple(action_profile[i+1:]) + tuple(action_profile[:i])
                if not player.is_best_response(own_action, opponents_actions,
                                               tol):
                    return False
        else:  
            if not self.players[0].is_best_response(action_profile[0], None,
                                                    tol):
                return False
        return True

class CPUTensor(Tensor):
    _tensor = None
    def __init__(self,
                 backend,
                 shape=None,
                 dtype=np.float32,
                 ary=None,
                 name=None,
                 persist_values=True):
        super(CPUTensor, self).__init__(backend, shape, dtype, name,
                                        persist_values)
        assert dtype in (np.float16, np.float32, np.float64, np.uint8, np.int8,
                         np.uint16, np.int16, np.uint32, np.int32)
        dtype = np.dtype(dtype)
        if type(ary) != np.ndarray:
            self._tensor = np.array(ary, dtype)
        elif ary.dtype != dtype:
            self._tensor = ary.astype(dtype)
        else:
            self._tensor = ary
        while self._tensor.ndim < self._min_dims:
            self._tensor = self._tensor.reshape(self._tensor.shape + (1, ))
        if shape is not None and len(shape) < self._min_dims:
            self.shape = shape + (1, )
        else:
            self.shape = self._tensor.shape
        try:
            size = 1
            for dim in self.shape:
                size *= dim
        except TypeError:
            assert isinstance(self.shape, (int, long, np.integer))
            size = self.shape
            self.shape = (self.shape,)
        self.size = size
    @property
    def base(self):
        return self._tensor.base
    def __str__(self):
        if self._tensor.base is not None:
            base_id = id(self._tensor.base)
        else:
            base_id = id(self._tensor)
        return ("CPUTensor(base 0x%x) name:%s shape:%s dtype:%s strides:%s"
                " is_c_contiguous:%s" % (base_id, self.name, self.shape,
                                         self.dtype, self._tensor.strides,
                                         self._tensor.flags.c_contiguous))
    def __repr__(self):
        return self.__str__()
    def __len__(self):
        if len(self.shape):
            return self.shape[0]
        else:
            return 0
    def __setitem__(self, key, value):
        self.__getitem__(key)._assign(value)
        return self
    def __getitem__(self, key):
        if not isinstance(key, tuple):
            if key == _none_slice:
                return self
            key = (key,)
        key_list = list(key)
        for idx, k in enumerate(key):
            if type(k) is int:
                k = self.shape[idx] + k if k < 0 else k
                key_list[idx] = slice(k, k + 1, None)
        key = tuple(key_list)
        new_shape = list(self._tensor[key].shape)
        for idx, k in enumerate(new_shape):
            if len(new_shape) > 2 and k is 1:
                new_shape.remove(k)
        return self.__class__(
            backend=self.backend,
            ary=self._tensor[key].reshape(new_shape),
            dtype=self._tensor.dtype)
    def _assign(self, value):
        if isinstance(value, (CPUTensor, OpTreeNode)):
            OpTreeNode.build("assign", self, value)
        elif isinstance(value, (int, float, np.ndarray)):
            self.set(value)
        else:
            raise TypeError("Invalid type for assignment: %s" % type(value))
        return self
    def set(self, value):
        if isinstance(value, np.ndarray):
            if value.dtype is not self.dtype:
                value = value.astype(self.dtype)
            assert value.size == self.size
            if value.ndim < self._min_dims:
                value = value.reshape(self.shape)
        self._tensor[:] = value
        return self
    def get(self):
        return self._tensor
    def asnumpyarray(self):
        return self._tensor
    def take(self, indices, axis=None):
        if type(indices) == self.__class__:
            indices = indices._tensor
        if type(indices) == np.ndarray:
            indices = indices.squeeze()
        new_shape = list(self.shape)
        new_shape[axis] = indices.size
        return self.__class__(
            backend=self.backend,
            ary=self._tensor.take(indices, axis).reshape(new_shape),
            dtype=self._tensor.dtype)
    def fill(self, value):
        self._tensor.fill(value)
        return self
    def copy(self, a):
        return self._assign(a)
    def copy_from(self, a):
        return self._assign(a)
    def reshape(self, *shape):
        if isinstance(shape[0], (tuple, list)):
            shape = tuple(shape[0])
        if shape == self.shape:
            return self
        return self.__class__(
            backend=self.backend,
            ary=self._tensor.reshape(shape),
            dtype=self._tensor.dtype)
    @property
    def T(self):
        if len(self.shape) <= 2:
            ary = self._tensor.transpose()
        else:
            ary = self._tensor.swapaxes(1, 2)
        return self.__class__(
            backend=self.backend,
            ary=ary,
            dtype=self._tensor.dtype)
    def transpose(self, out=None):
        if out:
            return OpTreeNode.build("assign", out, self.T)
        return self.T
    def share(self, shape, dtype=None, name=None):
        size = np.prod(shape)
        if size > self.size:
            raise ValueError("total size of new array must <= size of parent")
        ary = self._tensor.ravel()[:size].reshape(shape)
        return self.__class__(
            backend=self.backend,
            ary=ary,
            dtype=self._tensor.dtype)
    def hist(self, tag):
        nbins = self.backend.hist_bins
        offset = self.backend.hist_offset
        bins = np.arange(nbins + 1) + float(offset)
        bins[0] = -float('Inf')
        np_inp_log_abs = np.rint(
            np.log2(np.abs(self.get().astype(np.float32))))
        np_hist, edges = np.histogram(np_inp_log_abs, density=False, bins=bins)
        nc_hist = self.backend._hist_tensor(tag)._assign(np_hist)
        return nc_hist

class ControlAgent:
    def __init__(self,com_agent):
        self.com_agent = com_agent
        self.status = {
            "speed" : 0,
            "acc" : 0,
            "location" : {"x":0,"y":0},
            "angle" : 0,
        }
        pygame.init()
        pygame.display.set_mode(size=(640,480))
        if DEBUG: print("Control Agent Initiated successfully")
    def __repr__(self):
        return str(self.status)
    def run(self):
        while True:
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    pygame.quit();  
                if event.type == pygame.KEYDOWN:
                    if event.key == pygame.K_UP:
                        self.Generate_Command("front")
                    if event.key == pygame.K_DOWN:
                        self.Generate_Command("back")
                    if event.key == pygame.K_RIGHT:
                        self.Generate_Command("right")
                    if event.key == pygame.K_LEFT:
                        self.Generate_Command("left")
                    if event.key == pygame.K_KP_PLUS:
                        self.Update_Status("higher")
                    if event.key == pygame.K_KP_MINUS:
                        self.Update_Status("lower")
                    if event.key == pygame.K_ESCAPE:
                        self.Exit()
    def Update_Status(self, command):
        if DEBUG: print("Updating status", command)
        if command == "higher": self.status["speed"] += 1
        elif command == "lower" and self.status["speed"] > 0: self.status["speed"] -= 1
    def Generate_Command(self, command):
        if DEBUG: print("Generating Command", command)
        command_msg = {"speed":self.status["speed"], "acc":self.status["acc"], "action":command}
        self.com_agent.send(command_msg)
    def Exit(self):
        self.com_agent.terminate()
        print("Program Terminated")
        exit()

class _BlockOutputChannel(object):
    def __init__(self,block,index,name=None):
        self._block = block
        self._index = index
        self._global_name = None
        self._name = name
        self._type = None
        self._currentValue = None
