        self.__last = None
        self.__size = 0
        self.__last_access_node = None
        self.__last_access_idx = -1
        if sequence is None:
            return
        for value in sequence:
            node = dllistnode(value, self.__last, None, self)
            if self.__first is None:
                self.__first = node
            self.__last = node
            self.__size += 1
