class Cylinder(Shape):
    __slots__ = ['_circle', '_height']
    def __init__(self, circle, height):
        self._circle = None
        self._height = None
        self.circle = circle
        self.height = height
    @classmethod
    def from_data(cls, data):
        cylinder = cls(Circle(Plane.worldXY(), 1), 1)
        cylinder.data = data
        return cylinder
    @property
    def plane(self):
        return self.circle.plane
    @plane.setter
    def plane(self, plane):
        self.circle.plane = Plane(plane[0], plane[1])
    @property
    def circle(self):
        return self._circle
    @circle.setter
    def circle(self, circle):
        self._circle = circle
    @property
    def radius(self):
        return self.circle.radius
    @radius.setter
    def radius(self, radius):
        self.circle.radius = float(radius)
    @property
    def height(self):
        return self._height
    @height.setter
    def height(self, height):
        self._height = float(height)
    @property
    def normal(self):
        return self.plane.normal
    @property
    def diameter(self):
        return self.circle.diameter
    @property
    def data(self):
        return {'circle': self.circle.data,
                'height': self.height}
    @data.setter
    def data(self, data):
        self.circle = Circle.from_data(data['circle'])
        self.height = data['height']
    def to_data(self):
        return self.data
    @property
    def center(self):
        return self.circle.center
    @center.setter
    def center(self, point):
        self.circle.center = point
    @property
    def area(self):
        return (self.circle.area * 2) + (self.circle.circumference * self.height)
    @property
    def volume(self):
        return self.circle.area * self.height
    def to_vertices_and_faces(self, **kwargs):
        if 'u' in kwargs:
            u = kwargs['u']
        else:
            u = 10
        vertices = []
        a = 2 * pi / u
        for i in range(u):
            x = self.circle.radius * cos(i * a)
            y = self.circle.radius * sin(i * a)
            z = self.height / 2
            vertices.append([x, y, z])
            vertices.append([x, y, -z])
        frame = Frame.from_plane(self.circle.plane)
        M = matrix_from_frame(frame)
        vertices = transform_points(vertices, M)
        faces = []
        for i in range(0, u*2, 2):
            faces.append([i, i+1, (i+3)%(u*2), (i+2)%(u*2)])
        faces.append([i for i in range(0, u*2, 2)])
        faces.append([i for i in range(1, u*2, 2)])
        faces[-1].reverse()
        return vertices, faces
    def __repr__(self):
        return 'Cylinder({0}, {1})'.format(self.circle, self.height)
    def __len__(self):
        return 2
    def __getitem__(self, key):
        if key == 0:
            return self.circle
        elif key == 1:
            return self.height
        else:
            raise KeyError
    def __setitem__(self, key, value):
        if key == 0:
            self.circle = value
        elif key == 1:
            self.height = value
        else:
            raise KeyError
    def __iter__(self):
        return iter([self.circle, self.height])
    def copy(self):
        cls = type(self)
        return cls(self.circle.copy(), self.height)
    def transform(self, transformation):
        self.circle.transform(transformation)
    def transformed(self, transformation):
        cylinder = self.copy()
        cylinder.transform(transformation)
        return cylinder

