        if isinstance(i, str):
            try:
                return self.link_dict[i]
            except KeyError:
                raise KeyError(f"link {i} not in link dictionary")
            except AttributeError:
                raise AttributeError(f"robot has no link dictionary")
        else:
            return self._links[i]
    def dynchanged(self, what=None):
