    @property
    def qrandom(self):
        qlim = self.qlim
        if np.any(np.isnan(qlim)):
            raise ValueError('some joint limits not defined')
        return np.random.uniform(
            low=qlim[0, :], high=qlim[1, :], size=(self.n,))
    def addconfiguration(self, name, q, unit='rad'):
