    def todegrees(self, q):
        q = getmatrix(q, (None, self.n))
        for j, revolute in enumerate(self.revolutejoints):
            if revolute:
                q[:, j] *= 180.0 / np.pi
        if q.shape[0] == 1:
            return q[0]
