                self._base = SE3()
        return self._base.copy()
    @base.setter
    def base(self, T):
        if T is None:
            self._base = T
        elif isinstance(self, rtb.ERobot2):
            if isinstance(T, SE2):
                self._base = T
            elif SE2.isvalid(T):
                self._tool = SE2(T, check=True)
        elif isinstance(self, rtb.Robot):
            if isinstance(T, SE3):
                self._base = T
            elif SE3.isvalid(T):
                self._tool = SE3(T, check=True)
        else:
            raise ValueError('base must be set to None (no tool), SE2, or SE3')
