                'Control type must be one of \'p\', \'v\', or \'a\'')
    def _get_graphical_backend(self, backend):
        if backend is None:
            if isinstance(self, rtb.DHRobot):
                backend = 'pyplot'
            elif isinstance(self, rtb.ERobot2):
                backend = 'pyplot2'
            else:
                backend = 'swift'
        if backend.lower() == 'swift':  
            if isinstance(self, rtb.DHRobot):
                raise NotImplementedError(
                    'Plotting in Swift is not implemented for DHRobots yet')
            from roboticstoolbox.backends.Swift import Swift
            env = Swift()
        elif backend.lower() == 'pyplot':
            from roboticstoolbox.backends.PyPlot import PyPlot
            env = PyPlot()
        elif backend.lower() == 'pyplot2':
            from roboticstoolbox.backends.PyPlot import PyPlot2
            env = PyPlot2()
        elif backend.lower() == 'vpython':
            from roboticstoolbox.backends.VPython import VPython
            env = VPython()
        else:
            raise ValueError('unknown backend', backend)
        return env
    def plot(
            self, q, backend=None, block=False, dt=0.050,
            limits=None, vellipse=False, fellipse=False,
            jointaxes=True, jointlabels=False, eeframe=True, shadow=True, name=True, fig=None,
            movie=None, loop=False, **bopts
    ):
        env = None
        env = self._get_graphical_backend(backend)
        q = getmatrix(q, (None, self.n))
        self.q = q[0, :]
        if q.shape[0] == 1:
            env.launch(self.name + ' Plot', limits=limits, fig=fig)
        else:
            env.launch(self.name + ' Trajectory Plot', limits=limits, fig=fig)
        env.add(
            self, readonly=True, jointaxes=jointaxes, jointlabels=jointlabels,
            eeframe=eeframe, shadow=shadow, name=name)
        if vellipse:
            vell = self.vellipse(centre='ee')
            env.add(vell)
        if fellipse:
            fell = self.fellipse(centre='ee')
            env.add(fell)
        images = []  
        if movie is not None:
            loop = False
        while True:
            for qk in q:
                self.q = qk
                if vellipse:
                    vell.q = qk
                if fellipse:
                    fell.q = qk
                env.step(dt)
                if movie is not None:  
                    images.append(env.getframe())
            if movie is not None:  
                images[0].save(
                    movie,
                    save_all=True, append_images=images[1:], optimize=False,
                    duration=dt, loop=0)
            if not loop:
                break
        if block:           
            env.hold()
        return env
    def fellipse(self, q=None, opt='trans', unit='rad', centre=[0, 0, 0]):
        if isinstance(self, rtb.ERobot):  
            raise NotImplementedError(
                "ERobot fellipse not implemented yet")
