            jointaxes=jointaxes, eeframe=eeframe, shadow=shadow, name=name)
    def plot_vellipse(
            self, q=None, block=True, vellipse=None,
            limits=None, opt='trans', centre=[0, 0, 0],
            jointaxes=True, eeframe=True, shadow=True, name=True):
        if isinstance(self, rtb.ERobot):  
            raise NotImplementedError(
                "Ellipse Plotting of ERobot's not implemented yet")
        if q is not None:
            self.q = q
        if vellipse is None:
            vellipse = self.vellipse(q=q, opt=opt, centre=centre)
        return self.plot_ellipse(
            vellipse, block=block, limits=limits,
            jointaxes=jointaxes, eeframe=eeframe, shadow=shadow, name=name)
    def teach(
            self, q=None, block=True, order='xyz', limits=None,
            jointaxes=True, jointlabels=False,
            vellipse=False, fellipse=False, eeframe=True, shadow=True,
            name=True, backend=None):
        if q is None:
            q = np.zeros((self.n,))
        else:
            q = getvector(q, self.n)
        env = self._get_graphical_backend(backend)
        env.launch('Teach ' + self.name, limits=limits)
        env.add(
            self, readonly=True,
            jointaxes=jointaxes, jointlabels=jointlabels, eeframe=eeframe,
            shadow=shadow, name=name)
        env._add_teach_panel(self, q)
        if vellipse:
            vell = self.vellipse(centre='ee', scale=0.5)
            env.add(vell)
        if fellipse:
            fell = self.fellipse(centre='ee')
            env.add(fell)
        if block:           
            env.hold()
        return env
    def closest_point(self, q, shape, inf_dist=1.0, skip=False):
        if not skip:
            self._set_link_fk(q)
        d = 10000
        p1 = None
        p2 = None
        for link in self.links:
            td, tp1, tp2 = link.closest_point(shape, inf_dist)
            if td is not None and td < d:
                d = td
                p1 = tp1
                p2 = tp2
        if d == 10000:
            d = None
        return d, p1, p2
    def collided(self, q, shape, skip=False):
        if not skip:
            self._set_link_fk(q)
        for link in self.links:
            if link.collided(shape):
                return True
        if isinstance(self, rtb.ERobot):
            for gripper in self.grippers:
                for link in gripper.links:
                    if link.collided(shape):
                        return True
        return False
    def joint_velocity_damper(self, ps=0.05, pi=0.1, n=None, gain=1.0):
        if n is None:
            n = self.n
        Ain = np.zeros((n, n))
        Bin = np.zeros(n)
        for i in range(n):
            if self.q[i] - self.qlim[0, i] <= pi:
                Bin[i] = -gain * (
                    ((self.qlim[0, i] - self.q[i]) + ps) / (pi - ps))
                Ain[i, i] = -1
            if self.qlim[1, i] - self.q[i] <= pi:
                Bin[i] = gain * (
                    (self.qlim[1, i] - self.q[i]) - ps) / (pi - ps)
                Ain[i, i] = 1
        return Ain, Bin

class declaration_t(object):
    def __init__(
            self,
            name='',
            location=None,
            is_artificial=False,
            mangled=None,
            demangled=None,
            attributes=None):
        self._name = name
        self._location = location
        self._is_artificial = is_artificial
        self._mangled = mangled
        self._demangled = demangled
        self._attributes = attributes
        self._parent = None
        self._cache = algorithms_cache.declaration_algs_cache_t()
        self._partial_name = None
        self._decorated_name = None
    def __str__(self):
        name = self.decl_string
        if name[:2] == "::":
            name = name[2:]
        cls = self.__class__.__name__
        if cls[-2:] == "_t":
            cls = cls[:-2]
        cls = cls.replace('_', ' ')
        return "%s [%s]" % (name, cls)
    def _get__cmp__items(self):
        print(
            '_get__cmp__items not implemented for class ',
            self.__class__.__name__)
        raise NotImplementedError()
    def _get__cmp__data(self):
        if self._cache.cmp_data is None:
            cmp_data = [
                declaration_utils.declaration_path(self.parent),
                self.name,
                self.location]
            cmp_data.extend(self._get__cmp__items())
            self._cache.cmp_data = cmp_data
        return self._cache.cmp_data
    def __eq__(self, other):
        if not isinstance(other, self.__class__):
            return False
        return self.name == other.name \
            and self.location == other.location \
            and declaration_utils.declaration_path(self.parent) \
            == declaration_utils.declaration_path(other.parent)
    def __hash__(self):
        return (hash(self.__class__) ^
                hash(self.name) ^
                hash(self.location))
    def __ne__(self, other):
        return not self.__eq__(other)
    def __lt__(self, other):
        if not isinstance(other, self.__class__):
            return self.__class__.__name__ < other.__class__.__name__
        return self._get__cmp__data() < other._get__cmp__data()
    def _get_name_impl(self):
        return self._name
    def _on_rename(self):
        pass
    @property
    def name(self):
        return self._get_name_impl()
