        if None is self._partial_name:
            self._partial_name = self._get_partial_name_impl()
        return self._partial_name
    @property
    def parent(self):
        return self._parent
    @parent.setter
    def parent(self, new_parent):
        if new_parent:
            assert isinstance(new_parent, declaration_t)
        self._parent = new_parent
    @property
    def top_parent(self):
        parent = self.parent
        me = self
        while True:
            if not parent:
                return me
            else:
                me = parent
                parent = me.parent
