class Date:
    def __init__(self, init_month, init_day, init_year):
        self.month = init_month
        self.day = init_day
        self.year = init_year
    def __repr__(self):
        s = '%02d/%02d/%04d' % (self.month, self.day, self.year)
        return s
    def is_leap_year(self):
        if self.year % 400 == 0:
            return True
        elif self.year % 100 == 0:
            return False
        elif self.year % 4 == 0:
            return True
        return False
    def copy(self):
        new_date = Date(self.month, self.day, self.year)
        return new_date
    def advance_one(self):
        days_in_month = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        if self.is_leap_year() == True:
            days_in_month[2] = 29
        if days_in_month[self.month] == self.day:
            self.month += 1
            self.day = 1
            if self.month == 13:
                self.year += 1
                self.month = 1
        else:
            self.day += 1
    def advance_n(self, n):
        print(self.__repr__())
        for days in range(n):
            self.advance_one()
            print(self.__repr__())
    def __eq__(self, other):
        if self.day == other.day and self.month== other.month and self.year == other.year:
            return True
        else:
            return False
    def is_before(self, other):
        if self.year < other.year:
            return True
        elif self.month < other.month and self.year <= other.year:
            return True
        elif self.day < other.day and self.month <= other.month and self.year <= other.year:
            return True
        else:
            return False
    def is_after(self, other):
        if self.__eq__(other) == True or self.is_before(other) == True:
            return False
        else:
            return True
    def days_between(self, other):
        days_bet = 0
        date1 = self.copy()
        date2 = other.copy()
        if date1.__eq__(date2) == True:
            return 0
        elif date1.is_before(date2) == True:
            while date1.__eq__(date2)==False:
                date1.advance_one()
                days_bet -= 1
        elif date1.is_after(date2) == True:
            while date1.__eq__(date2)==False:
                date2.advance_one()
                days_bet += 1
        return days_bet
    def day_name(self):
        day_names = ['Monday', 'Tuesday', 'Wednesday', 
             'Thursday', 'Friday', 'Saturday', 'Sunday']
        dayh = Date(11, 11, 2019)
        day_b = self.days_between(dayh)
        return day_names[day_b % 7]

class StreamSchema(object) :
    def __init__(self, schema):
        schema = schema.strip()
        self._spl_type = not schema.startswith("tuple<")
        self._schema=schema
        if not self._spl_type:
            parser = _SchemaParser(schema)
            self._types = parser._parse()
        self._style = self._default_style()
    def _set(self, schema):
        if isinstance(schema, CommonSchema):
            self._spl_type = False
            self._schema = schema.schema()
            self._style = self._default_style()
        else:
            self._spl_type = schema._spl_type
            self._schema = schema._schema
            self._style = schema._style
    @property
    def style(self):
        return self._style
    def _default_style(self):
        if self._spl_type:
            return _spl_dict
        return _SCHEMA_COMMON_STYLES[self.schema()] if is_common(self) else _spl_dict
    def _copy(self, style=None):
        if style is None:
            return self
        if self._style is style:
            return self
        if is_common(self):
            return self
        c = StreamSchema(self.schema())
        c._style = style
        return c
    def _make_named_tuple(self, name):
        if self._spl_type:
            return tuple
        if name is True:
            name = 'StreamTuple'
        if sys.version_info.major == 2:
            fields = _attribute_names(self._types)
            nt = collections.namedtuple(name, fields, rename=True)
        else:
            import typing
            nt = typing.NamedTuple(name, _attribute_pytypes(self._types))
        nt._splpy_namedtuple = name
        return nt
    def as_tuple(self, named=None):
        if not named:
            return self._copy(tuple)
        if named == True or isinstance(named, basestring):
            return self._copy(self._make_named_tuple(name=named))
        return self._copy(tuple)
    def as_dict(self):
        return self._copy(_spl_dict)
    def schema(self):
        return self._schema
    def __str__(self):
        return self._schema
    def spl_json(self):
        _splj = {}
        _splj["type"] = 'spltype'
        _splj["value"] = self.schema()
        return _splj
    def extend(self, schema):
        if self._spl_type:
           raise TypeError("Not supported for declared SPL types")
        base = self.schema()
        extends = schema.schema()
        new_schema = base[:-1] + ',' + extends[6:]
        return StreamSchema(new_schema)
    def __hash__(self):
        return hash(self.schema())
    def __eq__(self, other):
        if isinstance(other, self.__class__):
            return self.schema() == other.schema()
        return False
    def __ne__(self, other):
        return not self.__eq__(other)
    @staticmethod
    def _fnop_style(schema, op, name):
        if is_common(schema):
            if name in op.params:
                del op.params[name]
            return
        if _is_pending(schema):
            ntp = 'pending'
        elif schema.style is tuple:
            ntp = 'tuple'
        elif schema.style is _spl_dict:
            ntp = 'dict'
        elif _is_namedtuple(schema.style) and hasattr(schema.style, '_splpy_namedtuple'):
            ntp = 'namedtuple:' + schema.style._splpy_namedtuple
        else:
            return
        op.params[name] = ntp

