class LiveServer(object):
    def __init__(self, app, port):
        self.app = app
        self.port = port
        self._thread = None
    def start(self):
        def worker(app, port):
            return app.run(port=port, use_reloader=False, threaded=True)
        self._thread = threading.Thread(
            target=worker,
            args=(self.app, self.port)
        )
        self._thread.start()
        delay = 0.01
        for i in range(100):
            try:
                urlopen(self.url('/ping'))
                break
            except:
                time.sleep(delay)
                delay *= 2
        else:
            raise RuntimeError("Cannot start flask server")
    def url(self, url=''):
        return 'http://localhost:%d%s' % (self.port, url)
    def stop(self):
        if self._thread:
            try:
                urlopen(self.url('/shutdown'))
            except HTTPError:
                pass  
            self._thread.join()
        self._thread = None
    def __repr__(self):
        return '<LiveServer listening at %s>' % self.url()

