class Op(NameableValue, DebugInfo):
    @staticmethod
    def _get_thread_ops():
        try:
            ops = get_thread_state().ops
        except AttributeError:
            ops = [None]
            get_thread_state().ops = ops
        return ops
    @staticmethod
    def get_all_ops():
        try:
            all_ops = get_thread_state().all_ops
        except AttributeError:
            all_ops = [None]
            get_thread_state().all_ops = all_ops
        return all_ops
    @staticmethod
    @contextmanager
    def all_ops(ops=None, isolate=False):
        if ops is None:
            ops = []
        try:
            all_ops = Op.get_all_ops()
            all_ops.append(ops)
            yield (ops)
        finally:
            all_ops.pop()
            parent = all_ops[-1]
            if not isolate and parent is not None:
                parent.extend(ops)
    @staticmethod
    def all_op_references(ops):
        op_set = OrderedSet(ops)
        def add_op(op):
            op_set.add(op)
            for key in op.__dict__:
                val = getattr(op, key)
                if isinstance(val, Op) and val not in op_set:
                    add_op(val)
                elif isinstance(val, dict):
                    for subkey in val:
                        if isinstance(val[subkey], Op) and val[subkey] not in op_set:
                            add_op(val[subkey])
                elif isinstance(val, (list, tuple, set, OrderedSet)):
                    for item in val:
                        if isinstance(item, Op) and item not in op_set:
                            add_op(item)
        for op in ops:
            add_op(op)
        return op_set
    @staticmethod
    def ordered_ops(results):
        ordered_ops = []
        Op.visit_input_closure(results, lambda o: ordered_ops.append(o))
        return ordered_ops
    @staticmethod
    def visit_input_closure(roots, fun):
        available = OrderedSet()
        counts = dict()
        parents = defaultdict(OrderedSet)
        ready = OrderedSet()
        available.update(root.forwarded for root in roots)
        while available:
            node = available.pop()
            node.update_forwards()
            if node in counts:
                continue
            children = OrderedSet((child.forwarded for child in node.control_deps))
            if children:
                counts[node] = len(children)
                for child in children:
                    parents[child].add(node)
                available.update(children)
            else:
                ready.add(node)
        while ready:
            node = ready.pop()
            fun(node)
            for p in parents.get(node, []):
                count = counts[p] - 1
                if count == 0:
                    ready.add(p)
                    del counts[p]
                else:
                    counts[p] = count
        if len(counts) > 0:
            raise ValueError("Graph not a DAG")
    def __init__(self,
                 args=(),
                 metadata=None,
                 const=None,
                 constant=False,
                 persistent=False,
                 trainable=False,
                 **kwargs):
        super(Op, self).__init__(**kwargs)
        self._args = tuple(as_op(arg) for arg in args)
        self.metadata = dict()
        if metadata is not None:
            if not isinstance(metadata, dict):
                raise ValueError("Metadata must be of type dict,"
                                 "not {} of {}".format(type(metadata), metadata))
            self.metadata.update(metadata)
        self._control_deps = OrderedSet()
        self._deriv_handler = None
        self._const = const
        self.uuid = uuid.uuid4()
        self._is_constant = constant
        self._is_persistent = persistent
        self._is_trainable = trainable
        ops = Op._get_thread_ops()[-1]
        if ops is not None:
            ops.append(self)
        all_ops = Op.get_all_ops()[-1]
        if all_ops is not None:
            all_ops.append(self)
        self.style = {}
        self._forward = None
    @property
    def tensor(self):
        return self
    @property
    def states_read(self):
        return OrderedSet()
    @property
    def states_written(self):
        return OrderedSet()
    def __str__(self):
        return self.graph_label
    def __repr__(self):
        return '<{cl}({gl}):{id}>'.format(
            cl=self.__class__.__name__,
            gl=self.graph_label_type,
            id=id(self)
        )
    @property
    def is_constant(self):
        return False
    @property
    def const(self):
        return None
    @property
    def is_input(self):
        return False
    @property
    def is_persistent(self):
        return False
    @property
    def is_trainable(self):
        return False
    @property
    def is_placeholder(self):
        return False
    @property
    def is_tensor_op(self):
        return False
    @property
    def is_scalar(self):
        return 0 == len(self.axes)
    @property
    def is_device_op(self):
        return True
    @property
    def scalar_op(self):
        if not self.is_scalar:
            raise ValueError()
        return self
    @property
    def args(self):
        return self._args
    @property
    def forward(self):
        return self._forward
    @forward.setter
    def forward(self, value):
        self.update_forwards()
        value.update_forwards()
        for dep in self._control_deps:
            value.add_control_dep(dep)
        self._forward = value
        tdcache.tensor_description_cache.clear()
        value.metadata.update(self.metadata)
    @property
    def forwarded(self):
        result = self
        while True:
            if result._forward is None:
                return result
            result = result._forward
    @property
    def control_deps(self):
        return self._control_deps | OrderedSet(self.args)
    def add_control_dep(self, dep):
        dep = dep.forwarded
        if dep is not self and dep not in self.control_deps:
            self._control_deps.add(dep)
    def remove_control_dep(self, dep):
        self.update_forwards()
        self._control_deps.remove(dep.forwarded)
    def update_forwards(self):
        for op in self.control_deps:
            if op.forward is not None:
                self._args = tuple(arg.forwarded for arg in self._args)
                control_deps = self._control_deps
                self._control_deps = OrderedSet()
                for op in control_deps:
                    self.add_control_dep(op.forwarded)
                break
    def replace_self(self, rep):
        self.forward = as_op(rep)
    @property
    def deriv_handler(self):
        if self._deriv_handler is None:
            return self
        else:
            return self._deriv_handler
    @deriv_handler.setter
    def deriv_handler(self, deriv_handler):
