class Cluster(object):
    def __init__(self, remotes=None):
        self.remotes = {}
        if remotes is not None:
            for remote, roles in remotes:
                self.add(remote, roles)
    def __repr__(self):
        remotes = [(k, v) for k, v in self.remotes.items()]
        remotes.sort(key=lambda tup: tup[0].name)
        remotes = '[' + ', '.join('[{remote!r}, {roles!r}]'.format(
            remote=k, roles=v) for k, v in remotes) + ']'
        return '{classname}(remotes={remotes})'.format(
            classname=self.__class__.__name__,
            remotes=remotes,
            )
    def __str__(self):
        remotes = list(self.remotes.items())
        remotes.sort(key=lambda tup: tup[0].name)
        remotes = ((k, ','.join(v)) for k, v in remotes)
        remotes = ('{k}[{v}]'.format(k=k, v=v) for k, v in remotes)
        return ' '.join(remotes)
    def add(self, remote, roles):
        if remote in self.remotes:
            raise RuntimeError(
                'Remote {new!r} already found in remotes: {old!r}'.format(
                    new=remote,
                    old=self.remotes[remote],
                    ),
                )
        self.remotes[remote] = list(roles)
    def run(self, **kwargs):
        remotes = sorted(self.remotes.keys(), key=lambda rem: rem.name)
        return [remote.run(**kwargs) for remote in remotes]
    def write_file(self, file_name, content, sudo=False, perms=None, owner=None):
        remotes = sorted(self.remotes.keys(), key=lambda rem: rem.name)
        for remote in remotes:
            if sudo:
                teuthology.misc.sudo_write_file(remote, file_name, content, perms=perms, owner=owner)
            else:
                if perms is not None or owner is not None:
                    raise ValueError("To specify perms or owner, sudo must be True")
                teuthology.misc.write_file(remote, file_name, content)
    def only(self, *roles):
        c = self.__class__()
        want = frozenset(r for r in roles if not callable(r))
        matchers = [r for r in roles if callable(r)]
        for remote, has_roles in self.remotes.items():
            if frozenset(has_roles) & want != want:
                continue
            if not all(
                any(matcher(role) for role in has_roles)
                for matcher in matchers
                ):
                continue
            c.add(remote, has_roles)
        return c
    def exclude(self, *roles):
        matches = self.only(*roles)
        c = self.__class__()
        for remote, has_roles in self.remotes.items():
            if remote not in matches.remotes:
                c.add(remote, has_roles)
        return c

class User(models.AnonymousUser):
    def __init__(self, id=None, token=None, user=None, tenant_id=None,
                 service_catalog=None, tenant_name=None, roles=None,
                 authorized_tenants=None, endpoint=None, enabled=False,
                 services_region=None, user_domain_id=None,
                 user_domain_name=None, domain_id=None, domain_name=None,
                 project_id=None, project_name=None):
        self.id = id
        self.pk = id
        self.token = token
        self.username = user
        self.user_domain_id = user_domain_id
        self.user_domain_name = user_domain_name
        self.domain_id = domain_id
        self.domain_name = domain_name
        self.project_id = project_id or tenant_id
        self.project_name = project_name or tenant_name
        self.service_catalog = service_catalog
        self._services_region = (services_region or
                                 self.default_services_region())
        self.roles = roles or []
        self.endpoint = endpoint
        self.enabled = enabled
        self._authorized_tenants = authorized_tenants
        self.tenant_id = self.project_id
        self.tenant_name = self.project_name
    def __unicode__(self):
        return self.username
    def __repr__(self):
        return "<%s: %s>" % (self.__class__.__name__, self.username)
    def is_token_expired(self):
        if self.token is None:
            return None
        return not utils.check_token_expiration(self.token)
    def is_authenticated(self):
        return (self.token is not None and
                utils.check_token_expiration(self.token))
    def is_anonymous(self):
        return not self.is_authenticated()
    @property
    def is_active(self):
        return self.enabled
    @property
    def is_superuser(self):
        return 'admin' in [role['name'].lower() for role in self.roles]
    @property
    def authorized_tenants(self):
        insecure = getattr(settings, 'OPENSTACK_SSL_NO_VERIFY', False)
        ca_cert = getattr(settings, "OPENSTACK_SSL_CACERT", None)
        if self.is_authenticated() and self._authorized_tenants is None:
            endpoint = self.endpoint
            token = self.token
            try:
                self._authorized_tenants = utils.get_project_list(
                    user_id=self.id,
                    auth_url=endpoint,
                    token=token.id,
                    insecure=insecure,
                    cacert=ca_cert,
                    debug=settings.DEBUG)
            except (keystone_exceptions.ClientException,
                    keystone_exceptions.AuthorizationFailure):
                LOG.exception('Unable to retrieve project list.')
        return self._authorized_tenants or []
    @authorized_tenants.setter
    def authorized_tenants(self, tenant_list):
        self._authorized_tenants = tenant_list
    def default_services_region(self):
        if self.service_catalog:
            for service in self.service_catalog:
                if service['type'] == 'identity':
                    continue
