class LinearOperator(object):
    def __init__(self, shape, dtype, dot=None, dot_adj=None):
        if len(shape)!=2 or not isintlike(shape[0]) or not isintlike(shape[1]):
            raise ValueError('shape must be (m,n) with m and n integer')
        self.shape = shape
        self.dtype = numpy.dtype(dtype) 
        if dot is None and dot_adj is None:
            raise ValueError('dot or dot_adj have to be defined')
        self._dot = dot
        self._dot_adj = dot_adj
    def dot(self, X):
        X = numpy.asanyarray(X)
        m, n = self.shape
        if X.shape[0]!=n:
            raise ValueError('dimension mismatch')
        if self._dot is None:
            raise ValueError('dot undefined')
        return self._dot(X)
    def dot_adj(self, X):
        X = numpy.asanyarray(X)
        m, n = self.shape
        if X.shape[0]!=m:
            raise ValueError('dimension mismatch')
        if self._dot_adj is None:
            raise ValueError('dot_adj undefined')
        return self._dot_adj(X)
    @property
    def adj(self):
        return _AdjointLinearOperator(self)
    def __mul__(self, X):
        try:
            if isinstance(X, LinearOperator):
                return _ProductLinearOperator(self, X)
            elif numpy.isscalar(X):
                return _ScaledLinearOperator(self, X)
            else:
                return self.dot(X)
        except ValueError:
            return NotImplemented
    def __rmul__(self, X):
        try:
            return _ScaledLinearOperator(self, X)
        except ValueError:
            return NotImplemented
    def __pow__(self, X):
        try:
            return _PowerLinearOperator(self, X)
        except ValueError:
            return NotImplemented
    def __add__(self, X):
        try:
            return _SumLinearOperator(self, X)
        except ValueError as e:
            return NotImplemented
    def __neg__(self):
        try:
            return _ScaledLinearOperator(self, -1)
        except ValueError as e:
            print(e)
            return NotImplemented
    def __sub__(self, X):
        return self + (-X)
    def __repr__(self):
        m, n = self.shape
        return '<%dx%d %s with dtype=%s>' % (m, n, self.__class__.__name__, str(self.dtype))

