class Set:
    def __init__(self, value = []):    
        self.data = []                 
        self.concat(value)
    def intersection(self, other):        
        res = []                       
        for x in self.data:
            if x in other:             
                res.append(x)
        return Set(res)                
    def union(self, other):            
        res = self.data[:]             
        for x in other:                
            if not x in res:
                res.append(x)
        return Set(res)
    def concat(self, value):
        for x in value:                
            if not x in self.data:     
                self.data.append(x)
    def __len__(self):          return len(self.data)        
    def __getitem__(self, key): return self.data[key]        
    def __and__(self, other):   return self.intersection(other) 
    def __or__(self, other):    return self.union(other)     
    def __repr__(self):         return 'Set({})'.format(repr(self.data))  
    def __iter__(self):         return iter(self.data)       
    def issubset(self, other):  
        return self<=other
    def __le__(self,other):
        return self.intersection(other).data==self.data
    def __lt__(self,other):
        return self.data!=other.data and self.intersection(other).data==self.data
    def issuperset(self, other):  return self>=other
    def __ge__(self,other):
        return self.intersection(other).data==other.data
    def __gt__(self,other):
        return self.data!=other.data and self.intersection(other).data==other.data
    def __ior__(self,other):   
        return self|other
    def __iand__(self,other):   
        return self&other
    def __isub__(self,other):
        interlist = self.intersection(other).data
        for i in self.data:
            if i in interlist:
                self.data.remove(i)
        return self
    def __ixor__(self,other):
        interlist = self.intersection(other).data
        unionlist = self.union(other).data
        new_list = []
        for i in unionlist:
            if i not in interlist:
                new_list.append(i)
        self.data = new_list
        return self 
    def add(self,elem): 
        self.data.append(elem)
    def remove(self,elem):
        if elem not in self.data:
            raise(KeyError)
        self.data.remove(elem)
    def intersection_update(self,other):
        self.data = self.intersection(other).data
    def difference_update(self,other):
        interlist = self.intersection(other).data
        self_data = []
        for i in self.data:
            if i not in interlist:
                self_data.append(i)
        self.data = self_data
    def symmetric_difference_update(self,other):
        interlist = self.intersection(other).data
        unionlist = self.union(other).data
        new_list = []
        for i in unionlist:
            if i not in interlist:
                new_list.append(i)
        self.data = new_list

