class Region(object):
    def __init__(self, a, b = None, xpos = -1):
        if b == None:
            b = a
        self.a = a
        self.b = b
        self.xpos = xpos
    def __str__(self):
        return "(" + str(self.a) + ", " + str(self.b) + ")"
    def __repr__(self):
        return "(" + str(self.a) + ", " + str(self.b) + ")"
    def __len__(self):
        return self.size()
    def __eq__(self, rhs):
        return isinstance(rhs, Region) and self.a == rhs.a and self.b == rhs.b
    def __lt__(self, rhs):
        lhs_begin = self.begin()
        rhs_begin = rhs.begin()
        if lhs_begin == rhs_begin:
            return self.end() < rhs.end()
        else:
            return lhs_begin < rhs_begin
    def empty(self):
        return self.a == self.b
    def begin(self):
        if self.a < self.b:
            return self.a
        else:
            return self.b
    def end(self):
        if self.a < self.b:
            return self.b
        else:
            return self.a
    def size(self):
        return abs(self.a - self.b)
    def contains(self, x):
        if isinstance(x, Region):
            return self.contains(x.a) and self.contains(x.b)
        else:
            return x >= self.begin() and x <= self.end()
    def cover(self, rhs):
        a = min(self.begin(), rhs.begin())
        b = max(self.end(), rhs.end())
        if self.a < self.b:
            return Region(a, b)
        else:
            return Region(b, a)
    def intersection(self, rhs):
        if self.end() <= rhs.begin():
            return Region(0)
        if self.begin() >= rhs.end():
            return Region(0)
        return Region(max(self.begin(), rhs.begin()), min(self.end(), rhs.end()))
    def intersects(self, rhs):
        lb = self.begin()
        le = self.end()
        rb = rhs.begin()
        re = rhs.end()
        return ((lb == rb and le == re) or
            (rb > lb and rb < le) or (re > lb and re < le) or
            (lb > rb and lb < re) or (le > rb and le < re))

