        if not isinstance(other, ResponseCustomerAttributeListResult):
            return False
        return self.__dict__ == other.__dict__
    def __ne__(self, other):
        return not self == other

class OilProps(OilWithEstimation):
    def __init__(self, oil_obj):
        super(OilProps, self).__init__(oil_obj)
        self._init_sara()
        self._bullwinkle = None
        self._bulltime = None
    def __repr__(self):
        return ('{0.__class__.__module__}.{0.__class__.__name__}('
                'oil_={0.record!r})'.format(self))
    name = property(lambda self: self.record.name,
                    lambda self, val: setattr(self.record, 'name', val))
    api = property(lambda self: self.get('api'))
    def get(self, prop):
        'get raw oil props'
        val = None
        try:
            val = getattr(self.record, prop)
        except AttributeError:
            try:
                val = getattr(self.record.imported, prop)
            except Exception:
                pass
        return val
    @property
    def bulltime(self):
        bulltime = -999.
        if self._bulltime is not None:
            return self._bulltime
        else:
            return bulltime
    @bulltime.setter
    def bulltime(self, value):
        self._bulltime = value
    @property
    def bullwinkle(self):
        if self._bullwinkle is not None:
            return self._bullwinkle
        else:
            return self.get('bullwinkle_fraction')
    @bullwinkle.setter
    def bullwinkle(self, value):
        self._bullwinkle = value
    @property
    def num_components(self):
        return len(self._sara)
    @property
    def molecular_weight(self):
        return self._component_mw()
    def _component_mw(self, sara_type=None):
        ret = self._sara['mol_wt']
        if sara_type is not None:
            ret = ret[np.where(self._sara['type'] == sara_type)]
        return ret
    @property
    def mass_fraction(self):
        return self._sara['fraction']
    @property
    def boiling_point(self):
        return self._sara['boiling_point']
    @property
    def component_density(self):
        return self._component_density()
    def _component_density(self, sara_type=None):
        ret = self._sara['density']
        if sara_type is not None:
            ret = ret[np.where(self._sara['type'] == sara_type)]
        return ret
    @property
    def component_types(self):
        return self._sara['type']
    @lru_cache(2)
    def vapor_pressure(self, temp, atmos_pressure=101325.0):
        D_Zb = 0.97
        R_cal = 1.987  
        D_S = 8.75 + 1.987 * np.log(self.boiling_point)
        C_2i = 0.19 * self.boiling_point - 18
        var = 1. / (self.boiling_point - C_2i) - 1. / (temp - C_2i)
        ln_Pi_Po = (D_S * (self.boiling_point - C_2i) ** 2 /
                    (D_Zb * R_cal * self.boiling_point) * var)
        Pi = np.exp(ln_Pi_Po) * atmos_pressure
        return Pi
    def tojson(self):
        return Oil.from_json(self.record.tojson()).tojson()
    def _compare__dict(self, other):
        for key, val in self.__dict__.iteritems():
            o_val = other.__dict__[key]
            if isinstance(val, np.ndarray):
                if np.any(val != o_val):
                    return False
            else:
                if val != o_val:
                    return False
        return True
    def __eq__(self, other):
        if type(self) != type(other):
            return False
        if self._compare__dict(other):
            return True
        try:
            return self.tojson() == other.tojson()
        except Exception:
            return False
    def __ne__(self, other):
        return not self == other
    def __deepcopy__(self, memo):
        c_op = self.__class__(self.record)
        if c_op != self:
            for attr in c_op.__dict__:
                if getattr(self, attr) != getattr(c_op, attr):
                    setattr(c_op, attr,
                            copy.deepcopy(getattr(self, attr), memo))
        return c_op
    def _init_sara(self):
        all_comp = list(chain(*[sorted(list(g), key=lambda s: s.sara_type,
                                       reverse=True)
                                for _k, g
                                in groupby(sorted(self.record.sara_fractions,
                                                  key=lambda s: s.ref_temp_k),
                                           lambda x: x.ref_temp_k)]
                              ))
        all_dens = list(chain(*[sorted(list(g), key=lambda s: s.sara_type,
                                       reverse=True)
                                for _k, g
                                in groupby(sorted(self.record.sara_densities,
                                                  key=lambda s: s.ref_temp_k),
                                           lambda x: x.ref_temp_k)]
                              ))
        all_mw = list(chain(*[sorted(list(g), key=lambda s: s.sara_type,
                                     reverse=True)
                              for _k, g
                              in groupby(sorted(self.record.molecular_weights,
                                                key=lambda s: s.ref_temp_k),
                                         lambda x: x.ref_temp_k)]
                            ))
        items = []
        sum_frac = 0.
        for comp, dens, mol_wt in izip_longest(all_comp, all_dens, all_mw):
            if (comp.ref_temp_k != comp.ref_temp_k or
                    comp.sara_type != comp.sara_type):
                msg = "mismatch in sara_fractions and sara_densities tables"
                raise ValueError(msg)
            if comp.fraction > 0.0:
                if hasattr(mol_wt, 'g_mol'):
                    mw = mol_wt.g_mol
                else:
                    if comp.sara_type == 'Resins':
                        mw = 800.0
                    elif comp.sara_type == 'Asphaltenes':
                        mw = 1000.0
                items.append((comp.sara_type, comp.ref_temp_k, comp.fraction,
                              dens.density, mw))
                sum_frac += comp.fraction
        self._sara = np.asarray(items, dtype=sara_dtype)
        if not np.isclose(self._sara[:]['fraction'].sum(), 1.0):
            msg = ("mass fraction sum: {0} - sum should be approximately 1.0"
                   .format(self._sara[:]['fraction'].sum()))
            raise ValueError(msg)

class PreviousPage(object):
    openapi_types = {
        'before': 'str',
        'link': 'str'
    }
    attribute_map = {
        'before': 'before',
        'link': 'link'
    }
    def __init__(self, before=None, link=None, local_vars_configuration=None):  
        if local_vars_configuration is None:
            local_vars_configuration = Configuration()
        self.local_vars_configuration = local_vars_configuration
        self._before = None
        self._link = None
        self.discriminator = None
        self.before = before
        if link is not None:
            self.link = link
    @property
    def before(self):
        return self._before
    @before.setter
    def before(self, before):
        if self.local_vars_configuration.client_side_validation and before is None:  
            raise ValueError("Invalid value for `before`, must not be `None`")  
        self._before = before
    @property
    def link(self):
        return self._link
    @link.setter
    def link(self, link):
        self._link = link
    def to_dict(self):
        result = {}
        for attr, _ in six.iteritems(self.openapi_types):
            value = getattr(self, attr)
            if isinstance(value, list):
                result[attr] = list(map(
                    lambda x: x.to_dict() if hasattr(x, "to_dict") else x,
                    value
                ))
            elif hasattr(value, "to_dict"):
                result[attr] = value.to_dict()
            elif isinstance(value, dict):
                result[attr] = dict(map(
                    lambda item: (item[0], item[1].to_dict())
                    if hasattr(item[1], "to_dict") else item,
                    value.items()
                ))
            else:
                result[attr] = value
        return result
    def to_str(self):
        return pprint.pformat(self.to_dict())
    def __repr__(self):
        return self.to_str()
    def __eq__(self, other):
        if not isinstance(other, PreviousPage):
            return False
        return self.to_dict() == other.to_dict()
    def __ne__(self, other):
        if not isinstance(other, PreviousPage):
            return True
        return self.to_dict() != other.to_dict()

class Policy(object):
  def __init__(self, name):
    if isinstance(name, dtypes.DType):
      raise TypeError("'name' must be a string, not a DType. "
                      "Instead, pass DType.name. Got: %s" % (name.name,))
    elif not isinstance(name, str):
      raise TypeError("'name' must be a string, but got: %s" % (name,))
    self._name = name
    self._compute_dtype, self._variable_dtype = self._parse_name(name)
    if name in ('mixed_float16', 'mixed_bloat16'):
      device_compatibility_check.log_device_compatibility_check(name)
  def _parse_name(self, name):
    if name.endswith('_float32_vars'):
      error_msg = ('Policies ending in \'_float32_vars\' have been removed '
                   'from TensorFlow.')
      if name in ('infer_float32_vars', 'infer_with_float32_vars'):
        error_msg += (' Please use the \'mixed_float16\' or \'mixed_bfloat16\' '
                      'policy instead.')
      elif name == 'float16_with_float32_vars':
        error_msg += (' Please use the \'mixed_float16\' policy instead.')
      elif name == 'bfloat16_with_float32_vars':
        error_msg += (' Please use the \'mixed_bfloat16\' policy instead.')
      error_msg += ' Got policy name: \'%s\'' % name
      raise ValueError(error_msg)
    if name == 'mixed_float16':
      return 'float16', 'float32'
    elif name == 'mixed_bfloat16':
      return 'bfloat16', 'float32'
    elif name == '_infer':
      return None, None
    try:
      dtype = dtypes.as_dtype(name).name
    except TypeError:
      error = ("Cannot convert value %s to a mixed precision Policy. "
               "Valid policies include 'mixed_float16', 'mixed_bfloat16', "
               "and the name of any dtype such as 'float32'." % (name,))
      raise ValueError(error)
    return dtype, dtype
  @property
  def variable_dtype(self):
    return self._variable_dtype
  @property
  def compute_dtype(self):
    return self._compute_dtype
  @property
  def name(self):
    return self._name
  def __repr__(self):
    return '<Policy "%s">' % self._name
  def get_config(self):
    return {'name': self.name}
  @classmethod
  def from_config(cls, config, custom_objects=None):
    del custom_objects
    if 'loss_scale' in config:
      config = config.copy()
      del config['loss_scale']
    return cls(**config)

class PolicyV1(Policy):
  def __init__(self, name, loss_scale='auto'):
    super(PolicyV1, self).__init__(name)
    if loss_scale == 'auto':
      loss_scale = 'dynamic' if name == 'mixed_float16' else None
      self._using_default_loss_scale = True
    else:
      self._using_default_loss_scale = False
    if loss_scale and self._compute_dtype not in (None, 'float16'):
      tf_logging.warning(
          'Creating a Policy with a loss scale is only useful for '
          'float16 policies. You passed loss_scale=%r for policy '
          '%s. Consider not passing any loss_scale instead.' %
          (loss_scale, name))
    self._loss_scale = keras_loss_scale_module.get(loss_scale)
  @property
  def loss_scale(self):
    return self._loss_scale
  def __repr__(self):
    return '<PolicyV1 "%s", loss_scale=%s>' % (self._name, self.loss_scale)
  def get_config(self):
    config = {
        'name': self.name
    }
    if not self._using_default_loss_scale:
      config['loss_scale'] = keras_loss_scale_module.serialize(self.loss_scale)
    return config
  @classmethod
  def from_config(cls, config, custom_objects=None):
    if 'loss_scale' in config and isinstance(config['loss_scale'], dict):
      config = config.copy()
      config['loss_scale'] = keras_loss_scale_module.deserialize(
          config['loss_scale'], custom_objects=custom_objects)
    return cls(**config)

class Vocab(object):
    def __init__(self, counts=None, max_size=None,
                 emb_id=None, emb_train=None, emb_dims=0, emb_file=None, emb_minfreq=1,
                 no_special_indices=False,
                 pad_index_only=False,
                 emb_dir=None,
                 pad_string="", oov_string="<<oov>>"):
        if counts:
            self.freqs = Counter(counts)
        else:
            self.freqs = Counter()
        if emb_train == "onehot" and not no_special_indices:
            pad_index_only = True
        self.no_special_indices = no_special_indices
        self.pad_index_only = pad_index_only
        self.emb_minfreq = emb_minfreq or 1
        self.max_size = max_size
        self.emb_dims = emb_dims
        self.emb_id = emb_id
        self.emb_file = emb_file
        self.emb_train = emb_train
        self.itos = None
        self.stoi = None
        self.stoe = {}
        self.emb_dir = emb_dir
        self.n = 0
        self.pad_string = pad_string
        self.oov_string = oov_string
        self.finished = False
        self.embeddings_loaded = False
        self.embeddings = None
        self.oov_emb = None
        if self.emb_train and self.emb_train not in ["yes", "mapping", "no", "onehot"]:
            raise Exception("Vocab emb_train must be one of yes, mapping, no, onehot but is "+str(self.emb_train))
        if not self.emb_file and self.emb_train == "mapping":
            raise Exception("Vocab emb_train 'mapping' not usable without embeddings file, "
                            "got emb_train=%s and emb_file=%s" % (self.emb_train, self.emb_file))
        if self.emb_file and self.emb_train == "onehot":
            raise Exception("Vocab emb_train 'onehot' not usable with embeddings file, "
                            "got emb_train=%s and emb_file=%s" % (self.emb_train, self.emb_file))
        self.have_oov = True
        self.have_pad = True
        self.have_vocab = False  
        if no_special_indices:
            self.have_oov = False
            self.have_pad = False
        if pad_index_only:
            self.have_oov = False
    def check_finished(self, method="method"):
        if not self.finished:
            raise Exception("Cannot call", method, "unless the finish() method has been called first!")
    def check_nonfinished(self, method="method"):
        if self.finished:
            raise Exception("Cannot call", method, "after the finish() method has been called!")
    def embs4line(self, line, fromidx, dims):
        embs = []
        toidx = fromidx
        for i in range(dims):
            fromidx = toidx + 1
            toidx = line.find(" ", fromidx)
            if toidx < 0:
                toidx = len(line)
            embs.append(float(line[fromidx:toidx]))
            return embs
    def load_embeddings(self, emb_file, filterset=None):
        if filterset is None:
            filterset = set()
        n_lines = 0
        n_added = 0
        n_vocab = len(self.itos)
        if emb_file.endswith(".txt") or emb_file.endswith(".vec") or emb_file.endswith(".txt.gz"):
            if emb_file.endswith(".txt.gz"):
                reader = gzip.open
            else:
                reader = open
            logger.info("Loading embeddings for %s from %s (%s words)" % (self.emb_id, emb_file, n_vocab))
            n_expected = 0
            with reader(emb_file, 'rt', encoding="utf-8") as infile:
                for line in infile:
                    if n_added == n_vocab:
                        logger.info("Got all %s embeddings needed, stopping reading the embeddings file" % (n_vocab,))
                        break
                    if n_lines == 0:
                        m = re.match(r'^\s*([0-9]+)\s+([0-9]+)\s*$', line)
                        if m:
                            n_expected = int(m.group(1))
                            self.emb_dims = int(m.group(2))
                            n_lines += 1
                            continue
                        else:
                            self.emb_dims = len(line.split())-1
                            n_expected = -1
                    n_lines += 1
                    if n_lines % 100000 == 0:
                        logger.info("Read lines from embeddings file: %s of %s, added words: %s of %s" %
                                    (n_lines, n_expected, n_added, n_vocab))
                    line = line.strip()
                    toidx = line.find(" ")
                    word = line[0:toidx]
                    if filterset:
                        if word not in filterset:
                            n_added += 1
                            self.stoe[word] = self.embs4line(line, toidx, self.emb_dims)
                    else:
                        if word in self.stoi:
                            n_added += 1
                            self.stoe[word] = self.embs4line(line, toidx, self.emb_dims)
        elif emb_file.endswith(".vocab") or emb_file.endswith(".npy"):
            raise Exception("TODO: format .vocab/.npy not yet implemented!")
        elif emb_file.endswith(".gensim"):
            gensimmodel = gensim.models.KeyedVectors.load(emb_file, mmap='r')
            raise Exception(".gensim format for embeddings not yet implemented")
        else:
            raise Exception("Embeddings file must have one of the extensions: .txt, .txt.gz, .vocab, .npy")
        self.embeddings_loaded = True
        logger.info("Embeddings for %s loaded: %s, dims=%s" % (self.emb_id, n_added, self.emb_dims))
    def get_embeddings(self):
        self.check_finished("get_embeddings")
        return self.embeddings
    @staticmethod
    def rnd_vec(dims, strng=None, as_numpy=True):
        if str:
            np.random.seed(hash(strng) % (2**32-1))
        vec = np.random.randn(dims).astype(np.float32)
        if as_numpy:
            return vec
        else:
            return list(vec)
    def zero_vec(self, as_numpy=True):
        if as_numpy:
            return np.zeros(self.emb_dims, np.float32)
        else:
            return list(np.zeros(self.emb_dims, np.float32))
    def add_counts(self, counts):
        self.check_nonfinished("add_counts")
        self.freqs.update(counts)
    def set_emb_minfreq(self, min_freq=1):
        self.check_nonfinished("set_emb_minfreq")
        self.emb_minfreq = min_freq
    def set_max_size(self, max_size=None):
        self.check_nonfinished("set_max_size")
        self.max_size = max_size
    def set_emb_id(self, embid):
        self.check_nonfinished("set_emb_id")
        self.emb_id = embid
    def set_emb_file(self, file):
        self.check_nonfinished("set_emb_file")
        self.emb_file = file
    def set_emb_dims(self, dim):
        self.check_nonfinished("set_emb_dims")
        self.emb_dims = dim
    def finish(self, remove_counts=True):
        self.check_nonfinished("finish")
        if not self.emb_train:
            if self.emb_file:
                self.emb_train = "no"
            else:
                self.emb_train = "yes"
        if self.have_oov:
            if self.oov_string in self.freqs:
                logger.debug("OOV symbol removed from frequencies, freq=%s, id=%s" %
                             (self.freqs[self.pad_string], self.emb_id))
                del self.freqs[self.oov_string]
        if self.have_pad:
            if self.pad_string in self.freqs:
                logger.debug("Pad symbol removed from frequencies, freq=%s, id=%s" %
                             (self.freqs[self.pad_string], self.emb_id))
                del self.freqs[self.pad_string]
        filtered_words = set()
        self.itos = []
        for s in self.freqs:
            if self.freqs[s] >= self.emb_minfreq:
                self.itos.append(s)
            else:
                filtered_words.add(s)
        self.itos = sorted(self.itos)
        self.itos = sorted(self.itos, reverse=True, key=lambda x: self.freqs[x])
        if self.no_special_indices:
            pass  
        elif self.pad_index_only:
            self.itos = [self.pad_string] + self.itos
        else:
            self.itos = [self.pad_string] + [self.oov_string] + self.itos
        if self.max_size and len(self.itos) > self.max_size:
            for w in self.itos[self.max_size:]:
                filtered_words.add(w)
            self.itos = self.itos[:self.max_size]
        self.stoi = defaultdict(int)
        for i, s in enumerate(self.itos):
            self.stoi[s] = i
        self.n = len(self.itos)
        if self.emb_train == "onehot":
            if self.have_pad:
                self.emb_dims = self.n - 1
            else:
                self.emb_dims = self.n
        if not self.emb_file and not self.emb_dims:
            self.emb_dims = int(math.log2(self.n)**1.8)+1
        if self.emb_file:
            self.load_embeddings(self.emb_file, filterset=filtered_words)
            if filtered_words:
                for s in self.stoi:
                    if s not in self.stoe:
                        self.stoe[s] = self.rnd_vec(dims=self.emb_dims, strng=s)
                words2add = set()
                for s in self.stoe:
                    if s not in self.stoi:
                        words2add.add(s)
                for s in words2add:
                    self.itos.append(s)
                    self.stoi[s] = self.n
                    self.n += 1
            else:
                self.itos = [w for w in self.itos if w == self.pad_string or w == self.oov_string or w in self.stoe]
                self.stoi = defaultdict(int)
                for i, s in enumerate(self.itos):
                    self.stoi[s] = i
                self.n = len(self.itos)
            if self.have_oov:
                self.stoe[self.oov_string] = self.rnd_vec(dims=self.emb_dims, strng=self.oov_string)
            if self.have_pad:
                self.stoe[self.pad_string] = self.zero_vec()
            self.embeddings = np.zeros((self.n, self.emb_dims), np.float32)
            for s in self.stoi:
                idx = self.stoi[s]
                emb = self.stoe[s]
                self.embeddings[idx] = emb
        else:  
            if self.emb_train == "onehot":
                self.embeddings = np.zeros((self.n, self.emb_dims), np.float32)
                fromindex = 0
                if self.have_pad:
                    fromindex = 1
                j = 0
                for i in range(fromindex, self.n):
                    self.embeddings[i, j] = 1.0
                    j += 1
            else:
                self.embeddings = np.random.randn(self.n, self.emb_dims).astype(np.float32)
                if not self.no_special_indices:
                    self.embeddings[0] = np.zeros(self.emb_dims, np.float32)
        self.stoe = None
        if remove_counts:
            self.freqs = None
        self.finished = True
    def idx2string(self, idx):
        self.check_finished("idx2string")
        if idx >= len(self.itos):
            raise Exception("Vocab: index larger than vocabulary size")
        else:
            return self.itos[idx]
    def string2idx(self, string):
        self.check_finished("string2idx")
        if string in self.stoi:
            return self.stoi[string]  
        else:
            if self.have_oov:
                return self.stoi[self.oov_string]
            else:
                raise Exception("String not found in vocab and do not have OOV symbol either: %s" % string)
    def string2emb(self, string):
        self.check_finished("string2emb")
        if self.embeddings is None:
            raise Exception("Cannot get embedding vector, no embeddings matrix")
        if string in self.stoi:
            return self.embeddings[self.stoi[string]]
        else:
            if self.have_oov:
                return self.embeddings[self.stoi[self.oov_string]]
            else:
                raise Exception("Cannot return embedding vector, string not found and no OOV symbol: %s" % string)
    def string2onehot(self, thestring):
        if not self.finished:
            raise Exception("Vocab %r has not been finished!" % self)
        vec = self.zero_onehotvec()
        if self.have_pad and thestring == self.pad_string:
            return vec
        if thestring in self.stoi:
            l = self.stoi[thestring]
        elif self.have_oov:
            l = self.stoi[self.oov_string]
        else:
            raise Exception("String not found in vocab and no OOV symbol: %s" % (thestring,))
        if self.have_pad:
            l -= 1
        vec[l] = 1.0
        return vec
    def zero_onehotvec(self):
        l = len(self.itos)
        if self.have_pad:
            l -= 1
        return [0.0] * l
    def onehot2string(self, vec):
        if not self.finished:
            raise Exception("Vocab has not been finished!")
        s = sum(vec)
        if self.have_pad and s == 0.0:
            return self.pad_string
        if s != 1.0:
            raise Exception("Not a proper one-hot vector: %s" % (vec,))
        idx = vec.index(1.0)
        if self.have_pad:
            idx += 1
        return self.itos[idx]
    def count(self, strng):
        if self.freqs:
            c = self.freqs.get(strng)
            if c:
                return c
            else:
                return 0
        else:
            raise Exception("Cannot retrieve count, data has been removed")
    def size(self):
        return len(self.itos)
    def __str__(self):
        return self.__repr__()+":nentries=%d" % len(self.stoi)
    def __repr__(self):
        tmp_entries = [self.itos[i] for i in range(min(len(self.itos),20))]
        return "Vocab(n=%d,emb_id=%r,emb_train=%r,emb_file=%r,emb_dims=%d,entries=%s)" % \
               (len(self.stoi), self.emb_id, self.emb_train, self.emb_file, self.emb_dims, tmp_entries)

