                            _dup2(c2pwrite, 1)
                            _dup2(errwrite, 2)
                            closed = set([None])
                            for fd in [p2cread, c2pwrite, errwrite]:
                                if fd not in closed and fd > 2:
                                    os.close(fd)
                                    closed.add(fd)
                            if close_fds:
                                self._close_fds(but=errpipe_write)
                            if cwd is not None:
                                os.chdir(cwd)
                            if preexec_fn:
                                preexec_fn()
