class TransposeFront(object):
    def __init__(self, obj, ndims, front, reverse=False):
        assert front < ndims
        self.obj = obj
        self.ndims = ndims
        self.front = front
        self.reverse = reverse
    def __order(self):
        order = list(range(self.ndims))
        front_elem = order.pop(self.front)
        if self.reverse:
            order.reverse()
        order.insert(0, front_elem)
        return order
    def __order_without(self, keep_dim):
        order = []
        next = 0
        for k in keep_dim:
            if k:
                order.append(next)
                next += 1
            else:
                order.append(None)
        front_elem = order.pop(self.front)
        if self.reverse:
            order.reverse()
        order.insert(0, front_elem)
        order = [o for o in order if o is not None]
        return order
    def __order_inv(self):
        order = self.__order()
        order_inv = [0] * len(order)
        for i in range(len(order)):
            order_inv[order[i]] = i
        return order_inv
    @property
    def shape(self):
        shape_inner = self.obj.shape
        assert self.ndims == len(shape_inner)
        shape = tuple(shape_inner[i] for i in self.__order())
        return shape
    def __getitem__(self, item):
        if not isinstance(item, collections.Iterable):
            item = (item,)
        assert len(item) <= self.ndims
        item_all = [np.s_[:],] * self.ndims
        keep_dim = np.ones(self.ndims, dtype=bool)
        for n, it in enumerate(item):
            item_all[n] = it
            if isinstance(it, int):
                keep_dim[n] = False
        item_inner = tuple(item_all[i] for i in self.__order_inv())
        data = self.obj[item_inner]
        data = np.transpose(data, axes=self.__order_without(keep_dim))
        return data
    def __repr__(self):
        classname = type(self).__name__
        string = "{}(obj={}, ndims={}, front={}, reverse={})".format(classname, repr(self.obj), repr(self.ndims),
                                                                     repr(self.front), repr(self.reverse))
        return string
    def __len__(self):
        return self.shape[0]

class IndicesCollection(object):
    def __init__(self, coll=None, id_array=None):
        self.coll = coll
        if id_array is not None:
            self.from_id_array(id_array)
    def __repr__(self):
        return repr(self.coll)
    def __str__(self):
        return str(self.coll)
    def getitem(self, obj):
        result = []
        ids = []
        for c in self.coll:
            obj_inner = obj
            if not isinstance(c, collections.Iterable):
                c = (c,)
            ids_act = []
            for ind in c:
                if isinstance(ind, slice):
                    s = ind.indices(len(obj_inner))
                    ids_act.append((np.arange(s[0], s[1], s[2]),))
                else:
                    ids_act.append(ind)
                obj_inner = obj_inner[ind]
            result.append(obj_inner)
            ids.append(ids_act)
        result = np.concatenate(result)
        id_array = IndicesCollection(ids).to_id_array()
        return result, id_array
    def to_id_array(self):
        id_all = np.zeros((0,0), dtype=int)
        for c in self.coll:
            id_prefix = np.zeros((1, 0), dtype=int)
            if not isinstance(c, collections.Iterable):
                c = (c,)
            for ind in c:
                ind = np.array(ind, dtype=int)
                ind = ind.reshape(-1,1)
                if ind.shape[0] > 1:
                    id_prefix = np.broadcast_to(id_prefix, (ind.shape[0], id_prefix.shape[1]))
                if id_prefix.shape[0] > 1:
                    ind = np.broadcast_to(ind, (id_prefix.shape[0], ind.shape[1]))
                id_prefix = np.concatenate([id_prefix, ind], axis=1)
            if id_all.shape[0] == 0:
                id_all = id_prefix
            else:
                id_all = np.concatenate([id_all, id_prefix], axis=0)
        return id_all
    def from_id_array(self, id_all):
        self.coll = []
        self.__from_id_array_rec(id_all)
    def __from_id_array_rec(self, id_all):
        if id_all.shape[0] == 0:
            return
        if id_all.shape[1] == 1:
            self.coll.append([(id_all,)])
            return
        id_next = id_all[0,:-1]
        ind = np.all(id_all[:,:-1] == id_next, axis=1)
        ind_tuple = [x for x in id_next]
        ind_tuple.append((id_all[ind,-1],))
        self.coll.append(ind_tuple)
        id_all = id_all[~ind, :]
        self.__from_id_array_rec(id_all)

class URL:
    def __init__(
        self,
        url: URLTypes,
        allow_relative: bool = False,
        params: QueryParamTypes = None,
    ) -> None:
        if isinstance(url, str):
            self._uri_reference = rfc3986.api.iri_reference(url).encode()
        else:
            self._uri_reference = url._uri_reference
        if self.is_absolute_url:
            self._uri_reference = self._uri_reference.normalize()
        if params:
            query_string = str(QueryParams(params))
            self._uri_reference = self._uri_reference.copy_with(query=query_string)
        if not allow_relative:
            if not self.scheme:
                raise InvalidURL("No scheme included in URL.")
            if not self.host:
                raise InvalidURL("No host included in URL.")
        self._full_path: typing.Optional[str] = None
    @property
    def scheme(self) -> str:
        return self._uri_reference.scheme or ""
    @property
    def authority(self) -> str:
        return self._uri_reference.authority or ""
    @property
    def userinfo(self) -> str:
        return self._uri_reference.userinfo or ""
    @property
    def username(self) -> str:
        userinfo = self._uri_reference.userinfo or ""
        return userinfo.partition(":")[0]
    @property
    def password(self) -> str:
        userinfo = self._uri_reference.userinfo or ""
        return userinfo.partition(":")[2]
    @property
    def host(self) -> str:
        return self._uri_reference.host or ""
    @property
    def port(self) -> int:
        port = self._uri_reference.port
        if port is None:
            return {"https": 443, "http": 80}[self.scheme]
        return int(port)
    @property
    def path(self) -> str:
        return self._uri_reference.path or "/"
    @property
    def query(self) -> str:
        return self._uri_reference.query or ""
    @property
    def full_path(self) -> str:
        if self._full_path is not None:
            return self._full_path
        path = self.path
        if self.query:
            path += "?" + self.query
        return path
    @full_path.setter
    def full_path(self, value: typing.Optional[str]) -> None:
        self._full_path = value
    @property
    def fragment(self) -> str:
        return self._uri_reference.fragment or ""
    @property
    def is_ssl(self) -> bool:
        return self.scheme == "https"
    @property
    def is_absolute_url(self) -> bool:
        return bool(self.scheme and self.host)
    @property
    def is_relative_url(self) -> bool:
        return not self.is_absolute_url
    @property
    def origin(self) -> "Origin":
        return Origin(self)
    def copy_with(self, **kwargs: typing.Any) -> "URL":
        if (
            "username" in kwargs
            or "password" in kwargs
            or "host" in kwargs
            or "port" in kwargs
        ):
            host = kwargs.pop("host", self.host)
            port = kwargs.pop("port", self.port)
            username = kwargs.pop("username", self.username)
            password = kwargs.pop("password", self.password)
            authority = host
            if port is not None:
                authority += f":{port}"
            if username is not None:
                userpass = username
                if password is not None:
                    userpass += f":{password}"
                authority = f"{userpass}@{authority}"
            kwargs["authority"] = authority
        return URL(self._uri_reference.copy_with(**kwargs).unsplit())
    def join(self, relative_url: URLTypes) -> "URL":
        if self.is_relative_url:
            return URL(relative_url)
        base_uri = self._uri_reference.copy_with(fragment=None)
        relative_url = URL(relative_url, allow_relative=True)
        return URL(relative_url._uri_reference.resolve_with(base_uri).unsplit())
    def __hash__(self) -> int:
        return hash(str(self))
    def __eq__(self, other: typing.Any) -> bool:
        return isinstance(other, (URL, str)) and str(self) == str(other)
    def __str__(self) -> str:
        return self._uri_reference.unsplit()
    def __repr__(self) -> str:
        class_name = self.__class__.__name__
        url_str = str(self)
        if self._uri_reference.userinfo:
            url_str = (
                rfc3986.urlparse(url_str)
                .copy_with(userinfo=f"{self.username}:[secure]")
                .unsplit()
            )
        return f"{class_name}({url_str!r})"

class Origin:
    def __init__(self, url: URLTypes) -> None:
        if not isinstance(url, URL):
            url = URL(url)
        self.scheme = url.scheme
        self.is_ssl = url.is_ssl
        self.host = url.host
        self.port = url.port
    def __eq__(self, other: typing.Any) -> bool:
        return (
            isinstance(other, self.__class__)
            and self.scheme == other.scheme
            and self.host == other.host
            and self.port == other.port
        )
    def __hash__(self) -> int:
        return hash((self.scheme, self.host, self.port))
    def __repr__(self) -> str:
        class_name = self.__class__.__name__
        return (
            f"{class_name}(scheme={self.scheme!r} host={self.host!r} port={self.port})"
        )

class QueryParams(typing.Mapping[str, str]):
    def __init__(self, *args: QueryParamTypes, **kwargs: typing.Any) -> None:
        assert len(args) < 2, "Too many arguments."
        assert not (args and kwargs), "Cannot mix named and unnamed arguments."
        value = args[0] if args else kwargs
        items: typing.Sequence[typing.Tuple[str, PrimitiveData]]
        if isinstance(value, str):
            items = parse_qsl(value)
        elif isinstance(value, QueryParams):
            items = value.multi_items()
        elif isinstance(value, list):
            items = value
        else:
            items = flatten_queryparams(value)
        self._list = [(str(k), str_query_param(v)) for k, v in items]
        self._dict = {str(k): str_query_param(v) for k, v in items}
    def getlist(self, key: typing.Any) -> typing.List[str]:
        return [item_value for item_key, item_value in self._list if item_key == key]
    def keys(self) -> typing.KeysView:
        return self._dict.keys()
    def values(self) -> typing.ValuesView:
        return self._dict.values()
    def items(self) -> typing.ItemsView:
        return self._dict.items()
    def multi_items(self) -> typing.List[typing.Tuple[str, str]]:
        return list(self._list)
    def get(self, key: typing.Any, default: typing.Any = None) -> typing.Any:
        if key in self._dict:
            return self._dict[key]
        return default
    def update(self, params: QueryParamTypes = None) -> None:  
        if not params:
            return
        params = QueryParams(params)
        for param in params:
            item, *extras = params.getlist(param)
            self[param] = item
            if extras:
                self._list.extend((param, e) for e in extras)
                self._dict[param] = params[param]
    def __getitem__(self, key: typing.Any) -> str:
        return self._dict[key]
    def __setitem__(self, key: str, value: str) -> None:
        self._dict[key] = value
        found_indexes = []
        for idx, (item_key, _) in enumerate(self._list):
            if item_key == key:
                found_indexes.append(idx)
        for idx in reversed(found_indexes[1:]):
            del self._list[idx]
        if found_indexes:
            idx = found_indexes[0]
            self._list[idx] = (key, value)
        else:
            self._list.append((key, value))
    def __contains__(self, key: typing.Any) -> bool:
        return key in self._dict
    def __iter__(self) -> typing.Iterator[typing.Any]:
        return iter(self.keys())
    def __len__(self) -> int:
        return len(self._dict)
    def __eq__(self, other: typing.Any) -> bool:
        if not isinstance(other, self.__class__):
            return False
        return sorted(self._list) == sorted(other._list)
    def __str__(self) -> str:
        return urlencode(self._list)
    def __repr__(self) -> str:
        class_name = self.__class__.__name__
        query_string = str(self)
        return f"{class_name}({query_string!r})"

class Headers(typing.MutableMapping[str, str]):
    def __init__(self, headers: HeaderTypes = None, encoding: str = None) -> None:
        if headers is None:
            self._list = []  
        elif isinstance(headers, Headers):
            self._list = list(headers.raw)
        elif isinstance(headers, dict):
            self._list = [
                (normalize_header_key(k, encoding), normalize_header_value(v, encoding))
                for k, v in headers.items()
            ]
        else:
            self._list = [
                (normalize_header_key(k, encoding), normalize_header_value(v, encoding))
                for k, v in headers
            ]
        self._encoding = encoding
    @property
    def encoding(self) -> str:
        if self._encoding is None:
            for encoding in ["ascii", "utf-8"]:
                for key, value in self.raw:
                    try:
                        key.decode(encoding)
                        value.decode(encoding)
                    except UnicodeDecodeError:
                        break
                else:
                    self._encoding = encoding
                    break
            else:
                self._encoding = "iso-8859-1"
        return self._encoding
    @encoding.setter
    def encoding(self, value: str) -> None:
        self._encoding = value
    @property
    def raw(self) -> typing.List[typing.Tuple[bytes, bytes]]:
        return self._list
    def keys(self) -> typing.List[str]:  
        return [key.decode(self.encoding) for key, value in self._list]
    def values(self) -> typing.List[str]:  
        return [value.decode(self.encoding) for key, value in self._list]
    def items(self) -> typing.List[typing.Tuple[str, str]]:  
        return [
            (key.decode(self.encoding), value.decode(self.encoding))
            for key, value in self._list
        ]
    def get(self, key: str, default: typing.Any = None) -> typing.Any:
        try:
            return self[key]
        except KeyError:
            return default
    def getlist(self, key: str, split_commas: bool = False) -> typing.List[str]:
        get_header_key = key.lower().encode(self.encoding)
        values = [
            item_value.decode(self.encoding)
            for item_key, item_value in self._list
            if item_key == get_header_key
        ]
        if not split_commas:
            return values
        split_values = []
        for value in values:
            split_values.extend([item.strip() for item in value.split(",")])
        return split_values
    def update(self, headers: HeaderTypes = None) -> None:  
        headers = Headers(headers)
        for header in headers:
            self[header] = headers[header]
    def copy(self) -> "Headers":
        return Headers(self.items(), encoding=self.encoding)
    def __getitem__(self, key: str) -> str:
        normalized_key = key.lower().encode(self.encoding)
        items = []
        for header_key, header_value in self._list:
            if header_key == normalized_key:
                items.append(header_value.decode(self.encoding))
        if items:
            return ", ".join(items)
        raise KeyError(key)
    def __setitem__(self, key: str, value: str) -> None:
        set_key = key.lower().encode(self.encoding)
        set_value = value.encode(self.encoding)
        found_indexes = []
        for idx, (item_key, _) in enumerate(self._list):
            if item_key == set_key:
                found_indexes.append(idx)
        for idx in reversed(found_indexes[1:]):
            del self._list[idx]
        if found_indexes:
            idx = found_indexes[0]
            self._list[idx] = (set_key, set_value)
        else:
            self._list.append((set_key, set_value))
    def __delitem__(self, key: str) -> None:
        del_key = key.lower().encode(self.encoding)
        pop_indexes = []
        for idx, (item_key, _) in enumerate(self._list):
            if item_key == del_key:
                pop_indexes.append(idx)
        if not pop_indexes:
            raise KeyError(key)
        for idx in reversed(pop_indexes):
            del self._list[idx]
    def __contains__(self, key: typing.Any) -> bool:
        get_header_key = key.lower().encode(self.encoding)
        for header_key, _ in self._list:
            if header_key == get_header_key:
                return True
        return False
    def __iter__(self) -> typing.Iterator[typing.Any]:
        return iter(self.keys())
    def __len__(self) -> int:
        return len(self._list)
    def __eq__(self, other: typing.Any) -> bool:
        if not isinstance(other, Headers):
            return False
        return sorted(self._list) == sorted(other._list)
    def __repr__(self) -> str:
        class_name = self.__class__.__name__
        encoding_str = ""
        if self.encoding != "ascii":
            encoding_str = f", encoding={self.encoding!r}"
        as_list = list(obfuscate_sensitive_headers(self.items()))
        as_dict = dict(as_list)
        no_duplicate_keys = len(as_dict) == len(as_list)
        if no_duplicate_keys:
            return f"{class_name}({as_dict!r}{encoding_str})"
        return f"{class_name}({as_list!r}{encoding_str})"

class Request:
    def __init__(
        self,
        method: str,
        url: typing.Union[str, URL],
        *,
        params: QueryParamTypes = None,
        headers: HeaderTypes = None,
        cookies: CookieTypes = None,
        data: RequestData = None,
        files: RequestFiles = None,
        json: typing.Any = None,
    ):
        self.method = method.upper()
        self.url = URL(url, params=params)
        self.headers = Headers(headers)
        if cookies:
            self._cookies = Cookies(cookies)
            self._cookies.set_cookie_header(self)
        self.content = encode(data, files, json)
        self.prepare()
    def prepare(self) -> None:
        for key, value in self.content.get_headers().items():
            self.headers.setdefault(key, value)
        auto_headers: typing.List[typing.Tuple[bytes, bytes]] = []
        has_host = "host" in self.headers
        has_user_agent = "user-agent" in self.headers
        has_accept = "accept" in self.headers
        has_accept_encoding = "accept-encoding" in self.headers
        has_connection = "connection" in self.headers
        if not has_host:
            url = self.url
            if url.userinfo:
                url = url.copy_with(username=None, password=None)
            auto_headers.append((b"host", url.authority.encode("ascii")))
        if not has_user_agent:
            auto_headers.append((b"user-agent", USER_AGENT.encode("ascii")))
        if not has_accept:
            auto_headers.append((b"accept", b"*/*"))
        if not has_accept_encoding:
            auto_headers.append((b"accept-encoding", ACCEPT_ENCODING.encode()))
        if not has_connection:
            auto_headers.append((b"connection", b"keep-alive"))
        for item in reversed(auto_headers):
            self.headers.raw.insert(0, item)
    @property
    def cookies(self) -> "Cookies":
        if not hasattr(self, "_cookies"):
            self._cookies = Cookies()
        return self._cookies
    def __repr__(self) -> str:
        class_name = self.__class__.__name__
        url = str(self.url)
        return f"<{class_name}({self.method!r}, {url!r})>"
    async def read(self) -> bytes:
        return await self.content.aread()
    async def stream(self) -> typing.AsyncIterator[bytes]:
        async for part in self.content:
            yield part

class Response:
    def __init__(
        self,
        status_code: int,
        *,
        http_version: str = None,
        headers: HeaderTypes = None,
        content: ResponseContent = None,
        on_close: typing.Callable = None,
        request: Request = None,
        history: typing.List["Response"] = None,
        elapsed: datetime.timedelta = None,
    ):
        self.status_code = status_code
        self.http_version = http_version
        self.headers = Headers(headers)
        self.request = request
        self.on_close = on_close
        self.elapsed = datetime.timedelta(0) if elapsed is None else elapsed
        self.call_next: typing.Optional[typing.Callable] = None
        self.history = [] if history is None else list(history)
        if content is None or isinstance(content, bytes):
            self.is_closed = True
            self.is_stream_consumed = True
            self._raw_content = content or b""
        else:
            self.is_closed = False
            self.is_stream_consumed = False
            self._raw_stream = content
    @property
    def reason_phrase(self) -> str:
        return StatusCode.get_reason_phrase(self.status_code)
    @property
    def url(self) -> typing.Optional[URL]:
        return None if self.request is None else self.request.url
    @property
    def content(self) -> bytes:
        if not hasattr(self, "_content"):
            if hasattr(self, "_raw_content"):
                raw_content = self._raw_content  
                content = self.decoder.decode(raw_content)
                content += self.decoder.flush()
                self._content = content
            else:
                raise ResponseNotRead()
        return self._content
    @property
    def text(self) -> str:
        if not hasattr(self, "_text"):
            content = self.content
            if not content:
                self._text = ""
            else:
                encoding = self.encoding
                self._text = content.decode(encoding, errors="replace")
        return self._text
    @property
    def encoding(self) -> str:
        if not hasattr(self, "_encoding"):
            encoding = self.charset_encoding
            if encoding is None or not is_known_encoding(encoding):
                encoding = self.apparent_encoding
                if encoding is None or not is_known_encoding(encoding):
                    encoding = "utf-8"
            self._encoding = encoding
        return self._encoding
    @encoding.setter
    def encoding(self, value: str) -> None:
        self._encoding = value
    @property
    def charset_encoding(self) -> typing.Optional[str]:
        content_type = self.headers.get("Content-Type")
        if content_type is None:
            return None
        parsed = cgi.parse_header(content_type)
        media_type, params = parsed[0], parsed[-1]
        if "charset" in params:
            return params["charset"].strip("'\"")
        if media_type.startswith("text/"):
            return "iso-8859-1"
        return None
    @property
    def apparent_encoding(self) -> typing.Optional[str]:
        return chardet.detect(self.content)["encoding"]
    @property
    def decoder(self) -> Decoder:
        if not hasattr(self, "_decoder"):
            decoders: typing.List[Decoder] = []
            values = self.headers.getlist("content-encoding", split_commas=True)
            for value in values:
                value = value.strip().lower()
                try:
                    decoder_cls = SUPPORTED_DECODERS[value]
                    decoders.append(decoder_cls())
                except KeyError:
                    continue
            if len(decoders) == 1:
                self._decoder = decoders[0]
            elif len(decoders) > 1:
                self._decoder = MultiDecoder(decoders)
            else:
                self._decoder = IdentityDecoder()
        return self._decoder
    @property
    def is_error(self) -> bool:
        return StatusCode.is_error(self.status_code)
    @property
    def is_redirect(self) -> bool:
        return StatusCode.is_redirect(self.status_code) and "location" in self.headers
    def raise_for_status(self) -> None:
        message = (
            "{0.status_code} {error_type}: {0.reason_phrase} for url: {0.url}\n"
            "For more information check: https://httpstatuses.com/{0.status_code}"
        )
        if StatusCode.is_client_error(self.status_code):
            message = message.format(self, error_type="Client Error")
            raise HTTPError(message, response=self)
        elif StatusCode.is_server_error(self.status_code):
            message = message.format(self, error_type="Server Error")
            raise HTTPError(message, response=self)
    def json(self, **kwargs: typing.Any) -> typing.Union[dict, list]:
        if self.charset_encoding is None and self.content and len(self.content) > 3:
            encoding = guess_json_utf(self.content)
            if encoding is not None:
                try:
                    return jsonlib.loads(self.content.decode(encoding), **kwargs)
                except UnicodeDecodeError:
                    pass
        return jsonlib.loads(self.text, **kwargs)
    @property
    def cookies(self) -> "Cookies":
        if not hasattr(self, "_cookies"):
            assert self.request is not None
            self._cookies = Cookies()
            self._cookies.extract_cookies(self)
        return self._cookies
    @property
    def links(self) -> typing.Dict[typing.Optional[str], typing.Dict[str, str]]:
        header = self.headers.get("link")
        ldict = {}
        if header:
            links = parse_header_links(header)
            for link in links:
                key = link.get("rel") or link.get("url")
                ldict[key] = link
        return ldict
    def __repr__(self) -> str:
        return f"<Response [{self.status_code} {self.reason_phrase}]>"
    async def read(self) -> bytes:
        if not hasattr(self, "_content"):
            self._content = b"".join([part async for part in self.aiter_bytes()])
        return self._content
    @property
    def stream(self):  
        warnings.warn(
            "Response.stream() is due to be deprecated. "
            "Use Response.aiter_bytes() instead."
        )
        return self.aiter_bytes
    @property
    def raw(self):  
        warnings.warn(
            "Response.raw() is due to be deprecated. "
            "Use Response.aiter_raw() instead."
        )
        return self.aiter_raw
    async def aiter_bytes(self) -> typing.AsyncIterator[bytes]:
        if hasattr(self, "_content"):
            yield self._content
        else:
            async for chunk in self.aiter_raw():
                yield self.decoder.decode(chunk)
            yield self.decoder.flush()
    async def aiter_text(self) -> typing.AsyncIterator[str]:
        decoder = TextDecoder(encoding=self.charset_encoding)
        async for chunk in self.aiter_bytes():
            yield decoder.decode(chunk)
        yield decoder.flush()
    async def aiter_lines(self) -> typing.AsyncIterator[str]:
        decoder = LineDecoder()
        async for text in self.aiter_text():
            for line in decoder.decode(text):
                yield line
        for line in decoder.flush():
            yield line
    async def aiter_raw(self) -> typing.AsyncIterator[bytes]:
        if hasattr(self, "_raw_content"):
            yield self._raw_content
        else:
            if self.is_stream_consumed:
                raise StreamConsumed()
            if self.is_closed:
                raise ResponseClosed()
            self.is_stream_consumed = True
            async for part in self._raw_stream:
                yield part
            await self.close()
    async def next(self) -> "Response":
        if not self.is_redirect:
            raise NotRedirectResponse()
        assert self.call_next is not None
        return await self.call_next()
    async def close(self) -> None:
        if not self.is_closed:
            self.is_closed = True
            if self.on_close is not None:
                await self.on_close()

class Module(object):
    def __init__(
        self,
        name,
        dependencies,
        source_file_regexes,
        build_profile_flags=(),
        environ=None,
        sbt_test_goals=(),
        python_test_goals=(),
        excluded_python_implementations=(),
        test_tags=(),
        should_run_r_tests=False,
