class Font:
    def _set(self, kw):
        options = []
        for k, v in kw.items():
            options.append("-"+k)
            options.append(str(v))
        return tuple(options)
    def _get(self, args):
        options = []
        for k in args:
            options.append("-"+k)
        return tuple(options)
    def _mkdict(self, args):
        options = {}
        for i in range(0, len(args), 2):
            options[args[i][1:]] = args[i+1]
        return options
    def __init__(self, root=None, font=None, name=None, exists=False, **options):
        if not root:
            root = tkinter._default_root
        if font:
            font = root.tk.splitlist(root.tk.call("font", "actual", font))
        else:
            font = self._set(options)
        if not name:
            name = "font" + str(id(self))
        self.name = name
        if exists:
            self.delete_font = False
            if self.name not in root.tk.call("font", "names"):
                raise tkinter._tkinter.TclError(
                    "named font %s does not already exist" % (self.name,))
            if font:
                root.tk.call("font", "configure", self.name, *font)
        else:
            root.tk.call("font", "create", self.name, *font)
            self.delete_font = True
        self._root  = root
        self._split = root.tk.splitlist
        self._call  = root.tk.call
    def __str__(self):
        return self.name
    def __eq__(self, other):
        return isinstance(other, Font) and self.name == other.name
    def __getitem__(self, key):
        return self.cget(key)
    def __setitem__(self, key, value):
        self.configure(**{key: value})
    def __del__(self):
        try:
            if self.delete_font:
                self._call("font", "delete", self.name)
        except (KeyboardInterrupt, SystemExit):
            raise
        except Exception:
            pass
    def copy(self):
        "Return a distinct copy of the current font"
        return Font(self._root, **self.actual())
    def actual(self, option=None):
        "Return actual font attributes"
        if option:
            return self._call("font", "actual", self.name, "-"+option)
        else:
            return self._mkdict(
                self._split(self._call("font", "actual", self.name))
                )
    def cget(self, option):
        "Get font attribute"
        return self._call("font", "config", self.name, "-"+option)
    def config(self, **options):
        "Modify font attributes"
        if options:
            self._call("font", "config", self.name,
                  *self._set(options))
        else:
            return self._mkdict(
                self._split(self._call("font", "config", self.name))
                )
    configure = config
    def measure(self, text):
        "Return text width"
        return int(self._call("font", "measure", self.name, text))
    def metrics(self, *options):
        if options:
            return int(
                self._call("font", "metrics", self.name, self._get(options))
                )
        else:
            res = self._split(self._call("font", "metrics", self.name))
            options = {}
            for i in range(0, len(res), 2):
                options[res[i][1:]] = int(res[i+1])
            return options

