    def __repr__(self):
        if self.channel:
            return f'{{{super().__repr__()}, "message": "{self.message}", "channel": "{self.channel}", "ts": {self.ts}}}'
        else:
            return f'{{{super().__repr__()}, "message": "{self.message}", "ts": {self.ts}}}'

class TemplateReference(object):
    def __init__(self, context):
        self.__context = context
    def __getitem__(self, name):
        blocks = self.__context.blocks[name]
        return BlockReference(name, self.__context, blocks, 0)
    def __repr__(self):
        return '<%s %r>' % (
            self.__class__.__name__,
            self.__context.name
        )

class Context(object):
    __slots__ = ('parent', 'vars', 'environment', 'eval_ctx', 'exported_vars',
                 'name', 'blocks', '__weakref__')
    def __init__(self, environment, parent, name, blocks):
        self.parent = parent
        self.vars = {}
        self.environment = environment
        self.eval_ctx = EvalContext(self.environment, name)
        self.exported_vars = set()
        self.name = name
        self.blocks = dict((k, [v]) for k, v in iteritems(blocks))
    def super(self, name, current):
        try:
            blocks = self.blocks[name]
            index = blocks.index(current) + 1
            blocks[index]
        except LookupError:
            return self.environment.undefined('there is no parent block '
                                              'called %r.' % name,
                                              name='super')
        return BlockReference(name, self, blocks, index)
    def get(self, key, default=None):
        try:
            return self[key]
        except KeyError:
            return default
    def resolve(self, key):
        if key in self.vars:
            return self.vars[key]
        if key in self.parent:
            return self.parent[key]
        return self.environment.undefined(name=key)
    def get_exported(self):
        return dict((k, self.vars[k]) for k in self.exported_vars)
    def get_all(self):
        return dict(self.parent, **self.vars)
    @internalcode
    def call(__self, __obj, *args, **kwargs):
        if __debug__:
            __traceback_hide__ = True
        fn = __obj.__call__
        for fn_type in ('contextfunction',
                        'evalcontextfunction',
                        'environmentfunction'):
            if hasattr(fn, fn_type):
                __obj = fn
                break
        if isinstance(__obj, _context_function_types):
            if getattr(__obj, 'contextfunction', 0):
                args = (__self,) + args
            elif getattr(__obj, 'evalcontextfunction', 0):
                args = (__self.eval_ctx,) + args
            elif getattr(__obj, 'environmentfunction', 0):
                args = (__self.environment,) + args
        try:
            return __obj(*args, **kwargs)
        except StopIteration:
            return __self.environment.undefined('value was undefined because '
                                                'a callable raised a '
                                                'StopIteration exception')
    def derived(self, locals=None):
        context = new_context(self.environment, self.name, {},
                              self.parent, True, None, locals)
        context.vars.update(self.vars)
        context.eval_ctx = self.eval_ctx
        context.blocks.update((k, list(v)) for k, v in iteritems(self.blocks))
        return context
    def _all(meth):
        proxy = lambda self: getattr(self.get_all(), meth)()
        proxy.__doc__ = getattr(dict, meth).__doc__
        proxy.__name__ = meth
        return proxy
    keys = _all('keys')
    values = _all('values')
    items = _all('items')
    if PY2:
        iterkeys = _all('iterkeys')
        itervalues = _all('itervalues')
        iteritems = _all('iteritems')
    del _all
    def __contains__(self, name):
        return name in self.vars or name in self.parent
    def __getitem__(self, key):
        item = self.resolve(key)
        if isinstance(item, Undefined):
            raise KeyError(key)
        return item
    def __repr__(self):
        return '<%s %s of %r>' % (
            self.__class__.__name__,
            repr(self.get_all()),
            self.name
        )

class Macro(object):
    def __init__(self, environment, func, name, arguments, defaults,
                 catch_kwargs, catch_varargs, caller):
        self._environment = environment
        self._func = func
        self._argument_count = len(arguments)
        self.name = name
        self.arguments = arguments
        self.defaults = defaults
        self.catch_kwargs = catch_kwargs
        self.catch_varargs = catch_varargs
        self.caller = caller
    @internalcode
    def __call__(self, *args, **kwargs):
        arguments = list(args[:self._argument_count])
        off = len(arguments)
        if off != self._argument_count:
            for idx, name in enumerate(self.arguments[len(arguments):]):
                try:
                    value = kwargs.pop(name)
                except KeyError:
                    try:
                        value = self.defaults[idx - self._argument_count + off]
                    except IndexError:
                        value = self._environment.undefined(
                            'parameter %r was not provided' % name, name=name)
                arguments.append(value)
        if self.caller:
            caller = kwargs.pop('caller', None)
            if caller is None:
                caller = self._environment.undefined('No caller defined',
                                                     name='caller')
            arguments.append(caller)
        if self.catch_kwargs:
            arguments.append(kwargs)
        elif kwargs:
            raise TypeError('macro %r takes no keyword argument %r' %
                            (self.name, next(iter(kwargs))))
        if self.catch_varargs:
            arguments.append(args[self._argument_count:])
        elif len(args) > self._argument_count:
            raise TypeError('macro %r takes not more than %d argument(s)' %
                            (self.name, len(self.arguments)))
        return self._func(*arguments)
    def __repr__(self):
        return '<%s %s>' % (
            self.__class__.__name__,
            self.name is None and 'anonymous' or repr(self.name)
        )

class Undefined(object):
    __slots__ = ('_undefined_hint', '_undefined_obj', '_undefined_name',
                 '_undefined_exception')
    def __init__(self, hint=None, obj=missing, name=None, exc=UndefinedError):
        self._undefined_hint = hint
        self._undefined_obj = obj
        self._undefined_name = name
        self._undefined_exception = exc
    @internalcode
    def _fail_with_undefined_error(self, *args, **kwargs):
        if self._undefined_hint is None:
            if self._undefined_obj is missing:
                hint = '%r is undefined' % self._undefined_name
            elif not isinstance(self._undefined_name, string_types):
                hint = '%s has no element %r' % (
                    object_type_repr(self._undefined_obj),
                    self._undefined_name
                )
            else:
                hint = '%r has no attribute %r' % (
                    object_type_repr(self._undefined_obj),
                    self._undefined_name
                )
        else:
            hint = self._undefined_hint
        raise self._undefined_exception(hint)
    @internalcode
    def __getattr__(self, name):
        if name[:2] == '__':
            raise AttributeError(name)
        return self._fail_with_undefined_error()
    __add__ = __radd__ = __mul__ = __rmul__ = __div__ = __rdiv__ = \
    __truediv__ = __rtruediv__ = __floordiv__ = __rfloordiv__ = \
    __mod__ = __rmod__ = __pos__ = __neg__ = __call__ = \
    __getitem__ = __lt__ = __le__ = __gt__ = __ge__ = __int__ = \
    __float__ = __complex__ = __pow__ = __rpow__ = \
        _fail_with_undefined_error
    def __str__(self):
        return u''
    def __len__(self):
        return 0
    def __iter__(self):
        if 0:
            yield None
    def __nonzero__(self):
        return False
    def __repr__(self):
        return 'Undefined'

class _Screen(object):
    def on(self):
        return devive_self.wakeup()
    def off(self):
        return devive_self.sleep()
    def __call__(self, action):
        if action == "on":
            return self.on()
        elif action == "off":
            return self.off()
        else:
            raise AttributeError("Invalid parameter: %s" % action)
    def __eq__(self, value):
        info = devive_self.info
        if "screenOn" not in info:
            raise EnvironmentError("Not supported on Android 4.3 and belows.")
        if value in ["on", "On", "ON"]:
            return info["screenOn"]
        elif value in ["off", "Off", "OFF"]:
            return not info["screenOn"]
        raise ValueError("Invalid parameter. It can only be compared with on/off.")
    def __ne__(self, value):
        return not self.__eq__(value)

class RawDataLoader(DataLoader):
    def __repr__(self):
        return "RawDataLoader (grain_length : %d)"%self.grain_length
    def __init__(self, *args, grain_length=grain_length, grain_hop=grain_hop, sequence_length=sequence_length, resampleFactor=resample, window=False, **func_args):
        super(RawDataLoader, self).__init__(*args, **func_args)
        self.grain_length= grain_length
        self.grain_hop = grain_hop or int(grain_length / 2)
        self.resampleFactor = resampleFactor
        self.sequence_length = sequence_length or 0
        self.window = window
    def __iter__(self):
        logger('start loading')
        for x, y in self.dataloader:
            logger('loaded')
            if self.resampleFactor:
                x = np.take(x, range(0, x.shape[-1], self.resampleFactor), axis=-1)
            if self.grain_length is not None:
                if self.sequence_length == 0:
                    assert self.grain_length < x.shape[-1], "grain length is greater than length of chunks"
                    random_pos = random.randrange(x.shape[-1] - self.grain_length)
                    x = np.take(x, range(random_pos, random_pos+self.grain_length), axis=-1)
                else:
                    full_length =  (self.sequence_length-1)*self.grain_hop  + self.grain_length
                    assert full_length < x.shape[1], \
                        "sequence length is greater than length of chunks (asked %d, is %d)"%(full_length, x.shape[1])
                    logger('start slicing')
                    max_idx = np.max(np.where((x==0).sum(0) == 0)[0])
                    random_pos = np.random.randint(0, max_idx - full_length, x.shape[0])
                    random_pos = np.stack([np.arange(r, r + full_length) for r in random_pos])
                    mask = np.zeros_like(x)
                    for i in range(x.shape[0]):
                        mask[i, random_pos[i]] = 1
                    logger('masked selecet')
                    full_shape = x.shape
                    x = torch.masked_select(x, torch.ByteTensor(mask, device=x.device))
                    x = torch.cat([np.take(x, range(i*self.grain_hop,(i*self.grain_hop+self.grain_length)), -1).unsqueeze(1) for i in range(self.sequence_length)], dim=1)
                    logger('splitted')
            if add_channel:
                if self.sequence_length <= 0:
                    x = x.unsqueeze(1)
                else:
                    x = x.unsqueeze(2)
            yield x.float(), y

