class Player(Piece):
    def __init__(self, player_id, role, name, nr, team, extra_skills=[], extra_ma=0, extra_st=0, extra_ag=0, extra_av=0,
                 niggling=0, mng=False, spp=0, position=None):
        super().__init__(position)
        self.player_id = player_id
        self.role = role
        self.name = name
        self.nr = nr
        self.team = team
        self.extra_skills = extra_skills
        self.skills = self.extra_skills + self.role.skills
        self.extra_ma = extra_ma
        self.extra_st = extra_st
        self.extra_ag = extra_ag
        self.extra_av = extra_av
        self.niggling = niggling
        self.mng = mng
        self.spp = spp
        self.state = PlayerState()
    def get_ag(self):
        return self.role.ag + self.extra_ag
    def get_st(self):
        return self.role.st + self.extra_st
    def get_ma(self):
        return self.role.ma + self.extra_ma
    def get_av(self):
        return self.role.av + self.extra_av
    def has_skill(self, skill):
        return skill in self.skills
    def get_skills(self):
        return self.skills
    def has_tackle_zone(self):
        if self.has_skill(Skill.TITCHY):
            return False
        if self.state.up and not self.state.bone_headed and not self.state.hypnotized and not self.state.really_stupid:
            return True
        return False
    def can_catch(self):
        return self.state.up and not self.state.bone_headed and not self.state.hypnotized and \
               not self.state.really_stupid and Skill.NO_HANDS not in self.get_skills()
    def can_assist(self):
        return self.state.up and not self.state.bone_headed and not self.state.hypnotized and not self.state.really_stupid
    def to_json(self):
        skills = []
        for skill in self.get_skills():
            skills.append(skill.name)
        return {
            'player_id': self.player_id,
            'name': self.name,
            'role': self.role.name,
            'team_id': self.team.team_id,
            'nr': self.nr,
            'skills': [skill.name for skill in self.skills],
            'ma': self.get_ma(),
            'st': self.get_st(),
            'ag': self.get_ag(),
            'av': self.get_av(),
            'niggling': self.niggling,
            'mng': self.mng,
            'spp': self.spp,
            'state': self.state.to_json(),
            'position': self.position.to_json() if self.position is not None else None
        }
    def move_allowed(self, include_gfi: bool = True):
        if self.state.used or self.state.stunned:
            moves = 0
        else:
            moves = self.get_ma()
            if not self.state.up and not self.has_skill(Skill.JUMP_UP):
                moves = max(0, moves - 3)
            moves = moves - self.state.moves
            if include_gfi:
                if self.has_skill(Skill.SPRINT):
                    moves = moves + 3
                else:
                    moves = moves + 2
        return moves
    def __eq__(self, other):
        return isinstance(other, Player) and other.player_id == self.player_id
    def __hash__(self):
        return self.player_id.__hash__()

class Square:
    def __init__(self, x, y):
        self.x = x
        self.y = y
    def to_json(self):
        return {
            'x': self.x,
            'y': self.y
        }
    def __eq__(self, other):
        if other is None or self is None:
            return False
        return self.x == other.x and self.y == other.y
    def __hash__(self):
        return self.x * 7 + self.y * 13
    def distance(self, other, manhattan=False, flight=False):
        if manhattan:
            return abs(other.x - self.x) + abs(other.y - self.y)
        elif flight:
            return sqrt((other.x - self.x)**2 + (other.y - self.y)**2)
        else:
            return max(abs(other.x - self.x), abs(other.y - self.y))
    def is_adjacent(self, other, manhattan=False):
        return self.distance(other, manhattan) == 1

class ErdosState(gym.Space):
    def __init__(self, K, potential, weights, unif_prob, geo_prob, diverse_prob,
                 state_unif_prob, high_one_prob, geo_high, 
                 unif_high, geo_ps, train_attacker, cattacker):
        assert K <= 40, "K is too large! Computing 2^-K may be very slow and inaccurate"
        self.K = K
        self.potential = potential
        self.weights = weights
        self.geo_prob = geo_prob
        self.unif_prob = unif_prob
        self.diverse_prob = diverse_prob
        self.state_unif_prob = state_unif_prob
        self.high_one_prob = high_one_prob
        self.geo_high = geo_high
        self.unif_high = unif_high
        self.geo_ps = geo_ps
        self.train_attacker = train_attacker
        self.cattacker = cattacker
        self.states_table = None
        self.all_states_table = None
        self.dtype = int
    def potential_fn(self, state):
        return np.sum(state*self.weights)
    def sample(self):
        samplers = ["unif", "geo", "diverse", "state_unif"]
        sample_idx = np.random.multinomial(1, [self.unif_prob, self.geo_prob, self.diverse_prob, self.state_unif_prob])
        idx = np.argmax(sample_idx)
        sampler = samplers[idx]
        if sampler == "unif":
            return self.unif_sampler()
        if sampler == "geo":
            return self.geo_sampler()
        if sampler == "diverse":
            return self.diverse_sampler()        
        if sampler == "unif_state":
            return self.state_unif_sampler()
    def get_high_one(self, state):
        non_zero_idxs = [-2, -3, -4]
        idx_idxs = np.random.randint(low=0, high=3, size=10)
        for idx_idx in idx_idxs:
            non_zero_idx = non_zero_idxs[idx_idx]
            if self.potential_fn(state) + self.weights[non_zero_idx] <= self.potential:
                state[non_zero_idx] += 1
                break
        return state    
    def unif_sampler(self):
        state = np.zeros(self.K+1, dtype=int)
        high_one = np.random.binomial(1, self.high_one_prob)
        if high_one:
            state = self.get_high_one(state)
        if (self.potential -  self.potential_fn(state)) <= 0:
            return state
        pot_state = self.potential_fn(state)
        for i in range(max(10, int(1/(100000*self.weights[0])))):
            levels = np.random.randint(low=0, high=self.unif_high, size=int(np.min([100000, 1.0/self.weights[0]])))
            for l in levels:
                if pot_state + self.weights[l] <= self.potential:
                    state[l] += 1
                    pot_state += self.weights[l]
                if pot_state >= self.potential - max(1e-8, self.weights[0]):
                    break
            if pot_state >= self.potential - max(1e-8, self.weights[0]):
                break
        return state
    def geo_sampler(self):
        state = np.zeros(self.K+1, dtype=int)
        high_one = np.random.binomial(1, self.high_one_prob)
        if high_one:
            state = self.get_high_one(state)
        ps = self.geo_ps
        p_idx = np.random.randint(low=0, high=len(ps))
        p = ps[p_idx]
        for i in range(max(1000, int(1/(100000*self.weights[0])))):
            assert self.K+1 < 30, "K too high, cannot use geo sampler"
            levels = np.random.geometric(p, int(1.0/self.weights[0])) - 1
            idxs = np.where(levels < self.geo_high)
            levels = levels[idxs]
            tmp = np.bincount(levels)
            counts = np.zeros(self.K + 1)
            counts[:len(tmp)] = tmp
            for l in range(self.K + 1):
                max_pieces = (self.potential - self.potential_fn(state))/self.weights[l]
                max_pieces = int(np.min([counts[l], max_pieces]))
                state[l] += max_pieces
                if self.potential_fn(state) >= self.potential - max(1e-8, self.weights[0]):
                    break
            if self.potential_fn(state) >= self.potential - max(1e-8, self.weights[0]):
                break
        return state
    def simplex_sampler(self, n):
        if n == 1:
            return np.array([self.potential])
        values = [np.random.uniform() for i in range(n-1)]
        values.extend([0,1])
        values.sort()
        values_arr = np.array(values)
        xs = values_arr[1:] - values_arr[:-1]
        xs = self.potential*np.sort(xs)
        xs = xs[::-1]
        return xs        
    def diverse_sampler(self):
        num_idxs = np.random.randint(low=1, high=self.K-1)
        idxs = []
        all_states =[ i for i in  range(self.K - 1)] 
        for i in range(num_idxs):
            rand_id = np.random.randint(low=0, high=len(all_states))
            idxs.append(all_states.pop(rand_id))
        idxs.sort()
        idxs.reverse()
        xs = self.simplex_sampler(num_idxs)
        remainder = 0
        state = np.zeros(self.K+1, dtype=int)
        for i in range(num_idxs):
            idx = idxs[i]
            pot_idx = xs[i] + remainder
            num_pieces = int(pot_idx/self.weights[idx])
            state[idx] += num_pieces
            remainder = pot_idx - num_pieces*self.weights[idx]
        return state
    def state_unif_sampler(self):
        assert self.states_table != None, "states_table attribute is not set, call enumerate_states_potential"
        high = len(self.states_table)
        idx = np.random.randint(low=0, high=high)
        state = np.array(self.states_table[idx]).astype("int")
        return state
    def enumerate_states_core(self, K, potential, N, weights):
        if K == 2:
            result = []
            max_N = np.floor(N*(weights[0]/weights[K-1])).astype("int") + 1
            for i in range(max_N):
                result.append([N - 2*i, i])
        else:
            result = []
            scaling = (weights[0]/weights[K-1])
            max_N = np.floor(N*scaling).astype("int") + 1
            for i in range(max_N):
                recursed_results = self.enumerate_states_core(K-1, potential-i*weights[K-1], int(N - i/scaling), weights[:-1])
                for state in recursed_results:
                    state.append(i)
                result.extend(recursed_results)
        return result
    def enumerate_states_potential(self):
        assert self.K <= 10, "K is too large for enumerating all states!"
        N = int(self.potential*np.power(2.0, self.K))
        raw_states = self.enumerate_states_core(self.K, self.potential, N, self.weights)
        for state in raw_states:
            state.append(0)
        self.states_table = raw_states
    def enumerate_states_all(self, upperbound=1.0):
        assert self.K < 10, "K is too large for enumerating all states"
        all_states = []
        for n in range(int(upperbound/self.weights[0])+1):
            N=n
            potential = float(n)*self.weights[0]
            raw_states = self.enumerate_states_core(self.K, potential, N, self.weights)
            for state in raw_states:
                state.append(0)
            all_states.extend(raw_states)
        self.all_states_table = all_states        
    def contains(self, action):
        pass   
    @property
    def shape(self):
        if self.train_attacker:
            return (self.K+1,)
        else:
            return (2*self.K + 2,)
    def __repr__(self):
        return "ErdosGame" + str(self.shape)

class SampleBatch:
    CUR_OBS = "obs"
    NEXT_OBS = "new_obs"
    ACTIONS = "actions"
    REWARDS = "rewards"
    PREV_ACTIONS = "prev_actions"
    PREV_REWARDS = "prev_rewards"
    DONES = "dones"
    INFOS = "infos"
    ACTION_DIST_INPUTS = "action_dist_inputs"
    ACTION_PROB = "action_prob"
    ACTION_LOGP = "action_logp"
    EPS_ID = "eps_id"
    UNROLL_ID = "unroll_id"
    AGENT_INDEX = "agent_index"
    VF_PREDS = "vf_preds"
    @PublicAPI
    def __init__(self, *args, **kwargs):
        self._initial_inputs = kwargs.pop("_initial_inputs", {})
        self.data = dict(*args, **kwargs)
        lengths = []
        for k, v in self.data.copy().items():
            assert isinstance(k, str), self
            lengths.append(len(v))
            self.data[k] = np.array(v, copy=False)
        if not lengths:
            raise ValueError("Empty sample batch")
        assert len(set(lengths)) == 1, ("data columns must be same length",
                                        self.data, lengths)
        self.count = lengths[0]
    @staticmethod
    @PublicAPI
    def concat_samples(samples: List[Dict[str, TensorType]]) -> \
            Union["SampleBatch", "MultiAgentBatch"]:
        if isinstance(samples[0], MultiAgentBatch):
            return MultiAgentBatch.concat_samples(samples)
        out = {}
        samples = [s for s in samples if s.count > 0]
        for k in samples[0].keys():
            out[k] = concat_aligned([s[k] for s in samples])
        return SampleBatch(out)
    @PublicAPI
    def concat(self, other: "SampleBatch") -> "SampleBatch":
        if self.keys() != other.keys():
            raise ValueError(
                "SampleBatches to concat must have same columns! {} vs {}".
                format(list(self.keys()), list(other.keys())))
        out = {}
        for k in self.keys():
            out[k] = concat_aligned([self[k], other[k]])
        return SampleBatch(out)
    @PublicAPI
    def copy(self) -> "SampleBatch":
        return SampleBatch(
            {k: np.array(v, copy=True)
             for (k, v) in self.data.items()})
    @PublicAPI
    def rows(self) -> Dict[str, TensorType]:
        for i in range(self.count):
            row = {}
            for k in self.keys():
                row[k] = self[k][i]
            yield row
    @PublicAPI
    def columns(self, keys: List[str]) -> List[any]:
        out = []
        for k in keys:
            out.append(self[k])
        return out
    @PublicAPI
    def shuffle(self) -> None:
        permutation = np.random.permutation(self.count)
        for key, val in self.items():
            self[key] = val[permutation]
    @PublicAPI
    def split_by_episode(self) -> List["SampleBatch"]:
        slices = []
        cur_eps_id = self.data["eps_id"][0]
        offset = 0
        for i in range(self.count):
            next_eps_id = self.data["eps_id"][i]
            if next_eps_id != cur_eps_id:
                slices.append(self.slice(offset, i))
                offset = i
                cur_eps_id = next_eps_id
        slices.append(self.slice(offset, self.count))
        for s in slices:
            slen = len(set(s["eps_id"]))
            assert slen == 1, (s, slen)
        assert sum(s.count for s in slices) == self.count, (slices, self.count)
        return slices
    @PublicAPI
    def slice(self, start: int, end: int) -> "SampleBatch":
        return SampleBatch({k: v[start:end] for k, v in self.data.items()})
    @PublicAPI
    def timeslices(self, k: int) -> List["SampleBatch"]:
        out = []
        i = 0
        while i < self.count:
            out.append(self.slice(i, i + k))
            i += k
        return out
    @PublicAPI
    def keys(self) -> Iterable[str]:
        return self.data.keys()
    @PublicAPI
    def items(self) -> Iterable[TensorType]:
        return self.data.items()
    @PublicAPI
    def get(self, key: str) -> Optional[TensorType]:
        return self.data.get(key)
    @PublicAPI
    def size_bytes(self) -> int:
        return sum(sys.getsizeof(d) for d in self.data)
    @PublicAPI
    def __getitem__(self, key: str) -> TensorType:
        return self.data[key]
    @PublicAPI
    def __setitem__(self, key, item) -> None:
        self.data[key] = item
    @DeveloperAPI
    def compress(
            self,
            bulk: bool = False,
            columns: Set[str] = frozenset(["obs", "new_obs"])) -> None:
        for key in columns:
            if key in self.data:
                if bulk:
                    self.data[key] = pack(self.data[key])
                else:
                    self.data[key] = np.array(
                        [pack(o) for o in self.data[key]])
    @DeveloperAPI
    def decompress_if_needed(
            self,
            columns: Set[str] = frozenset(
                ["obs", "new_obs"])) -> "SampleBatch":
        for key in columns:
            if key in self.data:
                arr = self.data[key]
                if is_compressed(arr):
                    self.data[key] = unpack(arr)
                elif len(arr) > 0 and is_compressed(arr[0]):
                    self.data[key] = np.array(
                        [unpack(o) for o in self.data[key]])
        return self
    def __str__(self):
        return "SampleBatch({})".format(str(self.data))
    def __repr__(self):
        return "SampleBatch({})".format(str(self.data))
    def __iter__(self):
        return self.data.__iter__()
    def __contains__(self, x):
        return x in self.data

class MultiAgentBatch:
    @PublicAPI
    def __init__(self,
                 policy_batches: Dict[PolicyID, SampleBatch],
                 env_steps: int):
        for v in policy_batches.values():
            assert isinstance(v, SampleBatch)
        self.policy_batches = policy_batches
        self.count = env_steps
    @PublicAPI
    def env_steps(self) -> int:
        return self.count
    @PublicAPI
    def agent_steps(self) -> int:
        ct = 0
        for batch in self.policy_batches.values():
            ct += batch.count
        return ct
    @PublicAPI
    def timeslices(self, k: int) -> List["MultiAgentBatch"]:
        from ray.rllib.evaluation.sample_batch_builder import \
            SampleBatchBuilder
        steps = []
        for policy_id, batch in self.policy_batches.items():
            for row in batch.rows():
                steps.append((row[SampleBatch.EPS_ID], row["t"],
                              row["agent_index"], policy_id, row))
        steps.sort()
        finished_slices = []
        cur_slice = collections.defaultdict(SampleBatchBuilder)
        cur_slice_size = 0
        def finish_slice():
            nonlocal cur_slice_size
            assert cur_slice_size > 0
            batch = MultiAgentBatch(
                {k: v.build_and_reset()
                 for k, v in cur_slice.items()}, cur_slice_size)
            cur_slice_size = 0
            finished_slices.append(batch)
        for _, group in itertools.groupby(steps, lambda x: x[:2]):
            for _, _, _, policy_id, row in group:
                cur_slice[policy_id].add_values(**row)
            cur_slice_size += 1
            if cur_slice_size >= k:
                finish_slice()
                assert cur_slice_size == 0
        if cur_slice_size > 0:
            finish_slice()
        assert len(finished_slices) > 0, finished_slices
        return finished_slices
    @staticmethod
    @PublicAPI
    def wrap_as_needed(
            policy_batches: Dict[PolicyID, SampleBatch],
            env_steps: int) -> Union[SampleBatch, "MultiAgentBatch"]:
        if len(policy_batches) == 1 and DEFAULT_POLICY_ID in policy_batches:
            return policy_batches[DEFAULT_POLICY_ID]
        return MultiAgentBatch(policy_batches, env_steps)
    @staticmethod
    @PublicAPI
    def concat_samples(samples: List["MultiAgentBatch"]) -> "MultiAgentBatch":
        policy_batches = collections.defaultdict(list)
        env_steps = 0
        for s in samples:
            if not isinstance(s, MultiAgentBatch):
                raise ValueError(
                    "`MultiAgentBatch.concat_samples()` can only concat "
                    "MultiAgentBatch types, not {}!".format(type(s).__name__))
            for key, batch in s.policy_batches.items():
                policy_batches[key].append(batch)
            env_steps += s.env_steps()
        out = {}
        for key, batches in policy_batches.items():
            out[key] = SampleBatch.concat_samples(batches)
        return MultiAgentBatch(out, env_steps)
    @PublicAPI
    def copy(self) -> "MultiAgentBatch":
        return MultiAgentBatch(
            {k: v.copy()
             for (k, v) in self.policy_batches.items()}, self.count)
    @PublicAPI
    def size_bytes(self) -> int:
        return sum(b.size_bytes() for b in self.policy_batches.values())
    @DeveloperAPI
    def compress(
            self,
            bulk: bool = False,
            columns: Set[str] = frozenset(
                ["obs", "new_obs"])) -> None:
        for batch in self.policy_batches.values():
            batch.compress(bulk=bulk, columns=columns)
    @DeveloperAPI
    def decompress_if_needed(
            self,
            columns: Set[str] = frozenset(
                ["obs", "new_obs"])) -> "MultiAgentBatch":
        for batch in self.policy_batches.values():
            batch.decompress_if_needed(columns)
        return self
    def __str__(self):
        return "MultiAgentBatch({}, env_steps={})".format(
            str(self.policy_batches), self.count)
    def __repr__(self):
        return "MultiAgentBatch({}, env_steps={})".format(
            str(self.policy_batches), self.count)
    def total(self):
        deprecation_warning("batch.total()", "batch.agent_steps()")
        return self.agent_steps()

