    def from_diameter(cls, diameter):
        return cls(diameter / 2)
    def __init__(self, radius):
        self._radius = radius
    def __repr__(self):
        return f'{self.__class__.__name__}({self.radius})'
    def __eq__(self, other):
        return self.radius == other.radius
    def __lt__(self, other):
        return self.radius < other.radius
    def __add__(self, other):
        try:
            return Circle(self.radius + other.radius)
        except AttributeError:
            return Circle(self.radius + other)
    def __sub__(self, other):
        try:
            return Circle(self.radius - other.radius)
        except AttributeError:
            return Circle(self.radius - other)
    def __mul__(self, other):
        try:
            return Circle(self.radius * other.radius)
        except AttributeError:
            return Circle(self.radius * other)
    def __truediv__(self, other):
        try:
            return Circle(self.radius / other.radius)
        except AttributeError:
            return Circle(self.radius / other)
    def __radd__(self, other):
        try:
            return Circle(self.radius + other.radius)
        except AttributeError:
            return Circle(self.radius + other)
    def __rsub__(self, other):
        try:
            return Circle(self.radius - other.radius)
        except AttributeError:
            return Circle(self.radius - other)
    def __rmul__(self, other):
        try:
            return Circle(self.radius * other.radius)
        except AttributeError:
            return Circle(self.radius * other)
    def __rtruediv__(self, other):
        try:
            return Circle(self.radius / other.radius)
        except AttributeError:
            return Circle(self.radius / other)
    def __iadd__(self, other):
        try:
            return Circle(self.radius + other.radius)
        except AttributeError:
            return Circle(self.radius + other)
    def __isub__(self, other):
        try:
            return Circle(self.radius - other.radius)
        except AttributeError:
            return Circle(self.radius - other)
    def __imul__(self, other):
        try:
            return Circle(self.radius * other.radius)
        except AttributeError:
            return Circle(self.radius * other)
    @property
    def radius(self):
        return self._radius
    @radius.setter
    def radius(self, val):
        if val > 0:
            self._radius = val
        else:
            raise ValueError("radius must be > 0")
    @property
    def diameter(self):
        return self.radius * 2
    @diameter.setter
    def diameter(self, val):
        self.radius = val / 2
    @property
    def area(self):
        return self.radius ** 2 * pi
    def sort_key(self):
        return self.radius

class Schema(object):
  @classmethod
  def combined_errors(self, *args):
    errors = []
    for schema in args:
      errors.extend(schema._errors.items())
    return dict(errors)
  def __init__(self, **kwargs):
    self._fields = self._get_fields()
    self._errors = {}
    for name, field in self._fields.items():
      if name in kwargs:
        field.set(kwargs.pop(name))
      else:
        field.reset()
  def get_namespace(self):
    if hasattr(self, '__namespace__'):
      return self.__namespace__
    return self.__class__.__name__.replace('Schema', '')
  def __call__(self, data=None):
    if data is None:
      data = {}
    errors = {}
    def add_errors(name, errs):
      if errs:
        field_errors = errors.get(name, [])
        field_errors += errs
        errors[name] = field_errors
    for name, value in data.items():
      if name not in self._fields:
        continue
      try:
        errs = self._fields[name].set(value)
      except ValueError as err:
        errs = [err.message]
      add_errors(name, errs)
    for name, field in self._fields.items():
      if not field.serialize:
        continue
      field.default()
    for name, field in self._fields.items():
      if not field.serialize:
        continue
      errs = field.validate()
      add_errors(name, errs)
      validator = 'validate_%s' % name
      if hasattr(self, validator):
        try:
          getattr(self, validator)(field.get())
        except ValueError as v:
          add_errors(name, v.args)
    self._errors = errors
    return not bool(errors)
  def __repr__(self):
    return str(self._get())
  def _get(self):
    rep = {}
    for name, field in self._fields.items():
      if field.serialize:
        name = getattr(field, 'name', name)
        rep[name] = field.get_simplified()
    rep['__namespace__'] = self.get_namespace()
    return rep
  def dict(self):
    return self._get()
  def _get_fields(self):
    fields = {}
    for field_name in dir(self):
      if not field_name.startswith('_'):
        field = getattr(self, field_name)
        if not hasattr(field, '__call__'):
          fields[field_name] = field
    return fields

