class _BVType(PySMTType):
    def __init__(self, width=32):
        PySMTType.__init__(self, type_id = 3)
        self._width = width
    @property
    def width(self):
        return self._width
    def is_bv_type(self, width=None):
        if width:
            return self.width == width
        return True
    def as_smtlib(self, funstyle=True):
        if funstyle:
            return "() (_ BitVec %d)" % self.width
        else:
            return "(_ BitVec %d)" % self.width
