        return "BV{%d}" % self.width
    def __eq__(self, other):
        if other is None:
            return False
        if self.type_id != other.type_id:
            return False
        if self.width != other.width:
            return False
        return True
    def __ne__(self, other):
        return not self.__eq__(other)
    def __hash__(self):
        return hash(self.type_id + self.width)

class _ArrayType(PySMTType):
    def __init__(self, index_type, elem_type):
        PySMTType.__init__(self, type_id = 5)
        self._index_type = index_type
        self._elem_type = elem_type
        self._hash = hash(index_type) + hash(elem_type)
        return
    @property
    def elem_type(self):
        return self._elem_type
    @property
    def index_type(self):
        return self._index_type
    def as_smtlib(self, funstyle=True):
        itype = self.index_type.as_smtlib(False)
        etype = self.elem_type.as_smtlib(False)
        if funstyle:
            return "() (Array %s %s)" % (itype, etype)
        else:
            return "(Array %s %s)" % (itype, etype)
    def __str__(self):
        return "Array{%s, %s}" % (self.index_type, self.elem_type)
    def is_array_type(self):
        return True
    def __eq__(self, other):
        if other is None:
            return False
        if self.type_id != other.type_id:
            return False
        if id(self) == id(other):
            return True
        if self.index_type != other.index_type:
            return False
        return self.elem_type == other.elem_type
    def __ne__(self, other):
        return not self.__eq__(other)
    def __hash__(self):
        return self._hash

class Script:
    def __init__(self, data: bytes):
        self.data = data[:]
    def address(self, network=NETWORKS["main"]) -> str:
        script_type = self.script_type()
        data = self.data
        if script_type is None:
            raise ValueError("This type of script doesn't have address representation")
        if script_type == "p2pkh":
            d = network["p2pkh"] + data[3:23]
            return base58.encode_check(d)
        if script_type == "p2sh":
            d = network["p2sh"] + data[2:22]
            return base58.encode_check(d)
        if script_type == "p2wpkh" or script_type == "p2wsh":
            return bech32.encode(network["bech32"], data[0], data[2:])
        raise ValueError("Unsupported script type")
    def script_type(self):
        data = self.data
        if len(data) == 25 and data[:3] == b"\x76\xa9\x14" and data[-2:] == b"\x88\xac":
            return "p2pkh"
        if len(data) == 23 and data[:2] == b"\xa9\x14" and data[-1] == 0x87:
            return "p2sh"
        if len(data) == 22 and data[:2] == b"\x00\x14":
            return "p2wpkh"
        if len(data) == 34 and data[:2] == b"\x00\x20":
            return "p2wsh"
        return None
    def serialize(self) -> bytes:
        return compact.to_bytes(len(self.data)) + self.data
    @classmethod
    def parse(cls, b: bytes) -> cls:
        stream = io.BytesIO(b)
        script = cls.read_from(stream)
        if len(stream.read(1)) > 0:
            raise ValueError("Too many bytes")
        return script
    @classmethod
    def read_from(cls, stream) -> cls:
        l = compact.read_from(stream)
        data = stream.read(l)
        if len(data) != l:
            raise ValueError("Cant read %d bytes" % l)
        return cls(data)
    def __eq__(self, other):
        return self.data == other.data
    def __ne__(self, other):
        return self.data != other.data

