class Page(object):
    def __init__(self, title, file, config):
        file.page = self
        self.file = file
        self.title = title
        self.parent = None
        self.children = None
        self.previous_page = None
        self.next_page = None
        self.active = False
        self.is_section = False
        self.is_page = True
        self.is_link = False
        if 'SOURCE_DATE_EPOCH' in os.environ:
            self.update_date = datetime.datetime.utcfromtimestamp(
                int(os.environ['SOURCE_DATE_EPOCH'])
            ).strftime("%Y-%m-%d")
        else:
            self.update_date = datetime.datetime.now().strftime("%Y-%m-%d")
        self._set_canonical_url(config.get('site_url', None))
        self._set_edit_url(config.get('repo_url', None), config.get('edit_uri', None))
        self.markdown = None
        self.content = None
        self.toc = []
        self.meta = {}
    def __eq__(self, other):
        def sub_dict(d):
            return dict((key, value) for key, value in d.items() if key in ['title', 'file'])
        return (isinstance(other, self.__class__) and sub_dict(self.__dict__) == sub_dict(other.__dict__))
    def __ne__(self, other):
        return not self.__eq__(other)
    def __repr__(self):
        title = "'{}'".format(self.title) if (self.title is not None) else '[blank]'
        return "Page(title={}, url='{}')".format(title, self.abs_url or self.file.url)
    def _indent_print(self, depth=0):
        return '{}{}'.format('    ' * depth, repr(self))
    def _get_active(self):
        return self.__active
    def _set_active(self, value):
        self.__active = bool(value)
        if self.parent is not None:
            self.parent.active = bool(value)
    active = property(_get_active, _set_active)
    @property
    def is_index(self):
        return self.file.name == 'index'
    @property
    def is_top_level(self):
        return self.parent is None
    @property
    def is_homepage(self):
        return self.is_top_level and self.is_index
    @property
    def url(self):
        return '' if self.file.url == '.' else self.file.url
    @property
    def ancestors(self):
        if self.parent is None:
            return []
        return [self.parent] + self.parent.ancestors
    def _set_canonical_url(self, base):
        if base:
            if not base.endswith('/'):
                base += '/'
            self.canonical_url = urljoin(base, self.url)
            self.abs_url = urlparse(self.canonical_url).path
        else:
            self.canonical_url = None
            self.abs_url = None
    def _set_edit_url(self, repo_url, edit_uri):
        if repo_url and edit_uri:
            src_path = self.file.src_path.replace('\\', '/')
            self.edit_url = urljoin(repo_url, edit_uri + src_path)
        else:
            self.edit_url = None
    def read_source(self, config):
        source = config['plugins'].run_event('page_read_source', None, config=config, page=self)
        if source is None:
            try:
                with io.open(self.file.abs_src_path, 'r', encoding='utf-8-sig', errors='strict') as f:
                    source = f.read()
            except IOError:
                log.error('File not found: {}'.format(self.file.src_path))
                raise
            except ValueError:
                log.error('Encoding error reading file: {}'.format(self.file.src_path))
                raise
        self.markdown, self.meta = meta.get_data(source)
        self._set_title()
    def _set_title(self):
        if self.title is not None:
            return
        if 'title' in self.meta:
            self.title = self.meta['title']
            return
        title = get_markdown_title(self.markdown)
        if title is None:
            if self.is_homepage:
                title = 'Home'
            else:
                title = self.file.name.replace('-', ' ').replace('_', ' ')
                if title.lower() == title:
                    title = title.capitalize()
        self.title = title
    def render(self, config, files):
        extensions = [
            _RelativePathExtension(self.file, files)
        ] + config['markdown_extensions']
        md = markdown.Markdown(
            extensions=extensions,
            extension_configs=config['mdx_configs'] or {}
        )
        self.content = md.convert(self.markdown)
        self.toc = get_toc(getattr(md, 'toc', ''))

class ComnodeObject(object):
    def __init__(self, fullkeyname, valuetype=Comnodestorage.DataTypes.Str, desc="", hidden=False):
        self.hidden = hidden
        if desc == "":
            desc = "no description"
        self.description = desc
        self.storage = Comnodestorage.ConfigDatabase()
        groupname, keyname = fullkeyname.lower().split(".")
        if valuetype in self.storage.supportedtypes:
            self.datamodel = Comnodestorage.DataModel(key=keyname, valuetype=valuetype, collectionname=groupname)
        else:
            print("Wrong type given on key %s - unknown type: %s" % (fullkeyname, valuetype))
            exit(-1)
    def GetDescription(self):
        return self.description
    def GetValueType(self):
        if self.datamodel is None:
            return None
        return self.datamodel.ValueType
    def Set(self, data):
        self.datamodel.Value = data
        self.storage.SetData(self.datamodel)
    def Get(self):
        self.datamodel.Value = None
        return self.storage.GetDataValue(self.datamodel)
    def Del(self):
        return self.storage.DelData(self.datamodel)
    def Name(self):
        return "%s.%s" % (self.datamodel.CollectionName, self.datamodel.Key)
    def GetMeta(self):
        self.datamodel.Value = None
        return self.storage.GetData(self.datamodel)
    def __repr__(self):
        return self.Get()
    def __str__(self):
        return "%s" % (self.Get())
    def IsEmpty(self, verbose=True):
        def Verbose():
            if verbose:
                Loggiz.L.notice("%s is empty" % self.Name())
        d = self.storage.GetData(self.datamodel, default=False)
        if d.Value is None:
            Verbose()
            return True
        elif (d.Value == list()) or (d.Value == dict()):
            Verbose()
            return True
        elif d.Value == "":
            Verbose()
            return True
        else:
            return False

