class YamlConfig(collections.MutableMapping):
    _defaults = dict()
    def __init__(self, yaml_path=None):
        self.yaml_path = yaml_path
        if self.yaml_path:
            self.load()
        else:
            self._conf = dict()
    def load(self):
        if os.path.exists(self.yaml_path):
            self._conf = yaml.safe_load(file(self.yaml_path))
        else:
            log.debug("%s not found", self.yaml_path)
            self._conf = dict()
    def update(self, in_dict):
        self._conf.update(in_dict)
    @classmethod
    def from_dict(cls, in_dict):
        conf_obj = cls()
        conf_obj._conf = in_dict
        return conf_obj
    def to_dict(self):
        return dict(self._conf)
    @classmethod
    def from_str(cls, in_str):
        conf_obj = cls()
        conf_obj._conf = yaml.safe_load(in_str)
        return conf_obj
    def to_str(self):
        return str(self)
    def get(self, key, default=None):
        return self._conf.get(key, default)
    def __str__(self):
        return yaml.safe_dump(self._conf, default_flow_style=False).strip()
    def __repr__(self):
        return self.__str__()
    def __getitem__(self, name):
        return self.__getattr__(name)
    def __getattr__(self, name):
        return self._conf.get(name, self._defaults.get(name))
    def __contains__(self, name):
        return self._conf.__contains__(name)
    def __setattr__(self, name, value):
        if name.endswith('_conf') or name in ('yaml_path'):
            object.__setattr__(self, name, value)
        else:
            self._conf[name] = value
    def __delattr__(self, name):
        del self._conf[name]
    def __len__(self):
        return self._conf.__len__()
    def __iter__(self):
        return self._conf.__iter__()
    def __setitem__(self, name, value):
        self._conf.__setitem__(name, value)
    def __delitem__(self, name):
        self._conf.__delitem__(name)

class FakeNamespace(YamlConfig):
    def __init__(self, config_dict=None):
        if not config_dict:
            config_dict = dict()
        self._conf = self._clean_config(config_dict)
        set_config_attr(self)
    def _clean_config(self, config_dict):
        result = dict()
        for key, value in config_dict.iteritems():
            new_key = key
            if new_key.startswith("--"):
                new_key = new_key[2:]
            elif new_key.startswith("<") and new_key.endswith(">"):
                new_key = new_key[1:-1]
            if "-" in new_key:
                new_key = new_key.replace("-", "_")
            result[new_key] = value
        return result
    def __getattr__(self, name):
        if name in self._conf:
            return self._conf[name]
        elif name in self._defaults:
            return self._defaults[name]
        raise AttributeError(name)
    def __setattr__(self, name, value):
        if name == 'teuthology_config':
            object.__setattr__(self, name, value)
        else:
            super(FakeNamespace, self).__setattr__(name, value)
    def __repr__(self):
        return repr(self._conf)
    def __str__(self):
        return str(self._conf)

class Board:
    __slots__ = ['_values', '_width', '_height', '_len', '_range', '_file_loaded']
    def __init__(self, source = '',  width = 0, height = 0, random = True, n_range = 1):
        self._values = []
        self._len = 0
        self._range = n_range
        self._file_loaded = False
        if source != '':
            file = self.load_from_file(source)
            self._width = len(file[0])
            self._height = len(file)
            self._file_loaded = True
            self.fill_values_from_file(file)
        else:
            self._width = width
            self._height = height
            if width > 0 and height > 0:
                if random:
                    self.fill_values_randomly(n_range)
                else:
                    self.fill_values(0)
    def fill_values(self, value = 0):
        if self.is_empty():
            for row in range(self._height):
                self.append([])
                for column in range(self._width):
                    self._values[row].append(value)
                    self._len += 1
        else:
            for row in range(self._height):
                for column in range(self._width):
                    self._values[row][column] = value
        assert not self.is_empty(), 'No elements were added'
        return self._values
    def fill_values_randomly(self, n_range):
        for row in range(self._height):
            self.append([])
            for column in range(self._width):
                rand_number = uniform(0, n_range)
                if rand_number > ONE_SPAWNING_PROBABILITY and rand_number < 1:
                    rand_number = 1
                elif rand_number >= TWO_SPAWNING_PROBABILITY:
                    rand_number = 2
                else:
                    rand_number = 0
                self._values[row].append(rand_number)
                self._len += 1
        assert not self.is_empty(), 'No elements were added'
        return self._values
    def fill_values_from_file(self, file):
        for row in range(self._height):
            self.append([])
            for column in range(self._width):
                self._values[row].append(int(file[row][column])) 
                self._len += 1
        assert not self.is_empty(), 'No elements were added'
        return self._values
    def load_from_file(self, file):
        f = open(file, 'r').read().split()
        return f
    def change_pos_value(self, row, column, value):
        self._values[row][column] = value
    def append(self, value):
        self._values.append(value)
    @property
    def width(self):
        return self._width
    @property
    def height(self):
        return self._height
    @property
    def values(self):
        return self._values
    @property
    def range(self):
        return self._range
    def loaded_from_file(self):
        return self._file_loaded == True
    def is_empty(self):
        return self._len == 0
    def clear(self):
        self._values.clear()
    def __len__(self):
        return self._len
    def __repr__(self):
        return ('[' + ', '.join(repr(x) for x in self._values) + ']')

