class JoinUnit:
    def __init__(self, block, shape, indexers=None):
        if indexers is None:
            indexers = {}
        self.block = block
        self.indexers = indexers
        self.shape = shape
    def __repr__(self) -> str:
        return f"{type(self).__name__}({repr(self.block)}, {self.indexers})"
    @cache_readonly
    def needs_filling(self):
        for indexer in self.indexers.values():
            if (indexer == -1).any():
                return True
        return False
    @cache_readonly
    def dtype(self):
        if self.block is None:
            raise AssertionError("Block is None, no dtype")
        if not self.needs_filling:
            return self.block.dtype
        else:
            return _get_dtype(maybe_promote(self.block.dtype, self.block.fill_value)[0])
    @cache_readonly
    def is_na(self):
        if self.block is None:
            return True
        if not self.block._can_hold_na:
            return False
        values = self.block.values
        if self.block.is_categorical:
            values_flat = values.categories
        elif is_sparse(self.block.values.dtype):
            return False
        elif self.block.is_extension:
            values_flat = values
        else:
            values_flat = values.ravel(order="K")
        total_len = values_flat.shape[0]
        chunk_len = max(total_len // 40, 1000)
        for i in range(0, total_len, chunk_len):
            if not isna(values_flat[i : i + chunk_len]).all():
                return False
        return True
    def get_reindexed_values(self, empty_dtype, upcasted_na):
        if upcasted_na is None:
            fill_value = self.block.fill_value
            values = self.block.get_values()
        else:
            fill_value = upcasted_na
            if self.is_na:
                if getattr(self.block, "is_object", False):
                    values = self.block.values.ravel(order="K")
                    if len(values) and values[0] is None:
                        fill_value = None
                if getattr(self.block, "is_datetimetz", False) or is_datetime64tz_dtype(
                    empty_dtype
                ):
                    if self.block is None:
                        array = empty_dtype.construct_array_type()
                        return array(
                            np.full(self.shape[1], fill_value.value), dtype=empty_dtype
                        )
                elif getattr(self.block, "is_categorical", False):
                    pass
                elif getattr(self.block, "is_extension", False):
                    pass
                else:
                    missing_arr = np.empty(self.shape, dtype=empty_dtype)
                    missing_arr.fill(fill_value)
                    return missing_arr
            if not self.indexers:
                if not self.block._can_consolidate:
                    return self.block.values
            if self.block.is_bool and not self.block.is_categorical:
                values = self.block.astype(np.object_).values
            elif self.block.is_extension:
                values = self.block.values
            else:
                values = self.block.get_values()
        if not self.indexers:
            values = values.view()
        else:
            for ax, indexer in self.indexers.items():
                values = algos.take_nd(values, indexer, axis=ax, fill_value=fill_value)
        return values

