class Slot(object):
    def __init__(self, value=0.0, func=None):
        self._value = value
        self.compute_value = func if func is not None else lambda: self._value
    def value(self):
        return self.compute_value()
    def __repr__(self):
        return "<Slot {}>".format(self.value())
    def __str__(self):
        return str(self.value())
    def __add__(self, val):
        return Slot(self, lambda: self.value() + val)
    def __radd__(self, val):
        return Slot(self, lambda: val + self.value())
    def __sub__(self, val):
        return Slot(self, lambda: self.value() - val)
    def __rsub__(self, val):
        return Slot(self, lambda: val - self.value())
    def __mul__(self, val):
        return Slot(self, lambda: self.value() * val)
    def __rmul__(self, val):
        return Slot(self, lambda: val * self.value())
    def __div__(self, val):
        return Slot(self, lambda: self.value() / val)
    def __rdiv__(self, val):
        return Slot(self, lambda: val / self.value())
    def __neg__(self):
        return Slot(self, lambda: -self.value())
    def __abs__(self):
        return Slot(self, lambda: abs(self.value()))
    def __max__(self, other):
        return max(other, self.value())
    def __lt__(self, other):
        return self.value() < other
    def __le__(self, other):
        return self.value() <= other
    def __eq__(self, other):
        return self.value() == other
    def __ne__(self, other):
        return self.value() != other
    def __gt__(self, other):
        return self.value() > other
    def __ge__(self, other):
        return self.value() >= other

class Vector:
    def __init__(self, x, y=None, z=None):
        if y is None and z is None:
            if len(x) != 3:
                raise ValueError("Vector: x is not a list/tuple/array of 3 numbers")
            self._ar = numpy.array(x, "d")
        else:
            self._ar = numpy.array((x, y, z), "d")
    def __repr__(self):
        x, y, z = self._ar
        return "<Vector %.2f, %.2f, %.2f>" % (x, y, z)
    def __neg__(self):
        a = -self._ar
        return Vector(a)
    def __add__(self, other):
        if isinstance(other, Vector):
            a = self._ar + other._ar
        else:
            a = self._ar + numpy.array(other)
        return Vector(a)
    def __sub__(self, other):
        if isinstance(other, Vector):
            a = self._ar - other._ar
        else:
            a = self._ar - numpy.array(other)
        return Vector(a)
    def __mul__(self, other):
        return sum(self._ar * other._ar)
    def __truediv__(self, x):
        a = self._ar / numpy.array(x)
        return Vector(a)
    def __pow__(self, other):
        if isinstance(other, Vector):
            a, b, c = self._ar
            d, e, f = other._ar
            c1 = numpy.linalg.det(numpy.array(((b, c), (e, f))))
            c2 = -numpy.linalg.det(numpy.array(((a, c), (d, f))))
            c3 = numpy.linalg.det(numpy.array(((a, b), (d, e))))
            return Vector(c1, c2, c3)
        else:
            a = self._ar * numpy.array(other)
            return Vector(a)
    def __getitem__(self, i):
        return self._ar[i]
    def __setitem__(self, i, value):
        self._ar[i] = value
    def __contains__(self, i):
        return i in self._ar
    def norm(self):
        return numpy.sqrt(sum(self._ar * self._ar))
    def normsq(self):
        return abs(sum(self._ar * self._ar))
    def normalize(self):
        if self.norm():
            self._ar = self._ar / self.norm()
    def normalized(self):
        v = self.copy()
        v.normalize()
        return v
    def angle(self, other):
        n1 = self.norm()
        n2 = other.norm()
        c = (self * other) / (n1 * n2)
        c = min(c, 1)
        c = max(-1, c)
        return numpy.arccos(c)
    def get_array(self):
        return numpy.array(self._ar)
    def left_multiply(self, matrix):
        a = numpy.dot(matrix, self._ar)
        return Vector(a)
    def right_multiply(self, matrix):
        a = numpy.dot(self._ar, matrix)
        return Vector(a)
    def copy(self):
        return Vector(self._ar)

