class Action(object):
    ACTION_UNDO = 'UNDO'
    ACTION_MOVE = 'MOVE'
    ACTION_CAPTURE = 'CAPTURE'
    def __init__(
        self,
        action_type,
        source,
        destination,
        captured=None,
    ):
        self.type_ = action_type
        self.source = source
        self.destination = destination
        self.captured = captured
    def undo(self):
        return Action(
            self.ACTION_UNDO,
            self.destination,
            self.source,
            self.captured,
        )
    def copy(self):
        return Action(
            self.type_,
            self.source,
            self.destination,
            self.captured,
        )
    def __len__(self):
        return 1
    def __eq__(self, other):
        if other is None:
            return False
        if self.type_ != other.type_:
            return False
        if self.source != other.source:
            return False
        if self.destination != other.destination:
            return False
        if self.captured != other.captured:
            return False
        return True
    def __repr__(self):
        return self.__str__()
    def __str__(self):
        return "{0} :: <{1}, {2}> -> <{3}, {4}>".format(
            self.type_,
            self.source[0],
            self.source[1],
            self.destination[0],
            self.destination[1]
        )

