class Noxious(object):
    def __init__(self, elem, parent=None):
        self._parent = parent
        self._elem = elem
    def _all(self):
        return [self.__class__(sibling)
                for sibling in self._parent._elem.findall(self._elem.tag)]
    def _get_path(self):
        path = []
        tag = self
        while tag:
            path.insert(0, tag._elem.tag)
            tag = tag._parent
        root = path.pop(0)
        return root + ''.join('[{!r}]'.format(p) for p in path)
    def _text(self):
        return self._elem.text
    def __add__(self, other):
        return str(self) + other
    def __bool__(self):
        e = self._elem
        return bool(e.text or list(e))
    def __float__(self):
        return float(str(self))
    def __int__(self):
        return int(str(self))
    def __getitem__(self, name):
        child = self._elem.find(name)
        if child is None:
            raise KeyError('No child {} on {!r}'.format(name, self))
        return self.__class__(child, self)
    def __getattr__(self, name):
        if name not in self._elem.attrib:
            raise AttributeError('No attribute {} on {!r}'.format(name, self))
        return self._elem.attrib[name]
    __nonzero__ = __bool__
    def __radd__(self, other):
        return other + str(self)
    def __str__(self):
        return self._text()
    def __repr__(self):
        return self._get_path()

class GridSpecBase:
    def __init__(self, nrows, ncols, height_ratios=None, width_ratios=None):
        self._nrows, self._ncols = nrows, ncols
        self.set_height_ratios(height_ratios)
        self.set_width_ratios(width_ratios)
    def __repr__(self):
        height_arg = (', height_ratios=%r' % (self._row_height_ratios,)
                      if self._row_height_ratios is not None else '')
        width_arg = (', width_ratios=%r' % (self._col_width_ratios,)
                     if self._col_width_ratios is not None else '')
        return '{clsname}({nrows}, {ncols}{optionals})'.format(
            clsname=self.__class__.__name__,
            nrows=self._nrows,
            ncols=self._ncols,
            optionals=height_arg + width_arg,
            )
    nrows = property(lambda self: self._nrows,
                     doc="The number of rows in the grid.")
    ncols = property(lambda self: self._ncols,
                     doc="The number of columns in the grid.")
    def get_geometry(self):
        return self._nrows, self._ncols
    def get_subplot_params(self, figure=None):
        pass
    def new_subplotspec(self, loc, rowspan=1, colspan=1):
        loc1, loc2 = loc
        subplotspec = self[loc1:loc1+rowspan, loc2:loc2+colspan]
        return subplotspec
    def set_width_ratios(self, width_ratios):
        if width_ratios is not None and len(width_ratios) != self._ncols:
            raise ValueError('Expected the given number of width ratios to '
                             'match the number of columns of the grid')
        self._col_width_ratios = width_ratios
    def get_width_ratios(self):
        return self._col_width_ratios
    def set_height_ratios(self, height_ratios):
        if height_ratios is not None and len(height_ratios) != self._nrows:
            raise ValueError('Expected the given number of height ratios to '
                             'match the number of rows of the grid')
        self._row_height_ratios = height_ratios
    def get_height_ratios(self):
        return self._row_height_ratios
    def get_grid_positions(self, fig, raw=False):
        nrows, ncols = self.get_geometry()
        if raw:
            left = 0.
            right = 1.
            bottom = 0.
            top = 1.
            wspace = 0.
            hspace = 0.
        else:
            subplot_params = self.get_subplot_params(fig)
            left = subplot_params.left
            right = subplot_params.right
            bottom = subplot_params.bottom
            top = subplot_params.top
            wspace = subplot_params.wspace
            hspace = subplot_params.hspace
        tot_width = right - left
        tot_height = top - bottom
        cell_h = tot_height / (nrows + hspace*(nrows-1))
        sep_h = hspace * cell_h
        if self._row_height_ratios is not None:
            norm = cell_h * nrows / sum(self._row_height_ratios)
            cell_heights = [r * norm for r in self._row_height_ratios]
        else:
            cell_heights = [cell_h] * nrows
        sep_heights = [0] + ([sep_h] * (nrows-1))
        cell_hs = np.cumsum(np.column_stack([sep_heights, cell_heights]).flat)
        cell_w = tot_width / (ncols + wspace*(ncols-1))
        sep_w = wspace * cell_w
        if self._col_width_ratios is not None:
            norm = cell_w * ncols / sum(self._col_width_ratios)
            cell_widths = [r * norm for r in self._col_width_ratios]
        else:
            cell_widths = [cell_w] * ncols
        sep_widths = [0] + ([sep_w] * (ncols-1))
        cell_ws = np.cumsum(np.column_stack([sep_widths, cell_widths]).flat)
        fig_tops, fig_bottoms = (top - cell_hs).reshape((-1, 2)).T
        fig_lefts, fig_rights = (left + cell_ws).reshape((-1, 2)).T
        return fig_bottoms, fig_tops, fig_lefts, fig_rights
    def __getitem__(self, key):
        nrows, ncols = self.get_geometry()
        def _normalize(key, size, axis):  
            orig_key = key
            if isinstance(key, slice):
                start, stop, _ = key.indices(size)
                if stop > start:
                    return start, stop - 1
                raise IndexError("GridSpec slice would result in no space "
                                 "allocated for subplot")
            else:
                if key < 0:
                    key = key + size
                if 0 <= key < size:
                    return key, key
                elif axis is not None:
                    raise IndexError(f"index {orig_key} is out of bounds for "
                                     f"axis {axis} with size {size}")
                else:  
                    raise IndexError(f"index {orig_key} is out of bounds for "
                                     f"GridSpec with size {size}")
        if isinstance(key, tuple):
            try:
                k1, k2 = key
            except ValueError as err:
                raise ValueError("Unrecognized subplot spec") from err
            num1, num2 = np.ravel_multi_index(
                [_normalize(k1, nrows, 0), _normalize(k2, ncols, 1)],
                (nrows, ncols))
        else:  
            num1, num2 = _normalize(key, nrows * ncols, None)
        return SubplotSpec(self, num1, num2)
    def subplots(self, sharex=False, sharey=False, squeeze=True,
                 subplot_kw=None):
        figure = self[0, 0].get_topmost_subplotspec().get_gridspec().figure
        if figure is None:
            raise ValueError("GridSpec.subplots() only works for GridSpecs "
                             "created with a parent figure")
        if isinstance(sharex, bool):
            sharex = "all" if sharex else "none"
        if isinstance(sharey, bool):
            sharey = "all" if sharey else "none"
        if isinstance(sharex, Integral):
            cbook._warn_external(
                "sharex argument to subplots() was an integer.  Did you "
                "intend to use subplot() (without 's')?")
        cbook._check_in_list(["all", "row", "col", "none"],
                             sharex=sharex, sharey=sharey)
        if subplot_kw is None:
            subplot_kw = {}
        subplot_kw = subplot_kw.copy()
        axarr = np.empty((self._nrows, self._ncols), dtype=object)
        for row in range(self._nrows):
            for col in range(self._ncols):
                shared_with = {"none": None, "all": axarr[0, 0],
                               "row": axarr[row, 0], "col": axarr[0, col]}
                subplot_kw["sharex"] = shared_with[sharex]
                subplot_kw["sharey"] = shared_with[sharey]
                axarr[row, col] = figure.add_subplot(
                    self[row, col], **subplot_kw)
        if sharex in ["col", "all"]:
            for ax in axarr[:-1, :].flat:
                ax.xaxis.set_tick_params(which='both',
                                         labelbottom=False, labeltop=False)
                ax.xaxis.offsetText.set_visible(False)
        if sharey in ["row", "all"]:
            for ax in axarr[:, 1:].flat:
                ax.yaxis.set_tick_params(which='both',
                                         labelleft=False, labelright=False)
                ax.yaxis.offsetText.set_visible(False)
        if squeeze:
            return axarr.item() if axarr.size == 1 else axarr.squeeze()
        else:
            return axarr

class SubplotSpec:
    def __init__(self, gridspec, num1, num2=None):
        self._gridspec = gridspec
        self.num1 = num1
        self.num2 = num2
        if gridspec._layoutbox is not None:
            glb = gridspec._layoutbox
            self._layoutbox = layoutbox.LayoutBox(
                    parent=glb,
                    name=glb.name + '.ss' + layoutbox.seq_id(),
                    artist=self)
        else:
            self._layoutbox = None
    def __repr__(self):
        return (f"{self.get_gridspec()}["
                f"{self.rowspan.start}:{self.rowspan.stop}, "
                f"{self.colspan.start}:{self.colspan.stop}]")
    @staticmethod
    def _from_subplot_args(figure, args):
        if len(args) == 1:
            arg, = args
            if isinstance(arg, SubplotSpec):
                return arg
            else:
                try:
                    s = str(int(arg))
                    rows, cols, num = map(int, s)
                except ValueError as err:
                    raise ValueError("Single argument to subplot must be a "
                                     "3-digit integer") from err
                return GridSpec(rows, cols, figure=figure)[num - 1]
        elif len(args) == 3:
            rows, cols, num = args
            rows = int(rows)
            cols = int(cols)
            if rows <= 0:
                raise ValueError(f"Number of rows must be > 0, not {rows}")
            if cols <= 0:
                raise ValueError(f"Number of columns must be > 0, not {cols}")
            if isinstance(num, tuple) and len(num) == 2:
                i, j = map(int, num)
                return GridSpec(rows, cols, figure=figure)[i-1:j]
            else:
                if num < 1 or num > rows*cols:
                    raise ValueError(
                        f"num must be 1 <= num <= {rows*cols}, not {num}")
                return GridSpec(rows, cols, figure=figure)[int(num) - 1]
        else:
            raise TypeError(f"subplot() takes 1 or 3 positional arguments but "
                            f"{len(args)} were given")
    @property
    def num2(self):
        return self.num1 if self._num2 is None else self._num2
    @num2.setter
    def num2(self, value):
        self._num2 = value
    def __getstate__(self):
        return {**self.__dict__, "_layoutbox": None}
    def get_gridspec(self):
        return self._gridspec
    def get_geometry(self):
        rows, cols = self.get_gridspec().get_geometry()
        return rows, cols, self.num1, self.num2
    @cbook.deprecated("3.3", alternative="rowspan, colspan")
    def get_rows_columns(self):
        gridspec = self.get_gridspec()
        nrows, ncols = gridspec.get_geometry()
        row_start, col_start = divmod(self.num1, ncols)
        row_stop, col_stop = divmod(self.num2, ncols)
        return nrows, ncols, row_start, row_stop, col_start, col_stop
    @property
    def rowspan(self):
        ncols = self.get_gridspec().ncols
        return range(self.num1 // ncols, self.num2 // ncols + 1)
    @property
    def colspan(self):
        ncols = self.get_gridspec().ncols
        return range(self.num1 % ncols, self.num2 % ncols + 1)
    def get_position(self, figure, return_all=False):
        gridspec = self.get_gridspec()
        nrows, ncols = gridspec.get_geometry()
        rows, cols = np.unravel_index([self.num1, self.num2], (nrows, ncols))
        fig_bottoms, fig_tops, fig_lefts, fig_rights = \
            gridspec.get_grid_positions(figure)
        fig_bottom = fig_bottoms[rows].min()
        fig_top = fig_tops[rows].max()
        fig_left = fig_lefts[cols].min()
        fig_right = fig_rights[cols].max()
        figbox = Bbox.from_extents(fig_left, fig_bottom, fig_right, fig_top)
        if return_all:
            return figbox, rows[0], cols[0], nrows, ncols
        else:
            return figbox
    def get_topmost_subplotspec(self):
        gridspec = self.get_gridspec()
        if hasattr(gridspec, "get_topmost_subplotspec"):
            return gridspec.get_topmost_subplotspec()
        else:
            return self
    def __eq__(self, other):
        return ((self._gridspec, self.num1, self.num2)
                == (getattr(other, "_gridspec", object()),
                    getattr(other, "num1", object()),
                    getattr(other, "num2", object())))
    def __hash__(self):
        return hash((self._gridspec, self.num1, self.num2))
    def subgridspec(self, nrows, ncols, **kwargs):
        return GridSpecFromSubplotSpec(nrows, ncols, self, **kwargs)

class DoublyLinkedList:
    class Node:
        def __init__(self, data=None, next=None, prev=None):
            self.data = data
            self.next = next
            self.prev = prev
        def disconnect(self):
            self.data = None
            self.next = None
            self.prev = None
    def __init__(self):
        self.header = DoublyLinkedList.Node()
        self.trailer = DoublyLinkedList.Node()
        self.header.next = self.trailer
        self.trailer.prev = self.header
        self.size = 0
    def __len__(self):
        return self.size
    def is_empty(self):
        return (len(self) == 0)
    def first_node(self):
        if (self.is_empty()):
            raise Empty("List is empty")
        return self.header.next
    def last_node(self):
        if (self.is_empty()):
            raise Empty("List is empty")
        return self.trailer.prev
    def add_first(self, elem):
        return self.add_after(self.header, elem)
    def add_last(self, elem):
        return self.add_after(self.trailer.prev, elem)
    def add_after(self, node, elem):
        prev = node
        succ = node.next
        new_node = DoublyLinkedList.Node()
        new_node.data = elem
        new_node.prev = prev
        new_node.next = succ
        prev.next = new_node
        succ.prev = new_node
        self.size += 1
        return new_node
    def add_before(self, node, elem):
        return self.add_after(node.prev, elem)
    def delete(self, node):
        prev = node.prev
        succ = node.next
        prev.next = succ
        succ.prev = prev
        self.size -= 1
        data = node.data
        node.disconnect()
        return data
    def __iter__(self):
        if(self.is_empty()):
            return
        cursor = self.first_node()
        while(cursor is not self.trailer):
            yield cursor.data
            cursor = cursor.next
    def __str__(self):
        return '[' + '<-->'.join([str(elem) for elem in self]) + ']'
    def __repr__(self):
        return str(self)

