class BinarySearchTree(object):
    def __init__(self, values: list = []):
        self.root = None  
        for value in values:
            self.insert(value)
    def insert(self, data):
        assert isinstance(data, int)
        if self.root is None:
            self.root = TreeNode(val=data)
        else:
            current = self.root
            p = None
            while current:
                p = current
                if data < current.val:
                    current = current.left
                else:
                    current = current.right
            new_node = TreeNode(data)
            new_node.parent = p
            if data < p.val:
                p.left = new_node
            else:
                p.right = new_node
        return True
    def search(self, data):
        assert isinstance(data, int)
        ret = []  
        current = self.root
        while current:
            if data < current.val:
                current = current.right
            else:
                if data == current.val:
                    ret.append(current)
                current = current.right  
        return ret
    def delete(self, data):
        assert isinstance(data, int)
        del_list = self.search(data)
        for n in del_list:
            if n.parent is None and n != self.root:
                continue
            else:
                self._del(n)
    def _del(self, node: TreeNode):
        if node.left is None and node.right is None:
            if node == self.root:
                self.root = None
            else:
                if node.val < node.parent.val:
                    node.parent.left = None  
                else:
                    node.parent.right = None
            node.parent = None  
        elif node.left is None and node.right is not None:
            if node == self.root:
                self.root = node.right
                self.root.parent = None  
                node.right = None  
            else:
                if node.val < node.parent.val:
                    node.parent.left = node.right
                else:
                    node.parent.right = node.right
                node.right.parent = node.parent  
                node.right = None
                node.parent = None
        elif node.left is not None and node.right is None:
            if node == self.root:
                self.root = node.left
                self.root.parent = None
                node.right = None
            else:
                if node.val < node.parent.val:
                    node.parent.left = node.left
                else:
                    node.parent.right = node.left
                node.left.parent = node.parent
                node.left = None
                node.parent = None
        else:
            min_node = node.right
            while min_node.left:
                min_node = min_node.left
            if node.val != min_node.val:
                node.val = min_node.val
                self._del(min_node)
            else:
                self._del(min_node)  
                self._del(node)  
    def get_min(self):
        if self.root is None:
            return None
        n = self.root
        while n.left:
            n = n.left
        return n.val
    def get_max(self):
        if self.root is None:
            return None
        n = self.root
        while n.right:
            n = n.right
        return n.val
    def order(self):
        if self.root is None:
            return []
        return self._in_order(self.root)
    def _in_order(self, node):
        if node is None:
            return []
        ret = []
        n = node
        ret.extend(self._in_order(n.left))
        ret.append(n.val)
        ret.extend(self._in_order(n.right))
        return ret
    def _draw_tree(self):
        nodes = self._bfs()
        if not nodes:
            print('This tree has no nodes.')
            return
        layer_num = int(math.log(nodes[-1][1], 2)) + 1
        prt_nums = []
        for i in range(layer_num):
            prt_nums.append([None] * 2 ** i)
        for v, p in nodes:
            row = int(math.log(p, 2))
            col = p % 2 ** row
            prt_nums[row][col] = v
        prt_str = ''
        for l in prt_nums:
            prt_str += str(l)[1:-1] + '\n'
        return prt_str
    def _bfs(self):
        if self.root is None:
            return []
        ret = []
        q = Queue()  
        q.put((self.root, 1))
        while not q.empty():
            n = q.get()  
            if n[0] is not None:
                ret.append((n[0].val, 1))
                q.put((n[0].left, n[1]*2))  
                q.put((n[0].right, n[1]*2+1))  
        return ret
    def __repr__(self):
        logger.info(str(self.order()))  
        return self._draw_tree()

