class Board:
    goal = None
    def __init__(self, size, R_pos, B_pos, Y_pos, G_pos, barriers):
        self.robots = {"R": R_pos, "B": B_pos, "Y": Y_pos, "G": G_pos}
        self.barriers = barriers
        self.size = size
    def __eq__(self, other):
        if type(other) is type(self):
            return self.robots == other.robots and self.size == other.size
        return False
    def __hash__(self):
        return hash((self.robots["R"], self.robots["B"], self.robots["Y"], self.robots["G"], self.size))
    def robot_position(self, robot: str):
        return self.robots[robot]
    def possible_actions(self, robot: str):
        actions = []
        (x, y) = self.robot_position(robot)
        if y != self.size: 
            if (x, y + 1) not in self.robots.values():
                if (x, y + 1) not in self.barriers["l"] and (x, y) not in self.barriers["r"]:
                    actions.append("r")
        if y != 1: 
            if (x, y - 1) not in self.robots.values():
                if (x, y - 1) not in self.barriers["r"] and (x, y) not in self.barriers["l"]:
                    actions.append("l")
        if x != self.size: 
            if (x + 1, y) not in self.robots.values():
                if (x + 1, y) not in self.barriers["u"] and (x, y) not in self.barriers["d"]:
                    actions.append("d")
        if x != 1: 
            if (x - 1, y) not in self.robots.values():
                if (x - 1, y) not in self.barriers["d"] and (x, y) not in self.barriers["u"]:
                    actions.append("u")
        return actions

class RedisDict(object):
    def __init__(self, *args, **kwargs):
        self.namespace = ''
        if 'namespace' in kwargs:
            self.namespace = kwargs['namespace'] + ':'
            del kwargs['namespace']
        self.expire = None
        if 'expire' in kwargs:
            self.expire = kwargs['expire']
            del kwargs['expire']
        self.redis = StrictRedis(*args, decode_responses=True, **kwargs)
        self.sentinel_none = '<META __None__ 9cab>'
    def _raw_get_item(self, k):
        return self.redis.get(k)
    def _get_item(self, k):
        result = self._raw_get_item(self.namespace + k)
        return result
    def __getitem__(self, k):
        result = self._get_item(k)
        if result is None:
            raise KeyError
        return result if result != self.sentinel_none else None
    def __setitem__(self, k, v):
        if v is None:
            v = self.sentinel_none
        self.redis.set(self.namespace + k, v, ex=self.expire)
    def __delitem__(self, k):
        self.redis.delete(self.namespace + k)
    def __contains__(self, k):
        return self._get_item(k) is not None
    def __repr__(self):
        return str(self.to_dict())
    def __str__(self):
        return self.__repr__()
    def __len__(self):
        return len(self._keys())
    def _scan_keys(self, search_term=''):
        return self.redis.scan(match=self.namespace + search_term + '*')
    def _keys(self, search_term=''):
        return self._scan_keys(search_term)[1]
    def keys(self):
        to_rm = len(self.namespace)
        return [item[to_rm:] for item in self._keys()]
    def to_dict(self):
        to_rm = len(self.namespace)
        return {item[to_rm:]: self._raw_get_item(item) for item in self._keys()}
    def chain_set(self, iterable, v):
        self[':'.join(iterable)] = v
    def chain_get(self, iterable):
        return self[':'.join(iterable)]
    def chain_del(self, iterable):
        return self.__delitem__(':'.join(iterable))
    @contextmanager
    def expire_at(self, sec_epoch):
        self.expire, temp = sec_epoch, self.expire
        yield
        self.expire = temp
    def __iter__(self):
        self.keys_iter = self.keys()
        return self
    def next(self):
        return self.__next__()
    def __next__(self):
        try:
            return self.keys_iter.pop()
        except (IndexError, KeyError):
            raise StopIteration
    def multi_get(self, key):
        found_keys = self._keys(key)
        if len(found_keys) == 0:
            return []
        return self.redis.mget(found_keys)
    def multi_chain_get(self, keys):
        return self.multi_get(':'.join(keys))
    def multi_dict(self, key):
        keys = self._keys(key)
        if len(keys) == 0:
            return {}
        to_rm = len(self.namespace)
        return dict(zip([i[to_rm:] for i in keys], self.redis.mget(keys)))
    def multi_del(self, key):
        keys = self._keys(key)
        if len(keys) == 0:
            return 0
        return self.redis.delete(*keys)
    def items(self):
        return zip(self.keys(), self.multi_get(self._keys()))

class Complex_number:
    def __init__(self, real, imaginary):
        if type(real) not in [int, float] and type(imaginary) not in [int, float]:
            print("Real and Imaginary parts must be Integers or Float")
            return 
        self.real = real
        self.imaginary = imaginary
    def __repr__(self):
        return self.real + self.imaginary * 1j
    def modulus(self):
        return (self.real**2 + self.imaginary**2) ** 0.5
    def __add__(self, other):
        real_part = self.real + other.real
        imaginary_part = self.imaginary + other.imaginary
        return real_part + imaginary_part * 1j
    def __sub__(self, other):
        real_part = self.real - other.real
        imaginary_part = self.imaginary - other.imaginary
        return real_part + imaginary_part * 1j
    def __eq__(self, other):
        return self.real == other.real and self.imaginary == other.imaginary
    def __lt__(self, other):
        return self.modulus() < other.modulus()
    def __le__(self, other):
        return self.modulus() <= other.modulus()
    def __gt__(self, other):
        return self.modulus() > other.modulus()
    def __ge__(self, other):
        return self.modulus() >= other.modulus()
    def __ne__(self, other):
        return self.real != other.real and self.imaginary != other.imaginary

class PaillierPublicKey(object):
    def __init__(self, n):
        self.g = n + 1
        self.n = n
        self.nsquare = n * n
        self.max_int = n // 3 - 1
    def __repr__(self):
        publicKeyHash = hex(hash(self))[2:]
        return "<PaillierPublicKey {}>".format(publicKeyHash[:10])
    def __eq__(self, other):
        return self.n == other.n
    def __hash__(self):
        return hash(self.n)
    def raw_encrypt(self, plaintext, r_value=None):
        if not isinstance(plaintext, int):
            raise TypeError('Expected int type plaintext but got: %s' %
                            type(plaintext))
        if self.n - self.max_int <= plaintext < self.n:
            neg_plaintext = self.n - plaintext  
            neg_ciphertext = (self.n * neg_plaintext + 1) % self.nsquare
            nude_ciphertext = invert(neg_ciphertext, self.nsquare)
        else:
            nude_ciphertext = (self.n * plaintext + 1) % self.nsquare
        r = r_value or self.get_random_lt_n()
        obfuscator = powmod(r, self.n, self.nsquare)
        return (nude_ciphertext * obfuscator) % self.nsquare
    def get_random_lt_n(self):
        return random.SystemRandom().randrange(1, self.n)
    def encrypt(self, value, precision=None, r_value=None):
        if isinstance(value, EncodedNumber):
            encoding = value
        else:
            encoding = EncodedNumber.encode(self, value, precision)
        return self.encrypt_encoded(encoding, r_value)
    def encrypt_encoded(self, encoding, r_value):
        obfuscator = r_value or 1
        ciphertext = self.raw_encrypt(encoding.encoding, r_value=obfuscator)
        encrypted_number = EncryptedNumber(self, ciphertext, encoding.exponent)
        if r_value is None:
            encrypted_number.obfuscate()
        return encrypted_number

class PaillierPrivateKey(object):
    def __init__(self, public_key, p, q):
        if not p*q == public_key.n:
            raise ValueError('given public key does not match the given p and q.')
        if p == q:
            raise ValueError('p and q have to be different')
        self.public_key = public_key
        if q < p: 
            self.p = q
            self.q = p
        else:
            self.p = p
            self.q = q
        self.psquare = self.p * self.p
        self.qsquare = self.q * self.q
        self.p_inverse = invert(self.p, self.q)
        self.hp = self.h_function(self.p, self.psquare)
        self.hq = self.h_function(self.q, self.qsquare)
    @staticmethod
    def from_totient(public_key, totient):
        p_plus_q = public_key.n - totient + 1
        p_minus_q = isqrt(p_plus_q * p_plus_q - public_key.n * 4)
        q = (p_plus_q - p_minus_q) // 2
        p = p_plus_q - q
        if not p*q == public_key.n:
            raise ValueError('given public key and totient do not match.')
        return PaillierPrivateKey(public_key, p, q)
    def __repr__(self):
        pub_repr = repr(self.public_key)
        return "<PaillierPrivateKey for {}>".format(pub_repr)
    def decrypt(self, encrypted_number):
        encoded = self.decrypt_encoded(encrypted_number)
        return encoded.decode()
    def decrypt_encoded(self, encrypted_number, Encoding=None):
        if not isinstance(encrypted_number, EncryptedNumber):
            raise TypeError('Expected encrypted_number to be an EncryptedNumber'
                            ' not: %s' % type(encrypted_number))
        if self.public_key != encrypted_number.public_key:
            raise ValueError('encrypted_number was encrypted against a '
                             'different key!')
        if Encoding is None:
            Encoding = EncodedNumber
        encoded = self.raw_decrypt(encrypted_number.ciphertext(be_secure=False))
        return Encoding(self.public_key, encoded,
                             encrypted_number.exponent)
    def raw_decrypt(self, ciphertext):
        if not isinstance(ciphertext, int):
            raise TypeError('Expected ciphertext to be an int, not: %s' %
                type(ciphertext))
        decrypt_to_p = self.l_function(powmod(ciphertext, self.p-1, self.psquare), self.p) * self.hp % self.p
        decrypt_to_q = self.l_function(powmod(ciphertext, self.q-1, self.qsquare), self.q) * self.hq % self.q
        return self.crt(decrypt_to_p, decrypt_to_q)
    def h_function(self, x, xsquare):
        return invert(self.l_function(powmod(self.public_key.g, x - 1, xsquare),x), x)
    def l_function(self, x, p):
        return (x - 1) // p
    def crt(self, mp, mq):
        u = (mq - mp) * self.p_inverse % self.q
        return mp + (u * self.p)
    def __eq__(self, other):
        return self.p == other.p and self.q == other.q
    def __hash__(self):
        return hash((self.p, self.q))

class Algorithm(Trainable):
    _allow_unknown_configs = False
    _allow_unknown_subkeys = [
        "tf_session_args",
        "local_tf_session_args",
        "env_config",
        "model",
        "optimizer",
        "multiagent",
        "custom_resources_per_worker",
        "evaluation_config",
        "exploration_config",
        "replay_buffer_config",
        "extra_python_environs_for_worker",
        "input_config",
        "output_config",
    ]
    _override_all_subkeys_if_type_changes = [
        "exploration_config",
        "replay_buffer_config",
    ]
    _override_all_key_list = ["off_policy_estimation_methods"]
    _progress_metrics = [
        "episode_reward_mean",
        "evaluation/episode_reward_mean",
        "num_env_steps_sampled",
        "num_env_steps_trained",
    ]
    @staticmethod
    def from_checkpoint(
        checkpoint: Union[str, Checkpoint],
        policy_ids: Optional[Container[PolicyID]] = None,
        policy_mapping_fn: Optional[Callable[[AgentID, EpisodeID], PolicyID]] = None,
        policies_to_train: Optional[
            Union[
                Container[PolicyID],
                Callable[[PolicyID, Optional[SampleBatchType]], bool],
            ]
        ] = None,
    ) -> "Algorithm":
        checkpoint_info = get_checkpoint_info(checkpoint)
        if checkpoint_info["checkpoint_version"] == version.Version("0.1"):
            raise ValueError(
                "Cannot restore a v0 checkpoint using `Algorithm.from_checkpoint()`!"
                "In this case, do the following:\n"
                "1) Create a new Algorithm object using your original config.\n"
                "2) Call the `restore()` method of this algo object passing it"
                " your checkpoint dir or AIR Checkpoint object."
            )
        if checkpoint_info["checkpoint_version"] < version.Version("1.0"):
            raise ValueError(
                "`checkpoint_info['checkpoint_version']` in `Algorithm.from_checkpoint"
                "()` must be 1.0 or later! You are using a checkpoint with "
                f"version v{checkpoint_info['checkpoint_version']}."
            )
        state = Algorithm._checkpoint_info_to_algorithm_state(
            checkpoint_info=checkpoint_info,
            policy_ids=policy_ids,
            policy_mapping_fn=policy_mapping_fn,
            policies_to_train=policies_to_train,
        )
        return Algorithm.from_state(state)
    @staticmethod
    def from_state(state: Dict) -> "Algorithm":
        algorithm_class: Type[Algorithm] = state.get("algorithm_class")
        if algorithm_class is None:
            raise ValueError(
                "No `algorithm_class` key was found in given `state`! "
                "Cannot create new Algorithm."
            )
        config = state.get("config")
        if not config:
            raise ValueError("No `config` found in given Algorithm state!")
        new_algo = algorithm_class(config=config)
        new_algo.__setstate__(state)
        return new_algo
    @PublicAPI
    def __init__(
        self,
        config: Optional[Union[PartialAlgorithmConfigDict, AlgorithmConfig]] = None,
        env: Optional[Union[str, EnvType]] = None,
        logger_creator: Optional[Callable[[], Logger]] = None,
        **kwargs,
    ):
        config = config or {}
        if isinstance(config, AlgorithmConfig):
            config = config.to_dict()
        self._env_id, self.env_creator = self._get_env_id_and_creator(
            env or config.get("env"), config
        )
        env_descr = (
            self._env_id.__name__ if isinstance(self._env_id, type) else self._env_id
        )
        self.local_replay_buffer = None
        if logger_creator is None:
            timestr = datetime.today().strftime("%Y-%m-%d_%H-%M-%S")
            logdir_prefix = "{}_{}_{}".format(str(self), env_descr, timestr)
            if not os.path.exists(DEFAULT_RESULTS_DIR):
                os.makedirs(DEFAULT_RESULTS_DIR, exist_ok=True)
            logdir = tempfile.mkdtemp(prefix=logdir_prefix, dir=DEFAULT_RESULTS_DIR)
            if config.get("logger_config") and "type" in config["logger_config"]:
                def default_logger_creator(config):
                    cfg = config["logger_config"].copy()
                    cls = cfg.pop("type")
                    logdir_ = cfg.pop("logdir", logdir)
                    return from_config(cls=cls, _args=[cfg], logdir=logdir_)
            else:
                def default_logger_creator(config):
                    return UnifiedLogger(config, logdir, loggers=None)
            logger_creator = default_logger_creator
        self._timers = defaultdict(_Timer)
        self._counters = defaultdict(int)
        self._episode_history = []
        self._episodes_to_be_collected = []
        self._remote_workers_for_metrics = []
        self.evaluation_workers: Optional[WorkerSet] = None
        self._evaluation_async_req_manager: Optional[AsyncRequestsManager] = None
        self.evaluation_metrics = {
            "evaluation": {
                "episode_reward_max": np.nan,
                "episode_reward_min": np.nan,
                "episode_reward_mean": np.nan,
            }
        }
        super().__init__(config=config, logger_creator=logger_creator, **kwargs)
        try:
            assert isinstance(self.training_iteration, int)
        except AssertionError:
            raise AssertionError(
                "Your Algorithm's `training_iteration` seems to be overridden by your "
                "custom training logic! To solve this problem, simply rename your "
                "`self.training_iteration()` method into `self.training_step`."
            )
    @OverrideToImplementCustomLogic
    @classmethod
    def get_default_config(cls) -> AlgorithmConfigDict:
        return AlgorithmConfig().to_dict()
    @OverrideToImplementCustomLogic_CallToSuperRecommended
    @override(Trainable)
