class User:
    def __init__(self, username: str, password):
        self.__user_name = username.strip()
        self.__watched_movies = []
        self.__reviews = []
        self.__time_spent_watching_movies_minutes = 0
        self.__password = password
        self.__watchlist = []
    @property
    def username(self) -> str:
        return self.__user_name
    @property
    def watchlist(self) -> list:
        return self.__watchlist
    @property
    def password(self):
        return self.__password
    @property
    def watched_movies(self) -> list:
        return self.__watched_movies
    @property
    def reviews(self) -> list:
        return self.__reviews
    @property
    def time_spent_watching_movies_minutes(self) -> int:
        return self.__time_spent_watching_movies_minutes
    def __repr__(self):
        return f"<User {self.__user_name} {self.__password}>"
    def __eq__(self, other):
        return self.username == other.username
    def __lt__(self, other):
        return self.username < other.username
    def __hash__(self):
        return hash(self.username)
    def watch_movie(self, movie: Movie):
        self.__watched_movies.append(movie)
        self.__time_spent_watching_movies_minutes += movie.runtime_minutes
    def add_review(self, review):
        self.__reviews.append(review)
    def add_to_watchlist(self, movie):
        self.__watchlist.append(movie)
    def remove_from_watchlist(self, movie):
        watchlist = self.__watchlist
        if movie in watchlist:
            for i in range(len(watchlist) - 1, -1, -1):
                if movie == watchlist[i]:
                    watchlist.pop(i)
        self.__watchlist = watchlist

class Review:
    def __init__(self, user: User, movie: Movie, review_text: str):
        self.__movie = movie
        self.__review_text = review_text
        self.__timestamp = datetime.now()
        self.__user = user
    @property
    def movie(self) -> Movie:
        return self.__movie
    @property
    def user(self) -> User:
        return self.__user
    @property
    def username(self) -> str:
        return self.__user.username
    @property
    def review_text(self) -> str:
        return self.__review_text
    @property
    def timestamp(self) -> datetime:
        return self.__timestamp
    def __eq__(self, other):
        return self.movie == other.movie and self.review_text == other.review_text and self.rating == other.rating and self.timestamp == other.timestamp

class SimulationOutput(object):
    def __init__(self):
        self.channel_rt = None
        self.channel_rt_grid = None
        self.chanobs = None
        self.lakeout = None
        self.gwout = None
        self.rtout = None
        self.ldasout = None
        self.restart_hydro = None
        self.restart_lsm = None
        self.restart_nudging = None
    def __print__(self):
        return self.__repr__(self)
    def __repr__(self):
        all_none = all([ ff is None for ff in self.__dict__.values() ])
        if all_none:
            return "This simulation currently has no output. Run simulation.collect()."
        the_repr = ''
        for key, val in self.__dict__.items():
            if isinstance(val, xarray.core.dataset.Dataset):
                the_repr += '\n' + key + ':\n' + val.__repr__() + '\n\n'
            else:
                if val is not None:
                    the_len = str(len(val))
                else:
                    the_len = "0"
                the_repr += key + ': ' + the_len + ' files \n'
        return the_repr
    def collect_output(self, sim_dir: Union[str, pathlib.Path] = None):
        if sim_dir is None:
            sim_dir = pathlib.Path(os.curdir).absolute()
        else:
            sim_dir = pathlib.Path(sim_dir).absolute()
        file_glob_dict = {
            'channel_rt': '*CHRTOUT_DOMAIN*',
            'channel_rt_grid': '*CHRTOUT_GRID*',
            'chanobs': '*CHANOBS*',
            'lakeout': '*LAKEOUT*',
            'gwout': '*GWOUT*',
            'rtout': '*.RTOUT_*',
            'ldasout': '*LDASOUT*',
            'restart_hydro': 'HYDRO_RST*',
            'restart_lsm': 'RESTART*',
            'restart_nudging': 'nudgingLastObs*'}
        for key, value in file_glob_dict.items():
            self.__dict__[key] = sort_files_by_time(list(sim_dir.glob(value)))
            if key == 'ldasout':
                self.__dict__[key] = self.__dict__[key][1:]
    def open(self, name, n_cores=None):
        if not hasattr(self, name):
            raise ValueError('Simulation output does not contain ' + name)
        the_files = self.__dict__[name]
        if isinstance(the_files, list):
            self.__dict__[name] = open_whp_dataset(the_files)
        elif isinstance(the_files, xarray.core.dataset.Dataset):
            print("This output appears to already be open: " + name)
        else:
            raise ValueError("Can not open: " + name)
        return None
    def check_output_nans(self, n_cores: int = 1):
        data_atts = [att for att in dir(self) if not att.startswith('_')]
        df_list = []
        for att in data_atts:
            att_obj = getattr(self, att)
            if isinstance(att_obj, list) or isinstance(att_obj, WrfHydroTs):
                if len(att_obj) == 0:
                    continue
                file = att_obj[-1]
                na_check_result = check_file_nans(file, n_cores=n_cores)
                if na_check_result is not None:
                    na_check_result['file'] = str(file)
                    df_list.append(na_check_result)
        if len(df_list) > 0:
            return pd.concat(df_list)
        else:
            return None

class Direction:
    def __init__(self, index=0, direction=None):
        self.__abs_index = index
        if not direction:
            self.__direction = [1, 0]
        else:
            self.__direction = direction
    def __getitem__(self, key):
        return self.__direction[key]
    def __repr__(self):
        return str(self.__abs_index) + str(self.__direction)
    def __get_abs_index(self):
        return self.__abs_index
    abs_index = property(__get_abs_index)
    def previous(self):
        return Direction(self.__abs_index - 1, [self.__direction[1], -self.__direction[0]])
    def next(self):
        return Direction(self.__abs_index + 1, [-self.__direction[1], self.__direction[0]])

