class Rope():
  def __init__(self, knots) -> None:
    self.head = Knot(knots.pop(0))
    ptr = self.head
    while knots:
      k = knots.pop(0)
      ptr.next = Knot(k)
      ptr = ptr.next
  @property
  def tail(self):
    tail = self.head
    while tail.next:
      tail = tail.next
    return tail
  def __iter__(self):
    self.__ptr = self.head
    return self
  def __next__(self):
    n = None
    if self.__ptr:
      n = self.__ptr
      self.__ptr = n.next
    else:
      raise StopIteration
    return n
  def __repr__(self) -> str:
    return f"{list(self)}"
  def __str__(self) -> str:
    return f"{list(self)}"

class Bounds:
    def _input_validation(self):
        try:
            res = np.broadcast_arrays(self.lb, self.ub, self.keep_feasible)
            self.lb, self.ub, self.keep_feasible = res
        except ValueError:
            message = "`lb`, `ub`, and `keep_feasible` must be broadcastable."
            raise ValueError(message)
    def __init__(self, lb=-np.inf, ub=np.inf, keep_feasible=False):
        self.lb = np.atleast_1d(lb)
        self.ub = np.atleast_1d(ub)
        self.keep_feasible = np.atleast_1d(keep_feasible).astype(bool)
        self._input_validation()
    def __repr__(self):
        start = f"{type(self).__name__}({self.lb!r}, {self.ub!r}"
        if np.any(self.keep_feasible):
            end = f", keep_feasible={self.keep_feasible!r})"
        else:
            end = ")"
        return start + end
    def residual(self, x):
        return x - self.lb, self.ub - x

