class Model(MutableMapping):
    data = DataDescriptor()
    _filter_fields = frozenset()
    _fields = frozenset()
    def __init__(self, **kwargs):
        for key, value in kwargs.items():
            self[key] = value
    @classmethod
    def transform_incoming_data(cls, data):
        return data
    @classmethod
    def _wrap(cls, data):
        new_class = cls()
        new_class.data = data
        return new_class
    @classmethod
    def wrap(cls, data):
        data = cls.transform_incoming_data(data)
        if isinstance(data, list):
            return ListObject(wrapper=cls._wrap, data=data)
        return cls._wrap(data)
    def alter(self, keep_fields=None, clean_fields=None, **new_fields) -> 'Model':
        fields = self._fields
        if clean_fields:
            fields -= frozenset(clean_fields)
        if keep_fields:
            fields = keep_fields
        AlteredModel = type(
            'Altered{}'.format(self.__class__.__name__),
            (self.__class__,),
            {i: Field() for i in new_fields.keys()}
        )
        model = AlteredModel.wrap(new_fields)
        [setattr(model, field, getattr(self, field)) for field in fields]
        return model
    @classmethod
    def get_field_key(cls, field):
        return cls.__dict__[field].name
    def model_filter(self):
        dct = {}
        for i in self._filter_fields:
            try:
                dct[i] = getattr(self, i)
            except AttributeError:
                pass
        return dct
    def data_filter(self):
        dct = {}
        for i in self._filter_fields:
            name = self.get_field_key(i)
            try:
                dct[name] = self.data[name]
            except KeyError:
                pass
        return dct
    def __str__(self):
        return 'M:{}'.format(self.data)
    def __repr__(self):
        return self.__str__()
    def __len__(self):
        return len(self.data)
    def __iter__(self):
        for elem in self._fields:
            if getattr(self, elem, Dummy) != Dummy:
                yield elem
    def __getitem__(self, item):
        try:
            return getattr(self, item)
        except AttributeError:
            raise KeyError(f'Model: {self.__class__.__name__} has no Field: {item}')
    def __setitem__(self, key, value):
        if key not in self._fields:
            raise KeyError(f'Model: {self.__class__.__name__} has no Field: {key}')
        setattr(self, key, value)
    def __delitem__(self, key):
        try:
            delattr(self, key)
        except AttributeError:
            raise KeyError(f'Model: {self.__class__.__name__} has no Field: {key}')

class RetriMeter(object):
    def __init__(self, freq=1024):
        self.freq = freq
        self.total = 0
        self.replace = 0
        self.updates = 0
    def __call__(self, data):
        if isinstance(data, np.ndarray):
            self.replace += data.shape[0] - int((data[:, 0] == -1).sum())
            self.total += data.shape[0]
        elif torch.is_tensor(data):
            self.replace += int(data.sum())
            self.total += data.size(0)
        else:
            raise ValueError("unsupported RetriMeter data type.", type(data))
        self.updates += 1
        if get_local_rank() == 0 and self.updates % self.freq == 0:
            print("[INFO]", self)
    def __repr__(self):
        return "RetriMeter (" + str(self.replace / self.total) \
            + "/" + str(self.replace) + "/" + str(self.total) + ")"

class StaticBaseClass(ABC):
    __metaclass__ = ABCMeta
    def __init__(self):
        self._locked = True
    def __setattr__(self, key, value):
        if hasattr(self, "_locked"):
            if self._locked and not hasattr(self, key):
                raise TypeError("This class does not support dynamic property assignment.")
            if self._locked and not isinstance(value, type(self.__getattribute__(key))):
                raise TypeError("Expected type %s but received %s." % (type(self.__getattribute__(key)), type(value)))
        object.__setattr__(self, key, value)
    def __hash__(self):
        return reduce(lambda current, next: 23 * current + next, [hash(x) for x in self.__dict__.items()])
    @abstractmethod
    def __str__(self):
        pass
    @abstractmethod
    def __repr__(self):
        pass
    @abstractmethod
    def __eq__(self, other):
        pass
    @abstractmethod
    def __ne__(self, other):
        pass
    @abstractmethod
    def __copy__(self):
        pass

