class Config(object):
    def __init__(self):
        self._config = {}
        self._http = HttpConfig()
        legacy_config_value = get_env('analytics', 'enabled', default=False)
        self.analytics_enabled = asbool(
            get_env('trace', 'analytics_enabled', default=legacy_config_value)
        )
        self.service = get_env("service")
        self.env = get_env("env")
        self.version = get_env("version")
        self.logs_injection = asbool(get_env("logs", "injection", default=False))
        self.report_hostname = asbool(
            get_env('trace', 'report_hostname', default=False)
        )
        self.health_metrics_enabled = asbool(
            get_env('trace', 'health_metrics_enabled', default=False)
        )
    def __getattr__(self, name):
        if name not in self._config:
            self._config[name] = IntegrationConfig(self, name)
        return self._config[name]
    def get_from(self, obj):
        pin = Pin.get_from(obj)
        if pin is None:
            log.debug('No configuration found for %s', obj)
            return {}
        return pin._config
    def _add(self, integration, settings, merge=True):
        existing = getattr(self, integration)
        settings = deepcopy(settings)
        if merge:
            self._config[integration] = IntegrationConfig(self, integration, _deepmerge(existing, settings))
        else:
            self._config[integration] = IntegrationConfig(self, integration, settings)
    def trace_headers(self, whitelist):
        self._http.trace_headers(whitelist)
        return self
    def header_is_traced(self, header_name):
        return self._http.header_is_traced(header_name)
    def _get_service(self, default=None):
        return self.service if self.service is not None else get_service_legacy(default=default)
    def __repr__(self):
        cls = self.__class__
        integrations = ', '.join(self._config.keys())
        return '{}.{}({})'.format(cls.__module__, cls.__name__, integrations)

class DetectorB(object):
    @abc.abstractmethod
    def __init__(self, contamination=0.1, window = 75):
        if not (0. < contamination <= 0.55):
            raise ValueError("contamination must be in (0, 0.55], "
                             "got: %f" % contamination)
        self.contamination = contamination
    @abc.abstractmethod
    def fit(self, X, y=None):
        pass
    @abc.abstractmethod
    def decision_function(self, X):
        pass
    def predict(self, X):
        check_is_fitted(self, ['decision_scores_', 'threshold_', 'labels_'])
        pred_score = self.decision_function(X)
        return (pred_score > self.threshold_).astype('int').ravel()
    def predict_proba(self, method='linear'):
        check_is_fitted(self, ['decision_scores_', 'threshold_', 'labels_'])
        train_scores = self.train_decision_scores_
        test_scores = self.decision_scores_
        probs = np.zeros([self.n_train_, int(self._classes)])
        if method == 'linear':
            scaler = MinMaxScaler().fit(train_scores.reshape(-1, 1))
            probs[:, 1] = scaler.transform(
                test_scores.reshape(-1, 1)).ravel().clip(0, 1)
            probs[:, 0] = 1 - probs[:, 1]
            return probs
        elif method == 'unify':
            pre_erf_score = (test_scores - self._mu) / (
                    self._sigma * np.sqrt(2))
            erf_score = erf(pre_erf_score)
            probs[:, 1] = erf_score.clip(0, 1).ravel()
            probs[:, 0] = 1 - probs[:, 1]
            return probs
        else:
            raise ValueError(method,
                             'is not a valid probability conversion method')
    def _predict_rank(self, normalized=False):
        check_is_fitted(self, ['decision_scores_'])
        train_scores = self.train_decision_scores_
        test_scores = self.decision_scores_
        sorted_train_scores = np.sort(train_scores)
        ranks = np.searchsorted(sorted_train_scores, test_scores)
        if normalized:
            ranks = ranks / ranks.max()
        return ranks
    def _set_n_classes(self, y):
        self._classes = 2  
        if y is not None:
            check_classification_targets(y)
            self._classes = len(np.unique(y))
            warnings.warn(
                "y should not be presented in unsupervised learning.")
        return self
    def _process_decision_scores(self):
        self.threshold_ = percentile(self.decision_scores_,
                                     100 * (1 - self.contamination))
        self.labels_ = (self.decision_scores_ > self.threshold_).astype(
            'int').ravel()
        self._mu = np.mean(self.decision_scores_)
        self._sigma = np.std(self.decision_scores_)
        return self
    def _set_threshold(self, X_train):
        self.fit(X_train)
        self.train_decision_scores_ = self.decision_scores_
        self.threshold_ = percentile(self.decision_scores_,
                                     100 * (1 - self.contamination))
        self.labels_ = (self.decision_scores_ > self.threshold_).astype(
            'int').ravel()
        self._mu = np.mean(self.decision_scores_)
        self._sigma = np.std(self.decision_scores_)
        return self
    def _get_param_names(cls):
        init = getattr(cls.__init__, 'deprecated_original', cls.__init__)
        if init is object.__init__:
            return []
        init_signature = signature(init)
        parameters = [p for p in init_signature.parameters.values()
                      if p.name != 'self' and p.kind != p.VAR_KEYWORD]
        for p in parameters:
            if p.kind == p.VAR_POSITIONAL:
                raise RuntimeError("scikit-learn estimators should always "
                                   "specify their parameters in the signature"
                                   " of their __init__ (no varargs)."
                                   " %s with constructor %s doesn't "
                                   " follow this convention."
                                   % (cls, init_signature))
        return sorted([p.name for p in parameters])
    def get_params(self, deep=True):
        out = dict()
        for key in self._get_param_names():
            warnings.simplefilter("always", DeprecationWarning)
            try:
                with warnings.catch_warnings(record=True) as w:
                    value = getattr(self, key, None)
                if len(w) and w[0].category == DeprecationWarning:
                    continue
            finally:
                warnings.filters.pop(0)
            if deep and hasattr(value, 'get_params'):
                deep_items = value.get_params().items()
                out.update((key + '__' + k, val) for k, val in deep_items)
            out[key] = value
        return out
    def set_params(self, **params):
        if not params:
            return self
        valid_params = self.get_params(deep=True)
        nested_params = defaultdict(dict)  
        for key, value in params.items():
            key, delim, sub_key = key.partition('__')
            if key not in valid_params:
                raise ValueError('Invalid parameter %s for estimator %s. '
                                 'Check the list of available parameters '
                                 'with `estimator.get_params().keys()`.' %
                                 (key, self))
            if delim:
                nested_params[key][sub_key] = value
            else:
                setattr(self, key, value)
        for key, sub_params in nested_params.items():
            valid_params[key].set_params(**sub_params)
        return self
    def __repr__(self):
        class_name = self.__class__.__name__
        return '%s(%s)' % (class_name, _pprint(self.get_params(deep=False),
                                               offset=len(class_name), ),)

