class Order(object):
    __slots__ = ['timestamp', 'quantity', 'indicator', 'price']
    def __init__(self, quantity, indicator, price, timestamp=None):
        self.quantity = quantity
        self.indicator = self._check_indicator(indicator)
        self.price = price
        self.timestamp = self._process_timestamp(timestamp)
    def __eq__(self, other):
        return self.timestamp == other.timestamp
    def __lt__(self, other):
        return self.timestamp < other.timestamp
    def __mul__(self, other):
        if isinstance(other, Order):
            return self.price * other.price
        else:
            return self.price * other
    __rmul__ = __mul__
    def _check_indicator(self, indicator):
        if indicator not in ['buy', 'sell']:
            raise OrderException("Indicator value is invalid")
        return indicator
    def _process_timestamp(self, timestamp):
        if timestamp is None:
            timestamp = time.time()
        else:
            if isinstance(timestamp, str):
                timestamp = time.mktime(convert_timestamp(timestamp))
        return timestamp

class Utm(UtmUpsBase):
    _band        = NN    
    _Error       = UTMError  
    _latlon_args = ()    
    _scale       = None  
    _scale0      = _K0   
    _zone        = 0     
    def __init__(self, zone, hemisphere, easting, northing, band=NN,  
                             datum=Datums.WGS84, falsed=True,
                             convergence=None, scale=None, name=NN):
        if name:
            self.name = name
        self._zone, B, _ = _to3zBlat(zone, band)
        h = str(hemisphere)[:1].upper()
        if h not in _NS_:
            raise self._Error(hemisphere=hemisphere)
        e, n = easting, northing  
        self._hemisphere = h
        UtmUpsBase.__init__(self, e, n, band=B, datum=datum, falsed=falsed,
                                        convergence=convergence, scale=scale)
    def __eq__(self, other):
        return isinstance(other, Utm) and other.zone       == self.zone \
                                      and other.hemisphere == self.hemisphere \
                                      and other.easting    == self.easting \
                                      and other.northing   == self.northing \
                                      and other.band       == self.band \
                                      and other.datum      == self.datum
    def __repr__(self):
        return self.toRepr(B=True)
    def __str__(self):
        return self.toStr()
    def _xcopy2(self, Xtm):
        return Xtm(self.zone, self.hemisphere,
                   self.easting, self.northing,
                   band=self.band, datum=self.datum,
                   falsed=self.falsed, scale=self.scale,
                   convergence=self.convergence)
    @property_RO
    def band(self):
        return self._band
    @property_RO
    def falsed2(self):
        e = n = 0
        if self.falsed:
            e = _FalseEasting  
            if self.hemisphere == _S_:  
                n = _FalseNorthing
        return EasNor2Tuple(e, n)
    def parse(self, strUTM, name=NN):
        return parseUTM5(strUTM, datum=self.datum, Utm=self.classof,
                                 name=name or self.name)
    def parseUTM(self, strUTM):
        return self.parse(strUTM)
    @property_RO
    def pole(self):
        return NN  
    def toEtm(self):
        from pygeodesy.etm import Etm  
        return self._xnamed(self._xcopy2(Etm))
    def toLatLon(self, LatLon=None, eps=EPS, unfalse=True, **LatLon_kwds):
        if eps < EPS:
            eps = EPS  
        if self._latlon and self._latlon_args == (eps, unfalse):
            return self._latlon5(LatLon)
        E = self.datum.ellipsoid  
        x, y = self.eastingnorthing2(falsed=not unfalse)
        A0 = self.scale0 * E.A
        if A0 < EPS:
            raise self._Error(meridional=A0)
        x /= A0  
        y /= A0  
        K = _Kseries(E.BetaKs, x, y)  
        y = neg(K.ys(-y))  
        x = neg(K.xs(-x))  
        shx = sinh(x)
        sy, cy = sincos2(y)
        H = hypot(shx, cy)
        if H < EPS:
            raise self._Error(H=H)
        T = t0 = sy / H  
        S = Fsum(T)
        q = _1_0 / E.e12
        P =  7  
        d = _1_0 + eps
        while abs(d) > eps and P > 0:
            p = -d  
            h = hypot1(T)
            s = sinh(E.e * atanh(E.e * T / h))
            t = T * hypot1(s) - s * h
            d = (t0 - t) / hypot1(t) * ((q + T**2) / h)
            T, d = S.fsum2_(d)  
            if d == p:  
                P -= 1
        a = atan(T)  
        b = atan2(shx, cy)
        if unfalse and self.falsed:
            b += radians(_cmlon(self.zone))
        ll = _LLEB(degrees90(a), degrees180(b), datum=self.datum, name=self.name)
        p = neg(K.ps(-1))
        q =     K.qs(0)
        ll._convergence = degrees(atan(tan(y) * tanh(x)) + atan2(q, p))
        ll._scale = E.e2s(sin(a)) * hypot1(T) * H * (A0 / E.a / hypot(p, q))
        self._latlon_to(ll, eps, unfalse)
        return self._latlon5(LatLon, **LatLon_kwds)
    def _latlon_to(self, ll, eps, unfalse):
        self._latlon, self._latlon_args = ll, (eps, unfalse)
    def toMgrs(self):
        if self._mgrs is None:
            from pygeodesy.mgrs import toMgrs  
            self._mgrs = toMgrs(self, name=self.name)
        return self._mgrs
    def toRepr(self, prec=0, fmt=Fmt.SQUARE, sep=_COMMASPACE_, B=False, cs=False, **unused):  
        return self._toRepr(fmt, B, cs, prec, sep)
    toStr2 = toRepr  
    def toStr(self, prec=0, sep=_SPACE_, B=False, cs=False):  
        return self._toStr(self.hemisphere, B, cs, prec, sep)
    def toUps(self, pole=NN, eps=EPS, falsed=True, **unused):
        u = self._ups
        if u is None or u.pole != (pole or u.pole) or falsed != bool(u.falsed):
            from pygeodesy.ups import toUps8, Ups  
            ll = self.toLatLon(LatLon=_LLEB, eps=eps, unfalse=True)
            self._ups = u = toUps8(ll, Ups=Ups, falsed=falsed, pole=pole, strict=False)
        return u
    def toUtm(self, zone, eps=EPS, falsed=True, **unused):
        if zone == self.zone and falsed == self.falsed:
            return self.copy()
        elif zone:
            u = self._utm
            if u is None or u.zone != zone or falsed != u.falsed:
                ll = self.toLatLon(LatLon=_LLEB, eps=eps, unfalse=True)
                self._utm = u = toUtm8(ll, Utm=self.classof, falsed=falsed,
                                           name=self.name, zone=zone)
            return u
        raise self._Error(zone=zone)
    @property_RO
    def zone(self):
        return self._zone

class Node:
    IDS = 0
    def __init__(self, name: str, **attributes):
        assert isinstance(
            name, str), f"Node name must be a string, got: {name}"
        self.name = name
        self.id = Node.IDS
        Node.IDS += 1
        self.parent: Optional['Node'] = None
        self.attributes: Dict[str, Any] = attributes
        self._children: List['Node'] = []
        self.metadata: Optional[Dict[str, Any]] = None
    @property
    def head(self) -> Optional['Node']:
        return self._children[0] if self._children else None
    @property
    def tail(self) -> List['Node']:
        return self._children[1:]
    @property
    def children(self) -> List['Node']:
        return self._children
    @property
    def count(self) -> int:
        return len(self._children)
    @property
    def root(self) -> Optional['Node']:
        root = None
        parent = self.parent
        while parent:
            root = parent
            parent = parent.parent
        return root
    @property
    def isTree(self) -> bool:
        return not self.parent
    @property
    def isEmpty(self) -> bool:
        return self.isLeaf and not self.hasAttributes
    @property
    def isSubtree(self) -> bool:
        return bool(self.parent)
    @property
    def previousSibling(self) -> Optional['Node']:
        if not self.parent:
            return None
        siblings = self.parent.children
        i = siblings.index(self)
        return siblings[i - 1] if i > 0 else None
    @property
    def nextSibling(self) -> Optional['Node']:
        if not self.parent:
            return None
        siblings = self.parent.children
        i = siblings.index(self)
        return siblings[i + 1] if i + 1 < len(siblings) else None
    @property
    def firstChild(self) -> Optional['Node']:
        return self._children[0] if self._children else None
    @property
    def lastChild(self) -> Optional['Node']:
        return self._children[-1] if self._children else None
    @property
    def isLeaf(self) -> bool:
        return len(self._children) == 0
    @property
    def isNode(self) -> bool:
        return len(self._children) > 0
    @property
    def hasAttributes(self) -> bool:
        return len(self.attributes) > 0
    def hasAttribute(self, name: str) -> bool:
        return name in self.attributes
    def setAttribute(self, name, value=None):
        self.attributes[name] = value
        return self
    def removeAttribute(self, name):
        del self.attributes[name]
        return self
    def updateAttributes(self, attributes):
        self.attributes.update(attributes)
        return self
    def copy(self, depth=-1):
        node = Node(self.name)
        self.attributes = type(self.attributes)((k, v)
                                                for k, v in self.attributes.items())
        if depth != 0:
            for child in self._children:
                node.append(child.copy(depth - 1))
        return node
    def index(self, node=None) -> Optional[int]:
        if not node:
            return self.parent.index(self) if self.parent else None
        else:
            return self._children.index(node)
    def detach(self) -> 'Node':
        if self.parent:
            self.parent.remove(self)
        return self
    def wrap(self, node: "Node") -> 'Node':
        parent = self.parent
        if parent:
            i = parent.index(self)
            parent.set(i, node)
        node.append(self)
        return self
    def absorb(self, node: "Node") -> 'Node':
        node.detach()
        self.merge(node)
        return self
    def merge(self, node: 'Node', attributes=True, replace=False) -> 'Node':
        children = [_ for _ in node._children]
        if attributes:
            for k, v in node.attributes.items():
                if replace or k not in self.attributes:
                    self.attributes[k] = v
        for c in children:
            self.add(c.detach())
        return self
    def add(self, node: 'Node') -> 'Node':
        assert isinstance(node, Node), f"Expected a Node, got: {node}"
        assert not node.parent, "Cannot add node to {0}, it already has a parent: {1}".format(
            self, node)
        node.parent = self
        self._children.append(node)
        return node
    def set(self, index, node: 'Node') -> 'Node':
        assert isinstance(node, Node), f"Expected a Node, got: {node}"
        assert not node.parent, "Cannot set node to {0}, it already has a parent: {1}".format(
            self, node)
        n = len(self._children)
        if n == 0:
            return self.add(node)
        else:
            i = min(max(0, n + index if index < 0 else index), n - 1)
            previous = self._children[i]
            self._children[i] = node
            previous.parent = None
            node.parent = self
            return node
    def setChildren(self, children: Iterable['Node']):
        if self.children:
            for child in self.children:
                child.parent = None
            self._children = []
        for child in children:
            self.append(child)
        return self
    def append(self, node: 'Node') -> 'Node':
        return self.add(node)
    def extend(self, nodes: List['Node']) -> 'Node':
        for node in nodes:
            self.add(node.detach())
        return self
    def remove(self, node: 'Node') -> 'Node':
        assert node.parent is self, "Cannot remove node from {0}, it has a different parent: {1}".format(
            self, node.parent)
        node.parent = None
        self._children.remove(node)
        return node
    def insert(self, index: int, node: 'Node') -> 'Node':
        index = index if index >= 0 else len(self._children) + index
        assert index >= 0 and index <= len(
            self._children), "Index out of bounds {0} in: {1}".format(index, self)
        assert not node.parent, "Cannot add node to {0}, it already has a parent: {1}".format(
            self, node)
        node.parent = self
        if index == len(self._children):
            self._children.append(node)
        else:
            self._children.insert(index, node)
        return node
    def replaceWith(self, nodes: Union['Node', List['Node']]):
        nodes = [nodes] if isinstance(nodes, Node) else nodes
        index = self.index()
        if index is None:
            assert self.parent
            for child in self.children:
                self.parent.append(child)
        else:
            for i in range(len(nodes) - 1, -1, -1):
                if self.parent:
                    self.parent.insert(index, nodes[i])
        self.detach()
        return self
    def walk(self, functor=None, processor=None) -> List[Any]:
        p = processor or (lambda _: _)
        return list(p(_) for _ in self.iterWalk(functor))
    def iterWalk(self, functor=None):
        if (not functor) or functor(self) is not False:
            yield self
            for c in self._children:
                yield from c.iterWalk(functor)
    def toPrimitive(self):
        res = {"id": self.id}
        if self.name:
            res["name"] = self.name
        if self.parent:
            res["parent"] = self.parent.id
        if self.attributes:
            res["attributes"] = self.attributes
        if self.metadata:
            res["metadata"] = self.metadata
        if self._children:
            res["children"] = [_._asdict() for _ in self._children]
        return res
    def iterXML(self) -> Iterable[str]:
        stop = False
        if self.name == "text":
            if "value" in self.attributes and len(self.attributes) == 1:
                yield str(self.attributes["value"])
                stop = True
            elif not self.attributes:
                yield ""
                stop = True
        if not stop:
            attributes = " ".join(
                f"{k}={json.dumps(v) if isinstance(v,str) else json.dumps(json.dumps(v))}" for k, v in self.attributes.items())
            prefix = f"{self.name}{' ' if attributes else ''}{attributes}"
            if not self._children:
                yield f"<{prefix} />"
            else:
                yield f"<{prefix}>"
                for child in self._children:
                    yield from child.iterXML()
                yield f"</{self.name}>"
    def toXML(self) -> str:
        return "".join(self.iterXML())
    def iterTDoc(self, level=0) -> Iterable[str]:
        attributes = " ".join(f"{k}={repr(v)}" for k,
                              v in self.attributes.items())
        yield f"{self.name or '┐'} {attributes}"
        last_i = len(self.children) - 1
        for i, child in enumerate(self.children):
            for j, line in enumerate(child.iterTDoc(level + 1)):
                leader = ("└─ " if i == last_i else "├─ ") if j == 0 else (
                    "   " if i == last_i else "│  ")
                yield leader + line
    def toTDoc(self) -> str:
        return "\n".join(self.iterTDoc())
    def __getitem__(self, index: Union[int, str]):
        if isinstance(index, str):
            if index not in self.attributes:
                raise IndexError(f"Node has no attribute '{index}': {self}")
            else:
                return self.attributes[index]
        else:
            return self._children[index]
    def __contains__(self, value: Union[int, str, 'Node']) -> bool:
        if isinstance(value, int):
            return value >= 0 and value < self.count
        elif isinstance(value, Node):
            return value in self._children
        elif isinstance(value, str):
            return value in self.attributes
        else:
            return False
    def __repr__(self):
        return f"<Node:{self.name} {' '.join(str(k)+'='+repr(v) for k,v in self.attributes.items())}{' …' + str(len(self.children)) if self._children else ''}>"

class User(db.Model):
    __tablename__ = 'users'
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(32), nullable=False, unique=True)
    email = db.Column(db.String(32), unique=True, nullable=False)
    subscriptions = db.relationship('Subscription',
                                    secondary=user_subscription,
                                    lazy='dynamic')
    password_hash = db.Column(db.String(256))
    avatar_hash = db.Column(db.String(32))
    login_count = db.Column(db.Integer, default=0)
    member_since = db.Column(db.Integer, default=timestamp)
    last_seen = db.Column(db.Integer, default=timestamp, onupdate=timestamp)
    confirmed = db.Column(db.Boolean, default=False)
    videos = db.relationship('UserVideo', back_populates='user', lazy='dynamic')
    def add_video(self, video, fetcher):
        uv = UserVideo()
        uv.video = video
        subscription = fetcher.subscription
        uv.subscription = subscription
        self.videos.append(uv)
        fetcher.videos.append(video)
        db.session.add_all([self, subscription])
    @staticmethod
    def create(data):
        user = User()
        user.from_dict(data, partial_update=False)
        user.avatar_hash = hashlib.md5(user.email.encode('utf-8')).hexdigest()
        return user
    @property
    def password(self):
        raise AttributeError('password is not a readable attribute')
    @password.setter
    def password(self, password):
        self.password_hash = generate_password_hash(password)
    def verify_password(self, password):
        return check_password_hash(self.password_hash, password)
    def generate_auth_token(self, expiration=600):
        s = Serializer(current_app.config['SECRET_KEY'], expires_in=expiration)
        return s.dumps({'id': self.id}).decode()
    @staticmethod
    def verify_auth_token(token):
        s = Serializer(current_app.config["SECRET_KEY"])
        try:
            data = s.loads(token)
        except (SignatureExpired, BadSignature):
            return None
        user = User.query.get(data['id'])
        return user
    def generate_confirmation_token(self, expiration=3600):
        s = Serializer(current_app.config["SECRET_KEY"], expiration)
        return s.dumps({'confirm': self.id})
    @staticmethod
    def confirm(token):
        token = token.encode()
        s = Serializer(current_app.config['SECRET_KEY'])
        try:
            data = s.loads(token)
        except:
            return False
        user_id = data['confirm']
        return user_id
    def ping(self):
        self.last_seen = timestamp()
        self.login_count += 1
        db.session.add(self)
    def gravatar(self, size=100, default='identicon', rating='g'):
        url = 'https://secure.gravatar.com/avatar'
        if self.avatar_hash:
            _hash = self.avatar_hash
        else:
            _hash = hashlib.md5(self.email.encode('utf-8')).hexdigest()
        return '{url}/{hash}?s={size}&d={default}&r={rating}'.format(
            url=url, hash=_hash, size=size, default=default, rating=rating
        )
    def from_dict(self, data, partial_update=True):
        for field in ['email', 'password', 'username']:
            try:
                setattr(self, field, data[field])
            except KeyError:
                if not partial_update:
                    abort(400)
    def to_dict(self):
        return {
            'id': self.id,
            'email': self.email,
            'username': self.username,
            'member_since': str(self.member_since),
            'last_seen': str(self.last_seen),
            'subscriptions': url_for('subscribeapi', _external=True, username=self.username),
            'url': url_for('userapi', _external=True, username=self.username),
        }
    def user_subs_videos(self, subs):
        user_videos = self.videos.filter_by(subscription=subs).all()
        if not user_videos:
            return
        d = {
            'download': [],
            'play': []
        }
        for uv in user_videos:
            if uv.video.fetcher.address_type == 'downloadable':
                d['download'].append(uv.video_to_dict())
            else:
                d['play'].append(uv.video_to_dict())
        return d
    def __repr__(self):
        return "<User(email='%s')>" % self.email

class Subscription(db.Model):
    __tablename__ = 'subscriptions'
    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(128), unique=True)
    user_count = db.Column(db.Integer)
    ended = db.Column(db.Boolean, default=False)
    users = db.relationship('User', secondary=user_subscription, lazy='dynamic')
    movie_id = db.Column(db.Integer, db.ForeignKey('movies.id'))
    create_at = db.Column(db.Integer, default=timestamp)
    fetchers = db.relationship('Fetcher', lazy='dynamic', backref='subscription')
    def add_one_user(self):
        if self.user_count is None:
            self.user_count = 0
        self.user_count += 1
    def is_ended(self):
        if self.ended:
            return
        is_ended_ = list(filter(lambda s: s.ended, self.fetchers))
        if is_ended_:
            self.ended = True
    @property
    def _timestamp(self):
        pass
    @_timestamp.getter
    def _timestamp(self):
        return datetime.fromtimestamp(self.create_at)
    def to_dict(self, username=None, include_poster=False, include_title=False):
        subs = {
            'id': self.id,
            'title': self.movie.title,
            'synopsis': self.movie.synopsis,
            'user_count': self.user_count,
            'create_at': str(self._timestamp),
            'episode_aired': self.movie.episode_aired,
            'episode_count': self.movie.episode_count,
            'refes': {r.second_level_domain: r.url for r in self.movie.refes}
        }
        if not include_poster and not include_title:
            return subs
        poster_path = self.movie.poster_path
        if poster_path.startswith('http'):
            poster = poster_path
        else:
            try:
                name = os.path.basename(self.movie.poster_path)
            except TypeError:
                poster = None
            else:
                poster = url_for('static', _external=True, filename='posters/'+name)
        subs.update({'poster': poster, 'title': self.movie.title})
        if username is None:
            return subs
        subs.update({
            'videos': url_for(
                'videosapi', _external=True, username=username, subs_id=self.id)})
        return subs
    def url(self, user):
        if self.users.filter_by(email=user.email).first():
            return url_for('subscriptionapi',
                           _external=True,
                           username=user.username,
                           sub_id=self.id)
    def __repr__(self):
        if self.movie:
            return "<Subscription(title='{}')>".format(self.movie.title)
        else:
            return "<Subscription(id='{}')>".format(self.id)

class Fetcher(db.Model):
    __tablename__ = 'fetchers'
    id = db.Column(db.Integer, primary_key=True)
    url = db.Column(db.String(128))
    ended = db.Column(db.Boolean, default=False)
    subscription_id = db.Column(db.Integer, db.ForeignKey('subscriptions.id'))
    address_type = db.Column(db.String(32))
    fetch_records = db.relationship('FetchRecord', backref='fetcher')
    videos = db.relationship('Video', lazy='dynamic', backref='fetcher')
    current_schedule = db.Column(db.PickleType)
    adjusted_schedule = db.Column(db.Boolean, default=False)
    @property
    def schedule(self):
        pass
    @schedule.setter
    def schedule(self, _schedule):
        self.current_schedule = pickle.dumps(_schedule)
    @schedule.getter
    def schedule(self):
        return pickle.loads(self.current_schedule)
    @classmethod
    def create(cls, url):
        f = cls()
        f.url = url
        f.schedule = init_schedule()
        return f
    def is_ended(self):
        if self.ended:
            return True
        if self.videos.count() >= self.subscription.movie.episode_count:
            self.ended = True
            return True
    def should_adjust(self):
        if self.fetch_records.count() >= 21 and not self.adjusted_schedule:
            schedule = self.estimated_update_cycle()
            return schedule
    def fetch_record_stats(self):
        d = dict()
        fetch_records = self.fetch_records
        for fr in fetch_records:
            _weekday = fr.weekday
            if _weekday not in d:
                d[_weekday] = 0
            if fr.updated:
                d[_weekday] += 1
        return d
    def estimated_update_cycle(self):
        stats = self.fetch_record_stats()
        weekdays = set()
        for _weekday, count in stats.items():
            if count != 0:
                weekdays.add(_weekday)
        self.schedule = crontab(hour=0, day_of_week=weekdays)
        self.adjusted_schedule = True
        return self.schedule
    def postponed_update(self):
        _weekday = self.schedule.day_of_week
        new_weekdays = set()
        for wd in _weekday:
            new_weekdays.add(wd)
            _wd = wd + 1
            if _wd < 7:
                new_weekdays.add(_wd)
            else:
                new_weekdays.add(0)
        self.schedule = crontab(hour=0, day_of_week=new_weekdays)
        return self.schedule
    def __repr__(self):
        return '<Fetcher(url={})>'.format(self.url)

