class CachedOperation(Operation):
    logdir: pathlib.Path = pathlib.Path.home() / "robustnessgym/cachedops/"
    logdir.mkdir(parents=True, exist_ok=True)
    def __init__(
        self, apply_fn: Callable = None, identifier: Identifier = None, *args, **kwargs
    ):
        super(CachedOperation, self).__init__(
            apply_fn=apply_fn,
            identifiers=[identifier] if identifier else None,
            num_outputs=1,
            *args,
            **kwargs,
        )
    def __repr__(self):
        return str(self.identifier)
    @property
    def identifier(self):
        return self.identifiers[0]
    @staticmethod
    def store(batch: Batch, updates: List[Dict]) -> Batch:
        if "cache" not in batch:
            batch["cache"] = [{} for _ in range(len(batch["index"]))]
        batch["cache"] = [
            recmerge(cache_dict, update_dict)
            for cache_dict, update_dict in zip(batch["cache"], updates)
        ]
        return batch
    @class_or_instancemethod
    def retrieve(
        self_or_cls,
        batch: Batch,
        columns: Union[List[str], List[List[str]]],
        proc_fns: Union[str, Callable, List[Union[str, Callable]]] = None,
        identifier: Union[str, Identifier] = None,
        reapply: bool = False,
        **kwargs,
    ) -> Optional[Union[Batch, List[Batch]]]:
        if not reapply:
            if "cache" not in batch:
                raise ValueError(
                    "`cache` key missing: nothing has been cached yet. "
                    "Are you sure you ran a CachedOperation?"
                )
            if not identifier:
                if isinstance(self_or_cls, type):
                    target_ident_key = self_or_cls.__name__
                else:
                    target_ident_key = str(self_or_cls.identifier)
                best_match, best_distance = None, 100000000
                for ident_key in batch["cache"][0].keys():
                    if (
                        ident_key.startswith(target_ident_key)
                        and len(ident_key.replace(target_ident_key, "")) < best_distance
                    ):
                        best_match = ident_key
                        best_distance = len(ident_key.replace(target_ident_key, ""))
                identifier = best_match
                if not identifier:
                    raise ValueError(
                        f"Retrieval failed: couldn't find a key called "
                        f"{target_ident_key} in cache."
                    )
            try:
                if isinstance(columns[0], str):
                    retrieval = {
                        strings_as_json(columns): [
                            self_or_cls.decode(
                                cache[str(identifier)][strings_as_json(columns)]
                            )
                            for cache in batch["cache"]
                        ]
                    }
                else:
                    retrieval = {
                        strings_as_json(cols_): [
                            self_or_cls.decode(
                                cache[str(identifier)][strings_as_json(cols_)]
                            )
                            for cache in batch["cache"]
                        ]
                        for cols_ in columns
                    }
            except KeyError:
                raise KeyError(
                    "Could not retrieve information for all columns. "
                    "If you're trying to retrieve information for multiple columns, "
                    "use columns=[[col_1], [col_2], ..] "
                    "instead of columns=[col_1, col_2, ..]."
                )
            if not proc_fns:
                return retrieval
            if isinstance(proc_fns, str):
                proc_fns = getattr(self_or_cls, proc_fns)
            elif isinstance(proc_fns, List):
                proc_fns = [
                    proc_fn
                    if isinstance(proc_fn, Callable)
                    else getattr(self_or_cls, proc_fn)
                    for proc_fn in proc_fns
                ]
            if isinstance(proc_fns, Callable):
                return {k: proc_fns(v) for k, v in retrieval.items()}
            return [
                {k: proc_fn(v) for k, v in retrieval.items()} for proc_fn in proc_fns
            ]
        else:
            if proc_fns:
                print("Warning: proc_fns has no effect when reapply=True.")
            if isinstance(columns[0], str):
                return {
                    strings_as_json(columns): self_or_cls(**kwargs).apply(
                        batch=batch, columns=columns
                    )
                    if isinstance(self_or_cls, type)
                    else self_or_cls.apply(batch=batch, columns=columns)
                }
            return {
                strings_as_json(cols_): self_or_cls(**kwargs).apply(
                    batch=batch, columns=cols_
                )
                if isinstance(self_or_cls, type)
                else self_or_cls.apply(batch=batch, columns=cols_)
                for cols_ in columns
            }
    def get_cache_hash(self, columns: Optional[List[str]] = None):
        val = hash(self)
        if columns:
            for key in columns:
                val ^= persistent_hash(key)
        return val
    def get_cache_file_name(self, columns=None):
        return "cache-" + str(abs(self.get_cache_hash(columns=columns))) + ".arrow"
    def prepare_batch(self, batch: Batch, columns: List[str]) -> Batch:
        return batch
    def prepare_dataset(
        self, dataset: Dataset, columns: List[str], batch_size: int = 32
    ) -> Dataset:
        try:
            return dataset.map(
                partial(self.prepare_batch, columns=columns),
                batched=True,
                batch_size=batch_size,
                cache_file_name=str(
                    dataset.logdir
                    / (
                        "cache-"
                        + str(
                            abs(
                                persistent_hash(str(dataset.identifier))
                                ^ dataset.hash_interactions()
                                ^ persistent_hash(
                                    str(self.identifier) + str(strings_as_json(columns))
                                )
                            )
                        )
                        + "-prep.arrow"
                    )
                ),
            )
        except:  
            all_batches = [
                self.prepare_batch(
                    batch=batch,
                    columns=columns,
                )
                for batch in dataset.batch(batch_size)
            ]
            return dataset.map(
                lambda examples, indices: all_batches[indices[0] // batch_size],
                batched=True,
                batch_size=batch_size,
                with_indices=True,
                load_from_cache_file=False,
                cache_file_name=str(
                    dataset.logdir
                    / (
                        "cache-"
                        + str(
                            abs(
                                persistent_hash(str(dataset.identifier))
                                ^ dataset.hash_interactions()
                                ^ persistent_hash(
                                    str(self.identifier) + str(strings_as_json(columns))
                                )
                            )
                        )
                        + "-prep.arrow"
                    )
                ),
            )
    def apply(self, batch: Batch, columns: List[str], *args, **kwargs) -> List:
        pass
    def process_batch(self, batch: Batch, columns: List[str]) -> Batch:
        assert (
            len(set(columns) - set(batch.keys())) == 0
        ), "Any column in 'columns' must be present in 'batch'."
        encoded_outputs = [
            self.encode(example_output)
            for example_output in self.apply(batch=batch, columns=columns)
        ]
        updates = self.construct_updates(
            encoded_outputs=encoded_outputs, columns=columns
        )
        return self.store(batch=batch, updates=updates)
    def process_dataset(
        self,
        dataset: Dataset,
        columns: List[str],
        batch_size: int = 32,
    ) -> Dataset:
        dataset = self.prepare_dataset(
            dataset=dataset,
            columns=columns,
            batch_size=batch_size,
        )
        try:
            return dataset.map(
                partial(self.process_batch, columns=columns),
                batched=True,
                batch_size=batch_size,
                cache_file_name=str(
                    dataset.logdir
                    / (
                        "cache-"
                        + str(
                            abs(
                                persistent_hash(str(dataset.identifier))
                                ^ dataset.hash_interactions()
                                ^ persistent_hash(
                                    str(self.identifier) + str(strings_as_json(columns))
                                )
                            )
                        )
                        + ".arrow"
                    )
                ),
            )
        except:  
            all_batches = [
                self.process_batch(
                    batch=batch,
                    columns=columns,
                )
                for batch in dataset.batch(batch_size)
            ]
            return dataset.map(
                lambda examples, indices: all_batches[indices[0] // batch_size],
                batched=True,
                batch_size=batch_size,
                with_indices=True,
                load_from_cache_file=False,
                cache_file_name=str(
                    dataset.logdir
                    / (
                        "cache-"
                        + str(
                            abs(
                                persistent_hash(str(dataset.identifier))
                                ^ dataset.hash_interactions()
                                ^ persistent_hash(
                                    str(self.identifier) + str(strings_as_json(columns))
                                )
                            )
                        )
                        + ".arrow"
                    )
                ),
            )
    def construct_updates(self, encoded_outputs: List[str], columns: List[str]):
        return [
            {str(self.identifier): {strings_as_json(columns): val}}
            for val in encoded_outputs
        ]
    @classmethod
    def available(cls, batch: Batch):
        if "cache" not in batch:
            return False
        return any([key.startswith(cls.__name__) for key in batch["cache"][0].keys()])
    def __call__(
        self, batch_or_dataset: BatchOrDataset, columns: List[str], batch_size: int = 32
    ) -> BatchOrDataset:
        if isinstance(batch_or_dataset, Dataset):
            if batch_or_dataset.check_tape(
                path=[CACHEDOPS],
                identifiers=self.identifier,
                columns=columns,
            ):
                return batch_or_dataset
            dataset = self.process_dataset(
                dataset=batch_or_dataset,
                columns=columns,
                batch_size=batch_size,
            )
            dataset.update_tape(
                path=[CACHEDOPS],
                identifiers=self.identifier,
                columns=columns,
            )
            return dataset
        elif isinstance(batch_or_dataset, Dict):
            return self.process_batch(batch=batch_or_dataset, columns=columns)
        else:
            raise NotImplementedError

class fast_csr_matrix(csr_matrix):
    def __init__(self, args=None, shape=None, dtype=None, copy=False):
        if args is None: 
            if shape is None:
                raise Exception('Shape must be given when building zero matrix.')
            self.data = np.array([], dtype=complex)
            self.indices = np.array([], dtype=np.int32)
            self.indptr = np.zeros(shape[0]+1, dtype=np.int32)
            self._shape = tuple(shape)
        else:
            if args[0].shape[0] and args[0].dtype != complex:
                raise TypeError('fast_csr_matrix allows only complex data.')
            if args[1].shape[0] and args[1].dtype != np.int32:
                raise TypeError('fast_csr_matrix allows only int32 indices.')
            if args[2].shape[0] and args[1].dtype != np.int32:
                raise TypeError('fast_csr_matrix allows only int32 indptr.')
            self.data = np.array(args[0], dtype=complex, copy=copy)
            self.indices = np.array(args[1], dtype=np.int32, copy=copy)
            self.indptr = np.array(args[2], dtype=np.int32, copy=copy)
            if shape is None:
                self._shape = tuple([len(self.indptr)-1]*2)
            else:
                self._shape = tuple(shape)
        self.dtype = complex
        self.maxprint = 50
        self.format = 'csr'
    def _binopt(self, other, op):
        if not isinstance(other, fast_csr_matrix):
            other = csr_matrix(other)
        fn = getattr(_sparsetools, self.format + op + self.format)
        maxnnz = self.nnz + other.nnz
        idx_dtype = get_index_dtype((self.indptr, self.indices,
                                     other.indptr, other.indices),
                                    maxval=maxnnz)
        indptr = np.empty(self.indptr.shape, dtype=idx_dtype)
        indices = np.empty(maxnnz, dtype=idx_dtype)
        bool_ops = ['_ne_', '_lt_', '_gt_', '_le_', '_ge_']
        if op in bool_ops:
            data = np.empty(maxnnz, dtype=np.bool_)
        else:
            data = np.empty(maxnnz, dtype=upcast(self.dtype, other.dtype))
        fn(self.shape[0], self.shape[1],
           np.asarray(self.indptr, dtype=idx_dtype),
           np.asarray(self.indices, dtype=idx_dtype),
           self.data,
           np.asarray(other.indptr, dtype=idx_dtype),
           np.asarray(other.indices, dtype=idx_dtype),
           other.data,
           indptr, indices, data)
        actual_nnz = indptr[-1]
        indices = indices[:actual_nnz]
        data = data[:actual_nnz]
        if actual_nnz < maxnnz // 2:
            indices = indices.copy()
            data = data.copy()
        if isinstance(other, fast_csr_matrix) and (not op in bool_ops):
            A = fast_csr_matrix((data, indices, indptr), dtype=data.dtype, shape=self.shape)
        else:
            A = csr_matrix((data, indices, indptr), dtype=data.dtype, shape=self.shape)
        return A
    def multiply(self, other):
        if isscalarlike(other):
            return self._mul_scalar(other)
        if isspmatrix(other):
            if self.shape == other.shape:
                if not isinstance(other, fast_csr_matrix):
                    other = csr_matrix(other)
                return self._binopt(other, '_elmul_')
            elif other.shape == (1,1):
                return self._mul_scalar(other.toarray()[0, 0])
            elif self.shape == (1,1):
                return other._mul_scalar(self.toarray()[0, 0])
            elif self.shape[1] == other.shape[0] and self.shape[1] == 1:
                return self._mul_sparse_matrix(other.tocsc())
            elif self.shape[0] == other.shape[1] and self.shape[0] == 1:
                return other._mul_sparse_matrix(self.tocsc())
            elif other.shape[0] == 1 and self.shape[1] == other.shape[1]:
                other = dia_matrix((other.toarray().ravel(), [0]),
                                    shape=(other.shape[1], other.shape[1]))
                return self._mul_sparse_matrix(other)
            elif self.shape[0] == 1 and self.shape[1] == other.shape[1]:
                copy = dia_matrix((self.toarray().ravel(), [0]),
                                    shape=(self.shape[1], self.shape[1]))
                return other._mul_sparse_matrix(copy)
            elif other.shape[1] == 1 and self.shape[0] == other.shape[0]:
                other = dia_matrix((other.toarray().ravel(), [0]),
                                    shape=(other.shape[0], other.shape[0]))
                return other._mul_sparse_matrix(self)
            elif self.shape[1] == 1 and self.shape[0] == other.shape[0]:
                copy = dia_matrix((self.toarray().ravel(), [0]),
                                    shape=(self.shape[0], self.shape[0]))
                return copy._mul_sparse_matrix(other)
            else:
                raise ValueError("inconsistent shapes")
        if isdense(other):
            if self.shape == other.shape:
                ret = self.tocoo()
                ret.data = np.multiply(ret.data, other[ret.row, ret.col]
                                       ).view(np.ndarray).ravel()
                return ret
            elif other.size == 1:
                return self._mul_scalar(other.flat[0])
        return np.multiply(self.todense(), other)
    def _mul_sparse_matrix(self, other):
        M, K1 = self.shape
        K2, N = other.shape
        major_axis = self._swap((M,N))[0]
        if isinstance(other, fast_csr_matrix):
            A = zcsr_mult(self, other, sorted=1)
            return A
        other = csr_matrix(other)  
        idx_dtype = get_index_dtype((self.indptr, self.indices,
                                     other.indptr, other.indices),
                                    maxval=M*N)
        indptr = np.empty(major_axis + 1, dtype=idx_dtype)
        fn = getattr(_sparsetools, self.format + '_matmat_pass1')
        fn(M, N,
           np.asarray(self.indptr, dtype=idx_dtype),
           np.asarray(self.indices, dtype=idx_dtype),
           np.asarray(other.indptr, dtype=idx_dtype),
           np.asarray(other.indices, dtype=idx_dtype),
           indptr)
        nnz = indptr[-1]
        idx_dtype = get_index_dtype((self.indptr, self.indices,
                                     other.indptr, other.indices),
                                    maxval=nnz)
        indptr = np.asarray(indptr, dtype=idx_dtype)
        indices = np.empty(nnz, dtype=idx_dtype)
        data = np.empty(nnz, dtype=upcast(self.dtype, other.dtype))
        fn = getattr(_sparsetools, self.format + '_matmat_pass2')
        fn(M, N, np.asarray(self.indptr, dtype=idx_dtype),
           np.asarray(self.indices, dtype=idx_dtype),
           self.data,
           np.asarray(other.indptr, dtype=idx_dtype),
           np.asarray(other.indices, dtype=idx_dtype),
           other.data,
           indptr, indices, data)
        A = csr_matrix((data,indices,indptr),shape=(M,N))
        return A
    def _scalar_binopt(self, other, op):
        self.sum_duplicates()
        res = self._with_data(op(self.data, other), copy=True)
        res.eliminate_zeros()
        return res
    def __eq__(self, other):
        if isscalarlike(other):
            if np.isnan(other):
                return csr_matrix(self.shape, dtype=np.bool_)
            if other == 0:
                warn("Comparing a sparse matrix with 0 using == is inefficient"
                        ", try using != instead.", SparseEfficiencyWarning)
                all_true = _all_true(self.shape)
                inv = self._scalar_binopt(other, operator.ne)
                return all_true - inv
            else:
                return self._scalar_binopt(other, operator.eq)
        elif isdense(other):
            return self.todense() == other
        elif isspmatrix(other):
            warn("Comparing sparse matrices using == is inefficient, try using"
                    " != instead.", SparseEfficiencyWarning)
            if self.shape != other.shape:
                return False
            elif self.format != other.format:
                other = other.asformat(self.format)
            res = self._binopt(other,'_ne_')
            all_true = _all_true(self.shape)
            return all_true - res
        else:
            return False
    def __ne__(self, other):
        if isscalarlike(other):
            if np.isnan(other):
                warn("Comparing a sparse matrix with nan using != is inefficient",
                     SparseEfficiencyWarning)
                all_true = _all_true(self.shape)
                return all_true
            elif other != 0:
                warn("Comparing a sparse matrix with a nonzero scalar using !="
                     " is inefficient, try using == instead.", SparseEfficiencyWarning)
                all_true = _all_true(self.shape)
                inv = self._scalar_binopt(other, operator.eq)
                return all_true - inv
            else:
                return self._scalar_binopt(other, operator.ne)
        elif isdense(other):
            return self.todense() != other
        elif isspmatrix(other):
            if self.shape != other.shape:
                return True
            elif self.format != other.format:
                other = other.asformat(self.format)
            return self._binopt(other,'_ne_')
        else:
            return True
    def _inequality(self, other, op, op_name, bad_scalar_msg):
        if isscalarlike(other):
            if 0 == other and op_name in ('_le_', '_ge_'):
                raise NotImplementedError(" >= and <= don't work with 0.")
            elif op(0, other):
                warn(bad_scalar_msg, SparseEfficiencyWarning)
                other_arr = np.empty(self.shape, dtype=np.result_type(other))
                other_arr.fill(other)
                other_arr = csr_matrix(other_arr)
                return self._binopt(other_arr, op_name)
            else:
                return self._scalar_binopt(other, op)
        elif isdense(other):
            return op(self.todense(), other)
        elif isspmatrix(other):
            if self.shape != other.shape:
                raise ValueError("inconsistent shapes")
            elif self.format != other.format:
                other = other.asformat(self.format)
            if op_name not in ('_ge_', '_le_'):
                return self._binopt(other, op_name)
            warn("Comparing sparse matrices using >= and <= is inefficient, "
                 "using <, >, or !=, instead.", SparseEfficiencyWarning)
            all_true = _all_true(self.shape)
            res = self._binopt(other, '_gt_' if op_name == '_le_' else '_lt_')
            return all_true - res
        else:
            raise ValueError("Operands could not be compared.")
    def _with_data(self,data,copy=True):
        data = np.asarray(data, dtype=complex)
        if copy:
            return fast_csr_matrix((data,self.indices.copy(),self.indptr.copy()),
                                   shape=self.shape,dtype=data.dtype)
        else:
            return fast_csr_matrix((data,self.indices,self.indptr),
                                   shape=self.shape,dtype=data.dtype)
    def transpose(self):
        return zcsr_transpose(self)
    def trans(self):
        return zcsr_transpose(self)
    def getH(self):
        return zcsr_adjoint(self)
    def adjoint(self):
        return zcsr_adjoint(self)

class NestedAggregateNvmfSubsystem(object):
    openapi_types = {
        'count': 'int'
    }
    attribute_map = {
        'count': 'count'
    }
    def __init__(self, **kwargs):  
        self.local_vars_configuration = kwargs.get("local_vars_configuration", Configuration.get_default_copy())
        self._count = None
