class HTTPHeaderDict(MutableMapping):
    def __init__(self, headers=None, **kwargs):
        super(HTTPHeaderDict, self).__init__()
        self._container = OrderedDict()
        if headers is not None:
            if isinstance(headers, HTTPHeaderDict):
                self._copy_from(headers)
            else:
                self.extend(headers)
        if kwargs:
            self.extend(kwargs)
    def __setitem__(self, key, val):
        self._container[key.lower()] = (key, val)
        return self._container[key.lower()]
    def __getitem__(self, key):
        val = self._container[key.lower()]
        return ', '.join(val[1:])
    def __delitem__(self, key):
        del self._container[key.lower()]
    def __contains__(self, key):
        return key.lower() in self._container
    def __eq__(self, other):
        if not isinstance(other, Mapping) and not hasattr(other, 'keys'):
            return False
        if not isinstance(other, type(self)):
            other = type(self)(other)
        return (dict((k.lower(), v) for k, v in self.itermerged()) ==
                dict((k.lower(), v) for k, v in other.itermerged()))
    def __ne__(self, other):
        return not self.__eq__(other)
    if not PY3:  
        iterkeys = MutableMapping.iterkeys
        itervalues = MutableMapping.itervalues
    __marker = object()
    def __len__(self):
        return len(self._container)
    def __iter__(self):
        for vals in self._container.values():
            yield vals[0]
    def pop(self, key, default=__marker):
        try:
            value = self[key]
        except KeyError:
            if default is self.__marker:
                raise
            return default
        else:
            del self[key]
            return value
    def discard(self, key):
        try:
            del self[key]
        except KeyError:
            pass
    def add(self, key, val):
        key_lower = key.lower()
        new_vals = key, val
        vals = self._container.setdefault(key_lower, new_vals)
        if new_vals is not vals:
            if isinstance(vals, list):
                vals.append(val)
            else:
                self._container[key_lower] = [vals[0], vals[1], val]
    def extend(self, *args, **kwargs):
        if len(args) > 1:
            raise TypeError("extend() takes at most 1 positional "
                            "arguments ({0} given)".format(len(args)))
        other = args[0] if len(args) >= 1 else ()
        if isinstance(other, HTTPHeaderDict):
            for key, val in other.iteritems():
                self.add(key, val)
        elif isinstance(other, Mapping):
            for key in other:
                self.add(key, other[key])
        elif hasattr(other, "keys"):
            for key in other.keys():
                self.add(key, other[key])
        else:
            for key, value in other:
                self.add(key, value)
        for key, value in kwargs.items():
            self.add(key, value)
    def getlist(self, key):
        try:
            vals = self._container[key.lower()]
        except KeyError:
            return []
        else:
            if isinstance(vals, tuple):
                return [vals[1]]
            else:
                return vals[1:]
    getheaders = getlist
    getallmatchingheaders = getlist
    iget = getlist
    def __repr__(self):
        return "%s(%s)" % (type(self).__name__, dict(self.itermerged()))
    def _copy_from(self, other):
        for key in other:
            val = other.getlist(key)
            if isinstance(val, list):
                val = list(val)
            self._container[key.lower()] = [key] + val
    def copy(self):
        clone = type(self)()
        clone._copy_from(self)
        return clone
    def iteritems(self):
        for key in self:
            vals = self._container[key.lower()]
            for val in vals[1:]:
                yield vals[0], val
    def itermerged(self):
        for key in self:
            val = self._container[key.lower()]
            yield val[0], ', '.join(val[1:])
    def items(self):
        return list(self.iteritems())
    @classmethod
    def from_httplib(cls, message):  
        headers = []
        for line in message.headers:
            if line.startswith((' ', '\t')):
                key, value = headers[-1]
                headers[-1] = (key, value + '\r\n' + line.rstrip())
                continue
            key, value = line.split(':', 1)
            headers.append((key, value.strip()))
        return cls(headers)

class service(object):
    def __init__(self, ip, port, protocol, weight=0):
        self.ip = str(ip)
        self.port = str(port)
        self.protocol = str(protocol)
        self.weight = weight
        self.dependencies = {}
    def copy(self):
        s = service( self.ip, self.port, self.protocol, self.weight )
        for d in self.dependencies:
            s.dependencies[d] = self.dependencies[d]
        return s
    def has(self,service):
        return service in self.dependencies
    def __cmp__(self,y):
        if type(y) is service:
            y = str(y)
        if type(y) is not str:
            raise TypeError
        return cmp(str(self), y)
    def sim(self, y):
        if self.port != y.port:
            return 0
        l1 = len(self.dependencies) * 1.0
        l2 = len(y.dependencies) * 1.0
        l3 = 0
        for i in self.dependencies:
            if i in y.dependencies:
                l3+=1
        return 1.0*l3 / max(l1,l2)
    def __str__(self):
        return str(self.ip)+":"+str(self.port)+":"+str(self.protocol)
    def __repr__(self):
        return str(self.ip)+":"+str(self.port)+":"+str(self.protocol)

class StatedDataItem(DataItem):
    STATUS_UNTRACKED = '?'
    STATUS_DELETE = 'D'
    STATUS_MODIFIED = 'M'
    STATUS_TYPE_CHANGED = 'T'
    def __init__(self, state, data_file, git, config, cache_file=None):
        super(StatedDataItem, self).__init__(data_file, git, config, cache_file)
        self._status = state
    @property
    def status(self):
        return self._status
    def _check_status(self, status):
        return self._status.find(status) >= 0
    @property
    def is_removed(self):
        return self._check_status(self.STATUS_DELETE)
    @property
    def is_modified(self):
        return self._check_status(self.STATUS_MODIFIED) \
               or self._check_status(self.STATUS_TYPE_CHANGED)
    @property
    def is_new(self):
        return self._check_status(self.STATUS_UNTRACKED)
    @property
    def is_unusual(self):
        return self.is_new or self.is_modified or self.is_removed
    def __repr__(self):
        return u'({}, {})'.format(self.state, self.data_dvc_short)

class Collection(persistence.IPersist):
    _fields = [
        (
            "citation_info",
            "",
            asstr,
            this,
            "str: Bibtex representation of the citation",
        )
    ]  
    def __init__(self, **kwargs):
        for name, default, *_ in self._fields:
            setattr(self, name, copy(default))
        for key, value in kwargs.items():
            if key in self._names:
                if isinstance(value, bytes):
                    value = value.decode()
                elif isinstance(value, np.ndarray) and value.dtype == np.dtype("O"):
                    value = value.astype(str)
                setattr(self, key, value)
    def __getitem__(self, key):
        key = key.casefold()
        return getattr(self, key)
    def __setitem__(self, key, value):
        key = key.casefold()
        setattr(self, key, value)
    def __contains__(self, key):
        return key in dir(self) and getattr(self, key) is not None
    def __str__(self):
        with np.printoptions(threshold=10):
            lines = []
            for name in self._names:
                lines += [f"{name}={self[name]!r}"]
            lines = ",\n".join(lines)
            output = f"{self.__class__.__name__}({lines})"
        return output
    def __repr__(self):
        return self.__str__()
    def create_citation(self, citation_info, output="string"):
        if output == "bibtex":
            return citation_info
        elif output == "string":
            output = "plaintext"
        return pybtex.format_from_string(
            citation_info, style="plain", output_backend=output
        )
    def citation(self, output="string"):
        return self.create_citation(self.citation_info, output=output)
    def to_dict(self):
        tree = {}
        for name in self._names:
            value = self[name]
            if hasattr(value, "to_dict"):
                value = value.to_dict()
            tree[name] = value
        return tree
    @classmethod
    def from_dict(cls, data):
        obj = cls(**data)
        return obj
    def _save(self):
        header = {}
        data = {}
        for name in self._names:
            value = self[name]
            if isinstance(value, np.ndarray) and value.size > 10:
                data[name] = value
            else:
                header[name] = value
        ext = MultipleDataExtension(header, data)
        return ext
    @classmethod
    def _load(cls, ext: MultipleDataExtension):
        header = ext.header
        if isinstance(ext, MultipleDataExtension):
            data = dict(ext.data)
            header.update(data)
        obj = cls(**header)
        return obj

class Model(object):
    @classmethod
    def db_path(cls):
        classname = cls.__name__
        path = 'data/{}.txt'.format(classname)
        return path
    @classmethod
    def all(cls):
        path = cls.db_path()
        models = load(path)
        ms = [cls.new(m) for m in models]
        return ms
    @classmethod
    def new(cls, form):
        m = cls(form)
        return m
    @classmethod
    def find_by(cls, **kwargs):
        log('kwargs, ', kwargs)
        k, v = '', ''
        for key, value in kwargs.items():
            k, v = key, value
        all = cls.all()
        for m in all:
            if v == m.__dict__[k]:
                return m
        return None
    @classmethod
    def find_all(cls, **kwargs):
        log('kwargs, ', kwargs)
        k, v = '', ''
        for key, value in kwargs.items():
            k, v = key, value
        all = cls.all()
        data = []
        for m in all:
            if v == m.__dict__[k]:
                data.append(m)
        return data
    def __repr__(self):
        classname = self.__class__.__name__
        properties = ['{}: ({})'.format(k, v) for k, v in self.__dict__.items()]
        s = '\n'.join(properties)
        return '< {}\n{} >\n'.format(classname, s)
    def save(self):
        log('debug save')
        models = self.all()
        log('models', models)
        first_index = 0
        if self.__dict__.get('id') is None:
            if len(models) > 0:
                log('用 log 可以查看代码执行的走向')
                self.id = models[-1].id + 1
            else:
                log('first index', first_index)
                self.id = first_index
            models.append(self)
        else:
            index = -1
            for i, m in enumerate(models):
                if m.id == self.id:
                    index = i
                    break
            if index > -1:
                models[index] = self
        l = [m.__dict__ for m in models]
        path = self.db_path()
        save(l, path)
    def remove(self):
        models = self.all()
        if self.__dict__.get('id') is not None:
            index = -1
            for i, m in enumerate(models):
                if m.id == self.id:
                    index = i
                    break
            if index > -1:
                del models[index]
        l = [m.__dict__ for m in models]
        path = self.db_path()
        save(l, path)

