class Buffer:
    def __init__(self, line):
        self._tokens = Buffer.tokenize(line)
        self._tokens.reverse() 
    def pop(self):
        while len(self._tokens) == 0:
            try:
                self._tokens = Buffer.tokenize(input(PS2))
            except KeyboardInterrupt:
                print(interrupt)
                exit(0)
            else:
                self._tokens.reverse()
        return self._tokens.pop()
    def current(self):
        while len(self._tokens) == 0:
            try:
                self._tokens = Buffer.tokenize(input(PS2))
            except KeyboardInterrupt:
                print(interrupt)
                exit(0)
            else:
                self._tokens.reverse()
        return self._tokens[-1]
    def prepend(self, token):
        self._tokens.append(token)
    @staticmethod
    def tokenize(line):
        for delim in DELIMS:
            line = line.replace(delim, ' ' + delim + ' ')
        return line.split()
    @property
    def empty(self):
        return len(self._tokens) == 0
    def __str__(self):
        return str(list(reversed(self._tokens)))
    def __repr__(self):
        return "Buffer(" + repr(list(reversed(self._tokens))) + ")"

class Group(collections.Sequence):
    def __init__(self, widgets=None, attrs=None, width=None, height=None):
        self.widgets = tuple(widgets or ())
        self.attrs = (attrs or {}).copy()
        self.width, self.height = width, height
    def __repr__(self):
        return '<Group of widgets: {}>'.format(self.widgets)
    def __len__(self):
        return len(self.widgets)
    def __getitem__(self, index):
        return self.widgets[index]
    def __add__(self, other):
        widgets = itertools.chain(self, other)
        width = getattr(other, 'width', self.width)
        height = getattr(other, 'height', self.height)
        attrs = self.attrs.copy()
        other_attrs = getattr(other, 'attrs', None)
        if other_attrs:
            attrs.update(other_attrs)
        return Group(widgets, attrs, width, height)
    def get_id(self):
        return self.attrs.get('id', '_and_'.join(x.slug for x in self))
    def get_class(self):
        return self.attrs.get('class', '')
    def get_attrs(self):
        return {key: value for key, value
                in self.attrs.items()
                if key not in ('id', 'class')}
    def _get_size(self, size):
        value = getattr(self, size, None)
        if value is not None:
            return value
        elif self.widgets:
            return max(getattr(x, size, None) or 0 for x in self) or None
    def get_width(self):
        return self._get_size('width')
    def get_height(self):
        return self._get_size('height')

