class Square:
    def __init__(self):
        self.mine = False
        self.adjacent = 0
        self.flagged = False
        self.visible = False
    def __repr__(self):
        if self.visible:
            if self.mine:
                return "M"
            elif self.adjacent == 0:
                return " "
            else:                
                return str(self.adjacent)
        elif self.flagged:
            return "F"
        else:
            return " "
    def flag(self):
        if not self.visible:
            self.flagged = not self.flagged
    def stepOn(self):
        isEmpty = False
        isAlive = True
        self.flagged = False
        if self.adjacent == 0:
            isEmpty = True
        elif self.mine:
            self.visible = True
            isAlive = False
        else:
            self.visible = True
        return isAlive, isEmpty

