class BidiMap(object):
    def __init__(self, channels, names):
        self.dictionary  = dict(zip(channels, names))
        self.reverse = {}
        for k,v in self.dictionary.items():
            self.reverse[v] = k
        self.dictionary.update(self.reverse)
    def __getitem__(self, k):
        return self.dictionary[k]
    def has_key(self, k):
        return (k in self.dictionary)
    def get(self, k, d=None):
        if self.has_key(k):
            return self[k]
        return d
    def update(self, input):
        self.dictionary.update(input)
        for k,v in input.iteritems():
            self.reverse[v] = k
        self.dictionary.update(self.reverse)
    def __repr__(self):
        return repr(self.dictionary)

class defaultdict:
    def __init__(self, func=None, x=None): 
        self.value = func()
    def __initdict__(self, func, d):
        value = func()
        value = d.value
        self.__setunit__(d.unit, value)
    def __inititer__(self, func, i):
        value = func()
        item = iter(i).next()
        value = item[1]
        self.__setunit__(item[0], value)
    def __setitem__(self, key, value):
        self.__setunit__(key, value)
    def __getitem__(self, key):
        self.__missing__(key)
        return self.value
    def __missing__(self, key):
        self.__key__(key)
        self.unit = key
        return self.value
    def keys(self):
        return [self.unit]
    def values(self):
        return [self.value]
    def items(self):
        return [(self.unit, self.value)]
    def __repr__(self):
        self.unit.__repr__()
        self.value.__repr__()
        return ''
    def __str__(self):
        return self.__repr__()
    def __key__(self, k):
        k.__hash__()
        k.__eq__(k)
    def __setunit__(self, k, v):
        self.__key__(k)
        self.unit = k
        self.value = v
    def __delitem__(self, k):
        self.__key__(k)
    def setdefault(self, k, v=None):
        self.__setunit__(k, v)
        return v
    def has_key(self, k):
        self.__key__(k)
        return 1
    def __len__(self):
        return 1
    def clear(self):
        pass
    def copy(self):
        return {self.unit: self.value}
    def get(self, k, default=None):
        self.__key__(k)
        return self.value
        return default
    def pop(self, k):
        self.__key__(k)
        return self.value
    def popitem(self):
        return (self.unit, self.value)
    def update(self, d):
        self.__setunit__(d.unit, d.value)
    def __delete__(self, k):
        self.__key__(k)
    def fromkeys(l, b=None):
        d = defaultdict()
        d.__setunit__(iter(l).next(), b)
        return d
    fromkeys = staticmethod(fromkeys) 
    def iterkeys(self):
        return __iter(self.unit)
    def itervalues(self):
        return __iter(self.value)
    def iteritems(self):
        return __iter((self.unit, self.value))
    def __iter__(self):
        return __iter(self.unit)

class Archive(object):
    def __init__(self, source, is_tmpdir=False):
        self._meta = {}
        self.name, _ = os.path.splitext(os.path.basename(source))
        if os.path.isdir(source):
            self.dirname = os.path.abspath(source)
            self.is_tmpdir = is_tmpdir  
        else:
            base = mkdtemp(dir=os.environ.get("TMPDIR", None))
            unpack_archive(source, base)
            (head, tail, _) = next(os.walk(base))
            if not tail:
                raise ValueError("'{}' is empty.".format(source))
            if len(tail) > 1:
                raise ValueError("'{}' is a bomb.".format(source))
            self.dirname = os.path.join(head, tail[0])
            self.is_tmpdir = True  
    @classmethod
    def empty(cls, head):
        base = mkdtemp(dir=os.environ.get("TMPDIR", None))
        source = os.path.join(base, head)
        os.makedirs(source, exist_ok=True)
        return cls(source, True)
    def add(self, source):
        copy(source, self.dirname)
    def __repr__(self):
        return "{}(dirname={!r})".format(self.__class__.__name__,
                                         self.dirname)
    def dump(self, sink, archive_fmt=FORMAT):
        return make_archive(sink, archive_fmt,
                            *os.path.split(self.dirname))
    def __del__(self):
        if self.is_tmpdir:
            rmtree(self.dirname)

