class Token(object):
    def __init__(self, position, text, tag, ud):
        self.position = position
        self.text = text
        self.tag = tag
        self.dependents = None
        self.gov = None
        self.gov_rel = None
        self.ud = ud
    def __repr__(self):
        return '%s/%s' % (self.text, self.position)
    @property
    def isword(self):
        "Check if the token is not punctuation."
        return self.tag != postag.PUNCT
    def argument_like(self):
        "Does this token look like the root of an argument?"
        return (self.gov_rel in self.ud.ARG_LIKE)
    def hard_to_find_arguments(self):
        for e in self.dependents:
            if e.rel in self.ud.SUBJ or e.rel in self.ud.OBJ:
                return False
        return self.gov_rel in self.ud.HARD_TO_FIND_ARGS

class Argument(object):
    def __init__(self, root, ud, rules):
        self.root = root
        self.rules = rules
        self.position = root.position
        self.ud = ud
        self.tokens = []
        self.share = False
    def __repr__(self):
        return 'Argument(%s)' % self.root
    def copy(self):
        x = Argument(self.root, self.ud, self.rules[:])
        x.tokens = self.tokens[:]
        return x
    def reference(self):
        x = Argument(self.root, self.ud, self.rules[:])
        x.tokens = self.tokens
        x.share = True
        return x
    def is_reference(self):
        return self.share
    def isclausal(self):
        return self.root.gov_rel in {self.ud.ccomp, self.ud.csubj,
                                     self.ud.csubjpass, self.ud.xcomp}
    def phrase(self):
        return ' '.join(x.text for x in self.tokens)
    def coords(self):
        "Argument => list of the heads of the conjunctions within it."
        coords = [self]
        if self.root.gov_rel not in {self.ud.ccomp, self.ud.csubj}:
            for e in self.root.dependents:
                if e.rel == self.ud.conj:
                    coords.append(Argument(e.dep, self.ud, [R.m()]))
        return sort_by_position(coords)

class Transition:
    def __init__(self, gate, new_output, time):
        if new_output != 0 and new_output != 1:
            raise ValueError('Invalid output value')
        self.gate = gate
        self.new_output = new_output
        self.time = time
        self.object_id = Transition.next_object_id()
    def __lt__(self, other):
        return (self.time < other.time or
                (self.time == other.time and self.object_id < other.object_id))
    def __le__(self, other):
        return (self.time < other.time or
                (self.time == other.time and self.object_id <= other.object_id))
    def __gt__(self, other):
        return (self.time > other.time or
                (self.time == other.time and self.object_id > other.object_id))
    def __ge__(self, other):
        return (self.time > other.time or
                (self.time == other.time and self.object_id >= other.object_id))
    def is_valid(self):
        return self.gate.output != self.new_output
    def apply(self):
        if self.gate.output == self.new_output:
            raise ValueError('Gate output should not transition to the same '
                             'value')
        self.gate.output = self.new_output
    def __repr__(self):
        return ('<Transition at t=' + str(self.time) + ', gate ' + 
                self.gate.name + ' -> ' + str(self.new_output) + '>')
    _next_id = 0
    @staticmethod
    def next_object_id():
        id = Transition._next_id
        Transition._next_id += 1
        return id

