class Ponto():
    def __init__(self, x, y, caracter):
        self.caracter = caracter
        self.x = round(x)
        self.y = round(y)
    def __eq__(self, other):
        return self.x == other.x and self.y == other.y and self.caracter == other.caracter
    def __hash__(self):
        return hash(self.x) ^ hash(self.y)
    def __repr__(self, *args, **kwargs):
        return "Ponto(%s,%s,'%s')" % (self.x, self.y, self.caracter)

class CallerCalleePercentageItem:
    def __init__(self, report, id, localPerc):
        self.report = report
        self.localPerc = localPerc
        self.funcAddr = id
        self.rtfFormattedReport = None
        self.plainTextFormattedReport = None
    def __createReport(self, rtf):
        report = TextPerfReport(rtf)
        rec = self.__myRec()
        callers = sorted(rec.getCallers(), key = lambda e: e.getOverallPercentage(), reverse=True)
        callees = sorted(self.createCallees(), key = lambda e: e.getLocalPercentage(), reverse=True)
        return report.format(functionName = self.getName(), 
                             callers = callers, 
                             callees = callees, 
                             overallPerc = self.getOverallPerc(),
                             percOfParent = self.getLocalPercentage(), 
                             localPerc = self.getLeftoverPerc())               
    def __myRec(self):
        return self.report.getRecord(self.funcAddr)
    def __myEntry(self):
        return self.report.getRecord(self.funcAddr).getRoot()
    def getLocalPercentage(self):
        return self.localPerc
    def getName(self):
        myEntry = self.__myEntry()
        shortened = cppName.smartShorten(myEntry.getFunctionName(), 100)
        return shortened
    def getOverallPerc(self):
        myEntry = self.__myEntry()
        return myEntry.getOverallPercentage()
    def getFullPerfDescription(self, rtf):
        if self.rtfFormattedReport == None:
            self.rtfFormattedReport = self.__createReport(rtf=True)
        if self.plainTextFormattedReport == None:
            self.plainTextFormattedReport = self.__createReport(rtf=False)
        if rtf:
            return self.rtfFormattedReport
        else:
            return self.plainTextFormattedReport
    def createCallees(self):
        myRec = self.__myRec()
        totTime = totRecordTime(myRec)
        exclPercentage = (myRec.getRoot().getElapsedExcl() / totTime) * 100.0
        children = []
        for callee in myRec.getCallees():
            perc = (callee.getElapsedIncl() / totTime) * 100.0
            children.append(
                            CallerCalleePercentageItem(self.report, 
                                                       callee.getFunctionAddr(),
                                                       perc)
                            )
        totPerc = (exclPercentage + sum([item.getLocalPercentage() for item in children]))
        assert totPerc < 100.0001
        return children
    def createCallers(self):
        myRec = self.__myRec()
        callers = myRec.getCallers()
        return [CallerCalleePercentageItem(self.report, caller.getFunctionAddr(), caller.getOverallPercentage())
                for caller in myRec.getCallers()]
    def getLeftoverPerc(self):
        myRec = self.report.getRecord(self.funcAddr)
        totTime = totRecordTime(myRec)
        return (myRec.getRoot().getElapsedExcl() / totTime) * 100.0
    def getAddress(self):
        return self.funcAddr
    def __repr__(self):
        return "CallerCalleePercentageItem(%s, %lf)" % (self.rootFunction, self.localPerc)

class NewPad(object):
    def __init__(self, fill=0, padding_mode='constant'):
        assert isinstance(fill, (numbers.Number, str, tuple))
        assert padding_mode in ['constant', 'edge', 'reflect', 'symmetric']
        self.fill = fill
        self.padding_mode = padding_mode
    def __call__(self, img):
        return F.pad(img, get_padding(img), self.fill, self.padding_mode)
    def __repr__(self):
        return self.__class__.__name__ + '(padding={0}, fill={1}, padding_mode={2})'.\
            format(self.fill, self.padding_mode)

class SchedulingUnit (general.DataClass):
  HEADERS = ["DELOVIŠČE", "VLOGA"]
  def __init__ (self, workplace, role):
    general.DataClass.__init__ (self)
    self.workplace = workplace
    self.role      = role
    self.__color     = (255, 255, 255)
    self.allowed_turnuses = set ()
  def as_data_list(self):
    return [self.workplace, self.role]
  def as_list(self):
    return [translate (self.workplace), translate (self.role)]
  def synchronize_data(self, *args):
    affected = False
    for data in args:
      if data == self.workplace:
        self.workplace = data
        affected       = True
      if data == self.role:
        self.role = data
        affected  = True
      if data in self.allowed_turnuses:
        self.remove_allowed_turnus (data)
        self.add_allowed_turnus (data)
        affected = True
    return affected
  def add_allowed_turnus (self, turnus):
    self.allowed_turnuses.add (turnus)
  def remove_allowed_turnus (self, turnus):
    self.allowed_turnuses.remove (turnus)
  def is_allowed_turnus (self, turnus):
    return turnus in self.allowed_turnuses
  def get_turnus_types (self):
    turnus_types = set ( )
    for turnus in self.allowed_turnuses:
      turnus_types |= turnus.types
    return sorted (turnus_types)
  def get_workplace (self):
    return self.workplace
  def has_workplace (self, workplace):
    return workplace == self.workplace
  def get_role (self):
    return self.role
  def has_role (self, role):
    return role == self.role
  def get_allowed_turnuses (self):
    return self.allowed_turnuses
  def has_holiday_rule (self):
    return self.get_workplace ( ).has_holiday_rule ( )
  def get_color (self):
    return self.__color
  def set_color (self, color):
    self.__color = color
  def __str__ (self):
    return str (self.workplace) + ' - ' + str (self.role)
  def __hash__ (self):
    return hash (str(self))
  def __eq__ (self, other):
    return self.__cmp__(other) == 0
  def __cmp__ (self, other):
    try:
      if not cmp (self.workplace, other.workplace):
        return cmp (self.role, other.role)
      else:
        return cmp (self.workplace, other.workplace)  
    except:
      return - 1

class Node:
    def __init__(self, data):
        self.data = data
        self.next = None
    def __repr__(self):
        return self.data

class LinkedList:
    def __init__(self, nodes=None):
        self.head = None
        if nodes is not None:
            node = Node(data=nodes.pop(0))
            self.head = node
            for item in nodes:
                node.next = Node(data=item)
                node = node.next
    def add_first(self,node):
        node.next = self.head
        self.head = node
    def add_last(self,node):
        if self.head is None:
            self.head = node
        else:
            temp = self.head
            while temp.next is not None:
                temp = temp.next
            temp.next = node
    def add_after(self, target_node_data, new_node):
        if not self.head:
            raise Exception("List is emppty")
        pass
    def add_before(self, target_node_data, new_node):
        if not self.head:
            raise Exception("List is empty")
        pass
    def remove_node(self, target_node_data):
        pass
    def __iter__(self):
        node = self.head
        while node is not None:
            yield node
            node = node.next
    def __repr__(self):
        node = self.head
        nodes = []
        while node is not None:
            nodes.append(node.data)
            node = node.next
        nodes.append('None')
        return " -> ".join(nodes)

class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(64), index=True, unique=True)
    email = db.Column(db.String(120), index=True, unique=True)
    password_hash = db.Column(db.String(128))
    about_me = db.Column(db.String(140))
    last_seen = db.Column(db.DateTime, default=datetime.utcnow)
    posts = db.relationship('Post', backref='author', lazy='dynamic')
    def __repr__(self):
        return '<User {}>'.format(self.username)
    def set_password(self, password):
        self.password_hash =  generate_password_hash(password)
    def check_password(self, password):
        return check_password_hash(self.password_hash, password)
    def avatar(self, size):
        digest = md5(self.email.lower().encode('utf-8')).hexdigest()
        return 'https://www.gravatar.com/avatar/{}?d=identicon&s={}'.format(digest, size)
    def follow(self, user):
        if not self.is_following(user):
            self.followed.append(user)
    def unfollow(self, user):
        if self.is_following(user):
            self.followed.remove(user)
    def is_following(self, user):
        return self.followed.filter(followers.c.followed_id == user.id).count() > 0
    def followed_posts(self):
        followed = Post.query.join(
            followers, (followers.c.followed_id == Post.user_id)).filter(followers.c.follower_id == self.id)
        own = Post.query.filter_by(user_id=self.id)
        return followed.union(own).order_by(Post.timestamp.desc())
    followed = db.relationship(
        'User', secondary=followers,
        primaryjoin=(followers.c.follower_id == id),
        secondaryjoin=(followers.c.followed_id == id),
        backref=db.backref('followers', lazy='dynamic'), lazy='dynamic')

