class Document:
    def __init__(self, id, category_id, topic_id, file_name):
        self.id = id
        self.category_id = category_id
        self.topic_id = topic_id
        self.file_name = file_name
        self.tags = []
    @classmethod
    def from_instances(cls, id, category, topic, file_name):
        return cls(id, category.id, topic.id, file_name)
    def add_tag(self, tag_content):
        if tag_content not in self.tags:
            self.tags.append(tag_content)
    def remove_tag(self, tag_content):
        if tag_content in self.tags:
            self.tags.remove(tag_content)
    def edit(self, file_name):
        self.file_name = file_name
    def __repr__(self):
        tags = ', '.join(self.tags)
        return f"Document {self.id}: {self.file_name}; category {self.category_id}, topic {self.topic_id}, tags: {tags}"

class CurrencyExchange(object):
    openapi_types = {
        'source_currency': 'str',
        'target_currency': 'str',
        'unit_currency': 'str',
        'exchange_rate': 'float'
    }
    attribute_map = {
        'source_currency': 'sourceCurrency',
        'target_currency': 'targetCurrency',
        'unit_currency': 'unitCurrency',
        'exchange_rate': 'exchangeRate'
    }
    def __init__(self, source_currency=None, target_currency=None, unit_currency=None, exchange_rate=None, local_vars_configuration=None):  
        if local_vars_configuration is None:
            local_vars_configuration = Configuration()
        self.local_vars_configuration = local_vars_configuration
        self._source_currency = None
        self._target_currency = None
        self._unit_currency = None
        self._exchange_rate = None
        self.discriminator = None
        if source_currency is not None:
            self.source_currency = source_currency
        if target_currency is not None:
            self.target_currency = target_currency
        if unit_currency is not None:
            self.unit_currency = unit_currency
        if exchange_rate is not None:
            self.exchange_rate = exchange_rate
    @property
    def source_currency(self):
        return self._source_currency
    @source_currency.setter
    def source_currency(self, source_currency):
        self._source_currency = source_currency
    @property
    def target_currency(self):
        return self._target_currency
    @target_currency.setter
    def target_currency(self, target_currency):
        self._target_currency = target_currency
    @property
    def unit_currency(self):
        return self._unit_currency
    @unit_currency.setter
    def unit_currency(self, unit_currency):
        self._unit_currency = unit_currency
    @property
    def exchange_rate(self):
        return self._exchange_rate
    @exchange_rate.setter
    def exchange_rate(self, exchange_rate):
        self._exchange_rate = exchange_rate
    def to_dict(self):
        result = {}
        for attr, _ in six.iteritems(self.openapi_types):
            value = getattr(self, attr)
            if isinstance(value, list):
                result[attr] = list(map(
                    lambda x: x.to_dict() if hasattr(x, "to_dict") else x,
                    value
                ))
            elif hasattr(value, "to_dict"):
                result[attr] = value.to_dict()
            elif isinstance(value, dict):
                result[attr] = dict(map(
                    lambda item: (item[0], item[1].to_dict())
                    if hasattr(item[1], "to_dict") else item,
                    value.items()
                ))
            else:
                result[attr] = value
        return result
    def to_str(self):
        return pprint.pformat(self.to_dict())
    def __repr__(self):
        return self.to_str()
    def __eq__(self, other):
        if not isinstance(other, CurrencyExchange):
            return False
        return self.to_dict() == other.to_dict()
    def __ne__(self, other):
        if not isinstance(other, CurrencyExchange):
            return True
        return self.to_dict() != other.to_dict()

class CMSPluginBase(with_metaclass(CMSPluginBaseMetaclass, admin.ModelAdmin)):
    name = ""
    module = _("Generic")  
    form = None
    change_form_template = "admin/cms/page/plugin/change_form.html"
    admin_preview = False
    render_template = None
    render_plugin = True
    model = CMSPlugin
    text_enabled = False
    page_only = False
    allow_children = False
    child_classes = None
    require_parent = False
    parent_classes = None
    disable_child_plugins = False
    cache_child_classes = True
    cache_parent_classes = True
    _has_extra_placeholder_menu_items = False
    _has_extra_plugin_menu_items = False
    cache = get_cms_setting('PLUGIN_CACHE')
    system = False
    opts = {}
    def __init__(self, model=None, admin_site=None):
        if admin_site:
            super(CMSPluginBase, self).__init__(self.model, admin_site)
        self.object_successfully_changed = False
        self.placeholder = None
        self.page = None
        self.cms_plugin_instance = None
        self._cms_initial_attributes = {}
        self._operation_token = None
    def _get_render_template(self, context, instance, placeholder):
        if hasattr(self, 'get_render_template'):
            template = self.get_render_template(context, instance, placeholder)
        elif getattr(self, 'render_template', False):
            template = getattr(self, 'render_template', False)
        else:
            template = None
        if not template:
            raise ValidationError("plugin has no render_template: %s" % self.__class__)
        return template
    @classmethod
    def get_render_queryset(cls):
        return cls.model._default_manager.all()
    def render(self, context, instance, placeholder):
        context['instance'] = instance
        context['placeholder'] = placeholder
        return context
    @classmethod
    def requires_parent_plugin(cls, slot, page):
        if cls.get_require_parent(slot, page):
            return True
        allowed_parents = cls.get_parent_classes(slot, page)
        return bool(allowed_parents)
    @classmethod
    def get_require_parent(cls, slot, page):
        from cms.utils.placeholder import get_placeholder_conf
        template = page.get_template() if page else None
        require_parent = get_placeholder_conf('require_parent', slot, template, default=cls.require_parent)
        return require_parent
    def get_cache_expiration(self, request, instance, placeholder):
        return None
    def get_vary_cache_on(self, request, instance, placeholder):
        return None
    def render_change_form(self, request, context, add=False, change=False, form_url='', obj=None):
        context.update({
            'preview': "no_preview" not in request.GET,
            'is_popup': True,
            'plugin': obj,
            'CMS_MEDIA_URL': get_cms_setting('MEDIA_URL'),
        })
        return super(CMSPluginBase, self).render_change_form(request, context, add, change, form_url, obj)
    def render_close_frame(self, request, obj, extra_context=None):
        try:
            root = obj.parent.get_bound_plugin() if obj.parent else obj
        except ObjectDoesNotExist:
            root = obj
        plugins = [root] + list(root.get_descendants().order_by('path'))
        child_classes = self.get_child_classes(
            slot=obj.placeholder.slot,
            page=obj.page,
            instance=obj,
        )
        parent_classes = self.get_parent_classes(
            slot=obj.placeholder.slot,
            page=obj.page,
            instance=obj,
        )
        data = get_plugin_toolbar_info(
            obj,
            children=child_classes,
            parents=parent_classes,
        )
        data['plugin_desc'] = escapejs(force_text(obj.get_short_description()))
        context = {
            'plugin': obj,
            'is_popup': True,
            'plugin_data': json.dumps(data),
            'plugin_structure': get_plugin_tree_as_json(request, plugins),
        }
        if extra_context:
            context.update(extra_context)
        return render_to_response(
            request, 'admin/cms/page/plugin/confirm_form.html', context
        )
    def save_model(self, request, obj, form, change):
        pl_admin = obj.placeholder._get_attached_admin()
        if pl_admin:
            operation_kwargs = {
                'request': request,
                'placeholder': obj.placeholder,
            }
            if change:
                operation_kwargs['old_plugin'] = self.model.objects.get(pk=obj.pk)
                operation_kwargs['new_plugin'] = obj
                operation_kwargs['operation'] = operations.CHANGE_PLUGIN
            else:
                parent_id = obj.parent.pk if obj.parent else None
                tree_order = obj.placeholder.get_plugin_tree_order(parent_id)
                operation_kwargs['plugin'] = obj
                operation_kwargs['operation'] = operations.ADD_PLUGIN
                operation_kwargs['tree_order'] = tree_order
            self._operation_token = pl_admin._send_pre_placeholder_operation(**operation_kwargs)
        self.saved_object = obj
        return super(CMSPluginBase, self).save_model(request, obj, form, change)
    def save_form(self, request, form, change):
        obj = super(CMSPluginBase, self).save_form(request, form, change)
        for field, value in self._cms_initial_attributes.items():
            setattr(obj, field, value)
        return obj
    def response_add(self, request, obj, **kwargs):
        self.object_successfully_changed = True
        return self.render_close_frame(request, obj)
    def response_change(self, request, obj):
        self.object_successfully_changed = True
        opts = self.model._meta
        msg_dict = {'name': force_text(opts.verbose_name), 'obj': force_text(obj)}
        msg = _('The %(name)s "%(obj)s" was changed successfully.') % msg_dict
        self.message_user(request, msg, messages.SUCCESS)
        return self.render_close_frame(request, obj)
    def log_addition(self, request, obj, bypass=None):
        pass
    def log_change(self, request, obj, message, bypass=None):
        pass
    def log_deletion(self, request, obj, object_repr, bypass=None):
        pass
    def icon_src(self, instance):
        return ""
    def icon_alt(self, instance):
        return "%s - %s" % (force_text(self.name), force_text(instance))
    def get_fieldsets(self, request, obj=None):
        fieldsets = super(CMSPluginBase, self).get_fieldsets(request, obj)
        for name, data in fieldsets:
            if data.get('fields'):  
                return fieldsets
        if self.inlines:
            return []  
        try:  
            fieldsets[0][1]['description'] = self.get_empty_change_form_text(obj=obj)
        except KeyError:
            pass
        return fieldsets
    @classmethod
    def get_empty_change_form_text(cls, obj=None):
        return ugettext('There are no further settings for this plugin. Please press save.')
    @classmethod
    def get_child_class_overrides(cls, slot, page):
        from cms.utils.placeholder import get_placeholder_conf
        template = page.get_template() if page else None
