class Space:
    def __init__(self, posx, posy, width, height):
        self.x = posx
        self.y = posy
        self.height = height
        self.width = width
    def overlap(self,s):
        if ( (self.x + self.width) > s.x and self.x < (s.x + s.width) and (self.y + self.height) > s.y and self.y < (s.y + s.height) ):
            return True
        return False
    def include(self,s):
        if (self.x <= s.x and (self.x + self.width) >= (s.x + s.width) and self.y <= s.y and (self.y + self.height) >= (s.y + s.height)):
            return True
        return False
    def combine(self,s):
        if ((self.x == s.x) and (self.width == s.width) and (self.y + self.height) >= s.y and self.y <= (s.y + s.height) ):
            posy =  min(self.y,s.y)
            height = max(self.y+self.height,s.y+s.height) - posy
            return Space(s.x,posy,s.width,height )
        if ((self.y == s.y) and (self.height == s.height) and (self.x + self.width) >= s.x and self.x <= (s.x + s.width) ):
            posx =  min(self.x,s.x)
            width = max(self.x+self.width,s.x+s.width) - posx
            return Space(posx,s.y,width,s.height )
        return None
    def freeSpacesDivision(self,s):
        spaces = SpaceList()
        if (not self.overlap(s)):
            spaces.append(self)
            return spaces 
        else:
            left = 0
            top = 0
            right = 0
            bot = 0
            if (self.x < s.x):
                left = s.x - self.x
            if ((self.x + self.width) > (s.x + s.width)):
                right = (self.x + self.width) - (s.x + s.width)
            if (self.y < s.y):
                top = s.y - self.y
            if ((self.y + self.height) > (s.y + s.height)):
                bot = (self.y + self.height) - (s.y + s.height)
            if (bot!= 0):
                spaces.append(Space(self.x,s.y+s.height,self.width,bot))
            if (top!= 0):
                spaces.append(Space(self.x,self.y,self.width,top))
            if (right!= 0):
                spaces.append(Space(s.x + s.width,self.y,right,self.height))
            if (left!= 0):
                spaces.append(Space(self.x,self.y,left,self.height))
        return spaces
    def calculateArea(self):
        return self.width*self.height
    def checkPlace(self,rect):
        return (self.width >= rect.width and self.height >= rect.height)
    def draw(self,p,screen):
        p.draw.rect(screen, (255,0,0) , (self.x,self.y,self.width,self.height), 1)
    def __str__(self):
        s = "("+str(self.x)+","+str(self.y)+","+str(self.width)+","+str(self.height)+")"
        return s
    def __repr__(self):
        return self.__str__()

class RNNCellBase(Module):
    def __repr__(self):
        s = '{name}({input_size}, {hidden_size}'
        if 'bias' in self.__dict__ and self.bias is not True:
            s += ', bias={bias}'
        if 'nonlinearity' in self.__dict__ and self.nonlinearity != "tanh":
            s += ', nonlinearity={nonlinearity}'
        s += ')'
        return s.format(name=self.__class__.__name__, **self.__dict__)
    def get_activation(self, activation):
        if hasattr(activations, activation):
            return getattr(activations, activation)
        return getattr(F, activation)
    def check_forward_input(self, input_data):
        if input_data.size(1) != self.input_size:
            raise RuntimeError(
                "input has inconsistent input_size: got {}, expected {}".format(
                    input_data.size(1), self.input_size))
    def check_forward_hidden(self, input_data, hx, hidden_label=''):
        if input_data.size(0) != hx.size(0):
            raise RuntimeError(
                "Input batch size {} doesn't match hidden{} batch size {}".format(
                    input_data.size(0), hidden_label, hx.size(0)))
        if hx.size(1) != self.hidden_size:
            raise RuntimeError(
                "hidden{} has inconsistent hidden_size: got {}, expected {}".format(
                    hidden_label, input_data.size(1), self.input_size))

class GroupedArray:
    def __init__(self, data: np.ndarray, indptr: np.ndarray):
        self.data = data
        self.indptr = indptr
        self.ngroups = len(indptr) - 1
    def __len__(self) -> int:
        return self.ngroups
    def __getitem__(self, idx: int) -> np.ndarray:
        return self.data[self.indptr[idx] : self.indptr[idx + 1]]
    def take_from_groups(self, idx: Union[int, slice]) -> 'GroupedArray':
        ranges = [
            range(self.indptr[i], self.indptr[i + 1])[idx] for i in range(self.ngroups)
        ]
        items = [self.data[rng] for rng in ranges]
        sizes = np.array([item.size for item in items])
        data = np.hstack(items)
        indptr = np.append(0, sizes.cumsum())
        return GroupedArray(data, indptr)
    def append(self, new: np.ndarray) -> 'GroupedArray':
        if new.size != self.ngroups:
            raise ValueError(f'new must be of size {self.ngroups}')
        new_data, new_indptr = _append_new(self.data, self.indptr, new)
        return GroupedArray(new_data, new_indptr)
    def __repr__(self) -> str:
        return f'GroupedArray(ndata={self.data.size}, ngroups={self.ngroups})'

class TimeSeries:
    def __init__(
        self,
        freq: str = 'D',
        lags: List[int] = [],
        lag_transforms: Dict[int, List[Tuple]] = {},
        date_features: List[str] = [],
        num_threads: Optional[int] = None,
    ):
        self.freq = pd.tseries.frequencies.to_offset(freq)
        self.num_threads = num_threads or os.cpu_count()
        self.date_features = date_features
        self.transforms: Dict[str, Tuple[Any, ...]] = OrderedDict()
        for lag in lags:
            self.transforms[f'lag-{lag}'] = (lag, _identity)
        for lag in lag_transforms.keys():
            for tfm_args in lag_transforms[lag]:
                tfm, *args = _as_tuple(tfm_args)
                tfm_name = _build_transform_name(lag, tfm, *args)
                self.transforms[tfm_name] = (lag, tfm, *args)
        self.ga: GroupedArray
    @property
    def features(self) -> List[str]:
        return list(self.transforms.keys()) + self.date_features
    def __repr__(self):
        return f'TimeSeries(freq={self.freq}, transforms={list(self.transforms.keys())}, date_features={self.date_features}, num_threads={self.num_threads})'
    def _apply_transforms(self, updates_only: bool = False) -> Dict[str, np.ndarray]:
        results = {}
        offset = 1 if updates_only else 0
        for tfm_name, (lag, tfm, *args) in self.transforms.items():
            results[tfm_name] = _transform_series(
                self.ga.data, self.ga.indptr, updates_only, lag - offset, tfm, *args
            )
        return results
    def _apply_multithreaded_transforms(
        self, updates_only: bool = False
    ) -> Dict[str, np.ndarray]:
        future_to_result = {}
        results = {}
        offset = 1 if updates_only else 0
        with concurrent.futures.ThreadPoolExecutor(self.num_threads) as executor:
            for tfm_name, (lag, tfm, *args) in self.transforms.items():
                future = executor.submit(
                    _transform_series,
                    self.ga.data,
                    self.ga.indptr,
                    updates_only,
                    lag - offset,
                    tfm,
                    *args,
                )
                future_to_result[future] = tfm_name
            for future in concurrent.futures.as_completed(future_to_result):
                tfm_name = future_to_result[future]
                results[tfm_name] = future.result()
        return results
    def _compute_transforms(self) -> Dict[str, np.ndarray]:
        if self.num_threads == 1 or len(self.transforms) == 1:
            return self._apply_transforms()
        return self._apply_multithreaded_transforms()
    def _update_y(self, new: np.ndarray) -> None:
        if not hasattr(self, 'y_pred'):
            self.y_pred = []
        self.y_pred.append(new)
        new_arr = np.asarray(new)
        self.ga = self.ga.append(new_arr)
    def _update_features(self) -> pd.DataFrame:
        if not hasattr(self, 'curr_dates'):
            self.curr_dates = self.last_dates.copy()
            self.test_dates = []
        self.curr_dates += self.freq
        self.test_dates.append(self.curr_dates)
        if self.num_threads == 1 or len(self.transforms) == 1:
            features = self._apply_transforms(updates_only=True)
        else:
            features = self._apply_multithreaded_transforms(updates_only=True)
        for feature in self.date_features:
            feat_vals = getattr(self.curr_dates, feature).values
            features[feature] = feat_vals.astype(date_features_dtypes[feature])
        features_df = pd.DataFrame(features, columns=self.features, index=self.uids)
        nulls_in_cols = features_df.isnull().any()
        if any(nulls_in_cols):
            warnings.warn(
                f'Found null values in {", ".join(nulls_in_cols[nulls_in_cols].index)}.'
            )
        results_df = self.static_features.join(features_df)
        results_df['ds'] = self.curr_dates
        return results_df
    def _get_predictions(self) -> pd.DataFrame:
        n_preds = len(self.y_pred)
        idx = pd.Index(
            chain.from_iterable([uid] * n_preds for uid in self.uids),
            name='unique_id',
            dtype=self.uids.dtype,
        )
        df = pd.DataFrame(
            {
                'ds': np.array(self.test_dates).ravel('F'),
                'y_pred': np.array(self.y_pred).ravel('F'),
            },
            index=idx,
        )
        return df
    def _fit(
        self,
        df: pd.DataFrame,
        static_features: Optional[List[str]] = None,
    ) -> 'TimeSeries':
        data, indptr = data_indptr_from_sorted_df(df)
        if data.dtype not in (np.float32, np.float64):
            data = data.astype(np.float32)
        self.ga = GroupedArray(data, indptr)
        self.uids = df.index.unique(level='unique_id')
        last_obs = df.iloc[indptr[1:] - 1]
        self.last_dates = last_obs.index.get_level_values('ds')
        self.static_features = last_obs.reset_index('ds').drop(columns=['ds', 'y'])
        if static_features is not None:
            self.static_features = self.static_features[static_features]
        return self
    def _transform(
        self,
        df: pd.DataFrame,
        dropna: bool = True,
        keep_last_n: Optional[int] = None,
    ) -> pd.DataFrame:
        df = df.reset_index('ds')
        features = self._compute_transforms()
        for feat in self.transforms.keys():
            df[feat] = features[feat]
        if dropna:
            df.dropna(inplace=True)
        for feature in self.date_features:
            feat_vals = getattr(df.ds.dt, feature).values
            df[feature] = feat_vals.astype(date_features_dtypes[feature])
        if keep_last_n is not None:
            self.ga = self.ga.take_from_groups(slice(-keep_last_n, None))
        self._ga = GroupedArray(self.ga.data, self.ga.indptr)
        self.features_order_ = df.columns.drop(['ds', 'y'])
        return df
    def fit_transform(
        self,
        data: pd.DataFrame,
        static_features: Optional[List[str]] = None,
        dropna: bool = True,
        keep_last_n: Optional[int] = None,
    ) -> pd.DataFrame:
        if data['y'].isnull().any():
            raise ValueError('y column contains null values.')
        data = data.set_index('ds', append=True)
        if not data.index.is_monotonic_increasing:
            data = data.sort_index()
        self._fit(data, static_features)
        return self._transform(data, dropna, keep_last_n)
    def _predict_setup(self) -> None:
        self.curr_dates = self.last_dates.copy()
        self.test_dates = []
        self.y_pred = []
        self.ga = GroupedArray(self._ga.data, self._ga.indptr)
    def predict(
        self,
        model,
        horizon: int,
        predict_fn: Callable = simple_predict,
        **predict_fn_kwargs,
    ) -> pd.DataFrame:
        self._predict_setup()
        for _ in range(horizon):
            new_x = self._update_features()
            predictions = predict_fn(
                model, new_x, self.features_order_, **predict_fn_kwargs
            )
            self._update_y(predictions)
        return self._get_predictions()

class Task:
  def __init__(self, id, act_db : dict, start_date = None, finish_date = None, duration = None, not_early_date = None):
    self.id = id                         
    self.start_date = start_date         
    self.finish_date = finish_date       
    self.duration = duration             
    self.next_activity = []              
    self.prior_activity = []             
    self.not_early_date = not_early_date 
    self.act_db = act_db
  def get_id(self):
    return self.id
  def get_start_date(self):
    return self.start_date
  def set_start_date(self, start_date):
    if start_date != None and self.start_date != start_date and start_date >= 0:
      if self.prior_activity != []:
        max_finish_date = 0
        for iactivity in self.prior_activity:
          activity = self.act_db[iactivity]
          if activity.finish_date > max_finish_date:
            max_finish_date = activity.finish_date
        if start_date > max_finish_date:          
          self.set_not_early_date(start_date)          
          self.start_date = start_date
          self.finish_date = self.start_date + self.duration
          self.recalculate_next()
        elif start_date == max_finish_date:
          self.start_date = max_finish_date
          self.finish_date = self.start_date + self.duration
          self.recalculate_next() 
        else:
          pass  
      else:
        self.set_not_early_date(start_date)
        self.start_date = start_date
        self.finish_date = self.start_date + self.duration
        self.recalculate_next()        
    else:
      pass 
  def get_finish_date(self):
    return self.finish_date
  def set_finish_date(self, finish_date):
    if finish_date != None and finish_date - self.start_date >= 0:
      self.finish_date = finish_date
      self.duration = self.finish_date - self.start_date
      self.recalculate_next()
    else:
      pass 
  def get_duration(self):
    return self.duration
  def set_duration(self, duration):
    if duration != None and duration >= 0:
      self.duration = duration
      self.finish_date = self.start_date + self.duration
      self.recalculate_next()
    else:
      pass 
  def recalculate_next(self):
    if self.next_activity != []:
      for iactivity in self.next_activity:
        activity = self.act_db[iactivity]
        max_finish_date = 0
        for iprior_activity in activity.prior_activity:
          prior_activity = self.act_db[iprior_activity]
          if prior_activity.finish_date > max_finish_date:
            max_finish_date = prior_activity.finish_date
        if (activity.not_early_date == None) or (activity.not_early_date != None and max_finish_date > activity.not_early_date):
          activity.set_start_date(max_finish_date)
  def get_next(self):
    return [self.act_db[activity].__str__() for activity in self.next_activity]
  def is_valid_next_activity(self, inext_activity : int):
    next_activity = self.act_db[inext_activity]
    is_valid = False
    if next_activity != None and self != next_activity:
      is_valid = True
    return is_valid
  def append_next(self, inext_activity : int):
    next_activity = self.act_db[inext_activity]
    if self.is_valid_next_activity(inext_activity):
      if next_activity.prior_activity != []:
        max_finish_date = 0
        for iactivity in next_activity.prior_activity:
          activity = self.act_db[iactivity]
          if activity.finish_date > max_finish_date:
            max_finish_date = activity.finish_date
        if self.finish_date > max_finish_date:
          recalculate = True
        else:
          recalculate = False
      else:
        recalculate = True
      self.next_activity.append(inext_activity)
      next_activity.prior_activity.append(self.id)
      if recalculate:
        self.recalculate_next()
    else:
      pass 
  def remove_next(self, inext_activity : int):
    next_activity = self.act_db[inext_activity]
    if self.next_activity.count(inext_activity) > 0:
      next_activity.prior_activity.remove(self.id)
      if next_activity.prior_activity != []:
        self.act_db[(next_activity.prior_activity)[0]].recalculate_next()
      self.next_activity.remove(inext_activity)
      self.recalculate_next()
    else:
      pass 
  def get_not_early_date(self):
    return self.not_early_date
  def set_not_early_date(self, not_early_date):
    self.not_early_date = not_early_date
    if not_early_date != None and not_early_date > self.start_date:
      self.start_date = not_early_date
      self.finish_date = self.start_date + self.duration
      self.recalculate_next()
    if self.not_early_date == None and self.prior_activity != []:
      max_finish_date = 0
      for iactivity in self.prior_activity:
        activity = self.act_db[iactivity]
        if activity.finish_date > max_finish_date:
          max_finish_date = activity.finish_date      
      self.set_start_date(max_finish_date)
  def __str__(self):
    return f"[{self.prior_activity}] <- Task(start={self.start_date} end={self.finish_date} dur={self.duration}) -> [{self.next_activity}]"
  def __repr__(self):
    return f"[{self.prior_activity}] <- Task(id={self.id} start={self.start_date} end={self.finish_date} dur={self.duration}) -> [{self.next_activity}]"

