class StateMachine:
	def __init__(self, states: dict=None, startName: str=None, chooser=None):
		self.states = states
		self.current = None
		if startName is not None:
			self.setCurrent(name=startName)
		self.chooser = chooser
	def getState(self, name, check=False):
		state = self.states[name] if name is not None else None
		if check and state is None:
			raise Exception('State not found: "%s"' % (name,))
		return state
	def setCurrent(self, name=None, state=None, check=True):
		if state is None:
			state = self.getState(name, check=check)
		self.current = state
		dbglog('state set to "%s"' % (state.name,))
		return state
	def getConnections(self):
		if self.current is None:
			return []
		return list(self.current.connections.values())
	def getAllConnections(self):
		for state in self.states.values():
			for conn in state.connections.values():
				yield conn
	def getConnectionTargetNames(self):
		return [c.target.name for c in self.getConnections()]
	def chooseNext(self):
		if self.current is None:
			return None
		conns = self.getConnections()
		if len(conns) == 0:
			return None
		if self.chooser is None:
			c = random.choice(conns)
			return None if c is None else c.target
		return self.chooser.chooseNext(self.current, conns)
	def followNext(self):
		nextState = self.chooseNext()
		if nextState is None:
			return None
		self.setCurrent(state=nextState)
		return nextState
	def __repr__(self):
		return 'StateMachine( current: %s )' % (self.current,)
	def toJsonDict(self):
		return {
			'current': (self.current.name if self.current is not None else None,),
			'states': {state.name: state.toJsonDict() for state in self.states.values()}}
	def toJson(self):
		d = self.toJsonDict()
		return json.dumps(d, sort_keys=True, indent=4)

class ParametrizedLine(Module):
    def __init__(self, origin: Tensor, direction: Tensor) -> None:
        super().__init__()
        self._origin = Parameter(origin)
        self._direction = Parameter(direction)
    def __str__(self) -> str:
        return f"Origin: {self.origin}\nDirection: {self.direction}"
    def __repr__(self) -> str:
        return str(self)
    def __getitem__(self, idx: int) -> Tensor:
        return self.origin if idx == 0 else self.direction
    def __iter__(self) -> Iterator[Tensor]:
        yield from (self.origin, self.direction)
    @property
    def origin(self) -> Tensor:
        return self._origin
    @property
    def direction(self) -> Tensor:
        return self._direction
    def dim(self) -> int:
        return self.direction.shape[-1]
    @classmethod
    def through(cls, p0: Tensor, p1: Tensor) -> "ParametrizedLine":
        return ParametrizedLine(p0, normalize((p1 - p0), p=2, dim=-1))
    def point_at(self, t: Union[float, Tensor]) -> Tensor:
        return self.origin + self.direction * t
    def projection(self, point: Tensor) -> Tensor:
        return self.origin + (self.direction @ (point - self.origin)) * self.direction
    def squared_distance(self, point: Tensor) -> Tensor:
        diff: Tensor = point - self.origin
        return squared_norm(diff - (self.direction @ diff) * self.direction)
    def distance(self, point: Tensor) -> Tensor:
        return self.squared_distance(point).sqrt()
    def intersect(self, plane: Hyperplane, eps: float = 1e-6) -> Tuple[Tensor, Tensor]:
        dot_prod = batched_dot_product(plane.normal.data, self.direction.data)
        dot_prod_mask = dot_prod.abs() >= eps
        res_lambda = where(
            dot_prod_mask,
            -(plane.offset + batched_dot_product(plane.normal.data, self.origin.data)) / dot_prod,
            torch.empty_like(dot_prod),
        )
        res_point = self.point_at(res_lambda)
        return res_lambda, res_point

class Inventory(object):
    _attrs = ['used', 'max_unit', 'step_size', 'min_unit', 'total']
    def __init__(self, resource_class, **kwargs):
        self.resource_class = resource_class
        allocation_ratio = kwargs['allocation_ratio']
        reserved = kwargs['reserved']
        for attr in self._attrs:
            try:
                if attr == 'total':
                    total = float(kwargs[attr] - reserved) * allocation_ratio
                    setattr(self, attr, total)
                    continue
                setattr(self, attr, float(kwargs[attr]))
            except KeyError:
                setattr(self, attr, 0.0)
        self.reserved = 0
    @property
    def free(self):
        return self.total - self.used
    @property
    def usage(self):
        if self.total:
            return self.used * 100 / self.total
        return 0
    @property
    def limit(self):
        return (self.total * CONF.aardvark.watermark) / 100
    @property
    def excessive(self):
        if self.usage <= CONF.aardvark.watermark:
            return 0
        else:
            return self.used + self.reserved - self.limit
    def __add__(self, other):
        kwargs = {
            'used': self.used + other.used,
            'reserved': self.reserved + other.reserved,
            'total': self.total + other.total,
        }
        return Inventory(self.resource_class, **kwargs)
    def __repr__(self):
        return self.to_str()
    def to_str(self):
        return "<Inventory: %s: total: %s , used: %s, usage: %s%%>" % (
            self.resource_class, self.total, self.used + self.reserved,
            self.usage)

