class Treap:
    class Iterator:
        def __init__(self, root):
            self.node = root
            self.stack = []
        def __next__(self):
            if self.node is None and not self.stack:
                raise StopIteration
            while self.node:
                self.stack.append(self.node)
                self.node = self.node.left
            self.node = self.stack.pop()
            item = self.node.data
            self.node = self.node.right
            return item
    def __iter__(self):
        return self.Iterator(self)
    def __build(arr,i,j):
        if i==j:
            return None
        mid=(i+j)//2
        treap=Treap(arr[mid])
        treap.left=Treap.__build(arr,i,mid)
        treap.right=Treap.__build(arr,mid+1,j)
        heapify(treap)
        return treap
    def build(arr):
        n=len(arr)
        for i in range(n-1):
            if arr[i]>arr[i+1]:
                raise ValueError('input not sorted')
        return Treap.__build(arr,0,n)
    def __init__(self, data):
        self.data = data
        self.priority = random()
        self.left = None
        self.right = None
    def __repr__(self):
        s = ''
        if self.left:
            s += str(self.left)
        s += str(self.data) + ' '
        if self.right:
            s += str(self.right)
        return s
    def height(self):
        def maxDepth(node):
            if node is None:
                return 0
            ldepth = maxDepth(node.left)
            rdepth = maxDepth(node.right)
            if ldepth > rdepth:
                return ldepth + 1
            else:
                return rdepth + 1
        return maxDepth(self)
    def inorder(self):
        def inorderUtil(node):
            if node:
                if node.left:
                    inorderUtil(node.left)
                print(node.data, end=' ')
                if node.right:
                    inorderUtil(node.right)
        inorderUtil(self)
        print()
    def preorder(self):
        def preorderUtil(node):
            if node:
                print(node.data, end=' ')
                if node.left:
                    preorderUtil(node.left)                
                if node.right:
                    preorderUtil(node.right)
        preorderUtil(self)
        print()
    def postorder(self):
        def postorderUtil(node):
            if node:
                if node.left:
                    postorderUtil(node.left)
                if node.right:
                    postorderUtil(node.right)
                print(node.data, end=' ')
        postorderUtil(self)
        print()
    def search(self, item):
        def searchUtil(root, item):
            if not root:
                return None
            if root.data == item:
                return root
            if item < root.data:
                return searchUtil(root.left, item)
            if item > root.data:
                return searchUtil(root.right, item)
        return searchUtil(self, item)

class TCell:
  thrift_spec = (
    None, 
    (1, TType.STRING, 'value', None, None, ), 
    (2, TType.I64, 'timestamp', None, None, ), 
  )
  def __init__(self, value=None, timestamp=None,):
    self.value = value
    self.timestamp = timestamp
  def read(self, iprot):
    if iprot.__class__ == TBinaryProtocol.TBinaryProtocolAccelerated and isinstance(iprot.trans, TTransport.CReadableTransport) and self.thrift_spec is not None and fastbinary is not None:
      fastbinary.decode_binary(self, iprot.trans, (self.__class__, self.thrift_spec))
      return
    iprot.readStructBegin()
    while True:
      (fname, ftype, fid) = iprot.readFieldBegin()
      if ftype == TType.STOP:
        break
      if fid == 1:
        if ftype == TType.STRING:
          self.value = iprot.readString();
        else:
          iprot.skip(ftype)
      elif fid == 2:
        if ftype == TType.I64:
          self.timestamp = iprot.readI64();
        else:
          iprot.skip(ftype)
      else:
        iprot.skip(ftype)
      iprot.readFieldEnd()
    iprot.readStructEnd()
  def write(self, oprot):
    if oprot.__class__ == TBinaryProtocol.TBinaryProtocolAccelerated and self.thrift_spec is not None and fastbinary is not None:
      oprot.trans.write(fastbinary.encode_binary(self, (self.__class__, self.thrift_spec)))
      return
    oprot.writeStructBegin('TCell')
    if self.value != None:
      oprot.writeFieldBegin('value', TType.STRING, 1)
      oprot.writeString(self.value)
