            except AssertionError:
                raise ValueError('Unable to convert between units of "%s" \
                                 and "%s"' % (from_u._dimensionality,
                                              to_u._dimensionality))
            signal = cf * self.magnitude
        new = self.__class__(signal=signal, units=to_u,
                             sampling_rate=self.sampling_rate)
        new._copy_data_complement(self)
        new.annotations.update(self.annotations)
        return new
    def duplicate_with_new_array(self, signal):
        new = self.__class__(signal=signal, units=self.units,
                             sampling_rate=self.sampling_rate)
        new._copy_data_complement(self)
        new.annotations.update(self.annotations)
        return new
    def __eq__(self, other):
        if (self.t_start != other.t_start or
                self.sampling_rate != other.sampling_rate):
            return False
        return super(AnalogSignal, self).__eq__(other)
    def __ne__(self, other):
        return not self.__eq__(other)
    def _check_consistency(self, other):
        if isinstance(other, AnalogSignal):
            for attr in "t_start", "sampling_rate":
                if getattr(self, attr) != getattr(other, attr):
                    raise ValueError("Inconsistent values of %s" % attr)
    def _copy_data_complement(self, other):
        for attr in ("t_start", "sampling_rate", "name", "file_origin",
                     "description", "annotations"):
            setattr(self, attr, getattr(other, attr, None))
    def _apply_operator(self, other, op, *args):
        self._check_consistency(other)
        f = getattr(super(AnalogSignal, self), op)
        new_signal = f(other, *args)
        new_signal._copy_data_complement(self)
        return new_signal
    def __add__(self, other, *args):
        return self._apply_operator(other, "__add__", *args)
    def __sub__(self, other, *args):
        return self._apply_operator(other, "__sub__", *args)
    def __mul__(self, other, *args):
        return self._apply_operator(other, "__mul__", *args)
    def __truediv__(self, other, *args):
        return self._apply_operator(other, "__truediv__", *args)
    def __div__(self, other, *args):
        return self._apply_operator(other, "__div__", *args)
    __radd__ = __add__
    __rmul__ = __sub__
    def __rsub__(self, other, *args):
        return self.__mul__(-1, *args) + other
    def _repr_pretty_(self, pp, cycle):
        pp.text("{cls} with {channels} channels of length {length}; "
                "units {units}; datatype {dtype} ".format(
                    cls=self.__class__.__name__,
                    channels=self.shape[1],
                    length=self.shape[0],
                    units=self.units.dimensionality.string,
                    dtype=self.dtype))
        if self._has_repr_pretty_attrs_():
            pp.breakable()
            self._repr_pretty_attrs_(pp, cycle)
        def _pp(line):
            pp.breakable()
            with pp.group(indent=1):
                pp.text(line)
        for line in ["sampling rate: {0}".format(self.sampling_rate),
                     "time: {0} to {1}".format(self.t_start, self.t_stop)
                     ]:
            _pp(line)
    def time_slice(self, t_start, t_stop):
        if t_start is None:
            i = 0
        else:
            t_start = t_start.rescale(self.sampling_period.units)
            i = (t_start - self.t_start) / self.sampling_period
            i = int(np.rint(i.magnitude))
        if t_stop is None:
            j = len(self)
        else:
            t_stop = t_stop.rescale(self.sampling_period.units)
            j = (t_stop - self.t_start) / self.sampling_period
            j = int(np.rint(j.magnitude))
        if (i < 0) or (j > len(self)):
            raise ValueError('t_start, t_stop have to be withing the analog \
                              signal duration')
        obj = super(AnalogSignal, self).__getitem__(np.arange(i, j, 1))
        obj.t_start = self.t_start + i * self.sampling_period
        return obj
    def merge(self, other):
        if self.sampling_rate != other.sampling_rate:
            raise MergeError("Cannot merge, different sampling rates")
        if self.t_start != other.t_start:
            raise MergeError("Cannot merge, different t_start")
        if self.segment != other.segment:
            raise MergeError("Cannot merge these two signals as they belong to different segments.")
        if hasattr(self, "lazy_shape"):
            if hasattr(other, "lazy_shape"):
                if self.lazy_shape[0] != other.lazy_shape[0]:
                    raise MergeError("Cannot merge signals of different length.")
                merged_lazy_shape = (self.lazy_shape[0], self.lazy_shape[1] + other.lazy_shape[1])
            else:
                raise MergeError("Cannot merge a lazy object with a real object.")
        if other.units != self.units:
            other = other.rescale(self.units)
        stack = np.hstack(map(np.array, (self, other)))
        kwargs = {}
        for name in ("name", "description", "file_origin"):
            attr_self = getattr(self, name)
            attr_other = getattr(other, name)
            if attr_self == attr_other:
                kwargs[name] = attr_self
            else:
                kwargs[name] = "merge(%s, %s)" % (attr_self, attr_other)
        merged_annotations = merge_annotations(self.annotations,
                                               other.annotations)
        kwargs.update(merged_annotations)
        signal = AnalogSignal(stack, units=self.units, dtype=self.dtype,
                              copy=False, t_start=self.t_start,
                              sampling_rate=self.sampling_rate,
                              **kwargs)
        signal.segment = self.segment
        if self.channel_index and other.channel_index:
            signal.channel_index = ChannelIndex(
                    index=np.arange(signal.shape[1]),
                    channel_ids=np.hstack([self.channel_index.channel_ids,
                                           other.channel_index.channel_ids]),
                    channel_names=np.hstack([self.channel_index.channel_names,
                                             other.channel_index.channel_names]))
        else:
            signal.channel_index = ChannelIndex(index=np.arange(signal.shape[1]))
        if hasattr(self, "lazy_shape"):
            signal.lazy_shape = merged_lazy_shape
        return signal

class Frame(Primitive):
    def __init__(self, point, xaxis, yaxis):
        self._point = None
        self._xaxis = None
        self._yaxis = None
        self.point = point
        self.xaxis = xaxis
        self.yaxis = yaxis
    @classmethod
    def worldXY(cls):
        return cls([0, 0, 0], [1, 0, 0], [0, 1, 0])
    @classmethod
    def worldZX(cls):
        return cls([0, 0, 0], [0, 0, 1], [1, 0, 0])
    @classmethod
    def worldYZ(cls):
        return cls([0, 0, 0], [0, 1, 0], [0, 0, 1])
    @classmethod
    def from_points(cls, point, point_xaxis, point_xyplane):
        xaxis = subtract_vectors(point_xaxis, point)
        xyvec = subtract_vectors(point_xyplane, point)
        yaxis = cross_vectors(cross_vectors(xaxis, xyvec), xaxis)
        return cls(point, xaxis, yaxis)
    @classmethod
    def from_rotation(cls, rotation, point=[0, 0, 0]):
        xaxis, yaxis = rotation.basis_vectors
        return cls(point, xaxis, yaxis)
    @classmethod
    def from_transformation(cls, transformation):
        xaxis, yaxis = transformation.basis_vectors
        point = transformation.translation
        return cls(point, xaxis, yaxis)
    @classmethod
    def from_matrix(cls, matrix):
        sc, sh, a, point, p = decompose_matrix(matrix)
        R = matrix_from_euler_angles(a, static=True, axes='xyz')
        xaxis, yaxis = basis_vectors_from_matrix(R)
        return cls(point, xaxis, yaxis)
    @classmethod
    def from_list(cls, values):
        if len(values) == 12:
            values.extend([0., 0., 0., 1.])
        if len(values) != 16:
            raise ValueError(
                'Expected 12 or 16 floats but got %d' %
                len(values))
        matrix = [[0. for i in range(4)] for j in range(4)]
        for i in range(4):
            for j in range(4):
                matrix[i][j] = float(values[i * 4 + j])
        return cls.from_matrix(matrix)
    @classmethod
    def from_quaternion(cls, quaternion, point=[0, 0, 0]):
        R = matrix_from_quaternion(quaternion)
        xaxis, yaxis = basis_vectors_from_matrix(R)
        return cls(point, xaxis, yaxis)
    @classmethod
    def from_axis_angle_vector(cls, axis_angle_vector, point=[0, 0, 0]):
        R = matrix_from_axis_angle_vector(axis_angle_vector)
        xaxis, yaxis = basis_vectors_from_matrix(R)
        return cls(point, xaxis, yaxis)
    @classmethod
    def from_euler_angles(cls, euler_angles, static=True,
                          axes='xyz', point=[0, 0, 0]):
        R = matrix_from_euler_angles(euler_angles, static, axes)
        xaxis, yaxis = basis_vectors_from_matrix(R)
        return cls(point, xaxis, yaxis)
    @classmethod
    def from_data(cls, data):
        frame = cls.worldXY()
        frame.data = data
        return frame
    @classmethod
    def from_plane(cls, plane):
        d = Vector(*plane.point).dot(plane.normal)
        coeffs = list(plane.normal)  
        coeffs_abs = [math.fabs(x) for x in coeffs]
        idx = coeffs_abs.index(max(coeffs_abs))
        coords = [0, 0, 0]  
        v = d/coeffs[idx]
        coords[idx] = v
        pt1_in_plane = Point(*coords)
        coords = [1, 1, 1]  
        coords[idx] = 0
        v = (d - sum([a*x for a, x in zip(coeffs, coords)]))/coeffs[idx]
        coords[idx] = v
        pt2_in_plane = Point(*coords)
        xaxis = pt2_in_plane - pt1_in_plane
        yaxis = plane.normal.cross(xaxis)
        return cls(plane.point, xaxis, yaxis)
    @property
    def point(self):
        return self._point
    @point.setter
    def point(self, point):
        self._point = Point(*point)
    @property
    def xaxis(self):
        return self._xaxis
    @xaxis.setter
    def xaxis(self, vector):
        xaxis = Vector(*vector)
        xaxis.unitize()
        self._xaxis = xaxis
    @property
    def yaxis(self):
        return self._yaxis
    @yaxis.setter
    def yaxis(self, vector):
        yaxis = Vector(*vector)
        yaxis.unitize()
        zaxis = Vector.cross(self.xaxis, yaxis)
        zaxis.unitize()
        self._yaxis = Vector.cross(zaxis, self.xaxis)
    @property
    def data(self):
        return {'point': list(self.point),
                'xaxis': list(self.xaxis),
                'yaxis': list(self.yaxis)}
    @data.setter
    def data(self, data):
        self.point = data['point']
        self.xaxis = data['xaxis']
        self.yaxis = data['yaxis']
    @property
    def normal(self):
        return Vector(*cross_vectors(self.xaxis, self.yaxis))
    @property
    def zaxis(self):
        return self.normal
    @property
    def quaternion(self):
        rotation = matrix_from_basis_vectors(self.xaxis, self.yaxis)
        return Quaternion(*quaternion_from_matrix(rotation))
    @property
    def axis_angle_vector(self):
        R = matrix_from_basis_vectors(self.xaxis, self.yaxis)
        return Vector(*axis_angle_vector_from_matrix(R))
    def __repr__(self):
        return "Frame({0}, {1}, {2})".format(self.point, self.xaxis, self.yaxis)
    def __len__(self):
        return 3
    def __getitem__(self, key):
        if key == 0:
            return self.point
        if key == 1:
            return self.xaxis
        if key == 2:
            return self.yaxis
        raise KeyError
    def __setitem__(self, key, value):
        if key == 0:
            self.point = value
            return
        if key == 1:
            self.xaxis = value
            return
        if key == 2:
            self.yaxis = value
        raise KeyError
    def __iter__(self):
        return iter([self.point, self.xaxis, self.yaxis])
    def __eq__(self, other, tol=1e-05):
        for v1, v2 in zip(self, other):
            for a, b in zip(v1, v2):
                if math.fabs(a - b) > tol:
                    return False
        return True
    def copy(self):
        cls = type(self)
        return cls(self.point.copy(), self.xaxis.copy(), self.yaxis.copy())
    def euler_angles(self, static=True, axes='xyz'):
        R = matrix_from_basis_vectors(self.xaxis, self.yaxis)
        return euler_angles_from_matrix(R, static, axes)
    def to_local_coords(self, object_in_wcf):
        T = Transformation.change_basis(Frame.worldXY(), self)
        if isinstance(object_in_wcf, list):
            return Point(*object_in_wcf).transformed(T)
        else:
            return object_in_wcf.transformed(T)
    def to_world_coords(self, object_in_lcs):
        T = Transformation.change_basis(self, Frame.worldXY())
        if isinstance(object_in_lcs, list):
            return Point(*object_in_lcs).transformed(T)
        else:
            return object_in_lcs.transformed(T)
    @staticmethod
    def local_to_local_coords(frame1, frame2, object_in_frame1):
        T = Transformation.change_basis(frame1, frame2)
        if isinstance(object_in_frame1, list):
            return Point(*object_in_frame1).transformed(T)
        else:
            return object_in_frame1.transformed(T)
    def transform(self, transformation):
        T = transformation * Transformation.from_frame(self)
        point = T.translation
        xaxis, yaxis = T.basis_vectors
        self.point = point
        self.xaxis = xaxis
        self.yaxis = yaxis
    def transformed(self, transformation):
        frame = self.copy()
        frame.transform(transformation)
        return frame

class Person(MutableMapping):
    REGEXP_ORCID_ID = re.compile(r"^(\d{4}-){3}\d{3}(\d|X)$")
    REGEXP_EMAIL = re.compile(r"^[\w\.+-]+@([\w-]+\.)+[\w-]{2,}$")
    def __init__(self, person: str=None, **kwargs):
        attrs = Person.parse(person) if person else {}
        if kwargs.get("fullname"):
            attrs.update(Person.parse(kwargs["fullname"]))
        attrs.update(kwargs)
        if not attrs.get("fullname") and attrs.get("name") and attrs.get("surname"):
            attrs["fullname"] = (attrs["name"] + " " + attrs["surname"]).strip()
        for key, val in attrs.items():
            if bool(val) or isinstance(val, (bool, int, float)):
                self.__dict__[key] = val
    def __setitem__(self, key, val):
        if bool(val) or isinstance(val, (bool, int, float)):
            self.__dict__[key] = val
        elif key in self.__dict__:
            del self.__dict__[key]
    def __getitem__(self, key):
        return self.__dict__[key]
    def __delitem__(self, key):
        del self.__dict__[key]
    def __iter__(self):
        return iter(self.__dict__)
    def __len__(self):
        return len(self.__dict__)
    def __str__(self):
        return str(self.__dict__)
    def __repr__(self):
        return f"Person({self.__dict__})"
    @classmethod
    def parse(cls, person: str) -> Dict:
        person = person.strip()
        if re.match(Person.REGEXP_ORCID_ID, person):
            return {"orcid_id": person}
        if re.match(Person.REGEXP_EMAIL, person):
            return {"email": person}
        attrs = {"fullname": person}
        parts = [part.strip() for part in person.split(",")]
        if len(parts) == 2:
            attrs["surname"], attrs["name"] = parts
        return attrs
    @staticmethod
    def get_orcid_token(client_id: str=None, client_secret: str=None) -> str:
        config = fairly.get_config("fairly")
        if not client_id:
            client_id = config.get("orcid_client_id")
            if not client_id:
                raise ValueError("No client id")
        if not client_secret:
            client_secret = config.get("orcid_client_secret")
            if not client_secret:
                raise ValueError("No client secret")
        response = requests.post(
            "https://orcid.org/oauth/token",
            data=f"client_id={client_id}&client_secret={client_secret}&grant_type=client_credentials&scope=/read-public",
            headers={
                "Accept": "application/json",
                "Content-Type": "application/x-www-form-urlencoded",
            }
        )
        json = response.json()
        if "access_token" not in json:
            raise ValueError("Invalid response")
        return json["access_token"]
    @staticmethod
    def from_orcid_id(orcid_id: str, token: str=None) -> Person:
        if not token:
            config = fairly.get_config("fairly")
            token = config.get("orcid_token")
            if not token:
                try:
                    token = Person.get_orcid_token()
                except:
                    raise ValueError("No access token")
        fields = ",".join(["orcid", "email", "given-names", "family-name", "current-institution-affiliation-name"])
        response = requests.get(
            f"https://pub.orcid.org/v3.0/expanded-search/?q=orcid:{orcid_id}&fl={fields}",
            headers={
                "Content-type": "application/vnd.orcid+json",
                "Authorization type and Access token": f"Bearer {token}"
            }
        )
        results = response.json().get("expanded-result")
        if not results:
            raise ValueError("Invalid ORCID Id")
        result = results[0]
        return Person(
            orcid_id=result.get("orcid-id"),
            name=result.get("given-names"),
            surname=result.get("family-names"),
            email=result.get("email"),
            institution=result["institution-name"][0] if result.get("institution-name") else None
        )
    @staticmethod
    def get_persons(people) -> List[Person]:
        if not people:
            return PersonList()
        if isinstance(people, str):
            people = re.split(r"[;\n]", people)
        if not isinstance(people, Iterable):
            raise ValueError
        persons = PersonList()
        for item in people:
            if not item:
                continue
            if isinstance(item, Person):
                person = copy.copy(item)
            else:
                if isinstance(item, str):
                    item = Person.parse(item)
                if not isinstance(item, Dict):
                    raise ValueError
                person = Person(**item)
            persons.append(person)
        return persons
    def autocomplete(self, overwrite: bool=False, orcid_token: str=None) -> Dict:
        if not self.get("orcid_id"):
            return {}
        person = Person.from_orcid_id(self["orcid_id"], token=orcid_token)
        updated = {}
        for key, val in person.__dict__.items():
            if key not in self.__dict__ or overwrite:
                self.__dict__[key] = updated[key] = val
        return updated
    def serialize(self) -> Dict:
        return self.__dict__.copy()

class Prestamo:
    prestamos = []
    def __init__(self, lector, libro):
        self.__lector = lector
        if libro.prestado() is False:   
            self.__libro = libro
            self.__libro.set_prestado(True)
            self.__fecha_prestamo = datetime.today()
            self.__fecha_devolucion = None
            Prestamo.prestamos.append(self)
        else:
            print('Lo sentimos, pero el libro "'+libro.titulo()+'" se encuentra en préstamo.')
    def __repr__(self):
        return f'Prestamo (Lector: {self.__lector}, Libro: {self.__libro}, Fecha préstamo: {self.__fecha_prestamo}, Fecha devolución: {self.__fecha_devolucion})'
    def lector(self):
        return self.__lector
    def libro(self):
        return self.__libro
    def fecha_prestamo(self):
        return self.__fecha_prestamo
    def fecha_devolucion(self):
        return self.__fecha_devolucion
    def set_fecha_devolucion(self, fecha):
        self.__fecha_devolucion = fecha
    def devolver_libro(self, fecha):
        self.set_fecha_devolucion(fecha)
        self.libro().set_prestado(False)
        diferencia = abs(self.fecha_devolucion() - self.fecha_prestamo()).days
        if diferencia > 15:
            self.lector().set_moroso(True)

