class Community_cards:
    def __init__(self):
        self.cards = []
    def __repr__(self):
        if len(self.cards) == 0:
            return "\n\n\n\n\n\n\n\nPre-flop"
        if len(self.cards) == 3:
            return show_cards(self.cards) + "\nFlop"
