class RangeProduct(object):
    __slots__ = ('range_lists',)
    def __init__(self, range_lists):
        self.range_lists = range_lists
        assert range_lists.__class__ is list
        for subrange in range_lists:
            assert subrange.__class__ is list
    def __str__(self):
        return "<" + ', '.join(
            str(tuple(_)) if len(_) > 1 else str(_[0])
            for _ in self.range_lists
        )+">"
    __repr__ = __str__
    def __eq__(self, other):
        return isinstance(other, RangeProduct) \
            and self.range_difference([other]) == [] \
            and other.range_difference([self]) == []
    def __ne__(self, other):
        return not self.__eq__(other)
    def __contains__(self, value):
        if not isinstance(value, Sequence):
            return False
        if len(value) != len(self.range_lists):
            return False
        return all(any(val in rng for rng in rng_list)
                   for val, rng_list in zip(value, self.range_lists))
    def __getstate__(self):
        state = {} 
        for i in RangeProduct.__slots__:
            state[i] = getattr(self, i)
        return state
    def __setstate__(self, state):
        for key, val in state.items():
            object.__setattr__(self, key, val)
    def isdiscrete(self):
        return all(all(rng.isdiscrete() for rng in rng_list)
                   for rng_list in self.range_lists)
    def isfinite(self):
        return all(all(rng.isfinite() for rng in rng_list)
                   for rng_list in self.range_lists)
    def isdisjoint(self, other):
        if type(other) is AnyRange:
            return False
        if type(other) is not RangeProduct:
            return True
        if len(other.range_lists) != len(self.range_lists):
            return True
        for s, o in zip(self.range_lists, other.range_lists):
            if all(s_rng.isdisjoint(o_rng) for s_rng in s for o_rng in o):
                return True
        return False
    def issubset(self, other):
        if type(other) is AnyRange:
            return True
        return not any(_ for _ in self.range_difference([other]))
    def range_difference(self, other_ranges):
        ans = [self]
        N = len(self.range_lists)
        for other in other_ranges:
            if type(other) is AnyRange:
                return []
            if type(other) is not RangeProduct or len(other.range_lists) != N:
                continue
            tmp = []
            for rp in ans:
                if rp.isdisjoint(other):
                    tmp.append(rp)
                    continue
                for dim in range(N):
                    remainder = []
                    for r in rp.range_lists[dim]:
                        remainder.extend(
                            r.range_difference(other.range_lists[dim]))
                    if remainder:
                        tmp.append(RangeProduct(list(rp.range_lists)))
                        tmp[-1].range_lists[dim] = remainder
            ans = tmp
        return ans
    def range_intersection(self, other_ranges):
        ans = list(self.range_lists)
        N = len(self.range_lists)
        for other in other_ranges:
            if type(other) is AnyRange:
                continue
            if type(other) is not RangeProduct or len(other.range_lists) != N:
                return []
            for dim in range(N):
                tmp = []
                for r in ans[dim]:
                    tmp.extend(r.range_intersection(other.range_lists[dim]))
                if not tmp:
                    return []
                ans[dim] = tmp
        return [RangeProduct(ans)]

class SparseGate(nn.Module):
    def __init__(self, channel_num: int):
        super().__init__()
        self._conv = nn.Conv2d(in_channels=channel_num,
                               out_channels=channel_num,
                               kernel_size=1,
                               groups=channel_num,
                               bias=False)
        nn.init.constant_(self.weight, 1)
        self._channel_num = channel_num
    def forward(self, x):
        return self._conv(x)
    @property
    def weight(self) -> torch.nn.Parameter:
        return self._conv.weight
    def clamp(self, upper_bound=1., lower_bound=0.):
        self.weight.data.clamp_(lower_bound, upper_bound)
    def prune(self, idx: np.ndarray) -> None:
        assert len(idx.shape) == 1, f"channel index is supposed to be a 1-d vector, got shape {idx.shape}"
        self.weight.data = self.weight.data[idx.tolist(), :, :, :].clone()
        self._conv.in_channels = len(idx)
        self._conv.out_channels = len(idx)
        self._conv.groups = len(idx)
        pass
    def set_ones(self):
        self._conv.weight.data = torch.ones_like(self._conv.weight)
    def do_pruning(self, mask: np.ndarray):
        idx = np.squeeze(np.argwhere(np.asarray(mask)))
        if len(idx.shape) == 0:
            idx = np.expand_dims(idx, 0)
        elif len(idx.shape) == 1 and idx.shape[0] == 0:
            raise NotImplementedError("No layer left in input channel")
        self._channel_num = len(idx)
        self._conv.weight.data = self._conv.weight.data.clone()[idx.tolist(), :, :, :]
        self._conv.in_channels = self._channel_num
        self._conv.out_channels = self._channel_num
        self._conv.groups = self._channel_num
    def __repr__(self):
        return f"SparseGate(channel_num={self._channel_num})"
        pass

