class raw_values_class:
    def __init__(self,filename,log_filename,log_lines,simulation_command):
        self.raw_filename = filename.replace(".net",".raw")
        self.log_filename = log_filename
        self.log_lines = log_lines
        self.name = remove_path_from_name(self.raw_filename)
        self.simulation_command = simulation_command
        self.node_values = "undefined" 
        self.read_in_file()
    def __repr__(self):
        return(self.name)
    def __str__(self):
        return(self.name)
    def read_in_file(self):
        file = open(self.raw_filename,"r")
        self.raw_file_lines = file.readlines()
        file.close()
        start_nodes = False
        start_values = False
        value_count = 0
        node_values = []
        for line in self.raw_file_lines:
            line=line.rstrip()
            if "Variables:" in line:
                if "No. Variables" not in line:
                    start_nodes = True
            elif "Values:" in line:
                start_nodes = False
                start_values = True
            elif start_nodes == True:
                node_value_pair = pull_node(line)
                node_values.append(copy.deepcopy(node_value_pair))
            elif start_values == True:
                if pull_step_number(line) != False:
                    step_number = pull_step_number
                    value_count = 0
                value = pull_value(line)
                node_values[value_count].values.append(value)
                value_count += 1
        if self.simulation_command.command_type != "operating point":
            self.independent_node = node_values[0]
        else:
            self.independent_node = "operating point"
        node_dictionary = {}
        for node_value in node_values:
            node_dictionary[node_value.node] = node_value
        self.node_values = node_dictionary
    def return_node_value(self,name,name_type="node"):
        if name_type == "node":
            name = name.lower()
        elif name_type == "device":
            name = name.capitalize()
        else:
            print("Invalid name_type for return_node_value")
            sys.exit(0)
        node_value = self.node_values[name]
        return(node_value)
    def find_node_value_at_independet_value(self,given_independent_value,given_node):
        return_values = find_value_in_list(given_independent_value,self.independent_node.values)
        actual_independent_value = return_values[0]
        given_node_value = given_node.values[return_values[1]]
        return((actual_independent_value,given_node_value))

class Schedule(object):
    MIN_WGT_PER_HR = 8
    def __init__(self, hours=0, mode=1, tasks=[]):
        self.hours = hours
        self.mode = mode
        self.tasks = tasks
    def _get_tasks_per_day(self):
        dates = {}
        for task in self.tasks:
            date_dct = dates.get(task.due, {"hours": 0, "tasks": []})
            date_dct["hours"] += task.time
            date_dct["tasks"].append(task)
            dates[task.due] = date_dct
        return dates
    def _get_quadrants(self):
        quadrants = {i: [] for i in range(1,5)}
        def add_quad(task, quad):
            task.quad = quad
            quadrants[quad].append(task)
        for task in self.tasks:
            if task.weight_per_hr >= self.MIN_WGT_PER_HR and task.urgency > 0:
                add_quad(task, 1)
            elif task.weight_per_hr >= self.MIN_WGT_PER_HR:
                add_quad(task, 2)
            elif task.urgency > 0:
                add_quad(task, 3)
            else:
                add_quad(task, 4)
        for i in quadrants:
            quadrants[i].sort(
                key=lambda task: (task.weight_per_hr, task.urgency),
                reverse=True)
        return quadrants
    def _format_todos(self):
        quadrants = self._get_quadrants() 
        tasks = []
        total_time = 0
        msg = ["\n\nTO DO:"]
        for i, task in enumerate(quadrants[1] + quadrants[2]):
            short = task.time < 1
            if self.mode == 1 or (self.mode == 2 and short) or (self.mode == 3
                    and not short):
                total_time += task.time
                tasks.append(task)
                msg.append("\n{}. ".format(i + 1) + task.get_msg())
            if total_time >= self.hours:
                break
        other_tasks = quadrants[3] + quadrants[4]
        if other_tasks:
            msg.append(("\n{}. Delegate or delete the following unimportant " + 
                "tasks: ").format(len(tasks) + 1))
            for task in other_tasks:
                short_msg = "\t- {desc} (quadrant {quad})".format(
                    desc=task.description,
                    quad=task.quad)
                msg.append(short_msg)
        return "\n".join(msg)
    def _format_future_todos(self):
        msg = ["\n\nWORK DUE IN UPCOMING DAYS:"]
        dates = sorted(self._get_tasks_per_day().items(), key=lambda tup: tup[0])
        for date, date_dct in dates:
            date_msg = [
                "* {date} - {hrs} HOURS".format(
                    date=date.strftime("%a %b %d"),
                    hrs=date_dct["hours"])
            ]
            date_tasks = sorted(date_dct["tasks"], 
                key=lambda task: (task.weight_per_hr, task.time),
                reverse=True)
            for task in date_tasks:
                date_msg.append(
                    "\t* ({time} hrs) {desc} - ${wgt}/hr".format(
                        desc=task.description,
                        time=task.time,
                        wgt=round(task.weight_per_hr, 2))
                )
            msg.append("\n".join(date_msg))
        return "\n\n".join(msg)
    def print_all(self):
        print("\nDATE: {}".format(date.today()))
        print(self._format_todos())
        print(self._format_future_todos())
    def __repr__(self):
        msg = ["Schedule: {} hrs | {} mode | {} median wph".format(
            self.hours,
            self.mode,
            self.median_wph)]
        for task in self.tasks:
            msg.append(task.__repr__())
        return "\n".join(msg)

