class LinkedList(object):
    def __init__(self, items=None):
        self.head = None  
        self.tail = None  
        if items is not None:
            for item in items:
                self.append(item)
    def __str__(self):
        items = ['({!r})'.format(item) for item in self.items()]
        return '[{}]'.format(' -> '.join(items))
    def __repr__(self):
        return 'LinkedList({!r})'.format(self.items())
    def items(self):
        items = []  
        node = self.head  
        while node is not None:  
            items.append(node.data)  
            node = node.next  
        return items  
    def is_empty(self):
        return self.head is None
    def length(self):
        counter = 0
        node = self.head  
        while node is not None:  
            counter+=1  
            node = node.next  
        return counter
    def append(self, item):
        node = Node(item)
        if not self.head:
            self.head = node
        else: 
            current = self.head
            while current.next:
                current = current.next
            current.next = node
    def prepend(self, item):
        node = Node(item)
        node.next = self.head
        self.head = node
    def find(self, quality):
        current = self.head
        while current.data != quality(current.data):
            if current.next:
                current = current.next
            else:
                return ('dne')
        return current.data
    def delete(self, item):
        current = self.head
        prev = None
        found = False
        while not found and current: 
            if current.data != item:
                prev = current
                current = current.next
            else:
                found = True
        if current == None:
            return ValueError('Item not found: {}'.format(item))
        elif prev == None:
            self.head = current.next
        else:
            prev.next = current.next
        return

class _AxesBase(martist.Artist):
    name = "rectilinear"
    _axis_names = ("x", "y")  
    _shared_axes = {name: cbook.Grouper() for name in _axis_names}
    _twinned_axes = cbook.Grouper()
    def __str__(self):
        return "{0}({1[0]:g},{1[1]:g};{1[2]:g}x{1[3]:g})".format(
            type(self).__name__, self._position.bounds)
    @_api.make_keyword_only("3.4", "facecolor")
    def __init__(self, fig, rect,
                 facecolor=None,  
                 frameon=True,
                 sharex=None,  
                 sharey=None,  
                 label='',
                 xscale=None,
                 yscale=None,
                 box_aspect=None,
                 **kwargs
                 ):
        super().__init__()
        if isinstance(rect, mtransforms.Bbox):
            self._position = rect
        else:
            self._position = mtransforms.Bbox.from_bounds(*rect)
        if self._position.width < 0 or self._position.height < 0:
            raise ValueError('Width and height specified must be non-negative')
        self._originalPosition = self._position.frozen()
        self.axes = self
        self._aspect = 'auto'
        self._adjustable = 'box'
        self._anchor = 'C'
        self._stale_viewlims = {name: False for name in self._axis_names}
        self._sharex = sharex
        self._sharey = sharey
        self.set_label(label)
        self.set_figure(fig)
        self.set_box_aspect(box_aspect)
        self._axes_locator = None  
        self._colorbars = []
        self.spines = mspines.Spines.from_dict(self._gen_axes_spines())
        self._init_axis()
        if facecolor is None:
            facecolor = mpl.rcParams['axes.facecolor']
        self._facecolor = facecolor
        self._frameon = frameon
        self.set_axisbelow(mpl.rcParams['axes.axisbelow'])
        self._rasterization_zorder = None
        self.cla()
        self.fmt_xdata = None
        self.fmt_ydata = None
        self.set_navigate(True)
        self.set_navigate_mode(None)
        if xscale:
            self.set_xscale(xscale)
        if yscale:
            self.set_yscale(yscale)
        self.update(kwargs)
        for name, axis in self._get_axis_map().items():
            axis.callbacks._pickled_cids.add(
                axis.callbacks.connect(
                    'units', self._unit_change_handler(name)))
        rcParams = mpl.rcParams
        self.tick_params(
            top=rcParams['xtick.top'] and rcParams['xtick.minor.top'],
            bottom=rcParams['xtick.bottom'] and rcParams['xtick.minor.bottom'],
            labeltop=(rcParams['xtick.labeltop'] and
                      rcParams['xtick.minor.top']),
            labelbottom=(rcParams['xtick.labelbottom'] and
                         rcParams['xtick.minor.bottom']),
            left=rcParams['ytick.left'] and rcParams['ytick.minor.left'],
            right=rcParams['ytick.right'] and rcParams['ytick.minor.right'],
            labelleft=(rcParams['ytick.labelleft'] and
                       rcParams['ytick.minor.left']),
            labelright=(rcParams['ytick.labelright'] and
                        rcParams['ytick.minor.right']),
            which='minor')
        self.tick_params(
            top=rcParams['xtick.top'] and rcParams['xtick.major.top'],
            bottom=rcParams['xtick.bottom'] and rcParams['xtick.major.bottom'],
            labeltop=(rcParams['xtick.labeltop'] and
                      rcParams['xtick.major.top']),
            labelbottom=(rcParams['xtick.labelbottom'] and
                         rcParams['xtick.major.bottom']),
            left=rcParams['ytick.left'] and rcParams['ytick.major.left'],
            right=rcParams['ytick.right'] and rcParams['ytick.major.right'],
            labelleft=(rcParams['ytick.labelleft'] and
                       rcParams['ytick.major.left']),
            labelright=(rcParams['ytick.labelright'] and
                        rcParams['ytick.major.right']),
            which='major')
    def __getstate__(self):
        state = super().__getstate__()
        state["_shared_axes"] = {
            name: self._shared_axes[name].get_siblings(self)
            for name in self._axis_names if self in self._shared_axes[name]}
        state["_twinned_axes"] = (self._twinned_axes.get_siblings(self)
                                  if self in self._twinned_axes else None)
        return state
    def __setstate__(self, state):
        shared_axes = state.pop("_shared_axes")
        for name, shared_siblings in shared_axes.items():
            self._shared_axes[name].join(*shared_siblings)
        twinned_siblings = state.pop("_twinned_axes")
        if twinned_siblings:
            self._twinned_axes.join(*twinned_siblings)
        self.__dict__ = state
        self._stale = True
    def __repr__(self):
        fields = []
        if self.get_label():
            fields += [f"label={self.get_label()!r}"]
        titles = []
        for k in ["left", "center", "right"]:
            title = self.get_title(loc=k)
            if title:
                titles.append(f"{k!r}:{title!r}")
        if titles:
            fields += ["title={" + ",".join(titles) + "}"]
        if self.get_xlabel():
            fields += [f"xlabel={self.get_xlabel()!r}"]
        if self.get_ylabel():
            fields += [f"ylabel={self.get_ylabel()!r}"]
        return f"<{self.__class__.__name__}:" + ", ".join(fields) + ">"
    def get_window_extent(self, *args, **kwargs):
        return self.bbox
    def _init_axis(self):
        self.xaxis = maxis.XAxis(self)
        self.spines.bottom.register_axis(self.xaxis)
        self.spines.top.register_axis(self.xaxis)
        self.yaxis = maxis.YAxis(self)
        self.spines.left.register_axis(self.yaxis)
        self.spines.right.register_axis(self.yaxis)
        self._update_transScale()
    def set_figure(self, fig):
        super().set_figure(fig)
        self.bbox = mtransforms.TransformedBbox(self._position,
                                                fig.transSubfigure)
        self.dataLim = mtransforms.Bbox.null()
        self._viewLim = mtransforms.Bbox.unit()
        self.transScale = mtransforms.TransformWrapper(
            mtransforms.IdentityTransform())
        self._set_lim_and_transforms()
    def _unstale_viewLim(self):
        need_scale = {
            name: any(ax._stale_viewlims[name]
                      for ax in self._shared_axes[name].get_siblings(self))
            for name in self._axis_names}
        if any(need_scale.values()):
            for name in need_scale:
                for ax in self._shared_axes[name].get_siblings(self):
                    ax._stale_viewlims[name] = False
            self.autoscale_view(**{f"scale{name}": scale
                                   for name, scale in need_scale.items()})
    @property
    def viewLim(self):
        self._unstale_viewLim()
        return self._viewLim
    def _request_autoscale_view(self, tight=None, **kwargs):
        want_scale = {name: True for name in self._axis_names}
        for k, v in kwargs.items():  
            if k.startswith("scale"):
                name = k[5:]
                if name in want_scale:
                    want_scale[name] = v
                    continue
            raise TypeError(
                f"_request_autoscale_view() got an unexpected argument {k!r}")
        if tight is not None:
            self._tight = tight
        for k, v in want_scale.items():
            if v:
                self._stale_viewlims[k] = True  
    def _set_lim_and_transforms(self):
        self.transAxes = mtransforms.BboxTransformTo(self.bbox)
        self.transScale = mtransforms.TransformWrapper(
            mtransforms.IdentityTransform())
        self.transLimits = mtransforms.BboxTransformFrom(
            mtransforms.TransformedBbox(self._viewLim, self.transScale))
        self.transData = self.transScale + (self.transLimits + self.transAxes)
        self._xaxis_transform = mtransforms.blended_transform_factory(
            self.transData, self.transAxes)
        self._yaxis_transform = mtransforms.blended_transform_factory(
            self.transAxes, self.transData)
    def get_xaxis_transform(self, which='grid'):
        if which == 'grid':
            return self._xaxis_transform
        elif which == 'tick1':
            return self.spines.bottom.get_spine_transform()
        elif which == 'tick2':
            return self.spines.top.get_spine_transform()
        else:
            raise ValueError('unknown value for which')
    def get_xaxis_text1_transform(self, pad_points):
        labels_align = mpl.rcParams["xtick.alignment"]
        return (self.get_xaxis_transform(which='tick1') +
                mtransforms.ScaledTranslation(0, -1 * pad_points / 72,
                                              self.figure.dpi_scale_trans),
                "top", labels_align)
    def get_xaxis_text2_transform(self, pad_points):
        labels_align = mpl.rcParams["xtick.alignment"]
        return (self.get_xaxis_transform(which='tick2') +
                mtransforms.ScaledTranslation(0, pad_points / 72,
                                              self.figure.dpi_scale_trans),
                "bottom", labels_align)
    def get_yaxis_transform(self, which='grid'):
        if which == 'grid':
            return self._yaxis_transform
        elif which == 'tick1':
            return self.spines.left.get_spine_transform()
        elif which == 'tick2':
            return self.spines.right.get_spine_transform()
        else:
            raise ValueError('unknown value for which')
    def get_yaxis_text1_transform(self, pad_points):
        labels_align = mpl.rcParams["ytick.alignment"]
        return (self.get_yaxis_transform(which='tick1') +
                mtransforms.ScaledTranslation(-1 * pad_points / 72, 0,
                                              self.figure.dpi_scale_trans),
                labels_align, "right")
    def get_yaxis_text2_transform(self, pad_points):
        labels_align = mpl.rcParams["ytick.alignment"]
        return (self.get_yaxis_transform(which='tick2') +
                mtransforms.ScaledTranslation(pad_points / 72, 0,
                                              self.figure.dpi_scale_trans),
                labels_align, "left")
    def _update_transScale(self):
        self.transScale.set(
            mtransforms.blended_transform_factory(
                self.xaxis.get_transform(), self.yaxis.get_transform()))
        for line in getattr(self, "_children", []):  
            if not isinstance(line, mlines.Line2D):
                continue
            try:
                line._transformed_path.invalidate()
            except AttributeError:
                pass
    def get_position(self, original=False):
        if original:
            return self._originalPosition.frozen()
        else:
            locator = self.get_axes_locator()
            if not locator:
                self.apply_aspect()
            return self._position.frozen()
    def set_position(self, pos, which='both'):
        self._set_position(pos, which=which)
        self.set_in_layout(False)
    def _set_position(self, pos, which='both'):
        if not isinstance(pos, mtransforms.BboxBase):
            pos = mtransforms.Bbox.from_bounds(*pos)
        for ax in self._twinned_axes.get_siblings(self):
            if which in ('both', 'active'):
                ax._position.set(pos)
            if which in ('both', 'original'):
                ax._originalPosition.set(pos)
        self.stale = True
    def reset_position(self):
        for ax in self._twinned_axes.get_siblings(self):
            pos = ax.get_position(original=True)
            ax.set_position(pos, which='active')
    def set_axes_locator(self, locator):
        self._axes_locator = locator
        self.stale = True
    def get_axes_locator(self):
        return self._axes_locator
    def _set_artist_props(self, a):
        a.set_figure(self.figure)
        if not a.is_transform_set():
            a.set_transform(self.transData)
        a.axes = self
        if a.mouseover:
            self._mouseover_set.add(a)
    def _gen_axes_patch(self):
        return mpatches.Rectangle((0.0, 0.0), 1.0, 1.0)
    def _gen_axes_spines(self, locations=None, offset=0.0, units='inches'):
        return OrderedDict((side, mspines.Spine.linear_spine(self, side))
                           for side in ['left', 'right', 'bottom', 'top'])
    def sharex(self, other):
        _api.check_isinstance(_AxesBase, other=other)
        if self._sharex is not None and other is not self._sharex:
            raise ValueError("x-axis is already shared")
        self._shared_axes["x"].join(self, other)
        self._sharex = other
        self.xaxis.major = other.xaxis.major  
        self.xaxis.minor = other.xaxis.minor  
        x0, x1 = other.get_xlim()
        self.set_xlim(x0, x1, emit=False, auto=other.get_autoscalex_on())
        self.xaxis._scale = other.xaxis._scale
    def sharey(self, other):
        _api.check_isinstance(_AxesBase, other=other)
        if self._sharey is not None and other is not self._sharey:
            raise ValueError("y-axis is already shared")
        self._shared_axes["y"].join(self, other)
        self._sharey = other
        self.yaxis.major = other.yaxis.major  
        self.yaxis.minor = other.yaxis.minor  
        y0, y1 = other.get_ylim()
        self.set_ylim(y0, y1, emit=False, auto=other.get_autoscaley_on())
        self.yaxis._scale = other.yaxis._scale
    def cla(self):
        if hasattr(self, 'patch'):
            patch_visible = self.patch.get_visible()
        else:
            patch_visible = True
        xaxis_visible = self.xaxis.get_visible()
        yaxis_visible = self.yaxis.get_visible()
        self.xaxis.clear()
        self.yaxis.clear()
        for name, spine in self.spines.items():
            spine.clear()
        self.ignore_existing_data_limits = True
        self.callbacks = cbook.CallbackRegistry()
        if self._sharex is not None:
            self.sharex(self._sharex)
        else:
            self.xaxis._set_scale('linear')
            try:
                self.set_xlim(0, 1)
            except TypeError:
                pass
        if self._sharey is not None:
            self.sharey(self._sharey)
        else:
            self.yaxis._set_scale('linear')
            try:
                self.set_ylim(0, 1)
            except TypeError:
                pass
        if mpl.rcParams['xtick.minor.visible']:
            self.xaxis.set_minor_locator(mticker.AutoMinorLocator())
        if mpl.rcParams['ytick.minor.visible']:
            self.yaxis.set_minor_locator(mticker.AutoMinorLocator())
        if self._sharex is None:
            self._autoscaleXon = True
        if self._sharey is None:
            self._autoscaleYon = True
        self._xmargin = mpl.rcParams['axes.xmargin']
        self._ymargin = mpl.rcParams['axes.ymargin']
        self._tight = None
        self._use_sticky_edges = True
