    def _get_view(self):
        xmin, xmax = self.get_xlim()
        ymin, ymax = self.get_ylim()
        return xmin, xmax, ymin, ymax
    def _set_view(self, view):
        xmin, xmax, ymin, ymax = view
        self.set_xlim((xmin, xmax))
        self.set_ylim((ymin, ymax))
    def _set_view_from_bbox(self, bbox, direction='in',
                            mode=None, twinx=False, twiny=False):
        if len(bbox) == 3:
            xp, yp, scl = bbox  
            if scl == 0:  
                scl = 1.
            if scl > 1:
                direction = 'in'
            else:
                direction = 'out'
                scl = 1/scl
            (xmin, ymin), (xmax, ymax) = self.transData.transform(
                np.transpose([self.get_xlim(), self.get_ylim()]))
            xwidth = xmax - xmin
            ywidth = ymax - ymin
            xcen = (xmax + xmin)*.5
            ycen = (ymax + ymin)*.5
            xzc = (xp*(scl - 1) + xcen)/scl
            yzc = (yp*(scl - 1) + ycen)/scl
            bbox = [xzc - xwidth/2./scl, yzc - ywidth/2./scl,
                    xzc + xwidth/2./scl, yzc + ywidth/2./scl]
        elif len(bbox) != 4:
            _api.warn_external(
                "Warning in _set_view_from_bbox: bounding box is not a tuple "
                "of length 3 or 4. Ignoring the view change.")
            return
        xmin0, xmax0 = self.get_xbound()
        ymin0, ymax0 = self.get_ybound()
        startx, starty, stopx, stopy = bbox
        (startx, starty), (stopx, stopy) = self.transData.inverted().transform(
            [(startx, starty), (stopx, stopy)])
        xmin, xmax = np.clip(sorted([startx, stopx]), xmin0, xmax0)
        ymin, ymax = np.clip(sorted([starty, stopy]), ymin0, ymax0)
        if twinx or mode == "y":
            xmin, xmax = xmin0, xmax0
        if twiny or mode == "x":
            ymin, ymax = ymin0, ymax0
        if direction == "in":
            new_xbound = xmin, xmax
            new_ybound = ymin, ymax
        elif direction == "out":
            x_trf = self.xaxis.get_transform()
            sxmin0, sxmax0, sxmin, sxmax = x_trf.transform(
                [xmin0, xmax0, xmin, xmax])  
            factor = (sxmax0 - sxmin0) / (sxmax - sxmin)  
            sxmin1 = sxmin0 - factor * (sxmin - sxmin0)
            sxmax1 = sxmax0 + factor * (sxmax0 - sxmax)
            new_xbound = x_trf.inverted().transform([sxmin1, sxmax1])
            y_trf = self.yaxis.get_transform()
            symin0, symax0, symin, symax = y_trf.transform(
                [ymin0, ymax0, ymin, ymax])
            factor = (symax0 - symin0) / (symax - symin)
            symin1 = symin0 - factor * (symin - symin0)
            symax1 = symax0 + factor * (symax0 - symax)
            new_ybound = y_trf.inverted().transform([symin1, symax1])
        if not twinx and mode != "y":
            self.set_xbound(new_xbound)
            self.set_autoscalex_on(False)
        if not twiny and mode != "x":
            self.set_ybound(new_ybound)
            self.set_autoscaley_on(False)
    def start_pan(self, x, y, button):
        self._pan_start = types.SimpleNamespace(
            lim=self.viewLim.frozen(),
            trans=self.transData.frozen(),
            trans_inverse=self.transData.inverted().frozen(),
            bbox=self.bbox.frozen(),
            x=x,
            y=y)
    def end_pan(self):
        del self._pan_start
    def drag_pan(self, button, key, x, y):
        def format_deltas(key, dx, dy):
            if key == 'control':
                if abs(dx) > abs(dy):
                    dy = dx
                else:
                    dx = dy
            elif key == 'x':
                dy = 0
            elif key == 'y':
                dx = 0
            elif key == 'shift':
                if 2 * abs(dx) < abs(dy):
                    dx = 0
                elif 2 * abs(dy) < abs(dx):
                    dy = 0
                elif abs(dx) > abs(dy):
                    dy = dy / abs(dy) * abs(dx)
                else:
                    dx = dx / abs(dx) * abs(dy)
            return dx, dy
        p = self._pan_start
        dx = x - p.x
        dy = y - p.y
        if dx == dy == 0:
            return
        if button == 1:
            dx, dy = format_deltas(key, dx, dy)
            result = p.bbox.translated(-dx, -dy).transformed(p.trans_inverse)
        elif button == 3:
            try:
                dx = -dx / self.bbox.width
                dy = -dy / self.bbox.height
                dx, dy = format_deltas(key, dx, dy)
                if self.get_aspect() != 'auto':
                    dx = dy = 0.5 * (dx + dy)
                alpha = np.power(10.0, (dx, dy))
                start = np.array([p.x, p.y])
                oldpoints = p.lim.transformed(p.trans)
                newpoints = start + alpha * (oldpoints - start)
                result = (mtransforms.Bbox(newpoints)
                          .transformed(p.trans_inverse))
            except OverflowError:
                _api.warn_external('Overflow while panning')
                return
        else:
            return
        valid = np.isfinite(result.transformed(p.trans))
        points = result.get_points().astype(object)
        points[~valid] = None
        self.set_xlim(points[:, 0])
        self.set_ylim(points[:, 1])
    def get_children(self):
        return [
            *self._children,
            *self.spines.values(),
            *self._get_axis_list(),
            self.title, self._left_title, self._right_title,
            *self.child_axes,
            *([self.legend_] if self.legend_ is not None else []),
            self.patch,
        ]
    def contains(self, mouseevent):
        inside, info = self._default_contains(mouseevent)
        if inside is not None:
            return inside, info
        return self.patch.contains(mouseevent)
    def contains_point(self, point):
        return self.patch.contains_point(point, radius=1.0)
    def get_default_bbox_extra_artists(self):
        artists = self.get_children()
        if not (self.axison and self._frameon):
            for spine in self.spines.values():
                artists.remove(spine)
        if not self.axison:
            for _axis in self._get_axis_list():
                artists.remove(_axis)
        artists.remove(self.title)
        artists.remove(self._left_title)
        artists.remove(self._right_title)
        return [artist for artist in artists
                if (artist.get_visible() and artist.get_in_layout())]
    def get_tightbbox(self, renderer, call_axes_locator=True,
                      bbox_extra_artists=None, *, for_layout_only=False):
        bb = []
        if not self.get_visible():
            return None
        locator = self.get_axes_locator()
        if locator and call_axes_locator:
            pos = locator(self, renderer)
            self.apply_aspect(pos)
        else:
            self.apply_aspect()
        if self.axison:
            if self.xaxis.get_visible():
                bb_xaxis = martist._get_tightbbox_for_layout_only(
                    self.xaxis, renderer)
                if bb_xaxis:
                    bb.append(bb_xaxis)
            if self.yaxis.get_visible():
                bb_yaxis = martist._get_tightbbox_for_layout_only(
                    self.yaxis, renderer)
                if bb_yaxis:
                    bb.append(bb_yaxis)
        self._update_title_position(renderer)
        axbbox = self.get_window_extent(renderer)
        bb.append(axbbox)
        for title in [self.title, self._left_title, self._right_title]:
            if title.get_visible():
                bt = title.get_window_extent(renderer)
                if for_layout_only and bt.width > 0:
                    bt.x0 = (bt.x0 + bt.x1) / 2 - 0.5
                    bt.x1 = bt.x0 + 1.0
                bb.append(bt)
        bbox_artists = bbox_extra_artists
        if bbox_artists is None:
            bbox_artists = self.get_default_bbox_extra_artists()
        for a in bbox_artists:
            clip_extent = a._get_clipping_extent_bbox()
            if clip_extent is not None:
                clip_extent = mtransforms.Bbox.intersection(
                    clip_extent, axbbox)
                if np.all(clip_extent.extents == axbbox.extents):
                    continue
            bbox = a.get_tightbbox(renderer)
            if (bbox is not None
                    and 0 < bbox.width < np.inf
                    and 0 < bbox.height < np.inf):
                bb.append(bbox)
        return mtransforms.Bbox.union(
            [b for b in bb if b.width != 0 or b.height != 0])
    def _make_twin_axes(self, *args, **kwargs):
        if 'sharex' in kwargs and 'sharey' in kwargs:
            raise ValueError("Twinned Axes may share only one axis")
        ax2 = self.figure.add_axes(
            self.get_position(True), *args, **kwargs,
            axes_locator=_TransformedBoundsLocator(
                [0, 0, 1, 1], self.transAxes))
        self.set_adjustable('datalim')
        ax2.set_adjustable('datalim')
        self._twinned_axes.join(self, ax2)
        return ax2
    def twinx(self):
        ax2 = self._make_twin_axes(sharex=self)
        ax2.yaxis.tick_right()
        ax2.yaxis.set_label_position('right')
        ax2.yaxis.set_offset_position('right')
        ax2.set_autoscalex_on(self.get_autoscalex_on())
        self.yaxis.tick_left()
        ax2.xaxis.set_visible(False)
        ax2.patch.set_visible(False)
        return ax2
    def twiny(self):
        ax2 = self._make_twin_axes(sharey=self)
        ax2.xaxis.tick_top()
        ax2.xaxis.set_label_position('top')
        ax2.set_autoscaley_on(self.get_autoscaley_on())
        self.xaxis.tick_bottom()
        ax2.yaxis.set_visible(False)
        ax2.patch.set_visible(False)
        return ax2
    def get_shared_x_axes(self):
        return self._shared_axes["x"]
    def get_shared_y_axes(self):
        return self._shared_axes["y"]

class ArtistList(MutableSequence):
    def __init__(self, axes, prop_name, add_name,
                 valid_types=None, invalid_types=None):
        self._axes = axes
        self._prop_name = prop_name
        self._add_name = add_name
        self._type_check = lambda artist: (
            (not valid_types or isinstance(artist, valid_types)) and
            (not invalid_types or not isinstance(artist, invalid_types))
        )
    def __repr__(self):
        return f'<Axes.ArtistList of {len(self)} {self._prop_name}>'
    def __len__(self):
        return sum(self._type_check(artist)
                   for artist in self._axes._children)
    def __iter__(self):
        for artist in self._axes._children:
            if self._type_check(artist):
                yield artist
    def __getitem__(self, key):
        return [artist
                for artist in self._axes._children
                if self._type_check(artist)][key]
    def __add__(self, other):
        if isinstance(other, (list, _AxesBase.ArtistList)):
            return [*self, *other]
        return NotImplemented
    def __radd__(self, other):
        if isinstance(other, list):
            return other + list(self)
        return NotImplemented
    def insert(self, index, item):
        _api.warn_deprecated(
            '3.5',
            name=f'modification of the Axes.{self._prop_name}',
            obj_type='property',
            alternative=f'Axes.{self._add_name}')
        try:
            index = self._axes._children.index(self[index])
        except IndexError:
            index = None
        getattr(self._axes, self._add_name)(item)
        if index is not None:
            self._axes._children[index:index] = self._axes._children[-1:]
            del self._axes._children[-1]
    def __setitem__(self, key, item):
        _api.warn_deprecated(
            '3.5',
            name=f'modification of the Axes.{self._prop_name}',
            obj_type='property',
            alternative=f'Artist.remove() and Axes.f{self._add_name}')
        del self[key]
        if isinstance(key, slice):
            key = key.start
        if not np.iterable(item):
            self.insert(key, item)
            return
        try:
            index = self._axes._children.index(self[key])
        except IndexError:
            index = None
        for i, artist in enumerate(item):
            getattr(self._axes, self._add_name)(artist)
        if index is not None:
            i = -(i + 1)
            self._axes._children[index:index] = self._axes._children[i:]
            del self._axes._children[i:]
    def __delitem__(self, key):
        _api.warn_deprecated(
            '3.5',
            name=f'modification of the Axes.{self._prop_name}',
            obj_type='property',
            alternative='Artist.remove()')
        if isinstance(key, slice):
            for artist in self[key]:
                artist.remove()
        else:
            self[key].remove()

class MediaFormatInfo(object):
    def __init__(self):
        self.format = None
        self.fullname = None
        self.bitrate = None
        self.duration = None
        self.filesize = None
    def parse_ffprobe(self, key, val):
        if key == 'format_name':
            self.format = val
        elif key == 'format_long_name':
            self.fullname = val
        elif key == 'bit_rate':
            self.bitrate = float(val)
        elif key == 'duration':
            self.duration = float(val)
        elif key == 'size':
            self.size = float(val)
    def __repr__(self):
        return 'MediaFormatInfo(format=%s, duration=%.2f)' % (self.format,
            self.duration)

class MediaStreamInfo(object):
    def __init__(self):
        self.index = None
        self.type = None
        self.codec = None
        self.codec_desc = None
        self.duration = None
        self.video_width = None
        self.video_height = None
        self.video_fps = None
        self.audio_channels = None
        self.audio_samplerate = None
        self.profile = None
        self.sample_aspect_ratio = None
        self.display_aspect_ratio = None
        self.level = None
        self.start_time = None
    @staticmethod
    def parse_float(val, default=0.0):
        try:
            return float(val)
        except:
            return default
    @staticmethod
    def parse_int(val, default=0):
        try:
            return int(val)
        except:
            return default
    def parse_ffprobe(self, key, val):
        if key == 'index':
            self.index = self.parse_int(val)
        elif key == 'codec_type':
            self.type = val
        elif key == 'codec_name':
            self.codec = val
        elif key == 'codec_long_name':
            self.codec_desc = val
        elif key == 'duration':
            self.duration = self.parse_float(val)
        elif key == 'width':
            self.video_width = self.parse_int(val)
        elif key == 'height':
            self.video_height = self.parse_int(val)
        elif key == 'channels':
            self.audio_channels = self.parse_int(val)
        elif key == 'sample_rate':
            self.audio_samplerate = self.parse_float(val)
        if self.type == 'audio':
            if key == 'avg_frame_rate':
                if '/' in val:
                    n, d = val.split('/')
                    n = self.parse_float(n)
                    d = self.parse_float(d)
                    if n > 0.0 and d > 0.0:
                        self.video_fps = float(n) / float(d)
                elif '.' in val:
                    self.video_fps = self.parse_float(val)
        if self.type == 'video':
            if key == 'r_frame_rate':
                if '/' in val:
                    n, d = val.split('/')
                    n = self.parse_float(n)
                    d = self.parse_float(d)
                    if n > 0.0 and d > 0.0:
                        self.video_fps = float(n) / float(d)
                elif '.' in val:
                    self.video_fps = self.parse_float(val)
            if key == 'sample_aspect_ratio':
                self.sample_aspect_ratio = val
            elif key == 'display_aspect_ratio':
                self.display_aspect_ratio = val
            elif key == 'profil':
                self.profile = val
            elif key == 'level':
                self.level = val
    def __repr__(self):
        d = ''
        if self.type == 'audio':
            d = 'type=%s, codec=%s, channels=%d, rate=%.0f' % (self.type,
                self.codec, self.audio_channels,
                self.audio_samplerate)
        elif self.type == 'video':
            d = 'type=%s, codec=%s, width=%d, height=%d, fps=%.1f sar=%s dar=%s profile=%s level=%s' % (
                self.type, self.codec, self.video_width, self.video_height,
                self.video_fps, self.sample_aspect_ratio, self.display_aspect_ratio,
                self.profile, self.level)
        return 'MediaStreamInfo(%s)' % d

class MediaInfo(object):
    def __init__(self):
        self.format = MediaFormatInfo()
        self.streams = []
    def parse_ffprobe(self, raw):
        in_format = False
        current_stream = None
        for line in raw.split('\n'):
            line = line.strip()
            if line == '':
                continue
            elif line == '[STREAM]':
                current_stream = MediaStreamInfo()
            elif line == '[/STREAM]':
                if current_stream.type:
                    self.streams.append(current_stream)
                current_stream = None
            elif line == '[FORMAT]':
                in_format = True
            elif line == '[/FORMAT]':
                in_format = False
            elif '=' in line:
                k, v = line.split('=', 1)
                k = k.strip()
                v = v.strip()
                if current_stream:
                    current_stream.parse_ffprobe(k, v)
                elif in_format:
                    self.format.parse_ffprobe(k, v)
    def __repr__(self):
        return 'MediaInfo(format=%s, streams=%s)' % (repr(self.format),
            repr(self.streams))
    @property
    def video(self):
        for s in self.streams:
            if s.type == 'video':
                return s
        return None
    @property
    def audio(self):
        for s in self.streams:
            if s.type == 'audio':
                return s
        return None

