class DocumentPropertiesResponse(object):
    swagger_types = {
        'code': 'int',
        'status': 'str',
        'document_properties': 'DocumentProperties'
    }
    attribute_map = {
        'code': 'Code',
        'status': 'Status',
        'document_properties': 'DocumentProperties'
    }
    def __init__(self, code=None, status=None, document_properties=None):
        self._code = None
        self._status = None
        self._document_properties = None
        self.code = code
        if status is not None:
          self.status = status
        if document_properties is not None:
          self.document_properties = document_properties
    @property
    def code(self):
        return self._code
    @code.setter
    def code(self, code):
        if code is None:
            raise ValueError("Invalid value for `code`, must not be `None`")
        self._code = code
    @property
    def status(self):
        return self._status
    @status.setter
    def status(self, status):
        self._status = status
    @property
    def document_properties(self):
        return self._document_properties
    @document_properties.setter
    def document_properties(self, document_properties):
        self._document_properties = document_properties
    def to_dict(self):
        result = {}
        for attr, _ in iteritems(self.swagger_types):
            value = getattr(self, attr)
            if isinstance(value, list):
                result[attr] = list(map(
                    lambda x: x.to_dict() if hasattr(x, "to_dict") else x,
                    value
                ))
