class Calcul:
    def __init__(self, left, right, op):
        self.left = left
        self.right = right
        self.op = op
    def __repr__(self):
        result = ""
        if isinstance(self.left, Calcul):
            if Calcul.comOperator(self.op, self.left.op):
                strLeft = f"({self.left})"
            else:
                strLeft = f"{self.left}"
        else:
            strLeft = str(self.left)
        if isinstance(self.right, Calcul):
            if Calcul.comOperator(self.op, self.right.op):
                strRight = f"({self.right})"
            else:
                strRight = f"{self.right}"
        else:
            strRight = str(self.right)
        return strLeft + "" + self.op + "" + strRight
    def toLatex(self):
        result = ""
        if isinstance(self.left, Calcul):
            if (Calcul.comOperator(self.op, self.left.op) and self.op != "/") or self.op in ["**", "^"]:
                left = "\\left("+ self.left.toLatex()+"\\right)"
            else:
                left = self.left.toLatex()
        else:
            left = str(self.left)
        if isinstance(self.right, Calcul):
            if Calcul.comOperator(self.op, self.right.op) and self.op != "/" or self.op in ["**", "^"]:
                right = "\\left("+ self.right.toLatex()+"\\right)"
            else:
                right = self.right.toLatex()
        else:
            right = str(self.right)
        if self.op == "+":
            return left + " + " + right
        if self.op == "-":
            return left + " - " + right
        if self.op == "*":
            if right[0] == "(":
                return left + "" + right
            if (not right[0].isdigit()) and (isinstance(self.right, Calcul) and self.right.op not in ["/", "^", "**"]):
                return left + "" + right
            if left == "1":
                return right
            return left +" \\times "+ right
        if self.op == "/":
            return " \\dfrac{"+left+"}{"+right+"} "
        if self.op == "**" or "^":
            return left + "^{" + right + "} "
    @staticmethod
    def comOperator(op1, op2):
        operateurs = ["+","-","*","/","**","^", "²"]
        index1 = operateurs.index(op1)
        index2 = operateurs.index(op2)
        return index1 > index2
    def toNPIArray(self):
        result = []
        if isinstance(self.left, Calcul):
            result.extend(self.left.toNPIArray())
        else:
            result.append(self.left)
        if isinstance(self.right, Calcul):
            result.extend(self.right.toNPIArray())
        else:
            result.append(self.right)
        result.append(self.op)
        return result
    def toNPI(self):
        result = ""
        array = self.toNPIArray()
        for v in array:
            result += v + " "
        return result
    @staticmethod
    def fromExpressionArray(expression):
        operations = ["+","-","*","/","**","^", "²"]
        for op in operations:
            if op in expression:
                pos = expression.index(op)
                if op =="²":
                    gauche = expression[:pos]
                    result = Calcul(Calcul.fromExpression(gauche), 2, "^")
                else:
                    gauche = expression[:pos]
                    droite = expression[pos+len(op):]
                    result = Calcul(Calcul.fromExpressionArray(gauche), Calcul.fromExpressionArray(droite), op)
                return result
        if type(expression) == type([]):
            return expression[0]
        return expression
    @staticmethod
    def fromExpression(expression):
        operations = ["+","-","*","/","**","^", "²"]
        parenthese = Calcul.extractParenthese(expression)
        if isinstance(expression, Calcul):
            return expression
        result = []
        temp = ""
        i = 0
        while i < len(expression):
            c = expression[i]
            if c in operations:
                if temp=="" and c=="-":
                    temp += "-"
                else:
                    result.append(temp)
                    temp = ""
                    if c=="²":
                        result.append("^")
                        temp = '2'
                    else:
                        result.append(c)
            elif c == "(":
                j = parenthese[i]
                result.append(Calcul.fromExpression(expression[i+1: j]))
                i = j-1
            elif isinstance(c, Calcul):
                result.append(c)
            else:
                temp += str(c)
            i+=1
        result.append(temp)
        return Calcul.fromExpressionArray(result)
    @staticmethod
    def fromNPIArray(NPIArrayExpression):
        pile = []
        for e in NPIArrayExpression:
            if e in ["+","-","*","/","**","^"]:
                droite = pile.pop()
                gauche = pile.pop()
                calcul = Calcul(gauche, droite, e)
                pile.append(calcul)
            elif e == "²": 
                gauche = pile.pop()
                calcul = Calcul(gauche, 2, '^')
                pile.append(calcul)
            else:
                pile.append(e)
        return pile[0]
    @staticmethod
    def fromNPI(expression):
        return Calcul.fromNPIArray(expression.strip().split(" "))
    @staticmethod
    def extractParenthese(expression):
        pile = []
        couple_list = {}
        content = []
        for i in range(len(expression)):
            c = expression[i]
            if (c=='('):
                pile.append(i)
            elif (c==')'):
                if len(pile) > 0:
                    val = pile.pop() 
                    couple_list[val] = i 
                else :
                    print ("Expression '",expression,"' invalide : Parenthèse fermante en trop", file = stderr)
                    return None
        if (len(pile)==0):
            return couple_list
        else:
            print ("Expression '",expression,"' invalide : Parenthèse ouvrante en trop", file = stderr)
            return False
    def eval(self):
        if self.op == None:
            return self.left
        if type(self.left) == Calcul:
            left = self.left.eval()
        else:
            left = eval(self.left)
        if type(self.right) == Calcul:
            right = self.right.eval()
        else :
            right = eval(self.right)
        if self.op == "+":
            return left + right
        if self.op == "-":
            return left - right
        if self.op == "*":
            return left * right
        if self.op == "/":
            return left / right
        if self.op == "**" or "^":
            return left ** right

