    def n_evidence(self):
        if self._gp is None:
            return 0
        return self._gp.num_data
    @property
    def X(self):
        return self._gp.X
    @property
    def Y(self):
        return self._gp.Y
    @property
    def noise(self):
        return self._gp.Gaussian_noise.variance[0]
    @property
    def instance(self):
        return self._gp
    def copy(self):
        kopy = copy.copy(self)
        if self._gp:
            kopy._gp = self._gp.copy()
        if 'kernel' in self.gp_params:
            kopy.gp_params['kernel'] = self.gp_params['kernel'].copy()
        if 'mean_function' in self.gp_params:
            kopy.gp_params['mean_function'] = self.gp_params['mean_function'].copy()
        return kopy
    def __copy__(self):
        return self.copy()

