            response["reported_noncompliant"] = True
        return response

class _MessageCode (int):
	if sys.version_info[0] < 3:
		__slots__ = ['SHORT','NAME']
	NOP           = 0x00  
	OPEN          = 0x01  
	UPDATE        = 0x02  
	NOTIFICATION  = 0x03  
	KEEPALIVE     = 0x04  
	ROUTE_REFRESH = 0x05  
	OPERATIONAL   = 0x06  
	names = {
		None:           'INVALID',
		NOP:            'NOP',
		OPEN:           'OPEN',
		UPDATE:         'UPDATE',
		NOTIFICATION:   'NOTIFICATION',
		KEEPALIVE:      'KEEPALIVE',
		ROUTE_REFRESH:  'ROUTE_REFRESH',
		OPERATIONAL:    'OPERATIONAL',
	}
	short_names = {
		None:           'invalid',
		NOP:            'nop',
		OPEN:           'open',
		UPDATE:         'update',
		NOTIFICATION:   'notification',
		KEEPALIVE:      'keepalive',
		ROUTE_REFRESH:  'refresh',
		OPERATIONAL:    'operational',
	}
	long_names = {
		None:           'invalid',
		NOP:            'nop',
		OPEN:           'open',
		UPDATE:         'update',
		NOTIFICATION:   'notification',
		KEEPALIVE:      'keepalive',
		ROUTE_REFRESH:  'route refresh',
		OPERATIONAL:    'operational',
	}
	def __init__ (self, value):
		self.SHORT = self.short()
		self.NAME = str(self)
	def __str__ (self):
		return self.names.get(self,'unknown message %s' % hex(self))
	def __repr__ (self):
		return str(self)
	def short (self):
		return self.short_names.get(self,'unknown')

