            raise ValueError(r"Invalid value for `pattern_with_digits_and_delimiter`, must be a follow pattern or equal to `/^image_\d{1,3}$/i`")  
        self._pattern_with_digits_and_delimiter = pattern_with_digits_and_delimiter
    def to_dict(self):
