        raise NotImplementedError('subclasses must override __str__()')

class Effect(object):
    def __init__(self, parameters, condition, literal):
        self.parameters = parameters
        self.condition = condition
        self.literal = literal
    def __hash__(self):
        return hash((self.__class__, tuple(self.parameters), self.condition, self.literal))
    def __str__(self):
        effect_str = ""
        indent = ""
        if self.parameters:
            effect_str += "%sforall %s" % (indent, ", ".join(map(str, self.parameters)))
            indent += "  "
        if self.condition != conditions.Truth():
            effect_str += "(when %s %s)" % (self.condition, self.literal)
        else:
            effect_str += "%s" % (self.literal)
        return effect_str
    def __eq__(self, other):
        return (self.__class__ is other.__class__ and
                self.parameters == other.parameters and
                self.condition == other.condition and
                self.literal == other.literal)
    def dump(self):
        indent = "  "
        if self.parameters:
            print("%sforall %s" % (indent, ", ".join(map(str, self.parameters))))
            indent += "  "
        if self.condition != conditions.Truth():
            print("%sif" % indent)
            self.condition.dump(indent + "  ")
            print("%sthen" % indent)
            indent += "  "
        print("%s%s" % (indent, self.literal))
    def copy(self):
        return Effect(self.parameters, self.condition, self.literal)
    def uniquify_variables(self, type_map):
        renamings = {}
        self.parameters = [par.uniquify_name(type_map, renamings)
                           for par in self.parameters]
        self.condition = self.condition.uniquify_variables(type_map, renamings)
        self.literal = self.literal.rename_variables(renamings)
    def instantiate(self, var_mapping, init_facts, fluent_facts,
                    objects_by_type, result):
        if self.parameters:
            var_mapping = var_mapping.copy() 
            object_lists = [objects_by_type.get(par.type_name, [])
                            for par in self.parameters]
            for object_tuple in cartesian_product(*object_lists):
                for (par, obj) in zip(self.parameters, object_tuple):
                    var_mapping[par.name] = obj
                self._instantiate(var_mapping, init_facts, fluent_facts, result)
        else:
            self._instantiate(var_mapping, init_facts, fluent_facts, result)
    def _instantiate(self, var_mapping, init_facts, fluent_facts, result):
        condition = []
        try:
            self.condition.instantiate(var_mapping, init_facts, fluent_facts, condition)
        except conditions.Impossible:
            return
        effects = []
        self.literal.instantiate(var_mapping, init_facts, fluent_facts, effects)
        assert len(effects) <= 1
        if effects:
            result.append((condition, effects[0]))
    def relaxed(self):
        if self.literal.negated:
            return None
        else:
            return Effect(self.parameters, self.condition.relaxed(), self.literal)
    def simplified(self):
        return Effect(self.parameters, self.condition.simplified(), self.literal)

class CaseInsensitiveStr(str):
    def __init__(self, *args):
        self._lowered = _try_lower(self)
    def __hash__(self):
        return str.__hash__(self._lowered)
    def __eq__(self, other):
        return str.__eq__(self._lowered, _try_lower(other))
    def __gt__(self, other):
        return str.__gt__(self._lowered, _try_lower(other))
    def __ge__(self, other):
        return str.__ge__(self._lowered, _try_lower(other))
    def __lt__(self, other):
        return str.__lt__(self._lowered, _try_lower(other))
    def __le__(self, other):
        return str.__le__(self._lowered, _try_lower(other))
    def __ne__(self, other):
        return str.__ne__(self._lowered, _try_lower(other))

class CaseInsensitiveDict(dict):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._keys_to_lower()
    def __eq__(self, other):
        return super().__eq__(CaseInsensitiveDict(other))
    def __getitem__(self, key):
        return super().__getitem__(CaseInsensitiveStr(key))
    def __setitem__(self, key, value):
        super().__setitem__(CaseInsensitiveStr(key), value)
    def __delitem__(self, key):
        return super().__delitem__(CaseInsensitiveStr(key))
    def __contains__(self, key):
        return super().__contains__(CaseInsensitiveStr(key))
    def pop(self, key, *args, **kwargs):
        return super().pop(CaseInsensitiveStr(key))
    def _keys_to_lower(self):
        for k in list(self.keys()):
            val = super().__getitem__(k)
            super().__delitem__(k)
            self.__setitem__(CaseInsensitiveStr(k), val)

