class Action(object):
    def __init__(self, role, host=None, start=True):
        self.role = role
        self.host = host
        self.start = start
    def __repr__(self):
        s = 'Action({}, start={}'.format(self.role.name, self.start)
        s += ', host={}'.format(self.host) if self.host else ''
        s += ')'
        return s
    def run(self, services, args_dict):
        if self.start:
            cmd = self.role.start_hook
            args = list(self.role.start_args)
        else:
            cmd = self.role.stop_hook
            args = list(self.role.stop_hook)
        if 'h' in args:
            cmd += ' -h {}'.format(self.host)
            args.remove('h')
        elif 'host' in args:
            cmd += ' --host {}'.format(self.host)
            args.remove('host')
        if 'i' in args:
            cmd += ' -i {}'.format(services[self.role.name].pop())
            args.remove('i')
        elif 'instance' in args:
            cmd += ' --instance {}'.format(services[self.role.name].pop())
            args.remove('instance')
        for arg in args:
            if len(arg) == 1:
                cmd += ' -{} {}'.format(arg, args_dict[arg])
            elif len(arg) > 1:
                cmd += ' --{} {}'.format(arg, args_dict[arg])
        subprocess.call(cmd.split())

class MovieWorld:
    def __init__(self, name):
        self.name = name
        self.customers = []
        self.dvds = []
        self.dvd_ids = {}
        self.customer_ids = {}
    @staticmethod
    def dvd_capacity():
        return 15
    @staticmethod
    def customer_capacity():
        return 10
    def add_customer(self, customer: Customer):
        if len(self.customers) >= self.customer_capacity():
            return
        self.customers.append(customer)
        self.customer_ids[customer.id] = customer
    def add_dvd(self, dvd: DVD):
        if len(self.dvds) >= self.dvd_capacity():
            return
        self.dvds.append(dvd)
        self.dvd_ids[dvd.id] = dvd
    def rent_dvd(self, customer_id, dvd_id):
        dvd = self.dvd_ids.get(dvd_id)
        customer = self.customer_ids.get(customer_id)
        if customer.has_dvd(dvd):
            return f"{customer.name} has already rented {dvd.name}"
        if dvd.is_rented:
            return "DVD is already rented"
        if customer.age < dvd.age_restriction:
            return f"{customer.name} should be at least {dvd.age_restriction} to rent this movie"
        dvd.rent()
        customer.add_dvd(dvd)
        return f"{customer.name} has successfully rented {dvd.name}"
    def return_dvd(self, customer_id, dvd_id):
        customer = self.customer_ids.get(customer_id)
        dvd = self.dvd_ids.get(dvd_id)
        if not customer.has_dvd(dvd):
            return f"{customer.name} does not have that DVD"
        customer.remove_dvd(dvd)
        return f"{customer.name} has successfully returned {dvd.name}"
    def __repr__(self):
        customers = list(map(str, self.customers))
        dvds = list(map(str, self.dvds))
        return '\n'.join(customers + dvds)

