class Handle:
    __slots__ = ('_callback', '_args', '_cancelled', '_loop',
                 '_source_traceback', '_repr', '__weakref__')
    def __init__(self, callback, args, loop):
        self._loop = loop
        self._callback = callback
        self._args = args
        self._cancelled = False
        self._repr = None
        if self._loop.get_debug():
            self._source_traceback = traceback.extract_stack(sys._getframe(1))
        else:
            self._source_traceback = None
    def _repr_info(self):
        taskName = [self.__class__.__name__]
        if self._cancelled:
            taskName.append('cancelled')
        if self._callback is not None:
            taskName.append(_format_callback_source(self._callback, self._args))
        if self._source_traceback:
            frame = self._source_traceback[-1]
            taskName.append('created at %s:%s' % (frame[0], frame[1]))
        return taskName
    def __repr__(self):
        if self._repr is not None:
            return self._repr
        taskName = self._repr_info()
        return '<%s>' % ' '.join(taskName)
    def cancel(self):
        if not self._cancelled:
            self._cancelled = True
            if self._loop.get_debug():
                self._repr = repr(self)
            self._callback = None
            self._args = None
    def _run(self):
        try:
            self._callback(*self._args)
        except Exception as exc:
            cb = _format_callback_source(self._callback, self._args)
            msg = 'Exception in callback {}'.format(cb)
            context = {
                'message': msg,
                'exception': exc,
                'handle': self,
            }
            if self._source_traceback:
                context['source_traceback'] = self._source_traceback
            self._loop.call_exception_handler(context)
        self = None

class TimerHandle(Handle):
    __slots__ = ['_scheduled', '_when']
    def __init__(self, when, callback, args, loop):
        assert when is not None
        super().__init__(callback, args, loop)
        if self._source_traceback:
            del self._source_traceback[-1]
        self._when = when
        self._scheduled = False
    def _repr_info(self):
        taskName = super()._repr_info()
        pos = 2 if self._cancelled else 1
        taskName.insert(pos, 'when=%s' % self._when)
        return taskName
    def __hash__(self):
        return hash(self._when)
    def __lt__(self, other):
        return self._when < other._when
    def __le__(self, other):
        if self._when < other._when:
            return True
        return self.__eq__(other)
    def __gt__(self, other):
        return self._when > other._when
    def __ge__(self, other):
        if self._when > other._when:
            return True
        return self.__eq__(other)
    def __eq__(self, other):
        if isinstance(other, TimerHandle):
            return (self._when == other._when and
                    self._callback == other._callback and
                    self._args == other._args and
                    self._cancelled == other._cancelled)
        return NotImplemented
    def __ne__(self, other):
        equal = self.__eq__(other)
        return NotImplemented if equal is NotImplemented else not equal
    def cancel(self):
        if not self._cancelled:
            self._loop._timer_handle_cancelled(self)
        super().cancel()

class PointMap(dict):
    @key_to_jfine
    def __setitem__(self, val, x, y):
        pnt = Point(x, y)
        dict.__setitem__(self, pnt, val)
    @key_to_jfine
    def __getitem__(self, *argv, **kwargs):
        ln_v, ln_kw = len(argv), len(kwargs)
        ln_args = ln_v + ln_kw
        if not (1 <= ln_args <= 2):
            raise ValueError
        if ln_args == 2:
            pnt = Point(*argv, **kwargs)
            return dict.__getitem__(self, pnt)
        if ln_kw == 1:
            axis, coord = next(iter(kwargs.items()))
            return tuple(
                kv_pair for kv_pair in self.items()
                if getattr(kv_pair[0], axis) == coord
            )
        raise SystemError
    def __repr__(self):
        return 'PointMap({})'.format(dict.__repr__(self))

class IOCB(DebugContents):
    _debugContents = \
        ( 'args', 'kwargs'
        , 'ioState', 'ioResponse-', 'ioError'
        , 'ioController', 'ioServerRef', 'ioControllerRef', 'ioClientID', 'ioClientAddr'
        , 'ioComplete', 'ioCallback+', 'ioQueue', 'ioPriority', 'ioTimeout'
        )
    def __init__(self, *args, **kwargs):
        global _identNext
        _identLock.acquire()
        ioID = _identNext
        _identNext += 1
        _identLock.release()
        if _debug: IOCB._debug("__init__(%d) %r %r", ioID, args, kwargs)
        self.ioID = ioID
        self.args = args
        self.kwargs = kwargs
        self.ioState = IDLE
        self.ioResponse = None
        self.ioError = None
        self.ioController = None
        self.ioComplete = threading.Event()
        self.ioComplete.clear()
        self.ioCallback = []
        self.ioQueue = None
        self.ioPriority = kwargs.get('_priority', 0)
        if '_priority' in kwargs:
            if _debug: IOCB._debug("    - ioPriority: %r", self.ioPriority)
            del kwargs['_priority']
        self.ioTimeout = None
    def add_callback(self, fn, *args, **kwargs):
        if _debug: IOCB._debug("add_callback(%d) %r %r %r", self.ioID, fn, args, kwargs)
        self.ioCallback.append((fn, args, kwargs))
        if self.ioComplete.isSet():
            self.trigger()
    def wait(self, *args):
        if _debug: IOCB._debug("wait(%d) %r", self.ioID, args)
        self.ioComplete.wait(*args)
    def trigger(self):
        if _debug: IOCB._debug("trigger(%d)", self.ioID)
        if self.ioQueue:
            if _debug: IOCB._debug("    - dequeue")
            self.ioQueue.remove(self)
        if self.ioTimeout:
            if _debug: IOCB._debug("    - cancel timeout")
            self.ioTimeout.suspend_task()
        self.ioComplete.set()
        for fn, args, kwargs in self.ioCallback:
            if _debug: IOCB._debug("    - callback fn: %r %r %r", fn, args, kwargs)
            fn(self, *args, **kwargs)
    def complete(self, msg):
        if _debug: IOCB._debug("complete(%d) %r", self.ioID, msg)
        if self.ioController:
            self.ioController.complete_io(self, msg)
        else:
            self.ioState = COMPLETED
            self.ioResponse = msg
            self.trigger()
    def abort(self, err):
        if _debug: IOCB._debug("abort(%d) %r", self.ioID, err)
        if self.ioController:
            self.ioController.abort_io(self, err)
        elif self.ioState < COMPLETED:
            self.ioState = ABORTED
            self.ioError = err
            self.trigger()
    def set_timeout(self, delay, err=TimeoutError):
        if _debug: IOCB._debug("set_timeout(%d) %r err=%r", self.ioID, delay, err)
        if self.ioTimeout:
            self.ioTimeout.suspend_task()
        else:
            self.ioTimeout = FunctionTask(self.abort, err)
        self.ioTimeout.install_task(_time() + delay)
    def __repr__(self):
        xid = id(self)
        if (xid < 0): xid += (1 << 32)
        sname = self.__module__ + '.' + self.__class__.__name__
        desc = "(%d)" % (self.ioID)
        return '<' + sname + desc + ' instance at 0x%08x' % (xid,) + '>'

class Chebfun(object):
    @classmethod
    def initempty(cls):
        return cls(array([]))
    @classmethod
    def initconst(cls, c, domain=DefaultPrefs.domain):
        funs = generate_funs(domain, Bndfun.initconst, [c])
        return cls(funs)
    @classmethod
    def initidentity(cls, domain=DefaultPrefs.domain):
        funs = generate_funs(domain, Bndfun.initidentity, [])
        return cls(funs)
    @classmethod
    def initfun_adaptive(cls, f, domain=DefaultPrefs.domain):
        funs = generate_funs(domain, Bndfun.initfun_adaptive, [f])
        return cls(funs)
    @classmethod
    def initfun_fixedlen(cls, f, n, domain=DefaultPrefs.domain):
        domain = array(domain)
        nn = array(n)
        if nn.size == 1:
            nn = nn * ones(domain.size-1)
        elif nn.size > 1:
            if nn.size != domain.size - 1:
                raise BadFunLengthArgument
        if domain.size < 2:
            raise BadDomainArgument
        funs = array([])
        intervals = zip(domain[:-1], domain[1:])
        for interval, length in zip(intervals, nn):
            interval = Interval(*interval)
            fun = Bndfun.initfun_fixedlen(f, interval, length)
            funs = append(funs, fun)
        return cls(funs)
    def __add__(self, f):
        return self._apply_binop(f, __add__)
    @self_empty(array([]))
    @float_argument
    def __call__(self, x):
        out = full(x.size, nan)
        for fun in self:
            idx = fun.interval.isinterior(x)
            out[idx] = fun(x[idx])
        breakpoints = self.breakpoints
        for breakpoint in breakpoints:
            out[x==breakpoint] = self.breakdata[breakpoint]
        lpts, rpts = x < breakpoints[0], x > breakpoints[-1]
        out[lpts] = self.funs[0](x[lpts])
        out[rpts] = self.funs[-1](x[rpts])
        return out
    def __init__(self, funs):
        self.funs = check_funs(funs)
        self.breakdata = compute_breakdata(self.funs)
        self.transposed = False
    def __iter__(self):
        return self.funs.__iter__()
    def __mul__(self, f):
        return self._apply_binop(f, __mul__)
    def __neg__(self):
        return self.__class__(-self.funs)
    def __pos__(self):
        return self
    def __rtruediv__(self, c):
        constfun = lambda x: .0*x + c
        newfuns = []
        for fun in self:
            quotnt = lambda x: constfun(x) / fun(x)
            newfun = fun.initfun_adaptive(quotnt, fun.interval)
            newfuns.append(newfun)
        return self.__class__(newfuns)
    @self_empty("chebfun<empty>")
    def __repr__(self):
        rowcol = "row" if self.transposed else "column"
        numpcs = self.funs.size
        plural = "" if numpcs == 1 else "s"
        header = "chebfun {} ({} smooth piece{})\n"\
            .format(rowcol, numpcs, plural)
        toprow = "       interval       length     endpoint values\n"
        tmplat = "[{:8.2g},{:8.2g}]   {:6}  {:8.2g} {:8.2g}\n"
        rowdta = ""
        for fun in self:
            endpts = fun.support
            xl, xr = endpts
            fl, fr = fun(endpts)
            row = tmplat.format(xl, xr, fun.size, fl, fr)
            rowdta += row
        btmrow = "vertical scale = {:3.2g}".format(self.vscale)
        btmxtr = "" if numpcs == 1 else \
            "    total length = {}".format(sum([f.size for f in self]))
        return header + toprow + rowdta + btmrow + btmxtr
    def __rsub__(self, f):
        return -(self-f)
    def __truediv__(self, f):
        return self._apply_binop(f, truediv)
    __rmul__ = __mul__
    __div__ = __truediv__
    __rdiv__ = __rtruediv__
    __radd__ = __add__
    def __str__(self):
        rowcol = "row" if self.transposed else "col"
        out = "<chebfun-{},{},{}>\n".format(
            rowcol, self.funs.size, sum([f.size for f in self]))
        return out
    def __sub__(self, f):
        return self._apply_binop(f, __sub__)
    @self_empty()
    def _apply_binop(self, f, op):
        try:
            if f.isempty:
                return f
        except:
            pass
        if isscalar(f):
            chbfn1 = self
            chbfn2 = f * ones(self.funs.size)
            simplify = False
        else:
            newdom = self.domain.union(f.domain)
            chbfn1 = self._break(newdom)
            chbfn2 = f._break(newdom)
            simplify = True
        newfuns = []
        for fun1, fun2 in zip(chbfn1, chbfn2):
            newfun = op(fun1, fun2)
            if simplify:
                newfun = newfun.simplify()
            newfuns.append(newfun)
        return self.__class__(newfuns)
    def _break(self, targetdomain):
        newfuns = []
        subintervals = targetdomain.intervals
        interval = next(subintervals) 
        for fun in self:
            while interval in fun.interval:
                newfun = fun.restrict(interval)
                newfuns.append(newfun)
                try:
                    interval = next(subintervals)
                except StopIteration:
                    break
        return self.__class__(newfuns)
    @property
    def breakpoints(self):
        return array([x for x in self.breakdata.keys()])
    @property
    @self_empty(array([]))
    def domain(self):
        return Domain.from_chebfun(self)
    @property
    @self_empty(array([]))
    def support(self):
        return self.breakpoints[[0,-1]]
    @property
    @self_empty(0)
    def hscale(self):
        return abs(self.support).max()
    @property
    @self_empty(False)
    def isconst(self):
        c = self.funs[0].coeffs[0]
        return all(fun.isconst and fun.coeffs[0]==c for fun in self)
    @property
    def isempty(self):
        return self.funs.size == 0
    @property
    @self_empty(0)
    def vscale(self):
        return max([fun.vscale for fun in self])
    @property
    @self_empty()
    def x(self):
        return self.__class__.initidentity(self.support)
    def copy(self):
        return self.__class__([fun.copy() for fun in self])
    @self_empty()
    def _restrict(self, subinterval):
        newdom = self.domain.restrict(Domain(subinterval))
        return self._break(newdom)
    @self_empty()
    def simplify(self):
        return self.__class__([fun.simplify() for fun in self])
    def restrict(self, subinterval):
        return self._restrict(subinterval).simplify()
    @self_empty(array([]))
    def roots(self):
        allrts = []
        prvrts = array([])
        htol = 1e2 * self.hscale * DefaultPrefs.eps
        for fun in self:
            rts = fun.roots()
            if prvrts.size > 0 and rts.size > 0:
                if abs(prvrts[-1]-rts[0]) <= htol:
                    rts = rts[1:]
            allrts.append(rts)
            prvrts = rts
        return concatenate([x for x in allrts])
    def cumsum(self):
        newfuns = []
        prevfun = None
        for fun in self:
            integral = fun.cumsum()
            if prevfun:
                _, fb = prevfun.endvalues
                integral = integral + fb
            newfuns.append(integral)
            prevfun = integral
        return self.__class__(newfuns)
    def diff(self):
        dfuns = array([fun.diff() for fun in self])
        return self.__class__(dfuns)
    def sum(self):
        return sum([fun.sum() for fun in self])
    def plot(self, ax=None, *args, **kwargs):
        ax = ax if ax else gca()
        a, b = self.support
        xx = linspace(a, b, 2001)
        ax.plot(xx, self(xx), *args, **kwargs)
        return ax
    def plotcoeffs(self, ax=None, *args, **kwargs):
        ax = ax if ax else gca()
        for fun in self:
            fun.plotcoeffs(ax=ax)
        return ax
    @self_empty()
    @cast_arg_to_chebfun
    def maximum(self, other):
        diffnc = self - other
        joined = self.domain.union(other.domain)
        newdom = joined.merge(diffnc.roots())
        funsA = self._break(newdom).funs
        funsB = other._break(newdom).funs
        x0 = mean(newdom[:2])
        if self(x0) > other(x0):
            funsA[1::2] = funsB[1::2]
        else:
            funsA[0::2] = funsB[0::2]
        funs = [x.simplify() for x in funsA]
        return self.__class__(funs)

class Stack(object):
    def __init__(self):
        self.items = []
    def isEmpty(self):
        return not bool(self.items)
    def push(self, value):
        self.items.append(value)
    def pop(self):
        value = self.items.pop()
        if value is not None:
            return value
        else:
            print("Stack is empty!")
    def size(self):
        return len(self.items)
    def peek(self):
        if self.items:
            return self.items[-1]
        else:
            print("Stack is Empty!")
    def __repr__(self):
        return repr(self.items)

class RecipeOldSubHeadingIngredient(object):
    openapi_types = {
        'name': 'list[str]',
        'ean': 'list[str]',
        'amount': 'list[IngredientOldAmount]',
        'amount_info': 'list[str]',
        'package_recipe': 'list[str]',
        'ingredient_type': 'list[str]'
    }
    attribute_map = {
        'name': 'Name',
        'ean': 'Ean',
        'amount': 'Amount',
        'amount_info': 'AmountInfo',
        'package_recipe': 'PackageRecipe',
        'ingredient_type': 'IngredientType'
    }
    def __init__(self, name=None, ean=None, amount=None, amount_info=None, package_recipe=None, ingredient_type=None, local_vars_configuration=None):  
        if local_vars_configuration is None:
            local_vars_configuration = Configuration()
        self.local_vars_configuration = local_vars_configuration
        self._name = None
        self._ean = None
        self._amount = None
        self._amount_info = None
        self._package_recipe = None
        self._ingredient_type = None
        self.discriminator = None
        if name is not None:
            self.name = name
        if ean is not None:
            self.ean = ean
        if amount is not None:
            self.amount = amount
        if amount_info is not None:
            self.amount_info = amount_info
        if package_recipe is not None:
            self.package_recipe = package_recipe
        if ingredient_type is not None:
            self.ingredient_type = ingredient_type
    @property
    def name(self):
        return self._name
    @name.setter
    def name(self, name):
        self._name = name
    @property
    def ean(self):
        return self._ean
    @ean.setter
    def ean(self, ean):
        self._ean = ean
    @property
    def amount(self):
        return self._amount
    @amount.setter
    def amount(self, amount):
        self._amount = amount
    @property
    def amount_info(self):
        return self._amount_info
    @amount_info.setter
    def amount_info(self, amount_info):
        self._amount_info = amount_info
    @property
    def package_recipe(self):
        return self._package_recipe
    @package_recipe.setter
    def package_recipe(self, package_recipe):
        self._package_recipe = package_recipe
    @property
    def ingredient_type(self):
        return self._ingredient_type
    @ingredient_type.setter
    def ingredient_type(self, ingredient_type):
        self._ingredient_type = ingredient_type
    def to_dict(self):
        result = {}
        for attr, _ in six.iteritems(self.openapi_types):
            value = getattr(self, attr)
            if isinstance(value, list):
                result[attr] = list(map(
                    lambda x: x.to_dict() if hasattr(x, "to_dict") else x,
                    value
                ))
            elif hasattr(value, "to_dict"):
                result[attr] = value.to_dict()
            elif isinstance(value, dict):
                result[attr] = dict(map(
                    lambda item: (item[0], item[1].to_dict())
                    if hasattr(item[1], "to_dict") else item,
                    value.items()
                ))
            else:
                result[attr] = value
        return result
    def to_str(self):
        return pprint.pformat(self.to_dict())
    def __repr__(self):
        return self.to_str()
    def __eq__(self, other):
        if not isinstance(other, RecipeOldSubHeadingIngredient):
            return False
        return self.to_dict() == other.to_dict()
    def __ne__(self, other):
        if not isinstance(other, RecipeOldSubHeadingIngredient):
            return True
        return self.to_dict() != other.to_dict()

class GDALRaster(GDALBase):
    destructor = capi.close_ds
    def __init__(self, ds_input, write=False):
        self._write = 1 if write else 0
        Driver.ensure_registered()
        if isinstance(ds_input, str) and json_regex.match(ds_input):
            ds_input = json.loads(ds_input)
        if isinstance(ds_input, str):
            if not os.path.exists(ds_input):
                raise GDALException('Unable to read raster source input "{}"'.format(ds_input))
            try:
                self._ptr = capi.open_ds(force_bytes(ds_input), self._write)
            except GDALException as err:
                raise GDALException('Could not open the datasource at "{}" ({}).'.format(ds_input, err))
        elif isinstance(ds_input, dict):
            self._write = 1
            driver = Driver(ds_input.get('driver', 'MEM'))
            if driver.name != 'MEM' and 'name' not in ds_input:
                raise GDALException('Specify name for creation of raster with driver "{}".'.format(driver.name))
            if 'width' not in ds_input or 'height' not in ds_input:
                raise GDALException('Specify width and height attributes for JSON or dict input.')
            if 'srid' not in ds_input:
                raise GDALException('Specify srid for JSON or dict input.')
            self._ptr = capi.create_ds(
                driver._ptr,
                force_bytes(ds_input.get('name', '')),
                ds_input['width'],
                ds_input['height'],
                ds_input.get('nr_of_bands', len(ds_input.get('bands', []))),
                ds_input.get('datatype', 6),
                None
            )
            for i, band_input in enumerate(ds_input.get('bands', [])):
                band = self.bands[i]
                if 'nodata_value' in band_input:
                    band.nodata_value = band_input['nodata_value']
                    if band.nodata_value is not None and (
                            'data' not in band_input or
                            'size' in band_input or
                            'shape' in band_input):
                        band.data(data=(band.nodata_value,), shape=(1, 1))
                band.data(
                    data=band_input.get('data'),
                    size=band_input.get('size'),
                    shape=band_input.get('shape'),
                    offset=band_input.get('offset'),
                )
            self.srs = ds_input.get('srid')
            if 'origin' in ds_input:
                self.origin.x, self.origin.y = ds_input['origin']
            if 'scale' in ds_input:
                self.scale.x, self.scale.y = ds_input['scale']
            if 'skew' in ds_input:
                self.skew.x, self.skew.y = ds_input['skew']
        elif isinstance(ds_input, c_void_p):
            self._ptr = ds_input
        else:
            raise GDALException('Invalid data source input type: "{}".'.format(type(ds_input)))
    def __str__(self):
        return self.name
    def __repr__(self):
        return '<Raster object at %s>' % hex(addressof(self._ptr))
    def _flush(self):
        if not self._write:
            raise GDALException('Raster needs to be opened in write mode to change values.')
        capi.flush_ds(self._ptr)
    @property
    def name(self):
        return force_text(capi.get_ds_description(self._ptr))
    @cached_property
    def driver(self):
        ds_driver = capi.get_ds_driver(self._ptr)
        return Driver(ds_driver)
    @property
    def width(self):
        return capi.get_ds_xsize(self._ptr)
    @property
    def height(self):
        return capi.get_ds_ysize(self._ptr)
    @property
    def srs(self):
        try:
            wkt = capi.get_ds_projection_ref(self._ptr)
            if not wkt:
                return None
            return SpatialReference(wkt, srs_type='wkt')
        except SRSException:
            return None
    @srs.setter
    def srs(self, value):
        if isinstance(value, SpatialReference):
            srs = value
        elif isinstance(value, (int, str)):
            srs = SpatialReference(value)
        else:
            raise ValueError('Could not create a SpatialReference from input.')
        capi.set_ds_projection_ref(self._ptr, srs.wkt.encode())
        self._flush()
    @property
    def srid(self):
        return self.srs.srid
    @srid.setter
    def srid(self, value):
        self.srs = value
    @property
    def geotransform(self):
        gtf = (c_double * 6)()
        capi.get_ds_geotransform(self._ptr, byref(gtf))
        return list(gtf)
    @geotransform.setter
    def geotransform(self, values):
        "Set the geotransform for the data source."
        if len(values) != 6 or not all(isinstance(x, (int, float)) for x in values):
            raise ValueError('Geotransform must consist of 6 numeric values.')
        values = (c_double * 6)(*values)
        capi.set_ds_geotransform(self._ptr, byref(values))
        self._flush()
    @property
    def origin(self):
        return TransformPoint(self, 'origin')
    @property
    def scale(self):
        return TransformPoint(self, 'scale')
    @property
    def skew(self):
        return TransformPoint(self, 'skew')
    @property
    def extent(self):
        xval = self.origin.x + self.scale.x * self.width
        yval = self.origin.y + self.scale.y * self.height
        xmin = min(xval, self.origin.x)
        xmax = max(xval, self.origin.x)
        ymin = min(yval, self.origin.y)
        ymax = max(yval, self.origin.y)
        return xmin, ymin, xmax, ymax
    @property
    def bands(self):
        return BandList(self)
    def warp(self, ds_input, resampling='NearestNeighbour', max_error=0.0):
        if 'width' not in ds_input:
            ds_input['width'] = self.width
        if 'height' not in ds_input:
            ds_input['height'] = self.height
        if 'srid' not in ds_input:
            ds_input['srid'] = self.srs.srid
        if 'origin' not in ds_input:
            ds_input['origin'] = self.origin
        if 'scale' not in ds_input:
            ds_input['scale'] = self.scale
        if 'skew' not in ds_input:
            ds_input['skew'] = self.skew
        if 'driver' not in ds_input:
            ds_input['driver'] = self.driver.name
        if 'name' not in ds_input:
            ds_input['name'] = self.name + '_copy.' + self.driver.name
        if 'datatype' not in ds_input:
            ds_input['datatype'] = self.bands[0].datatype()
        ds_input['bands'] = [{'nodata_value': bnd.nodata_value} for bnd in self.bands]
        target = GDALRaster(ds_input, write=True)
        algorithm = GDAL_RESAMPLE_ALGORITHMS[resampling]
        capi.reproject_image(
            self._ptr, self.srs.wkt.encode(),
            target._ptr, target.srs.wkt.encode(),
            algorithm, 0.0, max_error,
            c_void_p(), c_void_p(), c_void_p()
        )
        target._flush()
        return target
    def transform(self, srid, driver=None, name=None, resampling='NearestNeighbour',
                  max_error=0.0):
        algorithm = GDAL_RESAMPLE_ALGORITHMS[resampling]
        target_srs = SpatialReference(srid)
        target = capi.auto_create_warped_vrt(
            self._ptr, self.srs.wkt.encode(), target_srs.wkt.encode(),
            algorithm, max_error, c_void_p()
        )
        target = GDALRaster(target)
        data = {
            'srid': srid,
            'width': target.width,
            'height': target.height,
            'origin': [target.origin.x, target.origin.y],
            'scale': [target.scale.x, target.scale.y],
            'skew': [target.skew.x, target.skew.y],
        }
        if driver:
            data['driver'] = driver
        if name:
            data['name'] = name
        return self.warp(data, resampling=resampling, max_error=max_error)

class WorkerManager(object):
    def __init__(self, site):
        self.site = site
        self.workers = {}  
        self.tasks = []
        self.started_task_num = 0  
        self.asked_peers = []
        self.running = True
        self.time_task_added = 0
        self.log = logging.getLogger("WorkerManager:%s" % self.site.address_short)
        self.process_taskchecker = gevent.spawn(self.checkTasks)
    def __str__(self):
        return "WorkerManager %s" % self.site.address_short
    def __repr__(self):
        return "<%s>" % self.__str__()
    def checkTasks(self):
        while self.running:
            tasks = task = worker = workers = None  
            time.sleep(15)  
            for worker in self.workers.values():
                if worker.task and worker.task["done"]:
                    worker.skip()  
            if not self.tasks:
                continue
            tasks = self.tasks[:]  
            for task in tasks:
                size_extra_time = task["size"] / (1024 * 100)  
                if task["time_started"] and time.time() >= task["time_started"] + 60 + size_extra_time:
                    self.log.debug("Timeout, Skipping: %s" % task)  
                    workers = self.findWorkers(task)
                    if workers:
                        for worker in workers:
                            worker.skip()
                    else:
                        self.failTask(task)
                elif time.time() >= task["time_added"] + 60 + size_extra_time and not self.workers:  
                    self.log.debug("Timeout, Cleanup task: %s" % task)
                    self.failTask(task)
                elif (task["time_started"] and time.time() >= task["time_started"] + 15) or not self.workers:
                    workers = self.findWorkers(task)
                    self.log.debug(
                        "Slow task: %s 15+%ss, (workers: %s, optional_hash_id: %s, peers: %s, failed: %s, asked: %s)" %
                        (
                            task["inner_path"], size_extra_time, len(workers), task["optional_hash_id"],
                            len(task["peers"] or []), len(task["failed"]), len(self.asked_peers)
                        )
                    )
                    task["site"].announce(mode="more")  
                    if task["optional_hash_id"]:
                        if not task["time_started"]:
                            ask_limit = 20
                        elif task["priority"] > 0:
                            ask_limit = max(10, time.time() - task["time_started"])
                        else:
                            ask_limit = max(10, (time.time() - task["time_started"]) / 2)
                        if len(self.asked_peers) < ask_limit and len(task["peers"] or []) <= len(task["failed"]) * 2:
                            self.startFindOptional(find_more=True)
                    else:
                        if task["peers"]:  
                            self.log.debug("Task peer lock release: %s" % task["inner_path"])
                            task["peers"] = []
                            self.startWorkers()
                    break  
        self.log.debug("checkTasks stopped running")
    def getTask(self, peer):
        self.tasks.sort(key=lambda task: task["priority"] - task["workers_num"] * 5, reverse=True)
        for task in self.tasks:  
            if task["peers"] and peer not in task["peers"]:
                continue  
            if peer in task["failed"]:
                continue  
            if task["optional_hash_id"] and task["peers"] is None:
                continue  
            return task
    def removeGoodFileTasks(self):
        for task in self.tasks[:]:
            if task["inner_path"] not in self.site.bad_files:
                self.log.debug("No longer in bad_files, marking as good: %s" % task["inner_path"])
                task["done"] = True
                task["evt"].set(True)
                self.tasks.remove(task)
        if not self.tasks:
            self.started_task_num = 0
        self.site.updateWebsocket()
    def onPeers(self):
        self.startWorkers()
    def getMaxWorkers(self):
        if len(self.tasks) > 100:
            return config.connected_limit * 2
        else:
            return config.connected_limit
    def addWorker(self, peer):
        key = peer.key
        if key not in self.workers and len(self.workers) < self.getMaxWorkers():
            worker = Worker(self, peer)
            self.workers[key] = worker
            worker.key = key
            worker.start()
            return worker
        else:  
            return False
    def startWorkers(self, peers=None):
        if not self.tasks:
            return False  
        self.log.debug("Starting workers, tasks: %s, peers: %s, workers: %s" % (len(self.tasks), len(peers or []), len(self.workers)))
        if len(self.workers) >= self.getMaxWorkers() and not peers:
            return False  
        if not peers:
            peers = self.site.getConnectedPeers()
            if len(peers) < self.getMaxWorkers():
                peers += self.site.peers.values()[0:self.getMaxWorkers()]
        if type(peers) is set:
            peers = list(peers)
        random.shuffle(peers)
        for peer in peers:  
            if peers and peer not in peers:
                continue  
            worker = self.addWorker(peer)
            if worker:
                self.log.debug("Added worker: %s, workers: %s/%s" % (peer.key, len(self.workers), self.getMaxWorkers()))
    def findOptionalTasks(self, optional_tasks, reset_task=False):
        found = collections.defaultdict(list)  
        for peer in self.site.peers.values():
            if not peer.has_hashfield:
                continue
            hashfield_set = set(peer.hashfield)  
            for task in optional_tasks:
                optional_hash_id = task["optional_hash_id"]
                if optional_hash_id in hashfield_set:
                    if reset_task and len(task["failed"]) > 0:
                        task["failed"] = []
                    if peer in task["failed"]:
                        continue
                    found[optional_hash_id].append(peer)
                    if task["peers"] and peer not in task["peers"]:
                        task["peers"].append(peer)
                    else:
                        task["peers"] = [peer]
        return found
    def findOptionalHashIds(self, optional_hash_ids, limit=0):
        found = collections.defaultdict(list)  
        for peer in self.site.peers.values():
            if not peer.has_hashfield:
                continue
            hashfield_set = set(peer.hashfield)  
            for optional_hash_id in optional_hash_ids:
                if optional_hash_id in hashfield_set:
                    found[optional_hash_id].append(peer)
                    if limit and len(found[optional_hash_id]) >= limit:
                        optional_hash_ids.remove(optional_hash_id)
        return found
    def addOptionalPeers(self, found_ips):
        found = collections.defaultdict(list)
        for hash_id, peer_ips in found_ips.iteritems():
            task = [task for task in self.tasks if task["optional_hash_id"] == hash_id]
            if task:  
                task = task[0]
            else:
                continue
            for peer_ip in peer_ips:
                peer = self.site.addPeer(peer_ip[0], peer_ip[1], return_peer=True)
                if not peer:
                    continue
                if task["peers"] is None:
                    task["peers"] = []
                if peer not in task["peers"]:
                    task["peers"].append(peer)
                    found[hash_id].append(peer)
                if peer.hashfield.appendHashId(hash_id):  
                    peer.time_hashfield = None  
        return found
    @util.Noparallel(blocking=False, ignore_args=True)
    def startFindOptional(self, reset_task=False, find_more=False, high_priority=False):
        if len(self.tasks) < 20 or high_priority:
            time.sleep(0.01)
        if len(self.tasks) > 90:
            time.sleep(5)
        else:
            time.sleep(0.5)
        optional_tasks = [task for task in self.tasks if task["optional_hash_id"]]
        if not optional_tasks:
            return False
        optional_hash_ids = set([task["optional_hash_id"] for task in optional_tasks])
        time_tasks = self.time_task_added
        self.log.debug(
            "Finding peers for optional files: %s (reset_task: %s, find_more: %s)" %
            (optional_hash_ids, reset_task, find_more)
        )
        found = self.findOptionalTasks(optional_tasks, reset_task=reset_task)
        if found:
            found_peers = set([peer for peers in found.values() for peer in peers])
            self.startWorkers(found_peers)
        if len(found) < len(optional_hash_ids) or find_more or (high_priority and any(len(peers) < 10 for peers in found.itervalues())):
            self.log.debug("No local result for optional files: %s" % (optional_hash_ids - set(found)))
            threads = []
            peers = self.site.getConnectedPeers()
            if not peers:
                peers = self.site.getConnectablePeers()
            for peer in peers:
                if not peer.time_hashfield:
                    threads.append(gevent.spawn(peer.updateHashfield))
            gevent.joinall(threads, timeout=5)
            if time_tasks != self.time_task_added:  
                optional_tasks = [task for task in self.tasks if task["optional_hash_id"]]
                optional_hash_ids = set([task["optional_hash_id"] for task in optional_tasks])
            found = self.findOptionalTasks(optional_tasks)
            self.log.debug("Found optional files after query hashtable connected peers: %s/%s" % (
                len(found), len(optional_hash_ids)
            ))
            if found:
                found_peers = set([peer for hash_id_peers in found.values() for peer in hash_id_peers])
                self.startWorkers(found_peers)
        if len(found) < len(optional_hash_ids) or find_more:
            self.log.debug("No connected hashtable result for optional files: %s" % (optional_hash_ids - set(found)))
            threads = []
            peers = [peer for peer in self.site.getConnectedPeers() if peer not in self.asked_peers]
            if not peers:
                peers = self.site.getConnectablePeers()
            for peer in peers:
                threads.append(gevent.spawn(peer.findHashIds, list(optional_hash_ids)))
                self.asked_peers.append(peer)
            for i in range(5):
                time.sleep(1)
                thread_values = [thread.value for thread in threads if thread.value]
                if not thread_values:
                    continue
                found_ips = helper.mergeDicts(thread_values)
                found = self.addOptionalPeers(found_ips)
                self.log.debug("Found optional files after findhash connected peers: %s/%s (asked: %s)" % (
                    len(found), len(optional_hash_ids), len(threads)
                ))
                if found:
                    found_peers = set([peer for hash_id_peers in found.values() for peer in hash_id_peers])
                    self.startWorkers(found_peers)
                if len(thread_values) == len(threads):
                    break
        if len(found) < len(optional_hash_ids):
            self.log.debug("No findHash result, try random peers: %s" % (optional_hash_ids - set(found)))
            if time_tasks != self.time_task_added:  
                optional_tasks = [task for task in self.tasks if task["optional_hash_id"]]
                optional_hash_ids = set([task["optional_hash_id"] for task in optional_tasks])
            threads = []
            peers = self.site.getConnectablePeers(ignore=self.asked_peers)
            for peer in peers:
                threads.append(gevent.spawn(peer.findHashIds, list(optional_hash_ids)))
                self.asked_peers.append(peer)
            gevent.joinall(threads, timeout=15)
            found_ips = helper.mergeDicts([thread.value for thread in threads if thread.value])
            found = self.addOptionalPeers(found_ips)
            self.log.debug("Found optional files after findhash random peers: %s/%s" % (len(found), len(optional_hash_ids)))
            if found:
                found_peers = set([peer for hash_id_peers in found.values() for peer in hash_id_peers])
                self.startWorkers(found_peers)
        if len(found) < len(optional_hash_ids):
            self.log.debug("No findhash result for optional files: %s" % (optional_hash_ids - set(found)))
    def stopWorkers(self):
        for worker in self.workers.values():
            worker.stop()
        tasks = self.tasks[:]  
        for task in tasks:  
            self.failTask(task)
    def findWorkers(self, task):
        workers = []
        for worker in self.workers.values():
            if worker.task == task:
                workers.append(worker)
        return workers
    def removeWorker(self, worker):
        worker.running = False
        if worker.key in self.workers:
            del(self.workers[worker.key])
            self.log.debug("Removed worker, workers: %s/%s" % (len(self.workers), self.getMaxWorkers()))
        if len(self.workers) <= self.getMaxWorkers() / 3 and len(self.asked_peers) < 10:
            important_task = (task for task in self.tasks if task["priority"] > 0)
            if next(important_task, None) or len(self.asked_peers) == 0:
                self.startFindOptional(find_more=True)
            else:
                self.startFindOptional()
    def getPriorityBoost(self, inner_path):
        if inner_path == "content.json":
            return 9999  
        if inner_path == "index.html":
            return 9998  
        if "-default" in inner_path:
            return -4  
        elif inner_path.endswith(".css"):
            return 5  
        elif inner_path.endswith(".js"):
            return 4  
        elif inner_path.endswith("dbschema.json"):
            return 3  
        elif inner_path.endswith("content.json"):
            return 1  
        elif inner_path.endswith(".json"):
            return 2  
        return 0
    def addTask(self, inner_path, peer=None, priority=0):
        self.site.onFileStart(inner_path)  
        task = self.findTask(inner_path)
        if task:  
            if peer and task["peers"]:  
                task["peers"].append(peer)
                self.log.debug("Added peer %s to %s" % (peer.key, task["inner_path"]))
                self.startWorkers([peer])
            elif peer and peer in task["failed"]:
                task["failed"].remove(peer)  
                self.log.debug("Removed peer %s from failed %s" % (peer.key, task["inner_path"]))
                self.startWorkers([peer])
            if priority:
                task["priority"] += priority  
            return task["evt"]
        else:  
            evt = gevent.event.AsyncResult()
            if peer:
                peers = [peer]  
            else:
                peers = None
            file_info = self.site.content_manager.getFileInfo(inner_path)
            if file_info and file_info["optional"]:
                optional_hash_id = helper.toHashId(file_info["sha512"])
            else:
                optional_hash_id = None
            if file_info:
                size = file_info.get("size", 0)
            else:
                size = 0
            priority += self.getPriorityBoost(inner_path)
            task = {
                "evt": evt, "workers_num": 0, "site": self.site, "inner_path": inner_path, "done": False,
                "optional_hash_id": optional_hash_id, "time_added": time.time(), "time_started": None,
                "time_action": None, "peers": peers, "priority": priority, "failed": [], "size": size
            }
            self.tasks.append(task)
            self.started_task_num += 1
            self.log.debug(
                "New task: %s, peer lock: %s, priority: %s, optional_hash_id: %s, tasks started: %s" %
                (task["inner_path"], peers, priority, optional_hash_id, self.started_task_num)
            )
            self.time_task_added = time.time()
            if optional_hash_id:
                if self.asked_peers:
                    del self.asked_peers[:]  
                self.startFindOptional(high_priority=priority > 0)
                if peers:
                    self.startWorkers(peers)
            else:
                self.startWorkers(peers)
            return evt
    def findTask(self, inner_path):
        for task in self.tasks:
            if task["inner_path"] == inner_path:
                return task
        return None  
    def checkComplete(self):
        time.sleep(0.1)
        if not self.tasks:
            self.log.debug("Check compelte: No tasks")
            self.onComplete()
    def onComplete(self):
        self.started_task_num = 0
        del self.asked_peers[:]
        self.site.onComplete()  
    def doneTask(self, task):
        task["done"] = True
        self.tasks.remove(task)  
        if task["optional_hash_id"]:
            self.log.debug("Downloaded optional file, adding to hashfield: %s" % task["inner_path"])
            self.site.content_manager.optionalDownloaded(task["inner_path"], task["optional_hash_id"], task["size"])
        self.site.onFileDone(task["inner_path"])
        task["evt"].set(True)
        if not self.tasks:
            gevent.spawn(self.checkComplete)
    def failTask(self, task):
        if task in self.tasks:
            task["done"] = True
            self.tasks.remove(task)  
            self.site.onFileFail(task["inner_path"])
            task["evt"].set(False)
            if not self.tasks:
                self.started_task_num = 0

