class SourceCode:
    gitignore_filter: igittigitt.IgnoreParser
    project_root: Path
    root_directory: Path
    def __init__(
        self,
        root_directory: StrPath,
        *,
        gitignore_filter: Optional[igittigitt.IgnoreParser] = None,
        include_files_in_hash: Optional[Sequence[Path]] = None,
        project_root: Optional[StrPath] = None,
    ) -> None:
        self._include_files_in_hash = include_files_in_hash or []
        self.gitignore_filter = gitignore_filter or igittigitt.IgnoreParser()
        self.root_directory = (
            root_directory if isinstance(root_directory, Path) else Path(root_directory)
        )
        self.project_root = (  
            project_root
            if isinstance(project_root, Path)
            else (Path(project_root) if project_root else self.root_directory)
        )
        if not gitignore_filter:
            self.gitignore_filter.parse_rule_files(self.root_directory)
            self.gitignore_filter.add_rule(".git/", self.root_directory)
            self.gitignore_filter.add_rule(".gitignore", self.root_directory)
    @cached_property
    def md5_hash(self) -> str:
        sorted_files = list(self.sorted())
        for include_file in self._include_files_in_hash:
            if include_file not in sorted_files:
                sorted_files.append(include_file)
        file_hash = FileHash(hashlib.md5())
        file_hash.add_files(sorted(sorted_files), relative_to=self.project_root)
        return file_hash.hexdigest
    def add_filter_rule(self, pattern: str) -> None:
        self.gitignore_filter.add_rule(pattern=pattern, base_path=self.root_directory)
    def sorted(self, *, reverse: bool = False) -> List[Path]:
        return sorted(self, reverse=reverse)
    def __eq__(self, other: object) -> bool:
        if isinstance(other, SourceCode):
            return self.root_directory == other.root_directory
        return False
    def __fspath__(self) -> Union[str, bytes]:
        return str(self.root_directory)
    def __iter__(self) -> Iterator[Path]:
        for child in self.root_directory.rglob("*"):
            if child.is_dir():
                continue  
            if self.gitignore_filter.match(child):
                continue  
            yield child
    def __str__(self) -> str:
        return str(self.root_directory)
    def __truediv__(self, other: StrPath) -> Path:
        return self.root_directory / other

class Datetime(DatetimeStruct):
    _doc = {
        "year": "1 <= year <= 9999",
        "month": "1 <= month <= 12",
        "day": "1 <= day <= number of days in the given month and year",
        "hour": "0 <= hour < 24",
        "minute": "0 <= minute < 60",
        "second": "0 <= second < 60",
        "microsecond": "0 <= microsecond < 1000000",
    }
    _constructor = "wf.datetime.from_components"
    def __init__(self, year, month=1, day=1, hour=0, minute=0, second=0, microsecond=0):
        "Construct a `Datetime` from components. All parts are optional besides ``year``."
        super(Datetime, self).__init__(
            year=year,
            month=month,
            day=day,
            hour=hour,
            minute=minute,
            second=second,
            microsecond=microsecond,
        )
    @classmethod
    def _promote(cls, obj):
        if isinstance(obj, cls):
            return obj
        if isinstance(obj, Any):
            return obj.cast(cls)
        try:
            return cls.from_string(obj.isoformat())
        except AttributeError:
            if isinstance(obj, six.string_types):
                return cls.from_string(obj)
            if isinstance(obj, numbers.Number):
                return cls.from_timestamp(obj)
            return super(cls, cls)._promote(obj)
    @classmethod
    @typecheck_promote((Int, Float))
    def from_timestamp(cls, seconds):
        return cls._from_apply("wf.datetime.from_timestamp", seconds)
    @classmethod
    @typecheck_promote(Str)
    def from_string(cls, string):
        return cls._from_apply("wf.datetime.from_string", string)
    @typecheck_promote(Timedelta)
    def __add__(self, other):
        return self._from_apply("wf.add", self, other)
    @typecheck_promote(Timedelta)
    def __radd__(self, other):
        return self._from_apply("wf.add", other, self)
    @typecheck_promote(lambda: (Timedelta, Datetime))
    def __sub__(self, other):
        return _binary_op_casts_to(self, other)._from_apply("wf.sub", self, other)
    @typecheck_promote(Timedelta)
    def __mod__(self, other):
        return Timedelta._from_apply("wf.mod", self, other)
    @typecheck_promote(Timedelta)
    def __floordiv__(self, other):
        return self._from_apply("wf.floordiv", self, other)
    @typecheck_promote(Timedelta)
    def __divmod__(self, other):
        return Tuple[type(self), Timedelta]._from_apply("wf.divmod", self, other)
    @typecheck_promote(lambda: Datetime)
    def __eq__(self, other):
        return Bool._from_apply("wf.eq", self, other)
