class Population(object):
    def __init__(self, position, radius, velocity, health_state, **kwargs):
        self.X = np.array(position)
        self.R = np.reshape(radius, (-1, 1))
        self.V = np.array(velocity)
        self.state = np.reshape(health_state, (-1, 1))
        self.time = 0  
        self.mask = kwargs.get("mask", np.zeros([self.NP, 1]))
        self.contact = np.array([])
        self.distance = np.array([])
        self.hist_time, self.hist_sick, self.hist_health = [], [], []
    def __repr__(self):
        line1 = "A {} including {} persons of {} dimensions:\n{}".format(
            type(self).__name__, self.shape[0], self.shape[1], self.X)
        return line1
    def __len__(self):
        return self.NP
    @property
    def NP(self):
        return self.shape[0]
    @property
    def shape(self):
        return self.X.shape
    @property
    def R(self):
        return self._R
    @R.setter
    def R(self, array):
        self._R = array
        _ = np.tile(self._R, self.NP)
        self.R_sum = _ + _.transpose()  
        np.fill_diagonal(self.R_sum,
                         1)  
    @property
    def X_last(self):
        return self._X_last
    @X_last.setter
    def X_last(self, array):
        self._X_last = deepcopy(array)
    def update_statistic(self):
        self.total_sick = self.state[self.state >= 1].size
        self.total_health = self.NP - self.total_sick
    def save_to_history(self):
        self.hist_time.append(self.time)
        self.hist_sick.append(self.total_sick)
        self.hist_health.append(self.total_health)
    def plot_history(self, show=False, save=True, **kwargs):
        fig, axis = plt.subplots()
        axis.plot(self.hist_time, self.hist_sick, ".", label="Sick")
        axis.plot(self.hist_time, self.hist_health, ".", label="Health")
        axis.legend()
        axis.set(
            xlabel="Time (s)",
            ylabel="Number of people",
            title=kwargs.get("title"))
        if show == True:
            plt.show()
        if save == True:
            filename = kwargs.get("filename", "default.png")
            plt.savefig(filename)
            print("[OK] figure '{}' saved to disk !".format(filename))
    def save_to_json(self, filename):
        data = {
            "hist_time": self.hist_time,
            "hist_sick": self.hist_sick,
            "hist_health": self.hist_health
        }
        encode = json.dumps(data, indent=4)
        p = Path(filename)
        with p.open("w", encoding="utf-8") as f:
            f.write(encode)
        print("[OK] data '{}' saved to disk !".format(filename))

class SequencePoint(BaseSequenceLocation):
    def __new__(cls, position, *args, **kwargs):
        if isinstance(position, cls.mro()[1]):  
            if isinstance(position, cls):
                return position
            elif hasattr(position, 'start') and hasattr(position, 'stop'):
                if len(position) == 1:
                    return position.start
                raise TypeError("can only Convert {} to {} if len({}) = 1".format(
                    type(position), cls, type(position)))
        return super().__new__(cls)
    def __init__(self, position: point_types, *, validate=True):
        if isinstance(position, self.__class__.mro()[1]):  
            return
        self._pos = int(position)
        if validate:
            self.validate()
        self._index = self._pos - 1
        self._slice = slice(self.index, self.index + 1)
    @classmethod
    def from_index(cls, index: Union[int, Sequence], *, validate=True):
        if isinstance(index, cls.mro()[1]):  
            raise ValueError("index, cannot be of type {}".format(repr(index)))
        return cls(index + 1, validate=validate)
    def validate(self):
        if self.pos < 1:
            raise ValueError("position({}) < 1".format(self.pos))
    def _join(self, other, operator):
        return self.__class__.from_index(operator(self.index, other.index), validate=False)
    @property
    def pos(self):
        return self._pos
    @property
    def index(self):
        return self._index
    @property
    def slice(self):
        return self._slice
    def __str__(self):
        return str(self.pos)
    def __repr__(self):
        return "{}({})".format(type(self).__name__, self.pos)
    def __getnewargs__(self):
        return (self.pos,)

class Equation(object):
    def __init__(self, variables: int, clauses: int, conjunctives: list):
        self._variables = variables
        self._clauses = clauses
        self._conjunctives = conjunctives
        self._equation = self.__build_equation()
    def __repr__(self):
        return self._equation
    def __build_equation(self):
        e = []
        for i, conj in enumerate(self._conjunctives):
            e.append('(')
            for j, v in enumerate(conj):
                if v < 0:
                    e.append('¬' + str(abs(v)))
                else:
                    e.append(str(v))
                if j != len(conj) - 1:
                    e.append('∨')
            e.append(')')
            if i != len(self._conjunctives) - 1:
                e.append('∧')
        return ''.join(e)
    @property
    def clauses(self) -> int:
        return self._clauses
    @property
    def variables(self) -> int:
        return self._variables
    def check(self, chromosome):
        passed_clauses = 0
        for conjunctive in self._conjunctives:
            for v in conjunctive:
                if v < 0:
                    if not chromosome[abs(v) - 1]:
                        passed_clauses += 1
                        break
                else:
                    if chromosome[v - 1]:
                        passed_clauses += 1
                        break
        return passed_clauses, passed_clauses == self._clauses

class Chromosome(object):
    def __init__(self, equation: Equation, genes: list):
        self._equation = equation
        self._genes = genes
        self._valid = None
        self._fitness = None
    def __getitem__(self, index: int):
        return self._genes[index]
    def __len__(self) -> int:
        return len(self._genes)
    def __repr__(self) -> str:
        return ''.join(map(str, self._genes))
    def __setitem__(self, key: int, value: int):
        self._genes[key] = value
        self._fitness = None
        self._valid = None
    @property
    def equation(self) -> Equation:
        return self._equation
    @property
    def fitness(self):
        if self._fitness is None:
            clauses, passed = self._equation.check(self)
            self._fitness = clauses / self._equation.clauses
            self._valid = passed
        return self._fitness
    @property
    def genes(self):
        return self._genes
    @genes.setter
    def genes(self, value: str):
        self._genes = value
        self._fitness = None
        self._valid = None
    @property
    def valid(self) -> bool:
        if self._valid is None:
            clauses, passed = self._equation.check(self)
            self._fitness = clauses / self._equation.clauses
            self._valid = passed
        return self._valid
    def copy(self):
        return Chromosome(self._equation, self._genes[:])

class Population(object):
    def __init__(self, size:int, equation: Equation):
        self._size = size
        self._equation = equation
        self._chromosomes = []
        self._fittest = None
    def __getitem__(self, index: int) -> Chromosome:
        return self._chromosomes[index]
    def __len__(self) -> int:
        return len(self._chromosomes)
    def __repr__(self):
        return str(self._chromosomes)
    def __setitem__(self, key: int, value: Chromosome):
        self._chromosomes[key] = value
        self._fittest = None
    @property
    def equation(self) -> Equation:
        return self._equation
    @property
    def fittest(self):
        if self._fittest is None:
            for chromosome in self._chromosomes:
                if self._fittest is None:
                    self._fittest = chromosome
                else:
                    if self._fittest.fitness < chromosome.fitness:
                        self._fittest = chromosome
        return self._fittest
    @property
    def chromosomes(self) -> list:
        return self._chromosomes[:]
    @property
    def size(self) -> int:
        return self._size
    def add(self, chromosome: Chromosome):
        self._chromosomes.append(chromosome)
        self._fittest = None
    def initialize(self):
        for i in range(self.size):
            genes = [random.choice([0, 1]) for _ in range(self._equation.variables)]
            self.add(Chromosome(self._equation, genes))

