class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y
    @classmethod
    def zero(cls):   
        return cls(0, 0)
    def __str__(self):   
        return f"({self.x}, {self.y})"
    def __eq__(self, other):
        return self.x == other.x and self.y == other.y
    def __ne__(self, other):
        return not self.__eq__(other)
    def __ge__(self, other):
        return self.x >= other.x and self.y >= other.y
    def __lt__(self, other):
        return not self.__ge__(other)
    def __add__(self, other):
        return Point(self.x + other.x, self.y + other.y)
    def __sub__(self, other):
        return Point(self.x - other.x, self.y - other.y)
    def __mul__(self, other):
        return Point(other * self.x, other * self.y)
    def __hash__(self):
        return hash((self.x, self.y))

class DjangoTranslation(gettext_module.GNUTranslations):
    domain = 'djmodels'
    def __init__(self, language, domain=None, localedirs=None):
        gettext_module.GNUTranslations.__init__(self)
        if domain is not None:
            self.domain = domain
        self.__language = language
        self.__to_language = to_language(language)
        self.__locale = to_locale(language)
        self._catalog = None
        self.plural = lambda n: int(n != 1)
        if self.domain == 'djmodels':
            if localedirs is not None:
                warnings.warn("localedirs is ignored when domain is 'djmodels'.", RuntimeWarning)
                localedirs = None
            self._init_translation_catalog()
        if localedirs:
            for localedir in localedirs:
                translation = self._new_gnu_trans(localedir)
                self.merge(translation)
        else:
            self._add_installed_apps_translations()
        self._add_local_translations()
        if self.__language == settings.LANGUAGE_CODE and self.domain == 'djmodels' and self._catalog is None:
            raise IOError("No translation files found for default language %s." % settings.LANGUAGE_CODE)
        self._add_fallback(localedirs)
        if self._catalog is None:
            self._catalog = {}
    def __repr__(self):
        return "<DjangoTranslation lang:%s>" % self.__language
    def _new_gnu_trans(self, localedir, use_null_fallback=True):
        return gettext_module.translation(
            domain=self.domain,
            localedir=localedir,
            languages=[self.__locale],
            codeset='utf-8',
            fallback=use_null_fallback,
        )
    def _init_translation_catalog(self):
        settingsfile = sys.modules[settings.__module__].__file__
        localedir = os.path.join(os.path.dirname(settingsfile), 'locale')
        translation = self._new_gnu_trans(localedir)
        self.merge(translation)
    def _add_installed_apps_translations(self):
        try:
            app_configs = reversed(list(apps.get_app_configs()))
        except AppRegistryNotReady:
            raise AppRegistryNotReady(
                "The translation infrastructure cannot be initialized before the "
                "apps registry is ready. Check that you don't make non-lazy "
                "gettext calls at import time.")
        for app_config in app_configs:
            localedir = os.path.join(app_config.path, 'locale')
            if os.path.exists(localedir):
                translation = self._new_gnu_trans(localedir)
                self.merge(translation)
    def _add_local_translations(self):
        for localedir in reversed(settings.LOCALE_PATHS):
            translation = self._new_gnu_trans(localedir)
            self.merge(translation)
    def _add_fallback(self, localedirs=None):
        if self.__language == settings.LANGUAGE_CODE or self.__language.startswith('en'):
            return
        if self.domain == 'djmodels':
            default_translation = translation(settings.LANGUAGE_CODE)
        else:
            default_translation = DjangoTranslation(
                settings.LANGUAGE_CODE, domain=self.domain, localedirs=localedirs
            )
        self.add_fallback(default_translation)
    def merge(self, other):
        if not getattr(other, '_catalog', None):
            return  
        if self._catalog is None:
            self.plural = other.plural
            self._info = other._info.copy()
            self._catalog = other._catalog.copy()
        else:
            self._catalog.update(other._catalog)
        if other._fallback:
            self.add_fallback(other._fallback)
    def language(self):
        return self.__language
    def to_language(self):
        return self.__to_language

class ThreeCardPokerHand(Hand):
    all_labels = ['Nothing', 'Pair', 'Flush', 'Straight', 'Three of a Kind',
                  'Straight Flush']
    def _compute_rank(self):
        Card.ranks[9] = '11' 
        Card.ranks[10] = '12' 
        Card.ranks[11] = '13' 
        Card.ranks[12] = '14' 
        if len(set(self.suits)) == 1 and (int(self.ranks[0]) - int(self.ranks[2]) == 2 or int(self.ranks[0]) - int(self.ranks[2]) == 12):
            self.rank = 5
        elif len(set(self.ranks)) == 1:
            self.rank = 4
        elif int(self.ranks[0]) - int(self.ranks[2]) == 2 or int(self.ranks[0]) - int(self.ranks[2]) == 12:
            self.rank = 3
        elif len(set(self.suits)) == 1 and int(self.ranks[0]) - int(self.ranks[2]) != 2:
                self.rank = 2
        elif self.ranks[0] == self.ranks[1] and self.ranks[0] != self.ranks[2]:
            self.rank = 1
        elif self.ranks[0] == self.ranks[2] and self.ranks[0] != self.ranks[1]:
            self.rank = 1
        elif self.ranks[1] == self.ranks[2] and self.ranks[0] != self.ranks[2]:
            self.rank = 1
        else:
            self.rank = 0
        Card.ranks[9] = 'Jack'
        Card.ranks[10] = 'Queen' 
        Card.ranks[11] = 'King' 
        Card.ranks[12] = 'Ace' 
    def _compare(self, other):
        Card.ranks[9] = '11' 
        Card.ranks[10] = '12' 
        Card.ranks[11] = '13' 
        Card.ranks[12] = '14' 
        if self.rank > other.rank:
            return 1
        elif other.rank > self.rank:
            return -1
        elif self.rank == other.rank:
            if self.rank == 5:
                Card.ranks[12] = '1'
                if max(self.ranks) > max(other.ranks):
                    return 1
                elif max(other.ranks) > max(self.ranks):
                    return -1
                else:
                    return 0
            elif self.rank == 3:
