    @contextlib.contextmanager
    def _optional_conn_ctx_manager(self, connection=None):
        if connection is None:
            with self._contextual_connect() as conn:
                yield conn
        else:
            yield connection
    def _run_visitor(
        self, visitorcallable, element, connection=None, **kwargs
    ):
        with self._optional_conn_ctx_manager(connection) as conn:
            conn._run_visitor(visitorcallable, element, **kwargs)
    class _trans_ctx(object):
        def __init__(self, conn, transaction, close_with_result):
            self.conn = conn
            self.transaction = transaction
            self.close_with_result = close_with_result
        def __enter__(self):
            return self.conn
        def __exit__(self, type_, value, traceback):
            if type_ is not None:
                self.transaction.rollback()
            else:
                self.transaction.commit()
            if not self.close_with_result:
                self.conn.close()
    def begin(self, close_with_result=False):
        conn = self._contextual_connect(close_with_result=close_with_result)
        try:
            trans = conn.begin()
        except:
            with util.safe_reraise():
                conn.close()
        return Engine._trans_ctx(conn, trans, close_with_result)
    def transaction(self, callable_, *args, **kwargs):
        r
        with self._contextual_connect() as conn:
            return conn.transaction(callable_, *args, **kwargs)
    def run_callable(self, callable_, *args, **kwargs):
        r
        with self._contextual_connect() as conn:
            return conn.run_callable(callable_, *args, **kwargs)
    def execute(self, statement, *multiparams, **params):
        connection = self._contextual_connect(close_with_result=True)
        return connection.execute(statement, *multiparams, **params)
    def scalar(self, statement, *multiparams, **params):
        return self.execute(statement, *multiparams, **params).scalar()
    def _execute_clauseelement(self, elem, multiparams=None, params=None):
        connection = self._contextual_connect(close_with_result=True)
        return connection._execute_clauseelement(elem, multiparams, params)
    def _execute_compiled(self, compiled, multiparams, params):
        connection = self._contextual_connect(close_with_result=True)
        return connection._execute_compiled(compiled, multiparams, params)
    def connect(self, **kwargs):
        return self._connection_cls(self, **kwargs)
    @util.deprecated(
        "1.3",
        "The :meth:`_engine.Engine.contextual_connect` method is deprecated. "
        "This "
        "method is an artifact of the threadlocal engine strategy which is "
        "also to be deprecated.   For explicit connections from an "
        ":class:`_engine.Engine`, use the :meth:`_engine.Engine.connect` "
        "method.",
    )
    def contextual_connect(self, close_with_result=False, **kwargs):
        return self._contextual_connect(
            close_with_result=close_with_result, **kwargs
        )
    def _contextual_connect(self, close_with_result=False, **kwargs):
        return self._connection_cls(
            self,
            self._wrap_pool_connect(self.pool.connect, None),
            close_with_result=close_with_result,
            **kwargs
        )
    def table_names(self, schema=None, connection=None):
        with self._optional_conn_ctx_manager(connection) as conn:
            return self.dialect.get_table_names(conn, schema)
    def has_table(self, table_name, schema=None):
        return self.run_callable(self.dialect.has_table, table_name, schema)
    def _wrap_pool_connect(self, fn, connection):
        dialect = self.dialect
        try:
            return fn()
        except dialect.dbapi.Error as e:
            if connection is None:
                Connection._handle_dbapi_exception_noconnection(
                    e, dialect, self
                )
            else:
                util.raise_(
                    sys.exc_info()[1], with_traceback=sys.exc_info()[2]
                )
    def raw_connection(self, _connection=None):
        return self._wrap_pool_connect(
            self.pool.unique_connection, _connection
        )

class Action(object):
    def __init__(self,tower_init,tower_target,**kwords):
        while [0,0] in tower_init  :
            tower_init.remove([0,0])
        while [0,0] in tower_target:
            tower_target.remove([0,0])
        self.t_init = tower_init
        self.t_target = tower_target
        self.size_t_init = len(self.t_init)
        self.size_t_target = len(self.t_target)
        self.kwords = kwords
        self.weight = self._compute_weight()
        self.t_target.extend(self.t_init) 
        self.t_target.append(self.weight)
        self.representation = self._make_representation()
        if 'sub_board' in kwords :
            pass 
    def __eq__(self,other):
        return self.representation == other.representation
    def __hash__(self):
        return self.representation
    def _make_representation(self):
        return hash(str(self.t_target))
    def _weight(self):
        if self.size_t_init == 2 and self.size_t_target == 2 : 
            self.weight = 1
        elif self.size_t_init == 3 and self.size_t_target == 3 : 
            self.weight = 3
        elif self.size_t_init == 2 and self.size_t_target == 3 :
            self.weight = 2
        elif self.size_t_init == 3 and self.size_t_target == 2 :
            self.weight = 2 
        elif self.size_t_init == 4 and self.size_t_target == 2 :
            self.weight = 3
        elif self.size_t_init == 2 and self.size_t_target == 4 :
            self.weight = 3        
    def _detect_sandwich(self):
            if self.size_t_init > 1 and self.size_t_target > 1:
                if (self.t_init[1][0] == Color.RED and self.t_target[self.size_t_target-1][1] == Color.RED) \
                    or (self.t_init[1][0] == Color.YELLOW and self.t_target[self.size_t_target-1][1] == Color.YELLOW):
                    i = 1
                    while i < self.size_t_init :
                        if i == 1:
                            self.t_init[i][1] = -2
                        else :
                            self.t_init[i][0] = -2
                            self.t_init[i][1] = -2
                        i+=1
                    i = 1
                    while i < self.size_t_target :
                        if i == self.size_t_target-1 :
                            self.t_target[i][0] = -2
                        else :
                            self.t_target[i][0] = -2
                            self.t_target[i][1] = -2
                        i+=1 
                    self._weight()
                    if self.t_init[1][0] == Color.YELLOW :
                        self.weight = -self.weight
                    self.t_target.pop(0)
                    self.t_init.pop(0)
                    return True
                else :
                    return False
            else :
                return False
    def _detect_color_up(self):
        if self.size_t_init + self.size_t_target == 6 and self.size_t_target >1 :
            if self.t_init[self.size_t_init-1][1] == Color.YELLOW or self.t_init[self.size_t_init-1][1] == Color.RED :
                i = 1
                while i < self.size_t_init :
                    if i == self.size_t_init-1:
                        self.t_init[i][0] = -2
                    else :
                        self.t_init[i][0] = -2
                        self.t_init[i][1] = -2
                    i+=1
                i = 1
                while i < self.size_t_target :
                    if i > 1 :
                        self.t_target[i][0] = -2
                        self.t_target[i][1] = -2
                    i+=1 
                self._weight()
                if self.t_init[self.size_t_init-1][1] == Color.RED and self.t_target[0] == 4 :
                    self.weight = -self.weight
                elif self.t_init[self.size_t_init-1][1] == Color.YELLOW and self.t_target[0] == 3 and \
                    self.t_target[1][0] != Color.YELLOW :
                    self.t_target[1][0] = 2
                    self.weight = -self.weight
                elif self.t_init[self.size_t_init-1][1] == Color.RED and self.t_target[0] == 3 and \
                    self.t_target[1][0] == Color.RED :
                    self.weight = -self.weight
                    self.t_target[1][0] = 2
                self.t_init.pop(0)
                return True
        return False
    def _detect_color_bot(self):
        if self.size_t_init + self.size_t_target == 6 and self.size_t_target > 1 :
            if (self.t_target[1][0] == Color.YELLOW or self.t_target[1][0] == Color.RED) and self.t_target[0] == 3 :
                i = 1
                while i < self.size_t_init :
                        self.t_init[i][0] = -2
                        self.t_init[i][1] = -2
                        i+=1 
                i = 1
                while i < self.size_t_target :
                    if i == 1 :
                        self.t_target[i][1] = -2
                    else :
                        self.t_target[i][0] = -2
                        self.t_target[i][1] = -2
                    i+=1
                self._weight()
                if self.t_target[1][0] == Color.RED :
                    self.weight = -self.weight
                self.t_init.pop(0)
                return True
        return False
    def _compute_weight(self):
        self.weight = 0
        if 'sub_borad' in self.kwords :
            pass
        else :
            if self._detect_sandwich() :
                return self.weight
            if self._detect_color_up() :
                return self.weight
            if self._detect_color_bot() :
                return self.weight
            else: return 0
    def is_a_pattern(self,dico):
        return self in dico

class Pieces:
    PADDING = 15
    BORDER = 3
    def __init__(self, row, column, color):
        self.row = row
        self.column = column
        self.color = color
        self.x = 0
        self.y = 0
        self.calculate_position()
    def calculate_position(self):
        self.x = SQUARE_SIZE * self.column + SQUARE_SIZE // 2  
        self.y = SQUARE_SIZE * self.row + SQUARE_SIZE // 2
    def draw(self, window):
        pygame.draw.circle(window, RED, (self.x, self.y),
                           SQUARE_SIZE // 2 - self.PADDING + self.BORDER)  
        pygame.draw.circle(window, self.color, (self.x, self.y), SQUARE_SIZE // 2 - self.PADDING)
    def move(self, row, column):
        self.row = row
        self.column = column
        self.calculate_position()
    def __repr__(self):
        return str(self.color)

class Rule(Flowable):
    _fixedWidth = False
    _fixedHeight = True
    def __init__(self, width=None, lineWidth=1, spaceBefore=0, spaceAfter=0):
        self.width = self._origWidth = width
        self.height = lineWidth
        self.lineWidth = lineWidth
        self.spaceBefore = spaceBefore
        self.spaceAfter = spaceAfter
    def __repr__(self):
        return "%s(%s, %s)" % (self.__class__.__name__, self.width, self.height)
    def wrap(self, availWidth, availHeight):
        if self._origWidth is None:
            self.width = availWidth
        return self.width, self.height
    def draw(self):
        from reportlab.lib.colors import black
        self.canv.saveState()
        self.canv.setStrokeColor(black)
        self.canv.setLineWidth(self.lineWidth)
        self.canv.line(0, 0, self.width, 0)
        self.canv.restoreState()

class ListStructuresAsyncPager:
    def __init__(self,
            method: Callable[..., Awaitable[smart_device_management_service.ListStructuresResponse]],
            request: smart_device_management_service.ListStructuresRequest,
            response: smart_device_management_service.ListStructuresResponse,
            *,
            metadata: Sequence[Tuple[str, str]] = ()):
        self._method = method
        self._request = smart_device_management_service.ListStructuresRequest(request)
        self._response = response
        self._metadata = metadata
    def __getattr__(self, name: str) -> Any:
        return getattr(self._response, name)
    @property
    async def pages(self) -> AsyncIterable[smart_device_management_service.ListStructuresResponse]:
        yield self._response
        while self._response.next_page_token:
            self._request.page_token = self._response.next_page_token
            self._response = await self._method(self._request, metadata=self._metadata)
            yield self._response
    def __aiter__(self) -> AsyncIterable[site.Structure]:
        async def async_generator():
            async for page in self.pages:
                for response in page.structures:
                    yield response
        return async_generator()
    def __repr__(self) -> str:
        return '{0}<{1!r}>'.format(self.__class__.__name__, self._response)

