class Device(ValuesMixin, GPIOBase):
    pin_factory = None 
    def __init__(self, **kwargs):
        pin_factory = kwargs.pop('pin_factory', None)
        if pin_factory is None:
            if Device.pin_factory is None:
                Device.pin_factory = Device._default_pin_factory()
            self.pin_factory = Device.pin_factory
        else:
            self.pin_factory = pin_factory
        if kwargs:
            raise TypeError("Device.__init__() got unexpected keyword "
                            "argument '%s'" % kwargs.popitem()[0])
        super(Device, self).__init__()
    @staticmethod
    def _default_pin_factory():
        default_factories = OrderedDict((
            ('rpigpio', 'gpiozero.pins.rpigpio:RPiGPIOFactory'),
            ('lgpio',   'gpiozero.pins.lgpio:LGPIOFactory'),
            ('rpio',    'gpiozero.pins.rpio:RPIOFactory'),
            ('pigpio',  'gpiozero.pins.pigpio:PiGPIOFactory'),
            ('native',  'gpiozero.pins.native:NativeFactory'),
        ))
        name = os.environ.get('GPIOZERO_PIN_FACTORY')
        if name is None:
            for name, entry_point in default_factories.items():
                try:
                    mod_name, cls_name = entry_point.split(':', 1)
                    module = __import__(mod_name, fromlist=(cls_name,))
                    pin_factory = getattr(module, cls_name)()
                    if name == 'native':
                        warnings.warn(NativePinFactoryFallback(native_fallback_message))
                    return pin_factory
                except Exception as e:
                    warnings.warn(
                        PinFactoryFallback(
                            'Falling back from %s: %s' % (name, str(e))))
            raise BadPinFactory('Unable to load any default pin factory!')
        elif name in default_factories:
            mod_name, cls_name = default_factories[name].split(':', 1)
            module = __import__(mod_name, fromlist=(cls_name,))
            return getattr(module, cls_name)()
        else:
            import pkg_resources
            group = 'gpiozero_pin_factories'
            for factory in pkg_resources.iter_entry_points(group, name):
                return factory.load()()
            for factory in pkg_resources.iter_entry_points(group, name.lower()):
                return factory.load()()
            raise BadPinFactory('Unable to find pin factory "%s"' % name)
    def __repr__(self):
        return "<gpiozero.%s object>" % (self.__class__.__name__)
    def _conflicts_with(self, other):
        return True
    @property
    def value(self):
        raise NotImplementedError
    @property
    def is_active(self):
        return bool(self.value)

class CompositeDevice(Device):
    def __init__(self, *args, **kwargs):
        self._all = ()
        self._named = frozendict({})
        self._namedtuple = None
        self._order = kwargs.pop('_order', None)
        pin_factory = kwargs.pop('pin_factory', None)
        try:
            if self._order is None:
                self._order = sorted(kwargs.keys())
            else:
                for missing_name in set(kwargs.keys()) - set(self._order):
                    raise CompositeDeviceBadOrder(
                        '%s missing from _order' % missing_name)
            self._order = tuple(self._order)
            for name in set(self._order) & set(dir(self)):
                raise CompositeDeviceBadName(
                    '%s is a reserved name' % name)
            for dev in chain(args, kwargs.values()):
                if not isinstance(dev, Device):
                    raise CompositeDeviceBadDevice(
                        "%s doesn't inherit from Device" % dev)
            self._named = frozendict(kwargs)
            self._namedtuple = namedtuple(
                '%sValue' % self.__class__.__name__, chain(
                    ('device_%d' % i for i in range(len(args))), self._order))
        except:
            for dev in chain(args, kwargs.values()):
                if isinstance(dev, Device):
                    dev.close()
            raise
        self._all = args + tuple(kwargs[v] for v in self._order)
        super(CompositeDevice, self).__init__(pin_factory=pin_factory)
    def __getattr__(self, name):
        if name == '_named':
            return frozendict({})
        try:
            return self._named[name]
        except KeyError:
            raise AttributeError("no such attribute %s" % name)
    def __setattr__(self, name, value):
        if name in self._named:
            raise AttributeError("can't set attribute %s" % name)
        return super(CompositeDevice, self).__setattr__(name, value)
    def __repr__(self):
        try:
            self._check_open()
            named = len(self._named)
            unnamed = len(self) - len(self._named)
            if named > 0 and unnamed > 0:
                return "<gpiozero.%s object containing %d devices: %s and %d unnamed>" % (
                        self.__class__.__name__,
                        len(self), ', '.join(self._order),
                        len(self) - len(self._named)
                        )
            elif named > 0:
                return "<gpiozero.%s object containing %d devices: %s>" % (
                        self.__class__.__name__,
                        len(self),
                        ', '.join(self._order)
                        )
            else:
                return "<gpiozero.%s object containing %d unnamed devices>" % (
                        self.__class__.__name__,
                        len(self)
                        )
        except DeviceClosed:
            return "<gpiozero.%s object closed>" % (self.__class__.__name__)
    def __len__(self):
        return len(self._all)
    def __getitem__(self, index):
        return self._all[index]
    def __iter__(self):
        return iter(self._all)
    @property
    def all(self):
        return self._all
    def close(self):
        if getattr(self, '_all', None):
            for device in self._all:
                if isinstance(device, Device):
                    device.close()
            self._all = ()
    @property
    def closed(self):
        return all(device.closed for device in self)
    @property
    def namedtuple(self):
        return self._namedtuple
    @property
    def value(self):
        return self.namedtuple(*(device.value for device in self))
    @property
    def is_active(self):
        return any(self.value)

class GPIODevice(Device):
    def __init__(self, pin=None, **kwargs):
        super(GPIODevice, self).__init__(**kwargs)
        self._pin = None
        if pin is None:
            raise GPIOPinMissing('No pin given')
        self.pin_factory.reserve_pins(self, pin)
        pin = self.pin_factory.pin(pin)
        self._pin = pin
        self._active_state = True
        self._inactive_state = False
    def _state_to_value(self, state):
        return int(state == self._active_state)
    def _read(self):
        try:
            return self._state_to_value(self.pin.state)
        except (AttributeError, TypeError):
            self._check_open()
            raise
    def close(self):
        super(GPIODevice, self).close()
        if getattr(self, '_pin', None) is not None:
            self.pin_factory.release_pins(self, self._pin.number)
            self._pin.close()
        self._pin = None
    @property
    def closed(self):
        return self._pin is None
    def _check_open(self):
        try:
            super(GPIODevice, self)._check_open()
        except DeviceClosed as e:
            raise GPIODeviceClosed(str(e))
    @property
    def pin(self):
        return self._pin
    @property
    def value(self):
        return self._read()
    def __repr__(self):
        try:
            return "<gpiozero.%s object on pin %r, is_active=%s>" % (
                self.__class__.__name__, self.pin, self.is_active)
        except DeviceClosed:
            return "<gpiozero.%s object closed>" % self.__class__.__name__

class QuestStatData:
    EnemyDefeatTime = 0.0083333299999999999
    ShipDefeatTime = 0.050000000000000003
    VoyageTime = 0.11666666000000001
    PokerGoldTime = 0.02
    GoldTime = 0.02
    TreasureTime = 0.01666666
    VisitTime = 0.01666666
    Tasks = { }
    Enemies = { }
    Misc = { }
    def incrementTasks(self, name, count = 1):
        if not self.Tasks.has_key(name):
            self.Tasks[name] = count
        else:
            self.Tasks[name] = self.Tasks[name] + count
    def incrementEnemies(self, name, count = 1):
        if not self.Enemies.has_key(name):
            self.Enemies[name] = count
        else:
            self.Enemies[name] = self.Enemies[name] + count
    def incrementMisc(self, name, count = 1):
        if not self.Misc.has_key(name):
            self.Misc[name] = count
        else:
            self.Misc[name] = self.Misc[name] + count
    def computeTime(self):
        self.totalEnemyTime = self.Misc.get('totalEnemies') * self.EnemyDefeatTime
        self.totalShipTime = self.Misc.get('totalShips') * self.ShipDefeatTime
        self.totalQuestFightTime = self.totalEnemyTime + self.totalShipTime
        self.totalVoyageTime = self.Misc.get('voyages') * self.VoyageTime
        self.pokerGoldTime = self.Misc.get('poker-gold') * self.PokerGoldTime
        self.goldTime = self.Misc.get('gold') * self.GoldTime - self.pokerGoldTime
        self.treasureTime = self.Misc.get('treasures') * self.TreasureTime
        self.visitTime = self.Misc.get('visits') * self.VisitTime
        self.totalTime = self.totalQuestFightTime + self.totalVoyageTime + self.goldTime + self.TreasureTime + self.visitTime
    def __repr__(self):
        self.computeTime()
        argStr = ''
        for (name, value) in self.Tasks.items():
            argStr += '%s=%s,' % (name, repr(self.Tasks[name]))
        for (name, value) in self.Enemies.items():
            argStr += '%s=%s,' % (name, repr(self.Enemies[name]))
        for (name, value) in self.Misc.items():
            argStr += '%s=%s,' % (name, repr(self.Misc[name]))
        argStr += 'totalEnemyFightTime=%s,' % self.totalEnemyTime
        argStr += 'totalShipFightTime=%s,' % self.totalShipTime
        argStr += 'totalQuestFightTime=%s,' % self.totalQuestFightTime
        argStr += 'totalVoyageTime=%s,' % self.totalVoyageTime
        argStr += 'pokerTime=%s,' % self.pokerGoldTime
        argStr += 'goldTime=%s,' % self.goldTime
        argStr += 'treasureTime=%s,' % self.treasureTime
        argStr += 'visitTime=%s,' % self.visitTime
        argStr += 'totalTime=%s,' % self.totalTime
        return '%s(%s)' % (self.__class__.__name__, argStr)

class CompletionState:
    def __init__(
        self,
        original_document: "Document",
        completions: Optional[List["Completion"]] = None,
        complete_index: Optional[int] = None,
    ):
        self.original_document = original_document
        self.completions = completions or []
        self.complete_index = complete_index  
    def __repr__(self) -> str:
        return "%s(%r, <%r> completions, index=%r)" % (
            self.__class__.__name__,
            self.original_document,
            len(self.completions),
            self.complete_index,
        )
    def go_to_index(self, index: Optional[int]) -> None:
        if self.completions:
            assert index is None or 0 <= index < len(self.completions)
            self.complete_index = index
    def new_text_and_position(self) -> Tuple[str, int]:
        if self.complete_index is None:
            return self.original_document.text, self.original_document.cursor_position
        else:
            original_text_before_cursor = self.original_document.text_before_cursor
            original_text_after_cursor = self.original_document.text_after_cursor
            c = self.completions[self.complete_index]
            if c.start_position == 0:
                before = original_text_before_cursor
            else:
                before = original_text_before_cursor[: c.start_position]
            new_text = before + c.text + original_text_after_cursor
            new_cursor_position = len(before) + len(c.text)
            return new_text, new_cursor_position
    @property
    def current_completion(self) -> Optional["Completion"]:
        if self.complete_index is not None:
            return self.completions[self.complete_index]
        return None

