class LinkedList:
    def __init__(self):
        self.head = None  
    def insert_tail(self, data) -> None:
        if self.head is None:
            self.insert_head(data)  
        else:
            temp = self.head
            while temp.next:  
                temp = temp.next
            temp.next = Node(data)  
    def insert_head(self, data) -> None:
        new_node = Node(data)  
        if self.head:
            new_node.next = self.head  
        self.head = new_node  
    def print_list(self) -> None:  
        temp = self.head
        while temp:
            print(temp.data)
            temp = temp.next
    def delete_head(self):  
        temp = self.head
        if self.head:
            self.head = self.head.next
            temp.next = None
        return temp
    def delete_tail(self):  
        temp = self.head
        if self.head:
            if self.head.next is None:  
                self.head = None
            else:
                while temp.next.next:  
                    temp = temp.next
                temp.next, temp = None, temp.next
        return temp
    def is_empty(self) -> bool:
        return self.head is None  
    def reverse(self):
        prev = None
        current = self.head
        while current:
            next_node = current.next
            current.next = prev
            prev = current
            current = next_node
        self.head = prev
    def __repr__(self):  
        current = self.head
        string_repr = ""
        while current:
            string_repr += f"{current} --> "
            current = current.next
        return string_repr + "END"
    def __getitem__(self, index):
        current = self.head
        if current is None:
            raise IndexError("The Linked List is empty")
        for _ in range(index):
            if current.next is None:
                raise IndexError("Index out of range.")
            current = current.next
        return current
    def __setitem__(self, index, data):
        current = self.head
        if current is None:
            raise IndexError("The Linked List is empty")
        for i in range(index):
            if current.next is None:
                raise IndexError("Index out of range.")
            current = current.next
        current.data = data
    def __len__(self):
        if not self.head:
            return 0
        count = 0
        cur_node = self.head
        while cur_node.next:
            count += 1
            cur_node = cur_node.next
        return count + 1

class SnapshotPlanStatus(object):
    NORMAL = "NORMAL"
    STOPPED = "STOPPED"
    SUSPENDED = "SUSPENDED"
    allowable_values = [NORMAL, STOPPED, SUSPENDED]  
    openapi_types = {
    }
    attribute_map = {
    }
    def __init__(self, **kwargs):  
        self.local_vars_configuration = kwargs.get("local_vars_configuration", Configuration.get_default_copy())
        self.discriminator = None
    def to_dict(self, serialize=False):
        result = {}
        def convert(x):
            if hasattr(x, "to_dict"):
                args = getfullargspec(x.to_dict).args
                if len(args) == 1:
                    return x.to_dict()
                else:
                    return x.to_dict(serialize)
            else:
                return x
        for attr, _ in six.iteritems(self.openapi_types):
            value = getattr(self, attr)
            attr = self.attribute_map.get(attr, attr) if serialize else attr
            if isinstance(value, list):
                result[attr] = list(map(
                    lambda x: convert(x),
                    value
                ))
            elif isinstance(value, dict):
                result[attr] = dict(map(
                    lambda item: (item[0], convert(item[1])),
                    value.items()
                ))
            else:
                result[attr] = convert(value)
        return result
    def to_str(self):
        return pprint.pformat(self.to_dict())
    def __repr__(self):
        return self.to_str()
    def __eq__(self, other):
        if not isinstance(other, SnapshotPlanStatus):
            return False
        return self.to_dict() == other.to_dict()
    def __ne__(self, other):
        if not isinstance(other, SnapshotPlanStatus):
            return True
        return self.to_dict() != other.to_dict()

class WsgiResponse:
    _iterated = False
    _started = False
    DEFAULT_STATUS_CODE = 200
    def __init__(self, status=None, content=None, response_headers=None,
                 content_type=None, encoding=None, environ=None,
                 can_store_cookies=True):
        self.environ = environ
        self.status_code = status or self.DEFAULT_STATUS_CODE
        self.encoding = encoding
        self.cookies = SimpleCookie()
        self.headers = Headers(response_headers or ())
        self.content = content
        self._can_store_cookies = can_store_cookies
        if content_type is not None:
            self.content_type = content_type
    @property
    def started(self):
        return self._started
    @property
    def iterated(self):
        return self._iterated
    @property
    def path(self):
        if self.environ:
            return self.environ.get('PATH_INFO', '')
    @property
    def method(self):
        if self.environ:
            return self.environ.get('REQUEST_METHOD')
    @property
    def connection(self):
        if self.environ:
            return self.environ.get('pulsar.connection')
    @property
    def content(self):
        return self._content
    @content.setter
    def content(self, content):
        if not self._iterated:
            if content is None:
                content = ()
            else:
                if isinstance(content, str):
                    if not self.encoding:   
                        self.encoding = 'utf-8'
                    content = content.encode(self.encoding)
            if isinstance(content, bytes):
                content = (content,)
            self._content = content
        else:
            raise RuntimeError('Cannot set content. Already iterated')
    def _get_content_type(self):
        return self.headers.get('content-type')
    def _set_content_type(self, typ):
        if typ:
            self.headers['content-type'] = typ
        else:
            self.headers.pop('content-type', None)
    content_type = property(_get_content_type, _set_content_type)
    @property
    def response(self):
        return responses.get(self.status_code)
    @property
    def status(self):
        return '%s %s' % (self.status_code, self.response)
    def __str__(self):
        return self.status
    def __repr__(self):
        return '%s(%s)' % (self.__class__.__name__, self)
    @property
    def is_streamed(self):
        try:
            len(self.content)
        except TypeError:
            return True
        return False
    def can_set_cookies(self):
        if self.status_code < 400:
            return self._can_store_cookies
    def length(self):
        if not self.is_streamed:
            return reduce(lambda x, y: x+len(y), self.content, 0)
    def start(self, start_response):
        assert not self._started
        self._started = True
        return start_response(self.status, self.get_headers())
    def __iter__(self):
        if self._iterated:
            raise RuntimeError('WsgiResponse can be iterated once only')
        self._started = True
        self._iterated = True
        if self.is_streamed:
            return wsgi_encoder(self.content, self.encoding or 'utf-8')
        else:
            return iter(self.content)
    def close(self):
        if self.is_streamed:
            if hasattr(self.content, 'close'):
                self.content.close()
    def set_cookie(self, key, **kwargs):
        set_cookie(self.cookies, key, **kwargs)
    def delete_cookie(self, key, path='/', domain=None):
        set_cookie(self.cookies, key, max_age=0, path=path, domain=domain,
                   expires='Thu, 01-Jan-1970 00:00:00 GMT')
    def get_headers(self):
        headers = self.headers
        if has_empty_content(self.status_code):
            headers.pop('content-type', None)
            headers.pop('content-length', None)
            self._content = ()
        else:
            if not self.is_streamed:
                cl = 0
                for c in self.content:
                    cl += len(c)
                if cl == 0 and self.content_type in JSON_CONTENT_TYPES:
                    self._content = (b'{}',)
                    cl = len(self._content[0])
                headers['Content-Length'] = str(cl)
            ct = self.content_type
            if self.encoding:
                ct = ct or 'text/plain'
                if 'charset=' not in ct:
                    ct = '%s; charset=%s' % (ct, self.encoding)
            if ct:
                headers['Content-Type'] = ct
            if self.method == HEAD:
                self._content = ()
        if self.can_set_cookies():
            for c in self.cookies.values():
                headers.add_header('Set-Cookie', c.OutputString())
        return list(headers)
    def has_header(self, header):
        return header in self.headers
    __contains__ = has_header
    def __setitem__(self, header, value):
        self.headers[header] = value
    def __getitem__(self, header):
        return self.headers[header]

class WsgiRequest(EnvironMixin):
    def __init__(self, environ, app_handler=None, urlargs=None):
        super().__init__(environ)
        self.cache.cfg = environ.get('pulsar.cfg', {})
        if app_handler:
            self.cache.app_handler = app_handler
            self.cache.urlargs = urlargs
    def __repr__(self):
        return self.path
    def __str__(self):
        return self.__repr__()
    @cached_property
    def first_line(self):
        env = self.environ
        try:
            return '%s %s' % (env['REQUEST_METHOD'], self.absolute_uri())
        except Exception:
            return '%s %s' % (env.get('REQUEST_METHOD'), env.get('PATH'))
    @cached_property
    def content_types(self):
        return parse_accept_header(self.environ.get('HTTP_ACCEPT'),
                                   ContentAccept)
    @cached_property
    def charsets(self):
        return parse_accept_header(self.environ.get('HTTP_ACCEPT_CHARSET'),
                                   CharsetAccept)
    @cached_property
    def encodings(self):
        return parse_accept_header(self.environ.get('HTTP_ACCEPT_ENCODING'))
    @cached_property
    def languages(self):
        return parse_accept_header(self.environ.get('HTTP_ACCEPT_LANGUAGE'),
                                   LanguageAccept)
    @cached_property
    def cookies(self):
        cookies = SimpleCookie()
        cookie = self.environ.get('HTTP_COOKIE')
        if cookie:
            cookies.load(cookie)
        return cookies
    @property
    def app_handler(self):
        return self.cache.app_handler
    @property
    def urlargs(self):
        args = self.cache.urlargs
        return args if args is not None else {}
    @property
    def cfg(self):
        return self.cache.cfg
    @property
    def logger(self):
        return self.cache.logger
    @cached_property
    def response(self):
        return WsgiResponse(environ=self.environ)
    @property
    def is_xhr(self):
        return self.environ.get('HTTP_X_REQUESTED_WITH') == 'XMLHttpRequest'
    @property
    def is_secure(self):
        return self.environ.get('HTTPS') == 'on'
    @property
    def path(self):
        return self.environ.get('PATH_INFO', '/')
    @property
    def uri(self):
        return self.absolute_uri()
    @property
    def method(self):
        return self.environ['REQUEST_METHOD']
    @cached_property
    def encoding(self):
        return self.content_type_options[1].get('charset', 'utf-8')
    @cached_property
    def content_type_options(self):
        content_type = self.environ.get('CONTENT_TYPE')
        if content_type:
            return parse_options_header(content_type)
        else:
            return None, {}
    def data_and_files(self, data=True, files=True, stream=None):
        if self.method in ENCODE_URL_METHODS:
            value = {}, None
        else:
            value = self.cache.data_and_files
        if not value:
            return self._data_and_files(data, files, stream)
        elif data and files:
            return value
        elif data:
            return value[0]
        elif files:
            return value[1]
        else:
            return None
    def body_data(self):
        return self.data_and_files(files=False)
    def _data_and_files(self, data=True, files=True, stream=None, future=None):
        if future is None:
            data_files = parse_form_data(self.environ, stream=stream)
            if isawaitable(data_files):
                return chain_future(
                    data_files,
                    partial(self._data_and_files, data, files, stream))
        else:
            data_files = future
        self.cache.data_and_files = data_files
        return self.data_and_files(data, files, stream)
    @cached_property
    def url_data(self):
        return query_dict(self.environ.get('QUERY_STRING', ''),
                          encoding=self.encoding)
    @cached_property
    def html_document(self):
        return HtmlDocument()
    def get_host(self, use_x_forwarded=True):
        if use_x_forwarded and ('HTTP_X_FORWARDED_HOST' in self.environ):
            host = self.environ['HTTP_X_FORWARDED_HOST']
        elif 'HTTP_HOST' in self.environ:
            host = self.environ['HTTP_HOST']
        else:
            host = self.environ['SERVER_NAME']
            server_port = str(self.environ['SERVER_PORT'])
            if server_port != ('443' if self.is_secure else '80'):
                host = '%s:%s' % (host, server_port)
        return host
    def get_client_address(self, use_x_forwarded=True):
        xfor = self.environ.get('HTTP_X_FORWARDED_FOR')
        if use_x_forwarded and xfor:
            return xfor.split(',')[-1].strip()
        else:
            return self.environ['REMOTE_ADDR']
    def full_path(self, *args, **query):
        path = None
        if args:
            if len(args) > 1:
                raise TypeError("full_url() takes exactly 1 argument "
                                "(%s given)" % len(args))
            path = args[0]
        if not path:
            path = self.path
        elif not path.startswith('/'):
            path = remove_double_slash('%s/%s' % (self.path, path))
        return iri_to_uri(path, query)
    def absolute_uri(self, location=None, scheme=None, **query):
        if not is_absolute_uri(location):
            if location or location is None:
                location = self.full_path(location, **query)
            if not scheme:
                scheme = self.is_secure and 'https' or 'http'
            base = '%s://%s' % (scheme, self.get_host())
            return '%s%s' % (base, location)
        elif not scheme:
            return iri_to_uri(location)
        else:
            raise ValueError('Absolute location with scheme not valid')
    def redirect(self, path, **kw):
        return redirect(path, **kw)
    def set_response_content_type(self, response_content_types=None):
        request_content_types = self.content_types
        if request_content_types:
            ct = request_content_types.best_match(response_content_types)
            if ct and '*' in ct:
                ct = None
            if not ct and response_content_types:
                raise HttpException(status=415, msg=request_content_types)
            self.response.content_type = ct

class DBColDef(object):
	def __init__(self, fieldName, fieldType, bIsNullable, indexType):
		assert isinstance(fieldName, str)
		assert isinstance(fieldType, EnumDBColType)
		assert isinstance(bIsNullable, bool)
		assert isinstance(indexType, EnumDBIndexType)
		if fieldType == EnumDBColType.PK:
			bIsNullable = False
			indexType = EnumDBIndexType.NONE
		self.__name = fieldName
		self.__type = fieldType
		self.__bIsNullable = bIsNullable
		self.__indexType = indexType
	@property
	def index(self):
		return self.__indexType
	@property
	def nullable(self):
		return self.__bIsNullable
	@property
	def unique(self):
		return self.__indexType == EnumDBIndexType.UNIQUE_INDEX
	@property
	def type(self):
		return self.__type
	@property
	def name(self):
		return self.__name
	def isEqualWithoutIndex(self, other):
		return (self.__name == other.name) and (self.__type == other.type) and (self.__bIsNullable == other.nullable)
	def __ne__(self, other):
		return (self.__name != other.name) or (self.__type != other.type) or (self.__bIsNullable != other.nullable) or (self.__indexType != other.index)
	def __eq__(self, other):
		return (self.__name == other.name) and (self.__type == other.type) and (self.__bIsNullable == other.nullable) and (self.__indexType == other.index)
	def __str__(self):
		return self.__type + ": " + self.__name
	def __repr__(self):
		return self.__type + ": " + self.__name
	def __copy__(self):
		return DBColDef(self.__name, self.__type, self.__bIsNullable, self.__indexType)
	def __deepcopy__(self, memo):
		return DBColDef(self.__name, self.__type, self.__bIsNullable, self.__indexType)
	@staticmethod
	def loadFromJSON(jsonDef):
		t = jsonDef["type"]
		i = jsonDef["index"]
		return DBColDef(jsonDef["name"], EnumDBColType.parse(t), jsonDef["nullable"], EnumDBIndexType.parse(i))
	def toJSON(self):
		return {
			"name" : self.__name,
			"type" : str(self.__type),
			"nullable" : self.__bIsNullable,
			"index" : str(self.__indexType)
		}

