class LinkedList:
    def __init__(self):
        self.first = None
        self.last = None
        self.current_size = 0
    def size(self):
        return self.current_size
    def add(self, data):
        new_node = ListNode(data)
        if self.size() == 0:
            self.first = new_node
            self.last = new_node
        elif self.size() == 1:
            self.last = new_node
            new_node.prev = self.first
            self.first.next = new_node
        else:
            self.last.next = new_node
            new_node.prev = self.last
            self.last = new_node
        self.current_size += 1
    def __getitem__(self, target_index):
        curr_index = 0
        curr_node = self.first
        while curr_node != None and curr_index < target_index:
            curr_node = curr_node.next
            curr_index += 1
        if curr_node != None:
            return curr_node.data
        else:
            print("ERROR: ILLEGAL INDEX")
            indexErr = "Index %d out of bounds for list size: %d" % (target_index, self.size())
            raise IndexError(indexErr)
    def delete(self, target_index):
        if target_index == 0 and self.size() > 1:
            self.first.next.prev = None
            self.first = self.first.next
        elif target_index == 0 and self.size() == 1:
            self.first = None
            self.last = None
        elif target_index == self.size() - 1 and self.size() > 1:
            self.last.prev.next = None
            self.last = self.last.prev
        else:
            curr_index = 0
            curr_node = self.first
            while curr_node != None and curr_index < target_index:
                curr_node = curr_node.next
                curr_index += 1
            if curr_node != None:
                curr_node.prev.next = curr_node.next
                curr_node.next.prev = curr_node.prev
            else:
                raise IndexError("Index %d out of bounds for list size: %d" % (target_index, self.size()))
        self.current_size -= 1
    def __repr__(self):
        result = ""
        curr_node = self.first
        while curr_node != None:
            result += str(curr_node) + ", "
            curr_node = curr_node.next
        return result

class ScopeLabel(object):
    def __init__(self, scopename, scopetype='any', scopeloop=None):
        self.scopename = scopename
        if scopetype not in scopetype_list:
            raise DefinitionError('No such Scope type')
        self.scopetype = scopetype
        self.scopeloop = scopeloop
    def __repr__(self):
        ret = []
        ret.append(self.scopename)
        if self.scopeloop is not None:
            ret.append('[')
            ret.append(str(self.scopeloop))
            ret.append(']')
        return ''.join(ret)
    def tocode(self):
        if self.scopetype in scopetype_list_unprint: return ''
        return self.scopename
    def __eq__(self, other):
        if type(self) != type(other): return False
        if self.scopetype == 'any' or other.scopetype == 'any':
            return ((self.scopename, self.scopeloop) ==
                    (other.scopename, other.scopeloop))
        return (self.scopename, self.scopetype, self.scopeloop) == (other.scopename, other.scopetype, other.scopeloop)
    def __ne__(self, other):
        return not self.__eq__(other)
    def __hash__(self):
        return hash((self.scopename, self.scopeloop)) 
    def isPrintable(self):
        return self.scopetype in (scopetype_list_print + ('any',))

class ScopeChain(object):
    def __init__(self, scopechain=None):
        self.scopechain = []
        if scopechain is not None:
            self.scopechain = scopechain
    def __add__(self, r):
        new_chain = copy.deepcopy(self)
        if isinstance(r, ScopeLabel):
            new_chain.append(r)
        elif isinstance(r, ScopeChain):
            new_chain.extend(r.scopechain)
        else:
            raise verror.DefinitionError('Can not add %s' % str(r))
        return new_chain
    def append(self, r):
        self.scopechain.append(r)
    def extend(self, r):
        self.scopechain.extend(r)
    def tocode(self):
        ret = []
        it = None
        for scope in self.scopechain:
            l = scope.tocode()
            if l:
                ret.append(l)
            if it is not None:
                ret.append(it)
            if l:
                ret.append('_')
            if scope.scopetype == 'for' and scope.scopeloop is not None:
                it = '_' + str(scope.scopeloop) + '_'
            else:
                it = None
        ret = ret[:-1]
        return ''.join(ret)
    def __repr__(self):
        ret = ''
        for scope in self.scopechain:
            l = scope.__repr__()
            ret += l + '.'
        ret = ret[:-1]
        return ret
    def __len__(self):
        return len(self.scopechain)
    def __eq__(self, other):
        if type(self) != type(other): return False
        return self.scopechain == other.scopechain
    def __ne__(self, other):
        return not self.__eq__(other)
    def __hash__(self):
        return hash(tuple(self.scopechain))
    def __getitem__(self, key):
        if isinstance(key, slice):
            indices = key.indices(len(self))
            return ScopeChain([self.scopechain[x] for x in range(*indices)])
        return self.scopechain[key]
    def __iter__(self):
        for scope in self.scopechain:
            yield scope

