class JsonObject(BaseObject, metaclass=ABCMeta):
    @property
    @abstractmethod
    def attributes(self) -> Set[str]:
        return set()
    def _extract_attribute(self, name: str, others: dict) -> Any:
        if name in others:
            value = others.pop(name)
            return value if value is not None and value != "" else None
        if 'property_list' in others:
            for property in others['property_list']:
                if (name == property['pid']):
                    return property['value']
        if 'data' in others and 'property_list' in others['data']:
            for property in others['data']['property_list']:
                if (name == property['pid']):
                    return property['value']
        if 'device_params' in others and name in others['device_params']:
            return self._extract_attribute(name, others['device_params'])
        if 'device_setting' in others and name in others['device_setting']:
            return self._extract_attribute(name, others['device_setting'])
    def validate_json(self) -> None:
        for attribute in (func for func in dir(self) if not func.startswith("__")):
            method = getattr(self, attribute, None)
            if callable(method) and hasattr(method, "validator"):
                method()
    def get_non_null_attributes(self) -> dict:
        def to_dict_compatible(
            value: Union[dict, list, object]
        ) -> Union[dict, list, Any]:
            if isinstance(value, list):  
                return [to_dict_compatible(v) for v in value]
            else:
                to_dict = getattr(value, "to_dict", None)
                if to_dict and callable(to_dict):  
                    return {
                        k: to_dict_compatible(v) for k, v in value.to_dict().items()  
                    }
                else:
                    return value
        def is_not_empty(self, key: str) -> bool:
            value = getattr(self, key, None)
            if value is None:
                return False
            has_len = getattr(value, "__len__", None) is not None
            if has_len:  
                return len(value) > 0
            else:
                return value is not None
        return {
            key: to_dict_compatible(getattr(self, key, None))
            for key in sorted(self.attributes)
            if is_not_empty(self, key)
        }
    def to_dict(self, *args) -> dict:
        self.validate_json()
        return self.get_non_null_attributes()
    def __repr__(self):
        dict_value = self.get_non_null_attributes()
        if dict_value:  
            return f"<wyze_sdk.{self.__class__.__name__}: {dict_value}>"
        else:
            return self.__str__()

class User(db.Model, SerializerMixin):
    __tablename__ = 'user'
    serialize_only = ('email', )
    id = db.Column(db.Integer, primary_key=True)
    email = db.Column(db.String(100), unique=True)  
    password = db.Column(db.String(80), nullable=False)
    salt = db.Column(db.String(12), nullable=False)  
    notebook = db.relationship('Notebook', lazy=True)  
    def __init__(self, email, password):
        super().__init__()
        self.email = email
        self.salt = self.generate_salt
        self.password = self.get_hash_sha256(password)
    def __repr__(self):
        return '<User %r>' % self.email
    def check_password(self, password: str) -> bool:
        if self.get_hash_sha256(password) == self.password:
            return True
        return False
    def get_hash_sha256(self, passwd: str) -> str:
        return hashlib.sha256((passwd + self.salt).encode('utf-8')).hexdigest()
    @property
    def generate_salt(self) -> str:
        return ''.join([random.choice(list('qwertyuiopasdfghjklzxcvbnm')) for i in range(12)])

