class DoublyLinkedList:
    def __init__(self) -> None:
        self.head = DoublyLinkedNode(-1, -1)
        self.tail = DoublyLinkedNode(-1, -1)
        self.head.next = self.tail
        self.tail.prev = self.head
        self.count = 0
    def __repr__(self) -> str:
        res = []
        first = self.head.next
        while first:
            res.append('({}, {})'.format(first.key, first.value))
            first = first.next
        return '->'.join(res[:-1])
    def append(self, node: DoublyLinkedNode) -> None:
        node.prev = self.head
        node.next = self.head.next
        self.head.next = node
        node.next.prev = node
        self.count += 1
    def remove(self, node: DoublyLinkedNode) -> DoublyLinkedNode:
        if self.count == 0:
            return None
        node.prev.next = node.next
        node.next.prev = node.prev
        self.count -= 1
        return node
    def pop(self) -> DoublyLinkedNode:
        last = self.tail.prev
        return self.remove(last)
    def isEmpty(self) -> int:
        if self.count == 0:
            return True
        return False

