class HashTable:
    def __init__(self, capacity):
        if capacity < MIN_CAPACITY:
            capacity = 8
        self.table = [None] * capacity
        self.capacity = capacity
        self.occupiedSlots = 0
    def __repr__(self):
        print()
        for l in self.table:
            if l:
                current = l
                str_ = ""
                while current:
                    print(f"({current.key}: {current.value}) -> ")
                    current = current.next
            else:
                print("(Empty)")
        return ""
    def get_num_slots(self):
        return self.capacity
    def get_load_factor(self):
        return self.occupiedSlots / self.get_num_slots()
    def fnv1(self, key):
        FNV_prime = 1099511628211
        offset_basis = 14695981039346656037
        hash = offset_basis
        for char in key:
            hash *= FNV_prime
            hash ^= ord(char)
        return hash
    def djb2(self, key):
        hash = 5381
        for char in key:
            hash = ((hash << 5) + hash) + ord(char)
        return hash & 0xFFFFFFFF
    def hash_index(self, key):
        return self.djb2(key) % self.capacity
    def put(self, key, value):
        hash_index = self.hash_index(key)
        entry = HashTableEntry(key, value)
        current = self.table[hash_index]
        if current:
            while current.next and current.key != key:
                current = current.next
            if current.key == key:
                current.value = value
            else:
                current.next = entry
                self.occupiedSlots += 1
        else:
            self.table[hash_index] = entry
            self.occupiedSlots += 1
        if self.get_load_factor() > 0.7:
            self.resize(self.capacity * 2)
    def delete(self, key):
        hash_index = self.hash_index(key)
        current = self.table[hash_index]
        if current:
            if current.key == key:
                self.table[hash_index] = current.next
                self.occupiedSlots -= 1
            else:
                prev = current
                current = current.next
                while current:
                    if current.key == key:
                        prev.next = current.next
                        self.occupiedSlots -= 1
                        break
                    prev = current
                    current = current.next
            if self.get_load_factor() < 0.2 and self.get_num_slots() > MIN_CAPACITY:
                self.resize(self.capacity // 2)
            if current:
                return current
        print("\n*** WARNING!!! SPECIFIED VALUE DOES NOT EXISTS ***\n")
    def get(self, key):
        hash_index = self.hash_index(key)
        if self.table[hash_index]:
            current = self.table[hash_index]
            while current:
                if current.key == key:
                    return current.value
                current = current.next
    def reset_attrs(self, new_capacity):
        self.capacity = new_capacity
        self.table = [None] * new_capacity
        self.occupiedSlots = 0
    def resize(self, new_capacity):
        prev_table = self.table
        self.reset_attrs(new_capacity)
        for l_list in prev_table:
            if l_list:
                while l_list:
                    self.put(l_list.key, l_list.value)
                    l_list = l_list.next

