        self.sucessores = []
        self.custo = custo
        self.distancia = distancia
        self.custo_total = self.custo + self.distancia
    def addSucessores(self, meta):
        for i,j in list(combinations([0,1,2,3,4], 2)):
            self.meta = meta
            novos_estados = list(self.estado)
            if novos_estados[i] < 42 and novos_estados[j] < 42:
                novos_estados[i] += 8
                novos_estados[j] += 8
                heuristica = Heuristica2_03(novos_estados, self.meta)
                self.sucessores.append(Nodo(estado = tuple(novos_estados), pai = Nodo(self.estado, self.pai, self.acao), acao = "Subir os elevadores {} e {}".format(i+1, j+1), custo = self.custo + 800, distancia = heuristica))
            novos_estados = list(self.estado)
            if novos_estados[i] > 12 and novos_estados[j] > 12:
                novos_estados[i] -= 13
                novos_estados[j] -= 13
                heuristica = Heuristica2_03(novos_estados, self.meta)
                self.sucessores.append(Nodo(estado = tuple(novos_estados), pai = Nodo(self.estado, self.pai, self.acao), acao = "Descer os elevadores {} e {}".format(i+1, j+1), custo = self.custo + 32.5, distancia = heuristica))
    def __eq__(self, other):
        return isinstance(other, Nodo) and self.estado == other.estado
    def __lt__(self, other):
        return self.custo_total < other.custo_total
    def __hash__(self):
        return hash(self.estado)

class Connection:
    __slots__ = (
        "pid",
        "host",
        "port",
        "db",
        "username",
        "client_name",
        "password",
        "socket_timeout",
        "socket_connect_timeout",
        "socket_keepalive",
        "socket_keepalive_options",
        "socket_type",
        "retry_on_timeout",
        "health_check_interval",
        "next_health_check",
        "last_active_at",
        "encoder",
        "ssl_context",
        "_reader",
        "_writer",
        "_parser",
        "_connect_callbacks",
        "_buffer_cutoff",
        "_lock",
        "__dict__",
    )
    def __init__(
        self,
        *,
        host: str = "localhost",
        port: Union[str, int] = 6379,
        db: Union[str, int] = 0,
        password: Optional[str] = None,
        socket_timeout: Optional[float] = None,
        socket_connect_timeout: Optional[float] = None,
        socket_keepalive: bool = False,
        socket_keepalive_options: Optional[Mapping[int, Union[int, bytes]]] = None,
        socket_type: int = 0,
        retry_on_timeout: bool = False,
        encoding: str = "utf-8",
        encoding_errors: str = "strict",
        decode_responses: bool = False,
        parser_class: Type[BaseParser] = DefaultParser,
        socket_read_size: int = 65536,
        health_check_interval: float = 0,
        client_name: Optional[str] = None,
        username: Optional[str] = None,
        encoder_class: Type[Encoder] = Encoder,
    ):
        self.pid = os.getpid()
        self.host = host
        self.port = int(port)
        self.db = db
        self.username = username
        self.client_name = client_name
        self.password = password
        self.socket_timeout = socket_timeout
        self.socket_connect_timeout = socket_connect_timeout or socket_timeout or None
        self.socket_keepalive = socket_keepalive
        self.socket_keepalive_options = socket_keepalive_options or {}
        self.socket_type = socket_type
        self.retry_on_timeout = retry_on_timeout
        self.health_check_interval = health_check_interval
        self.next_health_check: float = -1
        self.ssl_context: Optional[RedisSSLContext] = None
        self.encoder = encoder_class(encoding, encoding_errors, decode_responses)
        self._reader: Optional[asyncio.StreamReader] = None
        self._writer: Optional[asyncio.StreamWriter] = None
        self._parser = parser_class(
            socket_read_size=socket_read_size,
        )
        self._connect_callbacks: List[ConnectCallbackT] = []
        self._buffer_cutoff = 6000
        self._lock = asyncio.Lock()
    def __repr__(self):
        repr_args = ",".join((f"{k}={v}" for k, v in self.repr_pieces()))
        return f"{self.__class__.__name__}<{repr_args}>"
    def repr_pieces(self):
        pieces = [("host", self.host), ("port", self.port), ("db", self.db)]
        if self.client_name:
            pieces.append(("client_name", self.client_name))
        return pieces
    def __del__(self):
        try:
            if self.is_connected:
                loop = asyncio.get_event_loop()
                coro = self.disconnect()
                if loop.is_running():
                    loop.create_task(coro)
                else:
                    loop.run_until_complete(coro)
        except Exception:
            pass
    @property
    def is_connected(self):
        return bool(self._reader and self._writer)
    def register_connect_callback(self, callback):
        self._connect_callbacks.append(callback)
    def clear_connect_callbacks(self):
        self._connect_callbacks = []
    async def connect(self):
        if self.is_connected:
            return
        try:
            await self._connect()
        except asyncio.CancelledError:
            raise
        except (socket.timeout, asyncio.TimeoutError):
            raise TimeoutError("Timeout connecting to server")
        except OSError as e:
            raise ConnectionError(self._error_message(e))
        except Exception as exc:
            raise ConnectionError(exc) from exc
        try:
            await self.on_connect()
        except RedisError:
            await self.disconnect()
            raise
        for callback in self._connect_callbacks:
            task = callback(self)
            if task and inspect.isawaitable(task):
                await task
    async def _connect(self):
        async with async_timeout.timeout(self.socket_connect_timeout):
            reader, writer = await asyncio.open_connection(
                host=self.host,
                port=self.port,
                ssl=self.ssl_context.get() if self.ssl_context else None,
            )
        self._reader = reader
        self._writer = writer
        sock = writer.transport.get_extra_info("socket")
        if sock is not None:
            sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
            try:
                if self.socket_keepalive:
                    sock.setsockopt(socket.SOL_SOCKET, socket.SO_KEEPALIVE, 1)
                    for k, v in self.socket_keepalive_options.items():
                        sock.setsockopt(socket.SOL_TCP, k, v)
            except (OSError, TypeError):
                writer.close()
                raise
    def _error_message(self, exception):
        if len(exception.args) == 1:
            return f"Error connecting to {self.host}:{self.port}. {exception.args[0]}."
        else:
            return (
                f"Error {exception.args[0]} connecting to {self.host}:{self.port}. "
                f"{exception.args[0]}."
            )
    async def on_connect(self):
        self._parser.on_connect(self)
        if self.username or self.password:
            auth_args: Union[Tuple[str], Tuple[str, str]]
            if self.username:
                auth_args = (self.username, self.password or "")
            else:
                auth_args = (self.password or "",)
            await self.send_command("AUTH", *auth_args, check_health=False)
            try:
                auth_response = await self.read_response()
            except AuthenticationWrongNumberOfArgsError:
                await self.send_command("AUTH", self.password, check_health=False)
                auth_response = await self.read_response()
            if str_if_bytes(auth_response) != "OK":
                raise AuthenticationError("Invalid Username or Password")
        if self.client_name:
            await self.send_command("CLIENT", "SETNAME", self.client_name)
            if str_if_bytes(await self.read_response()) != "OK":
                raise ConnectionError("Error setting client name")
        if self.db:
            await self.send_command("SELECT", self.db)
            if str_if_bytes(await self.read_response()) != "OK":
                raise ConnectionError("Invalid Database")
    async def disconnect(self):
        try:
            async with async_timeout.timeout(self.socket_connect_timeout):
                self._parser.on_disconnect()
                if not self.is_connected:
                    return
                try:
                    if os.getpid() == self.pid:
                        self._writer.close()  
                        if hasattr(self._writer, "wait_closed"):
                            await self._writer.wait_closed()  
                except OSError:
                    pass
                self._reader = None
                self._writer = None
        except asyncio.TimeoutError:
            raise TimeoutError(
                f"Timed out closing connection after {self.socket_connect_timeout}"
            ) from None
    async def check_health(self):
        if (
            self.health_check_interval
            and asyncio.get_event_loop().time() > self.next_health_check
        ):
            try:
                await self.send_command("PING", check_health=False)
                if str_if_bytes(await self.read_response()) != "PONG":
                    raise ConnectionError("Bad response from PING health check")
            except (ConnectionError, TimeoutError) as err:
                await self.disconnect()
                try:
                    await self.send_command("PING", check_health=False)
                    if str_if_bytes(await self.read_response()) != "PONG":
                        raise ConnectionError(
                            "Bad response from PING health check"
                        ) from None
                except BaseException as err2:
                    raise err2 from err
    async def _send_packed_command(self, command: Iterable[bytes]) -> None:
        if self._writer is None:
            raise RedisError("Connection already closed.")
        self._writer.writelines(command)
        await self._writer.drain()
    async def send_packed_command(
        self,
        command: Union[bytes, str, Iterable[bytes]],
        check_health: bool = True,
    ):
        if not self._writer:
            await self.connect()
        if check_health:
            await self.check_health()
        try:
            if isinstance(command, str):
                command = command.encode()
            if isinstance(command, bytes):
                command = [command]
            await asyncio.wait_for(
                self._send_packed_command(command),
                self.socket_timeout,
            )
        except asyncio.TimeoutError:
            await self.disconnect()
            raise TimeoutError("Timeout writing to socket") from None
        except OSError as e:
            await self.disconnect()
            if len(e.args) == 1:
                err_no, errmsg = "UNKNOWN", e.args[0]
            else:
                err_no = e.args[0]
                errmsg = e.args[1]
            raise ConnectionError(
                f"Error {err_no} while writing to socket. {errmsg}."
            ) from e
        except BaseException:
            await self.disconnect()
            raise
    async def send_command(self, *args, **kwargs):
        if not self.is_connected:
            await self.connect()
        await self.send_packed_command(
            self.pack_command(*args), check_health=kwargs.get("check_health", True)
        )
    async def can_read(self, timeout: float = 0):
        if not self.is_connected:
            await self.connect()
        return await self._parser.can_read(timeout)
    async def read_response(self):
        try:
            async with self._lock:
                async with async_timeout.timeout(self.socket_timeout):
                    response = await self._parser.read_response()
        except asyncio.TimeoutError:
            await self.disconnect()
            raise TimeoutError(f"Timeout reading from {self.host}:{self.port}")
        except OSError as e:
            await self.disconnect()
            raise ConnectionError(
                f"Error while reading from {self.host}:{self.port} : {e.args}"
            )
        except BaseException:
            await self.disconnect()
            raise
        if self.health_check_interval:
            self.next_health_check = (
                asyncio.get_event_loop().time() + self.health_check_interval
            )
        if isinstance(response, ResponseError):
            raise response from None
        return response
    def pack_command(self, *args: EncodableT) -> List[bytes]:
        output = []
        assert not isinstance(args[0], float)
        if isinstance(args[0], str):
            args = tuple(args[0].encode().split()) + args[1:]
        elif b" " in args[0]:
            args = tuple(args[0].split()) + args[1:]
        buff = SYM_EMPTY.join((SYM_STAR, str(len(args)).encode(), SYM_CRLF))
        buffer_cutoff = self._buffer_cutoff
        for arg in map(self.encoder.encode, args):
            arg_length = len(arg)
            if (
                len(buff) > buffer_cutoff
                or arg_length > buffer_cutoff
                or isinstance(arg, memoryview)
            ):
                buff = SYM_EMPTY.join(
                    (buff, SYM_DOLLAR, str(arg_length).encode(), SYM_CRLF)
                )
                output.append(buff)
                output.append(arg)
                buff = SYM_CRLF
            else:
                buff = SYM_EMPTY.join(
                    (
                        buff,
                        SYM_DOLLAR,
                        str(arg_length).encode(),
                        SYM_CRLF,
                        arg,
                        SYM_CRLF,
                    )
                )
        output.append(buff)
        return output
    def pack_commands(self, commands: Iterable[Iterable[EncodableT]]) -> List[bytes]:
        output: List[bytes] = []
        pieces: List[bytes] = []
        buffer_length = 0
        buffer_cutoff = self._buffer_cutoff
        for cmd in commands:
            for chunk in self.pack_command(*cmd):
                chunklen = len(chunk)
                if (
                    buffer_length > buffer_cutoff
                    or chunklen > buffer_cutoff
                    or isinstance(chunk, memoryview)
                ):
                    output.append(SYM_EMPTY.join(pieces))
                    buffer_length = 0
                    pieces = []
                if chunklen > buffer_cutoff or isinstance(chunk, memoryview):
                    output.append(chunk)
                else:
                    pieces.append(chunk)
                    buffer_length += chunklen
        if pieces:
            output.append(SYM_EMPTY.join(pieces))
        return output

class ConnectionPool:
    @classmethod
    def from_url(cls: Type[_CP], url: str, **kwargs) -> _CP:
        url_options = parse_url(url)
        kwargs.update(url_options)
        return cls(**kwargs)
    def __init__(
        self,
        connection_class: Type[Connection] = Connection,
        max_connections: Optional[int] = None,
        **connection_kwargs,
    ):
        max_connections = max_connections or 2**31
        if not isinstance(max_connections, int) or max_connections < 0:
            raise ValueError('"max_connections" must be a positive integer')
        self.connection_class = connection_class
        self.connection_kwargs = connection_kwargs
        self.max_connections = max_connections
        self._fork_lock = threading.Lock()
        self._lock = asyncio.Lock()
        self._created_connections: int
        self._available_connections: List[Connection]
        self._in_use_connections: Set[Connection]
        self.reset()  
        self.encoder_class = self.connection_kwargs.get("encoder_class", Encoder)
    def __repr__(self):
        return (
            f"{self.__class__.__name__}"
            f"<{self.connection_class(**self.connection_kwargs)!r}>"
        )
    def reset(self):
        self._lock = asyncio.Lock()
        self._created_connections = 0
        self._available_connections = []
        self._in_use_connections = set()
        self.pid = os.getpid()
    def _checkpid(self):
        if self.pid != os.getpid():
            acquired = self._fork_lock.acquire(timeout=5)
            if not acquired:
                raise ChildDeadlockedError
            try:
                if self.pid != os.getpid():
                    self.reset()
            finally:
                self._fork_lock.release()
    async def get_connection(self, command_name, *keys, **options):
        self._checkpid()
        async with self._lock:
            try:
                connection = self._available_connections.pop()
            except IndexError:
                connection = self.make_connection()
            self._in_use_connections.add(connection)
        try:
            await connection.connect()
            try:
                if await connection.can_read():
                    raise ConnectionError("Connection has data") from None
            except ConnectionError:
                await connection.disconnect()
                await connection.connect()
                if await connection.can_read():
                    raise ConnectionError("Connection not ready") from None
        except BaseException:
            await self.release(connection)
            raise
        return connection
    def get_encoder(self):
        kwargs = self.connection_kwargs
        return self.encoder_class(
            encoding=kwargs.get("encoding", "utf-8"),
            encoding_errors=kwargs.get("encoding_errors", "strict"),
            decode_responses=kwargs.get("decode_responses", False),
        )
    def make_connection(self):
        if self._created_connections >= self.max_connections:
            raise ConnectionError("Too many connections")
        self._created_connections += 1
        return self.connection_class(**self.connection_kwargs)
    async def release(self, connection: Connection):
        self._checkpid()
        async with self._lock:
            try:
                self._in_use_connections.remove(connection)
            except KeyError:
                pass
            if self.owns_connection(connection):
                self._available_connections.append(connection)
            else:
                self._created_connections -= 1
                await connection.disconnect()
                return
    def owns_connection(self, connection: Connection):
        return connection.pid == self.pid
    async def disconnect(self, inuse_connections: bool = True):
        self._checkpid()
        async with self._lock:
            if inuse_connections:
                connections: Iterable[Connection] = chain(
                    self._available_connections, self._in_use_connections
                )
            else:
                connections = self._available_connections
            resp = await asyncio.gather(
                *(connection.disconnect() for connection in connections),
                return_exceptions=True,
            )
            exc = next((r for r in resp if isinstance(r, BaseException)), None)
            if exc:
                raise exc

class ScaleContinuous(Scale):
    def __init__(self, aesthetics=None, scale_name=None, range=None, limits=None, na_value=NA,
                 expand=Waiver(), name=Waiver(), breaks=Waiver(), labels=Waiver(), guide="legend",
                 trans=TransIdentity(), rescaler=rescale, oob=censor, palette=None,
                 minor_breaks=Waiver()):
        range = RangeContinuous() if range is None else range
        Scale.__init__(self, aesthetics=aesthetics, range=range, na_value=na_value, trans=trans, limits=limits,
                       expand=expand, name=name, breaks=breaks, labels=labels, guide=guide, scale_name=scale_name,
                       palette=palette)
        self.rescaler = rescaler
        self.oob = oob
        self.minor_breaks = minor_breaks
    def expand_default(self, discrete=(0, 0.6), continuous=(0.05, 0)):
        return continuous
    def default_palette(self):
        return None
    def is_emtpy(self):
        return all(np.isnan(self.range.range)) or (self.limits is not None and all(np.isnan(self.limits)))
    def is_discrete(self):
        return False
    def train(self, x):
        if len(x) != 0:
            self.range.train(x)
    def transform(self, x):
        return self.trans.transform(x)
    def map(self, x, limits=None):
        if limits is None:
            limits = self.get_limits()
        x = self.oob(self.rescaler(x, from_=limits))
        uniq = np.unique(x)
        pal = self.palette(uniq)
        scaled = [pal[int(np.argwhere(v == uniq))] for v in x]
        scaled[is_nan(x)] = self.na_value
        return scaled
    def dimension(self, expand=(0, 0)):
        return expand_range(self.get_limits(), expand[0], expand[1])
    def get_breaks(self, limits=None):
        if self.is_emtpy():
            return np.array(())
        if limits is None:
            limits = self.get_limits()
        limits = self.trans.inverse(limits)
        if self.breaks is None:
            return np.array(())
        elif zero_range(limits):
            breaks = limits[0]
        elif type(self.breaks) == Waiver:
            breaks = self.trans.breaks(limits)
        elif callable(self.breaks):
            breaks = self.breaks(limits)
        else:
            breaks = self.breaks
        breaks = censor(self.trans.transform(breaks), self.trans.transform(limits), only_finite=False)
        if len(breaks) == 0:
            raise ValueError("Zero breaks for %s" % "/".join(self.aesthetics))
        return breaks
    def get_breaks_minor(self, n=2, b=None, limits=None):
        if b is None:
            b = self.break_positions()
        if limits is None:
            limits = self.get_limits()
        if zero_range(limits):
            return np.array(())
        if self.minor_breaks is None:
            return np.array(())
        elif isinstance(self.minor_breaks, Waiver):
            if b is None:
                return np.array(())
            b = b[~is_nan(b)]
            if len(b) < 2:
                return np.array(())
            bd = np.diff(b)[0]
            if np.min(limits) < np.min(b):
                b = np.concatenate([[b[0] - bd, ], b])
            if np.max(limits) > np.max(b):
                b = np.concatenate([b, [b[len(b)-1] + bd,]])
            breaks = [(b[i-1]+b[i])/2 for i in range(1, len(b))]
        elif callable(self.minor_breaks):
            breaks = self.minor_breaks(self.trans.inverse(limits))
            breaks = self.trans.transform(breaks)
        elif is_nan(self.minor_breaks):
            raise ValueError("Use None to specify no minor breaks")
        else:
            breaks = self.trans.transform(self.minor_breaks)
        return np.array([br for br in breaks if limits[0] <= br <= limits[1]])
    def get_labels(self, breaks=None):
        if self.labels is None:
            return np.array(())
        if breaks is None:
            breaks = self.get_breaks()
        if type(self.labels) == Waiver:
            return self.trans.format(breaks)
        elif callable(self.labels):
            return np.array(self.labels(breaks))
        else:
            labels = np.array(self.labels)
        if len(labels) != len(breaks):
            raise ValueError("Length of labels is different than length of breaks")
        return labels
    def clone(self):
        return copy.deepcopy(self)
    def break_info(self, range=None):
        if range is None:
            range = self.dimension()
        major = self.get_breaks(range)
        labels = self.get_labels(major)
        if major is not None:
            major = major[~np.isnan(major)]
        if labels is not None and len(labels) > 0:
            labels = labels[~is_nan(labels)]
        minor = self.get_breaks_minor(b=major, limits=range)
        major_n = rescale(major, from_=range)
        minor_n = rescale(minor, from_=range)
        return {'range': range, 'labels': labels, 'major': major_n, 'minor': minor_n,
                'major_source': major, 'minor_source': minor}
    def __repr__(self):  
        return "<%s>\n  Range: %.3f -- %.3f\n  Limits: %.3f -- %.3f\n  Breaks: %s" % \
               (type(self), self.range.range[0], self.range.range[1],
                self.dimension()[0], self.dimension()[1],
                self.break_info())

class ScaleDiscrete(Scale):
    def __init__(self, aesthetics=None, scale_name=None, drop=True, range=None, limits=None, na_value=NA_character_,
                 expand=Waiver(), name=Waiver(), breaks=Waiver(), palette=None,
                 labels=Waiver(), guide="legend"):
        range = RangeDiscrete() if range is None else range
        Scale.__init__(self, na_value=na_value, name=name, breaks=breaks, labels=labels, limits=limits,
                       expand=expand, guide=guide, range=range, aesthetics=aesthetics, scale_name=scale_name,
                       palette=palette)
        self.drop = drop
    def expand_default(self, discrete=(0, 0.6), continuous=(0.05, 0)):
        return discrete
    def default_palette(self, x=0):
        return lambda n: PaletteDiscrete(n=n, na_value=self.na_value)
    def is_emtpy(self):
        return len(self.range.range) == 0 and self.limits is not None and len(self.limits) == 0
    def is_discrete(self):
        return True
    def train(self, x):
        if len(x) == 0:
            return
        self.range.train(x, drop=self.drop)
    def transform(self, x):
        return x
    def map(self, x, limits=None):
        if limits is None:
            limits = self.get_limits()
        limits = list(limits)
        n = np.sum(~is_nan(np.array(limits)))
        pal = self.palette(n)
        pal_match = np.array([pal[limits.index(v)] if v in limits else NA for v in x])
        return pal_match
    def dimension(self, expand=(0, 0)):
        return expand_range((0, len(self.get_limits())-1), expand[0], expand[1])
    def get_breaks(self, limits=None):
        if self.is_emtpy():
            return np.array(())
        if limits is None:
            limits = self.get_limits()
        if self.breaks is None:
            return np.array(())
        elif type(self.breaks) == Waiver:
            breaks = limits
        elif callable(self.breaks):
            breaks = self.breaks(limits)
        else:
            breaks = self.breaks
        return np.array([b for b in breaks if b in limits])
    def get_breaks_minor(self, **kwargs):
        return np.array(())
    def get_labels(self, breaks=None):
        if self.labels is None:
            return np.array(())
        if breaks is None:
            breaks = self.get_breaks()
        if type(self.labels) == Waiver:
            return np.array([('%s' % label).strip() for label in breaks])
        elif callable(self.labels):
            return np.array(self.labels(breaks))
        elif type(self.labels) == dict:
            return np.array([self.labels[b] for b in breaks])
        else:
            labels = np.array(self.labels)
        if len(labels) != len(breaks):
            raise ValueError("Length of labels is different than length of breaks")
        return labels
    def clone(self):
        return copy.deepcopy(self)
    def break_info(self, range=None):
        limits = self.get_limits()
        major = self.get_breaks(limits)
        if len(major) == 0:
            labels = major_n = np.array(())
        else:
            labels = self.get_labels(major)
            major = self.map(major)
            if len(major) > 0:
                mask = ~is_nan(major)
                major = major[mask]
                labels = labels[mask]
            major_n = np.repeat(NA, len(major)) if range is None else rescale(major, from_=range)
        return {'range': range, 'labels': labels, 'major': major_n,
                'major_source': major}
    def __repr__(self):  
        return "<%s>\n  Range: %s\n  Limits: %s\n  Breaks: %s" % \
               (type(self), self.range.range, self.get_limits(), self.break_info())

