class LayoutAPI(object):
    swagger_types = {
        'kind': 'str',
        'layout': 'Layout',
        'type_id': 'str'
    }
    attribute_map = {
        'kind': 'kind',
        'layout': 'layout',
        'type_id': 'typeId'
    }
    def __init__(self, kind=None, layout=None, type_id=None):  
        self._kind = None
        self._layout = None
        self._type_id = None
        self.discriminator = None
        if kind is not None:
            self.kind = kind
        if layout is not None:
            self.layout = layout
        if type_id is not None:
            self.type_id = type_id
    @property
    def kind(self):
        return self._kind
    @kind.setter
    def kind(self, kind):
        self._kind = kind
    @property
    def layout(self):
        return self._layout
    @layout.setter
    def layout(self, layout):
        self._layout = layout
    @property
    def type_id(self):
        return self._type_id
    @type_id.setter
    def type_id(self, type_id):
        self._type_id = type_id
    def to_dict(self):
        result = {}
        for attr, _ in six.iteritems(self.swagger_types):
            value = getattr(self, attr)
            if isinstance(value, list):
                result[attr] = list(map(
                    lambda x: x.to_dict() if hasattr(x, "to_dict") else x,
                    value
                ))
            elif hasattr(value, "to_dict"):
                result[attr] = value.to_dict()
            elif isinstance(value, dict):
                result[attr] = dict(map(
                    lambda item: (item[0], item[1].to_dict())
                    if hasattr(item[1], "to_dict") else item,
                    value.items()
                ))
            else:
                result[attr] = value
        if issubclass(LayoutAPI, dict):
            for key, value in self.items():
                result[key] = value
        return result
    def to_str(self):
        return pprint.pformat(self.to_dict())
    def __repr__(self):
        return self.to_str()
    def __eq__(self, other):
        if not isinstance(other, LayoutAPI):
            return False
        return self.__dict__ == other.__dict__
    def __ne__(self, other):
        return not self == other

class Person():
	EYES_COLORS = ["Blue", "Green", "Brown"]
	GENRES = ["Female", "Male"]
	def __init__(self, id, first_name, date_of_birth, genre, eyes_color, is_married_to=0, last_name=None, children=[]):
		if id < 0 or type(id) != int:
			raise Exception("id is not an integer")
		if not first_name or type(first_name) != str:
			raise Exception("string is not a string")
		if type(date_of_birth) != list or len(date_of_birth) != 3 or not all(isinstance(x, int) for x in date_of_birth):
			raise Exception("date_of_birth is not a valid date")
		if genre not in Person.GENRES:
			raise Exception("genre is not valid")
		if eyes_color not in Person.EYES_COLORS:
			raise Exception("eyes_color is not valid")
		self.__id = id
		self.__eyes_color = eyes_color
		self.__genre = genre
		self.__gender = genre
		self.__date_of_birth = date_of_birth
		self.__first_name = first_name
		self.last_name = last_name
		self.is_married_to = is_married_to
		self.children = children[:]
	@staticmethod
	def load_from_json(json):
		if not type(json) == dict:
			raise Exception("json is not valid")
		if not all(i in json.keys() for i in ["id", "eyes_color", "genre", "date_of_birth", "first_name", "last_name", "is_married_to", "children"]):
			raise Exception("JSON missing fields")
		if "type" in json.keys():
			try:
				return {"Baby": Baby,
				"Teenager": Teenager,
				"Adult": Adult,
				"Senior": Senior,
			 	}[json["type"]](json["id"],
								str(json["first_name"]),
								json["date_of_birth"],
								json["genre"],
								json["eyes_color"],
								json["is_married_to"],
								str(json["last_name"]),
								json["children"])
			except:
				pass
		return Person(json["id"],
					  str(json["first_name"]),
					  json["date_of_birth"],
					  json["genre"],
					  json["eyes_color"],
					  json["is_married_to"],
					  str(json["last_name"]),
					  json["children"])
	def json(self):
		return {
			"type": self.type_string(),
			"id": self.__id,
			"eyes_color": self.__eyes_color,
			"genre": self.__genre,
			"date_of_birth": self.__date_of_birth,
			"first_name": self.__first_name,
			"last_name": self.last_name,
			"is_married_to": self.is_married_to,
			"children": self.children
		}
	def __str__(self):
		str = self.__first_name
		if self.last_name:
			str += " " + self.last_name
		return str
	def __repr__(self):
		return self.__str__()
	def get_id(self):
		return self.__id
	def is_married(self):
		if self.is_married_to:
			return True
		return False
	def divorce(self, p):
		if not self.__id == p.is_married_to or not p.__id == self.is_married_to:
			raise Exception("Not married to each other")
		self.is_married_to = 0
		p.is_married_to = 0
	def just_married_with(self, p):
		if p.is_married() or self.is_married():
			raise Exception("Already married")
		if not p.can_be_married() or not self.can_be_married():
			raise Exception("Can't be married")
		self.is_married_to = p.__id
		p.is_married_to = self.__id
		if {self.__gender, p.__gender} == {"Male", "Female"}:
			if p.__gender == "Male" and p.last_name:
				self.last_name = p.last_name
			elif self.__gender == "Male" and self.last_name:
				p.last_name = self.last_name
	def can_be_married(self):
		return any(isinstance(self, kind) for kind in [Adult, Senior])
	def type_string(self):
		return "Person"
	def is_male(self):
		return self.__gender == "Male"
	def age(self):
		age_ = 2016 - self.__date_of_birth[2]
		if self.__date_of_birth[0] >= 5 and self.__date_of_birth[1] >= 20:
			age_ += 1
		return age_
	def can_have_child(self):
		return isinstance(self, Adult)
	def has_child_with(self, p, id, first_name, date_of_birth, genre, eyes_color=None, married_to=0, last_name=None):
		if not all(person.can_have_child() for person in [self, p]):
			raise Exception("Can't have baby")
		if not eyes_color:
			if any(color == "Brown" for color in [self.__eyes_color, p.__eyes_color]):
				eyes_color = "Brown"
			elif any(color == "Blue" for color in [self.__eyes_color, p.__eyes_color]):
				eyes_color = "Blue"
			else:
				eyes_color = "Green"
		baby = Baby(id, first_name, date_of_birth, genre, eyes_color, married_to, last_name)
		self.children.append(id)
		p.children.append(id)
		return baby
	def get_eyes_color(self):
		return self.__eyes_color
	def adopt_child(self, c):
		if not self.can_have_child():
			raise Exception("Can't adopt child")
		self.children.append(c.__id)
	def who_are_my_grandchildren(self, list_person):
		raise NotImplementedError("Please Implement this method")
	def who_are_my_grand_parents(self, list_person):
		raise NotImplementedError("Please Implement this method")
	def who_are_my_parents(self, list_person):
		raise NotImplementedError("Please Implement this method")
	def can_run(self):
		raise NotImplementedError("Please Implement this method")
	def need_help(self):
		raise NotImplementedError("Please Implement this method")
	def is_young(self):
		raise NotImplementedError("Please Implement this method")
	def can_vote(self):
		raise NotImplementedError("Please Implement this method")
	def __cmp__(self, other):
		if self.age() == other.age():
			return True
		return False
	def __lt__(self, other):
		if self.age() < other.age():
			return True
		return False
	def __le__(self, other):
		if self.age() <= other.age():
			return True
		return False
	def __ne__(self, other):
		if self.age() != other.age():
			return True
		return False
	def __gt__(self, other):
		if self.age() > other.age():
			return True
		return False
	def __ge__(self, other):
		if self.age() >= other.age():
			return True
		return False

class Response(_SansIOResponse):
    implicit_sequence_conversion = True
    autocorrect_location_header = True
    automatically_set_content_length = True
    response: t.Union[t.Iterable[str], t.Iterable[bytes]]
    def __init__(
        self,
        response: t.Optional[
            t.Union[t.Iterable[bytes], bytes, t.Iterable[str], str]
        ] = None,
        status: t.Optional[t.Union[int, str, HTTPStatus]] = None,
        headers: t.Optional[
            t.Union[
                t.Mapping[str, t.Union[str, int, t.Iterable[t.Union[str, int]]]],
                t.Iterable[t.Tuple[str, t.Union[str, int]]],
            ]
        ] = None,
        mimetype: t.Optional[str] = None,
        content_type: t.Optional[str] = None,
        direct_passthrough: bool = False,
    ) -> None:
        super().__init__(
            status=status,
            headers=headers,
            mimetype=mimetype,
            content_type=content_type,
        )
        self.direct_passthrough = direct_passthrough
        self._on_close: t.List[t.Callable[[], t.Any]] = []
        if response is None:
            self.response = []
        elif isinstance(response, (str, bytes, bytearray)):
            self.set_data(response)
        else:
            self.response = response
    def call_on_close(self, func: t.Callable[[], t.Any]) -> t.Callable[[], t.Any]:
        self._on_close.append(func)
        return func
    def __repr__(self) -> str:
        if self.is_sequence:
            body_info = f"{sum(map(len, self.iter_encoded()))} bytes"
        else:
            body_info = "streamed" if self.is_streamed else "likely-streamed"
        return f"<{type(self).__name__} {body_info} [{self.status}]>"
    @classmethod
    def force_type(
        cls, response: "Response", environ: t.Optional["WSGIEnvironment"] = None
    ) -> "Response":
        if not isinstance(response, Response):
            if environ is None:
                raise TypeError(
                    "cannot convert WSGI application into response"
                    " objects without an environ"
                )
            from ..test import run_wsgi_app
            response = Response(*run_wsgi_app(response, environ))
        response.__class__ = cls
        return response
    @classmethod
    def from_app(
        cls, app: "WSGIApplication", environ: "WSGIEnvironment", buffered: bool = False
    ) -> "Response":
        from ..test import run_wsgi_app
        return cls(*run_wsgi_app(app, environ, buffered))
    @typing.overload
    def get_data(self, as_text: "te.Literal[False]" = False) -> bytes:
        ...
    @typing.overload
    def get_data(self, as_text: "te.Literal[True]") -> str:
        ...
    def get_data(self, as_text: bool = False) -> t.Union[bytes, str]:
        self._ensure_sequence()
        rv = b"".join(self.iter_encoded())
        if as_text:
            return rv.decode(self.charset)
        return rv
    def set_data(self, value: t.Union[bytes, str]) -> None:
        if isinstance(value, str):
            value = value.encode(self.charset)
        else:
            value = bytes(value)
        self.response = [value]
        if self.automatically_set_content_length:
            self.headers["Content-Length"] = str(len(value))
    data = property(
        get_data,
        set_data,
        doc="A descriptor that calls :meth:`get_data` and :meth:`set_data`.",
    )
    def calculate_content_length(self) -> t.Optional[int]:
        try:
            self._ensure_sequence()
        except RuntimeError:
            return None
        return sum(len(x) for x in self.iter_encoded())
    def _ensure_sequence(self, mutable: bool = False) -> None:
        if self.is_sequence:
            if mutable and not isinstance(self.response, list):
                self.response = list(self.response)  
            return
        if self.direct_passthrough:
            raise RuntimeError(
                "Attempted implicit sequence conversion but the"
                " response object is in direct passthrough mode."
            )
        if not self.implicit_sequence_conversion:
            raise RuntimeError(
                "The response object required the iterable to be a"
                " sequence, but the implicit conversion was disabled."
                " Call make_sequence() yourself."
            )
        self.make_sequence()
    def make_sequence(self) -> None:
        if not self.is_sequence:
            close = getattr(self.response, "close", None)
            self.response = list(self.iter_encoded())
            if close is not None:
                self.call_on_close(close)
    def iter_encoded(self) -> t.Iterator[bytes]:
        if __debug__:
            _warn_if_string(self.response)
        return _iter_encoded(self.response, self.charset)
    @property
    def is_streamed(self) -> bool:
        try:
            len(self.response)  
        except (TypeError, AttributeError):
            return True
        return False
    @property
    def is_sequence(self) -> bool:
        return isinstance(self.response, (tuple, list))
    def close(self) -> None:
        if hasattr(self.response, "close"):
            self.response.close()  
        for func in self._on_close:
            func()
    def __enter__(self) -> "Response":
        return self
    def __exit__(self, exc_type, exc_value, tb):  
        self.close()
    def freeze(self, no_etag: None = None) -> None:
        self.response = list(self.iter_encoded())
        self.headers["Content-Length"] = str(sum(map(len, self.response)))
        if no_etag is not None:
            warnings.warn(
                "The 'no_etag' parameter is deprecated and will be"
                " removed in Werkzeug 2.1.",
                DeprecationWarning,
                stacklevel=2,
            )
        self.add_etag()
    def get_wsgi_headers(self, environ: "WSGIEnvironment") -> Headers:
        headers = Headers(self.headers)
        location: t.Optional[str] = None
        content_location: t.Optional[str] = None
        content_length: t.Optional[t.Union[str, int]] = None
        status = self.status_code
        for key, value in headers:
            ikey = key.lower()
            if ikey == "location":
                location = value
            elif ikey == "content-location":
                content_location = value
            elif ikey == "content-length":
                content_length = value
        if location is not None:
            old_location = location
            if isinstance(location, str):
                location = iri_to_uri(location, safe_conversion=True)
            if self.autocorrect_location_header:
                current_url = get_current_url(environ, strip_querystring=True)
                if isinstance(current_url, str):
                    current_url = iri_to_uri(current_url)
                location = url_join(current_url, location)
            if location != old_location:
                headers["Location"] = location
        if content_location is not None and isinstance(content_location, str):
            headers["Content-Location"] = iri_to_uri(content_location)
        if 100 <= status < 200 or status == 204:
            headers.remove("Content-Length")
        elif status == 304:
            remove_entity_headers(headers)
        if (
            self.automatically_set_content_length
            and self.is_sequence
            and content_length is None
            and status not in (204, 304)
            and not (100 <= status < 200)
        ):
            try:
                content_length = sum(len(_to_bytes(x, "ascii")) for x in self.response)
            except UnicodeError:
                pass
            else:
                headers["Content-Length"] = str(content_length)
        return headers
    def get_app_iter(self, environ: "WSGIEnvironment") -> t.Iterable[bytes]:
        status = self.status_code
        if (
            environ["REQUEST_METHOD"] == "HEAD"
            or 100 <= status < 200
            or status in (204, 304)
        ):
            iterable: t.Iterable[bytes] = ()
        elif self.direct_passthrough:
            if __debug__:
                _warn_if_string(self.response)
            return self.response  
        else:
            iterable = self.iter_encoded()
        return ClosingIterator(iterable, self.close)
    def get_wsgi_response(
        self, environ: "WSGIEnvironment"
    ) -> t.Tuple[t.Iterable[bytes], str, t.List[t.Tuple[str, str]]]:
        headers = self.get_wsgi_headers(environ)
        app_iter = self.get_app_iter(environ)
        return app_iter, self.status, headers.to_wsgi_list()
    def __call__(
        self, environ: "WSGIEnvironment", start_response: "StartResponse"
    ) -> t.Iterable[bytes]:
        app_iter, status, headers = self.get_wsgi_response(environ)
        start_response(status, headers)
        return app_iter
    json_module = json
    @property
    def json(self) -> t.Optional[t.Any]:
        return self.get_json()
    def get_json(self, force: bool = False, silent: bool = False) -> t.Optional[t.Any]:
        if not (force or self.is_json):
            return None
        data = self.get_data()
        try:
            return self.json_module.loads(data)
        except ValueError:
            if not silent:
                raise
            return None
    @cached_property
    def stream(self) -> "ResponseStream":
        return ResponseStream(self)
    def _wrap_range_response(self, start: int, length: int) -> None:
        if self.status_code == 206:
            self.response = _RangeWrapper(self.response, start, length)  
    def _is_range_request_processable(self, environ: "WSGIEnvironment") -> bool:
        return (
            "HTTP_IF_RANGE" not in environ
            or not is_resource_modified(
                environ,
                self.headers.get("etag"),
                None,
                self.headers.get("last-modified"),
                ignore_if_range=False,
            )
        ) and "HTTP_RANGE" in environ
    def _process_range_request(
        self,
        environ: "WSGIEnvironment",
        complete_length: t.Optional[int] = None,
        accept_ranges: t.Optional[t.Union[bool, str]] = None,
    ) -> bool:
        from ..exceptions import RequestedRangeNotSatisfiable
        if (
            accept_ranges is None
            or complete_length is None
            or complete_length == 0
            or not self._is_range_request_processable(environ)
        ):
            return False
        parsed_range = parse_range_header(environ.get("HTTP_RANGE"))
        if parsed_range is None:
            raise RequestedRangeNotSatisfiable(complete_length)
        range_tuple = parsed_range.range_for_length(complete_length)
        content_range_header = parsed_range.to_content_range_header(complete_length)
        if range_tuple is None or content_range_header is None:
            raise RequestedRangeNotSatisfiable(complete_length)
        content_length = range_tuple[1] - range_tuple[0]
        self.headers["Content-Length"] = content_length
        self.headers["Accept-Ranges"] = accept_ranges
        self.content_range = content_range_header  
        self.status_code = 206
        self._wrap_range_response(range_tuple[0], content_length)
        return True
    def make_conditional(
        self,
        request_or_environ: "WSGIEnvironment",
        accept_ranges: t.Union[bool, str] = False,
        complete_length: t.Optional[int] = None,
    ) -> "Response":
        environ = _get_environ(request_or_environ)
        if environ["REQUEST_METHOD"] in ("GET", "HEAD"):
            if "date" not in self.headers:
                self.headers["Date"] = http_date()
            accept_ranges = _clean_accept_ranges(accept_ranges)
            is206 = self._process_range_request(environ, complete_length, accept_ranges)
            if not is206 and not is_resource_modified(
                environ,
                self.headers.get("etag"),
                None,
                self.headers.get("last-modified"),
            ):
                if parse_etags(environ.get("HTTP_IF_MATCH")):
                    self.status_code = 412
                else:
                    self.status_code = 304
            if (
                self.automatically_set_content_length
                and "content-length" not in self.headers
            ):
                length = self.calculate_content_length()
                if length is not None:
                    self.headers["Content-Length"] = length
        return self
    def add_etag(self, overwrite: bool = False, weak: bool = False) -> None:
        if overwrite or "etag" not in self.headers:
            self.set_etag(generate_etag(self.get_data()), weak)

class GateOperation(raw_types.Operation,
                    extension.PotentialImplementation[Union[
                        gate_features.BoundedEffect,
                        gate_features.CompositeOperation,
                        gate_features.ExtrapolatableEffect,
                        gate_features.PhaseableEffect,
                        gate_features.ReversibleEffect,
                        gate_features.QasmConvertibleOperation,
                    ]]):
    def __init__(self,
                 gate: raw_types.Gate,
                 qubits: Sequence[raw_types.QubitId]) -> None:
        self._gate = gate
        self._qubits = tuple(qubits)
    @property
    def gate(self) -> raw_types.Gate:
        return self._gate
    @property
    def qubits(self) -> Tuple[raw_types.QubitId, ...]:
        return self._qubits
    def with_qubits(self, *new_qubits: raw_types.QubitId) -> 'GateOperation':
        return self.gate.on(*new_qubits)
    def with_gate(self, new_gate: raw_types.Gate) -> 'GateOperation':
        return new_gate.on(*self.qubits)
    def __repr__(self):
        if self == self.gate.on(*self.qubits):
            return '{!r}.on({})'.format(
                self.gate,
                ', '.join(repr(q) for q in self.qubits))
        return 'cirq.GateOperation(gate={!r}, qubits={!r})'.format(
            self.gate,
            list(self.qubits))
    def __str__(self):
        return '{}({})'.format(self.gate,
                               ', '.join(str(e) for e in self.qubits))
    def _group_interchangeable_qubits(self) -> Tuple[
            Union[raw_types.QubitId,
                  Tuple[int, FrozenSet[raw_types.QubitId]]],
            ...]:
        cast_gate = extension.try_cast(gate_features.InterchangeableQubitsGate,
                                       self.gate)
        if cast_gate is None:
            return self.qubits
        groups = {}  
        for i, q in enumerate(self.qubits):
            k = cast_gate.qubit_index_to_equivalence_group_key(i)
            if k not in groups:
                groups[k] = []
            groups[k].append(q)
        return tuple(sorted((k, frozenset(v)) for k, v in groups.items()))
    def _eq_tuple(self):
        grouped_qubits = self._group_interchangeable_qubits()
        return raw_types.Operation, self.gate, grouped_qubits
    def __hash__(self):
        return hash(self._eq_tuple())
    def __eq__(self, other):
        if not isinstance(other, type(self)):
            return NotImplemented
        return self._eq_tuple() == other._eq_tuple()
    def __ne__(self, other):
        return not self == other
    def try_cast_to(self, desired_type, extensions):
        desired_gate_type = LIFTED_POTENTIAL_TYPES.get(desired_type)
        if desired_gate_type is not None:
            cast_gate = extensions.try_cast(desired_gate_type, self.gate)
            if cast_gate is not None:
                return self.with_gate(cast_gate)
        return None
    def default_decompose(self):
        cast_gate = extension.cast(gate_features.CompositeGate, self.gate)
        return cast_gate.default_decompose(self.qubits)
    def _apply_unitary_to_tensor_(self,
                                  target_tensor: np.ndarray,
                                  available_buffer: np.ndarray,
                                  axes: Sequence[int],
                                  ) -> Union[np.ndarray, type(NotImplemented)]:
        return protocols.apply_unitary_to_tensor(
            self.gate,
            target_tensor,
            available_buffer,
            axes,
            default=NotImplemented)
    def _unitary_(self) -> Union[np.ndarray, type(NotImplemented)]:
        return protocols.unitary(self._gate, NotImplemented)
    def _is_parameterized_(self) -> bool:
        return protocols.is_parameterized(self._gate)
    def _resolve_parameters_(self, resolver):
        resolved_gate = protocols.resolve_parameters(self._gate, resolver)
        return GateOperation(resolved_gate, self._qubits)
    def _circuit_diagram_info_(self,
                               args: protocols.CircuitDiagramInfoArgs
                               ) -> protocols.CircuitDiagramInfo:
        return protocols.circuit_diagram_info(self.gate,
                                              args,
                                              NotImplemented)
    def trace_distance_bound(self) -> float:
        cast_gate = extension.cast(gate_features.BoundedEffect, self.gate)
        return cast_gate.trace_distance_bound()
    def inverse(self) -> 'GateOperation':
        cast_gate = extension.cast(gate_features.ReversibleEffect, self.gate)
        return self.with_gate(cast(raw_types.Gate, cast_gate.inverse()))
    def extrapolate_effect(self, factor: Union[float, value.Symbol]
                           ) -> 'GateOperation':
        cast_gate = extension.cast(gate_features.ExtrapolatableEffect,
                                   self.gate)
        return self.with_gate(cast(raw_types.Gate,
                                   cast_gate.extrapolate_effect(factor)))
    def phase_by(self, phase_turns: float, qubit_index: int) -> 'GateOperation':
        cast_gate = extension.cast(gate_features.PhaseableEffect,
                                   self.gate)
        return self.with_gate(cast(raw_types.Gate,
                                   cast_gate.phase_by(phase_turns,
                                                      qubit_index)))
    def __pow__(self, power: float) -> 'GateOperation':
        if power == -1:
            inv_gate = protocols.inverse(self.gate, None)
            if inv_gate is None:
                return NotImplemented
            return self.with_gate(inv_gate)
        return self.extrapolate_effect(power)
    def known_qasm_output(self,
                          args: gate_features.QasmOutputArgs) -> Optional[str]:
        cast_gate = extension.cast(gate_features.QasmConvertibleGate,
                                   self.gate)
        return cast_gate.known_qasm_output(self.qubits, args)

class SelectionMask(object):
    (kSelectObjectMode,
     kSelectComponentMode,
     kSelectRootModem,
     kSelectLeafMode,
     kSelectTemplateMode) = range(5)
    def __new__(cls, mask=None):
        cls = object.__new__(cls, mask)
        for a in oapi.MSelectionMask.__dict__:
            if a.startswith('kSelect'):
                setattr(cls, a, oapi.MSelectionMask.__dict__[a])
        return cls
    def __init__(self, mask=None):
        self._mask = mask or oapi.MSelectionMask()
    def __repr__(self):
        return '{}({})'.format(self.__class__.__name__, list(self))
    def __str__(self):
        return '{}'.format(self.typestr)
    def __iter__(self):
        return iter(self.get_active_masks(local=True))
    def __contains__(self, value):
        return self._mask.intersects(value)
    @property
    def mask(self):
        return self._mask
    @property
    def mode(self):
        return MGlobal.selectionMode()
    @property
    def typestr(self):
        return self.get_active_masks(internal=False, local=True)
    @classmethod
    def active(cls):
        mask = {
            MGlobal.kSelectObjectMode: MGlobal.objectSelectionMask(),
            MGlobal.kSelectComponentMode: MGlobal.componentSelectionMask(),
        }[MGlobal.selectionMode()]
        return cls(mask)
    @staticmethod
    def set_mode(kmode):
        MGlobal.setSelectionMode(kmode)
    def add(self, other):
        if type(other) in [list, tuple, set]:
            for o in other:
                self._mask.addMask(o)
        else:
            self._mask.addMask(other)
        self.update()
    def set_mask(self, other):
        self._mask.setMask(other)
        self.update()
    def get_active_masks(self, internal=True, local=False):
        active = set()
        for m in self.__dict__:
            if not m.startswith('kSelect'):
                continue
            if local:
                space = self
            else:
                space = self.active()
            if self.__dict__[m] in space:
                if internal:
                    active.add(self.__dict__[m])
                else:
                    active.add(m)
        return active
    def clear(self):
        self._mask = oapi.MSelectionMask()
        self.update()
    def update(self):
        if self.mode == MGlobal.kSelectComponentMode:
            MGlobal.setComponentSelectionMask(self._mask)
        elif self.mode == MGlobal.kSelectObjectMode:
            MGlobal.setObjectSelectionMask(self._mask)

class LeaveOneOut(object):
    def __init__(self, n, indices=False):
        self.n = n
        self.indices = indices
    def __iter__(self):
        n = self.n
        for i in xrange(n):
            test_index = np.zeros(n, dtype=np.bool)
            test_index[i] = True
            train_index = np.logical_not(test_index)
            if self.indices:
                ind = np.arange(n)
                train_index = ind[train_index]
                test_index = ind[test_index]
            yield train_index, test_index
    def __repr__(self):
        return '%s.%s(n=%i)' % (self.__class__.__module__,
                                self.__class__.__name__,
                                self.n,
                                )
    def __len__(self):
        return self.n

class LeavePOut(object):
    def __init__(self, n, p, indices=False):
        self.n = n
        self.p = p
        self.indices = indices
    def __iter__(self):
        n = self.n
        p = self.p
        comb = combinations(range(n), p)
        for idx in comb:
            test_index = np.zeros(n, dtype=np.bool)
            test_index[np.array(idx)] = True
            train_index = np.logical_not(test_index)
            if self.indices:
                ind = np.arange(n)
                train_index = ind[train_index]
                test_index = ind[test_index]
            yield train_index, test_index
    def __repr__(self):
        return '%s.%s(n=%i, p=%i)' % (
                                self.__class__.__module__,
                                self.__class__.__name__,
                                self.n,
                                self.p,
                                )
    def __len__(self):
        return factorial(self.n) / factorial(self.n - self.p) \
               / factorial(self.p)

class KFold(object):
    def __init__(self, n, k, indices=False):
        assert k>0, ('cannot have k below 1')
        assert k<=n, ('cannot have k=%d greater than the number '
                            'of samples: %d'% (k, n))
        self.n = n
        self.k = k
        self.indices = indices
    def __iter__(self):
        n = self.n
        k = self.k
        j = ceil(n / k)
        for i in xrange(k):
            test_index = np.zeros(n, dtype=np.bool)
            if i < k-1:
                test_index[i*j:(i+1)*j] = True
            else:
                test_index[i*j:] = True
            train_index = np.logical_not(test_index)
            if self.indices:
                ind = np.arange(n)
                train_index = ind[train_index]
                test_index = ind[test_index]
            yield train_index, test_index
    def __repr__(self):
        return '%s.%s(n=%i, k=%i)' % (
                                self.__class__.__module__,
                                self.__class__.__name__,
                                self.n,
                                self.k,
                                )
    def __len__(self):
        return self.k

class LeaveOneLabelOut(object):
    def __init__(self, labels, indices=False):
        self.labels = labels
        self.n_labels = unique(labels).size
        self.indices = indices
    def __iter__(self):
        labels = np.array(self.labels, copy=True)
        for i in unique(labels):
            test_index = np.zeros(len(labels), dtype=np.bool)
            test_index[labels==i] = True
            train_index = np.logical_not(test_index)
            if self.indices:
                ind = np.arange(len(labels))
                train_index = ind[train_index]
                test_index = ind[test_index]
            yield train_index, test_index
    def __repr__(self):
        return '%s.%s(labels=%s)' % (
            self.__class__.__module__,
            self.__class__.__name__,
            self.labels,
        )
    def __len__(self):
        return self.n_labels

class LeavePLabelOut(object):
    def __init__(self, labels, p, indices=False):
        self.labels = labels
        self.unique_labels = unique(self.labels)
        self.n_labels = self.unique_labels.size
        self.p = p
        self.indices = indices
    def __iter__(self):
        labels = np.array(self.labels, copy=True)
        unique_labels = unique(labels)
        n_labels = unique_labels.size
        comb = combinations(range(n_labels), self.p)
        for idx in comb:
            test_index = np.zeros(labels.size, dtype=np.bool)
            idx = np.array(idx)
            for l in unique_labels[idx]:
                test_index[labels == l] = True
            train_index = np.logical_not(test_index)
            if self.indices:
                ind = np.arange(labels.size)
                train_index = ind[train_index]
                test_index = ind[test_index]
            yield train_index, test_index
    def __repr__(self):
        return '%s.%s(labels=%s, p=%s)' % (
                                self.__class__.__module__,
                                self.__class__.__name__,
                                self.labels,
                                self.p,
                                )
    def __len__(self):
        return factorial(self.n_labels) / factorial(self.n_labels - self.p) \
               / factorial(self.p)

class Users(Base):
    __tablename__ = 'users'
    id = sa.Column(sa.Integer, primary_key=True)
    username = sa.Column(sa.String(20), nullable=False)
    password = sa.Column(sa.String(20), nullable=False)
    nickname = sa.Column(sa.String(64), nullable=False)
    email = sa.Column(sa.String(120), nullable=False)
    description = sa.Column(sa.String(500), nullable=False, server_default=' ', default=' ')
    imgpath = sa.Column(sa.String(30), nullable=False, server_default='default.jpg', default='default.jpg')
    last_seen = sa.Column(sa.DateTime())
    followed = relationship('Users',
                            secondary='followers',
                            primaryjoin=(followers.c.follower_id == id),
                            secondaryjoin=(followers.c.followed_id == id),
                            backref=backref('followers', lazy='dynamic'),
                            lazy='dynamic')
    def is_authenticated(self):
        return True
    def is_active(self):
        return True
    def is_anonymous(self):
        return False
    def get_id(self):
        return str(self.id)
    def __repr__(self):
        return 'username:%s, password:%s' % (self.username, self.password)
    def get_imgpath(self):
        img_path = '/static/resources/' + self.imgpath
        return img_path
    def follow(self, user):
        if not self.is_following(user):
            self.followed.append(user)
            return self
    def unfollow(self, user):
        if self.is_following(user):
            self.followed.remove(user)
            return self
    def is_following(self, user):
        return self.followed.filter(followers.c.followed_id == user.id).count() > 0
    def followed_posts(self, page=0):
        limit = app.config['POSTS_PER_PAGE']
        posts = self.__get_followed_posts(limit=limit, page=(page - 1))
        has_next_page = False
        tmp_posts = self.__get_followed_posts(limit=limit, page=(page))
        if tmp_posts.count() > 0:
            has_next_page = True
        has_pre_page = False
        tmp_posts = self.__get_followed_posts(limit=limit, page=(page - 2))
        if tmp_posts.count() > 0 and page > 1:
            has_pre_page = True
        results = {
            'posts' : posts,
            'has_pre_page' : has_pre_page,
            'pre_page_num' : page - 1,
            'has_next_page' : has_next_page,
            'next_page_num' : page + 1
        }
        return results
    def __get_followed_posts(self, limit, page):
        posts = session.query(Posts).join(followers, (followers.c.followed_id == Posts.user_id)).filter(
            followers.c.follower_id == self.id).order_by(Posts.timestamp.desc()).limit(limit).offset(
            limit * int(page))
        return posts

class Slot(object):
    type_name = None
    def __init__(
        self, name, initial_value=None, value_reset_delay=None, auto_fill=True
    ):
        self.name = name
        self.value = initial_value
        self.initial_value = initial_value
        self._value_reset_delay = value_reset_delay
        self.auto_fill = auto_fill
    def feature_dimensionality(self):
        return 1
    def has_features(self):
        return self.feature_dimensionality() != 0
    def value_reset_delay(self):
        return self._value_reset_delay
    def as_feature(self):
        raise NotImplementedError(
            "Each slot type needs to specify how its "
            "value can be converted to a feature. Slot "
            "'{}' is a generic slot that can not be used "
            "for predictions. Make sure you add this "
            "slot to your domain definition, specifying "
            "the type of the slot. If you implemented "
            "a custom slot type class, make sure to "
            "implement `.as_feature()`."
            "".format(self.name)
        )
    def reset(self):
        self.value = self.initial_value
    def __str__(self):
        return "{}({}: {})".format(self.__class__.__name__, self.name, self.value)
    def __repr__(self):
        return "<{}({}: {})>".format(self.__class__.__name__, self.name, self.value)
    @staticmethod
    def resolve_by_type(type_name):
        for cls in utils.all_subclasses(Slot):
            if cls.type_name == type_name:
                return cls
        try:
            return class_from_module_path(type_name)
        except (ImportError, AttributeError):
            raise ValueError(
                "Failed to find slot type, '{}' is neither a known type nor "
                "user-defined. If you are creating your own slot type, make "
                "sure its module path is correct.".format(type_name)
            )
    def persistence_info(self):
        return {
            "type": utils.module_path_from_instance(self),
            "initial_value": self.initial_value,
            "auto_fill": self.auto_fill,
        }

class BaseEstimator:
    @classmethod
    def _get_param_names(cls):
        init = getattr(cls.__init__, 'deprecated_original', cls.__init__)
        if init is object.__init__:
            return []
        init_signature = inspect.signature(init)
        parameters = [p for p in init_signature.parameters.values()
                      if p.name != 'self' and p.kind != p.VAR_KEYWORD]
        for p in parameters:
            if p.kind == p.VAR_POSITIONAL:
                raise RuntimeError("scikit-learn estimators should always "
                                   "specify their parameters in the signature"
                                   " of their __init__ (no varargs)."
                                   " %s with constructor %s doesn't "
                                   " follow this convention."
                                   % (cls, init_signature))
        return sorted([p.name for p in parameters])
    def get_params(self, deep=True):
        out = dict()
        for key in self._get_param_names():
            value = getattr(self, key, None)
            if deep and hasattr(value, 'get_params'):
                deep_items = value.get_params().items()
                out.update((key + '__' + k, val) for k, val in deep_items)
            out[key] = value
        return out
    def set_params(self, **params):
        if not params:
            return self
        valid_params = self.get_params(deep=True)
        nested_params = defaultdict(dict)  
        for key, value in params.items():
            key, delim, sub_key = key.partition('__')
            if key not in valid_params:
                raise ValueError('Invalid parameter %s for estimator %s. '
                                 'Check the list of available parameters '
                                 'with `estimator.get_params().keys()`.' %
                                 (key, self))
            if delim:
                nested_params[key][sub_key] = value
            else:
                setattr(self, key, value)
                valid_params[key] = value
        for key, sub_params in nested_params.items():
            valid_params[key].set_params(**sub_params)
        return self
    def __repr__(self, N_CHAR_MAX=700):
        from .utils._pprint import _EstimatorPrettyPrinter
        N_MAX_ELEMENTS_TO_SHOW = 30  
        pp = _EstimatorPrettyPrinter(
            compact=True, indent=1, indent_at_name=True,
            n_max_elements_to_show=N_MAX_ELEMENTS_TO_SHOW)
        repr_ = pp.pformat(self)
        n_nonblank = len(''.join(repr_.split()))
        if n_nonblank > N_CHAR_MAX:
            lim = N_CHAR_MAX // 2  
            regex = r'^(\s*\S){%d}' % lim
            left_lim = re.match(regex, repr_).end()
            right_lim = re.match(regex, repr_[::-1]).end()
            if '\n' in repr_[left_lim:-right_lim]:
                regex += r'[^\n]*\n'
                right_lim = re.match(regex, repr_[::-1]).end()
            ellipsis = '...'
            if left_lim + len(ellipsis) < len(repr_) - right_lim:
                repr_ = repr_[:left_lim] + '...' + repr_[-right_lim:]
        return repr_
    def __getstate__(self):
        try:
            state = super().__getstate__()
        except AttributeError:
            state = self.__dict__.copy()
        if type(self).__module__.startswith('sklearn.'):
            return dict(state.items(), _sklearn_version=__version__)
        else:
            return state
    def __setstate__(self, state):
        if type(self).__module__.startswith('sklearn.'):
            pickle_version = state.pop("_sklearn_version", "pre-0.18")
            if pickle_version != __version__:
                warnings.warn(
                    "Trying to unpickle estimator {0} from version {1} when "
                    "using version {2}. This might lead to breaking code or "
                    "invalid results. Use at your own risk.".format(
                        self.__class__.__name__, pickle_version, __version__),
                    UserWarning)
        try:
            super().__setstate__(state)
        except AttributeError:
            self.__dict__.update(state)
    def _get_tags(self):
        collected_tags = {}
        for base_class in inspect.getmro(self.__class__):
            if (hasattr(base_class, '_more_tags')
                    and base_class != self.__class__):
                more_tags = base_class._more_tags(self)
                collected_tags = _update_if_consistent(collected_tags,
                                                       more_tags)
        if hasattr(self, '_more_tags'):
            more_tags = self._more_tags()
            collected_tags = _update_if_consistent(collected_tags, more_tags)
        tags = _DEFAULT_TAGS.copy()
        tags.update(collected_tags)
        return tags

