class Call:
    _loop: asyncio.AbstractEventLoop
    _code: grpc.StatusCode
    _cython_call: cygrpc._AioCall
    _metadata: Tuple[MetadatumType, ...]
    _request_serializer: SerializingFunction
    _response_deserializer: DeserializingFunction
    def __init__(
        self,
        cython_call: cygrpc._AioCall,
        metadata: Metadata,
        request_serializer: SerializingFunction,
        response_deserializer: DeserializingFunction,
        loop: asyncio.AbstractEventLoop,
    ) -> None:
        self._loop = loop
        self._cython_call = cython_call
        self._metadata = tuple(metadata)
        self._request_serializer = request_serializer
        self._response_deserializer = response_deserializer
    def __del__(self) -> None:
        if hasattr(self, "_cython_call"):
            if not self._cython_call.done():
                self._cancel(_GC_CANCELLATION_DETAILS)
    def cancelled(self) -> bool:
        return self._cython_call.cancelled()
    def _cancel(self, details: str) -> bool:
        if not self._cython_call.done():
            self._cython_call.cancel(details)
            return True
        else:
            return False
    def cancel(self) -> bool:
        return self._cancel(_LOCAL_CANCELLATION_DETAILS)
    def done(self) -> bool:
        return self._cython_call.done()
    def add_done_callback(self, callback: DoneCallbackType) -> None:
        cb = partial(callback, self)
        self._cython_call.add_done_callback(cb)
    def time_remaining(self) -> Optional[float]:
        return self._cython_call.time_remaining()
    async def initial_metadata(self) -> Metadata:
        raw_metadata_tuple = await self._cython_call.initial_metadata()
        return Metadata.from_tuple(raw_metadata_tuple)
    async def trailing_metadata(self) -> Metadata:
        raw_metadata_tuple = (
            await self._cython_call.status()
        ).trailing_metadata()
        return Metadata.from_tuple(raw_metadata_tuple)
    async def code(self) -> grpc.StatusCode:
        cygrpc_code = (await self._cython_call.status()).code()
        return _common.CYGRPC_STATUS_CODE_TO_STATUS_CODE[cygrpc_code]
    async def details(self) -> str:
        return (await self._cython_call.status()).details()
    async def debug_error_string(self) -> str:
        return (await self._cython_call.status()).debug_error_string()
    async def _raise_for_status(self) -> None:
        if self._cython_call.is_locally_cancelled():
            raise asyncio.CancelledError()
        code = await self.code()
        if code != grpc.StatusCode.OK:
            raise _create_rpc_error(
                await self.initial_metadata(), await self._cython_call.status()
            )
    def _repr(self) -> str:
        return repr(self._cython_call)
    def __repr__(self) -> str:
        return self._repr()
    def __str__(self) -> str:
        return self._repr()

class LengthSum(object):
    def __init__(self, sum_type="normal"):
        self.compress_flag = False
        if sum_type == "union":
            self.add = self.add_union
            self.sum_type = "union"
            self.intervals = []
        elif sum_type == "normal":
            self.add = self.add_normal
            self.sum_type = "normal"
            self.sum = 0.0
        else:
            raise TypeError("sum_type must be either union or normal")
    def __str__(self):
        return str(self.__float__())
    def __repr__(self):
        return repr(self.__float__())
    def __float__(self):
        if self.compress_flag:
            self.intervals = self.compress(self.intervals)
        if self.sum_type == "union":
            r_sum = 0.0
            for interval in self.intervals:
                r_sum += interval[1] - interval[0]
            return r_sum
        return self.sum
    def __div__(self, other):
        return self.__float__() / other
    def add_union(self, ss, se):
        self.intervals.append((ss, se))
        self.compress_flag = True
    def add_normal(self, ss, se):
        self.sum += se - ss
    @staticmethod
    def compress(source_list):
        source_list.sort(key=lambda lis: lis[0])
        return_list = [source_list[0]]
        for cell in source_list[1:]:
            if cell[0] > return_list[-1][1]:
                return_list.append(cell)
            elif return_list[-1][1] <= cell[1]:
                return_list[-1] = (return_list[-1][0], cell[1])
        return return_list

class Vertex:
    def __init__(self, node):
        self.id = node
        self.adjacent = {}
        self.distance = sys.maxsize
        self.visited = False  
        self.previous = None
    def add_neighbor(self, neighbor, weight=0):
        self.adjacent[neighbor] = weight
    def get_connections(self):
        return self.adjacent.keys()  
    def get_id(self):
        return self.id
    def get_weight(self, neighbor):
        return self.adjacent[neighbor]
    def set_distance(self, dist):
        self.distance = dist
    def get_distance(self):
        return self.distance
    def set_previous(self, prev):
        self.previous = prev
    def set_visited(self):
        self.visited = True
    def __hash__(self):
        return hash(str(self.id))
    def __eq__(self, other):
        if isinstance(other, self.__class__):
             return self.distance == other.distance
        return NotImplemented
    def __lt__(self, other):
        if isinstance(other, self.__class__):
            return self.distance < other.distance
        return NotImplemented
    def __str__(self):
        return str(self.id) + ' adjacent: ' + str([x.id for x in self.adjacent])

class Dictionary(object):
    def __init__(self):
        self.id2word = {}
        self.word2id = {}
        self.counts = Counter()
    def __len__(self):
        return len(self.id2word)
    def __getitem__(self, i):
        return self.id2word[i]
    def __contains__(self, w):
        return w in self.word2id
    def __eq__(self, y):
        self.check_valid()
        y.check_valid()
        if len(self.id2word) != len(y):
            return False
        return all(self.id2word[i] == y[i] for i in range(len(y)))
    def from_corpus(self, path, min_occur=0, most_freq=-1):
        if isinstance(path, str):
            assert os.path.isfile(path), path
            data = open(path, 'r', encoding='utf-8')
            for line in tqdm(data, total=get_num_lines(path)):
                self.counts.update(line.split())
            data.close()
        if isinstance(path, list):
            for p in path:
                assert os.path.isfile(p), p
                data = open(p, 'r', encoding='utf-8')
                for line in tqdm(data, total=get_num_lines(p)):
                    self.counts.update(line.split())
                data.close()
        ordered_counts = OrderedDict(sorted(self.counts.items(), key=lambda item: (-item[1], item[0])))
        self.word2id = {BOS_WORD: 0, EOS_WORD: 1, PAD_WORD: 2, UNK_WORD: 3}
        for i in range(N_SPECIAL_WORDS):
            self.word2id[SPECIAL_WORD % i] = 4 + i
        self.counts = {k: 0 for k in self.word2id.keys()}
        for k, v in ordered_counts.items():
            if len(self.id2word) == most_freq:
                break
            if ordered_counts[k] > min_occur:
                if k != UNK_WORD:
                    self.word2id[k] = len(self.word2id)
                self.counts[k] = v
        self.id2word = {v: k for k, v in self.word2id.items()}
        self.check_valid()
    def from_vocab(self, vocab_path):
        skipped = 0
        assert os.path.isfile(vocab_path), vocab_path
        self.word2id = {BOS_WORD: 0, EOS_WORD: 1, PAD_WORD: 2, UNK_WORD: 3}
        for i in range(N_SPECIAL_WORDS):
            self.word2id[SPECIAL_WORD % i] = 4 + i
        self.counts = {k: 0 for k in self.word2id.keys()}
        f = open(vocab_path, 'r', encoding='utf-8')
        for i, line in enumerate(f):
            if '\u2028' in line:
                skipped += 1
                continue
            line = line.rstrip().split()
            if len(line) != 2:
                skipped += 1
                continue
            assert len(line) == 2, (i, line)
            assert line[1].isdigit(), (i, line)
            if line[0] in self.word2id:
                skipped += 1
                logger.debug('%s already in vocab' % line[0])
                continue
            if not line[1].isdigit():
                skipped += 1
                logger.debug('Empty word at line %s with count %s' % (i, line))
                continue
            self.word2id[line[0]] = 4 + N_SPECIAL_WORDS + i - skipped  
            self.counts[line[0]] = int(line[1])
        f.close()
        self.id2word = {v: k for k, v in self.word2id.items()}
        logger.info("Read %i words from the vocabulary file." % len(self.id2word))
        if skipped > 0:
            logger.warning("Skipped %i empty lines!" % skipped)
        self.check_valid()
    def check_valid(self):
        assert self.word2id[BOS_WORD] == 0
        assert self.word2id[EOS_WORD] == 1
        assert self.word2id[PAD_WORD] == 2
        assert self.word2id[UNK_WORD] == 3
        assert all(self.id2word[4 + i] == SPECIAL_WORD % i for i in range(N_SPECIAL_WORDS))
        assert len(self.id2word) == len(self.word2id) == len(self.counts)
        assert set(self.word2id.keys()) == set(self.counts.keys())
        for i in range(len(self.id2word)):
            assert self.word2id[self.id2word[i]] == i
        last_count = 1e18
        for i in range(4 + N_SPECIAL_WORDS, len(self.id2word) - 1):
            count = self.counts[self.id2word[i]]
            assert count <= last_count
            last_count = count
    def index(self, word, no_unk=False):
        if no_unk:
            return self.word2id[word]
        else:
            return self.word2id.get(word, self.word2id[UNK_WORD])
    def max_vocab(self, max_vocab):
        assert max_vocab >= 1
        init_size = len(self)
        self.id2word = {k: v for k, v in self.id2word.items() if k < max_vocab}
        self.word2id = {v: k for k, v in self.id2word.items()}
        self.counts = {k: v for k, v in self.counts.items() if k in self.word2id}
        self.check_valid()
        logger.info("Maximum vocabulary size: %i. Dictionary size: %i -> %i (removed %i words)."
                    % (max_vocab, init_size, len(self), init_size - len(self)))
    def min_count(self, min_count):
        assert min_count >= 0
        init_size = len(self)
        self.id2word = {k: v for k, v in self.id2word.items() if
                        self.counts[self.id2word[k]] >= min_count or k < 4 + N_SPECIAL_WORDS}
        self.word2id = {v: k for k, v in self.id2word.items()}
        self.counts = {k: v for k, v in self.counts.items() if k in self.word2id}
        self.check_valid()
        logger.info("Minimum frequency count: %i. Dictionary size: %i -> %i (removed %i words)."
                    % (min_count, init_size, len(self), init_size - len(self)))
    def write_vocab(self, path):
        with open(path, mode='w', encoding='utf-8') as f:
            f.writelines('{} {}'.format(k, v) + '\n' for k, v in self.counts.items())
    @staticmethod
    def index_data(dico, path, bin_path=None):
        positions = []
        sentences = []
        unk_words = {}
        eos_index = dico.word2id[EOS_WORD]
        unk_index = dico.word2id[UNK_WORD]
        f = open(path, 'r', encoding='utf-8')
        for i, line in tqdm(enumerate(f), total=get_num_lines(path)):
            s = line.rstrip().split()
            if len(s) == 0:
                logger.debug("Empty sentence in line %i." % i)
            count_unk = 0
            indexed = []
            for w in s:
                word_id = dico.index(w, no_unk=False)
                if 0 <= word_id < 4 + N_SPECIAL_WORDS and word_id != unk_index:
                    logger.warning('Found unexpected special word "%s" (%i)!!' % (w, word_id))
                    continue
                assert word_id >= 0
                indexed.append(word_id)
                if word_id == unk_index:
                    unk_words[w] = unk_words.get(w, 0) + 1
                    count_unk += 1
            positions.append([len(sentences), len(sentences) + len(indexed)])
            sentences.extend(indexed)
            sentences.append(eos_index)  
        f.close()
        positions = np.int64(positions)
        if len(dico) < 1 << 16:
            sentences = np.uint16(sentences)
        elif len(dico) < 1 << 31:
            sentences = np.int32(sentences)
        else:
            raise Exception("Dictionary is too big.")
        assert sentences.min() >= 0
        data = {
            'dictionary': dico,
            'positions': positions,
            'sentences': sentences,
            'unk_words': unk_words,
        }
        if bin_path:
            logger.info("Saving the data to %s ..." % bin_path)
            torch.save(data, bin_path, pickle_protocol=4)
        return data

