    @classmethod
    def getOptParser(cls):
        parser = argparse.ArgumentParser()
        dest = "config"
        parser.add_argument(
            "--" + dest,
            action="store",
            help="config file. if not provided will look for %s in --workdir, current directory "
            % (cls.FN_CONFIG),
        )
        dest = "noscan"
        default = False
        parser.add_argument(
            "--" + dest,
            default=default,
            action="store_true",
            help="don't scan to classify packages. build phase will re-use existing pip-stripper.scan.yaml. [%s]. "
            % (default),
        )
        dest = "build"
        default = False
        parser.add_argument(
            "--" + dest,
            default=default,
            action="store_true",
            help="read pip-stripper.scan.yaml to create requirements.prod/dev.txt [%s]"
            % (default),
        )
        dest = "init"
        parser.add_argument(
            "--" + dest,
            action="store_true",
            help="initialize the config file (as %s) if it doesn't exist"
            % (cls.FN_CONFIG),
        )
        dest = "workdir"
        parser.add_argument(
            "--" + dest,
            action="store",
            help="work directory [defaults to config file's value or current directory]",
        )
        dest = "verbose"
        default = False
        parser.add_argument(
            "--" + dest,
            default=default,
            action="store_true",
            help="verbose mode.  adds extra zzz_debug: entry to pip-stripper.scan.yaml [%s]"
            % (default),
        )
        return parser
    def _initialize(self, fnp_config):
        try:
            fnp_config = fnp_config or os.path.join(self.workdir, self.FN_CONFIG)
            if os.path.isfile(fnp_config):
                print(
                    "pip-stripper configuration file exists already at  @ %s.  leaving it alone"
                    % (fnp_config)
                )
                return fnp_config
            fnp_template = os.path.join(self.DN, "templates/pip-stripper.yaml")
            with open(fnp_template) as fi:
                tmpl = fi.read()
            seed = fill_template(tmpl, self)
            with open(fnp_config, "w") as fo:
                fo.write(seed)
            print("pip-stripper configuration generated @ %s" % (fnp_config))
            return fnp_config
        except (Exception,) as e:
            if cpdb():
                pdb.set_trace()
            raise

class Word(unicode):
    translator = Translator()
    def __new__(cls, string, pos_tag=None):
        return super(Word, cls).__new__(cls, string)
    def __init__(self, string, pos_tag=None):
        self.string = string
        self.pos_tag = pos_tag
    def __repr__(self):
        return repr(self.string)
    def __str__(self):
        return self.string
    def singularize(self):
        return Word(_singularize(self.string))
    def pluralize(self):
        return Word(_pluralize(self.string))
    def translate(self, from_lang='auto', to="en"):
        return translate(self.string, to, from_lang)                                 
    def detect_language(self):
        return self.translator.detect(self.string)
    def spellcheck(self):
        return suggest(self.string)
    def correct(self):
        return Word(self.spellcheck()[0][0])
    @cached_property
    @requires_nltk_corpus
    def lemma(self):
        tag = _penn_to_wordnet(self.pos_tag) if (self.pos_tag is not None) else None
        return self.lemmatize(pos=tag)
    @requires_nltk_corpus
    def lemmatize(self, pos=None):
        if pos is None:
            pos = _wordnet.NOUN
        lemmatizer = nltk.stem.WordNetLemmatizer()
        return lemmatizer.lemmatize(self.string, pos)
    @cached_property
    def synsets(self):
        return self.get_synsets(pos=None)
    @cached_property
    def definitions(self):
        return self.define(pos=None)
    def get_synsets(self, pos=None):
        return _wordnet.synsets(self.string, pos)
    def define(self, pos=None):
        return [syn.definition() for syn in self.get_synsets(pos=pos)]

class WordList(list):
    def __init__(self, collection):
        self._collection = [Word(w) for w in collection]
        super(WordList, self).__init__(self._collection)
    def __str__(self):
        return str(self._collection)
    def __repr__(self):
        class_name = self.__class__.__name__
        return '{cls}({lst})'.format(cls=class_name, lst=repr(self._collection))
    def __getitem__(self, key):
        if isinstance(key, slice):
            return self.__class__(self._collection[key])
        else:
            return self._collection[key]
    def __getslice__(self, i, j):
        return self.__class__(self._collection[i:j])
    def __iter__(self):
        return iter(self._collection)
    def count(self, strg, case_sensitive=False, *args, **kwargs):
        if not case_sensitive:
            return [word.lower() for word in self].count(strg.lower(), *args,
                    **kwargs)
        return self._collection.count(strg, *args, **kwargs)
    def append(self, obj):
        if isinstance(obj, basestring):
            return self._collection.append(Word(obj))
        else:
            return self._collection.append(obj)
    def extend(self, iterable):
        [self._collection.append(Word(e) if isinstance(e, basestring) else e)
            for e in iterable]
        return self
    def upper(self):
        return self.__class__([word.upper() for word in self])
    def lower(self):
        return self.__class__([word.lower() for word in self])
    def singularize(self):
        return self.__class__([word.singularize() for word in self])
    def pluralize(self):
        return self.__class__([word.pluralize() for word in self])
    def lemmatize(self):
        return self.__class__([word.lemmatize() for word in self])

