class EarlyStoppingCallback(TrainingCallback):
    def __init__(self, stopping_scores: {int: float}, improvement_window: int=100):
        super().__init__()
        self.stopping_scores = stopping_scores
        self.improvement_window = improvement_window
    def __str__(self):
        return 'EarlyStoppingCallback(stopping_scores={}, improvement_window={})'.format(self.stopping_scores, self.improvement_window)
    def __repr__(self):
        return self.__str__()
    def __call__(self, epoch, evaluation_loss_statistics, **kwargs):
        max_score = self.stopping_scores.get(epoch, float('inf'))
        if np.average(evaluation_loss_statistics[epoch]) > max_score:
            return True
        best_score_epoch = np.argmin(np.average(evaluation_loss_statistics[:epoch+1], axis=1))
        if best_score_epoch + self.improvement_window < epoch:
            return True
        return False

class ObjectContainer(EventSentinel):
    def __init__(self, obj, name=None, notes=''):
        super(ObjectContainer, self).__init__()
        self._am_obj = None
        self.am_obj = obj
        self.am_name = name if name is not None else NameGenerator.random_name()
        self.am_notes = notes
    @property
    def am_obj(self):
        return self._am_obj
    @am_obj.setter
    def am_obj(self, v):
        if type(self._am_obj) is ObjectContainer:
            self._am_obj.am_unsubscribe(self.__forwarder)
        if type(v) is ObjectContainer:
            v.am_subscribe(self.__forwarder)
        self._am_obj = v
    def am_none(self):
        return self._am_obj is None
    def __forwarder(self, **kwargs):
        kwargs['forwarded'] = True
        self.am_event(**kwargs)
    def __getattr__(self, item):
        if item.startswith('am_') or item.startswith('_am_'):
            return object.__getattribute__(self, item)
        return getattr(self._am_obj, item)
    def __setattr__(self, key, value):
        if key.startswith('am_') or key.startswith('_am_'):
            return object.__setattr__(self, key, value)
        setattr(self._am_obj, key, value)
    def __getitem__(self, item):
        return self._am_obj[item]
    def __setitem__(self, key, value):
        self._am_obj[key] = value
    def __dir__(self):
        return dir(self._am_obj) + list(self.__dict__) + list(EventSentinel.__dict__) + ['am_obj', 'am_full']
    def __iter__(self):
        return iter(self._am_obj)
    def __len__(self):
        return len(self._am_obj)
    def __eq__(self, other):
        return self is other or self._am_obj == other
    def __ne__(self, other):
        return not (self == other)
    def __repr__(self):
        return '(container %s)%s' % (self.am_name, repr(self._am_obj))

class PrefetchAccessFilterValue(object):
    def __init__(self, model=None, field=None, value=None, can=None):
        self.swagger_types = {
            'model': 'str',
            'field': 'str',
            'value': 'str',
            'can': 'dict(str, bool)'
        }
        self.attribute_map = {
            'model': 'model',
            'field': 'field',
            'value': 'value',
            'can': 'can'
        }
        self._model = model
        self._field = field
        self._value = value
        self._can = can
    @property
    def model(self):
        return self._model
    @model.setter
    def model(self, model):
        self._model = model
    @property
    def field(self):
        return self._field
    @field.setter
    def field(self, field):
        self._field = field
    @property
    def value(self):
        return self._value
    @value.setter
    def value(self, value):
        self._value = value
    @property
    def can(self):
        return self._can
    @can.setter
    def can(self, can):
        self._can = can
    def to_dict(self):
        result = {}
        for attr, _ in iteritems(self.swagger_types):
            value = getattr(self, attr)
            if isinstance(value, list):
                result[attr] = list(map(
                    lambda x: x.to_dict() if hasattr(x, "to_dict") else x,
                    value
                ))
            elif hasattr(value, "to_dict"):
                result[attr] = value.to_dict()
            elif isinstance(value, dict):
                result[attr] = dict(map(
                    lambda item: (item[0], item[1].to_dict())
                    if hasattr(item[1], "to_dict") else item,
                    value.items()
                ))
            else:
                result[attr] = value
        return result
    def to_str(self):
        return pformat(self.to_dict())
    def __repr__(self):
        return self.to_str()
    def __eq__(self, other):
        if not isinstance(other, PrefetchAccessFilterValue):
            return False
        return self.__dict__ == other.__dict__
    def __ne__(self, other):
        return not self == other

class GTFT(MemoryOnePlayer):
    name = 'GTFT'
