                        Path(path).rglob(pattern)
                    ),
                    desc=msg
                )
            )
        with ProcessPoolExecutor(num_jobs) as ex:
            return RecordingSet.from_recordings(
                tqdm(
                    ex.map(
                        Recording.from_file,
                        Path(path).rglob(pattern)
                    ),
                    desc=msg
                )
            )
    @staticmethod
    def from_dicts(data: Iterable[dict]) -> 'RecordingSet':
        return RecordingSet.from_recordings(Recording.from_dict(raw_rec) for raw_rec in data)
    def to_dicts(self) -> Iterable[dict]:
        return (r.to_dict() for r in self)
    def filter(self, predicate: Callable[[Recording], bool]) -> 'RecordingSet':
        return RecordingSet.from_recordings(rec for rec in self if predicate(rec))
    def split(self, num_splits: int, shuffle: bool = False) -> List['RecordingSet']:
        return [
            RecordingSet.from_recordings(subset) for subset in
            split_sequence(self, num_splits=num_splits, shuffle=shuffle)
        ]
    def subset(self, first: Optional[int] = None, last: Optional[int] = None) -> 'RecordingSet':
        assert exactly_one_not_null(first, last), "subset() can handle only one non-None arg."
        if first is not None:
            assert first > 0
            if first > len(self):
                logging.warning(f'RecordingSet has only {len(self)} items but first {first} required; '
                                f'not doing anything.')
                return self
            return RecordingSet.from_recordings(islice(self, first))
        if last is not None:
            assert last > 0
            if last > len(self):
                logging.warning(f'RecordingSet has only {len(self)} items but last {last} required; '
                                f'not doing anything.')
                return self
            return RecordingSet.from_recordings(islice(self, len(self) - last, len(self)))
    def load_audio(
            self,
            recording_id: str,
            channels: Optional[Channels] = None,
            offset_seconds: float = 0.0,
            duration_seconds: Optional[float] = None,
    ) -> np.ndarray:
        return self.recordings[recording_id].load_audio(
            channels=channels,
            offset=offset_seconds,
            duration=duration_seconds
        )
    def with_path_prefix(self, path: Pathlike) -> 'RecordingSet':
        return RecordingSet.from_recordings(r.with_path_prefix(path) for r in self)
    def num_channels(self, recording_id: str) -> int:
        return self.recordings[recording_id].num_channels
    def sampling_rate(self, recording_id: str) -> int:
        return self.recordings[recording_id].sampling_rate
    def num_samples(self, recording_id: str) -> int:
        return self.recordings[recording_id].num_samples
    def duration(self, recording_id: str) -> Seconds:
        return self.recordings[recording_id].duration
    def perturb_speed(self, factor: float, affix_id: bool = True) -> 'RecordingSet':
        return RecordingSet.from_recordings(r.perturb_speed(factor=factor, affix_id=affix_id) for r in self)
    def resample(self, sampling_rate: int) -> 'RecordingSet':
        return RecordingSet.from_recordings(r.resample(sampling_rate) for r in self)
    def __repr__(self) -> str:
        return f'RecordingSet(len={len(self)})'
    def __getitem__(self, recording_id_or_index: Union[int, str]) -> Recording:
        if isinstance(recording_id_or_index, str):
            return self.recordings[recording_id_or_index]
        return next(val for idx, val in enumerate(self.recordings.values()) if idx == recording_id_or_index)
    def __iter__(self) -> Iterable[Recording]:
        return iter(self.recordings.values())
    def __len__(self) -> int:
        return len(self.recordings)
    def __add__(self, other: 'RecordingSet') -> 'RecordingSet':
        return RecordingSet(recordings={**self.recordings, **other.recordings})

class ValueSet(BackendObject):
    def __init__(self, name=None, region=None, bits=None, val=None):
        self._name = name
        if self._name is None:
            self._name = 'VS_%d' % vs_id_ctr.next()
        self._regions = {}
        self._reversed = False
        if bits is None:
            if val is None:
                raise ClaripyVSAError("Either 'size' or 'val' must be specified.")
            else:
                self._bits = val.bits()
        else:
            self._bits = bits
        if region is not None and val is not None:
            if isinstance(val, (StridedInterval, IfProxy)):
                self.set_si(region, val)
            elif type(val) in (int, long):
                self.set_si(region, StridedInterval(bits=bits, stride=0, lower_bound=val, upper_bound=val))
            else:
                raise ClaripyVSAError("Unsuported type '%s' for argument 'val'" % type(val))
        else:
            if region is not None or val is not None:
                raise ClaripyVSAError("You must specify 'region' and 'val' at the same time.")
    @property
    def name(self):
        return self._name
    @property
    def regions(self):
        return self._regions
    @property
    def reversed(self):
        return self._reversed
    @property
    def unique(self):
        return len(self.regions) == 1 and self.regions.values()[0].unique
    @property
    def bits(self):
        return self.size()
    @normalize_types
    def set_si(self, region, si):
        if not isinstance(si, StridedInterval):
            raise ClaripyVSAOperationError('Unsupported type %s for si' % type(si))
        self._regions[region] = si
    def get_si(self, region):
        if region in self._regions:
            return self._regions[region]
        return None
    def items(self):
        return self._regions.items()
    def size(self):
        return len(self)
    @normalize_types
    def merge_si(self, region, si):
        if region not in self._regions:
            self.set_si(region, si)
        else:
            self._regions[region] = self._regions[region].union(si)
    @normalize_types
    def remove_si(self, region, si):
        raise NotImplementedError()
    def __repr__(self):
        s = ""
        for region, si in self._regions.items():
            s = "%s: %s" % (region, si)
        return "(" + s + ")"
    def __len__(self):
        return self._bits
    @normalize_types_one_arg
    def __add__(self, other):
        if type(other) is ValueSet:
            raise NotImplementedError()
        else:
            new_vs = ValueSet(bits=self.bits)
            for region, si in self._regions.items():
                new_vs._regions[region] = si + other
            return new_vs
    @normalize_types_one_arg
    def __radd__(self, other):
        return self.__add__(other)
    @normalize_types_one_arg
    def __sub__(self, other):
        deltas = [ ]
        if type(other) is ValueSet:
            if self.regions.keys() == other.regions.keys():
                for region, si in self._regions.iteritems():
                    deltas.append(si - other._regions[region])
            else:
                __import__('ipdb').set_trace()
                raise NotImplementedError()
            delta = StridedInterval.empty(self.bits)
            for d in deltas:
                delta = delta.union(d)
            return delta
        else:
            new_vs = self.copy()
            for region, si in new_vs._regions.items():
                new_vs._regions[region] = si - other
            return new_vs
    @normalize_types_one_arg
    def __and__(self, other):
        if type(other) is ValueSet:
            if self.identical(other):
                return self.copy()
            raise NotImplementedError("__and__(vs1, vs2)?")
        if BoolResult.is_true(other == 0):
            return StridedInterval(bits=self.bits, stride=0, lower_bound=0, upper_bound=0)
        new_vs = ValueSet(bits=self.bits)
        if BoolResult.is_true(other < 0x100):
            ret = None
            for region, si in self._regions.items():
                r = si.__and__(other)
                ret = r if ret is None else ret.union(r)
            return ret
        else:
            for region, si in self._regions.items():
                r = si.__and__(other)
                new_vs._regions[region] = r
            return new_vs
    def __eq__(self, other):
        if isinstance(other, ValueSet):
            same = False
            different = False
            for region, si in other.regions.items():
                if region in self.regions:
                    comp_ret = self.regions[region] == si
                    if BoolResult.has_true(comp_ret):
                        same = True
                    if BoolResult.has_false(comp_ret):
                        different = True
                else:
                    different = True
            if same and not different:
                return TrueResult()
            if same and different:
                return MaybeResult()
            return FalseResult()
        elif isinstance(other, StridedInterval):
            if 'global' in self.regions:
                return self.regions['global'] == other
            else:
                return FalseResult()
        else:
            return FalseResult()
    def __ne__(self, other):
        return ~ (self == other)
    def eval(self, n):
        results = []
        for _, si in self._regions.items():
            if len(results) < n:
                results.extend(si.eval(n))
        return results
    def copy(self):
        vs = ValueSet(bits=self.bits)
        vs._regions = self._regions.copy()
        vs._reversed = self._reversed
        return vs
    def reverse(self):
        vs = self.copy()
        vs._reversed = not vs._reversed
        return vs
    @property
    def is_empty(self):
        return len(self._regions) == 0
    def extract(self, high_bit, low_bit):
        if high_bit - low_bit + 1 == self.bits:
            return self.copy()
        if ('global' in self._regions and len(self._regions.keys()) > 1) or \
            len(self._regions.keys()) > 0:
            si_ret = StridedInterval.top(high_bit - low_bit + 1)
        else:
            if 'global' in self._regions:
                si = self._regions['global']
                si_ret = si.extract(high_bit, low_bit)
            else:
                si_ret = StridedInterval.empty(high_bit - low_bit + 1)
        return si_ret
    def concat(self, b):
        new_vs = ValueSet(bits=self.bits + b.bits)
        if isinstance(b, StridedInterval):
            for region, si in self._regions.items():
                new_vs.set_si(region, si.concat(b))
        elif isinstance(b, ValueSet):
            for region, si in self._regions.items():
                new_vs.set_si(region, si.concat(b.get_si(region)))
        else:
            raise ClaripyVSAOperationError('ValueSet.concat() got an unsupported operand %s (type %s)' % (b, type(b)))
        return new_vs
    @normalize_types_one_arg
    def union(self, b):
        merged_vs = self.copy()
        if type(b) is ValueSet:
            for region, si in b.regions.items():
                if region not in merged_vs._regions:
                    merged_vs._regions[region] = si
                else:
                    merged_vs._regions[region] = merged_vs._regions[region].union(si)
        else:
            for region, si in self._regions.items():
                merged_vs._regions[region] = merged_vs._regions[region].union(b)
        return merged_vs
    @normalize_types_one_arg
    def widen(self, b):
        merged_vs = self.copy()
        if isinstance(b, ValueSet):
            for region, si in b.regions.items():
                if region not in merged_vs.regions:
                    merged_vs.regions[region] = si
                else:
                    merged_vs.regions[region] = merged_vs.regions[region].widen(si)
        else:
            for region, si in self._regions.iteritems():
                merged_vs._regions[region] = merged_vs._regions[region].widen(b)
        return merged_vs
    def identical(self, o):
        if self._reversed != o._reversed:
            return False
        for region, si in self.regions.items():
            if region in o.regions:
                o_si = o.regions[region]
                if not si.identical(o_si):
                    return False
            else:
                return False
        return True
    def __hash__(self):
        return hash(tuple([ (r, hash(si)) for r, si in self._regions.iteritems() ]))

class Proj(_Proj):
    def __init__(
        self, projparams: Any = None, preserve_units: bool = True, **kwargs
    ) -> None:
        self.crs = CRS.from_user_input(projparams, **kwargs)
        if not preserve_units and "foot" in self.crs.axis_info[0].unit_name:
            with warnings.catch_warnings():
                warnings.filterwarnings(
                    "ignore",
                    "You will likely lose important projection information",
                    UserWarning,
                )
                projstring = self.crs.to_proj4(4)
            projstring = re.sub(r"\s\+units=[\w-]+", "", projstring)
            projstring += " +units=m"
            self.crs = CRS(projstring)
        with warnings.catch_warnings():
            warnings.filterwarnings(
                "ignore",
                "You will likely lose important projection information",
                UserWarning,
            )
            projstring = self.crs.to_proj4() or self.crs.srs
        projstring = re.sub(r"\s\+?type=crs", "", projstring)
        super().__init__(cstrencode(projstring.strip()))
    def __call__(self, *args, **kw) -> Tuple[Any, Any]:
        inverse = kw.get("inverse", False)
        errcheck = kw.get("errcheck", False)
        lon, lat = args
        inx, xisfloat, xislist, xistuple = _copytobuffer(lon)
        iny, yisfloat, yislist, yistuple = _copytobuffer(lat)
        if inverse:
            self._inv(inx, iny, errcheck=errcheck)
        else:
            self._fwd(inx, iny, errcheck=errcheck)
        outx = _convertback(xisfloat, xislist, xistuple, inx)
        outy = _convertback(yisfloat, yislist, xistuple, iny)
        return outx, outy
    def get_factors(
        self,
        longitude: Any,
        latitude: Any,
        radians: bool = False,
        errcheck: bool = False,
    ) -> Factors:
        inx, xisfloat, xislist, xistuple = _copytobuffer(longitude)
        iny, yisfloat, yislist, yistuple = _copytobuffer(latitude)
        factors = self._get_factors(inx, iny, radians=radians, errcheck=errcheck)
        return Factors(
            meridional_scale=_convertback(
                xisfloat, xislist, xistuple, factors.meridional_scale
            ),
            parallel_scale=_convertback(
                xisfloat, xislist, xistuple, factors.parallel_scale
            ),
            areal_scale=_convertback(xisfloat, xislist, xistuple, factors.areal_scale),
            angular_distortion=_convertback(
                xisfloat, xislist, xistuple, factors.angular_distortion
            ),
            meridian_parallel_angle=_convertback(
                xisfloat, xislist, xistuple, factors.meridian_parallel_angle
            ),
            meridian_convergence=_convertback(
                xisfloat, xislist, xistuple, factors.meridian_convergence
            ),
            tissot_semimajor=_convertback(
                xisfloat, xislist, xistuple, factors.tissot_semimajor
            ),
            tissot_semiminor=_convertback(
                xisfloat, xislist, xistuple, factors.tissot_semiminor
            ),
            dx_dlam=_convertback(xisfloat, xislist, xistuple, factors.dx_dlam),
            dx_dphi=_convertback(xisfloat, xislist, xistuple, factors.dx_dphi),
            dy_dlam=_convertback(xisfloat, xislist, xistuple, factors.dy_dlam),
            dy_dphi=_convertback(xisfloat, xislist, xistuple, factors.dy_dphi),
        )
    def definition_string(self) -> str:
        return pystrdecode(self.definition)
    def to_latlong_def(self) -> Optional[str]:
        return self.crs.geodetic_crs.to_proj4(4) if self.crs.geodetic_crs else None
    def to_latlong(self) -> "Proj":
        return Proj(self.crs.geodetic_crs)
    def __reduce__(self) -> Tuple[Type["Proj"], Tuple[str]]:
        return self.__class__, (self.crs.srs,)
    def __repr__(self) -> str:
        return "Proj('{srs}', preserve_units=True)".format(srs=self.srs)
    def __eq__(self, other: Any) -> bool:
        if not isinstance(other, Proj):
            return False
        return self._is_equivalent(other)

class Node:
    def __init__(self, pos: tuple):
        self.x = pos[0]
