class Board:
	def __init__(self, _s):
		s=_s
		if 'a' in s.lower():
			s = s.replace('\n', '').replace(' ', '').lower()
			if len(s) in [1, 4, 9, 16, 25] and set(s) == set("abcdefghijklmnopqrstuvwxy"[:len(s)]):
				for i in range(25):
					s = s.replace(chr(ord('a')+i), str(1+i)+' ')
			else:
				raise ValueError(s, Counter(s))
		board = [int(i) for i in s.split()]
		if set(board) != set(range(1,len(board)+1)):
			raise ValueError(_s, Counter(board))
		i=0
		while i*i < len(board):
			i += 1
		if i*i != len(board):
			raise ValueError(_s)
		self.board = [board[i*j:i*(j+1)] for j in range(i)]
		self.width = self.height = i
		self.x, self.y = (0, 0)
		self.typed = self.keys = ''
	def __str__(self):
		return "Board(" + str(self.board) + ")"
	def __repr__(self):
		return "Board(\n\t" + '\n\t'.join(
			'['+', '.join(str(i) for i in row)+']' for row in self.board
		) + "\n)"
	def move(self, x=None, y=None):
		if x is not None:
			w = self.width
			left_dist = (self.x%w - x%w) % w
			right_dist = (x%w - self.x%w) % w
			if left_dist < right_dist:
				for i in range(left_dist):
					concurrent and interact.key('j')
					self.keys += 'j'
			else:
				for i in range(right_dist):
					concurrent and interact.key('l')
					self.keys += 'l'
			self.x = x % self.width
		if y is not None:
			h = self.height
			up_dist = (self.y%h - y%h) % h
			down_dist = (y%h - self.y%h) % h
			if up_dist < down_dist:
				for i in range(up_dist):
					concurrent and interact.key('i')
					self.keys += 'i'
			else:
				for i in range(down_dist):
					concurrent and interact.key('k')
					self.keys += 'k'
			self.y = y % self.width
	def swipe_up(self, col, dist):
		self.move(col, None)
		col = self.x 
		dist %= self.height
		column = [self.board[i][col] for i in range(self.height)]
		column = column[dist:] + column[:dist]
		for i in range(self.height):
			self.board[i][col] = column[i]
		if not dist:
			pass
		elif dist < (-dist) % self.height:
			for i in range(dist):
				concurrent and interact.key("w")
				self.y = self.y-1 % self.height
				self.keys += 'w'
		else:
			for i in range(self.height - dist):
				concurrent and interact.key("s")
				self.y = self.y+1 % self.height
				self.keys += 's'
	def swipe_left(self, row, dist):
		self.move(None, row)
		row = self.y 
		dist %= self.height
		row_ = self.board[row][dist:] + self.board[row][:dist]
		self.board[row] = row_
		if not dist:
			pass
		elif dist < (-dist) % self.width:
			for i in range(dist):
				concurrent and interact.key("a")
				self.x = self.x-1 % self.width
				self.keys += 'a'
		else:
			for i in range(self.width - dist):
				concurrent and interact.key("d")
				self.x = self.x+1 % self.width
				self.keys += 'd'
	def find(self, i_x, y=None):
		if y is None:
			i = i_x
		else:
			i = self.width*(y%self.height) + (i_x%self.width) + 1 
		for r in range(len(self.board)):
			if i in self.board[r]:
				return self.board[r].index(i), r
		raise ValueError((i_x, y) if y is not None else i_x)
	def reverse(self):
		opposite = {
			'a':lambda: self.swipe_left(None, -1),
			'd':lambda: self.swipe_left(None, 1),
			's':lambda: self.swipe_up(None, 1),
			'w':lambda: self.swipe_up(None, -1),
			'j':lambda: self.move(self.x+1, None),
			'l':lambda: self.move(self.x-1, None),
			'k':lambda: self.move(None, self.y-1),
			'i':lambda: self.move(None, self.y+1)
		}
		for key in self.keys[::-1]:
			opposite[key]()
		concurrent or interact.type(self.keys)
		self.typed += self.keys
		self.keys = ""
	def solved(self, width=None, height=None):
		for x in range(width if width is not None else self.width):
			for y in range(height if height is not None else self.height):
				if (x,y) != self.find(x, y):
					return False
		return True
	def solve_box(self, width=None, height=None):
		if width is None and height is None:
			width, height = self.width-1, self.height-1
		if self.width <= width or self.height <= height:
			raise ValueError
		if self.solved(width, height):
			return
		if height > 1: 
			self.solve_box(width, height-1)
			for i in range(width): 
				nx, ny = i, height-1
				x, y = self.find(nx, ny)
				if y == ny:
					self.swipe_left(y, x-width) 
					self.swipe_up(width, -1) 
					self.swipe_left(y, width-x) 
					self.swipe_up(width, 1) 
					self.swipe_left(ny, 1) 
				elif y < ny:
					self.swipe_up(x, y-ny-1) 
					self.swipe_left(ny+1, x-width) 
					self.swipe_up(width, 1) 
					self.swipe_left(ny, 1) 
				elif y > ny:
					self.swipe_left(y, x-width) 
					self.swipe_up(width, y-ny) 
					self.swipe_left(ny, 1) 
		elif width > height >= 1: 
			self.solve_box(width-1, height)
			for i in range(height): 
				nx, ny = width-1, i
				x, y = self.find(nx, ny)
				if x == nx:
					self.swipe_up(x, y-height)
					self.swipe_left(height, -1)
					self.swipe_up(x, height-y)
					self.swipe_left(height, 1)
					self.swipe_up(nx, 1)
				elif x < nx:
					self.swipe_left(y, x-nx-1)
					self.swipe_up(nx+1, y-height)
					self.swipe_left(height, 1)
					self.swipe_up(nx, 1)
				elif x > nx:
					self.swipe_up(x, y-height)
					self.swipe_left(height, x-nx)
					self.swipe_up(nx, 1)
		elif width == height == 1:
			x,y = self.find(1)
			self.swipe_up(x, y)
			self.swipe_left(0, x)
		concurrent and interact.key("space") 
		self.keys += ' '
	def solve_lastcol(self): 
		if not self.solved(self.width-1, self.height-1):
			raise ValueError(self)
		for i in range(self.height-2): 
			nx, ny = self.width-1, i
			x, y = self.find(nx, ny)
			if x == self.width-1: 
				self.swipe_up(self.width-1, y+1)
				self.swipe_left(self.height-1, 1)
				self.swipe_up(self.width-1, -y-1)
				self.swipe_left(self.height-1, -1)
				self.swipe_up(self.width-1, 1)
			elif y == self.height-1: 
				self.swipe_left(self.height-1, x+1)
				self.swipe_up(self.width-1, 1)
			else:
				raise ValueError(self)
		self.swipe_up(self.width-1, 1)
	def solve_keyhole(self):
		if not self.solved(self.width-1, self.height-1): 
			raise ValueError(self)
		if not self.solved(self.width, self.height-2): 
			raise ValueError(self)
		key = None 
		keyloc = (None, None)
		def update_keyloc():
			nonlocal keyloc
			keyloc = self.find(key)
		lastcol_up = True 
		def swapkey():
			nonlocal key, lastcol_up
			if lastcol_up:
				self.swipe_up(-1, -1)
				lastcol_up = False
				key = self.board[0][-1]
				update_keyloc()
			else:
				self.swipe_up(-1, 1)
				lastcol_up = True
				key = self.board[-2][-1]
				update_keyloc()
		x, y = self.find(0, -1) 
		if y == self.height-1: 
			self.swipe_left(-1, x) 
			key = self.board[-2][-1]
			update_keyloc()
		else: 
			self.swipe_up(-1, -1)
			self.swipe_left(-1, x) 
			lastcol_up = False
			key = self.board[0][-1]
			update_keyloc()
		for i in range(1, self.width):
			x, y = self.find(i, -1)
			if (x,y) == keyloc:
				self.swipe_left(-1, i+1)
				swapkey()
				self.swipe_left(-1, -i-1)
			else:
				self.swipe_left(-1, x+1)
				swapkey()
				self.swipe_left(-1, i-x)
				swapkey()
				self.swipe_left(-1, -i-1)
		if not lastcol_up:
			self.swipe_up(-1, 1)
	def solve_parity(self):
		if not self.solved(self.width, self.height-2) or not self.solved(self.width-1, self.height-1):
			raise ValueError(self)
		while not self.solved():
			print("Parity issue")
			self.swipe_up(-1, -1)
			if self.solved():continue
			self.swipe_left(-1, 1)
			if self.solved():continue
			self.swipe_up(-1, 1)
			if self.solved():continue
			self.swipe_left(-1, 1)
	def solve(self):
		self.solve_box()
		self.solve_lastcol()
		self.solve_keyhole()
		if not self.solved() and not self.width % 2:
			self.solve_parity()
		concurrent or interact.type(optimize_solution(self.keys, self.width, self.height))
		self.typed += self.keys
		self.keys = ""

class Canvas(object):
    def __init__(self, width, height, xmin=0, ymin=0, xmax=1, ymax=1, background=None, color_mode='names'):
        assert isinstance(width, int), '`width` has to be of type `int`'
        assert isinstance(height, int), '`height` has to be of type `int`'
        assert width > 0, '`width` has to be greater than 0'
        assert height > 0, '`height` has to be greater than 0'
        assert isinstance(xmin, (int, float))
        assert isinstance(xmax, (int, float))
        assert isinstance(ymin, (int, float))
        assert isinstance(ymax, (int, float))
        assert xmin < xmax, 'xmin ({}) has to be smaller than xmax ({})'.format(xmin, xmax)
        assert ymin < ymax, 'ymin ({}) has to be smaller than ymax ({})'.format(ymin, ymax)
        self._width = width
        self._height = height
        self._xmin = xmin
        self._xmax = xmax
        self._ymin = ymin
        self._ymax = ymax
        self._x_delta = abs((xmax - xmin) / width)
        self._y_delta = abs((ymax - ymin) / height)
        self._x_delta_pt = self._x_delta / 2
        self._y_delta_pt = self._y_delta / 4
        self._canvas = [[Dots(bg=background, color_mode=color_mode) for j_ in range(width)] for i_ in range(height)]
    def __str__(self):
        return 'Canvas(width={}, height={}, xmin={}, ymin={}, xmax={}, ymax={})'.format(
            self.width, self.height, self.xmin, self.ymin, self.xmax, self.ymax,
        )
    def __repr__(self):
        return self.__str__()
    @property
    def width(self):
        return self._width
    @property
    def height(self):
        return self._height
    @property
    def xmin(self):
        return self._xmin
    @property
    def ymin(self):
        return self._ymin
    @property
    def xmax(self):
        return self._xmax
    @property
    def ymax(self):
        return self._ymax
    def _transform_x(self, x):
        return int(roundeven((x - self.xmin) / self._x_delta_pt))
    def _transform_y(self, y):
        return int(roundeven((y - self.ymin) / self._y_delta_pt))
    def _set(self, x_idx, y_idx, set_=True, color=None):
        x_c, x_p = x_idx // 2, x_idx % 2
        y_c, y_p = y_idx // 4, y_idx % 4
        if 0 <= x_c < self.width and 0 <= y_c < self.height:
            self._canvas[y_c][x_c].update(x_p, y_p, set_)
            if color:
                self._canvas[y_c][x_c].fg = color
    def dots_between(self, x0, y0, x1, y1):
        x0_idx = self._transform_x(x0)
        y0_idx = self._transform_y(y0)
        x1_idx = self._transform_x(x1)
        y1_idx = self._transform_y(y1)
        return x1_idx - x0_idx, y1_idx - y0_idx
    def point(self, x, y, set_=True, color=None):
        x_idx = self._transform_x(x)
        y_idx = self._transform_y(y)
        self._set(x_idx, y_idx, set_, color)
    def fill_char(self, x, y, set_=True):
        x_idx = self._transform_x(x)
        y_idx = self._transform_y(y)
        x_c = x_idx // 2
        y_c = y_idx // 4
        if set_:
            self._canvas[y_c][x_c].fill()
        else:
            self._canvas[y_c][x_c].clear()
    def line(self, x0, y0, x1, y1, set_=True, color=None):
        x0_idx = self._transform_x(x0)
        y0_idx = self._transform_y(y0)
        self._set(x0_idx, y0_idx, set_, color)
        x1_idx = self._transform_x(x1)
        y1_idx = self._transform_y(y1)
        self._set(x1_idx, y1_idx, set_, color)
        x_diff = x1_idx - x0_idx
        y_diff = y1_idx - y0_idx
        steps = max(abs(x_diff), abs(y_diff))
        for i in range(1, steps):
            xb = x0_idx + int(roundeven(x_diff / steps * i))
            yb = y0_idx + int(roundeven(y_diff / steps * i))
            self._set(xb, yb, set_, color)
    def rect(self, xmin, ymin, xmax, ymax, set_=True, color=None):
        assert xmin <= xmax
        assert ymin <= ymax
        self.line(xmin, ymin, xmin, ymax, set_, color)
        self.line(xmin, ymax, xmax, ymax, set_, color)
        self.line(xmax, ymax, xmax, ymin, set_, color)
        self.line(xmax, ymin, xmin, ymin, set_, color)
    def plot(self, linesep=linesep):
        return linesep.join(''.join(map(six.text_type, row))
                            for row in reversed(self._canvas))

