class Queue(object):
    def __init__(self, data=None):
        self.front: Node = None
        self.back: Node = None
        self._length: int = 0
        if data is not None:
            try:
                vals = iter(data)
            except TypeError:
                vals = [data]
            for i in vals:
                newNode = Node(i)
                if self.front is None:  
                    self.front, self.back = newNode, newNode
                elif self.back is self.front:  
                    self.front._next, self.back = newNode, newNode
                else:
                    self.back._next, self.back = newNode, newNode
                self._length += 1
    def __len__(self):
        return self._length
    def __str__(self):
        return f'Front: {self.front} | Back: {self.back} | Length: {self._length}'
    def __repr__(self):
        return f'<Front: {self.front} | Back: {self.back} | Length: {self._length}>'
    def enqueue(self, val):
        newNode = Node(val)
        if self.front is None:  
            self.front, self.back = newNode, newNode
        elif self.back is self.front:  
            self.front._next, self.back = newNode, newNode
        else:
            self.back._next, self.back = newNode, newNode
        self._length += 1
    def dequeue(self):
        temp = self.front
        self.front = self.front._next
        temp._next = None
        self._length -= 1
        return temp
    def peek(self):
        return self.front

