class Channel(db.Model):
    __tablename__ = "channel"
    RENEW_INTERVAL = int(timedelta(days=4).total_seconds())
    id = db.Column(db.String(32), primary_key=True)
    name = db.Column(db.String(128))
    active = db.Column(db.Boolean, default=False)
    infos = db.Column(db.JSON, nullable=False, default={})
    hub_infos = db.Column(db.JSON, nullable=False, default={})
    subscribe_timestamp = db.Column(db.DateTime, default=datetime.utcnow)
    unsubscribe_timestamp = db.Column(db.DateTime)
    actions = db.relationship("Action", back_populates="channel")
    videos = db.relationship(
        "Video", back_populates="channel", lazy="dynamic", cascade="all, delete-orphan"
    )
    callbacks = db.relationship(
        "Callback",
        back_populates="channel",
        lazy="dynamic",
        cascade="all, delete-orphan",
    )
    subscriptions = db.relationship(
        "Subscription",
        back_populates="channel",
        lazy="dynamic",
        cascade="all, delete-orphan",
    )
    def __init__(self, channel_id):
        from ..tasks import channels_fetch_videos, channels_refresh, channels_renew
        self.id = channel_id
        db.session.add(self)
        db.session.commit()
        try:
            self.update()
            current_app.logger.info(f"Channel <{self.id}>: Create")
        except (APIError, InvalidAction) as error:
            db.session.delete(self)
            db.session.commit()
            current_app.logger.exception(
                f"Channel <{channel_id}>: Create failed with API Error"
            )
            raise error
        channels_refresh.apply_async(
            args=[[channel_id]],
            countdown=60,
        )
        channels_fetch_videos.apply_async(args=[[channel_id]])
        channels_renew.apply_async(args=[[channel_id], 345600], countdown=345600)
        self.activate()
    def __repr__(self):
        return f"<Channel <{self.id}> ({self.name})>"
    @property
    def expiration(self):
        try:
            return try_parse_datetime(self.hub_infos["expiration"])
        except (TypeError, KeyError):
            return None
    @expiration.setter
    def expiration(self, expiration):
        raise ValueError("expiration can not be set")
    @expiration.deleter
    def expiration(self):
        raise ValueError("expiration can not be delete")
    @property
    def renewal(self):
        expiration = self.expiration
        tomorrow = datetime.now() + timedelta(days=1)
        if expiration is None:
            renewal = datetime.now() + timedelta(seconds=self.RENEW_INTERVAL)
        elif expiration > tomorrow:
            renewal = expiration - timedelta(days=1)
        else:
            renewal = datetime.now()
        return renewal
    @renewal.setter
    def renewal(self, renewal):
        raise ValueError("renewal can not be set")
    @renewal.deleter
    def renewal(self):
        raise ValueError("renewal can not be delete")
    def activate(self):
        if self.active:
            raise AttributeError("Channel is already active")
        results = self.subscribe()
        if not results:
            raise RuntimeError("Channel activate failed")
        self.active = True
        self.subscribe_timestamp = datetime.utcnow()
        db.session.commit()
        current_app.logger.info(f"Channel <{self.id}>: Activate")
        return results
    def deactivate(self):
        if not self.active:
            raise AttributeError("Channel is already deactivate")
        callback_url = url_for(
            "main.channel_callback", channel_id=self.id, _external=True
        )
        topic_url = current_app.config["HUB_YOUTUBE_TOPIC"] + urlencode(
            {"channel_id": self.id}
        )
        response = unsubscribe(
            current_app.config["HUB_GOOGLE_HUB"], callback_url, topic_url
        )
        if response.success:
            self.active = False
            self.unsubscribe_timestamp = datetime.utcnow()
            db.session.commit()
            current_app.logger.info(f"Channel <{self.id}>: Deactivate")
        else:
            current_app.logger.error(f"Channel <{self.id}>: Deactivate failed")
        return response
    def refresh(self):
        callback_url = url_for(
            "main.channel_callback", channel_id=self.id, _external=True
        )
        topic_url = current_app.config["HUB_YOUTUBE_TOPIC"] + urlencode(
            {"channel_id": self.id}
        )
        results = details(current_app.config["HUB_GOOGLE_HUB"], callback_url, topic_url)
        results.pop("requests_url")
        results.pop("response_object")
        response = results.copy()
        for key, val in results.items():
            if not val:
                continue
            if isinstance(val, datetime):
                results[key] = str(val)
            elif isinstance(val[0], datetime):
                results[key] = (str(val[0]), val[1])
        if results["state"] != self.hub_infos.get("state"):
            from ..helper import notify_admin
            notify_admin(
                "channel-refresh",
                "Pushover",
                title=f"Channel {self.name} <{self.id}> missed subscription renewal",
                message="\n".join(
                    [
                        json.dumps(results, indent=4),
                        json.dumps(self.hub_infos, indent=4),
                    ]
                ),
            )
        self.hub_infos = results
        db.session.commit()
        current_app.logger.info(f"Channel <{self.id}>: Hub info updated")
        return response
    def update(self):
        try:
            api_result = (
                build_youtube_api()
                .channels()
                .list(part="snippet", id=self.id)
                .execute()
            )
            if "items" not in api_result:
                if self.name is None:
                    raise InvalidAction(
                        f"Channel <{self.id}>: YouTube info update failed, "
                        "doesn't exists"
                    )
                raise APIError(
                    service="YouTube",
                    message=f"Unable to update channel <{self.id}> info",
                )
            self.infos = api_result["items"][0]
            self.name = self.infos["snippet"]["title"]
            db.session.commit()
            current_app.logger.info(f"Channel <{self.id}>: YouTube info updated")
            return self.infos
        except (YouTubeAPIError, KeyError) as error:
            current_app.logger.exception(
                f"Channel <{self.id}>: YouTube info update failed"
            )
            raise APIError(
                service="YouTube",
                message=str(error.args),
                error_type=error.__class__.__name__,
            )
    def subscribe(self):
        callback_url = url_for(
            "main.channel_callback", channel_id=self.id, _external=True
        )
        topic_url = current_app.config["HUB_YOUTUBE_TOPIC"] + urlencode(
            {"channel_id": self.id}
        )
        response = subscribe(
            current_app.config["HUB_GOOGLE_HUB"], callback_url, topic_url
        )
        current_app.logger.debug(f"Callback URL: {callback_url}")
        current_app.logger.debug(f"Topic URL   : {topic_url}")
        current_app.logger.debug(f"Channel ID  : {self.id}")
        current_app.logger.debug(f"Response    : {response.status_code}")
        current_app.logger.info(f"Channel <{self.id}>: Hub Subscribe")
        return response.success
    def fetch_videos(self, fetch_all=False):
        from .video import Video
        search = build_youtube_api().search()
        request = search.list(
            part="snippet",
            channelId=self.id,
            maxResults=50,
            order="date",
            type="video",
            fields=Video.DETAILS_FIELDS,
        )
        results = {"new_item_appended": 0, "video_ids": []}
        while request is not None:
            api_results = request.execute()
            for video in api_results["items"]:
                video_id = video["id"]["videoId"]
                if not Video.query.get(video_id):
                    Video(video_id, self, details=video["snippet"])
                    results["new_item_appended"] += 1
                    results["video_ids"].append(video_id)
            if not fetch_all:
                request = search.list_next(request, api_results)
            else:
                break
        current_app.logger.info(f"Channel <{self.id}>: Video Fetched")
        return results

class PlatformDeployment(db.Model, DictSerializableMixin):
    __tablename__ = 'platform_deployments'
    __table_args__ = {u'schema': __schema__}
    __searchable__ = ['display_name']
    id = db.Column(db.Integer, primary_key=True)
    start_date = db.Column(db.Date)
    end_date = db.Column(db.Date)
    platform_id = db.Column(db.ForeignKey(u'' + __schema__ + '.platforms.id'))
    reference_designator = db.Column(db.Text, nullable=False)
    array_id = db.Column(db.ForeignKey(u'' + __schema__ + '.arrays.id'))
    deployment_id = db.Column(db.ForeignKey(u'' + __schema__ + '.deployments.id'))
    display_name = db.Column(db.Text)
    geo_location = db.Column(Geometry(geometry_type='GEOMETRY', srid=-1, dimension=2, spatial_index=True, management=True))
    array = db.relationship(u'Array')
    deployment = db.relationship(u'Deployment')
    platform = db.relationship(u'Platform')
    @hybrid_property
    def geojson(self):
        return json.loads(db.session.scalar(func.ST_AsGeoJSON(self.geo_location)))
    @hybrid_property
    def proper_display_name(self):
        return self._get_display_name(reference_designator=self.reference_designator)
    def to_json(self):
        geo_location = None
        if self.geo_location is not None:
            loc = db.session.scalar(func.ST_AsGeoJSON(self.geo_location))
            geo_location = json.loads(loc)
        json_platform_deployment = {
            'id' : self.id,
            'reference_designator' : self.reference_designator,
            'array_id' : self.array_id,
            'display_name' : self.proper_display_name,
            'start_date' : self.start_date,
            'end_date' : self.end_date,
            'geo_location' : geo_location
        }
        return json_platform_deployment
    @classmethod
    def _f_concat_rd(cls, array_type, array_name, site, platform, assembly, instrument_name):
        if assembly is not None and instrument_name is not None:
            return array_type + ' ' + array_name + ' ' + site + ' ' + platform + ' - ' + assembly + ' - ' + instrument_name
        elif assembly is not None and instrument_name is None:
            return array_type + ' ' + array_name + ' ' + site + ' ' + platform + ' - ' + assembly
        else:
            return array_type + ' ' + array_name + ' ' + site + ' ' + platform
    @classmethod
    def _get_display_name(cls, reference_designator):
        import re
        if not reference_designator:
            return None
        rd_len = len(reference_designator)
        p_n = Platformname.query.filter(Platformname.reference_designator == reference_designator[:14]).first()
        if not p_n:
            return reference_designator
        if rd_len == 8:
            return cls._f_concat_rd(p_n.array_type, p_n.array_name, p_n.site, p_n.platform, None, None)
        elif rd_len == 14:
            assy = reference_designator[9:14]
            if re.match('AV[0-9]{3}', assy):
                platform_text = 'AUV ' + assy[2:5]
            elif re.match('GL[0-9]{3}', assy):
                platform_text = 'Glider ' + assy[2:5]
            else:
                platform_text = p_n.assembly
            return cls._f_concat_rd(p_n.array_type, p_n.array_name, p_n.site, p_n.platform, platform_text, None)
        elif rd_len == 27:
            inst = reference_designator[18:23]
            assy = reference_designator[9:14]
            if re.match('AV[0-9]{3}', assy):
                platform_text = 'AUV ' + assy[2:5]
            elif re.match('GL[0-9]{3}', assy):
                platform_text = 'Glider ' + assy[2:5]
            else:
                platform_text = p_n.assembly
            i_n = Instrumentname.query.filter(Instrumentname.instrument_class == inst).first()
            if not i_n:
                return cls._f_concat_rd(p_n.array_type, p_n.array_name, p_n.site, p_n.platform, platform_text, inst)
            return cls._f_concat_rd(p_n.array_type, p_n.array_name, p_n.site, p_n.platform, platform_text, i_n.display_name)
        return None
    def __repr__(self):
        return '{0}(display_name={1})'.format(self.__class__.__name__, self.display_name)

