class Vector2d:
    typecode = 'd'
    __slots__ = ('__x', '__y')
    def __init__(self, x, y):
        self.__x = float(x)
        self.__y = float(y)
    @property  
    def x(self):
        return self.__x
    @property
    def y(self):
        return self.__y
    def __hash__(self):
        return hash(self.x) ^ hash(self.y)
    def __iter__(self):
        return (i for i in (self.x, self.y))
    def __repr__(self):
        class_name = type(self).__name__
        return '{}({!r}, {!r})'.format(class_name, *self)
    def __str__(self):
        return str(tuple(self))
    def __bytes__(self):
        return (bytes([ord(self.typecode)]) +
                bytes(array(self.typecode, self)))
    def __eq__(self, other):
        return tuple(self) == tuple(other)
    def __abs__(self):
        return math.hypot(self.x, self.y)
    def __bool__(self):
        return bool(abs(self))
    @classmethod
    def frombytes(cls, octets):
        typecode = chr(octets[0])
        memv = memoryview(octets[1:]).cast(typecode)
        return cls(*memv)

class MultiArrayLayout(metaclass=Metaclass_MultiArrayLayout):
    __slots__ = [
        '_dim',
        '_data_offset',
    ]
    _fields_and_field_types = {
        'dim': 'sequence<example_interfaces/MultiArrayDimension>',
        'data_offset': 'uint32',
    }
    SLOT_TYPES = (
        rosidl_parser.definition.UnboundedSequence(rosidl_parser.definition.NamespacedType(['example_interfaces', 'msg'], 'MultiArrayDimension')),  
        rosidl_parser.definition.BasicType('uint32'),  
    )
    def __init__(self, **kwargs):
        assert all('_' + key in self.__slots__ for key in kwargs.keys()), \
            'Invalid arguments passed to constructor: %s' % \
            ', '.join(sorted(k for k in kwargs.keys() if '_' + k not in self.__slots__))
        self.dim = kwargs.get('dim', [])
        self.data_offset = kwargs.get('data_offset', int())
    def __repr__(self):
        typename = self.__class__.__module__.split('.')
        typename.pop()
        typename.append(self.__class__.__name__)
        args = []
        for s, t in zip(self.__slots__, self.SLOT_TYPES):
            field = getattr(self, s)
            fieldstr = repr(field)
            if (
                isinstance(t, rosidl_parser.definition.AbstractSequence) and
                isinstance(t.value_type, rosidl_parser.definition.BasicType) and
                t.value_type.typename in ['float', 'double', 'int8', 'uint8', 'int16', 'uint16', 'int32', 'uint32', 'int64', 'uint64']
            ):
                if len(field) == 0:
                    fieldstr = '[]'
                else:
                    assert fieldstr.startswith('array(')
                    prefix = "array('X', "
                    suffix = ')'
                    fieldstr = fieldstr[len(prefix):-len(suffix)]
            args.append(s[1:] + '=' + fieldstr)
        return '%s(%s)' % ('.'.join(typename), ', '.join(args))
    def __eq__(self, other):
        if not isinstance(other, self.__class__):
            return False
        if self.dim != other.dim:
            return False
        if self.data_offset != other.data_offset:
            return False
        return True
    @classmethod
    def get_fields_and_field_types(cls):
        from copy import copy
        return copy(cls._fields_and_field_types)
    @property
    def dim(self):
        return self._dim
    @dim.setter
    def dim(self, value):
        if __debug__:
            from example_interfaces.msg import MultiArrayDimension
            from collections.abc import Sequence
            from collections.abc import Set
            from collections import UserList
            from collections import UserString
            assert \
                ((isinstance(value, Sequence) or
                  isinstance(value, Set) or
                  isinstance(value, UserList)) and
                 not isinstance(value, str) and
                 not isinstance(value, UserString) and
                 all(isinstance(v, MultiArrayDimension) for v in value) and
                 True), \
                "The 'dim' field must be a set or sequence and each value of type 'MultiArrayDimension'"
        self._dim = value
    @property
    def data_offset(self):
        return self._data_offset
    @data_offset.setter
    def data_offset(self, value):
        if __debug__:
            assert \
                isinstance(value, int), \
                "The 'data_offset' field must be of type 'int'"
            assert value >= 0 and value < 4294967296, \
                "The 'data_offset' field must be an unsigned integer in [0, 4294967295]"
        self._data_offset = value

class CPubKey(bytes):
    def __new__(cls, buf, _cec_key=None):
        self = super(CPubKey, cls).__new__(cls, buf)
        if _cec_key is None:
            _cec_key = CECKey()
        self._cec_key = _cec_key
        self.is_fullyvalid = _cec_key.set_pubkey(self) != 0
        return self
    @property
    def is_valid(self):
        return len(self) > 0
    @property
    def is_compressed(self):
        return len(self) == 33
    def verify(self, hash, sig):
        return self._cec_key.verify(hash, sig)
    def __str__(self):
        return repr(self)
    def __repr__(self):
        if sys.version > '3':
            return '%s(%s)' % (self.__class__.__name__, super(CPubKey, self).__repr__())
        else:
            return '%s(b%s)' % (self.__class__.__name__, super(CPubKey, self).__repr__())

