        'Query',
        secondary=querypacks,
        back_populates='packs',
    )
    tags = relationship(
        'Tag',
        secondary=pack_tags,
        back_populates='packs',
    )
    def __init__(self, name, platform=None, version=None,
                 description=None, shard=None, **kwargs):
