        self,
        filename: str,
        relname: str,
        line: int,
        col_start: int,
        col_end: int,
    ) -> None:
        self.filename = filename
        self.relname = relname
        self._basename = None  
        self.line = int(line)
        self.col_start = int(col_start)
        self.col_end = int(col_end)
