class Line:
    logger = logging.getLogger(__name__)
    def __init__(self, line_id: int, directed: bool, length: float = 0,
                 cost: float = 0, frequency: int = 0,
                 line_path: Path[Stop, Link]=None):
        self.line_id = line_id
        self.directed = directed
        self.length = length
        self.cost = cost
        self.frequency = frequency
        self.line_path = line_path
        if not line_path:
            self.line_path = ListPath(directed)
    def addLink(self, link: Link, compute_cost_and_length: bool = False,
                factor_cost_length: float = 0,
                factor_cost_link: float = 0) -> bool:
        if self.line_path.containsNode(link.getLeftNode()) and self.line_path.containsNode(link.getRightNode()):
            self.logger.warning("Line {} now contains a loop, closed by link\
                                {}. This may create problems in the LinTim\
                                algorithms!".format(self.getId(),
                                                    link.getId()))
        result = self.line_path.addLastEdge(link)
        if compute_cost_and_length and result:
            self.length += link.getLength()
            self.cost += (link.getLength()
                          * factor_cost_length
                          + factor_cost_link)
        return result
    def toLineCostCsvStrings(self) -> [str]:
        return [str(self.getId()),
                CsvWriter.shortenDecimalValueForOutput(self.getLength()),
                CsvWriter.shortenDecimalValueForOutput(self.getCost())
                ]
    def getId(self) -> int:
        return self.line_id
    def getLength(self) -> float:
        return self.length
    def getCost(self) -> float:
        return self.cost
    def getFrequency(self) -> int:
        return self.frequency
    def getLinePath(self) -> Path[Stop, Link]:
        return self.line_path
    def setFrequency(self, frequency: int) -> None:
        self.frequency = frequency
    def setLength(self, length: float) -> None:
        self.length = length
    def setCost(self, cost: float) -> None:
        self.cost = cost
    def __eq__(self, other):
        if not isinstance(other, Line):
            return False
        return (self.getId() == other.getId()
                and math.isclose(self.getLength(), other.getLength())
                and math.isclose(self.getCost(), other.getCost())
                and self.getLinePath() == other.getLinePath())
    def __ne__(self, other):
        return not self.__eq__(other)
    def __hash__(self) -> int:
        return self.line_id
    def __str__(self):
        return ("Line " + ", ".join(self.toLineCostCsvStrings()) + ", Path "
                + str(self.line_path))

class LinePool:
    def __init__(self):
        self.pool = {}  
    def addLine(self, line: Line) -> bool:
        if line.getId() in self.pool:
            return False
        self.pool[line.getId()] = line
        return True
    def removeLine(self, line_id: int) -> bool:
        if line_id not in self.pool:
            return False
        del self.pool[line_id]
        return True
    def getLines(self) -> [Line]:
        return list(self.pool.values())
    def getLine(self, line_id: int) -> Line:
        return self.pool[line_id]
    def getLineConcept(self) -> [Line]:
        return [line for line in self.pool.values() if line.getFrequency() > 0]
    def __eq__(self, other):
        if not isinstance(other, LinePool):
            return False
        return self.pool == other.pool
    def __ne__(self, other):
        return not self.__eq__(other)
    def __str__(self):
        return ("LineConcept:\n"
                + "\n".join(["{}:{}".format(line_id, line)
                             for line_id, line in self.pool.items()]))

class Trie:
    NO_NODE = -1
    SPACE_CODE = -1
    ATTRS = ['is_numpied', 'precompute_symbols', 'allow_spaces',
             'is_terminated', 'to_make_cashed']
    def __init__(self, alphabet, make_sorted=True, make_alphabet_codes=True,
                 is_numpied=False, to_make_cashed=False,
                 precompute_symbols=None, allow_spaces=False, dict_storage=False):
        self.alphabet = sorted(alphabet) if make_sorted else alphabet
        self.alphabet_codes = ({a: i for i, a in enumerate(self.alphabet)}
                               if make_alphabet_codes else self.alphabet)
        self.alphabet_codes[" "] = Trie.SPACE_CODE
        self.is_numpied = is_numpied
        self.to_make_cashed = to_make_cashed
        self.dict_storage = dict_storage
        self.precompute_symbols = precompute_symbols
        self.allow_spaces = allow_spaces
        self.initialize()
    def initialize(self):
        self.root = 0
        self.graph = [self._make_default_node()]
        self.data, self.final = [None], [False]
        self.nodes_number = 1
        self.descend = self._descend_simple
        self.is_terminated = False
    def _make_default_node(self):
        if self.dict_storage:
            return defaultdict(lambda: -1)
        elif self.is_numpied:
            return np.full(shape=(len(self.alphabet),),
                           fill_value=Trie.NO_NODE, dtype=int)
        else:
            return [Trie.NO_NODE] * len(self.alphabet)
    def save(self, outfile):
        with open(outfile, "w", encoding="utf8") as fout:
            attr_values = [getattr(self, attr) for attr in Trie.ATTRS]
            attr_values.append(any(x is not None for x in self.data))
            fout.write("{}\n{}\t{}\n".format(
                " ".join("T" if x else "F" for x in attr_values),
                self.nodes_number, self.root))
            fout.write(" ".join(str(a) for a in self.alphabet) + "\n")
            for index, label in enumerate(self.final):
                letters = self._get_letters(index, return_indexes=True)
                children = self._get_children(index)
                fout.write("{}\t{}\n".format(
                    "T" if label else "F", " ".join("{}:{}".format(*elem)
                                                    for elem in zip(letters, children))))
            if self.precompute_symbols is not None:
                for elem in self.data:
                    fout.write(":".join(",".join(
                        map(str, symbols)) for symbols in elem) + "\n")
        return
    def make_cashed(self):
        self._descendance_cash = [dict() for _ in self.graph]
        self.descend = self._descend_cashed
    def make_numpied(self):
        self.graph = np.array(self.graph)
        self.final = np.asarray(self.final, dtype=bool)
        self.is_numpied = True
    def add(self, s):
        if self.is_terminated:
            raise TypeError("Impossible to add string to fitted trie")
        if s == "":
            self._set_final(self.root)
            return
        curr = self.root
        for i, a in enumerate(s):
            code = self.alphabet_codes[a]
            next = self.graph[curr][code]
            if next == Trie.NO_NODE:
                curr = self._add_descendant(curr, s[i:])
                break
            else:
                curr = next
        self._set_final(curr)
        return self
    def fit(self, words):
        for s in words:
            self.add(s)
        self.terminate()
    def terminate(self):
        if self.is_numpied:
            self.make_numpied()
        self.terminated = True
        if self.precompute_symbols is not None:
            precompute_future_symbols(self, self.precompute_symbols,
                                      allow_spaces=self.allow_spaces)
        if self.to_make_cashed:
            self.make_cashed()
    def __contains__(self, s):
        if any(a not in self.alphabet for a in s):
            return False
        node = self.descend(self.root, s)
        return (node != Trie.NO_NODE) and self.is_final(node)
    def words(self):
        branch, word, indexes = [self.root], [], [0]
        letters_with_children = [self._get_children_and_letters(self.root)]
        while len(branch) > 0:
            if self.is_final(branch[-1]):
                yield "".join(word)
            while indexes[-1] == len(letters_with_children[-1]):
                indexes.pop()
                letters_with_children.pop()
                branch.pop()
                if len(indexes) == 0:
                    raise StopIteration()
                word.pop()
            next_letter, next_child = letters_with_children[-1][indexes[-1]]
            indexes[-1] += 1
            indexes.append(0)
            word.append(next_letter)
            branch.append(next_child)
            letters_with_children.append(self._get_children_and_letters(branch[-1]))
    def is_final(self, index):
        return self.final[index]
    def find_partitions(self, s, max_count=1):
        curr_agenda = [(self.root, [], 0)]
        for i, a in enumerate(s):
            next_agenda = []
            for curr, borders, cost in curr_agenda:
                if cost >= max_count:
                    continue
                child = self.graph[curr][self.alphabet_codes[a]]
                if child == Trie.NO_NODE:
                    continue
                next_agenda.append((child, borders, cost))
                if self.is_final(child):
                    next_agenda.append((self.root, borders + [i+1], cost+1))
            curr_agenda = next_agenda
        answer = []
        for curr, borders, cost in curr_agenda:
            if curr == self.root:
                borders = [0] + borders
                answer.append([s[left:borders[i+1]] for i, left in enumerate(borders[:-1])])
        return answer
    def __len__(self):
        return self.nodes_number
    def __repr__(self):
        answer = ""
        for i, (final, data) in enumerate(zip(self.final, self.data)):
            letters, children = self._get_letters(i), self._get_children(i)
            answer += "{0}".format(i)
            if final:
                answer += "F"
            for a, index in zip(letters, children):
                answer += " {0}:{1}".format(a, index)
            answer += "\n"
            if data is not None:
                answer += "data:{0} {1}\n".format(len(data), " ".join(str(elem) for elem in data))
        return answer
    def _add_descendant(self, parent, s, final=False):
        for a in s:
            code = self.alphabet_codes[a]
            parent = self._add_empty_child(parent, code, final)
        return parent
    def _add_empty_child(self, parent, code, final=False):
        self.graph[parent][code] = self.nodes_number
        self.graph.append(self._make_default_node())
        self.data.append(None)
        self.final.append(final)
        self.nodes_number += 1
        return (self.nodes_number - 1)
    def _descend_simple(self, curr, s):
        for a in s:
            curr = self.graph[curr][self.alphabet_codes[a]]
            if curr == Trie.NO_NODE:
                break
        return curr
    def _descend_cashed(self, curr, s):
        if s == "":
            return curr
        curr_cash = self._descendance_cash[curr]
        answer = curr_cash.get(s, None)
        if answer is not None:
            return answer
        res = curr
        for a in s:
            res = self.graph[res][self.alphabet_codes[a]]
            if res == Trie.NO_NODE:
                break
        curr_cash[s] = res
        return res
    def _set_final(self, curr):
        self.final[curr] = True
    def _get_letters(self, index, return_indexes=False):
        if self.dict_storage:
            answer = list(self.graph[index].keys())
        else:
            answer =  [i for i, elem in enumerate(self.graph[index])
                       if elem != Trie.NO_NODE]
        if not return_indexes:
            answer = [(self.alphabet[i] if i >= 0 else " ") for i in answer]
        return answer
    def _get_children_and_letters(self, index, return_indexes=False):
        if self.dict_storage:
            answer = list(self.graph[index].items())
        else:
            answer =  [elem for elem in enumerate(self.graph[index])
                       if elem[1] != Trie.NO_NODE]
        if not return_indexes:
            for i, (letter_index, child) in enumerate(answer):
                answer[i] = (self.alphabet[letter_index], child)
        return answer
    def _get_children(self, index):
        if self.dict_storage:
            return list(self.graph[index].values())
        else:
            return [elem for elem in self.graph[index] if elem != Trie.NO_NODE]

class GymSpaceWrapper:
    def __init__(self, space, null_value=0, name="obs", force_float32=True,
                 schemas=None):
        self._gym_space = space
        self._base_name = name
        self._null_value = null_value
        if schemas is None:
            schemas = {}
        self._schemas = schemas
        if isinstance(space, GymDict):
            nt = self._schemas.get(name)
            if nt is None:
                nt = NamedTupleSchema(name, [k for k in space.spaces.keys()])
                schemas[name] = nt  
            elif not (isinstance(nt, NamedTupleSchema) and
                    sorted(nt._fields) ==
                    sorted([k for k in space.spaces.keys()])):
                raise ValueError(f"Name clash in schemas: {name}.")
            spaces = [GymSpaceWrapper(
                space=v,
                null_value=null_value,
                name="_".join([name, k]),
                force_float32=force_float32,
                schemas=schemas)
                for k, v in space.spaces.items()]
            self.space = Composite(spaces, nt)
            self._dtype = None
        else:
            self.space = space
            self._dtype = np.float32 if (space.dtype == np.float64 and
                force_float32) else None
    def sample(self):
        sample = self.space.sample()
        if self.space is self._gym_space:  
            sample = np.asarray(sample, dtype=self._dtype)
        return sample
    def null_value(self):
        if self.space is self._gym_space:
            null = np.asarray(self.space.sample(), dtype=self._dtype)
            if self._null_value is not None:
                try:
                    null[:] = self._null_value
                except IndexError:  
                    null.fill(self._null_value)
            else:
                null.fill(0)
        else:  
            null = self.space.null_value()
        return null
    def convert(self, value):
        return dict_to_nt(value, name=self._base_name, schemas=self._schemas)
    def revert(self, value):
        return nt_to_dict(value)
    @property
    def dtype(self):
        return self._dtype or self.space.dtype
    @property
    def shape(self):
        return self.space.shape
    def contains(self, x):
        return self.space.contains(x)
    def __repr__(self):
        return self.space.__repr__()
    def __eq__(self, other):
        return self.space.__eq__(other)
    @property
    def low(self):
        return self.space.low
    @property
    def high(self):
        return self.space.high
    @property
    def n(self):
        return self.space.n

